  <text x="18" y="150" fill="#aaa" font-size="9" font-family="sans-serif">Battery</text>
  <!-- Top bus wire -->
  <line x1="40" y1="20" x2="340" y2="20" stroke="#7cfc00" stroke-width="2"/>
  <!-- Bottom bus wire -->
  <line x1="40" y1="140" x2="340" y2="140" stroke="#7cfc00" stroke-width="2"/>
