INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (1, 1, 'Which of the following is a natural number: -3, 0, 4, or 1/2?', 'text', 1, 'Natural numbers start at 1.', '{"why":"Natural numbers are positive counting numbers beginning with 1.","sol":"Step 1: Natural numbers are 1, 2, 3, 4, ...\nStep 2: -3 is negative.\nStep 3: 0 is not included in this classification.\nStep 4: 1/2 is a fraction.\nStep 5: 4 belongs to the natural numbers.","steps":["Step 1: Natural numbers are 1, 2, 3, 4, ...","Step 2: -3 is negative.","Step 3: 0 is not included in this classification.","Step 4: 1/2 is a fraction.","Step 5: 4 belongs to the natural numbers."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"Number Systems"}', 0),
  (2, 1, 'Is 0 a natural number, whole number, or integer?', 'text', 1, 'Remember which sets include zero.', '{"why":"Whole numbers include 0, and integers include negative numbers, zero, and positive numbers.","sol":"Step 1: 0 is not a natural number in this classification.\nStep 2: Whole numbers include 0.\nStep 3: Integers also include 0.","steps":["Step 1: 0 is not a natural number in this classification.","Step 2: Whole numbers include 0.","Step 3: Integers also include 0."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"Number Systems"}', 1),
  (3, 1, 'Which type of number is -8?', 'text', 1, 'Look at its sign.', '{"why":"-8 belongs to the set of integers because integers include negative whole-number values.","sol":"Step 1: -8 is less than zero.\nStep 2: Negative numbers are not natural or whole numbers.\nStep 3: Negative whole-number values belong to the integers.","steps":["Step 1: -8 is less than zero.","Step 2: Negative numbers are not natural or whole numbers.","Step 3: Negative whole-number values belong to the integers."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"Number Systems"}', 2),
  (4, 1, 'Which is greater: -3 or -7?', 'text', 1, 'Think about their positions on the number line.', '{"why":"-3 is closer to zero and is therefore greater than -7.","sol":"Step 1: Locate -3 and -7 on the number line.\nStep 2: -3 is to the right of -7.\nStep 3: A number farther right is greater.","steps":["Step 1: Locate -3 and -7 on the number line.","Step 2: -3 is to the right of -7.","Step 3: A number farther right is greater."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q4","subject":"math","chapter":"numbers","topic":"Number Systems"}', 3),
  (5, 1, 'Arrange these integers from smallest to largest: 3, -2, 0, -5, 1.', 'text', 1, 'Start with the most negative number.', '{"why":"Numbers increase as we move from left to right on the number line.","sol":"Step 1: The smallest number is -5.\nStep 2: Next is -2.\nStep 3: Then comes 0.\nStep 4: Then 1.\nStep 5: Finally, 3.","steps":["Step 1: The smallest number is -5.","Step 2: Next is -2.","Step 3: Then comes 0.","Step 4: Then 1.","Step 5: Finally, 3."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q5","subject":"math","chapter":"numbers","topic":"Number Systems"}', 4),
  (6, 1, 'Calculate: -6 + 4', 'text', 1, 'Start at -6 and move 4 units to the right.', '{"why":"Adding 4 to -6 moves four units toward zero, giving -2.","sol":"Step 1: Start with -6.\nStep 2: Add 4.\nStep 3: -6 + 4 = -2.","steps":["Step 1: Start with -6.","Step 2: Add 4.","Step 3: -6 + 4 = -2."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q6","subject":"math","chapter":"numbers","topic":"Number Systems"}', 5),
  (7, 1, 'Calculate: 5 - 9', 'text', 1, 'Subtracting a larger number from a smaller number gives a negative result.', '{"why":"5 is 4 less than 9, so 5 - 9 = -4.","sol":"Step 1: Start with 5.\nStep 2: Subtract 9.\nStep 3: 5 - 9 = -4.","steps":["Step 1: Start with 5.","Step 2: Subtract 9.","Step 3: 5 - 9 = -4."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q7","subject":"math","chapter":"numbers","topic":"Number Systems"}', 6),
  (8, 1, 'Calculate: -4 × -3', 'text', 1, 'Look at the signs.', '{"why":"Two negative signs produce a positive result, and 4 × 3 = 12.","sol":"Step 1: The numbers have the same sign.\nStep 2: Negative × Negative gives Positive.\nStep 3: 4 × 3 = 12.","steps":["Step 1: The numbers have the same sign.","Step 2: Negative × Negative gives Positive.","Step 3: 4 × 3 = 12."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q8","subject":"math","chapter":"numbers","topic":"Number Systems"}', 7),
  (9, 1, 'Calculate: -20 ÷ 5', 'text', 1, 'Look at the signs before dividing.', '{"why":"Different signs give a negative result, and 20 ÷ 5 = 4.","sol":"Step 1: Negative ÷ Positive gives Negative.\nStep 2: 20 ÷ 5 = 4.\nStep 3: Therefore, -20 ÷ 5 = -4.","steps":["Step 1: Negative ÷ Positive gives Negative.","Step 2: 20 ÷ 5 = 4.","Step 3: Therefore, -20 ÷ 5 = -4."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q9","subject":"math","chapter":"numbers","topic":"Number Systems"}', 8),
  (10, 1, 'Which statement is correct?', 'text', 1, 'Think about how the number sets are contained.', '{"why":"The natural-number set is contained inside the whole-number set, which is contained inside the integers.","sol":"Step 1: Natural numbers are contained in whole numbers.\nStep 2: Whole numbers are contained in integers.\nStep 3: Therefore, Natural Numbers ⊂ Whole Numbers ⊂ Integers.","steps":["Step 1: Natural numbers are contained in whole numbers.","Step 2: Whole numbers are contained in integers.","Step 3: Therefore, Natural Numbers ⊂ Whole Numbers ⊂ Integers."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q10","subject":"math","chapter":"numbers","topic":"Number Systems"}', 9),
  (11, 2, 'Solve: 6 + 2 × 3', 'text', 1, 'Multiplication comes before addition.', '{"why":"Multiplication has priority over addition, so 2 × 3 is calculated first.","sol":"Step 1: Identify multiplication and addition.\nStep 2: Calculate 2 × 3 = 6.\nStep 3: Calculate 6 + 6 = 12.","steps":["Step 1: Identify multiplication and addition.","Step 2: Calculate 2 × 3 = 6.","Step 3: Calculate 6 + 6 = 12."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 0),
  (12, 2, 'Solve: 20 - 12 ÷ 3', 'text', 1, 'Division comes before subtraction.', '{"why":"Division is performed before subtraction.","sol":"Step 1: Calculate 12 ÷ 3 = 4.\nStep 2: Calculate 20 - 4 = 16.","steps":["Step 1: Calculate 12 ÷ 3 = 4.","Step 2: Calculate 20 - 4 = 16."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 1),
  (13, 2, 'Solve: (7 + 5) × 2', 'text', 1, 'Start with the brackets.', '{"why":"Brackets are calculated before multiplication.","sol":"Step 1: Calculate 7 + 5 = 12.\nStep 2: Calculate 12 × 2 = 24.","steps":["Step 1: Calculate 7 + 5 = 12.","Step 2: Calculate 12 × 2 = 24."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 2),
  (14, 2, 'Solve: 3 + 2²', 'text', 1, 'Calculate the order before addition.', '{"why":"Orders such as powers are calculated before addition.","sol":"Step 1: Calculate 2² = 4.\nStep 2: Calculate 3 + 4 = 7.","steps":["Step 1: Calculate 2² = 4.","Step 2: Calculate 3 + 4 = 7."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q4","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 3),
  (15, 2, 'Solve: 24 ÷ 3 × 2', 'text', 1, 'Division and multiplication have equal priority. Work left to right.', '{"why":"Division and multiplication have equal priority, so they are evaluated from left to right.","sol":"Step 1: Start from the left: 24 ÷ 3 = 8.\nStep 2: Continue left to right: 8 × 2 = 16.","steps":["Step 1: Start from the left: 24 ÷ 3 = 8.","Step 2: Continue left to right: 8 × 2 = 16."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q5","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 4),
  (16, 2, 'Solve: 15 - 6 + 2', 'text', 1, 'Addition and subtraction have equal priority.', '{"why":"Addition and subtraction have equal priority, so they are evaluated from left to right.","sol":"Step 1: Start from the left: 15 - 6 = 9.\nStep 2: Continue left to right: 9 + 2 = 11.","steps":["Step 1: Start from the left: 15 - 6 = 9.","Step 2: Continue left to right: 9 + 2 = 11."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q6","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 5),
  (17, 2, 'Solve: 8 + 2 × (5 - 3)²', 'text', 1, 'Follow the order: brackets, orders, multiplication, addition.', '{"why":"The expression follows BODMAS: brackets, orders, multiplication, then addition.","sol":"Step 1: (5 - 3) = 2.\nStep 2: 2² = 4.\nStep 3: 2 × 4 = 8.\nStep 4: 8 + 8 = 16.","steps":["Step 1: (5 - 3) = 2.","Step 2: 2² = 4.","Step 3: 2 × 4 = 8.","Step 4: 8 + 8 = 16."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q7","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 6),
  (18, 2, 'Solve: 2 × [3 + (4 - 1)]', 'text', 1, 'Solve the innermost brackets first.', '{"why":"Nested brackets are solved from the innermost bracket outward.","sol":"Step 1: 4 - 1 = 3.\nStep 2: 3 + 3 = 6.\nStep 3: 2 × 6 = 12.","steps":["Step 1: 4 - 1 = 3.","Step 2: 3 + 3 = 6.","Step 3: 2 × 6 = 12."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q8","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 7),
  (19, 2, 'A student solves 10 + 4 × 2 as (10 + 4) × 2. What did the student do wrong?', 'text', 1, 'Check which operation should be performed first.', '{"why":"The multiplication must be performed before the addition, so the correct answer is 18.","sol":"Step 1: Multiplication has priority over addition.\nStep 2: Calculate 4 × 2 = 8.\nStep 3: Calculate 10 + 8 = 18.","steps":["Step 1: Multiplication has priority over addition.","Step 2: Calculate 4 × 2 = 8.","Step 3: Calculate 10 + 8 = 18."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q9","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 8),
  (20, 2, 'Solve: 18 ÷ 3 × 2', 'text', 1, 'Do not automatically multiply first.', '{"why":"Division and multiplication have equal priority and are evaluated from left to right.","sol":"Step 1: Division and multiplication have equal priority.\nStep 2: Work from left to right: 18 ÷ 3 = 6.\nStep 3: 6 × 2 = 12.","steps":["Step 1: Division and multiplication have equal priority.","Step 2: Work from left to right: 18 ÷ 3 = 6.","Step 3: 6 × 2 = 12."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q10","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 9),
  (21, 3, 'Is 4,572 divisible by 3?', 'text', 1, 'Sum the digits', '{"why":"A number is divisible by 3 if the sum of its digits is divisible by 3 (4 + 5 + 7 + 2 = 18 = 3 × 6).","sol":"Step 1: Compute sum of digits: 4 + 5 + 7 + 2 = 18\nStep 2: Check if 18 is divisible by 3: 18 ÷ 3 = 6 (no remainder)\nStep 3: Conclude: 4,572 is divisible by 3","steps":["Step 1: Compute sum of digits: 4 + 5 + 7 + 2 = 18","Step 2: Check if 18 is divisible by 3: 18 ÷ 3 = 6 (no remainder)","Step 3: Conclude: 4,572 is divisible by 3"],"options":[],"conceptId":"math_numbers_divisibility_rules","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"Divisibility Rules"}', 0),
  (22, 3, 'Determine if 3,524 is divisible by 4.', 'text', 1, 'Check last two digits', '{"why":"A number is divisible by 4 if the number formed by its last two digits is divisible by 4 (24 ÷ 4 = 6).","sol":"Step 1: Identify the last two digits: 24\nStep 2: Check if 24 is divisible by 4: 24 ÷ 4 = 6\nStep 3: Conclude: 3,524 is divisible by 4","steps":["Step 1: Identify the last two digits: 24","Step 2: Check if 24 is divisible by 4: 24 ÷ 4 = 6","Step 3: Conclude: 3,524 is divisible by 4"],"options":[],"conceptId":"math_numbers_divisibility_rules","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"Divisibility Rules"}', 1),
  (23, 3, 'Is 1,236 divisible by 6?', 'text', 1, 'Check divisibility by both 2 and 3', '{"why":"Divisibility by 6 requires the number to be even and the sum of its digits to be a multiple of 3.","sol":"Step 1: Check divisibility by 2: last digit is 6 (even) → divisible by 2\nStep 2: Check divisibility by 3: 1 + 2 + 3 + 6 = 12, and 12 ÷ 3 = 4 → divisible by 3\nStep 3: Conclude: Since divisible by both 2 and 3, it is divisible by 6","steps":["Step 1: Check divisibility by 2: last digit is 6 (even) → divisible by 2","Step 2: Check divisibility by 3: 1 + 2 + 3 + 6 = 12, and 12 ÷ 3 = 4 → divisible by 3","Step 3: Conclude: Since divisible by both 2 and 3, it is divisible by 6"],"options":[],"conceptId":"math_numbers_divisibility_rules","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"Divisibility Rules"}', 2),
  (24, 3, 'Find the smallest single digit x such that 5,3x2 is divisible by 9.', 'text', 1, 'Sum of digits must be a multiple of 9', '{"why":"Sum of digits is 5 + 3 + x + 2 = 10 + x. The smallest single digit making this divisible by 9 is x = 8 (sum = 18).","sol":"Step 1: Calculate sum of known digits: 5 + 3 + 2 = 10\nStep 2: Set equation: 10 + x = 18 (next multiple of 9)\nStep 3: Solve for x: x = 18 - 10 = 8","steps":["Step 1: Calculate sum of known digits: 5 + 3 + 2 = 10","Step 2: Set equation: 10 + x = 18 (next multiple of 9)","Step 3: Solve for x: x = 18 - 10 = 8"],"options":[],"conceptId":"math_numbers_divisibility_rules","skillId":"math_numbers","subskillId":"math_numbers_q4","subject":"math","chapter":"numbers","topic":"Divisibility Rules"}', 3),
  (25, 4, 'Calculate 17 mod 5.', 'text', 1, 'Find remainder when 17 is divided by 5', '{"why":"17 divided by 5 yields quotient 3 with remainder 2.","sol":"Step 1: Divide 17 by 5: 17 = 5 × 3 + 2\nStep 2: Identify quotient (3) and remainder (2)\nStep 3: Conclude: 17 mod 5 = 2","steps":["Step 1: Divide 17 by 5: 17 = 5 × 3 + 2","Step 2: Identify quotient (3) and remainder (2)","Step 3: Conclude: 17 mod 5 = 2"],"options":[],"conceptId":"math_numbers_modular_arithmetic","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"Modular Arithmetic"}', 0),
  (26, 4, 'Evaluate (14 + 23) mod 6.', 'text', 1, 'Add then take modulo, or take modulo first', '{"why":"14 + 23 = 37. 37 = 6 × 6 + 1, so 37 mod 6 = 1.","sol":"Step 1: 14 mod 6 = 2, and 23 mod 6 = 5\nStep 2: Add remainders: 2 + 5 = 7\nStep 3: Reduce modulo 6: 7 mod 6 = 1","steps":["Step 1: 14 mod 6 = 2, and 23 mod 6 = 5","Step 2: Add remainders: 2 + 5 = 7","Step 3: Reduce modulo 6: 7 mod 6 = 1"],"options":[],"conceptId":"math_numbers_modular_arithmetic","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"Modular Arithmetic"}', 1),
  (27, 4, 'Find (7 × 8) mod 5.', 'text', 1, 'Multiply then divide by 5', '{"why":"56 divided by 5 gives remainder 1.","sol":"Step 1: Compute product: 7 × 8 = 56\nStep 2: Divide 56 by 5: 56 = 5 × 11 + 1\nStep 3: Conclude: 56 mod 5 = 1","steps":["Step 1: Compute product: 7 × 8 = 56","Step 2: Divide 56 by 5: 56 = 5 × 11 + 1","Step 3: Conclude: 56 mod 5 = 1"],"options":[],"conceptId":"math_numbers_modular_arithmetic","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"Modular Arithmetic"}', 2),
  (28, 4, 'Find 3^4 mod 7.', 'text', 1, 'Compute powers step by step', '{"why":"3^4 = 81. 81 = 7 × 11 + 4, so 81 mod 7 = 4.","sol":"Step 1: 3^2 = 9 ≡ 2 (mod 7)\nStep 2: 3^4 = (3^2)^2 ≡ 2^2 (mod 7)\nStep 3: 2^2 = 4 (mod 7)","steps":["Step 1: 3^2 = 9 ≡ 2 (mod 7)","Step 2: 3^4 = (3^2)^2 ≡ 2^2 (mod 7)","Step 3: 2^2 = 4 (mod 7)"],"options":[],"conceptId":"math_numbers_modular_arithmetic","skillId":"math_numbers","subskillId":"math_numbers_q4","subject":"math","chapter":"numbers","topic":"Modular Arithmetic"}', 3),
  (29, 5, 'What is the only even prime number?', 'text', 1, 'Smallest prime', '{"why":"2 is the smallest prime and the only even prime number, because any larger even number is divisible by 2.","sol":"Step 1: Check even numbers: 2, 4, 6, 8...\nStep 2: 2 has only divisors 1 and 2 → prime\nStep 3: Any even number > 2 is divisible by 2 → composite. ∴ 2 is the only even prime","steps":["Step 1: Check even numbers: 2, 4, 6, 8...","Step 2: 2 has only divisors 1 and 2 → prime","Step 3: Any even number > 2 is divisible by 2 → composite. ∴ 2 is the only even prime"],"options":[],"conceptId":"math_numbers_prime_numbers","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"Prime Numbers"}', 0),
  (30, 5, 'Find the prime factorization of 60.', 'text', 1, 'Break into prime factors', '{"why":"60 = 4 × 15 = (2 × 2) × (3 × 5) = 2² × 3 × 5.","sol":"Step 1: 60 = 2 × 30\nStep 2: 30 = 2 × 15\nStep 3: 15 = 3 × 5\nStep 4: Combine prime factors: 2 × 2 × 3 × 5 = 2² × 3 × 5","steps":["Step 1: 60 = 2 × 30","Step 2: 30 = 2 × 15","Step 3: 15 = 3 × 5","Step 4: Combine prime factors: 2 × 2 × 3 × 5 = 2² × 3 × 5"],"options":[],"conceptId":"math_numbers_prime_numbers","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"Prime Numbers"}', 1),
  (31, 5, 'Is 29 a prime or composite number?', 'text', 1, 'Check divisibility by primes ≤ √29 ≈ 5.38 (2, 3, 5)', '{"why":"29 has no divisors other than 1 and itself, making it prime.","sol":"Step 1: Check primes up to √29: 2, 3, 5\nStep 2: 29 is not divisible by 2 (odd), 3 (2+9=11), or 5 (ends in 9)\nStep 3: Conclude: 29 has no divisors other than 1 and 29 → Prime","steps":["Step 1: Check primes up to √29: 2, 3, 5","Step 2: 29 is not divisible by 2 (odd), 3 (2+9=11), or 5 (ends in 9)","Step 3: Conclude: 29 has no divisors other than 1 and 29 → Prime"],"options":[],"conceptId":"math_numbers_prime_numbers","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"Prime Numbers"}', 2),
  (32, 5, 'Find the greatest common divisor (GCD) of 24 and 36 using prime factorization.', 'text', 1, 'Take lowest power of common prime factors', '{"why":"GCD(24, 36) = 2² × 3 = 12.","sol":"Step 1: Prime factorize: 24 = 2³ × 3¹, 36 = 2² × 3²\nStep 2: Identify common prime factors: 2 and 3\nStep 3: Take minimum powers: 2² × 3¹ = 4 × 3 = 12","steps":["Step 1: Prime factorize: 24 = 2³ × 3¹, 36 = 2² × 3²","Step 2: Identify common prime factors: 2 and 3","Step 3: Take minimum powers: 2² × 3¹ = 4 × 3 = 12"],"options":[],"conceptId":"math_numbers_prime_numbers","skillId":"math_numbers","subskillId":"math_numbers_q4","subject":"math","chapter":"numbers","topic":"Prime Numbers"}', 3),
  (33, 6, 'Solve the linear congruence: 2x ≡ 6 (mod 8) for 0 ≤ x < 8.', 'text', 1, 'Check integers 0 through 7 or divide by gcd', '{"why":"2(3) = 6 ≡ 6 (mod 8) and 2(7) = 14 ≡ 6 (mod 8).","sol":"Step 1: Note gcd(2, 8) = 2. Since 2 divides 6, there are 2 incongruent solutions\nStep 2: Divide congruence by 2: x ≡ 3 (mod 4)\nStep 3: Find values in range 0 ≤ x < 8: x = 3 and x = 3 + 4 = 7","steps":["Step 1: Note gcd(2, 8) = 2. Since 2 divides 6, there are 2 incongruent solutions","Step 2: Divide congruence by 2: x ≡ 3 (mod 4)","Step 3: Find values in range 0 ≤ x < 8: x = 3 and x = 3 + 4 = 7"],"options":[],"conceptId":"math_numbers_congruence_relations","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"Congruence Relations"}', 0),
  (34, 6, 'Is 38 ≡ 14 (mod 8)?', 'text', 1, 'Check if (38 - 14) is divisible by 8', '{"why":"38 - 14 = 24, which is a multiple of 8 (8 × 3 = 24).","sol":"Step 1: Calculate difference: 38 - 14 = 24\nStep 2: Check divisibility by 8: 24 ÷ 8 = 3 (exact integer)\nStep 3: Conclude: 38 ≡ 14 (mod 8) is True","steps":["Step 1: Calculate difference: 38 - 14 = 24","Step 2: Check divisibility by 8: 24 ÷ 8 = 3 (exact integer)","Step 3: Conclude: 38 ≡ 14 (mod 8) is True"],"options":[],"conceptId":"math_numbers_congruence_relations","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"Congruence Relations"}', 1),
  (35, 6, 'Find the modular inverse of 3 modulo 7.', 'text', 1, 'Find integer x such that 3x ≡ 1 (mod 7)', '{"why":"3 × 5 = 15 ≡ 1 (mod 7), so 5 is the modular multiplicative inverse of 3 modulo 7.","sol":"Step 1: Test multiples of 3 modulo 7: 3(1)=3, 3(2)=6, 3(3)=9 ≡ 2, 3(4)=12\nStep 2: 12 mod 7 = 5; next test 3(5) = 15\nStep 3: 15 mod 7 = 1 (since 15 = 2 × 7 + 1). ∴ inverse is 5","steps":["Step 1: Test multiples of 3 modulo 7: 3(1)=3, 3(2)=6, 3(3)=9 ≡ 2, 3(4)=12","Step 2: 12 mod 7 = 5; next test 3(5) = 15","Step 3: 15 mod 7 = 1 (since 15 = 2 × 7 + 1). ∴ inverse is 5"],"options":[],"conceptId":"math_numbers_congruence_relations","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"Congruence Relations"}', 2),
  (36, 7, 'A boy walks 600 m from home to school. What is the distance travelled?', 'text', 1, 'Distance tells how far the boy travelled.', '{"why":"Distance is the total length of the path travelled.","sol":"Step 1: The boy travels from home to school.\nStep 2: The given length is 600 m.\nStep 3: Therefore, the distance travelled is 600 m.","steps":["Step 1: The boy travels from home to school.","Step 2: The given length is 600 m.","Step 3: Therefore, the distance travelled is 600 m."],"options":[],"conceptId":"math_linear_motion_distance","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Distance"}', 0),
  (37, 7, 'A runner travels 400 m and then another 300 m. Find the total distance.', 'text', 1, 'Add both sections of the path.', '{"why":"Both sections form part of the total path travelled.","sol":"Step 1: First section = 400 m.\nStep 2: Second section = 300 m.\nStep 3: Total distance = 400 + 300.\nStep 4: Total distance = 700 m.","steps":["Step 1: First section = 400 m.","Step 2: Second section = 300 m.","Step 3: Total distance = 400 + 300.","Step 4: Total distance = 700 m."],"options":[],"conceptId":"math_linear_motion_distance","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Distance"}', 1),
  (38, 7, 'A cyclist travels 5 km, then 2 km, then 3 km. Find the total distance.', 'text', 1, 'Add every section travelled.', '{"why":"Total distance is the sum of all parts of the path.","sol":"Step 1: First section = 5 km.\nStep 2: Second section = 2 km.\nStep 3: Third section = 3 km.\nStep 4: Total distance = 5 + 2 + 3 = 10 km.","steps":["Step 1: First section = 5 km.","Step 2: Second section = 2 km.","Step 3: Third section = 3 km.","Step 4: Total distance = 5 + 2 + 3 = 10 km."],"options":[],"conceptId":"math_linear_motion_distance","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Distance"}', 2),
  (39, 7, 'What does distance measure in a motion problem?', 'text', 1, 'Think about how far the object travels.', '{"why":"Distance measures how far an object travels, without considering direction.","sol":"Step 1: An object follows a path when it moves.\nStep 2: Distance measures the length of that path.\nStep 3: Therefore, distance tells how far the object travelled.","steps":["Step 1: An object follows a path when it moves.","Step 2: Distance measures the length of that path.","Step 3: Therefore, distance tells how far the object travelled."],"options":[],"conceptId":"math_linear_motion_distance","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Distance"}', 3),
  (40, 8, 'A car moves 60 km east from A to B. What is its displacement?', 'text', 1, 'State both the size and direction of the change in position.', '{"why":"Displacement describes the change in position together with direction.","sol":"Step 1: The car starts at A.\nStep 2: It finishes 60 km east of A.\nStep 3: Therefore, its displacement is 60 km east.","steps":["Step 1: The car starts at A.","Step 2: It finishes 60 km east of A.","Step 3: Therefore, its displacement is 60 km east."],"options":[],"conceptId":"math_linear_motion_displacement","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Displacement"}', 0),
  (41, 8, 'A cyclist moves 5 km west from P to Q. What is the displacement?', 'text', 1, 'The direction of movement is west.', '{"why":"Displacement must include the direction of the change in position.","sol":"Step 1: The cyclist starts at P.\nStep 2: The cyclist finishes 5 km west of P.\nStep 3: Therefore, displacement = 5 km west.","steps":["Step 1: The cyclist starts at P.","Step 2: The cyclist finishes 5 km west of P.","Step 3: Therefore, displacement = 5 km west."],"options":[],"conceptId":"math_linear_motion_displacement","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Displacement"}', 1),
  (42, 8, 'A runner completes a 400 m lap and finishes exactly where they started. Find the displacement.', 'text', 1, 'Compare the starting position with the final position.', '{"why":"There is no change in position when the object finishes where it started.","sol":"Step 1: The runner starts at one point.\nStep 2: After one complete lap, the runner returns to that same point.\nStep 3: The starting and final positions are identical.\nStep 4: Therefore, displacement = 0 m.","steps":["Step 1: The runner starts at one point.","Step 2: After one complete lap, the runner returns to that same point.","Step 3: The starting and final positions are identical.","Step 4: Therefore, displacement = 0 m."],"options":[],"conceptId":"math_linear_motion_displacement","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Displacement"}', 2),
  (43, 8, 'A person moves 2 km north. State the displacement.', 'text', 1, 'Include both magnitude and direction.', '{"why":"Displacement requires both magnitude and direction.","sol":"Step 1: The person changes position by 2 km.\nStep 2: The direction is north.\nStep 3: Therefore, displacement = 2 km north.","steps":["Step 1: The person changes position by 2 km.","Step 2: The direction is north.","Step 3: Therefore, displacement = 2 km north."],"options":[],"conceptId":"math_linear_motion_displacement","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Displacement"}', 3),
  (44, 9, 'A car travels 70 km east in a straight line. State its distance and displacement.', 'text', 1, 'The car moves in one direction only.', '{"why":"For straight movement in one direction, distance equals the magnitude of displacement.","sol":"Step 1: The total path travelled is 70 km.\nStep 2: The final position is 70 km east of the start.\nStep 3: Distance = 70 km.\nStep 4: Displacement = 70 km east.","steps":["Step 1: The total path travelled is 70 km.","Step 2: The final position is 70 km east of the start.","Step 3: Distance = 70 km.","Step 4: Displacement = 70 km east."],"options":[],"conceptId":"math_linear_motion_distance_and_displacement_compared","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Distance and Displacement Compared"}', 0),
  (45, 9, 'A student walks 3 km north and then 3 km south. Find the distance and displacement.', 'text', 1, 'Calculate the whole path first, then compare start and finish.', '{"why":"The student travels 6 km but finishes at the starting position.","sol":"Step 1: Distance = 3 + 3 = 6 km.\nStep 2: The student returns to the starting position.\nStep 3: Therefore, displacement = 0 km.","steps":["Step 1: Distance = 3 + 3 = 6 km.","Step 2: The student returns to the starting position.","Step 3: Therefore, displacement = 0 km."],"options":[],"conceptId":"math_linear_motion_distance_and_displacement_compared","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Distance and Displacement Compared"}', 1),
  (46, 9, 'A cyclist travels 4 km east and then 1 km east. Find the distance and displacement.', 'text', 1, 'Both parts are in the same direction.', '{"why":"Both movements increase the cyclist''s position in the same direction.","sol":"Step 1: Distance = 4 + 1 = 5 km.\nStep 2: The cyclist finishes 5 km east of the start.\nStep 3: Displacement = 5 km east.","steps":["Step 1: Distance = 4 + 1 = 5 km.","Step 2: The cyclist finishes 5 km east of the start.","Step 3: Displacement = 5 km east."],"options":[],"conceptId":"math_linear_motion_distance_and_displacement_compared","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Distance and Displacement Compared"}', 2),
  (47, 9, 'Can displacement be zero while distance is greater than zero?', 'text', 1, 'Think about an object returning to its starting point.', '{"why":"Returning to the starting position makes displacement zero even though a distance was travelled.","sol":"Step 1: An object can move away from its starting point.\nStep 2: It can then return to the same starting point.\nStep 3: The distance travelled is greater than zero.\nStep 4: The starting and final positions are the same, so displacement is zero.","steps":["Step 1: An object can move away from its starting point.","Step 2: It can then return to the same starting point.","Step 3: The distance travelled is greater than zero.","Step 4: The starting and final positions are the same, so displacement is zero."],"options":[],"conceptId":"math_linear_motion_distance_and_displacement_compared","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Distance and Displacement Compared"}', 3),
  (48, 10, 'A car travels 180 km in 3 hours. Find its speed.', 'text', 1, 'Use speed = distance ÷ time.', '{"why":"Speed tells us the distance covered per unit of time.","sol":"Step 1: Distance = 180 km.\nStep 2: Time = 3 h.\nStep 3: Speed = 180 ÷ 3.\nStep 4: Speed = 60 km/h.","steps":["Step 1: Distance = 180 km.","Step 2: Time = 3 h.","Step 3: Speed = 180 ÷ 3.","Step 4: Speed = 60 km/h."],"options":[],"conceptId":"math_linear_motion_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Speed"}', 0),
  (49, 10, 'A cyclist travels 100 km in 5 hours. Find the speed.', 'text', 1, 'Divide the distance by the time.', '{"why":"Dividing distance by time gives the rate at which distance is covered.","sol":"Step 1: Distance = 100 km.\nStep 2: Time = 5 h.\nStep 3: Speed = 100 ÷ 5.\nStep 4: Speed = 20 km/h.","steps":["Step 1: Distance = 100 km.","Step 2: Time = 5 h.","Step 3: Speed = 100 ÷ 5.","Step 4: Speed = 20 km/h."],"options":[],"conceptId":"math_linear_motion_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Speed"}', 1),
  (50, 10, 'A bus travels 360 km in 6 hours. Find its speed.', 'text', 1, 'Substitute distance and time into s = d/t.', '{"why":"Speed is the distance travelled for each hour of the journey.","sol":"Step 1: Distance = 360 km.\nStep 2: Time = 6 h.\nStep 3: Speed = 360 ÷ 6.\nStep 4: Speed = 60 km/h.","steps":["Step 1: Distance = 360 km.","Step 2: Time = 6 h.","Step 3: Speed = 360 ÷ 6.","Step 4: Speed = 60 km/h."],"options":[],"conceptId":"math_linear_motion_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Speed"}', 2),
  (51, 10, 'A runner covers 20 km in 2 hours. Find the runner''s speed.', 'text', 1, 'Divide 20 km by 2 hours.', '{"why":"Speed is calculated by dividing distance by time.","sol":"Step 1: Distance = 20 km.\nStep 2: Time = 2 h.\nStep 3: Speed = 20 ÷ 2.\nStep 4: Speed = 10 km/h.","steps":["Step 1: Distance = 20 km.","Step 2: Time = 2 h.","Step 3: Speed = 20 ÷ 2.","Step 4: Speed = 10 km/h."],"options":[],"conceptId":"math_linear_motion_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Speed"}', 3),
  (52, 11, 'A car travels 50 km in 1 hour and 70 km in 2 hours. Find its average speed.', 'text', 1, 'Find total distance and total time first.', '{"why":"Average speed uses the total distance and total time for the whole journey.","sol":"Step 1: Total distance = 50 + 70 = 120 km.\nStep 2: Total time = 1 + 2 = 3 h.\nStep 3: Average speed = 120 ÷ 3.\nStep 4: Average speed = 40 km/h.","steps":["Step 1: Total distance = 50 + 70 = 120 km.","Step 2: Total time = 1 + 2 = 3 h.","Step 3: Average speed = 120 ÷ 3.","Step 4: Average speed = 40 km/h."],"options":[],"conceptId":"math_linear_motion_average_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Average Speed"}', 0),
  (53, 11, 'A cyclist travels 40 km in 2 hours and 20 km in 1 hour. Find the average speed.', 'text', 1, 'Add the distances and add the times.', '{"why":"Average speed is total distance divided by total time.","sol":"Step 1: Total distance = 40 + 20 = 60 km.\nStep 2: Total time = 2 + 1 = 3 h.\nStep 3: Average speed = 60 ÷ 3.\nStep 4: Average speed = 20 km/h.","steps":["Step 1: Total distance = 40 + 20 = 60 km.","Step 2: Total time = 2 + 1 = 3 h.","Step 3: Average speed = 60 ÷ 3.","Step 4: Average speed = 20 km/h."],"options":[],"conceptId":"math_linear_motion_average_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Average Speed"}', 1),
  (54, 11, 'A bus travels 100 km to a town in 2 hours and returns 100 km in 3 hours. Find its average speed.', 'text', 1, 'The total distance is 200 km and the total time is 5 hours.', '{"why":"The whole journey must be considered when calculating average speed.","sol":"Step 1: Total distance = 100 + 100 = 200 km.\nStep 2: Total time = 2 + 3 = 5 h.\nStep 3: Average speed = 200 ÷ 5.\nStep 4: Average speed = 40 km/h.","steps":["Step 1: Total distance = 100 + 100 = 200 km.","Step 2: Total time = 2 + 3 = 5 h.","Step 3: Average speed = 200 ÷ 5.","Step 4: Average speed = 40 km/h."],"options":[],"conceptId":"math_linear_motion_average_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Average Speed"}', 2),
  (55, 11, 'A journey covers 90 km in 3 hours. What is the average speed?', 'text', 1, 'For one constant journey, divide distance by time.', '{"why":"Average speed is total distance divided by total time.","sol":"Step 1: Total distance = 90 km.\nStep 2: Total time = 3 h.\nStep 3: Average speed = 90 ÷ 3.\nStep 4: Average speed = 30 km/h.","steps":["Step 1: Total distance = 90 km.","Step 2: Total time = 3 h.","Step 3: Average speed = 90 ÷ 3.","Step 4: Average speed = 30 km/h."],"options":[],"conceptId":"math_linear_motion_average_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Average Speed"}', 3),
  (56, 12, 'A car travels at 70 km/h east. State its velocity.', 'text', 1, 'Velocity includes speed and direction.', '{"why":"Velocity requires both magnitude and direction.","sol":"Step 1: Speed = 70 km/h.\nStep 2: Direction = east.\nStep 3: Therefore, velocity = 70 km/h east.","steps":["Step 1: Speed = 70 km/h.","Step 2: Direction = east.","Step 3: Therefore, velocity = 70 km/h east."],"options":[],"conceptId":"math_linear_motion_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Velocity"}', 0),
  (57, 12, 'A train moves at 90 km/h south. State its velocity.', 'text', 1, 'Include the direction south.', '{"why":"The direction distinguishes velocity from speed.","sol":"Step 1: Speed = 90 km/h.\nStep 2: Direction = south.\nStep 3: Therefore, velocity = 90 km/h south.","steps":["Step 1: Speed = 90 km/h.","Step 2: Direction = south.","Step 3: Therefore, velocity = 90 km/h south."],"options":[],"conceptId":"math_linear_motion_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Velocity"}', 1),
  (58, 12, 'Is 40 km/h a complete statement of velocity?', 'text', 1, 'Ask whether a direction has been given.', '{"why":"A velocity must specify direction.","sol":"Step 1: 40 km/h gives the magnitude of motion.\nStep 2: No direction is specified.\nStep 3: Therefore, it describes speed, not a complete velocity.","steps":["Step 1: 40 km/h gives the magnitude of motion.","Step 2: No direction is specified.","Step 3: Therefore, it describes speed, not a complete velocity."],"options":[],"conceptId":"math_linear_motion_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Velocity"}', 2),
  (59, 12, 'A cyclist moves at 30 km/h west. What is the speed and what is the velocity?', 'text', 1, 'Speed has no direction; velocity includes direction.', '{"why":"Velocity is speed together with direction.","sol":"Step 1: The speed is 30 km/h.\nStep 2: The direction is west.\nStep 3: Therefore, velocity is 30 km/h west.","steps":["Step 1: The speed is 30 km/h.","Step 2: The direction is west.","Step 3: Therefore, velocity is 30 km/h west."],"options":[],"conceptId":"math_linear_motion_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Velocity"}', 3),
  (60, 13, 'A car moves 100 km east in 2 hours. Find its average velocity.', 'text', 1, 'Use displacement ÷ time.', '{"why":"Average velocity uses displacement divided by total time.","sol":"Step 1: Displacement = 100 km east.\nStep 2: Time = 2 h.\nStep 3: Average velocity = 100 ÷ 2.\nStep 4: Average velocity = 50 km/h east.","steps":["Step 1: Displacement = 100 km east.","Step 2: Time = 2 h.","Step 3: Average velocity = 100 ÷ 2.","Step 4: Average velocity = 50 km/h east."],"options":[],"conceptId":"math_linear_motion_average_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Average Velocity"}', 0),
  (61, 13, 'A runner returns to the starting point after 3 hours. What is the average velocity?', 'text', 1, 'The displacement is zero.', '{"why":"Returning to the starting point gives zero displacement.","sol":"Step 1: The runner finishes at the starting position.\nStep 2: Displacement = 0 km.\nStep 3: Average velocity = 0 ÷ 3.\nStep 4: Average velocity = 0 km/h.","steps":["Step 1: The runner finishes at the starting position.","Step 2: Displacement = 0 km.","Step 3: Average velocity = 0 ÷ 3.","Step 4: Average velocity = 0 km/h."],"options":[],"conceptId":"math_linear_motion_average_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Average Velocity"}', 1),
  (62, 13, 'A cyclist travels 60 km west in 3 hours. Find the average velocity.', 'text', 1, 'Include the direction west.', '{"why":"Average velocity includes the direction of displacement.","sol":"Step 1: Displacement = 60 km west.\nStep 2: Time = 3 h.\nStep 3: Average velocity = 60 ÷ 3.\nStep 4: Average velocity = 20 km/h west.","steps":["Step 1: Displacement = 60 km west.","Step 2: Time = 3 h.","Step 3: Average velocity = 60 ÷ 3.","Step 4: Average velocity = 20 km/h west."],"options":[],"conceptId":"math_linear_motion_average_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Average Velocity"}', 2),
  (63, 13, 'What quantity is used to calculate average velocity: distance or displacement?', 'text', 1, 'Velocity describes a change in position.', '{"why":"Average velocity is total displacement divided by total time.","sol":"Step 1: Velocity includes direction.\nStep 2: Displacement includes direction.\nStep 3: Therefore, average velocity uses displacement.","steps":["Step 1: Velocity includes direction.","Step 2: Displacement includes direction.","Step 3: Therefore, average velocity uses displacement."],"options":[],"conceptId":"math_linear_motion_average_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Average Velocity"}', 3),
  (64, 14, 'A car changes velocity from 10 m/s to 30 m/s in 5 s. Find its acceleration.', 'text', 1, 'Use a = (v - u)/t.', '{"why":"Acceleration measures the change in velocity per unit time.","sol":"Step 1: u = 10 m/s.\nStep 2: v = 30 m/s.\nStep 3: Change in velocity = 30 - 10 = 20 m/s.\nStep 4: Acceleration = 20 ÷ 5 = 4 m/s².","steps":["Step 1: u = 10 m/s.","Step 2: v = 30 m/s.","Step 3: Change in velocity = 30 - 10 = 20 m/s.","Step 4: Acceleration = 20 ÷ 5 = 4 m/s²."],"options":[],"conceptId":"math_linear_motion_acceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Acceleration"}', 0),
  (65, 14, 'A bicycle changes velocity from 4 m/s to 16 m/s in 6 s. Find its acceleration.', 'text', 1, 'Subtract the initial velocity from the final velocity first.', '{"why":"Acceleration is the change in velocity divided by time.","sol":"Step 1: u = 4 m/s.\nStep 2: v = 16 m/s.\nStep 3: Change in velocity = 16 - 4 = 12 m/s.\nStep 4: Acceleration = 12 ÷ 6 = 2 m/s².","steps":["Step 1: u = 4 m/s.","Step 2: v = 16 m/s.","Step 3: Change in velocity = 16 - 4 = 12 m/s.","Step 4: Acceleration = 12 ÷ 6 = 2 m/s²."],"options":[],"conceptId":"math_linear_motion_acceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Acceleration"}', 1),
  (66, 14, 'A car changes velocity from 20 m/s to 8 m/s in 4 s. Find its acceleration.', 'text', 1, 'Final velocity minus initial velocity gives a negative change.', '{"why":"The negative acceleration shows that velocity is decreasing in the chosen direction.","sol":"Step 1: u = 20 m/s.\nStep 2: v = 8 m/s.\nStep 3: Change in velocity = 8 - 20 = -12 m/s.\nStep 4: Acceleration = -12 ÷ 4 = -3 m/s².","steps":["Step 1: u = 20 m/s.","Step 2: v = 8 m/s.","Step 3: Change in velocity = 8 - 20 = -12 m/s.","Step 4: Acceleration = -12 ÷ 4 = -3 m/s²."],"options":[],"conceptId":"math_linear_motion_acceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Acceleration"}', 2),
  (67, 14, 'What does acceleration measure?', 'text', 1, 'Think about what happens to velocity as time passes.', '{"why":"Acceleration tells us how quickly velocity changes with time.","sol":"Step 1: Velocity can change during motion.\nStep 2: Acceleration measures how quickly that velocity changes.\nStep 3: Therefore, acceleration is change in velocity per unit time.","steps":["Step 1: Velocity can change during motion.","Step 2: Acceleration measures how quickly that velocity changes.","Step 3: Therefore, acceleration is change in velocity per unit time."],"options":[],"conceptId":"math_linear_motion_acceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Acceleration"}', 3),
  (68, 15, 'A car slows from 30 m/s to 20 m/s in 5 s. Find its acceleration.', 'text', 1, 'Use final velocity minus initial velocity.', '{"why":"The negative acceleration represents a decrease in velocity.","sol":"Step 1: u = 30 m/s.\nStep 2: v = 20 m/s.\nStep 3: Change = 20 - 30 = -10 m/s.\nStep 4: Acceleration = -10 ÷ 5 = -2 m/s².","steps":["Step 1: u = 30 m/s.","Step 2: v = 20 m/s.","Step 3: Change = 20 - 30 = -10 m/s.","Step 4: Acceleration = -10 ÷ 5 = -2 m/s²."],"options":[],"conceptId":"math_linear_motion_deceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Deceleration"}', 0),
  (69, 15, 'A bus slows from 40 m/s to 16 m/s in 6 s. Find its acceleration.', 'text', 1, 'Subtract 40 from 16, then divide by 6.', '{"why":"Velocity decreases by 24 m/s during the 6 seconds.","sol":"Step 1: u = 40 m/s.\nStep 2: v = 16 m/s.\nStep 3: Change = 16 - 40 = -24 m/s.\nStep 4: Acceleration = -24 ÷ 6 = -4 m/s².","steps":["Step 1: u = 40 m/s.","Step 2: v = 16 m/s.","Step 3: Change = 16 - 40 = -24 m/s.","Step 4: Acceleration = -24 ÷ 6 = -4 m/s²."],"options":[],"conceptId":"math_linear_motion_deceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Deceleration"}', 1),
  (70, 15, 'A motorcycle slows from 18 m/s to 6 m/s in 3 s. Find its acceleration.', 'text', 1, 'A decrease in velocity produces a negative change.', '{"why":"The negative sign indicates that the velocity is decreasing.","sol":"Step 1: u = 18 m/s.\nStep 2: v = 6 m/s.\nStep 3: Change = 6 - 18 = -12 m/s.\nStep 4: Acceleration = -12 ÷ 3 = -4 m/s².","steps":["Step 1: u = 18 m/s.","Step 2: v = 6 m/s.","Step 3: Change = 6 - 18 = -12 m/s.","Step 4: Acceleration = -12 ÷ 3 = -4 m/s²."],"options":[],"conceptId":"math_linear_motion_deceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Deceleration"}', 2),
  (71, 15, 'What does a negative acceleration mean in these examples?', 'text', 1, 'Look at what happened to the velocity.', '{"why":"A negative change in velocity produces negative acceleration in the chosen direction.","sol":"Step 1: The final velocity is smaller than the initial velocity.\nStep 2: Therefore, v - u is negative.\nStep 3: The negative acceleration represents a decrease in velocity in the chosen direction.","steps":["Step 1: The final velocity is smaller than the initial velocity.","Step 2: Therefore, v - u is negative.","Step 3: The negative acceleration represents a decrease in velocity in the chosen direction."],"options":[],"conceptId":"math_linear_motion_deceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Deceleration"}', 3),
  (72, 16, 'A point on a distance-time graph is (3 h, 150 km). What distance has been travelled?', 'text', 1, 'Distance is read from the vertical coordinate.', '{"why":"Distance is represented on the vertical axis.","sol":"Step 1: The point is (3 h, 150 km).\nStep 2: The second coordinate represents distance.\nStep 3: Therefore, distance = 150 km.","steps":["Step 1: The point is (3 h, 150 km).","Step 2: The second coordinate represents distance.","Step 3: Therefore, distance = 150 km."],"options":[],"conceptId":"math_linear_motion_reading_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Reading a Distance-Time Graph"}', 0),
  (73, 16, 'A point on a distance-time graph is (4 h, 200 km). What time does it represent?', 'text', 1, 'Time is represented on the horizontal axis.', '{"why":"Time is represented on the horizontal axis.","sol":"Step 1: The point is (4 h, 200 km).\nStep 2: The first coordinate represents time.\nStep 3: Therefore, time = 4 h.","steps":["Step 1: The point is (4 h, 200 km).","Step 2: The first coordinate represents time.","Step 3: Therefore, time = 4 h."],"options":[],"conceptId":"math_linear_motion_reading_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Reading a Distance-Time Graph"}', 1),
  (74, 16, 'At 6 hours, a graph shows a distance of 360 km. State the point on the graph.', 'text', 1, 'Write the point as (time, distance).', '{"why":"The horizontal coordinate is time and the vertical coordinate is distance.","sol":"Step 1: Time = 6 h.\nStep 2: Distance = 360 km.\nStep 3: A point is written as (time, distance).\nStep 4: Therefore, the point is (6 h, 360 km).","steps":["Step 1: Time = 6 h.","Step 2: Distance = 360 km.","Step 3: A point is written as (time, distance).","Step 4: Therefore, the point is (6 h, 360 km)."],"options":[],"conceptId":"math_linear_motion_reading_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Reading a Distance-Time Graph"}', 2),
  (75, 16, 'Which quantity belongs on the horizontal axis of a distance-time graph?', 'text', 1, 'Think about which quantity is allowed to pass as the motion happens.', '{"why":"A distance-time graph shows how distance changes with time.","sol":"Step 1: Time passes during motion.\nStep 2: Distance changes as time passes.\nStep 3: Therefore, time is placed on the horizontal axis.","steps":["Step 1: Time passes during motion.","Step 2: Distance changes as time passes.","Step 3: Therefore, time is placed on the horizontal axis."],"options":[],"conceptId":"math_linear_motion_reading_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Reading a Distance-Time Graph"}', 3),
  (76, 17, 'A distance-time graph goes from (0 h, 0 km) to (4 h, 200 km). Find its gradient.', 'text', 1, 'Gradient = change in distance ÷ change in time.', '{"why":"The gradient of a distance-time graph represents speed.","sol":"Step 1: Change in distance = 200 - 0 = 200 km.\nStep 2: Change in time = 4 - 0 = 4 h.\nStep 3: Gradient = 200 ÷ 4.\nStep 4: Gradient = 50 km/h.","steps":["Step 1: Change in distance = 200 - 0 = 200 km.","Step 2: Change in time = 4 - 0 = 4 h.","Step 3: Gradient = 200 ÷ 4.","Step 4: Gradient = 50 km/h."],"options":[],"conceptId":"math_linear_motion_gradient_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Gradient of a Distance-Time Graph"}', 0),
  (77, 17, 'A graph passes through (2 h, 40 km) and (5 h, 160 km). Find the gradient.', 'text', 1, 'Subtract corresponding coordinates first.', '{"why":"Gradient is change in distance divided by change in time.","sol":"Step 1: Change in distance = 160 - 40 = 120 km.\nStep 2: Change in time = 5 - 2 = 3 h.\nStep 3: Gradient = 120 ÷ 3.\nStep 4: Gradient = 40 km/h.","steps":["Step 1: Change in distance = 160 - 40 = 120 km.","Step 2: Change in time = 5 - 2 = 3 h.","Step 3: Gradient = 120 ÷ 3.","Step 4: Gradient = 40 km/h."],"options":[],"conceptId":"math_linear_motion_gradient_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Gradient of a Distance-Time Graph"}', 1),
  (78, 17, 'A distance-time graph has a gradient of 60 km/h. What does this tell you about the object''s speed?', 'text', 1, 'The gradient represents speed.', '{"why":"Gradient on a distance-time graph gives speed.","sol":"Step 1: For a distance-time graph, gradient represents speed.\nStep 2: The gradient is 60 km/h.\nStep 3: Therefore, the object''s speed is 60 km/h.","steps":["Step 1: For a distance-time graph, gradient represents speed.","Step 2: The gradient is 60 km/h.","Step 3: Therefore, the object''s speed is 60 km/h."],"options":[],"conceptId":"math_linear_motion_gradient_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Gradient of a Distance-Time Graph"}', 2),
  (79, 17, 'Which object is faster: one with a distance-time gradient of 30 km/h or one with 50 km/h?', 'text', 1, 'A larger gradient means greater speed.', '{"why":"A greater gradient represents a greater speed.","sol":"Step 1: First object''s speed = 30 km/h.\nStep 2: Second object''s speed = 50 km/h.\nStep 3: 50 km/h is greater than 30 km/h.\nStep 4: Therefore, the second object is faster.","steps":["Step 1: First object''s speed = 30 km/h.","Step 2: Second object''s speed = 50 km/h.","Step 3: 50 km/h is greater than 30 km/h.","Step 4: Therefore, the second object is faster."],"options":[],"conceptId":"math_linear_motion_gradient_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Gradient of a Distance-Time Graph"}', 3),
  (80, 18, 'A distance-time graph is horizontal from 2 h to 5 h. What is happening?', 'text', 1, 'A horizontal line means distance is not changing.', '{"why":"A horizontal distance-time graph means there is no change in distance.","sol":"Step 1: The distance remains constant.\nStep 2: Time continues to pass.\nStep 3: Therefore, the object is stationary.","steps":["Step 1: The distance remains constant.","Step 2: Time continues to pass.","Step 3: Therefore, the object is stationary."],"options":[],"conceptId":"math_linear_motion_interpreting_a_horizontal_section_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Interpreting a Horizontal Section of a Distance-Time Graph"}', 0),
  (81, 18, 'An object is stationary from 4 h to 6 h. How long is it stationary?', 'text', 1, 'Subtract the starting time from the ending time.', '{"why":"The length of a stationary period is the difference between the two times.","sol":"Step 1: Starting time = 4 h.\nStep 2: Ending time = 6 h.\nStep 3: Time = 6 - 4 = 2 h.","steps":["Step 1: Starting time = 4 h.","Step 2: Ending time = 6 h.","Step 3: Time = 6 - 4 = 2 h."],"options":[],"conceptId":"math_linear_motion_interpreting_a_horizontal_section_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Interpreting a Horizontal Section of a Distance-Time Graph"}', 1),
  (82, 18, 'A horizontal section runs from 1.5 h to 2.5 h. How long is the stationary period?', 'text', 1, 'Calculate 2.5 - 1.5.', '{"why":"The object remains at the same distance for the one-hour interval.","sol":"Step 1: Starting time = 1.5 h.\nStep 2: Ending time = 2.5 h.\nStep 3: Time = 2.5 - 1.5 = 1 h.","steps":["Step 1: Starting time = 1.5 h.","Step 2: Ending time = 2.5 h.","Step 3: Time = 2.5 - 1.5 = 1 h."],"options":[],"conceptId":"math_linear_motion_interpreting_a_horizontal_section_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Interpreting a Horizontal Section of a Distance-Time Graph"}', 2),
  (83, 18, 'What does a horizontal line on a distance-time graph tell us about speed?', 'text', 1, 'If distance is not changing, what is the rate of change of distance?', '{"why":"No change in distance over time means zero speed.","sol":"Step 1: Speed is change in distance divided by time.\nStep 2: A horizontal line means change in distance is zero.\nStep 3: Therefore, speed is zero.","steps":["Step 1: Speed is change in distance divided by time.","Step 2: A horizontal line means change in distance is zero.","Step 3: Therefore, speed is zero."],"options":[],"conceptId":"math_linear_motion_interpreting_a_horizontal_section_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Interpreting a Horizontal Section of a Distance-Time Graph"}', 3),
  (84, 19, 'A car travels at 70 km/h for 3 hours. Find the distance.', 'text', 1, 'Use d = st.', '{"why":"Distance is found by multiplying speed by time.","sol":"Step 1: Speed = 70 km/h.\nStep 2: Time = 3 h.\nStep 3: Distance = 70 × 3.\nStep 4: Distance = 210 km.","steps":["Step 1: Speed = 70 km/h.","Step 2: Time = 3 h.","Step 3: Distance = 70 × 3.","Step 4: Distance = 210 km."],"options":[],"conceptId":"math_linear_motion_distance_speed_time_relationship","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Distance-Speed-Time Relationship"}', 0),
  (85, 19, 'A cyclist travels at 20 km/h for 5 hours. Find the distance.', 'text', 1, 'Multiply 20 by 5.', '{"why":"The cyclist covers 20 km in each hour for 5 hours.","sol":"Step 1: Speed = 20 km/h.\nStep 2: Time = 5 h.\nStep 3: Distance = 20 × 5.\nStep 4: Distance = 100 km.","steps":["Step 1: Speed = 20 km/h.","Step 2: Time = 5 h.","Step 3: Distance = 20 × 5.","Step 4: Distance = 100 km."],"options":[],"conceptId":"math_linear_motion_distance_speed_time_relationship","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Distance-Speed-Time Relationship"}', 1),
  (86, 19, 'A bus travels at 90 km/h for 2.5 hours. Find the distance.', 'text', 1, 'Use d = st.', '{"why":"Multiplying the rate by the time gives the total distance.","sol":"Step 1: Speed = 90 km/h.\nStep 2: Time = 2.5 h.\nStep 3: Distance = 90 × 2.5.\nStep 4: Distance = 225 km.","steps":["Step 1: Speed = 90 km/h.","Step 2: Time = 2.5 h.","Step 3: Distance = 90 × 2.5.","Step 4: Distance = 225 km."],"options":[],"conceptId":"math_linear_motion_distance_speed_time_relationship","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Distance-Speed-Time Relationship"}', 2),
  (87, 19, 'Which formula gives distance when speed and time are known?', 'text', 1, 'Think about multiplying the rate by the amount of time.', '{"why":"Distance equals speed multiplied by time.","sol":"Step 1: Speed tells us distance covered per unit of time.\nStep 2: Multiplying speed by time gives the total distance.\nStep 3: Therefore, d = st.","steps":["Step 1: Speed tells us distance covered per unit of time.","Step 2: Multiplying speed by time gives the total distance.","Step 3: Therefore, d = st."],"options":[],"conceptId":"math_linear_motion_distance_speed_time_relationship","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Distance-Speed-Time Relationship"}', 3),
  (88, 20, 'A car travels 300 km at 75 km/h. Find the time taken.', 'text', 1, 'Use t = d/s.', '{"why":"Time is found by dividing distance by speed.","sol":"Step 1: Distance = 300 km.\nStep 2: Speed = 75 km/h.\nStep 3: Time = 300 ÷ 75.\nStep 4: Time = 4 hours.","steps":["Step 1: Distance = 300 km.","Step 2: Speed = 75 km/h.","Step 3: Time = 300 ÷ 75.","Step 4: Time = 4 hours."],"options":[],"conceptId":"math_linear_motion_finding_time_from_distance_and_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Time from Distance and Speed"}', 0),
  (89, 20, 'A cyclist travels 120 km at 40 km/h. Find the time.', 'text', 1, 'Divide 120 by 40.', '{"why":"The time is the distance divided by the distance covered per hour.","sol":"Step 1: Distance = 120 km.\nStep 2: Speed = 40 km/h.\nStep 3: Time = 120 ÷ 40.\nStep 4: Time = 3 hours.","steps":["Step 1: Distance = 120 km.","Step 2: Speed = 40 km/h.","Step 3: Time = 120 ÷ 40.","Step 4: Time = 3 hours."],"options":[],"conceptId":"math_linear_motion_finding_time_from_distance_and_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Time from Distance and Speed"}', 1),
  (90, 20, 'A train travels 360 km at 90 km/h. Find the time.', 'text', 1, 'Use time = distance ÷ speed.', '{"why":"Dividing distance by speed gives the time taken.","sol":"Step 1: Distance = 360 km.\nStep 2: Speed = 90 km/h.\nStep 3: Time = 360 ÷ 90.\nStep 4: Time = 4 hours.","steps":["Step 1: Distance = 360 km.","Step 2: Speed = 90 km/h.","Step 3: Time = 360 ÷ 90.","Step 4: Time = 4 hours."],"options":[],"conceptId":"math_linear_motion_finding_time_from_distance_and_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Time from Distance and Speed"}', 2),
  (91, 20, 'Which formula should you use to find time when distance and speed are known?', 'text', 1, 'Rearrange d = st so that time is alone.', '{"why":"Rearranging the distance-speed-time relationship gives time.","sol":"Step 1: Start with d = st.\nStep 2: Divide both sides by s.\nStep 3: This gives t = d/s.","steps":["Step 1: Start with d = st.","Step 2: Divide both sides by s.","Step 3: This gives t = d/s."],"options":[],"conceptId":"math_linear_motion_finding_time_from_distance_and_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Finding Time from Distance and Speed"}', 3),
  (92, 21, 'A car travels 300 km in 5 hours. Find its speed.', 'text', 1, 'Use s = d/t.', '{"why":"Speed is distance divided by time.","sol":"Step 1: Distance = 300 km.\nStep 2: Time = 5 h.\nStep 3: Speed = 300 ÷ 5.\nStep 4: Speed = 60 km/h.","steps":["Step 1: Distance = 300 km.","Step 2: Time = 5 h.","Step 3: Speed = 300 ÷ 5.","Step 4: Speed = 60 km/h."],"options":[],"conceptId":"math_linear_motion_finding_speed_from_distance_and_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Speed from Distance and Time"}', 0),
  (93, 21, 'A runner covers 24 km in 2 hours. Find the speed.', 'text', 1, 'Divide distance by time.', '{"why":"The speed tells how much distance is covered per hour.","sol":"Step 1: Distance = 24 km.\nStep 2: Time = 2 h.\nStep 3: Speed = 24 ÷ 2.\nStep 4: Speed = 12 km/h.","steps":["Step 1: Distance = 24 km.","Step 2: Time = 2 h.","Step 3: Speed = 24 ÷ 2.","Step 4: Speed = 12 km/h."],"options":[],"conceptId":"math_linear_motion_finding_speed_from_distance_and_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Speed from Distance and Time"}', 1),
  (94, 21, 'A bus travels 280 km in 4 hours. Find its speed.', 'text', 1, 'Use speed = distance ÷ time.', '{"why":"Dividing the total distance by total time gives speed.","sol":"Step 1: Distance = 280 km.\nStep 2: Time = 4 h.\nStep 3: Speed = 280 ÷ 4.\nStep 4: Speed = 70 km/h.","steps":["Step 1: Distance = 280 km.","Step 2: Time = 4 h.","Step 3: Speed = 280 ÷ 4.","Step 4: Speed = 70 km/h."],"options":[],"conceptId":"math_linear_motion_finding_speed_from_distance_and_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Speed from Distance and Time"}', 2),
  (95, 21, 'A cyclist travels 90 km in 1.5 hours. Find the speed.', 'text', 1, 'Divide 90 by 1.5.', '{"why":"Speed is the distance travelled per unit of time.","sol":"Step 1: Distance = 90 km.\nStep 2: Time = 1.5 h.\nStep 3: Speed = 90 ÷ 1.5.\nStep 4: Speed = 60 km/h.","steps":["Step 1: Distance = 90 km.","Step 2: Time = 1.5 h.","Step 3: Speed = 90 ÷ 1.5.","Step 4: Speed = 60 km/h."],"options":[],"conceptId":"math_linear_motion_finding_speed_from_distance_and_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Finding Speed from Distance and Time"}', 3),
  (96, 22, 'A car travels at 80 km/h while another car travels at 55 km/h in the same direction. Find their relative speed.', 'text', 1, 'For objects moving in the same direction, subtract the smaller speed from the larger speed.', '{"why":"The faster car gains on the slower car at the difference between their speeds.","sol":"Step 1: Relative speed = 80 − 55\nStep 2: Relative speed = 25 km/h","steps":["Step 1: Relative speed = 80 − 55","Step 2: Relative speed = 25 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 0),
  (97, 22, 'A bus travels at 72 km/h and a truck travels at 60 km/h in the same direction. Find the relative speed.', 'text', 1, 'Subtract the two speeds.', '{"why":"The distance between the two vehicles changes at 12 km/h.","sol":"Step 1: Relative speed = 72 − 60\nStep 2: Relative speed = 12 km/h","steps":["Step 1: Relative speed = 72 − 60","Step 2: Relative speed = 12 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 1),
  (98, 22, 'Two cyclists travel in the same direction at 30 km/h and 22 km/h. Find the relative speed.', 'text', 1, 'Same direction means subtraction.', '{"why":"The faster cyclist gains 8 km on the slower cyclist every hour.","sol":"Step 1: Relative speed = 30 − 22\nStep 2: Relative speed = 8 km/h","steps":["Step 1: Relative speed = 30 − 22","Step 2: Relative speed = 8 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 2),
  (99, 22, 'A car travels at 90 km/h while a bus travels at 60 km/h in the same direction. Find their relative speed.', 'text', 1, 'Subtract the smaller speed from the larger speed.', '{"why":"The car gains on the bus at 30 km/h.","sol":"Step 1: Relative speed = 90 − 60\nStep 2: Relative speed = 30 km/h","steps":["Step 1: Relative speed = 90 − 60","Step 2: Relative speed = 30 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 3),
  (100, 22, 'Two cyclists travel in the same direction at 28 km/h and 20 km/h. Find their relative speed.', 'text', 1, 'Same direction means subtract.', '{"why":"The faster cyclist reduces the separation by 8 km every hour.","sol":"Step 1: Relative speed = 28 − 20\nStep 2: Relative speed = 8 km/h","steps":["Step 1: Relative speed = 28 − 20","Step 2: Relative speed = 8 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 4),
  (101, 22, 'A truck moves at 55 km/h and a car moves at 75 km/h in the same direction. Find the relative speed.', 'text', 1, 'Subtract 55 from 75.', '{"why":"The car gains on the truck at 20 km/h.","sol":"Step 1: Relative speed = 75 − 55\nStep 2: Relative speed = 20 km/h","steps":["Step 1: Relative speed = 75 − 55","Step 2: Relative speed = 20 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 5),
  (102, 23, 'Two cars travel towards each other at 70 km/h and 50 km/h. Find their relative speed.', 'text', 1, 'Opposite directions mean the speeds are added.', '{"why":"Both cars reduce the distance between them, so their speeds add.","sol":"Step 1: Relative speed = 70 + 50\nStep 2: Relative speed = 120 km/h","steps":["Step 1: Relative speed = 70 + 50","Step 2: Relative speed = 120 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 0),
  (103, 23, 'Two cyclists move towards each other at 25 km/h and 15 km/h. Find their relative speed.', 'text', 1, 'Add the two speeds.', '{"why":"The cyclists are approaching each other from opposite directions.","sol":"Step 1: Relative speed = 25 + 15\nStep 2: Relative speed = 40 km/h","steps":["Step 1: Relative speed = 25 + 15","Step 2: Relative speed = 40 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 1),
  (104, 23, 'A train travels east at 90 km/h while another train travels west at 80 km/h. Find their relative speed.', 'text', 1, 'They are moving towards each other.', '{"why":"Their speeds combine because the trains are moving towards each other.","sol":"Step 1: Relative speed = 90 + 80\nStep 2: Relative speed = 170 km/h","steps":["Step 1: Relative speed = 90 + 80","Step 2: Relative speed = 170 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 2),
  (105, 23, 'Two cars move towards each other at 70 km/h and 50 km/h. Find their relative speed.', 'text', 1, 'Opposite directions mean add the speeds.', '{"why":"Both cars reduce the distance between them.","sol":"Step 1: Relative speed = 70 + 50\nStep 2: Relative speed = 120 km/h","steps":["Step 1: Relative speed = 70 + 50","Step 2: Relative speed = 120 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 3),
  (106, 23, 'Two cyclists approach each other at 20 km/h and 30 km/h. Find their relative speed.', 'text', 1, 'They are moving towards each other.', '{"why":"Their speeds combine because they move in opposite directions.","sol":"Step 1: Relative speed = 20 + 30\nStep 2: Relative speed = 50 km/h","steps":["Step 1: Relative speed = 20 + 30","Step 2: Relative speed = 50 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 4),
  (107, 23, 'A bus and a car approach each other at 45 km/h and 75 km/h. Find their relative speed.', 'text', 1, 'Add the two speeds.', '{"why":"The distance between them decreases at the sum of their speeds.","sol":"Step 1: Relative speed = 45 + 75\nStep 2: Relative speed = 120 km/h","steps":["Step 1: Relative speed = 45 + 75","Step 2: Relative speed = 120 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 5),
  (108, 24, 'Two cars travel in the same direction at 90 km/h and 70 km/h. How much does the distance between them change in 3 hours?', 'text', 1, 'First find relative speed, then multiply by time.', '{"why":"The faster car gains 20 km every hour, so in 3 hours it gains 60 km.","sol":"Step 1: Relative speed = 90 − 70 = 20 km/h\nStep 2: Change in distance = 20 × 3\nStep 3: Change in distance = 60 km","steps":["Step 1: Relative speed = 90 − 70 = 20 km/h","Step 2: Change in distance = 20 × 3","Step 3: Change in distance = 60 km"],"options":[],"conceptId":"math_linear_motion_finding_distance_between_moving_objects","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Distance Between Moving Objects"}', 0),
  (109, 24, 'Two vehicles move towards each other at 60 km/h and 40 km/h. How much distance do they close in 2 hours?', 'text', 1, 'Find the relative speed first.', '{"why":"The vehicles approach each other at a combined rate of 100 km/h.","sol":"Step 1: Relative speed = 60 + 40 = 100 km/h\nStep 2: Change in distance = 100 × 2\nStep 3: Change in distance = 200 km","steps":["Step 1: Relative speed = 60 + 40 = 100 km/h","Step 2: Change in distance = 100 × 2","Step 3: Change in distance = 200 km"],"options":[],"conceptId":"math_linear_motion_finding_distance_between_moving_objects","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Distance Between Moving Objects"}', 1),
  (110, 24, 'A bus travels at 75 km/h and a car ahead travels at 55 km/h. How much distance does the bus gain in 5 hours?', 'text', 1, 'Subtract their speeds before multiplying by time.', '{"why":"The bus gains 20 km every hour on the car.","sol":"Step 1: Relative speed = 75 − 55 = 20 km/h\nStep 2: Distance gained = 20 × 5\nStep 3: Distance gained = 100 km","steps":["Step 1: Relative speed = 75 − 55 = 20 km/h","Step 2: Distance gained = 20 × 5","Step 3: Distance gained = 100 km"],"options":[],"conceptId":"math_linear_motion_finding_distance_between_moving_objects","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Distance Between Moving Objects"}', 2),
  (111, 25, 'Two cars move in the same direction at 90 km/h and 60 km/h. How much does the faster car gain in 4 hours?', 'text', 1, 'First find the relative speed.', '{"why":"The faster car gains 30 km every hour.","sol":"Step 1: Relative speed = 90 − 60 = 30 km/h\nStep 2: Gain = 30 × 4\nStep 3: Gain = 120 km","steps":["Step 1: Relative speed = 90 − 60 = 30 km/h","Step 2: Gain = 30 × 4","Step 3: Gain = 120 km"],"options":[],"conceptId":"math_linear_motion_finding_separation_using_relative_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Separation Using Relative Speed"}', 0),
  (112, 25, 'Two vehicles approach each other at 50 km/h and 40 km/h. How much does their separation decrease in 3 hours?', 'text', 1, 'Add their speeds first.', '{"why":"Their combined motion closes the gap at 90 km/h.","sol":"Step 1: Relative speed = 50 + 40 = 90 km/h\nStep 2: Decrease = 90 × 3\nStep 3: Decrease = 270 km","steps":["Step 1: Relative speed = 50 + 40 = 90 km/h","Step 2: Decrease = 90 × 3","Step 3: Decrease = 270 km"],"options":[],"conceptId":"math_linear_motion_finding_separation_using_relative_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Separation Using Relative Speed"}', 1),
  (113, 25, 'A bus travels at 70 km/h while a car travels at 100 km/h in the same direction. Find the distance gained by the car in 5 hours.', 'text', 1, 'Relative speed = 100 − 70.', '{"why":"The car gains 30 km on the bus every hour.","sol":"Step 1: Relative speed = 100 − 70 = 30 km/h\nStep 2: Gain = 30 × 5\nStep 3: Gain = 150 km","steps":["Step 1: Relative speed = 100 − 70 = 30 km/h","Step 2: Gain = 30 × 5","Step 3: Gain = 150 km"],"options":[],"conceptId":"math_linear_motion_finding_separation_using_relative_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Separation Using Relative Speed"}', 2),
  (114, 26, 'A car travels at 50 km/h for 4 hours. Find the distance travelled.', 'text', 1, 'Use d = st.', '{"why":"Distance is obtained by multiplying speed by time.","sol":"Step 1: d = 50 × 4\nStep 2: d = 200 km","steps":["Step 1: d = 50 × 4","Step 2: d = 200 km"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 0),
  (115, 26, 'A cyclist travels at 24 km/h for 2.5 hours. Find the distance travelled.', 'text', 1, 'Multiply 24 by 2.5.', '{"why":"The cyclist covers 24 km in each hour.","sol":"Step 1: d = 24 × 2.5\nStep 2: d = 60 km","steps":["Step 1: d = 24 × 2.5","Step 2: d = 60 km"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 1),
  (116, 26, 'A train travels at 90 km/h for 2 hours. Find the distance travelled.', 'text', 1, 'Use distance = speed × time.', '{"why":"The train covers 90 km each hour for 2 hours.","sol":"Step 1: d = 90 × 2\nStep 2: d = 180 km","steps":["Step 1: d = 90 × 2","Step 2: d = 180 km"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 2),
  (117, 26, 'A vehicle travels at 70 km/h for 3 hours. Find the distance.', 'text', 1, 'Distance = speed × time.', '{"why":"The vehicle covers 70 km each hour for 3 hours.","sol":"Step 1: d = st\nStep 2: d = 70 × 3\nStep 3: d = 210 km","steps":["Step 1: d = st","Step 2: d = 70 × 3","Step 3: d = 210 km"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 3),
  (118, 26, 'A cyclist covers 120 km in 4 hours. Find the speed.', 'text', 1, 'Speed = distance ÷ time.', '{"why":"Speed tells us how much distance is covered in one hour.","sol":"Step 1: s = d/t\nStep 2: s = 120/4\nStep 3: s = 30 km/h","steps":["Step 1: s = d/t","Step 2: s = 120/4","Step 3: s = 30 km/h"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 4),
  (119, 26, 'A bus travels at 60 km/h and covers 300 km. Find the time.', 'text', 1, 'Time = distance ÷ speed.', '{"why":"Dividing total distance by the speed gives the travel time.","sol":"Step 1: t = d/s\nStep 2: t = 300/60\nStep 3: t = 5 hours","steps":["Step 1: t = d/s","Step 2: t = 300/60","Step 3: t = 5 hours"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 5),
  (120, 27, 'A car travels 300 km at 75 km/h. Find the time taken.', 'text', 1, 'Use t = d/s.', '{"why":"Time is found by dividing distance by speed.","sol":"Step 1: t = 300 / 75\nStep 2: t = 4 hours","steps":["Step 1: t = 300 / 75","Step 2: t = 4 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 0),
  (121, 27, 'A bus travels 180 km at 60 km/h. Find the time taken.', 'text', 1, 'Divide the distance by the speed.', '{"why":"At 60 km/h, the bus needs 3 hours to cover 180 km.","sol":"Step 1: t = 180 / 60\nStep 2: t = 3 hours","steps":["Step 1: t = 180 / 60","Step 2: t = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 1),
  (122, 27, 'A cyclist travels 100 km at 20 km/h. Find the time taken.', 'text', 1, 'Use t = d/s.', '{"why":"The cyclist covers 20 km each hour.","sol":"Step 1: t = 100 / 20\nStep 2: t = 5 hours","steps":["Step 1: t = 100 / 20","Step 2: t = 5 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 2),
  (123, 27, 'A car travels 360 km at 90 km/h. Find the time taken.', 'text', 1, 'Use t = d/s.', '{"why":"At 90 km/h, the car covers 90 km in each hour.","sol":"Step 1: t = 360/90\nStep 2: t = 4 hours","steps":["Step 1: t = 360/90","Step 2: t = 4 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 3),
  (124, 27, 'A bus travels 420 km at 70 km/h. Find the travel time.', 'text', 1, 'Divide distance by speed.', '{"why":"Six groups of 70 km make 420 km.","sol":"Step 1: t = 420/70\nStep 2: t = 6 hours","steps":["Step 1: t = 420/70","Step 2: t = 6 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 4),
  (125, 27, 'A cyclist travels 150 km at 25 km/h. Find the time.', 'text', 1, 'Use t = 150/25.', '{"why":"The cyclist needs six hours to cover 150 km at 25 km/h.","sol":"Step 1: t = 150/25\nStep 2: t = 6 hours","steps":["Step 1: t = 150/25","Step 2: t = 6 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 5),
  (126, 28, 'A car travels 360 km in 6 hours. Find its speed.', 'text', 1, 'Use s = d/t.', '{"why":"Speed is distance divided by time.","sol":"Step 1: s = 360 / 6\nStep 2: s = 60 km/h","steps":["Step 1: s = 360 / 6","Step 2: s = 60 km/h"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_speed_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Speed in a Motion Problem"}', 0),
  (127, 28, 'A bus covers 240 km in 4 hours. Find its speed.', 'text', 1, 'Divide distance by time.', '{"why":"The bus covers 60 km during each hour.","sol":"Step 1: s = 240 / 4\nStep 2: s = 60 km/h","steps":["Step 1: s = 240 / 4","Step 2: s = 60 km/h"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_speed_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Speed in a Motion Problem"}', 1),
  (128, 28, 'A cyclist covers 75 km in 3 hours. Find the speed.', 'text', 1, 'Use s = d/t.', '{"why":"The cyclist covers 25 km in each hour.","sol":"Step 1: s = 75 / 3\nStep 2: s = 25 km/h","steps":["Step 1: s = 75 / 3","Step 2: s = 25 km/h"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_speed_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Speed in a Motion Problem"}', 2),
  (129, 29, 'A car travels at 80 km/h for 6 hours. Find the distance.', 'text', 1, 'Multiply speed by time.', '{"why":"The car covers 80 km each hour for 6 hours.","sol":"Step 1: d = 80 × 6\nStep 2: d = 480 km","steps":["Step 1: d = 80 × 6","Step 2: d = 480 km"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance in a Motion Problem"}', 0),
  (130, 29, 'A cyclist travels at 30 km/h for 2.5 hours. Find the distance.', 'text', 1, 'Use d = st.', '{"why":"The cyclist covers 30 km per hour, so 2.5 hours gives 75 km.","sol":"Step 1: d = 30 × 2.5\nStep 2: d = 75 km","steps":["Step 1: d = 30 × 2.5","Step 2: d = 75 km"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance in a Motion Problem"}', 1),
  (131, 29, 'A train travels at 90 km/h for 1.5 hours. Find the distance.', 'text', 1, 'Multiply 90 by 1.5.', '{"why":"The train covers 90 km in the first hour and another 45 km in half an hour.","sol":"Step 1: d = 90 × 1.5\nStep 2: d = 135 km","steps":["Step 1: d = 90 × 1.5","Step 2: d = 135 km"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance in a Motion Problem"}', 2),
  (132, 30, 'Two cars are 200 km apart and travel towards each other at 60 km/h and 40 km/h. Find their meeting time.', 'text', 1, 'Add their speeds first.', '{"why":"Their combined approach speed is 100 km/h.","sol":"Step 1: Relative speed = 60 + 40 = 100 km/h\nStep 2: Time = 200 / 100\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 60 + 40 = 100 km/h","Step 2: Time = 200 / 100","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time"}', 0),
  (133, 30, 'Two cyclists are 150 km apart and move towards each other at 40 km/h and 35 km/h. Find when they meet.', 'text', 1, 'Use time = distance ÷ relative speed.', '{"why":"Together they close 75 km of separation each hour.","sol":"Step 1: Relative speed = 40 + 35 = 75 km/h\nStep 2: Time = 150 / 75\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 40 + 35 = 75 km/h","Step 2: Time = 150 / 75","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time"}', 1),
  (134, 30, 'Two buses are 300 km apart and travel towards each other at 70 km/h and 80 km/h. Find the meeting time.', 'text', 1, 'Add 70 and 80.', '{"why":"Their combined speed towards each other is 150 km/h.","sol":"Step 1: Relative speed = 70 + 80 = 150 km/h\nStep 2: Time = 300 / 150\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 70 + 80 = 150 km/h","Step 2: Time = 300 / 150","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time"}', 2),
  (135, 31, 'Two cars are 180 km apart and travel towards each other at 60 km/h and 30 km/h. Find the distance travelled by the 60 km/h car before they meet.', 'text', 1, 'First find the meeting time.', '{"why":"The faster car travels at 60 km/h for the 2 hours before meeting.","sol":"Step 1: Relative speed = 60 + 30 = 90 km/h\nStep 2: Meeting time = 180 / 90 = 2 h\nStep 3: Distance = 60 × 2\nStep 4: Distance = 120 km","steps":["Step 1: Relative speed = 60 + 30 = 90 km/h","Step 2: Meeting time = 180 / 90 = 2 h","Step 3: Distance = 60 × 2","Step 4: Distance = 120 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 0),
  (136, 31, 'Two cyclists are 120 km apart and travel towards each other at 40 km/h and 20 km/h. Find the distance travelled by the slower cyclist before meeting.', 'text', 1, 'Find the meeting time, then use d = st.', '{"why":"The slower cyclist travels for the same 2 hours at 20 km/h.","sol":"Step 1: Relative speed = 40 + 20 = 60 km/h\nStep 2: Meeting time = 120 / 60 = 2 h\nStep 3: Distance = 20 × 2\nStep 4: Distance = 40 km","steps":["Step 1: Relative speed = 40 + 20 = 60 km/h","Step 2: Meeting time = 120 / 60 = 2 h","Step 3: Distance = 20 × 2","Step 4: Distance = 40 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 1),
  (137, 31, 'Two buses are 300 km apart and travel towards each other at 75 km/h and 50 km/h. Find the distance travelled by the 75 km/h bus before they meet.', 'text', 1, 'Find time first.', '{"why":"The faster bus travels 75 km/h for 2.4 hours.","sol":"Step 1: Relative speed = 75 + 50 = 125 km/h\nStep 2: Meeting time = 300 / 125 = 2.4 h\nStep 3: Distance = 75 × 2.4\nStep 4: Distance = 180 km","steps":["Step 1: Relative speed = 75 + 50 = 125 km/h","Step 2: Meeting time = 300 / 125 = 2.4 h","Step 3: Distance = 75 × 2.4","Step 4: Distance = 180 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 2),
  (138, 31, 'Two cars meet after 3 hours. The first car travels at 50 km/h. How far has it travelled to the meeting point?', 'text', 1, 'Use distance = speed × time.', '{"why":"The first car travels 50 km every hour for 3 hours.","sol":"Step 1: d = 50 × 3\nStep 2: d = 150 km","steps":["Step 1: d = 50 × 3","Step 2: d = 150 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 3),
  (139, 31, 'Two cyclists meet after 2 hours. The first cyclist travels at 35 km/h. Find the distance from the first cyclist''s starting point to the meeting point.', 'text', 1, 'Multiply 35 by 2.', '{"why":"The cyclist covers 35 km each hour for two hours.","sol":"Step 1: d = 35 × 2\nStep 2: d = 70 km","steps":["Step 1: d = 35 × 2","Step 2: d = 70 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 4),
  (140, 31, 'Two buses meet after 4 hours. The first bus travels at 60 km/h. Find its distance to the meeting point.', 'text', 1, 'Use d = st.', '{"why":"The first bus covers 240 km before reaching the meeting point.","sol":"Step 1: d = 60 × 4\nStep 2: d = 240 km","steps":["Step 1: d = 60 × 4","Step 2: d = 240 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 5),
  (141, 32, 'A car travelling at 90 km/h is 30 km behind a bus travelling at 60 km/h. Find the time needed to catch the bus.', 'text', 1, 'Subtract the speeds, then divide the gap by the relative speed.', '{"why":"The car closes the 30 km gap at 30 km/h.","sol":"Step 1: Relative speed = 90 − 60 = 30 km/h\nStep 2: Time = 30 / 30\nStep 3: Time = 1 hour","steps":["Step 1: Relative speed = 90 − 60 = 30 km/h","Step 2: Time = 30 / 30","Step 3: Time = 1 hour"],"options":[],"conceptId":"math_linear_motion_overtaking_a_slower_object","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Overtaking a Slower Object"}', 0),
  (142, 32, 'A cyclist travelling at 25 km/h is 20 km behind another cyclist travelling at 15 km/h. Find the catching time.', 'text', 1, 'Relative speed = 25 − 15.', '{"why":"The faster cyclist gains 10 km every hour.","sol":"Step 1: Relative speed = 25 − 15 = 10 km/h\nStep 2: Time = 20 / 10\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 25 − 15 = 10 km/h","Step 2: Time = 20 / 10","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_overtaking_a_slower_object","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Overtaking a Slower Object"}', 1),
  (143, 32, 'A motorcycle travelling at 100 km/h is 45 km behind a car travelling at 85 km/h. Find the time needed to catch it.', 'text', 1, 'Find the relative speed first.', '{"why":"The motorcycle closes the gap at 15 km/h.","sol":"Step 1: Relative speed = 100 − 85 = 15 km/h\nStep 2: Time = 45 / 15\nStep 3: Time = 3 hours","steps":["Step 1: Relative speed = 100 − 85 = 15 km/h","Step 2: Time = 45 / 15","Step 3: Time = 3 hours"],"options":[],"conceptId":"math_linear_motion_overtaking_a_slower_object","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Overtaking a Slower Object"}', 2),
  (144, 33, 'Two cars are 240 km apart and travel towards each other at 70 km/h and 50 km/h. Find the meeting time.', 'text', 1, 'Relative speed = 70 + 50.', '{"why":"Together the cars close 120 km of separation every hour.","sol":"Step 1: Relative speed = 70 + 50 = 120 km/h\nStep 2: Time = 240/120\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 70 + 50 = 120 km/h","Step 2: Time = 240/120","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time_from_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time from Opposite Directions"}', 0),
  (145, 33, 'Two cyclists are 150 km apart and travel towards each other at 25 km/h and 50 km/h. Find when they meet.', 'text', 1, 'Add the speeds.', '{"why":"Their combined closing speed is 75 km/h.","sol":"Step 1: Relative speed = 25 + 50 = 75 km/h\nStep 2: Time = 150/75\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 25 + 50 = 75 km/h","Step 2: Time = 150/75","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time_from_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time from Opposite Directions"}', 1),
  (146, 33, 'Two buses are 360 km apart and travel towards each other at 80 km/h and 40 km/h. Find the meeting time.', 'text', 1, 'Use time = separation ÷ relative speed.', '{"why":"At a combined speed of 120 km/h, 360 km is covered in 3 hours.","sol":"Step 1: Relative speed = 80 + 40 = 120 km/h\nStep 2: Time = 360/120\nStep 3: Time = 3 hours","steps":["Step 1: Relative speed = 80 + 40 = 120 km/h","Step 2: Time = 360/120","Step 3: Time = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time_from_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time from Opposite Directions"}', 2),
  (147, 34, 'A car is 60 km behind a bus. The car travels at 90 km/h and the bus at 60 km/h. Find the overtaking time.', 'text', 1, 'Relative speed = 90 − 60.', '{"why":"The car closes the 60 km gap at 30 km/h.","sol":"Step 1: Relative speed = 90 − 60 = 30 km/h\nStep 2: Time = 60/30\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 90 − 60 = 30 km/h","Step 2: Time = 60/30","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_overtaking_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Overtaking Time"}', 0),
  (148, 34, 'A cyclist is 20 km behind another cyclist. Their speeds are 30 km/h and 25 km/h. Find the time to catch up.', 'text', 1, 'Subtract the speeds first.', '{"why":"The faster cyclist gains 5 km every hour.","sol":"Step 1: Relative speed = 30 − 25 = 5 km/h\nStep 2: Time = 20/5\nStep 3: Time = 4 hours","steps":["Step 1: Relative speed = 30 − 25 = 5 km/h","Step 2: Time = 20/5","Step 3: Time = 4 hours"],"options":[],"conceptId":"math_linear_motion_finding_overtaking_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Overtaking Time"}', 1),
  (149, 34, 'A car is 45 km behind a truck. The car travels at 75 km/h and the truck at 60 km/h. Find the overtaking time.', 'text', 1, 'Use time = separation ÷ relative speed.', '{"why":"The car closes the 45 km gap at 15 km/h.","sol":"Step 1: Relative speed = 75 − 60 = 15 km/h\nStep 2: Time = 45/15\nStep 3: Time = 3 hours","steps":["Step 1: Relative speed = 75 − 60 = 15 km/h","Step 2: Time = 45/15","Step 3: Time = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_overtaking_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Overtaking Time"}', 2),
  (150, 35, 'Convert 5 km to metres.', 'text', 1, 'Multiply by 1000.', '{"why":"Each kilometre contains 1000 metres.","sol":"Step 1: 5 × 1000 = 5000\nStep 2: Therefore, 5 km = 5000 m","steps":["Step 1: 5 × 1000 = 5000","Step 2: Therefore, 5 km = 5000 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 0),
  (151, 35, 'Convert 2.4 km to metres.', 'text', 1, 'Multiply 2.4 by 1000.', '{"why":"Kilometres are changed to metres by multiplying by 1000.","sol":"Step 1: 2.4 × 1000 = 2400\nStep 2: Therefore, 2.4 km = 2400 m","steps":["Step 1: 2.4 × 1000 = 2400","Step 2: Therefore, 2.4 km = 2400 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 1),
  (152, 35, 'Convert 0.35 km to metres.', 'text', 1, 'Multiply by 1000.', '{"why":"0.35 of a kilometre is 350 metres.","sol":"Step 1: 0.35 × 1000 = 350\nStep 2: Therefore, 0.35 km = 350 m","steps":["Step 1: 0.35 × 1000 = 350","Step 2: Therefore, 0.35 km = 350 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 2),
  (153, 35, 'Convert 5 km to metres.', 'text', 1, 'Multiply by 1000.', '{"why":"One kilometre contains 1000 metres.","sol":"Step 1: 5 × 1000\nStep 2: 5000 m","steps":["Step 1: 5 × 1000","Step 2: 5000 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 3),
  (154, 35, 'Convert 2.4 km to metres.', 'text', 1, 'Multiply 2.4 by 1000.', '{"why":"Kilometres are converted to metres by multiplying by 1000.","sol":"Step 1: 2.4 × 1000\nStep 2: 2400 m","steps":["Step 1: 2.4 × 1000","Step 2: 2400 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 4),
  (155, 35, 'Convert 0.35 km to metres.', 'text', 1, 'Multiply by 1000.', '{"why":"0.35 kilometres contains 350 metres.","sol":"Step 1: 0.35 × 1000\nStep 2: 350 m","steps":["Step 1: 0.35 × 1000","Step 2: 350 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 5),
  (156, 36, 'Convert 6 minutes to seconds.', 'text', 1, '1 minute = 60 seconds.', '{"why":"Each minute contains 60 seconds.","sol":"Step 1: 6 × 60 = 360\nStep 2: Therefore, 6 minutes = 360 seconds","steps":["Step 1: 6 × 60 = 360","Step 2: Therefore, 6 minutes = 360 seconds"],"options":[],"conceptId":"math_linear_motion_converting_minutes_and_seconds","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting Minutes and Seconds"}', 0),
  (157, 36, 'Convert 4.5 minutes to seconds.', 'text', 1, 'Multiply 4.5 by 60.', '{"why":"The conversion factor from minutes to seconds is 60.","sol":"Step 1: 4.5 × 60 = 270\nStep 2: Therefore, 4.5 minutes = 270 seconds","steps":["Step 1: 4.5 × 60 = 270","Step 2: Therefore, 4.5 minutes = 270 seconds"],"options":[],"conceptId":"math_linear_motion_converting_minutes_and_seconds","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting Minutes and Seconds"}', 1),
  (158, 36, 'Convert 3 hours to minutes.', 'text', 1, '1 hour = 60 minutes.', '{"why":"Each hour contains 60 minutes.","sol":"Step 1: 3 × 60 = 180\nStep 2: Therefore, 3 hours = 180 minutes","steps":["Step 1: 3 × 60 = 180","Step 2: Therefore, 3 hours = 180 minutes"],"options":[],"conceptId":"math_linear_motion_converting_minutes_and_seconds","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting Minutes and Seconds"}', 2),
  (159, 37, 'Convert 18 km/h to m/s.', 'text', 1, 'Multiply by 5/18.', '{"why":"The conversion factor from km/h to m/s is 5/18.","sol":"Step 1: 18 × 5/18\nStep 2: 18 ÷ 18 = 1\nStep 3: 1 × 5 = 5 m/s","steps":["Step 1: 18 × 5/18","Step 2: 18 ÷ 18 = 1","Step 3: 1 × 5 = 5 m/s"],"options":[],"conceptId":"math_linear_motion_converting_speed_between_km_h_and_m_s","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting Speed Between km/h and m/s"}', 0),
  (160, 37, 'Convert 90 km/h to m/s.', 'text', 1, 'Use 5/18.', '{"why":"90 km/h is equivalent to 25 metres per second.","sol":"Step 1: 90 × 5/18\nStep 2: 90 ÷ 18 = 5\nStep 3: 5 × 5 = 25 m/s","steps":["Step 1: 90 × 5/18","Step 2: 90 ÷ 18 = 5","Step 3: 5 × 5 = 25 m/s"],"options":[],"conceptId":"math_linear_motion_converting_speed_between_km_h_and_m_s","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting Speed Between km/h and m/s"}', 1),
  (161, 37, 'Convert 108 km/h to m/s.', 'text', 1, 'Multiply 108 by 5/18.', '{"why":"The unit conversion gives 30 metres per second.","sol":"Step 1: 108 × 5/18\nStep 2: 108 ÷ 18 = 6\nStep 3: 6 × 5 = 30 m/s","steps":["Step 1: 108 × 5/18","Step 2: 108 ÷ 18 = 6","Step 3: 6 × 5 = 30 m/s"],"options":[],"conceptId":"math_linear_motion_converting_speed_between_km_h_and_m_s","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting Speed Between km/h and m/s"}', 2),
  (162, 38, 'Convert 5 m/s to km/h.', 'text', 1, 'Multiply by 18/5.', '{"why":"The conversion factor from m/s to km/h is 18/5.","sol":"Step 1: 5 × 18/5\nStep 2: 5 ÷ 5 = 1\nStep 3: 1 × 18 = 18 km/h","steps":["Step 1: 5 × 18/5","Step 2: 5 ÷ 5 = 1","Step 3: 1 × 18 = 18 km/h"],"options":[],"conceptId":"math_linear_motion_converting_m_s_to_km_h","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting m/s to km/h"}', 0),
  (163, 38, 'Convert 15 m/s to km/h.', 'text', 1, 'Use 18/5.', '{"why":"15 metres per second is equivalent to 54 kilometres per hour.","sol":"Step 1: 15 × 18/5\nStep 2: 15 ÷ 5 = 3\nStep 3: 3 × 18 = 54 km/h","steps":["Step 1: 15 × 18/5","Step 2: 15 ÷ 5 = 3","Step 3: 3 × 18 = 54 km/h"],"options":[],"conceptId":"math_linear_motion_converting_m_s_to_km_h","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting m/s to km/h"}', 1),
  (164, 38, 'Convert 30 m/s to km/h.', 'text', 1, 'Multiply 30 by 18/5.', '{"why":"The converted speed is 108 kilometres per hour.","sol":"Step 1: 30 × 18/5\nStep 2: 30 ÷ 5 = 6\nStep 3: 6 × 18 = 108 km/h","steps":["Step 1: 30 × 18/5","Step 2: 30 ÷ 5 = 6","Step 3: 6 × 18 = 108 km/h"],"options":[],"conceptId":"math_linear_motion_converting_m_s_to_km_h","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting m/s to km/h"}', 2),
  (165, 39, 'Convert 20 minutes to hours.', 'text', 1, 'Divide 20 by 60.', '{"why":"An hour contains 60 minutes, so minutes are divided by 60.","sol":"Step 1: 20/60 = 1/3\nStep 2: 1/3 hour ≈ 0.333 hour","steps":["Step 1: 20/60 = 1/3","Step 2: 1/3 hour ≈ 0.333 hour"],"options":[],"conceptId":"math_linear_motion_converting_minutes_to_hours","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting Minutes to Hours"}', 0),
  (166, 39, 'Convert 30 minutes to hours.', 'text', 1, 'Divide by 60.', '{"why":"Thirty minutes is half of one hour.","sol":"Step 1: 30/60\nStep 2: 0.5 hours","steps":["Step 1: 30/60","Step 2: 0.5 hours"],"options":[],"conceptId":"math_linear_motion_converting_minutes_to_hours","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting Minutes to Hours"}', 1),
  (167, 39, 'Convert 120 minutes to hours.', 'text', 1, 'Divide 120 by 60.', '{"why":"Two groups of 60 minutes make 120 minutes.","sol":"Step 1: 120/60\nStep 2: 2 hours","steps":["Step 1: 120/60","Step 2: 2 hours"],"options":[],"conceptId":"math_linear_motion_converting_minutes_to_hours","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting Minutes to Hours"}', 2),
  (168, 40, 'Convert 10 m/s to km/h.', 'text', 1, 'Multiply by 3.6.', '{"why":"Every 1 m/s is equivalent to 3.6 km/h.","sol":"Step 1: 10 × 3.6\nStep 2: 36 km/h","steps":["Step 1: 10 × 3.6","Step 2: 36 km/h"],"options":[],"conceptId":"math_linear_motion_converting_metres_per_second_to_kilometres_per_hour","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting Metres per Second to Kilometres per Hour"}', 0),
  (169, 40, 'Convert 15 m/s to km/h.', 'text', 1, 'Use km/h = m/s × 3.6.', '{"why":"Multiplying by 3.6 converts the speed into kilometres per hour.","sol":"Step 1: 15 × 3.6\nStep 2: 54 km/h","steps":["Step 1: 15 × 3.6","Step 2: 54 km/h"],"options":[],"conceptId":"math_linear_motion_converting_metres_per_second_to_kilometres_per_hour","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting Metres per Second to Kilometres per Hour"}', 1),
  (170, 40, 'Convert 25 m/s to km/h.', 'text', 1, 'Multiply 25 by 3.6.', '{"why":"25 m/s is equivalent to 90 km/h.","sol":"Step 1: 25 × 3.6\nStep 2: 90 km/h","steps":["Step 1: 25 × 3.6","Step 2: 90 km/h"],"options":[],"conceptId":"math_linear_motion_converting_metres_per_second_to_kilometres_per_hour","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting Metres per Second to Kilometres per Hour"}', 2),
  (171, 41, 'A car travels at 60 km/h for 2 hours and then at 40 km/h for 1 hour. Find the distance travelled in each stage.', 'text', 1, 'Calculate each stage separately.', '{"why":"Each stage has its own speed and time.","sol":"Step 1: Stage 1: 60 × 2 = 120 km\nStep 2: Stage 2: 40 × 1 = 40 km","steps":["Step 1: Stage 1: 60 × 2 = 120 km","Step 2: Stage 2: 40 × 1 = 40 km"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 0),
  (172, 41, 'A cyclist travels at 25 km/h for 2 hours and then at 20 km/h for 3 hours. Find the distance in each stage.', 'text', 1, 'Use d = st for each stage.', '{"why":"The distance for each stage is calculated from that stage''s speed and time.","sol":"Step 1: Stage 1: 25 × 2 = 50 km\nStep 2: Stage 2: 20 × 3 = 60 km","steps":["Step 1: Stage 1: 25 × 2 = 50 km","Step 2: Stage 2: 20 × 3 = 60 km"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 1),
  (173, 41, 'A bus travels at 70 km/h for 1.5 hours and then at 50 km/h for 2 hours. Find the distance in each stage.', 'text', 1, 'Treat the two stages separately.', '{"why":"The speed changes after the first stage, so each stage must be calculated separately.","sol":"Step 1: Stage 1: 70 × 1.5 = 105 km\nStep 2: Stage 2: 50 × 2 = 100 km","steps":["Step 1: Stage 1: 70 × 1.5 = 105 km","Step 2: Stage 2: 50 × 2 = 100 km"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 2),
  (174, 41, 'A vehicle travels 120 km and then 80 km. Find the total distance.', 'text', 1, 'Add the distances of the two stages.', '{"why":"Total distance is the sum of the distances travelled in all stages.","sol":"Step 1: Stage 1 = 120 km\nStep 2: Stage 2 = 80 km\nStep 3: Total = 120 + 80\nStep 4: Total = 200 km","steps":["Step 1: Stage 1 = 120 km","Step 2: Stage 2 = 80 km","Step 3: Total = 120 + 80","Step 4: Total = 200 km"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 3),
  (175, 41, 'A journey takes 3 hours in the first stage and 2 hours in the second stage. Find the total time.', 'text', 1, 'Add the stage times.', '{"why":"The journey takes both stages consecutively.","sol":"Step 1: Stage 1 = 3 h\nStep 2: Stage 2 = 2 h\nStep 3: Total = 3 + 2\nStep 4: Total = 5 h","steps":["Step 1: Stage 1 = 3 h","Step 2: Stage 2 = 2 h","Step 3: Total = 3 + 2","Step 4: Total = 5 h"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 4),
  (176, 41, 'A cyclist travels 50 km and then another 25 km. Find the total distance.', 'text', 1, 'Add the two distances.', '{"why":"Both stages contribute to the total distance.","sol":"Step 1: Total distance = 50 + 25\nStep 2: Total distance = 75 km","steps":["Step 1: Total distance = 50 + 25","Step 2: Total distance = 75 km"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 5),
  (177, 42, 'A car travels at 50 km/h for 2 hours and then at 70 km/h for 1 hour. Find the total distance.', 'text', 1, 'Find each stage distance, then add them.', '{"why":"The total journey distance is the sum of the distances in both stages.","sol":"Step 1: Stage 1 = 50 × 2 = 100 km\nStep 2: Stage 2 = 70 × 1 = 70 km\nStep 3: Total distance = 100 + 70 = 170 km","steps":["Step 1: Stage 1 = 50 × 2 = 100 km","Step 2: Stage 2 = 70 × 1 = 70 km","Step 3: Total distance = 100 + 70 = 170 km"],"options":[],"conceptId":"math_linear_motion_finding_total_distance_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Total Distance in a Multi-Stage Journey"}', 0),
  (178, 42, 'A cyclist travels at 30 km/h for 2 hours and then at 20 km/h for 3 hours. Find the total distance.', 'text', 1, 'Calculate both stage distances.', '{"why":"Both stage distances are added to obtain the complete journey distance.","sol":"Step 1: Stage 1 = 30 × 2 = 60 km\nStep 2: Stage 2 = 20 × 3 = 60 km\nStep 3: Total distance = 60 + 60 = 120 km","steps":["Step 1: Stage 1 = 30 × 2 = 60 km","Step 2: Stage 2 = 20 × 3 = 60 km","Step 3: Total distance = 60 + 60 = 120 km"],"options":[],"conceptId":"math_linear_motion_finding_total_distance_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Total Distance in a Multi-Stage Journey"}', 1),
  (179, 42, 'A bus travels at 80 km/h for 1.5 hours and then at 60 km/h for 2 hours. Find the total distance.', 'text', 1, 'Use d = st for each stage.', '{"why":"The total distance is the sum of both stage distances.","sol":"Step 1: Stage 1 = 80 × 1.5 = 120 km\nStep 2: Stage 2 = 60 × 2 = 120 km\nStep 3: Total distance = 120 + 120 = 240 km","steps":["Step 1: Stage 1 = 80 × 1.5 = 120 km","Step 2: Stage 2 = 60 × 2 = 120 km","Step 3: Total distance = 120 + 120 = 240 km"],"options":[],"conceptId":"math_linear_motion_finding_total_distance_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Total Distance in a Multi-Stage Journey"}', 2),
  (180, 43, 'A car travels 180 km at 60 km/h and then 100 km at 50 km/h. Find the total time.', 'text', 1, 'Find the time for each stage using t = d/s.', '{"why":"The total travelling time is the sum of the times for both stages.","sol":"Step 1: Stage 1 = 180 / 60 = 3 h\nStep 2: Stage 2 = 100 / 50 = 2 h\nStep 3: Total time = 3 + 2 = 5 h","steps":["Step 1: Stage 1 = 180 / 60 = 3 h","Step 2: Stage 2 = 100 / 50 = 2 h","Step 3: Total time = 3 + 2 = 5 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 0),
  (181, 43, 'A cyclist travels 90 km at 30 km/h and then 40 km at 20 km/h. Find the total time.', 'text', 1, 'Calculate each stage time.', '{"why":"Both stage times must be included in the total journey time.","sol":"Step 1: Stage 1 = 90 / 30 = 3 h\nStep 2: Stage 2 = 40 / 20 = 2 h\nStep 3: Total time = 3 + 2 = 5 h","steps":["Step 1: Stage 1 = 90 / 30 = 3 h","Step 2: Stage 2 = 40 / 20 = 2 h","Step 3: Total time = 3 + 2 = 5 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 1),
  (182, 43, 'A bus travels 240 km at 80 km/h and then 150 km at 50 km/h. Find the total time.', 'text', 1, 'Use t = d/s for each stage.', '{"why":"The complete journey takes the sum of the two stage times.","sol":"Step 1: Stage 1 = 240 / 80 = 3 h\nStep 2: Stage 2 = 150 / 50 = 3 h\nStep 3: Total time = 3 + 3 = 6 h","steps":["Step 1: Stage 1 = 240 / 80 = 3 h","Step 2: Stage 2 = 150 / 50 = 3 h","Step 3: Total time = 3 + 3 = 6 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 2),
  (183, 43, 'A car travels 100 km at 50 km/h and then 120 km at 60 km/h. Find the total travel time.', 'text', 1, 'Find each stage time first.', '{"why":"The total journey time is the sum of the times spent on both stages.","sol":"Step 1: Stage 1 time = 100/50 = 2 h\nStep 2: Stage 2 time = 120/60 = 2 h\nStep 3: Total time = 2 + 2 = 4 h","steps":["Step 1: Stage 1 time = 100/50 = 2 h","Step 2: Stage 2 time = 120/60 = 2 h","Step 3: Total time = 2 + 2 = 4 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 3),
  (184, 43, 'A bus travels 150 km at 50 km/h and then 180 km at 60 km/h. Find the total time.', 'text', 1, 'Calculate t₁ and t₂ separately.', '{"why":"Both stages occur one after another, so their times are added.","sol":"Step 1: Stage 1 = 150/50 = 3 h\nStep 2: Stage 2 = 180/60 = 3 h\nStep 3: Total = 3 + 3 = 6 h","steps":["Step 1: Stage 1 = 150/50 = 3 h","Step 2: Stage 2 = 180/60 = 3 h","Step 3: Total = 3 + 3 = 6 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 4),
  (185, 43, 'A cyclist travels 60 km at 30 km/h and then 45 km at 15 km/h. Find the total travel time.', 'text', 1, 'Use time = distance ÷ speed for each stage.', '{"why":"The complete journey takes the sum of the two stage times.","sol":"Step 1: Stage 1 = 60/30 = 2 h\nStep 2: Stage 2 = 45/15 = 3 h\nStep 3: Total = 2 + 3 = 5 h","steps":["Step 1: Stage 1 = 60/30 = 2 h","Step 2: Stage 2 = 45/15 = 3 h","Step 3: Total = 2 + 3 = 5 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 5),
  (186, 44, 'A car travels 150 km at 50 km/h. Find the time for this stage.', 'text', 1, 'Use t = d/s.', '{"why":"The time for a stage is its distance divided by its speed.","sol":"Step 1: t = 150/50\nStep 2: t = 3 hours","steps":["Step 1: t = 150/50","Step 2: t = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_time_for_each_stage","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Time for Each Stage"}', 0),
  (187, 44, 'A bus travels 200 km at 80 km/h. Find the time taken.', 'text', 1, 'Divide 200 by 80.', '{"why":"At 80 km/h, 200 km requires 2.5 hours.","sol":"Step 1: t = 200/80\nStep 2: t = 2.5 hours","steps":["Step 1: t = 200/80","Step 2: t = 2.5 hours"],"options":[],"conceptId":"math_linear_motion_finding_time_for_each_stage","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Time for Each Stage"}', 1),
  (188, 44, 'A cyclist travels 90 km at 30 km/h. Find the time.', 'text', 1, 'Use t = 90/30.', '{"why":"The cyclist covers 30 km every hour.","sol":"Step 1: t = 90/30\nStep 2: t = 3 hours","steps":["Step 1: t = 90/30","Step 2: t = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_time_for_each_stage","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Time for Each Stage"}', 2),
  (189, 45, 'An object is at position +7. Describe its position relative to the origin.', 'text', 1, 'A positive position lies to the right of zero.', '{"why":"Positive positions are measured to the right of zero.","sol":"Step 1: The position is +7.\nStep 2: The positive sign means the object is to the right of the origin.\nStep 3: Its distance from the origin is 7 units.","steps":["Step 1: The position is +7.","Step 2: The positive sign means the object is to the right of the origin.","Step 3: Its distance from the origin is 7 units."],"options":[],"conceptId":"math_linear_motion_representing_position_on_a_number_line","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Representing Position on a Number Line"}', 0),
  (190, 45, 'An object is at position −5. Describe its position relative to the origin.', 'text', 1, 'A negative position lies to the left of zero.', '{"why":"Negative positions are measured to the left of zero.","sol":"Step 1: The position is −5.\nStep 2: The negative sign means the object is to the left of the origin.\nStep 3: Its distance from the origin is 5 units.","steps":["Step 1: The position is −5.","Step 2: The negative sign means the object is to the left of the origin.","Step 3: Its distance from the origin is 5 units."],"options":[],"conceptId":"math_linear_motion_representing_position_on_a_number_line","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Representing Position on a Number Line"}', 1),
  (191, 45, 'Which position is farther to the right: −4 or +2?', 'text', 1, 'Look at their positions on the number line.', '{"why":"Numbers increase as we move from left to right on a number line.","sol":"Step 1: −4 lies to the left of zero.\nStep 2: +2 lies to the right of zero.\nStep 3: Therefore +2 is farther to the right.","steps":["Step 1: −4 lies to the left of zero.","Step 2: +2 lies to the right of zero.","Step 3: Therefore +2 is farther to the right."],"options":[],"conceptId":"math_linear_motion_representing_position_on_a_number_line","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Representing Position on a Number Line"}', 2),
  (192, 46, 'An object moves from position +3 to position +10. Find its displacement.', 'text', 1, 'Use final position − initial position.', '{"why":"The object moved 7 units in the positive direction.","sol":"Step 1: Displacement = 10 − 3\nStep 2: Displacement = +7 units","steps":["Step 1: Displacement = 10 − 3","Step 2: Displacement = +7 units"],"options":[],"conceptId":"math_linear_motion_finding_displacement_from_two_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Displacement from Two Positions"}', 0),
  (193, 46, 'An object moves from position +9 to position +4. Find its displacement.', 'text', 1, 'Subtract the initial position from the final position.', '{"why":"The negative displacement shows movement in the negative direction.","sol":"Step 1: Displacement = 4 − 9\nStep 2: Displacement = −5 units","steps":["Step 1: Displacement = 4 − 9","Step 2: Displacement = −5 units"],"options":[],"conceptId":"math_linear_motion_finding_displacement_from_two_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Displacement from Two Positions"}', 1),
  (194, 46, 'An object moves from position −6 to position +3. Find its displacement.', 'text', 1, 'Be careful with the negative initial position.', '{"why":"Moving from −6 to +3 requires a positive change of 9 units.","sol":"Step 1: Displacement = 3 − (−6)\nStep 2: Displacement = 3 + 6\nStep 3: Displacement = +9 units","steps":["Step 1: Displacement = 3 − (−6)","Step 2: Displacement = 3 + 6","Step 3: Displacement = +9 units"],"options":[],"conceptId":"math_linear_motion_finding_displacement_from_two_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Displacement from Two Positions"}', 2),
  (195, 47, 'An object moves from position +1 to +8. Find the distance travelled.', 'text', 1, 'Find the change in position and take its absolute value.', '{"why":"The object covers 7 units between the two positions.","sol":"Step 1: Change = 8 − 1 = 7\nStep 2: Distance = |7| = 7 units","steps":["Step 1: Change = 8 − 1 = 7","Step 2: Distance = |7| = 7 units"],"options":[],"conceptId":"math_linear_motion_finding_distance_travelled_from_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Distance Travelled from Positions"}', 0),
  (196, 47, 'An object moves from +10 to +4. Find the distance travelled.', 'text', 1, 'Distance cannot be negative.', '{"why":"The negative sign describes direction, but distance measures only the amount travelled.","sol":"Step 1: Change = 4 − 10 = −6\nStep 2: Distance = |−6|\nStep 3: Distance = 6 units","steps":["Step 1: Change = 4 − 10 = −6","Step 2: Distance = |−6|","Step 3: Distance = 6 units"],"options":[],"conceptId":"math_linear_motion_finding_distance_travelled_from_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Distance Travelled from Positions"}', 1),
  (197, 47, 'An object moves from −3 to +7. Find the distance travelled.', 'text', 1, 'Subtract the initial position from the final position.', '{"why":"The object moves through 10 units between −3 and +7.","sol":"Step 1: Change = 7 − (−3)\nStep 2: Change = 10\nStep 3: Distance = 10 units","steps":["Step 1: Change = 7 − (−3)","Step 2: Change = 10","Step 3: Distance = 10 units"],"options":[],"conceptId":"math_linear_motion_finding_distance_travelled_from_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Distance Travelled from Positions"}', 2),
  (198, 48, 'An object starts at position 8 m and moves at 2 m/s. Write its position equation.', 'text', 1, 'Use x = x₀ + st.', '{"why":"The object begins at 8 m and gains 2 m of position every second.","sol":"Step 1: x₀ = 8\nStep 2: s = 2\nStep 3: x = 8 + 2t","steps":["Step 1: x₀ = 8","Step 2: s = 2","Step 3: x = 8 + 2t"],"options":[],"conceptId":"math_linear_motion_writing_a_position_equation_for_constant_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Writing a Position Equation for Constant Speed"}', 0),
  (199, 48, 'An object starts at position 15 m and moves at 5 m/s. Write its position equation.', 'text', 1, 'Substitute the initial position and speed.', '{"why":"The initial position is 15 m and the position increases by 5 m each second.","sol":"Step 1: x₀ = 15\nStep 2: s = 5\nStep 3: x = 15 + 5t","steps":["Step 1: x₀ = 15","Step 2: s = 5","Step 3: x = 15 + 5t"],"options":[],"conceptId":"math_linear_motion_writing_a_position_equation_for_constant_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Writing a Position Equation for Constant Speed"}', 1),
  (200, 48, 'An object starts at 10 m and moves at 6 m/s. Find its position after 4 seconds.', 'text', 1, 'First write x = 10 + 6t, then substitute t = 4.', '{"why":"In 4 seconds the object travels 24 m from its starting position of 10 m.","sol":"Step 1: x = 10 + 6t\nStep 2: x = 10 + 6(4)\nStep 3: x = 10 + 24\nStep 4: x = 34 m","steps":["Step 1: x = 10 + 6t","Step 2: x = 10 + 6(4)","Step 3: x = 10 + 24","Step 4: x = 34 m"],"options":[],"conceptId":"math_linear_motion_writing_a_position_equation_for_constant_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Writing a Position Equation for Constant Speed"}', 2),
  (201, 49, 'Given x = 4 + 5t, find x when t = 3.', 'text', 1, 'Replace t with 3.', '{"why":"Substituting t = 3 gives the position at 3 units of time.","sol":"Step 1: x = 4 + 5(3)\nStep 2: x = 4 + 15\nStep 3: x = 19","steps":["Step 1: x = 4 + 5(3)","Step 2: x = 4 + 15","Step 3: x = 19"],"options":[],"conceptId":"math_linear_motion_finding_position_from_a_linear_motion_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Position from a Linear Motion Equation"}', 0),
  (202, 49, 'Given x = 8 + 2t, find x when t = 6.', 'text', 1, 'Substitute t = 6.', '{"why":"The equation gives the position directly once the time is known.","sol":"Step 1: x = 8 + 2(6)\nStep 2: x = 8 + 12\nStep 3: x = 20","steps":["Step 1: x = 8 + 2(6)","Step 2: x = 8 + 12","Step 3: x = 20"],"options":[],"conceptId":"math_linear_motion_finding_position_from_a_linear_motion_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Position from a Linear Motion Equation"}', 1),
  (203, 49, 'Given x = 15 + 7t, find x when t = 2.', 'text', 1, 'Replace t by 2.', '{"why":"At t = 2, the position is obtained by substituting 2 into the equation.","sol":"Step 1: x = 15 + 7(2)\nStep 2: x = 15 + 14\nStep 3: x = 29","steps":["Step 1: x = 15 + 7(2)","Step 2: x = 15 + 14","Step 3: x = 29"],"options":[],"conceptId":"math_linear_motion_finding_position_from_a_linear_motion_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Position from a Linear Motion Equation"}', 2),
  (204, 50, 'Given x = 4 + 2t, find t when x = 14.', 'text', 1, 'Substitute x = 14 and solve the linear equation.', '{"why":"Solving the position equation gives the time at which the object reaches position 14.","sol":"Step 1: 14 = 4 + 2t\nStep 2: 10 = 2t\nStep 3: t = 5","steps":["Step 1: 14 = 4 + 2t","Step 2: 10 = 2t","Step 3: t = 5"],"options":[],"conceptId":"math_linear_motion_finding_time_from_a_position_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Time from a Position Equation"}', 0),
  (205, 50, 'Given x = 7 + 3t, find t when x = 22.', 'text', 1, 'Subtract 7 first.', '{"why":"The unknown time is found by solving the linear equation.","sol":"Step 1: 22 = 7 + 3t\nStep 2: 15 = 3t\nStep 3: t = 5","steps":["Step 1: 22 = 7 + 3t","Step 2: 15 = 3t","Step 3: t = 5"],"options":[],"conceptId":"math_linear_motion_finding_time_from_a_position_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Time from a Position Equation"}', 1),
  (206, 50, 'Given x = 12 + 4t, find t when x = 32.', 'text', 1, 'Subtract 12, then divide by 4.', '{"why":"The equation tells us the position at every time, so we can solve it backwards for time.","sol":"Step 1: 32 = 12 + 4t\nStep 2: 20 = 4t\nStep 3: t = 5","steps":["Step 1: 32 = 12 + 4t","Step 2: 20 = 4t","Step 3: t = 5"],"options":[],"conceptId":"math_linear_motion_finding_time_from_a_position_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Time from a Position Equation"}', 2),
  (207, 51, 'A person walks 5 km away from home and 5 km back. Find the total distance.', 'text', 1, 'Add the outward and return distances.', '{"why":"Both the outward and return parts contribute to total distance.","sol":"Step 1: Total distance = 5 + 5\nStep 2: Total distance = 10 km","steps":["Step 1: Total distance = 5 + 5","Step 2: Total distance = 10 km"],"options":[],"conceptId":"math_linear_motion_distance_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Distance in a Return Journey"}', 0),
  (208, 51, 'A cyclist travels 8 km from A to B and then 3 km back towards A. Find the total distance travelled.', 'text', 1, 'Add both parts.', '{"why":"Distance counts every part of the path travelled.","sol":"Step 1: Outward distance = 8 km\nStep 2: Return distance = 3 km\nStep 3: Total distance = 8 + 3 = 11 km","steps":["Step 1: Outward distance = 8 km","Step 2: Return distance = 3 km","Step 3: Total distance = 8 + 3 = 11 km"],"options":[],"conceptId":"math_linear_motion_distance_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Distance in a Return Journey"}', 1),
  (209, 51, 'A car travels 20 km east and then 12 km west. Find the total distance travelled.', 'text', 1, 'Direction does not make distance negative.', '{"why":"Total distance is the complete length of the path.","sol":"Step 1: First distance = 20 km\nStep 2: Second distance = 12 km\nStep 3: Total distance = 20 + 12\nStep 4: Total distance = 32 km","steps":["Step 1: First distance = 20 km","Step 2: Second distance = 12 km","Step 3: Total distance = 20 + 12","Step 4: Total distance = 32 km"],"options":[],"conceptId":"math_linear_motion_distance_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Distance in a Return Journey"}', 2),
  (210, 52, 'A person walks 7 km east and then 7 km west. Find the displacement.', 'text', 1, 'The person finishes at the starting point.', '{"why":"The final position is the same as the initial position.","sol":"Step 1: Initial position = 0\nStep 2: Final position = 0\nStep 3: Displacement = 0 − 0 = 0 km","steps":["Step 1: Initial position = 0","Step 2: Final position = 0","Step 3: Displacement = 0 − 0 = 0 km"],"options":[],"conceptId":"math_linear_motion_displacement_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Displacement in a Return Journey"}', 0),
  (211, 52, 'A cyclist travels 12 km east and then 5 km west. Find the displacement.', 'text', 1, 'Take east as positive.', '{"why":"The cyclist finishes 7 km east of the starting point.","sol":"Step 1: Final position = 12 − 5\nStep 2: Final position = +7 km\nStep 3: Displacement = +7 km","steps":["Step 1: Final position = 12 − 5","Step 2: Final position = +7 km","Step 3: Displacement = +7 km"],"options":[],"conceptId":"math_linear_motion_displacement_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Displacement in a Return Journey"}', 1),
  (212, 52, 'A car travels 15 km west and then 10 km east. Find its displacement.', 'text', 1, 'Take east as positive, so west is negative.', '{"why":"The car finishes 5 km west of its starting point.","sol":"Step 1: First movement = −15 km\nStep 2: Second movement = +10 km\nStep 3: Final position = −15 + 10 = −5 km\nStep 4: Displacement = −5 km","steps":["Step 1: First movement = −15 km","Step 2: Second movement = +10 km","Step 3: Final position = −15 + 10 = −5 km","Step 4: Displacement = −5 km"],"options":[],"conceptId":"math_linear_motion_displacement_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Displacement in a Return Journey"}', 2),
  (213, 53, 'An object starts at 0 m, moves 10 m east and then 4 m west. Find its final position.', 'text', 1, 'Take east as positive.', '{"why":"The object finishes 6 m east of its starting point.","sol":"Step 1: Final position = 0 + 10 − 4\nStep 2: Final position = +6 m","steps":["Step 1: Final position = 0 + 10 − 4","Step 2: Final position = +6 m"],"options":[],"conceptId":"math_linear_motion_finding_the_final_position_after_several_movements","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding the Final Position After Several Movements"}', 0),
  (214, 53, 'An object starts at 8 m, moves 5 m west and then 2 m east. Find its final position.', 'text', 1, 'West is negative and east is positive.', '{"why":"The two movements change the starting position of 8 m.","sol":"Step 1: Final position = 8 − 5 + 2\nStep 2: Final position = 5 m","steps":["Step 1: Final position = 8 − 5 + 2","Step 2: Final position = 5 m"],"options":[],"conceptId":"math_linear_motion_finding_the_final_position_after_several_movements","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding the Final Position After Several Movements"}', 1),
  (215, 53, 'An object starts at −4 m, moves 9 m east and then 3 m west. Find its final position.', 'text', 1, 'Add +9 and −3 to the initial position.', '{"why":"The signed movements take the object from −4 m to +2 m.","sol":"Step 1: Final position = −4 + 9 − 3\nStep 2: Final position = +2 m","steps":["Step 1: Final position = −4 + 9 − 3","Step 2: Final position = +2 m"],"options":[],"conceptId":"math_linear_motion_finding_the_final_position_after_several_movements","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding the Final Position After Several Movements"}', 2),
  (216, 54, 'A bus starts at 8:00 a.m. and a car starts at 10:00 a.m. If t is the number of hours after 8:00 a.m., express the car''s travel time.', 'text', 1, 'The car starts 2 hours after the reference time.', '{"why":"The car has been travelling for two fewer hours than the elapsed time measured from 8:00 a.m.","sol":"Step 1: The delay is 2 hours.\nStep 2: Elapsed time = t.\nStep 3: Car travel time = t − 2.","steps":["Step 1: The delay is 2 hours.","Step 2: Elapsed time = t.","Step 3: Car travel time = t − 2."],"options":[],"conceptId":"math_linear_motion_representing_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Representing a Delayed Start"}', 0),
  (217, 54, 'A cyclist starts at 7:00 a.m. and another starts at 8:00 a.m. If t is measured from 7:00 a.m., express the second cyclist''s travel time.', 'text', 1, 'The second cyclist starts 1 hour later.', '{"why":"The second cyclist loses one hour of travel time because of the delayed start.","sol":"Step 1: Delay = 1 hour\nStep 2: Elapsed time = t\nStep 3: Travel time = t − 1","steps":["Step 1: Delay = 1 hour","Step 2: Elapsed time = t","Step 3: Travel time = t − 1"],"options":[],"conceptId":"math_linear_motion_representing_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Representing a Delayed Start"}', 1),
  (218, 54, 'A vehicle starts at 6:00 a.m. and another starts at 6:30 a.m. If t is measured from 6:00 a.m., express the second vehicle''s travel time.', 'text', 1, 'Convert 30 minutes to hours.', '{"why":"The second vehicle begins half an hour after the first.","sol":"Step 1: 30 minutes = 0.5 hours\nStep 2: Delay = 0.5 hours\nStep 3: Travel time = t − 0.5","steps":["Step 1: 30 minutes = 0.5 hours","Step 2: Delay = 0.5 hours","Step 3: Travel time = t − 0.5"],"options":[],"conceptId":"math_linear_motion_representing_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Representing a Delayed Start"}', 2),
  (219, 55, 'A car starts 2 hours after a bus and travels at 70 km/h. If t is measured from the bus''s starting time, write the car''s distance equation.', 'text', 1, 'The car travels for t − 2 hours.', '{"why":"The car''s actual travel time is t − 2 because it starts two hours late.","sol":"Step 1: Car travel time = t − 2\nStep 2: Distance = speed × time\nStep 3: Distance = 70(t − 2)","steps":["Step 1: Car travel time = t − 2","Step 2: Distance = speed × time","Step 3: Distance = 70(t − 2)"],"options":[],"conceptId":"math_linear_motion_finding_distance_after_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Distance After a Delayed Start"}', 0),
  (220, 55, 'A cyclist starts 1 hour after another cyclist and travels at 30 km/h. Write its distance equation using t as time from the first cyclist''s start.', 'text', 1, 'Subtract the 1-hour delay from t.', '{"why":"The cyclist travels for one hour less than the elapsed time t.","sol":"Step 1: Travel time = t − 1\nStep 2: Distance = 30(t − 1)","steps":["Step 1: Travel time = t − 1","Step 2: Distance = 30(t − 1)"],"options":[],"conceptId":"math_linear_motion_finding_distance_after_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Distance After a Delayed Start"}', 1),
  (221, 55, 'A bus starts 0.5 hours after a car and travels at 60 km/h. Write its distance equation.', 'text', 1, 'The delay is half an hour.', '{"why":"The bus has only travelled for t − 0.5 hours.","sol":"Step 1: Travel time = t − 0.5\nStep 2: Distance = 60(t − 0.5)","steps":["Step 1: Travel time = t − 0.5","Step 2: Distance = 60(t − 0.5)"],"options":[],"conceptId":"math_linear_motion_finding_distance_after_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Distance After a Delayed Start"}', 2),
  (222, 56, 'A bus leaves at 8:00 a.m. at 40 km/h. A car leaves at 10:00 a.m. at 60 km/h. How many hours after 8:00 a.m. does the car catch the bus?', 'text', 1, 'Set 40t equal to 60(t − 2).', '{"why":"At the catching point both vehicles have travelled the same distance from the starting point.","sol":"Step 1: Bus distance = 40t\nStep 2: Car distance = 60(t − 2)\nStep 3: 40t = 60(t − 2)\nStep 4: 40t = 60t − 120\nStep 5: 120 = 20t\nStep 6: t = 6 hours","steps":["Step 1: Bus distance = 40t","Step 2: Car distance = 60(t − 2)","Step 3: 40t = 60(t − 2)","Step 4: 40t = 60t − 120","Step 5: 120 = 20t","Step 6: t = 6 hours"],"options":[],"conceptId":"math_linear_motion_finding_when_a_delayed_object_catches_up","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding When a Delayed Object Catches Up"}', 0),
  (223, 56, 'A cyclist leaves at 7:00 a.m. at 20 km/h. Another leaves at 9:00 a.m. at 30 km/h. Find the catching time measured from 7:00 a.m.', 'text', 1, 'Use 20t = 30(t − 2).', '{"why":"The second cyclist makes up the initial two-hour disadvantage because they travel faster.","sol":"Step 1: 20t = 30(t − 2)\nStep 2: 20t = 30t − 60\nStep 3: 60 = 10t\nStep 4: t = 6 hours","steps":["Step 1: 20t = 30(t − 2)","Step 2: 20t = 30t − 60","Step 3: 60 = 10t","Step 4: t = 6 hours"],"options":[],"conceptId":"math_linear_motion_finding_when_a_delayed_object_catches_up","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding When a Delayed Object Catches Up"}', 1),
  (224, 56, 'A truck leaves at 6:00 a.m. at 50 km/h. A car leaves at 8:00 a.m. at 75 km/h. Find when the car catches the truck, measured from 6:00 a.m.', 'text', 1, 'Set 50t = 75(t − 2).', '{"why":"Equal distances indicate the exact moment the car catches the truck.","sol":"Step 1: 50t = 75(t − 2)\nStep 2: 50t = 75t − 150\nStep 3: 150 = 25t\nStep 4: t = 6 hours","steps":["Step 1: 50t = 75(t − 2)","Step 2: 50t = 75t − 150","Step 3: 150 = 25t","Step 4: t = 6 hours"],"options":[],"conceptId":"math_linear_motion_finding_when_a_delayed_object_catches_up","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding When a Delayed Object Catches Up"}', 2),
  (225, 57, 'A car travels at 80 km/h for t hours and covers 240 km. Find t.', 'text', 1, 'Use 240 = 80t.', '{"why":"The unknown time is obtained by dividing distance by speed.","sol":"Step 1: 240 = 80t\nStep 2: t = 240/80\nStep 3: t = 3 hours","steps":["Step 1: 240 = 80t","Step 2: t = 240/80","Step 3: t = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_algebraically","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance Algebraically"}', 0),
  (226, 57, 'A cyclist travels at x km/h for 5 hours and covers 125 km. Find x.', 'text', 1, 'Use 125 = 5x.', '{"why":"The unknown speed is distance divided by time.","sol":"Step 1: 125 = 5x\nStep 2: x = 125/5\nStep 3: x = 25 km/h","steps":["Step 1: 125 = 5x","Step 2: x = 125/5","Step 3: x = 25 km/h"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_algebraically","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance Algebraically"}', 1),
  (227, 57, 'A bus travels at 60 km/h for t hours and covers 300 km. Find t.', 'text', 1, 'Form the equation 300 = 60t.', '{"why":"The equation follows directly from distance = speed × time.","sol":"Step 1: 300 = 60t\nStep 2: t = 300/60\nStep 3: t = 5 hours","steps":["Step 1: 300 = 60t","Step 2: t = 300/60","Step 3: t = 5 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_algebraically","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance Algebraically"}', 2),
  (228, 58, 'A car covers 180 km at 60 km/h while a bus covers the same distance at 45 km/h. Find the difference in their travel times.', 'text', 1, 'Find each time using t = d/s.', '{"why":"The slower bus requires one extra hour to cover the same distance.","sol":"Step 1: Car time = 180/60 = 3 h\nStep 2: Bus time = 180/45 = 4 h\nStep 3: Difference = 4 − 3 = 1 h","steps":["Step 1: Car time = 180/60 = 3 h","Step 2: Bus time = 180/45 = 4 h","Step 3: Difference = 4 − 3 = 1 h"],"options":[],"conceptId":"math_linear_motion_using_algebra_to_compare_two_travel_times","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Using Algebra to Compare Two Travel Times"}', 0),
  (229, 58, 'A cyclist covers 120 km at 30 km/h while another covers it at 40 km/h. Find the difference in time.', 'text', 1, 'Calculate both times.', '{"why":"The lower speed results in a longer travel time.","sol":"Step 1: First time = 120/30 = 4 h\nStep 2: Second time = 120/40 = 3 h\nStep 3: Difference = 4 − 3 = 1 h","steps":["Step 1: First time = 120/30 = 4 h","Step 2: Second time = 120/40 = 3 h","Step 3: Difference = 4 − 3 = 1 h"],"options":[],"conceptId":"math_linear_motion_using_algebra_to_compare_two_travel_times","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Using Algebra to Compare Two Travel Times"}', 1),
  (230, 58, 'A train covers 300 km at 75 km/h while another covers the same distance at 60 km/h. Find the difference in travel time.', 'text', 1, 'Use distance divided by speed for each train.', '{"why":"The second train takes one additional hour to cover the same distance.","sol":"Step 1: First time = 300/75 = 4 h\nStep 2: Second time = 300/60 = 5 h\nStep 3: Difference = 5 − 4 = 1 h","steps":["Step 1: First time = 300/75 = 4 h","Step 2: Second time = 300/60 = 5 h","Step 3: Difference = 5 − 4 = 1 h"],"options":[],"conceptId":"math_linear_motion_using_algebra_to_compare_two_travel_times","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Using Algebra to Compare Two Travel Times"}', 2),
  (231, 59, 'A 150 km journey takes 3 hours for one car and 5 hours for another. Find both speeds.', 'text', 1, 'Use speed = distance ÷ time for each car.', '{"why":"Each speed is found by dividing the common distance by that vehicle''s travel time.","sol":"Step 1: First speed = 150/3 = 50 km/h\nStep 2: Second speed = 150/5 = 30 km/h","steps":["Step 1: First speed = 150/3 = 50 km/h","Step 2: Second speed = 150/5 = 30 km/h"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_time_difference","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Time Difference"}', 0),
  (232, 59, 'A 200 km journey takes 4 hours for one vehicle and 5 hours for another. Find both speeds.', 'text', 1, 'Calculate each speed separately.', '{"why":"The same distance divided by different times gives different speeds.","sol":"Step 1: First speed = 200/4 = 50 km/h\nStep 2: Second speed = 200/5 = 40 km/h","steps":["Step 1: First speed = 200/4 = 50 km/h","Step 2: Second speed = 200/5 = 40 km/h"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_time_difference","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Time Difference"}', 1),
  (233, 59, 'A 360 km journey takes 6 hours for one vehicle and 9 hours for another. Find both speeds.', 'text', 1, 'Use s = d/t.', '{"why":"Speed is distance divided by the time taken.","sol":"Step 1: First speed = 360/6 = 60 km/h\nStep 2: Second speed = 360/9 = 40 km/h","steps":["Step 1: First speed = 360/6 = 60 km/h","Step 2: Second speed = 360/9 = 40 km/h"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_time_difference","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Time Difference"}', 2),
  (234, 60, 'A car travels at 70 km/h for 4 hours. Find the distance travelled.', 'text', 1, 'Use d = st.', '{"why":"Distance is found by multiplying speed by time.","sol":"Step 1: d = st\nStep 2: d = 70 × 4\nStep 3: d = 280 km","steps":["Step 1: d = st","Step 2: d = 70 × 4","Step 3: d = 280 km"],"options":[],"conceptId":"math_linear_motion_using_distance_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Using Distance-Time Relationships"}', 0),
  (235, 60, 'A runner moves at 8 m/s for 25 seconds. Find the distance travelled.', 'text', 1, 'Multiply speed by time.', '{"why":"The runner covers 8 metres every second for 25 seconds.","sol":"Step 1: d = st\nStep 2: d = 8 × 25\nStep 3: d = 200 m","steps":["Step 1: d = st","Step 2: d = 8 × 25","Step 3: d = 200 m"],"options":[],"conceptId":"math_linear_motion_using_distance_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Using Distance-Time Relationships"}', 1),
  (236, 60, 'A vehicle travels 360 km at 90 km/h. Find the time taken.', 'text', 1, 'Rearrange d = st to make t the subject.', '{"why":"Time is distance divided by speed.","sol":"Step 1: 360 = 90t\nStep 2: t = 360 ÷ 90\nStep 3: t = 4 hours","steps":["Step 1: 360 = 90t","Step 2: t = 360 ÷ 90","Step 3: t = 4 hours"],"options":[],"conceptId":"math_linear_motion_using_distance_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Using Distance-Time Relationships"}', 2),
  (237, 61, 'A car travels 300 km in 5 hours. Find its speed.', 'text', 1, 'Speed = distance ÷ time.', '{"why":"Speed measures how much distance is covered in each unit of time.","sol":"Step 1: s = d/t\nStep 2: s = 300 ÷ 5\nStep 3: s = 60 km/h","steps":["Step 1: s = d/t","Step 2: s = 300 ÷ 5","Step 3: s = 60 km/h"],"options":[],"conceptId":"math_linear_motion_using_speed_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Using Speed-Time Relationships"}', 0),
  (238, 61, 'A cyclist covers 180 m in 30 seconds. Find the speed.', 'text', 1, 'Divide distance by time.', '{"why":"The cyclist covers 6 metres during each second.","sol":"Step 1: s = d/t\nStep 2: s = 180 ÷ 30\nStep 3: s = 6 m/s","steps":["Step 1: s = d/t","Step 2: s = 180 ÷ 30","Step 3: s = 6 m/s"],"options":[],"conceptId":"math_linear_motion_using_speed_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Using Speed-Time Relationships"}', 1),
  (239, 61, 'A train travels 450 km in 6 hours. Find its average speed.', 'text', 1, 'Average speed = total distance ÷ total time.', '{"why":"Average speed uses the total distance and the total time.","sol":"Step 1: Average speed = 450 ÷ 6\nStep 2: Average speed = 75 km/h","steps":["Step 1: Average speed = 450 ÷ 6","Step 2: Average speed = 75 km/h"],"options":[],"conceptId":"math_linear_motion_using_speed_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Using Speed-Time Relationships"}', 2),
  (240, 62, 'A distance-time graph passes through (2 s, 8 m) and (6 s, 28 m). Find the speed.', 'text', 1, 'Find change in distance and divide by change in time.', '{"why":"The gradient of a distance-time graph represents speed.","sol":"Step 1: Change in distance = 28 − 8 = 20 m\nStep 2: Change in time = 6 − 2 = 4 s\nStep 3: Speed = 20 ÷ 4\nStep 4: Speed = 5 m/s","steps":["Step 1: Change in distance = 28 − 8 = 20 m","Step 2: Change in time = 6 − 2 = 4 s","Step 3: Speed = 20 ÷ 4","Step 4: Speed = 5 m/s"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Distance-Time Graph"}', 0),
  (241, 62, 'A graph passes through (0 s, 0 m) and (10 s, 60 m). Find the speed.', 'text', 1, 'Use gradient = change in distance ÷ change in time.', '{"why":"The graph''s gradient gives the speed.","sol":"Step 1: Change in distance = 60 m\nStep 2: Change in time = 10 s\nStep 3: Speed = 60 ÷ 10\nStep 4: Speed = 6 m/s","steps":["Step 1: Change in distance = 60 m","Step 2: Change in time = 10 s","Step 3: Speed = 60 ÷ 10","Step 4: Speed = 6 m/s"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Distance-Time Graph"}', 1),
  (242, 62, 'A distance-time graph passes through (4 s, 12 m) and (9 s, 32 m). Find the speed.', 'text', 1, 'Subtract the coordinates first.', '{"why":"Speed is the gradient of the distance-time graph.","sol":"Step 1: Change in distance = 32 − 12 = 20 m\nStep 2: Change in time = 9 − 4 = 5 s\nStep 3: Speed = 20 ÷ 5\nStep 4: Speed = 4 m/s","steps":["Step 1: Change in distance = 32 − 12 = 20 m","Step 2: Change in time = 9 − 4 = 5 s","Step 3: Speed = 20 ÷ 5","Step 4: Speed = 4 m/s"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Distance-Time Graph"}', 2),
  (243, 63, 'A car travels 80 km in 2 hours and then 120 km in 3 hours. Find its average speed.', 'text', 1, 'Add the distances and add the times before dividing.', '{"why":"Average speed is based on total distance divided by total time.","sol":"Step 1: Total distance = 80 + 120 = 200 km\nStep 2: Total time = 2 + 3 = 5 hours\nStep 3: Average speed = 200 ÷ 5\nStep 4: Average speed = 40 km/h","steps":["Step 1: Total distance = 80 + 120 = 200 km","Step 2: Total time = 2 + 3 = 5 hours","Step 3: Average speed = 200 ÷ 5","Step 4: Average speed = 40 km/h"],"options":[],"conceptId":"math_linear_motion_average_speed_for_different_parts_of_a_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Average Speed for Different Parts of a Journey"}', 0),
  (244, 63, 'A cyclist travels 40 km in 2 hours and 30 km in 1 hour. Find the average speed.', 'text', 1, 'Do not average 20 km/h and 30 km/h directly.', '{"why":"The two parts take different amounts of time, so the total distance and total time must be used.","sol":"Step 1: Total distance = 40 + 30 = 70 km\nStep 2: Total time = 2 + 1 = 3 hours\nStep 3: Average speed = 70 ÷ 3\nStep 4: Average speed ≈ 23.33 km/h","steps":["Step 1: Total distance = 40 + 30 = 70 km","Step 2: Total time = 2 + 1 = 3 hours","Step 3: Average speed = 70 ÷ 3","Step 4: Average speed ≈ 23.33 km/h"],"options":[],"conceptId":"math_linear_motion_average_speed_for_different_parts_of_a_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Average Speed for Different Parts of a Journey"}', 1),
  (245, 63, 'A vehicle travels 150 km in 3 hours and 100 km in 2 hours. Find the average speed.', 'text', 1, 'Find total distance and total time.', '{"why":"Average speed measures the entire journey rather than treating each section separately.","sol":"Step 1: Total distance = 150 + 100 = 250 km\nStep 2: Total time = 3 + 2 = 5 hours\nStep 3: Average speed = 250 ÷ 5\nStep 4: Average speed = 50 km/h","steps":["Step 1: Total distance = 150 + 100 = 250 km","Step 2: Total time = 3 + 2 = 5 hours","Step 3: Average speed = 250 ÷ 5","Step 4: Average speed = 50 km/h"],"options":[],"conceptId":"math_linear_motion_average_speed_for_different_parts_of_a_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Average Speed for Different Parts of a Journey"}', 2),
  (246, 64, 'A vehicle travels at 70 km/h for 4 hours. Find the distance travelled.', 'text', 1, 'Identify speed and time, then use d = st.', '{"why":"Distance is obtained by multiplying speed by time.","sol":"Step 1: d = st\nStep 2: d = 70 × 4\nStep 3: d = 280 km","steps":["Step 1: d = st","Step 2: d = 70 × 4","Step 3: d = 280 km"],"options":[],"conceptId":"math_linear_motion_solving_a_complete_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Solving a Complete Motion Problem"}', 0),
  (247, 64, 'A bus travels 360 km in 6 hours. Find its average speed.', 'text', 1, 'Use speed = distance ÷ time.', '{"why":"Average speed is total distance divided by total time.","sol":"Step 1: s = d/t\nStep 2: s = 360 ÷ 6\nStep 3: s = 60 km/h","steps":["Step 1: s = d/t","Step 2: s = 360 ÷ 6","Step 3: s = 60 km/h"],"options":[],"conceptId":"math_linear_motion_solving_a_complete_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Solving a Complete Motion Problem"}', 1),
  (248, 64, 'A car travels 120 km at 60 km/h and then 180 km at 90 km/h. Find the total time.', 'text', 1, 'Find the time for each section separately, then add them.', '{"why":"The journey has two stages, so their individual times must be added.","sol":"Step 1: First section: t = 120 ÷ 60 = 2 hours\nStep 2: Second section: t = 180 ÷ 90 = 2 hours\nStep 3: Total time = 2 + 2\nStep 4: Total time = 4 hours","steps":["Step 1: First section: t = 120 ÷ 60 = 2 hours","Step 2: Second section: t = 180 ÷ 90 = 2 hours","Step 3: Total time = 2 + 2","Step 4: Total time = 4 hours"],"options":[],"conceptId":"math_linear_motion_solving_a_complete_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Solving a Complete Motion Problem"}', 2),
  (249, 65, 'Evaluate 3x + 5 when x = 2', 'text', 1, 'substitute first', '{"why":"Substitution must be done before simplifying","sol":"Step 1: Replace x with 2 → 3(2) + 5\nStep 2: Multiply → 6 + 5\nStep 3: = 11","steps":["Step 1: Replace x with 2 → 3(2) + 5","Step 2: Multiply → 6 + 5","Step 3: = 11"],"options":[],"conceptId":"math_algebra_algebraic_expressions","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Algebraic expressions"}', 0),
  (250, 65, 'Simplify 2x + 3x', 'text', 1, 'like terms', '{"why":"Only like terms can be combined","sol":"Step 1: 2x + 3x\nStep 2: (2 + 3)x\nStep 3: = 5x","steps":["Step 1: 2x + 3x","Step 2: (2 + 3)x","Step 3: = 5x"],"options":[],"conceptId":"math_algebra_algebraic_expressions","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Algebraic expressions"}', 1);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (251, 65, 'Identify: 4y + 7', 'text', 1, 'expression parts', '{"why":"It has variables and constants but no equation","sol":"Step 1: Contains variable y\nStep 2: Contains constant 7\nStep 3: No equals sign","steps":["Step 1: Contains variable y","Step 2: Contains constant 7","Step 3: No equals sign"],"options":[],"conceptId":"math_algebra_algebraic_expressions","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Algebraic expressions"}', 2),
  (252, 65, 'Translate: ‘5 less than a number x’', 'text', 1, 'subtract 5', '{"why":"Word phrases convert into algebraic expressions","sol":"Step 1: number x → x\nStep 2: 5 less → −5\nStep 3: x − 5","steps":["Step 1: number x → x","Step 2: 5 less → −5","Step 3: x − 5"],"options":[],"conceptId":"math_algebra_algebraic_expressions","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Algebraic expressions"}', 3),
  (253, 66, 'Simplify 3x + 4x + 2', 'text', 1, 'group like terms', '{"why":"Only like terms can be combined","sol":"Step 1: 3x + 4x = 7x\nStep 2: +2 remains unchanged\nStep 3: 7x + 2","steps":["Step 1: 3x + 4x = 7x","Step 2: +2 remains unchanged","Step 3: 7x + 2"],"options":[],"conceptId":"math_algebra_simplifying_expressions","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Simplifying expressions"}', 0),
  (254, 66, 'Simplify 6a - 2a', 'text', 1, 'subtract coefficients', '{"why":"Same variable means combine coefficients","sol":"Step 1: 6a − 2a\nStep 2: (6 − 2)a = 4a","steps":["Step 1: 6a − 2a","Step 2: (6 − 2)a = 4a"],"options":[],"conceptId":"math_algebra_simplifying_expressions","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Simplifying expressions"}', 1),
  (255, 66, 'Simplify 2x + 3y + 5x', 'text', 1, 'group x terms', '{"why":"Like terms grouped together","sol":"Step 1: (2x + 5x) + 3y\nStep 2: 7x + 3y","steps":["Step 1: (2x + 5x) + 3y","Step 2: 7x + 3y"],"options":[],"conceptId":"math_algebra_simplifying_expressions","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Simplifying expressions"}', 2),
  (256, 66, 'Simplify x + 2x + y + 3y', 'text', 1, 'group both variables', '{"why":"Combine each variable separately","sol":"Step 1: (x + 2x) + (y + 3y)\nStep 2: 3x + 4y","steps":["Step 1: (x + 2x) + (y + 3y)","Step 2: 3x + 4y"],"options":[],"conceptId":"math_algebra_simplifying_expressions","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Simplifying expressions"}', 3),
  (257, 67, 'Solve x + 5 = 12', 'text', 1, 'inverse operation', '{"why":"Maintain balance by doing same operation on both sides","sol":"Step 1: Subtract 5 from both sides\nStep 2: x = 12 − 5\nStep 3: x = 7","steps":["Step 1: Subtract 5 from both sides","Step 2: x = 12 − 5","Step 3: x = 7"],"options":[],"conceptId":"math_algebra_linear_equations","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Linear equations"}', 0),
  (258, 67, 'Solve 2x = 10', 'text', 1, 'divide both sides', '{"why":"Inverse of multiplication is division","sol":"Step 1: Divide both sides by 2\nStep 2: x = 5","steps":["Step 1: Divide both sides by 2","Step 2: x = 5"],"options":[],"conceptId":"math_algebra_linear_equations","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Linear equations"}', 1),
  (259, 67, 'Solve 3x + 2 = 11', 'text', 1, 'remove constant first', '{"why":"Isolate variable step by step","sol":"Step 1: 3x = 11 − 2\nStep 2: 3x = 9\nStep 3: x = 3","steps":["Step 1: 3x = 11 − 2","Step 2: 3x = 9","Step 3: x = 3"],"options":[],"conceptId":"math_algebra_linear_equations","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Linear equations"}', 2),
  (260, 67, 'Solve 4x − 6 = 10', 'text', 1, 'add 6 first', '{"why":"Move constants using inverse operations","sol":"Step 1: 4x = 10 + 6\nStep 2: 4x = 16\nStep 3: x = 4","steps":["Step 1: 4x = 10 + 6","Step 2: 4x = 16","Step 3: x = 4"],"options":[],"conceptId":"math_algebra_linear_equations","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Linear equations"}', 3),
  (261, 68, 'If x = 3, find x + 4', 'text', 1, 'replace x first', '{"why":"Substitution replaces variables with numbers","sol":"Step 1: Substitute x = 3\nStep 2: 3 + 4\nStep 3: = 7","steps":["Step 1: Substitute x = 3","Step 2: 3 + 4","Step 3: = 7"],"options":[],"conceptId":"math_algebra_substitution","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Substitution"}', 0),
  (262, 68, 'If x = 2, find 2x + 1', 'text', 1, 'multiply first', '{"why":"Follow multiplication before addition","sol":"Step 1: Substitute → 2(2) + 1\nStep 2: Multiply → 4 + 1\nStep 3: = 5","steps":["Step 1: Substitute → 2(2) + 1","Step 2: Multiply → 4 + 1","Step 3: = 5"],"options":[],"conceptId":"math_algebra_substitution","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Substitution"}', 1),
  (263, 68, 'If x = 4, y = 3, find x + y', 'text', 1, 'replace both variables', '{"why":"Both variables must be replaced","sol":"Step 1: Substitute → 4 + 3\nStep 2: Simplify\nStep 3: = 7","steps":["Step 1: Substitute → 4 + 3","Step 2: Simplify","Step 3: = 7"],"options":[],"conceptId":"math_algebra_substitution","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Substitution"}', 2),
  (264, 68, 'If x = 5, find 3x − 2', 'text', 1, 'multiply then subtract', '{"why":"Substitution followed by order of operations","sol":"Step 1: 3 × 5 = 15\nStep 2: 15 − 2\nStep 3: = 13","steps":["Step 1: 3 × 5 = 15","Step 2: 15 − 2","Step 3: = 13"],"options":[],"conceptId":"math_algebra_substitution","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Substitution"}', 3),
  (265, 69, 'Expand 2(x + 3)', 'text', 1, 'multiply each term', '{"why":"Distributive law multiplies each term inside bracket","sol":"Step 1: 2 × x = 2x\nStep 2: 2 × 3 = 6\nStep 3: Combine → 2x + 6","steps":["Step 1: 2 × x = 2x","Step 2: 2 × 3 = 6","Step 3: Combine → 2x + 6"],"options":[],"conceptId":"math_algebra_expanding_brackets","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Expanding brackets"}', 0),
  (266, 69, 'Expand 3(a + 2)', 'text', 1, 'distribute 3', '{"why":"Each term inside bracket must be multiplied","sol":"Step 1: 3 × a = 3a\nStep 2: 3 × 2 = 6\nStep 3: 3a + 6","steps":["Step 1: 3 × a = 3a","Step 2: 3 × 2 = 6","Step 3: 3a + 6"],"options":[],"conceptId":"math_algebra_expanding_brackets","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Expanding brackets"}', 1),
  (267, 69, 'Expand 4(x + 1)', 'text', 1, 'multiply each term', '{"why":"Distributive property applies to all terms","sol":"Step 1: 4 × x = 4x\nStep 2: 4 × 1 = 4\nStep 3: 4x + 4","steps":["Step 1: 4 × x = 4x","Step 2: 4 × 1 = 4","Step 3: 4x + 4"],"options":[],"conceptId":"math_algebra_expanding_brackets","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Expanding brackets"}', 2),
  (268, 69, 'What is the distributive law?', 'text', 1, 'a(b + c)', '{"why":"It ensures correct expansion of brackets","sol":"Step 1: Multiply outside term\nStep 2: Multiply each inside term\nStep 3: Combine results","steps":["Step 1: Multiply outside term","Step 2: Multiply each inside term","Step 3: Combine results"],"options":[],"conceptId":"math_algebra_expanding_brackets","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Expanding brackets"}', 3),
  (269, 70, 'Classify an angle of 24°.', 'text', 1, 'Compare it with 90°.', '{"why":"An acute angle is greater than 0° but less than 90°.","sol":"Step 1: 24° is less than 90°.\nStep 2: An angle between 0° and 90° is acute.","steps":["Step 1: 24° is less than 90°.","Step 2: An angle between 0° and 90° is acute."],"options":[],"conceptId":"math_geometry_classifying_angles","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Classifying Angles"}', 0),
  (270, 70, 'Classify an angle of 112°.', 'text', 1, 'Is it between 90° and 180°?', '{"why":"An obtuse angle is larger than a right angle but smaller than a straight angle.","sol":"Step 1: 90° < 112° < 180°.\nStep 2: An angle between 90° and 180° is obtuse.","steps":["Step 1: 90° < 112° < 180°.","Step 2: An angle between 90° and 180° is obtuse."],"options":[],"conceptId":"math_geometry_classifying_angles","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Classifying Angles"}', 1),
  (271, 70, 'An angle measures exactly 90°. What type is it?', 'text', 1, 'Think of a quarter-turn.', '{"why":"A right angle measures exactly 90°.","sol":"Step 1: The angle measures exactly 90°.\nStep 2: Therefore, it is a right angle.","steps":["Step 1: The angle measures exactly 90°.","Step 2: Therefore, it is a right angle."],"options":[],"conceptId":"math_geometry_classifying_angles","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Classifying Angles"}', 2),
  (272, 70, 'Can an angle of 180° be acute?', 'text', 1, 'An acute angle must be smaller than 90°.', '{"why":"Angle classification depends on the measured size.","sol":"Step 1: An acute angle is less than 90°.\nStep 2: 180° is a straight angle.\nStep 3: Therefore, it cannot be acute.","steps":["Step 1: An acute angle is less than 90°.","Step 2: 180° is a straight angle.","Step 3: Therefore, it cannot be acute."],"options":[],"conceptId":"math_geometry_classifying_angles","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Classifying Angles"}', 3),
  (273, 71, 'Two adjacent angles on a straight line are 127° and x°. Find x.', 'text', 1, 'Their sum is 180°.', '{"why":"Angles forming a straight line total 180°.","sol":"Step 1: 127° + x = 180°\nStep 2: x = 180° - 127°\nStep 3: x = 53°.","steps":["Step 1: 127° + x = 180°","Step 2: x = 180° - 127°","Step 3: x = 53°."],"options":[],"conceptId":"math_geometry_angles_on_a_straight_line","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Angles on a Straight Line"}', 0),
  (274, 71, 'Angles 2x° and 70° lie on a straight line. Find x.', 'text', 1, 'Write 2x + 70 = 180.', '{"why":"Use the straight-line angle sum to form an equation.","sol":"Step 1: 2x + 70 = 180\nStep 2: 2x = 110\nStep 3: x = 110 / 2\nStep 4: x = 55.","steps":["Step 1: 2x + 70 = 180","Step 2: 2x = 110","Step 3: x = 110 / 2","Step 4: x = 55."],"options":[],"conceptId":"math_geometry_angles_on_a_straight_line","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Angles on a Straight Line"}', 1),
  (275, 71, 'Three angles on a straight line are 42°, 91° and x°. Find x.', 'text', 1, 'Add the known angles, then subtract from 180°.', '{"why":"All adjacent angles forming the straight angle sum to 180°.","sol":"Step 1: 42° + 91° = 133°\nStep 2: 133° + x = 180°\nStep 3: x = 180° - 133°\nStep 4: x = 47°.","steps":["Step 1: 42° + 91° = 133°","Step 2: 133° + x = 180°","Step 3: x = 180° - 133°","Step 4: x = 47°."],"options":[],"conceptId":"math_geometry_angles_on_a_straight_line","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Angles on a Straight Line"}', 2),
  (276, 72, 'Angles around a point are 75°, 125° and x°. Find x.', 'text', 1, 'A complete turn is 360°.', '{"why":"Angles around a point make one complete turn of 360°.","sol":"Step 1: 75° + 125° = 200°\nStep 2: x = 360° - 200°\nStep 3: x = 160°.","steps":["Step 1: 75° + 125° = 200°","Step 2: x = 360° - 200°","Step 3: x = 160°."],"options":[],"conceptId":"math_geometry_angles_around_a_point","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Angles Around a Point"}', 0),
  (277, 72, 'Five equal angles meet at a point. Find each angle.', 'text', 1, 'Divide 360° equally among five angles.', '{"why":"Equal angles share the complete turn equally.","sol":"Step 1: Total angle = 360°\nStep 2: Each angle = 360° / 5\nStep 3: Each angle = 72°.","steps":["Step 1: Total angle = 360°","Step 2: Each angle = 360° / 5","Step 3: Each angle = 72°."],"options":[],"conceptId":"math_geometry_angles_around_a_point","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Angles Around a Point"}', 1),
  (278, 72, 'Angles x°, 2x°, 3x° and 60° meet at a point. Find x.', 'text', 1, 'Their sum is 360°.', '{"why":"Use the 360° total to form an equation.","sol":"Step 1: x + 2x + 3x + 60 = 360\nStep 2: 6x + 60 = 360\nStep 3: 6x = 300\nStep 4: x = 50.","steps":["Step 1: x + 2x + 3x + 60 = 360","Step 2: 6x + 60 = 360","Step 3: 6x = 300","Step 4: x = 50."],"options":[],"conceptId":"math_geometry_angles_around_a_point","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Angles Around a Point"}', 2),
  (279, 73, 'Two straight lines cross. One angle is 83°. Find the vertically opposite angle.', 'text', 1, 'Opposite angles formed by intersecting lines are equal.', '{"why":"Vertically opposite angles are equal.","sol":"Step 1: The given angle is 83°.\nStep 2: The opposite angle equals it.\nStep 3: Answer = 83°.","steps":["Step 1: The given angle is 83°.","Step 2: The opposite angle equals it.","Step 3: Answer = 83°."],"options":[],"conceptId":"math_geometry_vertically_opposite_angles","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Vertically Opposite Angles"}', 0),
  (280, 73, 'Opposite angles are (5x - 8)° and 72°. Find x.', 'text', 1, 'Set the two angle expressions equal.', '{"why":"Equal vertically opposite angles give an equation.","sol":"Step 1: 5x - 8 = 72\nStep 2: 5x = 80\nStep 3: x = 16.","steps":["Step 1: 5x - 8 = 72","Step 2: 5x = 80","Step 3: x = 16."],"options":[],"conceptId":"math_geometry_vertically_opposite_angles","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Vertically Opposite Angles"}', 1),
  (281, 73, 'An angle at an intersection is 121°. Find the smaller adjacent angle.', 'text', 1, 'Adjacent angles on a straight line total 180°.', '{"why":"The adjacent angle and 121° form a straight angle.","sol":"Step 1: Adjacent angle = 180° - 121°\nStep 2: Adjacent angle = 59°.","steps":["Step 1: Adjacent angle = 180° - 121°","Step 2: Adjacent angle = 59°."],"options":[],"conceptId":"math_geometry_vertically_opposite_angles","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Vertically Opposite Angles"}', 2),
  (282, 74, 'Two parallel lines are crossed by a transversal. A corresponding angle is 74°. Find its partner.', 'text', 1, 'Corresponding angles are equal for parallel lines.', '{"why":"Corresponding angles are equal when the lines are parallel.","sol":"Step 1: The lines are parallel.\nStep 2: Corresponding angles are equal.\nStep 3: The required angle is 74°.","steps":["Step 1: The lines are parallel.","Step 2: Corresponding angles are equal.","Step 3: The required angle is 74°."],"options":[],"conceptId":"math_geometry_parallel_lines_and_a_transversal","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Parallel Lines and a Transversal"}', 0),
  (283, 74, 'One alternate interior angle is 126°. Find the other alternate interior angle.', 'text', 1, 'Alternate interior angles are equal.', '{"why":"The alternate interior angle rule applies to parallel lines.","sol":"Step 1: The lines are parallel.\nStep 2: Alternate interior angles are equal.\nStep 3: The required angle is 126°.","steps":["Step 1: The lines are parallel.","Step 2: Alternate interior angles are equal.","Step 3: The required angle is 126°."],"options":[],"conceptId":"math_geometry_parallel_lines_and_a_transversal","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Parallel Lines and a Transversal"}', 1),
  (284, 74, 'Co-interior angles are (2x + 10)° and 110°. Find x.', 'text', 1, 'Co-interior angles add up to 180°.', '{"why":"Co-interior angles on parallel lines are supplementary.","sol":"Step 1: 2x + 10 + 110 = 180\nStep 2: 2x + 120 = 180\nStep 3: 2x = 60\nStep 4: x = 30.","steps":["Step 1: 2x + 10 + 110 = 180","Step 2: 2x + 120 = 180","Step 3: 2x = 60","Step 4: x = 30."],"options":[],"conceptId":"math_geometry_parallel_lines_and_a_transversal","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Parallel Lines and a Transversal"}', 2),
  (285, 74, 'A co-interior angle is 97°. Find the other angle.', 'text', 1, 'Subtract 97° from 180°.', '{"why":"The two co-interior angles add up to 180°.","sol":"Step 1: Other angle = 180° - 97°\nStep 2: Other angle = 83°.","steps":["Step 1: Other angle = 180° - 97°","Step 2: Other angle = 83°."],"options":[],"conceptId":"math_geometry_parallel_lines_and_a_transversal","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Parallel Lines and a Transversal"}', 3),
  (286, 75, 'A triangle has angles 45°, 65° and x°. Find x.', 'text', 1, 'Add 45° and 65°, then subtract their sum from 180°.', '{"why":"The missing angle is the difference between 180° and the sum of the two known angles.","sol":"Step 1: The interior angles of a triangle add up to 180°.\nStep 2: 45° + 65° + x = 180°.\nStep 3: 110° + x = 180°.\nStep 4: x = 180° - 110° = 70°.","steps":["Step 1: The interior angles of a triangle add up to 180°.","Step 2: 45° + 65° + x = 180°.","Step 3: 110° + x = 180°.","Step 4: x = 180° - 110° = 70°."],"options":[],"conceptId":"math_geometry_triangle_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Triangle Angle Sum"}', 0),
  (287, 75, 'Two angles of a triangle are 28° and 92°. Calculate the third angle.', 'text', 1, 'Find 28° + 92° first.', '{"why":"The three interior angles must total exactly 180°.","sol":"Step 1: Add the known angles: 28° + 92° = 120°.\nStep 2: Subtract their sum from 180°.\nStep 3: x = 180° - 120° = 60°.","steps":["Step 1: Add the known angles: 28° + 92° = 120°.","Step 2: Subtract their sum from 180°.","Step 3: x = 180° - 120° = 60°."],"options":[],"conceptId":"math_geometry_triangle_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Triangle Angle Sum"}', 1),
  (288, 75, 'The angles of a triangle are x°, 2x° and 30°. Find x.', 'text', 1, 'Form the equation x + 2x + 30 = 180.', '{"why":"The equation represents all three angles. Substituting x = 50° gives 50°, 100° and 30°, which total 180°.","sol":"Step 1: Write the angle-sum equation: x + 2x + 30 = 180.\nStep 2: Collect like terms: 3x + 30 = 180.\nStep 3: Subtract 30: 3x = 150.\nStep 4: Divide by 3: x = 50°.","steps":["Step 1: Write the angle-sum equation: x + 2x + 30 = 180.","Step 2: Collect like terms: 3x + 30 = 180.","Step 3: Subtract 30: 3x = 150.","Step 4: Divide by 3: x = 50°."],"options":[],"conceptId":"math_geometry_triangle_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Triangle Angle Sum"}', 2),
  (289, 76, 'An isosceles triangle has a top angle of 36°. Find each base angle.', 'text', 1, 'Subtract 36° from 180°, then divide the result by 2.', '{"why":"The base angles are equal and together they must total 144°.","sol":"Step 1: The two base angles share the remaining angle sum.\nStep 2: 180° - 36° = 144°.\nStep 3: 144° ÷ 2 = 72°.\nStep 4: Each base angle is 72°.","steps":["Step 1: The two base angles share the remaining angle sum.","Step 2: 180° - 36° = 144°.","Step 3: 144° ÷ 2 = 72°.","Step 4: Each base angle is 72°."],"options":[],"conceptId":"math_geometry_isosceles_triangle_base_angles","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Isosceles Triangle Base Angles"}', 0),
  (290, 76, 'Each base angle of an isosceles triangle is 48°. Find its top angle.', 'text', 1, 'Add the base angles before subtracting from 180°.', '{"why":"The top angle is the remaining part of the triangle''s 180° angle sum.","sol":"Step 1: Add the base angles: 48° + 48° = 96°.\nStep 2: Subtract from 180°: 180° - 96° = 84°.","steps":["Step 1: Add the base angles: 48° + 48° = 96°.","Step 2: Subtract from 180°: 180° - 96° = 84°."],"options":[],"conceptId":"math_geometry_isosceles_triangle_base_angles","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Isosceles Triangle Base Angles"}', 1),
  (291, 76, 'An isosceles triangle has angles x°, x° and 4x°. Find x.', 'text', 1, 'Write x + x + 4x = 180.', '{"why":"The two equal base angles are both 30°, while the third angle is four times x.","sol":"Step 1: Combine the angles: x + x + 4x = 180.\nStep 2: Simplify: 6x = 180.\nStep 3: Divide by 6: x = 30°.\nStep 4: The angles are 30°, 30° and 120°.","steps":["Step 1: Combine the angles: x + x + 4x = 180.","Step 2: Simplify: 6x = 180.","Step 3: Divide by 6: x = 30°.","Step 4: The angles are 30°, 30° and 120°."],"options":[],"conceptId":"math_geometry_isosceles_triangle_base_angles","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Isosceles Triangle Base Angles"}', 2),
  (292, 77, 'The two opposite interior angles of a triangle are 38° and 72°. Find the exterior angle.', 'text', 1, 'Add the two opposite interior angles.', '{"why":"An exterior angle equals the sum of the two opposite interior angles.","sol":"Step 1: Use the exterior angle rule.\nStep 2: Exterior angle = 38° + 72°.\nStep 3: Exterior angle = 110°.","steps":["Step 1: Use the exterior angle rule.","Step 2: Exterior angle = 38° + 72°.","Step 3: Exterior angle = 110°."],"options":[],"conceptId":"math_geometry_exterior_angle_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Exterior Angle of a Triangle"}', 0),
  (293, 77, 'An exterior angle is 132°. One opposite interior angle is 57°. Find the other opposite interior angle.', 'text', 1, 'Subtract 57° from 132°.', '{"why":"The two opposite interior angles together equal the exterior angle.","sol":"Step 1: Let the missing angle be x.\nStep 2: 132° = 57° + x.\nStep 3: x = 132° - 57°.\nStep 4: x = 75°.","steps":["Step 1: Let the missing angle be x.","Step 2: 132° = 57° + x.","Step 3: x = 132° - 57°.","Step 4: x = 75°."],"options":[],"conceptId":"math_geometry_exterior_angle_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Exterior Angle of a Triangle"}', 1),
  (294, 77, 'An exterior angle of a triangle is 118°. Calculate the interior angle next to it.', 'text', 1, 'The two adjacent angles on a straight line add up to 180°.', '{"why":"The adjacent interior and exterior angles form a straight line, so they add up to 180°.","sol":"Step 1: Let the adjacent interior angle be x.\nStep 2: x + 118° = 180°.\nStep 3: x = 180° - 118°.\nStep 4: x = 62°.","steps":["Step 1: Let the adjacent interior angle be x.","Step 2: x + 118° = 180°.","Step 3: x = 180° - 118°.","Step 4: x = 62°."],"options":[],"conceptId":"math_geometry_exterior_angle_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Exterior Angle of a Triangle"}', 2),
  (295, 78, 'A triangle has sides 9 cm, 9 cm and 9 cm. Classify it by its sides.', 'text', 1, 'Check whether all three lengths are equal.', '{"why":"An equilateral triangle has three equal sides.","sol":"Step 1: Compare the three side lengths.\nStep 2: All three sides are 9 cm.\nStep 3: Therefore, the triangle is equilateral.","steps":["Step 1: Compare the three side lengths.","Step 2: All three sides are 9 cm.","Step 3: Therefore, the triangle is equilateral."],"options":[],"conceptId":"math_geometry_classifying_triangles_by_sides","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Classifying Triangles by Sides"}', 0),
  (296, 78, 'A triangle has sides 8 cm, 8 cm and 5 cm. Classify it by its sides.', 'text', 1, 'Count how many sides have the same length.', '{"why":"An isosceles triangle has two equal sides.","sol":"Step 1: Two sides are 8 cm.\nStep 2: The third side is 5 cm.\nStep 3: Exactly two sides are equal, so it is isosceles.","steps":["Step 1: Two sides are 8 cm.","Step 2: The third side is 5 cm.","Step 3: Exactly two sides are equal, so it is isosceles."],"options":[],"conceptId":"math_geometry_classifying_triangles_by_sides","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Classifying Triangles by Sides"}', 1),
  (297, 78, 'A learner says a triangle with sides 3 cm, 4 cm and 8 cm is scalene. Is the learner correct?', 'text', 1, 'Before classifying, check whether the lengths can form a triangle.', '{"why":"Having three different lengths is not enough. The sum of the two shorter sides must be greater than the longest side.","sol":"Step 1: Add the two shorter sides: 3 + 4 = 7.\nStep 2: Compare this sum with the longest side, 8.\nStep 3: Since 7 is not greater than 8, the triangle inequality fails.\nStep 4: These lengths cannot form a triangle, so classifying them as a scalene triangle is incorrect.","steps":["Step 1: Add the two shorter sides: 3 + 4 = 7.","Step 2: Compare this sum with the longest side, 8.","Step 3: Since 7 is not greater than 8, the triangle inequality fails.","Step 4: These lengths cannot form a triangle, so classifying them as a scalene triangle is incorrect."],"options":[],"conceptId":"math_geometry_classifying_triangles_by_sides","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Classifying Triangles by Sides"}', 2),
  (298, 79, 'A right-angled triangle has shorter sides of 9 cm and 12 cm. Find the hypotenuse.', 'text', 1, 'Use c² = 9² + 12².', '{"why":"The hypotenuse is found by adding the squares of the two shorter sides and then taking the square root.","sol":"Step 1: c² = 9² + 12².\nStep 2: c² = 81 + 144.\nStep 3: c² = 225.\nStep 4: c = √225.\nStep 5: c = 15 cm.","steps":["Step 1: c² = 9² + 12².","Step 2: c² = 81 + 144.","Step 3: c² = 225.","Step 4: c = √225.","Step 5: c = 15 cm."],"options":[],"conceptId":"math_geometry_pythagoras_theorem","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Pythagoras'' Theorem"}', 0),
  (299, 79, 'A right-angled triangle has a hypotenuse of 17 m and one shorter side of 8 m. Find the other shorter side.', 'text', 1, 'Use b² = c² - a².', '{"why":"When finding a shorter side, subtract the square of the known shorter side from the square of the hypotenuse.","sol":"Step 1: 17² = 8² + b².\nStep 2: 289 = 64 + b².\nStep 3: 289 - 64 = b².\nStep 4: 225 = b².\nStep 5: b = √225.\nStep 6: b = 15 m.","steps":["Step 1: 17² = 8² + b².","Step 2: 289 = 64 + b².","Step 3: 289 - 64 = b².","Step 4: 225 = b².","Step 5: b = √225.","Step 6: b = 15 m."],"options":[],"conceptId":"math_geometry_pythagoras_theorem","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Pythagoras'' Theorem"}', 1),
  (300, 79, 'A learner uses 10² = 6² - 8² to find the hypotenuse of a triangle with shorter sides 6 cm and 8 cm. Identify the error and find the correct hypotenuse.', 'text', 1, 'When finding the hypotenuse, the two shorter-side squares are added.', '{"why":"The learner subtracted the squares. To find the hypotenuse, the squares of the two shorter sides must be added.","sol":"Step 1: The hypotenuse is found using c² = a² + b².\nStep 2: c² = 6² + 8².\nStep 3: c² = 36 + 64.\nStep 4: c² = 100.\nStep 5: c = √100.\nStep 6: c = 10 cm.","steps":["Step 1: The hypotenuse is found using c² = a² + b².","Step 2: c² = 6² + 8².","Step 3: c² = 36 + 64.","Step 4: c² = 100.","Step 5: c = √100.","Step 6: c = 10 cm."],"options":[],"conceptId":"math_geometry_pythagoras_theorem","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Pythagoras'' Theorem"}', 2),
  (301, 79, 'The sides of a triangle are 7 cm, 24 cm and 25 cm. The triangle is right-angled. Verify Pythagoras'' theorem.', 'text', 1, 'The longest side is the hypotenuse.', '{"why":"The square of the hypotenuse equals the sum of the squares of the two shorter sides.","sol":"Step 1: The hypotenuse is 25 cm.\nStep 2: 25² = 625.\nStep 3: 7² + 24² = 49 + 576.\nStep 4: 7² + 24² = 625.\nStep 5: Therefore, 25² = 7² + 24².","steps":["Step 1: The hypotenuse is 25 cm.","Step 2: 25² = 625.","Step 3: 7² + 24² = 49 + 576.","Step 4: 7² + 24² = 625.","Step 5: Therefore, 25² = 7² + 24²."],"options":[],"conceptId":"math_geometry_pythagoras_theorem","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Pythagoras'' Theorem"}', 3),
  (302, 80, 'Three angles of a quadrilateral are 70°, 110° and 95°. Find the fourth angle.', 'text', 1, 'Add the three known angles and subtract from 360°.', '{"why":"The four interior angles of a quadrilateral total 360°.","sol":"Step 1: Add the known angles: 70° + 110° + 95° = 275°.\nStep 2: Subtract from 360°: 360° - 275° = 85°.","steps":["Step 1: Add the known angles: 70° + 110° + 95° = 275°.","Step 2: Subtract from 360°: 360° - 275° = 85°."],"options":[],"conceptId":"math_geometry_quadrilateral_interior_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Quadrilateral Interior Angle Sum"}', 0),
  (303, 80, 'A quadrilateral has angles 90°, 90°, 90° and x°. Find x.', 'text', 1, 'Three right angles total 270°.', '{"why":"The missing angle must complete the quadrilateral''s 360° total.","sol":"Step 1: Add the known angles: 90° + 90° + 90° = 270°.\nStep 2: Subtract from 360°: x = 360° - 270°.\nStep 3: Therefore, x = 90°.","steps":["Step 1: Add the known angles: 90° + 90° + 90° = 270°.","Step 2: Subtract from 360°: x = 360° - 270°.","Step 3: Therefore, x = 90°."],"options":[],"conceptId":"math_geometry_quadrilateral_interior_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Quadrilateral Interior Angle Sum"}', 1),
  (304, 80, 'The angles of a quadrilateral are x°, 2x°, 3x° and 60°. Find x.', 'text', 1, 'Form the equation x + 2x + 3x + 60 = 360.', '{"why":"The four angles must total 360°. Substitution gives 50°, 100°, 150° and 60°, which total 360°.","sol":"Step 1: Add the angles: x + 2x + 3x + 60 = 360.\nStep 2: Collect like terms: 6x + 60 = 360.\nStep 3: Subtract 60: 6x = 300.\nStep 4: Divide by 6: x = 50°.","steps":["Step 1: Add the angles: x + 2x + 3x + 60 = 360.","Step 2: Collect like terms: 6x + 60 = 360.","Step 3: Subtract 60: 6x = 300.","Step 4: Divide by 6: x = 50°."],"options":[],"conceptId":"math_geometry_quadrilateral_interior_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Quadrilateral Interior Angle Sum"}', 2),
  (305, 81, 'A parallelogram has AB = 14 cm. If CD is opposite AB, find CD.', 'text', 1, 'Opposite sides of a parallelogram are equal.', '{"why":"Opposite sides of a parallelogram have equal lengths.","sol":"Step 1: AB and CD are opposite sides.\nStep 2: Therefore, AB = CD.\nStep 3: CD = 14 cm.","steps":["Step 1: AB and CD are opposite sides.","Step 2: Therefore, AB = CD.","Step 3: CD = 14 cm."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_sides_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Sides Are Equal"}', 0),
  (306, 81, 'Opposite sides of a parallelogram are (4x - 3) cm and 21 cm. Find x.', 'text', 1, 'Set 4x - 3 equal to 21.', '{"why":"The two expressions describe opposite sides, which must have equal lengths.","sol":"Step 1: Set the opposite sides equal: 4x - 3 = 21.\nStep 2: Add 3 to both sides: 4x = 24.\nStep 3: Divide both sides by 4: x = 6.","steps":["Step 1: Set the opposite sides equal: 4x - 3 = 21.","Step 2: Add 3 to both sides: 4x = 24.","Step 3: Divide both sides by 4: x = 6."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_sides_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Sides Are Equal"}', 1),
  (307, 81, 'A parallelogram has adjacent sides of 11 cm and 7 cm. A learner says every side must be 11 cm. Explain the error and calculate the perimeter.', 'text', 1, 'Only opposite sides must be equal. Add all four sides.', '{"why":"A parallelogram has equal opposite sides, not necessarily four equal sides.","sol":"Step 1: The side lengths are 11 cm, 7 cm, 11 cm and 7 cm.\nStep 2: The sides of length 11 cm are opposite each other.\nStep 3: The sides of length 7 cm are also opposite each other.\nStep 4: Perimeter = 11 + 7 + 11 + 7 = 36 cm.","steps":["Step 1: The side lengths are 11 cm, 7 cm, 11 cm and 7 cm.","Step 2: The sides of length 11 cm are opposite each other.","Step 3: The sides of length 7 cm are also opposite each other.","Step 4: Perimeter = 11 + 7 + 11 + 7 = 36 cm."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_sides_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Sides Are Equal"}', 2),
  (308, 82, 'One angle of a parallelogram is 112°. Find its opposite angle.', 'text', 1, 'Opposite angles are equal.', '{"why":"Opposite angles of a parallelogram have equal measures.","sol":"Step 1: Identify the angle opposite 112°.\nStep 2: Opposite angles are equal.\nStep 3: The missing angle is 112°.","steps":["Step 1: Identify the angle opposite 112°.","Step 2: Opposite angles are equal.","Step 3: The missing angle is 112°."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_angles_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Angles Are Equal"}', 0),
  (309, 82, 'Opposite angles are (5x - 20)° and 80°. Find x.', 'text', 1, 'Set 5x - 20 equal to 80.', '{"why":"The angles are opposite, so their expressions must have equal values.","sol":"Step 1: Write 5x - 20 = 80.\nStep 2: Add 20 to both sides: 5x = 100.\nStep 3: Divide by 5: x = 20.","steps":["Step 1: Write 5x - 20 = 80.","Step 2: Add 20 to both sides: 5x = 100.","Step 3: Divide by 5: x = 20."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_angles_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Angles Are Equal"}', 1),
  (310, 82, 'A parallelogram has one angle of 64°. Find the other three angles.', 'text', 1, 'The opposite angle equals 64°. Each adjacent angle is 180° - 64°.', '{"why":"Opposite angles are equal, while adjacent angles are supplementary.","sol":"Step 1: The opposite angle is 64°.\nStep 2: Calculate each adjacent angle: 180° - 64° = 116°.\nStep 3: The four angles are 64°, 116°, 64° and 116°.","steps":["Step 1: The opposite angle is 64°.","Step 2: Calculate each adjacent angle: 180° - 64° = 116°.","Step 3: The four angles are 64°, 116°, 64° and 116°."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_angles_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Angles Are Equal"}', 2),
  (311, 83, 'One angle of a parallelogram is 83°. Find an adjacent angle.', 'text', 1, 'Subtract 83° from 180°.', '{"why":"The adjacent angle must complete the 180° total.","sol":"Step 1: Adjacent angles add to 180°.\nStep 2: 83° + x = 180°.\nStep 3: x = 180° - 83° = 97°.","steps":["Step 1: Adjacent angles add to 180°.","Step 2: 83° + x = 180°.","Step 3: x = 180° - 83° = 97°."],"options":[],"conceptId":"math_geometry_parallelogram_adjacent_angles","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Parallelogram: Adjacent Angles"}', 0),
  (312, 83, 'Adjacent angles are (4x + 5)° and 95°. Find x.', 'text', 1, 'Their sum is 180°.', '{"why":"Adjacent angles in a parallelogram are supplementary.","sol":"Step 1: Write 4x + 5 + 95 = 180.\nStep 2: Simplify: 4x + 100 = 180.\nStep 3: Subtract 100: 4x = 80.\nStep 4: Divide by 4: x = 20.","steps":["Step 1: Write 4x + 5 + 95 = 180.","Step 2: Simplify: 4x + 100 = 180.","Step 3: Subtract 100: 4x = 80.","Step 4: Divide by 4: x = 20."],"options":[],"conceptId":"math_geometry_parallelogram_adjacent_angles","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Parallelogram: Adjacent Angles"}', 1),
  (313, 83, 'Two adjacent angles of a parallelogram are in the ratio 4:5. Find both angles.', 'text', 1, 'Represent the angles as 4x and 5x and use their 180° sum.', '{"why":"The ratio gives the relative sizes, and the supplementary-angle rule supplies their total.","sol":"Step 1: Let the angles be 4x and 5x.\nStep 2: 4x + 5x = 180.\nStep 3: 9x = 180, so x = 20.\nStep 4: The angles are 4(20) = 80° and 5(20) = 100°.","steps":["Step 1: Let the angles be 4x and 5x.","Step 2: 4x + 5x = 180.","Step 3: 9x = 180, so x = 20.","Step 4: The angles are 4(20) = 80° and 5(20) = 100°."],"options":[],"conceptId":"math_geometry_parallelogram_adjacent_angles","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Parallelogram: Adjacent Angles"}', 2),
  (314, 84, 'A circle has radius 7 cm. Calculate its diameter.', 'text', 1, 'Multiply the radius by 2.', '{"why":"A diameter consists of two radii placed end to end through the centre.","sol":"Step 1: Diameter = 2 × radius.\nStep 2: Diameter = 2 × 7.\nStep 3: Diameter = 14 cm.","steps":["Step 1: Diameter = 2 × radius.","Step 2: Diameter = 2 × 7.","Step 3: Diameter = 14 cm."],"options":[],"conceptId":"math_geometry_circle_radius_and_diameter","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Circle: Radius and Diameter"}', 0),
  (315, 84, 'The diameter of a circle is 26 cm. Find its radius.', 'text', 1, 'Divide the diameter by 2.', '{"why":"The radius is half the diameter.","sol":"Step 1: Radius = diameter ÷ 2.\nStep 2: Radius = 26 ÷ 2.\nStep 3: Radius = 13 cm.","steps":["Step 1: Radius = diameter ÷ 2.","Step 2: Radius = 26 ÷ 2.","Step 3: Radius = 13 cm."],"options":[],"conceptId":"math_geometry_circle_radius_and_diameter","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Circle: Radius and Diameter"}', 1),
  (316, 84, 'A learner says a circle with radius 8 cm has diameter 8 cm. Identify the error and give the correct diameter.', 'text', 1, 'The learner has treated the radius and diameter as the same length.', '{"why":"The diameter passes through the centre and spans two radii.","sol":"Step 1: The radius is 8 cm.\nStep 2: Diameter = 2 × radius.\nStep 3: Diameter = 2 × 8 = 16 cm.\nStep 4: The learner forgot that the diameter is twice the radius.","steps":["Step 1: The radius is 8 cm.","Step 2: Diameter = 2 × radius.","Step 3: Diameter = 2 × 8 = 16 cm.","Step 4: The learner forgot that the diameter is twice the radius."],"options":[],"conceptId":"math_geometry_circle_radius_and_diameter","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Circle: Radius and Diameter"}', 2),
  (317, 85, 'A circle has radius 5 cm. Find its circumference in terms of π.', 'text', 1, 'Use C = 2πr.', '{"why":"The radius formula multiplies the radius by 2π.","sol":"Step 1: Use C = 2πr.\nStep 2: Substitute r = 5.\nStep 3: C = 2 × π × 5 = 10π cm.","steps":["Step 1: Use C = 2πr.","Step 2: Substitute r = 5.","Step 3: C = 2 × π × 5 = 10π cm."],"options":[],"conceptId":"math_geometry_circumference_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Circumference of a Circle"}', 0),
  (318, 85, 'A circle has diameter 14 m. Find its circumference in terms of π.', 'text', 1, 'Use C = πd because the diameter is given.', '{"why":"The circumference equals π multiplied by the diameter.","sol":"Step 1: Use C = πd.\nStep 2: Substitute d = 14.\nStep 3: C = 14π m.","steps":["Step 1: Use C = πd.","Step 2: Substitute d = 14.","Step 3: C = 14π m."],"options":[],"conceptId":"math_geometry_circumference_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Circumference of a Circle"}', 1),
  (319, 85, 'A learner calculates the circumference of a circle with radius 4 cm as 16π cm². Identify the error and give the correct answer.', 'text', 1, 'Check both the formula and the unit.', '{"why":"The learner used an incorrect calculation and a square unit. Circumference is a one-dimensional length.","sol":"Step 1: Use C = 2πr.\nStep 2: Substitute r = 4: C = 2 × π × 4.\nStep 3: C = 8π cm.\nStep 4: Circumference is a length, so the unit is cm, not cm².","steps":["Step 1: Use C = 2πr.","Step 2: Substitute r = 4: C = 2 × π × 4.","Step 3: C = 8π cm.","Step 4: Circumference is a length, so the unit is cm, not cm²."],"options":[],"conceptId":"math_geometry_circumference_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Circumference of a Circle"}', 2),
  (320, 86, 'A circle has a radius of 6 cm. Find its area. Use π = 3.142.', 'text', 1, 'Use A = πr² and remember to square the radius.', '{"why":"The area of a circle is found by multiplying π by the square of its radius.","sol":"Step 1: A = πr².\nStep 2: A = 3.142 × 6².\nStep 3: 6² = 36.\nStep 4: A = 3.142 × 36.\nStep 5: A = 113.112 cm².","steps":["Step 1: A = πr².","Step 2: A = 3.142 × 6².","Step 3: 6² = 36.","Step 4: A = 3.142 × 36.","Step 5: A = 113.112 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Circle"}', 0),
  (321, 86, 'A circle has a diameter of 14 cm. Find its area. Use π = 22/7.', 'text', 1, 'Find the radius first.', '{"why":"The area formula requires the radius, so the diameter must first be divided by 2.","sol":"Step 1: Radius = diameter ÷ 2.\nStep 2: r = 14 ÷ 2 = 7 cm.\nStep 3: A = πr².\nStep 4: A = 22/7 × 7².\nStep 5: A = 22/7 × 49.\nStep 6: A = 154 cm².","steps":["Step 1: Radius = diameter ÷ 2.","Step 2: r = 14 ÷ 2 = 7 cm.","Step 3: A = πr².","Step 4: A = 22/7 × 7².","Step 5: A = 22/7 × 49.","Step 6: A = 154 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Circle"}', 1),
  (322, 86, 'A circle has a radius of 8 m. Find its area using π = 3.142.', 'text', 1, 'Square 8 before multiplying by π.', '{"why":"The radius is squared before multiplying by π.","sol":"Step 1: A = πr².\nStep 2: A = 3.142 × 8².\nStep 3: 8² = 64.\nStep 4: A = 3.142 × 64.\nStep 5: A = 201.088 m².","steps":["Step 1: A = πr².","Step 2: A = 3.142 × 8².","Step 3: 8² = 64.","Step 4: A = 3.142 × 64.","Step 5: A = 201.088 m²."],"options":[],"conceptId":"math_geometry_area_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Circle"}', 2),
  (323, 86, 'A learner says that the area of a circle with radius 5 cm is 31.42 cm². Identify the error and calculate the correct area using π = 3.142.', 'text', 1, 'Check whether the radius was squared.', '{"why":"The learner multiplied π by 5 instead of multiplying π by 5².","sol":"Step 1: A = πr².\nStep 2: A = 3.142 × 5².\nStep 3: 5² = 25.\nStep 4: A = 3.142 × 25.\nStep 5: A = 78.55 cm².","steps":["Step 1: A = πr².","Step 2: A = 3.142 × 5².","Step 3: 5² = 25.","Step 4: A = 3.142 × 25.","Step 5: A = 78.55 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Area of a Circle"}', 3),
  (324, 87, 'A rectangle has length 12 cm and width 5 cm. Find its perimeter.', 'text', 1, 'Use P = 2(l + w).', '{"why":"The formula adds the length and width and doubles their sum to include all four sides.","sol":"Step 1: Write P = 2(l + w).\nStep 2: Substitute: P = 2(12 + 5).\nStep 3: P = 2 × 17 = 34 cm.","steps":["Step 1: Write P = 2(l + w).","Step 2: Substitute: P = 2(12 + 5).","Step 3: P = 2 × 17 = 34 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Perimeter of a Rectangle"}', 0),
  (325, 87, 'A rectangle has perimeter 40 m and length 13 m. Find its width.', 'text', 1, 'Start with 40 = 2(13 + w).', '{"why":"Half the perimeter equals one length plus one width.","sol":"Step 1: 40 = 2(13 + w).\nStep 2: Divide by 2: 20 = 13 + w.\nStep 3: Subtract 13: w = 7 m.","steps":["Step 1: 40 = 2(13 + w).","Step 2: Divide by 2: 20 = 13 + w.","Step 3: Subtract 13: w = 7 m."],"options":[],"conceptId":"math_geometry_perimeter_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Perimeter of a Rectangle"}', 1),
  (326, 87, 'A learner calculates the perimeter of a 7 cm by 4 cm rectangle as 28 cm. Explain the mistake and give the correct perimeter.', 'text', 1, 'Check whether the learner multiplied the dimensions instead of adding all four sides.', '{"why":"Perimeter adds boundary lengths; multiplying length by width calculates area.","sol":"Step 1: Multiplying 7 × 4 gives 28, which is the area in cm².\nStep 2: Perimeter = 2(7 + 4).\nStep 3: Perimeter = 2 × 11 = 22 cm.","steps":["Step 1: Multiplying 7 × 4 gives 28, which is the area in cm².","Step 2: Perimeter = 2(7 + 4).","Step 3: Perimeter = 2 × 11 = 22 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Perimeter of a Rectangle"}', 2),
  (327, 88, 'A square has sides of 11 cm. Find its perimeter.', 'text', 1, 'Multiply one side by 4.', '{"why":"A square has four equal sides.","sol":"Step 1: P = 4s.\nStep 2: P = 4 × 11.\nStep 3: P = 44 cm.","steps":["Step 1: P = 4s.","Step 2: P = 4 × 11.","Step 3: P = 44 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Perimeter of a Square"}', 0),
  (328, 88, 'The perimeter of a square is 52 m. Find the length of one side.', 'text', 1, 'Divide the perimeter by 4.', '{"why":"The total perimeter is shared equally among the four sides.","sol":"Step 1: P = 4s.\nStep 2: 52 = 4s.\nStep 3: s = 52 ÷ 4 = 13 m.","steps":["Step 1: P = 4s.","Step 2: 52 = 4s.","Step 3: s = 52 ÷ 4 = 13 m."],"options":[],"conceptId":"math_geometry_perimeter_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Perimeter of a Square"}', 1),
  (329, 88, 'A learner says a square with side 8 cm has perimeter 64 cm. Identify the error and calculate the correct perimeter.', 'text', 1, 'Compare 4 × side with side × side.', '{"why":"Perimeter uses four times the side length; squaring the side gives area.","sol":"Step 1: The learner calculated 8 × 8 = 64, which is the area in cm².\nStep 2: Perimeter = 4 × 8.\nStep 3: Perimeter = 32 cm.","steps":["Step 1: The learner calculated 8 × 8 = 64, which is the area in cm².","Step 2: Perimeter = 4 × 8.","Step 3: Perimeter = 32 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Perimeter of a Square"}', 2),
  (330, 89, 'A triangle has sides 6 cm, 8 cm and 11 cm. Find its perimeter.', 'text', 1, 'Add all three side lengths.', '{"why":"The perimeter is the total distance around the triangle.","sol":"Step 1: P = 6 + 8 + 11.\nStep 2: P = 25 cm.","steps":["Step 1: P = 6 + 8 + 11.","Step 2: P = 25 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Perimeter of a Triangle"}', 0),
  (331, 89, 'A triangle has perimeter 31 cm. Two sides measure 9 cm and 13 cm. Find the third side.', 'text', 1, 'Subtract the two known sides from the perimeter.', '{"why":"The missing side is the total perimeter minus the two known sides.","sol":"Step 1: Let the missing side be x.\nStep 2: 9 + 13 + x = 31.\nStep 3: 22 + x = 31.\nStep 4: x = 9 cm.","steps":["Step 1: Let the missing side be x.","Step 2: 9 + 13 + x = 31.","Step 3: 22 + x = 31.","Step 4: x = 9 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Perimeter of a Triangle"}', 1),
  (332, 89, 'An equilateral triangle has perimeter 57 cm. A learner says each side is 19 cm². Correct the answer and explain the unit.', 'text', 1, 'Divide by 3, and remember that side length is a distance.', '{"why":"Dividing the perimeter by three gives one side, which is a length.","sol":"Step 1: All three sides are equal.\nStep 2: Side length = 57 ÷ 3 = 19.\nStep 3: The correct side length is 19 cm, not 19 cm².\nStep 4: Centimetres measure length; square centimetres measure area.","steps":["Step 1: All three sides are equal.","Step 2: Side length = 57 ÷ 3 = 19.","Step 3: The correct side length is 19 cm, not 19 cm².","Step 4: Centimetres measure length; square centimetres measure area."],"options":[],"conceptId":"math_geometry_perimeter_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Perimeter of a Triangle"}', 2),
  (333, 90, 'A rectangle is 13 m long and 4 m wide. Find its area.', 'text', 1, 'Multiply length by width.', '{"why":"The rectangle''s surface is measured by multiplying its length by its width.","sol":"Step 1: A = l × w.\nStep 2: A = 13 × 4.\nStep 3: A = 52 m².","steps":["Step 1: A = l × w.","Step 2: A = 13 × 4.","Step 3: A = 52 m²."],"options":[],"conceptId":"math_geometry_area_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Rectangle"}', 0),
  (334, 90, 'A rectangle has area 96 cm² and width 8 cm. Find its length.', 'text', 1, 'Divide the area by the width.', '{"why":"Dividing area by one dimension gives the other dimension.","sol":"Step 1: A = l × w.\nStep 2: 96 = l × 8.\nStep 3: l = 96 ÷ 8.\nStep 4: l = 12 cm.","steps":["Step 1: A = l × w.","Step 2: 96 = l × 8.","Step 3: l = 96 ÷ 8.","Step 4: l = 12 cm."],"options":[],"conceptId":"math_geometry_area_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Rectangle"}', 1),
  (335, 90, 'A learner finds the area of a rectangle measuring 10 cm by 6 cm as 32 cm². Identify the likely mistake and calculate the correct area.', 'text', 1, 'Check whether the learner added the dimensions.', '{"why":"The area formula is length multiplied by width, not their sum.","sol":"Step 1: Adding the dimensions gives 10 + 6 = 16, not 32.\nStep 2: Area must be calculated by multiplication.\nStep 3: A = 10 × 6.\nStep 4: A = 60 cm².","steps":["Step 1: Adding the dimensions gives 10 + 6 = 16, not 32.","Step 2: Area must be calculated by multiplication.","Step 3: A = 10 × 6.","Step 4: A = 60 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Rectangle"}', 2),
  (336, 91, 'A square has side length 12 cm. Find its area.', 'text', 1, 'Multiply 12 by 12.', '{"why":"The area of a square is its side length multiplied by itself.","sol":"Step 1: A = s².\nStep 2: A = 12 × 12.\nStep 3: A = 144 cm².","steps":["Step 1: A = s².","Step 2: A = 12 × 12.","Step 3: A = 144 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Square"}', 0),
  (337, 91, 'A square has area 121 cm². Find its side length.', 'text', 1, 'Find the positive square root of 121.', '{"why":"The side length is the positive number whose square equals the area.","sol":"Step 1: A = s².\nStep 2: 121 = s².\nStep 3: s = √121 = 11 cm.","steps":["Step 1: A = s².","Step 2: 121 = s².","Step 3: s = √121 = 11 cm."],"options":[],"conceptId":"math_geometry_area_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Square"}', 1),
  (338, 91, 'A learner says a square with side 9 m has area 36 m² because 4 × 9 = 36. Explain the error and calculate the correct area.', 'text', 1, 'The learner used the perimeter calculation instead of the area formula.', '{"why":"Area squares the side length; multiplying by four calculates the perimeter.","sol":"Step 1: 4 × 9 calculates the perimeter, which is 36 m.\nStep 2: Area = side × side.\nStep 3: Area = 9 × 9 = 81 m².","steps":["Step 1: 4 × 9 calculates the perimeter, which is 36 m.","Step 2: Area = side × side.","Step 3: Area = 9 × 9 = 81 m²."],"options":[],"conceptId":"math_geometry_area_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Square"}', 2),
  (339, 92, 'A triangle has base 14 cm and perpendicular height 8 cm. Find its area.', 'text', 1, 'Multiply 14 by 8, then divide by 2.', '{"why":"The triangle occupies half the area of a rectangle with the same base and perpendicular height.","sol":"Step 1: A = ½ × b × h.\nStep 2: A = ½ × 14 × 8.\nStep 3: A = ½ × 112 = 56 cm².","steps":["Step 1: A = ½ × b × h.","Step 2: A = ½ × 14 × 8.","Step 3: A = ½ × 112 = 56 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Triangle"}', 0),
  (340, 92, 'A triangle has area 54 m² and base 12 m. Find its perpendicular height.', 'text', 1, 'Start with 54 = ½ × 12 × h.', '{"why":"Rearranging the area formula gives height = 2 × area ÷ base.","sol":"Step 1: 54 = ½ × 12 × h.\nStep 2: Simplify: 54 = 6h.\nStep 3: Divide by 6: h = 9 m.","steps":["Step 1: 54 = ½ × 12 × h.","Step 2: Simplify: 54 = 6h.","Step 3: Divide by 6: h = 9 m."],"options":[],"conceptId":"math_geometry_area_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Triangle"}', 1),
  (341, 92, 'A learner calculates the area of a triangle with base 9 cm and perpendicular height 4 cm as 36 cm². Identify the error and calculate the correct area.', 'text', 1, 'The learner multiplied base by height but forgot to take half.', '{"why":"The area formula includes the factor ½.","sol":"Step 1: Multiply base by height: 9 × 4 = 36.\nStep 2: Take half: 36 ÷ 2 = 18.\nStep 3: The correct area is 18 cm².","steps":["Step 1: Multiply base by height: 9 × 4 = 36.","Step 2: Take half: 36 ÷ 2 = 18.","Step 3: The correct area is 18 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Triangle"}', 2),
  (342, 93, 'A parallelogram has a base of 15 cm and a perpendicular height of 6 cm. Find its area.', 'text', 1, 'Use A = base × perpendicular height.', '{"why":"The area of a parallelogram is found by multiplying its base by its perpendicular height.","sol":"Step 1: A = b × h.\nStep 2: A = 15 × 6.\nStep 3: A = 90 cm².","steps":["Step 1: A = b × h.","Step 2: A = 15 × 6.","Step 3: A = 90 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_parallelogram","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Parallelogram"}', 0),
  (343, 93, 'A parallelogram has an area of 72 m² and a base of 9 m. Find its perpendicular height.', 'text', 1, 'Start with 72 = 9 × h.', '{"why":"When the area and base are known, divide the area by the base to find the perpendicular height.","sol":"Step 1: A = b × h.\nStep 2: 72 = 9 × h.\nStep 3: h = 72 ÷ 9.\nStep 4: h = 8 m.","steps":["Step 1: A = b × h.","Step 2: 72 = 9 × h.","Step 3: h = 72 ÷ 9.","Step 4: h = 8 m."],"options":[],"conceptId":"math_geometry_area_of_a_parallelogram","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Parallelogram"}', 1),
  (344, 93, 'A parallelogram has an area of 120 cm² and a perpendicular height of 8 cm. Find its base.', 'text', 1, 'Start with 120 = b × 8.', '{"why":"When the area and perpendicular height are known, divide the area by the height to find the base.","sol":"Step 1: A = b × h.\nStep 2: 120 = b × 8.\nStep 3: b = 120 ÷ 8.\nStep 4: b = 15 cm.","steps":["Step 1: A = b × h.","Step 2: 120 = b × 8.","Step 3: b = 120 ÷ 8.","Step 4: b = 15 cm."],"options":[],"conceptId":"math_geometry_area_of_a_parallelogram","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Parallelogram"}', 2),
  (345, 93, 'A learner uses the sloping side of a parallelogram as its height. Explain why this can give the wrong area.', 'text', 1, 'Think about what the word perpendicular means.', '{"why":"The formula A = base × height requires the perpendicular height, not simply any side length.","sol":"Step 1: The height must meet the base at 90°.\nStep 2: A sloping side may not meet the base at 90°.\nStep 3: Therefore, the sloping side cannot automatically be used as the height.\nStep 4: The perpendicular height must be used.","steps":["Step 1: The height must meet the base at 90°.","Step 2: A sloping side may not meet the base at 90°.","Step 3: Therefore, the sloping side cannot automatically be used as the height.","Step 4: The perpendicular height must be used."],"options":[],"conceptId":"math_geometry_area_of_a_parallelogram","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Area of a Parallelogram"}', 3),
  (346, 94, 'A trapezium has parallel sides of 7 cm and 13 cm and a perpendicular height of 6 cm. Find its area.', 'text', 1, 'Add the two parallel sides first, then multiply by half the height.', '{"why":"The area is half the sum of the two parallel sides multiplied by the perpendicular height.","sol":"Step 1: A = ½ × (a + b) × h.\nStep 2: A = ½ × (7 + 13) × 6.\nStep 3: A = ½ × 20 × 6.\nStep 4: A = 10 × 6.\nStep 5: A = 60 cm².","steps":["Step 1: A = ½ × (a + b) × h.","Step 2: A = ½ × (7 + 13) × 6.","Step 3: A = ½ × 20 × 6.","Step 4: A = 10 × 6.","Step 5: A = 60 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_trapezium","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Trapezium"}', 0),
  (347, 94, 'A trapezium has parallel sides of 12 m and 18 m and an area of 150 m². Find its perpendicular height.', 'text', 1, 'Substitute into 150 = ½ × (12 + 18) × h.', '{"why":"After adding the parallel sides and taking half, divide the area by that value to find the height.","sol":"Step 1: 150 = ½ × (12 + 18) × h.\nStep 2: 150 = ½ × 30 × h.\nStep 3: 150 = 15h.\nStep 4: h = 150 ÷ 15.\nStep 5: h = 10 m.","steps":["Step 1: 150 = ½ × (12 + 18) × h.","Step 2: 150 = ½ × 30 × h.","Step 3: 150 = 15h.","Step 4: h = 150 ÷ 15.","Step 5: h = 10 m."],"options":[],"conceptId":"math_geometry_area_of_a_trapezium","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Trapezium"}', 1),
  (348, 94, 'A trapezium has parallel sides of 9 cm and 15 cm and a perpendicular height of 8 cm. A learner calculates its area as 192 cm². Identify the error and find the correct area.', 'text', 1, 'Check whether the learner added the parallel sides and then multiplied by the height without taking half.', '{"why":"The learner forgot the factor ½. Without taking half, the result is twice the correct area.","sol":"Step 1: A = ½ × (9 + 15) × 8.\nStep 2: A = ½ × 24 × 8.\nStep 3: A = 12 × 8.\nStep 4: A = 96 cm².","steps":["Step 1: A = ½ × (9 + 15) × 8.","Step 2: A = ½ × 24 × 8.","Step 3: A = 12 × 8.","Step 4: A = 96 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_trapezium","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Trapezium"}', 2),
  (349, 94, 'A trapezium has parallel sides of 10 cm and 20 cm and a perpendicular height of 7 cm. Find its area.', 'text', 1, 'Use A = ½ × (a + b) × h.', '{"why":"The average of the parallel sides is 15 cm, and 15 × 7 gives the area.","sol":"Step 1: A = ½ × (10 + 20) × 7.\nStep 2: A = ½ × 30 × 7.\nStep 3: A = 15 × 7.\nStep 4: A = 105 cm².","steps":["Step 1: A = ½ × (10 + 20) × 7.","Step 2: A = ½ × 30 × 7.","Step 3: A = 15 × 7.","Step 4: A = 105 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_trapezium","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Area of a Trapezium"}', 3),
  (350, 95, 'Find the sum of the interior angles of an octagon.', 'text', 1, 'An octagon has 8 sides. Use (n − 2) × 180°.', '{"why":"An octagon can be divided into 6 triangles, and each triangle has an angle sum of 180°.","sol":"Step 1: n = 8.\nStep 2: Sum = (8 − 2) × 180°.\nStep 3: Sum = 6 × 180°.\nStep 4: Sum = 1080°.","steps":["Step 1: n = 8.","Step 2: Sum = (8 − 2) × 180°.","Step 3: Sum = 6 × 180°.","Step 4: Sum = 1080°."],"options":[],"conceptId":"math_geometry_interior_angle_sum_of_polygons","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Interior Angle Sum of Polygons"}', 0),
  (351, 95, 'A polygon has 10 sides. Find the sum of its interior angles.', 'text', 1, 'Substitute n = 10 into (n − 2) × 180°.', '{"why":"A 10-sided polygon can be divided into 8 triangles.","sol":"Step 1: n = 10.\nStep 2: Sum = (10 − 2) × 180°.\nStep 3: Sum = 8 × 180°.\nStep 4: Sum = 1440°.","steps":["Step 1: n = 10.","Step 2: Sum = (10 − 2) × 180°.","Step 3: Sum = 8 × 180°.","Step 4: Sum = 1440°."],"options":[],"conceptId":"math_geometry_interior_angle_sum_of_polygons","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Interior Angle Sum of Polygons"}', 1),
  (352, 95, 'A polygon has an interior angle sum of 1260°. How many sides does it have?', 'text', 1, 'Start with 1260 = (n − 2) × 180.', '{"why":"A polygon with 9 sides has 7 triangles, giving an interior angle sum of 7 × 180° = 1260°.","sol":"Step 1: 1260 = (n − 2) × 180.\nStep 2: 1260 ÷ 180 = n − 2.\nStep 3: 7 = n − 2.\nStep 4: n = 9.","steps":["Step 1: 1260 = (n − 2) × 180.","Step 2: 1260 ÷ 180 = n − 2.","Step 3: 7 = n − 2.","Step 4: n = 9."],"options":[],"conceptId":"math_geometry_interior_angle_sum_of_polygons","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Interior Angle Sum of Polygons"}', 2),
  (353, 95, 'A learner says that the interior angle sum of a hexagon is 1080°. Identify the error and find the correct answer.', 'text', 1, 'Check the number of triangles formed using n − 2.', '{"why":"The learner did not use the correct number of triangles. A hexagon forms 4 triangles, not 6.","sol":"Step 1: A hexagon has 6 sides.\nStep 2: Number of triangles = 6 − 2 = 4.\nStep 3: Interior angle sum = 4 × 180°.\nStep 4: Interior angle sum = 720°.","steps":["Step 1: A hexagon has 6 sides.","Step 2: Number of triangles = 6 − 2 = 4.","Step 3: Interior angle sum = 4 × 180°.","Step 4: Interior angle sum = 720°."],"options":[],"conceptId":"math_geometry_interior_angle_sum_of_polygons","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Interior Angle Sum of Polygons"}', 3),
  (354, 96, 'The exterior angles of a polygon are 90°, 80°, 70° and 60°. Find the fifth exterior angle.', 'text', 1, 'All exterior angles together add to 360°.', '{"why":"The exterior angles of a polygon make one complete turn, which is 360°.","sol":"Step 1: Total exterior angle sum = 360°.\nStep 2: 90° + 80° + 70° + 60° = 300°.\nStep 3: Missing angle = 360° − 300°.\nStep 4: Missing angle = 60°.","steps":["Step 1: Total exterior angle sum = 360°.","Step 2: 90° + 80° + 70° + 60° = 300°.","Step 3: Missing angle = 360° − 300°.","Step 4: Missing angle = 60°."],"options":[],"conceptId":"math_geometry_exterior_angles_of_a_polygon","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Exterior Angles of a Polygon"}', 0),
  (355, 96, 'Find each exterior angle of a regular pentagon.', 'text', 1, 'Divide 360° by the number of sides.', '{"why":"A regular polygon has equal exterior angles, and together they total 360°.","sol":"Step 1: A pentagon has 5 sides.\nStep 2: Each exterior angle = 360° ÷ 5.\nStep 3: Each exterior angle = 72°.","steps":["Step 1: A pentagon has 5 sides.","Step 2: Each exterior angle = 360° ÷ 5.","Step 3: Each exterior angle = 72°."],"options":[],"conceptId":"math_geometry_exterior_angles_of_a_polygon","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Exterior Angles of a Polygon"}', 1),
  (356, 96, 'Each exterior angle of a regular polygon is 30°. How many sides does the polygon have?', 'text', 1, 'Use n = 360° ÷ exterior angle.', '{"why":"There are 360° in one complete turn, so 30° exterior angles require 12 equal turns.","sol":"Step 1: n = 360° ÷ 30°.\nStep 2: n = 12.","steps":["Step 1: n = 360° ÷ 30°.","Step 2: n = 12."],"options":[],"conceptId":"math_geometry_exterior_angles_of_a_polygon","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Exterior Angles of a Polygon"}', 2),
  (357, 96, 'A regular polygon has an interior angle of 135°. Find each exterior angle.', 'text', 1, 'Interior angle + exterior angle = 180°.', '{"why":"The interior and exterior angles at the same vertex form a straight line.","sol":"Step 1: Interior angle + exterior angle = 180°.\nStep 2: 135° + exterior angle = 180°.\nStep 3: Exterior angle = 180° − 135°.\nStep 4: Exterior angle = 45°.","steps":["Step 1: Interior angle + exterior angle = 180°.","Step 2: 135° + exterior angle = 180°.","Step 3: Exterior angle = 180° − 135°.","Step 4: Exterior angle = 45°."],"options":[],"conceptId":"math_geometry_exterior_angles_of_a_polygon","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Exterior Angles of a Polygon"}', 3),
  (358, 96, 'A learner says that each exterior angle of a regular hexagon is 30°. Identify the error and find the correct angle.', 'text', 1, 'A hexagon has 6 equal exterior angles whose total is 360°.', '{"why":"The sum of the exterior angles is 360°, not 180°.","sol":"Step 1: A hexagon has 6 sides.\nStep 2: Each exterior angle = 360° ÷ 6.\nStep 3: Each exterior angle = 60°.\nStep 4: The learner used 180° ÷ 6 instead of 360° ÷ 6.","steps":["Step 1: A hexagon has 6 sides.","Step 2: Each exterior angle = 360° ÷ 6.","Step 3: Each exterior angle = 60°.","Step 4: The learner used 180° ÷ 6 instead of 360° ÷ 6."],"options":[],"conceptId":"math_geometry_exterior_angles_of_a_polygon","skillId":"math_geometry","subskillId":"math_geometry_q5","subject":"math","chapter":"geometry","topic":"Exterior Angles of a Polygon"}', 4),
  (359, 97, 'A farmer must choose how much land to use for maize and beans while trying to obtain the greatest profit. What mathematical method can be used?', 'text', 1, 'Think about choosing quantities while working under a restriction.', '{"why":"Linear programming is used to find the best choice while satisfying restrictions.","sol":"Step 1: The farmer must choose quantities for two crops.\nStep 2: The available land is limited.\nStep 3: There is a goal of obtaining the greatest profit.\nStep 4: Therefore, this is a linear programming situation.","steps":["Step 1: The farmer must choose quantities for two crops.","Step 2: The available land is limited.","Step 3: There is a goal of obtaining the greatest profit.","Step 4: Therefore, this is a linear programming situation."],"options":[],"conceptId":"math_linear_programming_meaning_of_linear_programming","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of Linear Programming"}', 0),
  (360, 97, 'A business has limited money and must choose how many of two products to buy. What makes this a linear programming situation?', 'text', 1, 'Identify the choice, restriction and goal.', '{"why":"These are the basic ingredients of a linear programming problem.","sol":"Step 1: The business chooses quantities of the products.\nStep 2: The money available is limited.\nStep 3: The business wants the best possible choice.\nStep 4: Therefore, the situation can be handled using linear programming.","steps":["Step 1: The business chooses quantities of the products.","Step 2: The money available is limited.","Step 3: The business wants the best possible choice.","Step 4: Therefore, the situation can be handled using linear programming."],"options":[],"conceptId":"math_linear_programming_meaning_of_linear_programming","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of Linear Programming"}', 1),
  (361, 97, 'Does linear programming require the use of a computer?', 'text', 1, 'Look at what the word programming means in this topic.', '{"why":"Linear programming is a mathematical optimisation method, not computer programming.","sol":"Step 1: The word programming in linear programming means planning.\nStep 2: It does not refer to writing computer code.\nStep 3: Therefore, a computer is not required to define the method.","steps":["Step 1: The word programming in linear programming means planning.","Step 2: It does not refer to writing computer code.","Step 3: Therefore, a computer is not required to define the method."],"options":[],"conceptId":"math_linear_programming_meaning_of_linear_programming","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of Linear Programming"}', 2),
  (362, 98, 'A farmer grows maize and beans. Let x represent hectares of maize and y represent hectares of beans. Which are the decision variables?', 'text', 1, 'Look for the quantities whose values must be decided.', '{"why":"Decision variables represent the quantities that must be chosen.","sol":"Step 1: x represents hectares of maize.\nStep 2: y represents hectares of beans.\nStep 3: Both quantities must be decided.\nStep 4: Therefore, x and y are the decision variables.","steps":["Step 1: x represents hectares of maize.","Step 2: y represents hectares of beans.","Step 3: Both quantities must be decided.","Step 4: Therefore, x and y are the decision variables."],"options":[],"conceptId":"math_linear_programming_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Decision Variables"}', 0),
  (363, 98, 'A shop sells shoes and shirts. Choose suitable decision variables.', 'text', 1, 'Use x and y to represent the two quantities.', '{"why":"The variables must clearly identify the quantities being decided.","sol":"Step 1: Let x represent the number of shoes.\nStep 2: Let y represent the number of shirts.\nStep 3: These are the quantities the shop must decide.","steps":["Step 1: Let x represent the number of shoes.","Step 2: Let y represent the number of shirts.","Step 3: These are the quantities the shop must decide."],"options":[],"conceptId":"math_linear_programming_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Decision Variables"}', 1),
  (364, 98, 'Why should we state what x represents before solving a linear programming problem?', 'text', 1, 'Think about what x = 20 would mean without a definition.', '{"why":"A numerical answer is useful only when we know what quantity it represents.","sol":"Step 1: The letter x alone has no specific meaning.\nStep 2: We need to know what quantity x represents.\nStep 3: This allows us to interpret the final answer correctly.","steps":["Step 1: The letter x alone has no specific meaning.","Step 2: We need to know what quantity x represents.","Step 3: This allows us to interpret the final answer correctly."],"options":[],"conceptId":"math_linear_programming_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Decision Variables"}', 2),
  (365, 99, 'A farmer has at most 15 hectares for two crops. If x and y are the hectares used for the two crops, write the land constraint.', 'text', 1, 'At most means the total cannot exceed 15.', '{"why":"The inequality represents the limited amount of land.","sol":"Step 1: The total land used is x + y.\nStep 2: The available land is 15 hectares.\nStep 3: The total cannot be greater than 15.\nStep 4: Therefore, x + y ≤ 15.","steps":["Step 1: The total land used is x + y.","Step 2: The available land is 15 hectares.","Step 3: The total cannot be greater than 15.","Step 4: Therefore, x + y ≤ 15."],"options":[],"conceptId":"math_linear_programming_understanding_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Understanding Constraints"}', 0),
  (366, 99, 'A factory can make at most 80 products of two types in one day. If x and y are the quantities, write the constraint.', 'text', 1, 'At most 80 means not more than 80.', '{"why":"The total number of products cannot be greater than 80.","sol":"Step 1: Total production is x + y.\nStep 2: Production cannot exceed 80.\nStep 3: Therefore, x + y ≤ 80.","steps":["Step 1: Total production is x + y.","Step 2: Production cannot exceed 80.","Step 3: Therefore, x + y ≤ 80."],"options":[],"conceptId":"math_linear_programming_understanding_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Understanding Constraints"}', 1),
  (367, 99, 'In a constraint, what does the restriction actually do?', 'text', 1, 'Think about allowed and forbidden choices.', '{"why":"Constraints describe the conditions that every acceptable solution must satisfy.","sol":"Step 1: Without a constraint, many values might be possible.\nStep 2: The constraint removes values that violate the condition.\nStep 3: The remaining values are the allowed choices.","steps":["Step 1: Without a constraint, many values might be possible.","Step 2: The constraint removes values that violate the condition.","Step 3: The remaining values are the allowed choices."],"options":[],"conceptId":"math_linear_programming_understanding_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Understanding Constraints"}', 2),
  (368, 100, 'A farmer has at most 40 hectares for two crops. If x and y are the hectares used, write the constraint.', 'text', 1, 'At most means not greater than.', '{"why":"At most 40 means the total is less than or equal to 40.","sol":"Step 1: The total land is x + y.\nStep 2: The maximum available is 40 hectares.\nStep 3: Therefore the total cannot exceed 40.\nStep 4: So x + y ≤ 40.","steps":["Step 1: The total land is x + y.","Step 2: The maximum available is 40 hectares.","Step 3: Therefore the total cannot exceed 40.","Step 4: So x + y ≤ 40."],"options":[],"conceptId":"math_linear_programming_writing_a_constraint_from_a_statement","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Writing a Constraint from a Statement"}', 0),
  (369, 100, 'A school must have at least 300 learners in two programmes. If x and y are the numbers of learners, write the constraint.', 'text', 1, 'At least means not below.', '{"why":"At least 300 means the total must be greater than or equal to 300.","sol":"Step 1: The total number of learners is x + y.\nStep 2: The minimum required is 300.\nStep 3: Therefore the total must be 300 or more.\nStep 4: So x + y ≥ 300.","steps":["Step 1: The total number of learners is x + y.","Step 2: The minimum required is 300.","Step 3: Therefore the total must be 300 or more.","Step 4: So x + y ≥ 300."],"options":[],"conceptId":"math_linear_programming_writing_a_constraint_from_a_statement","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Writing a Constraint from a Statement"}', 1),
  (370, 100, 'A factory has no more than 120 kg of material. If x and y are the amounts used for two products, write the constraint.', 'text', 1, 'No more than means the same idea as at most.', '{"why":"No more than means less than or equal to.","sol":"Step 1: Total material used is x + y.\nStep 2: The available amount is 120 kg.\nStep 3: The amount used cannot exceed 120 kg.\nStep 4: Therefore x + y ≤ 120.","steps":["Step 1: Total material used is x + y.","Step 2: The available amount is 120 kg.","Step 3: The amount used cannot exceed 120 kg.","Step 4: Therefore x + y ≤ 120."],"options":[],"conceptId":"math_linear_programming_writing_a_constraint_from_a_statement","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Writing a Constraint from a Statement"}', 2),
  (371, 101, 'Does x = 6 satisfy x ≤ 10?', 'text', 1, 'Compare 6 with 10.', '{"why":"6 is less than 10.","sol":"Step 1: Substitute x = 6.\nStep 2: We get 6 ≤ 10.\nStep 3: This statement is true.\nStep 4: Therefore x = 6 satisfies the inequality.","steps":["Step 1: Substitute x = 6.","Step 2: We get 6 ≤ 10.","Step 3: This statement is true.","Step 4: Therefore x = 6 satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_less_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of Less Than or Equal To"}', 0),
  (372, 101, 'Does x = 10 satisfy x ≤ 10?', 'text', 1, 'Remember that ≤ includes equality.', '{"why":"The symbol ≤ allows the value to equal 10.","sol":"Step 1: Substitute x = 10.\nStep 2: We get 10 ≤ 10.\nStep 3: Equality is allowed by ≤.\nStep 4: Therefore x = 10 satisfies the inequality.","steps":["Step 1: Substitute x = 10.","Step 2: We get 10 ≤ 10.","Step 3: Equality is allowed by ≤.","Step 4: Therefore x = 10 satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_less_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of Less Than or Equal To"}', 1),
  (373, 101, 'Does x = 11 satisfy x ≤ 10?', 'text', 1, 'Is 11 less than or equal to 10?', '{"why":"11 is greater than 10.","sol":"Step 1: Substitute x = 11.\nStep 2: We get 11 ≤ 10.\nStep 3: This is false.\nStep 4: Therefore x = 11 does not satisfy the inequality.","steps":["Step 1: Substitute x = 11.","Step 2: We get 11 ≤ 10.","Step 3: This is false.","Step 4: Therefore x = 11 does not satisfy the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_less_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of Less Than or Equal To"}', 2),
  (374, 102, 'Does x = 30 satisfy x ≥ 20?', 'text', 1, 'Is 30 greater than or equal to 20?', '{"why":"30 is greater than 20.","sol":"Step 1: Substitute x = 30.\nStep 2: We get 30 ≥ 20.\nStep 3: This is true.\nStep 4: Therefore x = 30 satisfies the inequality.","steps":["Step 1: Substitute x = 30.","Step 2: We get 30 ≥ 20.","Step 3: This is true.","Step 4: Therefore x = 30 satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_greater_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of Greater Than or Equal To"}', 0),
  (375, 102, 'Does x = 20 satisfy x ≥ 20?', 'text', 1, 'Does ≥ include equality?', '{"why":"The symbol ≥ includes equality.","sol":"Step 1: Substitute x = 20.\nStep 2: We get 20 ≥ 20.\nStep 3: Equality is allowed.\nStep 4: Therefore x = 20 satisfies the inequality.","steps":["Step 1: Substitute x = 20.","Step 2: We get 20 ≥ 20.","Step 3: Equality is allowed.","Step 4: Therefore x = 20 satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_greater_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of Greater Than or Equal To"}', 1),
  (376, 102, 'Does x = 18 satisfy x ≥ 20?', 'text', 1, 'Compare 18 and 20.', '{"why":"18 is less than 20.","sol":"Step 1: Substitute x = 18.\nStep 2: We get 18 ≥ 20.\nStep 3: This is false.\nStep 4: Therefore x = 18 does not satisfy the inequality.","steps":["Step 1: Substitute x = 18.","Step 2: We get 18 ≥ 20.","Step 3: This is false.","Step 4: Therefore x = 18 does not satisfy the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_greater_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of Greater Than or Equal To"}', 2),
  (377, 103, 'If x represents the number of desks produced, write its non-negativity constraint.', 'text', 1, 'The number of desks cannot be negative.', '{"why":"The quantity represented by x cannot be negative.","sol":"Step 1: x represents a quantity.\nStep 2: A quantity of desks cannot be below zero.\nStep 3: Therefore x must be at least zero.","steps":["Step 1: x represents a quantity.","Step 2: A quantity of desks cannot be below zero.","Step 3: Therefore x must be at least zero."],"options":[],"conceptId":"math_linear_programming_non_negativity_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Non-Negativity Constraints"}', 0),
  (378, 103, 'If y represents kilograms of flour used, can y = -5 satisfy the non-negativity constraint?', 'text', 1, 'Check whether -5 is greater than or equal to zero.', '{"why":"A negative quantity does not satisfy the non-negativity constraint.","sol":"Step 1: The constraint is y ≥ 0.\nStep 2: Substitute y = -5.\nStep 3: We get -5 ≥ 0.\nStep 4: This is false.","steps":["Step 1: The constraint is y ≥ 0.","Step 2: Substitute y = -5.","Step 3: We get -5 ≥ 0.","Step 4: This is false."],"options":[],"conceptId":"math_linear_programming_non_negativity_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Non-Negativity Constraints"}', 1),
  (379, 103, 'Does x = 0 satisfy x ≥ 0?', 'text', 1, 'The symbol ≥ includes equality.', '{"why":"Non-negativity allows zero.","sol":"Step 1: Substitute x = 0.\nStep 2: We get 0 ≥ 0.\nStep 3: Equality is allowed.\nStep 4: Therefore x = 0 is allowed.","steps":["Step 1: Substitute x = 0.","Step 2: We get 0 ≥ 0.","Step 3: Equality is allowed.","Step 4: Therefore x = 0 is allowed."],"options":[],"conceptId":"math_linear_programming_non_negativity_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Non-Negativity Constraints"}', 2),
  (380, 104, 'A farmer has at most 25 hectares for two crops. What is the constraint if x and y are the hectares used?', 'text', 1, 'Identify the condition that limits the total land.', '{"why":"The 25 hectares limit the total amount of land that can be used.","sol":"Step 1: The total land used is x + y.\nStep 2: The farmer has at most 25 hectares.\nStep 3: The total cannot exceed 25.\nStep 4: Therefore x + y ≤ 25.","steps":["Step 1: The total land used is x + y.","Step 2: The farmer has at most 25 hectares.","Step 3: The total cannot exceed 25.","Step 4: Therefore x + y ≤ 25."],"options":[],"conceptId":"math_linear_programming_identifying_constraints_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Identifying Constraints in a Word Problem"}', 0),
  (381, 104, 'A factory has no more than 90 hours available. If x and y are hours used for two activities, write the constraint.', 'text', 1, 'No more than means the total cannot exceed the available amount.', '{"why":"The available time places a maximum on the total time used.","sol":"Step 1: Total time used is x + y.\nStep 2: The maximum available time is 90 hours.\nStep 3: Therefore x + y ≤ 90.","steps":["Step 1: Total time used is x + y.","Step 2: The maximum available time is 90 hours.","Step 3: Therefore x + y ≤ 90."],"options":[],"conceptId":"math_linear_programming_identifying_constraints_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Identifying Constraints in a Word Problem"}', 1),
  (382, 104, 'A school requires at least 400 learners in two programmes. If x and y are the numbers of learners, write the constraint.', 'text', 1, 'At least means the total must reach or exceed the number.', '{"why":"The school requires a minimum total of 400 learners.","sol":"Step 1: Total learners are x + y.\nStep 2: The minimum required is 400.\nStep 3: Therefore the total must be at least 400.\nStep 4: So x + y ≥ 400.","steps":["Step 1: Total learners are x + y.","Step 2: The minimum required is 400.","Step 3: Therefore the total must be at least 400.","Step 4: So x + y ≥ 400."],"options":[],"conceptId":"math_linear_programming_identifying_constraints_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Identifying Constraints in a Word Problem"}', 2),
  (383, 105, 'A farmer has at most 30 hectares. Is x + y ≥ 30 the correct constraint?', 'text', 1, 'Try a value greater than 30.', '{"why":"At most means the total cannot exceed 30.","sol":"Step 1: At most 30 means values greater than 30 must not be allowed.\nStep 2: But x + y ≥ 30 allows 40, 50, and other larger values.\nStep 3: Therefore it does not represent the condition.\nStep 4: The correct inequality is x + y ≤ 30.","steps":["Step 1: At most 30 means values greater than 30 must not be allowed.","Step 2: But x + y ≥ 30 allows 40, 50, and other larger values.","Step 3: Therefore it does not represent the condition.","Step 4: The correct inequality is x + y ≤ 30."],"options":[],"conceptId":"math_linear_programming_checking_whether_an_inequality_matches_a_condition","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Checking Whether an Inequality Matches a Condition"}', 0),
  (384, 105, 'A school needs at least 200 learners. Is x + y ≥ 200 correct?', 'text', 1, 'Check whether the inequality allows 200 and values above 200.', '{"why":"Greater than or equal to represents at least.","sol":"Step 1: At least 200 means 200 is allowed.\nStep 2: Values greater than 200 must also be allowed.\nStep 3: x + y ≥ 200 allows exactly these values.\nStep 4: Therefore it is correct.","steps":["Step 1: At least 200 means 200 is allowed.","Step 2: Values greater than 200 must also be allowed.","Step 3: x + y ≥ 200 allows exactly these values.","Step 4: Therefore it is correct."],"options":[],"conceptId":"math_linear_programming_checking_whether_an_inequality_matches_a_condition","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Checking Whether an Inequality Matches a Condition"}', 1),
  (385, 105, 'A factory has no more than 70 kg of material. Does x + y ≤ 70 represent this condition?', 'text', 1, 'Check values below, equal to, and above 70.', '{"why":"Less than or equal to represents no more than.","sol":"Step 1: Values below 70 are allowed.\nStep 2: 70 itself is allowed.\nStep 3: Values above 70 are not allowed.\nStep 4: That exactly matches no more than 70.","steps":["Step 1: Values below 70 are allowed.","Step 2: 70 itself is allowed.","Step 3: Values above 70 are not allowed.","Step 4: That exactly matches no more than 70."],"options":[],"conceptId":"math_linear_programming_checking_whether_an_inequality_matches_a_condition","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Checking Whether an Inequality Matches a Condition"}', 2),
  (386, 106, 'A farmer uses x hectares for maize and y hectares for beans. There are at most 50 hectares available. Write the complete basic set of constraints.', 'text', 1, 'Include the land restriction and non-negativity.', '{"why":"All three conditions are required for an acceptable choice.","sol":"Step 1: The total land is x + y.\nStep 2: At most 50 hectares gives x + y ≤ 50.\nStep 3: Land cannot be negative, so x ≥ 0.\nStep 4: Land cannot be negative, so y ≥ 0.","steps":["Step 1: The total land is x + y.","Step 2: At most 50 hectares gives x + y ≤ 50.","Step 3: Land cannot be negative, so x ≥ 0.","Step 4: Land cannot be negative, so y ≥ 0."],"options":[],"conceptId":"math_linear_programming_writing_the_complete_set_of_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Writing the Complete Set of Constraints"}', 0),
  (387, 106, 'A factory produces x units of A and y units of B. It can produce at most 120 units. Write the complete basic constraints.', 'text', 1, 'Do not forget the meaning of the quantities.', '{"why":"The production limit and non-negativity together define the basic restrictions.","sol":"Step 1: Total production is x + y.\nStep 2: At most 120 gives x + y ≤ 120.\nStep 3: Production cannot be negative.\nStep 4: Therefore x ≥ 0 and y ≥ 0.","steps":["Step 1: Total production is x + y.","Step 2: At most 120 gives x + y ≤ 120.","Step 3: Production cannot be negative.","Step 4: Therefore x ≥ 0 and y ≥ 0."],"options":[],"conceptId":"math_linear_programming_writing_the_complete_set_of_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Writing the Complete Set of Constraints"}', 1),
  (388, 106, 'A school requires at least 600 learners in two programmes. Let x and y be the numbers of learners. Write the complete basic set of constraints.', 'text', 1, 'Translate at least first, then add non-negativity.', '{"why":"The complete set must contain the total requirement and the non-negativity restrictions.","sol":"Step 1: The total number of learners is x + y.\nStep 2: At least 600 gives x + y ≥ 600.\nStep 3: Numbers of learners cannot be negative.\nStep 4: Therefore x ≥ 0 and y ≥ 0.","steps":["Step 1: The total number of learners is x + y.","Step 2: At least 600 gives x + y ≥ 600.","Step 3: Numbers of learners cannot be negative.","Step 4: Therefore x ≥ 0 and y ≥ 0."],"options":[],"conceptId":"math_linear_programming_writing_the_complete_set_of_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Writing the Complete Set of Constraints"}', 2),
  (389, 107, 'Find the boundary equation for x + y ≤ 8.', 'text', 1, 'Replace ≤ with =.', '{"why":"The boundary contains the points where the inequality reaches its limit.","sol":"Step 1: Start with x + y ≤ 8.\nStep 2: The boundary occurs at the limit.\nStep 3: Replace ≤ with =.\nStep 4: Therefore x + y = 8.","steps":["Step 1: Start with x + y ≤ 8.","Step 2: The boundary occurs at the limit.","Step 3: Replace ≤ with =.","Step 4: Therefore x + y = 8."],"options":[],"conceptId":"math_linear_programming_turning_an_inequality_into_a_boundary_equation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Turning an Inequality into a Boundary Equation"}', 0),
  (390, 107, 'Find the boundary equation for 2x + 3y ≥ 12.', 'text', 1, 'Only change the inequality symbol to =.', '{"why":"The equality gives the line separating the two regions.","sol":"Step 1: Start with 2x + 3y ≥ 12.\nStep 2: Replace ≥ with =.\nStep 3: Therefore 2x + 3y = 12.","steps":["Step 1: Start with 2x + 3y ≥ 12.","Step 2: Replace ≥ with =.","Step 3: Therefore 2x + 3y = 12."],"options":[],"conceptId":"math_linear_programming_turning_an_inequality_into_a_boundary_equation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Turning an Inequality into a Boundary Equation"}', 1),
  (391, 107, 'What is the boundary equation of 4x + y ≤ 20?', 'text', 1, 'Replace ≤ with =.', '{"why":"The boundary is formed where the inequality becomes an equality.","sol":"Step 1: Start with 4x + y ≤ 20.\nStep 2: Replace ≤ by =.\nStep 3: The boundary is 4x + y = 20.","steps":["Step 1: Start with 4x + y ≤ 20.","Step 2: Replace ≤ by =.","Step 3: The boundary is 4x + y = 20."],"options":[],"conceptId":"math_linear_programming_turning_an_inequality_into_a_boundary_equation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Turning an Inequality into a Boundary Equation"}', 2),
  (392, 108, 'Find the x-intercept of x + y = 7.', 'text', 1, 'Set y = 0.', '{"why":"The x-axis has y = 0.","sol":"Step 1: Set y = 0.\nStep 2: x + 0 = 7.\nStep 3: Therefore x = 7.\nStep 4: The point is (7, 0).","steps":["Step 1: Set y = 0.","Step 2: x + 0 = 7.","Step 3: Therefore x = 7.","Step 4: The point is (7, 0)."],"options":[],"conceptId":"math_linear_programming_finding_the_x_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the x-Intercept"}', 0),
  (393, 108, 'Find the x-intercept of 2x + y = 10.', 'text', 1, 'Put y = 0.', '{"why":"Setting y = 0 gives the point where the line crosses the x-axis.","sol":"Step 1: Set y = 0.\nStep 2: 2x + 0 = 10.\nStep 3: 2x = 10.\nStep 4: x = 5.\nStep 5: Therefore the point is (5, 0).","steps":["Step 1: Set y = 0.","Step 2: 2x + 0 = 10.","Step 3: 2x = 10.","Step 4: x = 5.","Step 5: Therefore the point is (5, 0)."],"options":[],"conceptId":"math_linear_programming_finding_the_x_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the x-Intercept"}', 1),
  (394, 108, 'Find the x-intercept of 4x + 2y = 20.', 'text', 1, 'Set y = 0 and solve for x.', '{"why":"The x-intercept always has y-coordinate zero.","sol":"Step 1: Set y = 0.\nStep 2: 4x + 2(0) = 20.\nStep 3: 4x = 20.\nStep 4: x = 5.\nStep 5: Therefore the x-intercept is (5, 0).","steps":["Step 1: Set y = 0.","Step 2: 4x + 2(0) = 20.","Step 3: 4x = 20.","Step 4: x = 5.","Step 5: Therefore the x-intercept is (5, 0)."],"options":[],"conceptId":"math_linear_programming_finding_the_x_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the x-Intercept"}', 2),
  (395, 109, 'Find the y-intercept of x + y = 8.', 'text', 1, 'Set x = 0.', '{"why":"The y-axis has x = 0.","sol":"Step 1: Set x = 0.\nStep 2: 0 + y = 8.\nStep 3: Therefore y = 8.\nStep 4: The point is (0, 8).","steps":["Step 1: Set x = 0.","Step 2: 0 + y = 8.","Step 3: Therefore y = 8.","Step 4: The point is (0, 8)."],"options":[],"conceptId":"math_linear_programming_finding_the_y_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the y-Intercept"}', 0),
  (396, 109, 'Find the y-intercept of 2x + y = 14.', 'text', 1, 'Put x = 0.', '{"why":"Setting x = 0 gives the point where the line crosses the y-axis.","sol":"Step 1: Set x = 0.\nStep 2: 2(0) + y = 14.\nStep 3: Therefore y = 14.\nStep 4: The point is (0, 14).","steps":["Step 1: Set x = 0.","Step 2: 2(0) + y = 14.","Step 3: Therefore y = 14.","Step 4: The point is (0, 14)."],"options":[],"conceptId":"math_linear_programming_finding_the_y_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the y-Intercept"}', 1),
  (397, 109, 'Find the y-intercept of 4x + 2y = 20.', 'text', 1, 'Set x = 0 and solve for y.', '{"why":"The y-intercept always has x-coordinate zero.","sol":"Step 1: Set x = 0.\nStep 2: 4(0) + 2y = 20.\nStep 3: 2y = 20.\nStep 4: y = 10.\nStep 5: Therefore the y-intercept is (0, 10).","steps":["Step 1: Set x = 0.","Step 2: 4(0) + 2y = 20.","Step 3: 2y = 20.","Step 4: y = 10.","Step 5: Therefore the y-intercept is (0, 10)."],"options":[],"conceptId":"math_linear_programming_finding_the_y_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the y-Intercept"}', 2),
  (398, 110, 'Draw the boundary line x + y = 6. Which two intercepts should you plot?', 'text', 1, 'Find the x-intercept and y-intercept.', '{"why":"These two points lie on the boundary line and are easy to obtain.","sol":"Step 1: For the x-intercept, set y = 0.\nStep 2: Then x = 6, giving (6,0).\nStep 3: For the y-intercept, set x = 0.\nStep 4: Then y = 6, giving (0,6).","steps":["Step 1: For the x-intercept, set y = 0.","Step 2: Then x = 6, giving (6,0).","Step 3: For the y-intercept, set x = 0.","Step 4: Then y = 6, giving (0,6)."],"options":[],"conceptId":"math_linear_programming_drawing_a_boundary_line_from_its_intercepts","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Drawing a Boundary Line from Its Intercepts"}', 0),
  (399, 110, 'Find the two intercepts needed to draw 2x + y = 10.', 'text', 1, 'Set y = 0 for the x-intercept and x = 0 for the y-intercept.', '{"why":"The line is determined by these two intercepts.","sol":"Step 1: Set y = 0: 2x = 10, so x = 5.\nStep 2: The x-intercept is (5,0).\nStep 3: Set x = 0: y = 10.\nStep 4: The y-intercept is (0,10).","steps":["Step 1: Set y = 0: 2x = 10, so x = 5.","Step 2: The x-intercept is (5,0).","Step 3: Set x = 0: y = 10.","Step 4: The y-intercept is (0,10)."],"options":[],"conceptId":"math_linear_programming_drawing_a_boundary_line_from_its_intercepts","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Drawing a Boundary Line from Its Intercepts"}', 1),
  (400, 110, 'Find the two intercepts of 3x + y = 12.', 'text', 1, 'Use y = 0 and then x = 0.', '{"why":"The two intercepts provide the two points needed to draw the boundary.","sol":"Step 1: Set y = 0: 3x = 12, so x = 4.\nStep 2: The x-intercept is (4,0).\nStep 3: Set x = 0: y = 12.\nStep 4: The y-intercept is (0,12).","steps":["Step 1: Set y = 0: 3x = 12, so x = 4.","Step 2: The x-intercept is (4,0).","Step 3: Set x = 0: y = 12.","Step 4: The y-intercept is (0,12)."],"options":[],"conceptId":"math_linear_programming_drawing_a_boundary_line_from_its_intercepts","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Drawing a Boundary Line from Its Intercepts"}', 2),
  (401, 111, 'Should the boundary of x + y ≤ 10 be solid or broken?', 'text', 1, 'Does ≤ include equality?', '{"why":"≤ includes equality.","sol":"Step 1: The inequality is ≤.\nStep 2: Equality is included.\nStep 3: Therefore points on the boundary are included.\nStep 4: Use a solid line.","steps":["Step 1: The inequality is ≤.","Step 2: Equality is included.","Step 3: Therefore points on the boundary are included.","Step 4: Use a solid line."],"options":[],"conceptId":"math_linear_programming_solid_and_broken_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Solid and Broken Boundary Lines"}', 0),
  (402, 111, 'Should the boundary of 2x + y ≥ 8 be solid or broken?', 'text', 1, 'Check whether ≥ includes equality.', '{"why":"≥ includes equality.","sol":"Step 1: The inequality is ≥.\nStep 2: Equality is included.\nStep 3: Therefore the boundary belongs to the solution.\nStep 4: Use a solid line.","steps":["Step 1: The inequality is ≥.","Step 2: Equality is included.","Step 3: Therefore the boundary belongs to the solution.","Step 4: Use a solid line."],"options":[],"conceptId":"math_linear_programming_solid_and_broken_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Solid and Broken Boundary Lines"}', 1),
  (403, 111, 'Should the boundary of x + y > 5 be solid or broken?', 'text', 1, 'Is equality included in >?', '{"why":"> excludes equality.","sol":"Step 1: The inequality is >.\nStep 2: Equality is not included.\nStep 3: Therefore the boundary itself is excluded.\nStep 4: Use a broken line.","steps":["Step 1: The inequality is >.","Step 2: Equality is not included.","Step 3: Therefore the boundary itself is excluded.","Step 4: Use a broken line."],"options":[],"conceptId":"math_linear_programming_solid_and_broken_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Solid and Broken Boundary Lines"}', 2),
  (404, 112, 'Does (0,0) satisfy x + y ≤ 12?', 'text', 1, 'Substitute x = 0 and y = 0.', '{"why":"The point makes the inequality true.","sol":"Step 1: 0 + 0 ≤ 12.\nStep 2: 0 ≤ 12 is true.\nStep 3: Therefore (0,0) satisfies the inequality.","steps":["Step 1: 0 + 0 ≤ 12.","Step 2: 0 ≤ 12 is true.","Step 3: Therefore (0,0) satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_testing_a_point_in_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Testing a Point in an Inequality"}', 0),
  (405, 112, 'Does (0,0) satisfy 2x + y ≥ 10?', 'text', 1, 'Substitute both coordinates.', '{"why":"The inequality becomes false at (0,0).","sol":"Step 1: 2(0) + 0 ≥ 10.\nStep 2: 0 ≥ 10 is false.\nStep 3: Therefore (0,0) does not satisfy the inequality.","steps":["Step 1: 2(0) + 0 ≥ 10.","Step 2: 0 ≥ 10 is false.","Step 3: Therefore (0,0) does not satisfy the inequality."],"options":[],"conceptId":"math_linear_programming_testing_a_point_in_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Testing a Point in an Inequality"}', 1),
  (406, 112, 'Does (2,4) satisfy x + y ≤ 8?', 'text', 1, 'Calculate 2 + 4 first.', '{"why":"The point makes the inequality true.","sol":"Step 1: Substitute x = 2 and y = 4.\nStep 2: 2 + 4 ≤ 8.\nStep 3: 6 ≤ 8 is true.\nStep 4: Therefore (2,4) satisfies the inequality.","steps":["Step 1: Substitute x = 2 and y = 4.","Step 2: 2 + 4 ≤ 8.","Step 3: 6 ≤ 8 is true.","Step 4: Therefore (2,4) satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_testing_a_point_in_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Testing a Point in an Inequality"}', 2),
  (407, 113, 'For x + y ≤ 6, does the region containing (0,0) satisfy the inequality?', 'text', 1, 'Test (0,0).', '{"why":"The test point satisfies the inequality.","sol":"Step 1: Substitute (0,0).\nStep 2: 0 + 0 ≤ 6.\nStep 3: 0 ≤ 6 is true.\nStep 4: Therefore the region containing (0,0) is the solution region.","steps":["Step 1: Substitute (0,0).","Step 2: 0 + 0 ≤ 6.","Step 3: 0 ≤ 6 is true.","Step 4: Therefore the region containing (0,0) is the solution region."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≤"}', 0),
  (408, 113, 'For 2x + y ≤ 10, should the side containing (0,0) be shaded?', 'text', 1, 'Substitute (0,0).', '{"why":"The test point makes the inequality true.","sol":"Step 1: 2(0) + 0 ≤ 10.\nStep 2: 0 ≤ 10 is true.\nStep 3: Therefore (0,0) is in the solution region.\nStep 4: Shade the side containing (0,0).","steps":["Step 1: 2(0) + 0 ≤ 10.","Step 2: 0 ≤ 10 is true.","Step 3: Therefore (0,0) is in the solution region.","Step 4: Shade the side containing (0,0)."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≤"}', 1),
  (409, 113, 'Why is testing a point safer than simply memorising ''shade below the line''?', 'text', 1, 'Think about lines with different slopes and rearrangements.', '{"why":"Testing a point works regardless of the orientation of the boundary line.","sol":"Step 1: Different inequalities can have different line arrangements.\nStep 2: The words above and below can become misleading.\nStep 3: A test point directly checks whether a region satisfies the original inequality.\nStep 4: Therefore testing is more reliable.","steps":["Step 1: Different inequalities can have different line arrangements.","Step 2: The words above and below can become misleading.","Step 3: A test point directly checks whether a region satisfies the original inequality.","Step 4: Therefore testing is more reliable."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≤"}', 2),
  (410, 114, 'For x + y ≥ 8, does (0,0) lie in the solution region?', 'text', 1, 'Test the point.', '{"why":"The point does not satisfy the inequality.","sol":"Step 1: 0 + 0 ≥ 8.\nStep 2: 0 ≥ 8 is false.\nStep 3: Therefore (0,0) is not in the solution region.","steps":["Step 1: 0 + 0 ≥ 8.","Step 2: 0 ≥ 8 is false.","Step 3: Therefore (0,0) is not in the solution region."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≥"}', 0),
  (411, 114, 'For 2x + y ≥ 10, is the region containing (0,0) the solution region?', 'text', 1, 'Substitute (0,0).', '{"why":"The test point fails the inequality.","sol":"Step 1: 2(0) + 0 ≥ 10.\nStep 2: 0 ≥ 10 is false.\nStep 3: Therefore the region containing (0,0) is not the solution region.","steps":["Step 1: 2(0) + 0 ≥ 10.","Step 2: 0 ≥ 10 is false.","Step 3: Therefore the region containing (0,0) is not the solution region."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≥"}', 1),
  (412, 114, 'For x + y ≥ 6, does (4,3) belong to the solution region?', 'text', 1, 'Calculate 4 + 3.', '{"why":"The coordinates make the inequality true.","sol":"Step 1: 4 + 3 ≥ 6.\nStep 2: 7 ≥ 6 is true.\nStep 3: Therefore (4,3) belongs to the solution region.","steps":["Step 1: 4 + 3 ≥ 6.","Step 2: 7 ≥ 6 is true.","Step 3: Therefore (4,3) belongs to the solution region."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≥"}', 2),
  (413, 115, 'Find the two intercepts of 2x + 3y = 12.', 'text', 1, 'Set y = 0, then set x = 0.', '{"why":"The coefficients determine the intercepts.","sol":"Step 1: For the x-intercept, y = 0.\nStep 2: 2x = 12, so x = 6.\nStep 3: Therefore the x-intercept is (6,0).\nStep 4: For the y-intercept, x = 0.\nStep 5: 3y = 12, so y = 4.\nStep 6: Therefore the y-intercept is (0,4).","steps":["Step 1: For the x-intercept, y = 0.","Step 2: 2x = 12, so x = 6.","Step 3: Therefore the x-intercept is (6,0).","Step 4: For the y-intercept, x = 0.","Step 5: 3y = 12, so y = 4.","Step 6: Therefore the y-intercept is (0,4)."],"options":[],"conceptId":"math_linear_programming_graphing_an_inequality_with_different_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Graphing an Inequality with Different Coefficients"}', 0),
  (414, 115, 'Find the x-intercept of 5x + 2y = 20.', 'text', 1, 'Set y = 0.', '{"why":"The x-axis has y = 0.","sol":"Step 1: Set y = 0.\nStep 2: 5x = 20.\nStep 3: x = 4.\nStep 4: Therefore the x-intercept is (4,0).","steps":["Step 1: Set y = 0.","Step 2: 5x = 20.","Step 3: x = 4.","Step 4: Therefore the x-intercept is (4,0)."],"options":[],"conceptId":"math_linear_programming_graphing_an_inequality_with_different_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Graphing an Inequality with Different Coefficients"}', 1),
  (415, 115, 'Find the y-intercept of 3x + 4y = 24.', 'text', 1, 'Set x = 0.', '{"why":"The y-axis has x = 0.","sol":"Step 1: Set x = 0.\nStep 2: 4y = 24.\nStep 3: y = 6.\nStep 4: Therefore the y-intercept is (0,6).","steps":["Step 1: Set x = 0.","Step 2: 4y = 24.","Step 3: y = 6.","Step 4: Therefore the y-intercept is (0,6)."],"options":[],"conceptId":"math_linear_programming_graphing_an_inequality_with_different_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Graphing an Inequality with Different Coefficients"}', 2),
  (416, 116, 'A point must satisfy x + y ≤ 10 and x ≥ 2. Does (1,4) satisfy both?', 'text', 1, 'Test the point in each inequality separately.', '{"why":"A feasible point must satisfy every constraint.","sol":"Step 1: First: 1 + 4 ≤ 10, which is true.\nStep 2: Second: 1 ≥ 2, which is false.\nStep 3: Because one condition fails, the point is not in the common region.","steps":["Step 1: First: 1 + 4 ≤ 10, which is true.","Step 2: Second: 1 ≥ 2, which is false.","Step 3: Because one condition fails, the point is not in the common region."],"options":[],"conceptId":"math_linear_programming_graphing_two_inequalities_together","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Graphing Two Inequalities Together"}', 0),
  (417, 116, 'Does (3,4) satisfy x + y ≤ 10 and x ≥ 2?', 'text', 1, 'Check both inequalities.', '{"why":"The point lies in the overlap of the two solution regions.","sol":"Step 1: 3 + 4 ≤ 10 gives 7 ≤ 10, true.\nStep 2: 3 ≥ 2 is also true.\nStep 3: Therefore the point satisfies both constraints.","steps":["Step 1: 3 + 4 ≤ 10 gives 7 ≤ 10, true.","Step 2: 3 ≥ 2 is also true.","Step 3: Therefore the point satisfies both constraints."],"options":[],"conceptId":"math_linear_programming_graphing_two_inequalities_together","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Graphing Two Inequalities Together"}', 1),
  (418, 116, 'Why do we need the overlap when graphing two inequalities?', 'text', 1, 'Think about what ''satisfying both'' means.', '{"why":"The intersection of the regions represents choices that obey every constraint.","sol":"Step 1: Each inequality imposes a separate condition.\nStep 2: A valid point must obey the first condition.\nStep 3: It must also obey the second condition.\nStep 4: Therefore only the common region is acceptable.","steps":["Step 1: Each inequality imposes a separate condition.","Step 2: A valid point must obey the first condition.","Step 3: It must also obey the second condition.","Step 4: Therefore only the common region is acceptable."],"options":[],"conceptId":"math_linear_programming_graphing_two_inequalities_together","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Graphing Two Inequalities Together"}', 2),
  (419, 117, 'What is a feasible region?', 'text', 1, 'Think about all the constraints together.', '{"why":"Feasibility means that a choice obeys all restrictions.","sol":"Step 1: Each constraint limits the possible choices.\nStep 2: A feasible point must satisfy every constraint.\nStep 3: The collection of all such points forms the feasible region.","steps":["Step 1: Each constraint limits the possible choices.","Step 2: A feasible point must satisfy every constraint.","Step 3: The collection of all such points forms the feasible region."],"options":[],"conceptId":"math_linear_programming_meaning_of_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of the Feasible Region"}', 0),
  (420, 117, 'Does the point (3,4) satisfy x + y ≤ 10, x ≥ 0 and y ≥ 0?', 'text', 1, 'Check all three conditions.', '{"why":"A point is feasible when every constraint is satisfied.","sol":"Step 1: 3 + 4 ≤ 10 gives 7 ≤ 10, true.\nStep 2: 3 ≥ 0 is true.\nStep 3: 4 ≥ 0 is true.\nStep 4: Therefore the point satisfies every constraint.","steps":["Step 1: 3 + 4 ≤ 10 gives 7 ≤ 10, true.","Step 2: 3 ≥ 0 is true.","Step 3: 4 ≥ 0 is true.","Step 4: Therefore the point satisfies every constraint."],"options":[],"conceptId":"math_linear_programming_meaning_of_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of the Feasible Region"}', 1),
  (421, 117, 'A point satisfies two constraints but violates a third. Is it feasible?', 'text', 1, 'Feasible means all conditions must hold.', '{"why":"One violated constraint is enough to make a point infeasible.","sol":"Step 1: Every constraint must be satisfied.\nStep 2: The point violates one constraint.\nStep 3: Therefore it is not feasible.","steps":["Step 1: Every constraint must be satisfied.","Step 2: The point violates one constraint.","Step 3: Therefore it is not feasible."],"options":[],"conceptId":"math_linear_programming_meaning_of_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of the Feasible Region"}', 2),
  (422, 118, 'If two inequalities are graphed, what part of the graph is feasible?', 'text', 1, 'Think about what both inequalities require.', '{"why":"The feasible region must satisfy all constraints.","sol":"Step 1: Each inequality creates a solution region.\nStep 2: A feasible point must satisfy both.\nStep 3: Therefore the overlapping part is feasible.","steps":["Step 1: Each inequality creates a solution region.","Step 2: A feasible point must satisfy both.","Step 3: Therefore the overlapping part is feasible."],"options":[],"conceptId":"math_linear_programming_identifying_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Identifying the Feasible Region"}', 0),
  (423, 118, 'If x ≥ 0 and y ≥ 0 are constraints, which part of the coordinate plane can contain feasible points?', 'text', 1, 'Think about the signs of x and y.', '{"why":"Both coordinates must be zero or positive.","sol":"Step 1: x ≥ 0 means x cannot be negative.\nStep 2: y ≥ 0 means y cannot be negative.\nStep 3: Therefore both coordinates must be non-negative.\nStep 4: This is the first quadrant together with its axes.","steps":["Step 1: x ≥ 0 means x cannot be negative.","Step 2: y ≥ 0 means y cannot be negative.","Step 3: Therefore both coordinates must be non-negative.","Step 4: This is the first quadrant together with its axes."],"options":[],"conceptId":"math_linear_programming_identifying_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Identifying the Feasible Region"}', 1),
  (424, 118, 'A point lies in the region satisfying the first constraint but outside the region satisfying the second. Is it feasible?', 'text', 1, 'Does it satisfy every condition?', '{"why":"Feasibility requires all constraints to be satisfied.","sol":"Step 1: The point satisfies the first condition.\nStep 2: It violates the second condition.\nStep 3: Therefore it does not satisfy all constraints.","steps":["Step 1: The point satisfies the first condition.","Step 2: It violates the second condition.","Step 3: Therefore it does not satisfy all constraints."],"options":[],"conceptId":"math_linear_programming_identifying_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Identifying the Feasible Region"}', 2),
  (425, 119, 'Is (2,6) feasible for x + y ≤ 10, x ≥ 0 and y ≥ 0?', 'text', 1, 'Check all three conditions.', '{"why":"The point satisfies every constraint.","sol":"Step 1: 2 + 6 ≤ 10 gives 8 ≤ 10, true.\nStep 2: 2 ≥ 0 is true.\nStep 3: 6 ≥ 0 is true.\nStep 4: All constraints are satisfied.","steps":["Step 1: 2 + 6 ≤ 10 gives 8 ≤ 10, true.","Step 2: 2 ≥ 0 is true.","Step 3: 6 ≥ 0 is true.","Step 4: All constraints are satisfied."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_point_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Point Is Feasible"}', 0),
  (426, 119, 'Is (1,5) feasible for x + y ≤ 10 and x ≥ 2?', 'text', 1, 'One constraint may fail.', '{"why":"The point violates x ≥ 2.","sol":"Step 1: 1 + 5 ≤ 10 gives 6 ≤ 10, true.\nStep 2: But 1 ≥ 2 is false.\nStep 3: Therefore the point is not feasible.","steps":["Step 1: 1 + 5 ≤ 10 gives 6 ≤ 10, true.","Step 2: But 1 ≥ 2 is false.","Step 3: Therefore the point is not feasible."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_point_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Point Is Feasible"}', 1),
  (427, 119, 'Is (5,4) feasible for 2x + y ≤ 12, x ≥ 0 and y ≥ 0?', 'text', 1, 'Start with 2x + y.', '{"why":"The point violates the first constraint.","sol":"Step 1: 2(5) + 4 = 14.\nStep 2: 14 ≤ 12 is false.\nStep 3: Therefore the point is not feasible.","steps":["Step 1: 2(5) + 4 = 14.","Step 2: 14 ≤ 12 is false.","Step 3: Therefore the point is not feasible."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_point_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Point Is Feasible"}', 2),
  (428, 120, 'For x + y ≤ 8, x ≥ 0 and y ≥ 0, which side of x + y = 8 contains the feasible region?', 'text', 1, 'Test the origin.', '{"why":"The origin satisfies the inequality and the non-negativity constraints.","sol":"Step 1: Substitute (0,0).\nStep 2: 0 + 0 ≤ 8 is true.\nStep 3: Therefore the side containing (0,0) satisfies the inequality.\nStep 4: Because x and y must also be non-negative, only the first-quadrant portion is feasible.","steps":["Step 1: Substitute (0,0).","Step 2: 0 + 0 ≤ 8 is true.","Step 3: Therefore the side containing (0,0) satisfies the inequality.","Step 4: Because x and y must also be non-negative, only the first-quadrant portion is feasible."],"options":[],"conceptId":"math_linear_programming_constructing_a_feasible_region_from_three_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Constructing a Feasible Region from Three Constraints"}', 0),
  (429, 120, 'For 2x + y ≤ 10, x ≥ 0 and y ≥ 0, find the boundary intercepts.', 'text', 1, 'Set y = 0 and then x = 0.', '{"why":"These are the axis points of the boundary.","sol":"Step 1: Set y = 0: 2x = 10, so x = 5.\nStep 2: The x-intercept is (5,0).\nStep 3: Set x = 0: y = 10.\nStep 4: The y-intercept is (0,10).","steps":["Step 1: Set y = 0: 2x = 10, so x = 5.","Step 2: The x-intercept is (5,0).","Step 3: Set x = 0: y = 10.","Step 4: The y-intercept is (0,10)."],"options":[],"conceptId":"math_linear_programming_constructing_a_feasible_region_from_three_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Constructing a Feasible Region from Three Constraints"}', 1),
  (430, 120, 'What must be true of every point inside the feasible region?', 'text', 1, 'Think about the definition of feasible.', '{"why":"The feasible region is the common solution to all constraints.","sol":"Step 1: A feasible point is an allowed choice.\nStep 2: Every restriction must be satisfied.\nStep 3: Therefore every point in the feasible region satisfies every constraint.","steps":["Step 1: A feasible point is an allowed choice.","Step 2: Every restriction must be satisfied.","Step 3: Therefore every point in the feasible region satisfies every constraint."],"options":[],"conceptId":"math_linear_programming_constructing_a_feasible_region_from_three_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Constructing a Feasible Region from Three Constraints"}', 2),
  (431, 121, 'If x represents shirts and y represents trousers, what does the point (6,4) represent?', 'text', 1, 'Read the x-coordinate first and the y-coordinate second.', '{"why":"Coordinates give the values of the decision variables.","sol":"Step 1: The x-coordinate is 6.\nStep 2: x represents shirts.\nStep 3: The y-coordinate is 4.\nStep 4: y represents trousers.","steps":["Step 1: The x-coordinate is 6.","Step 2: x represents shirts.","Step 3: The y-coordinate is 4.","Step 4: y represents trousers."],"options":[],"conceptId":"math_linear_programming_reading_a_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Reading a Feasible Region"}', 0),
  (432, 121, 'If x represents hectares of maize and y represents hectares of beans, what does (3,7) mean?', 'text', 1, 'Match each coordinate to its variable.', '{"why":"The coordinates describe the chosen quantities.","sol":"Step 1: x = 3, so maize uses 3 hectares.\nStep 2: y = 7, so beans use 7 hectares.","steps":["Step 1: x = 3, so maize uses 3 hectares.","Step 2: y = 7, so beans use 7 hectares."],"options":[],"conceptId":"math_linear_programming_reading_a_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Reading a Feasible Region"}', 1),
  (433, 121, 'If a point lies inside the feasible region, what does that tell us about the corresponding choice?', 'text', 1, 'Think about what feasible means.', '{"why":"The feasible region represents allowed combinations of the decision variables.","sol":"Step 1: Every point in the feasible region satisfies every constraint.\nStep 2: Therefore the corresponding choice obeys all restrictions.","steps":["Step 1: Every point in the feasible region satisfies every constraint.","Step 2: Therefore the corresponding choice obeys all restrictions."],"options":[],"conceptId":"math_linear_programming_reading_a_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Reading a Feasible Region"}', 2),
  (434, 122, 'What does x + y = 50 represent if x and y are quantities of two products?', 'text', 1, 'Look at the equality.', '{"why":"The boundary equation represents the limiting value itself.","sol":"Step 1: x + y gives the total quantity.\nStep 2: The equality says the total is exactly 50.\nStep 3: Therefore the boundary represents combinations whose total is 50.","steps":["Step 1: x + y gives the total quantity.","Step 2: The equality says the total is exactly 50.","Step 3: Therefore the boundary represents combinations whose total is 50."],"options":[],"conceptId":"math_linear_programming_interpreting_the_boundary_and_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Interpreting the Boundary and Feasible Region"}', 0),
  (435, 122, 'For x + y ≤ 100, is (40,50) within the allowed region?', 'text', 1, 'Add the coordinates.', '{"why":"The total is below the maximum of 100.","sol":"Step 1: 40 + 50 = 90.\nStep 2: 90 ≤ 100 is true.\nStep 3: Therefore the point satisfies the constraint.","steps":["Step 1: 40 + 50 = 90.","Step 2: 90 ≤ 100 is true.","Step 3: Therefore the point satisfies the constraint."],"options":[],"conceptId":"math_linear_programming_interpreting_the_boundary_and_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Interpreting the Boundary and Feasible Region"}', 1),
  (436, 122, 'For x + y ≤ 100, is (70,40) allowed?', 'text', 1, 'Calculate the total first.', '{"why":"The total exceeds the maximum allowed value.","sol":"Step 1: 70 + 40 = 110.\nStep 2: 110 ≤ 100 is false.\nStep 3: Therefore the point is outside the allowed region.","steps":["Step 1: 70 + 40 = 110.","Step 2: 110 ≤ 100 is false.","Step 3: Therefore the point is outside the allowed region."],"options":[],"conceptId":"math_linear_programming_interpreting_the_boundary_and_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Interpreting the Boundary and Feasible Region"}', 2),
  (437, 123, 'Find where 2x + y = 8 meets the x-axis.', 'text', 1, 'Set y = 0.', '{"why":"Every point on the x-axis has y = 0.","sol":"Step 1: Set y = 0.\nStep 2: 2x = 8.\nStep 3: x = 4.\nStep 4: Therefore the point is (4,0).","steps":["Step 1: Set y = 0.","Step 2: 2x = 8.","Step 3: x = 4.","Step 4: Therefore the point is (4,0)."],"options":[],"conceptId":"math_linear_programming_finding_a_corner_point_on_an_axis","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding a Corner Point on an Axis"}', 0),
  (438, 123, 'Find where 2x + y = 8 meets the y-axis.', 'text', 1, 'Set x = 0.', '{"why":"Every point on the y-axis has x = 0.","sol":"Step 1: Set x = 0.\nStep 2: y = 8.\nStep 3: Therefore the point is (0,8).","steps":["Step 1: Set x = 0.","Step 2: y = 8.","Step 3: Therefore the point is (0,8)."],"options":[],"conceptId":"math_linear_programming_finding_a_corner_point_on_an_axis","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding a Corner Point on an Axis"}', 1),
  (439, 123, 'Find the x-axis point on 3x + y = 15.', 'text', 1, 'Set y = 0.', '{"why":"Setting y to zero gives the x-axis intersection.","sol":"Step 1: Set y = 0.\nStep 2: 3x = 15.\nStep 3: x = 5.\nStep 4: Therefore the point is (5,0).","steps":["Step 1: Set y = 0.","Step 2: 3x = 15.","Step 3: x = 5.","Step 4: Therefore the point is (5,0)."],"options":[],"conceptId":"math_linear_programming_finding_a_corner_point_on_an_axis","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding a Corner Point on an Axis"}', 2),
  (440, 124, 'Find the intersection of x + y = 6 and x + 2y = 10.', 'text', 1, 'Subtract the first equation from the second.', '{"why":"The point satisfies both boundary equations.","sol":"Step 1: (x + 2y) - (x + y) = 10 - 6.\nStep 2: y = 4.\nStep 3: Substitute into x + y = 6.\nStep 4: x + 4 = 6.\nStep 5: x = 2.\nStep 6: Therefore the intersection is (2,4).","steps":["Step 1: (x + 2y) - (x + y) = 10 - 6.","Step 2: y = 4.","Step 3: Substitute into x + y = 6.","Step 4: x + 4 = 6.","Step 5: x = 2.","Step 6: Therefore the intersection is (2,4)."],"options":[],"conceptId":"math_linear_programming_finding_the_intersection_of_two_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the Intersection of Two Boundary Lines"}', 0),
  (441, 124, 'Find the intersection of 2x + y = 9 and x + y = 6.', 'text', 1, 'Subtract the second equation from the first.', '{"why":"The point lies on both boundary lines.","sol":"Step 1: (2x + y) - (x + y) = 9 - 6.\nStep 2: x = 3.\nStep 3: Substitute into x + y = 6.\nStep 4: 3 + y = 6.\nStep 5: y = 3.","steps":["Step 1: (2x + y) - (x + y) = 9 - 6.","Step 2: x = 3.","Step 3: Substitute into x + y = 6.","Step 4: 3 + y = 6.","Step 5: y = 3."],"options":[],"conceptId":"math_linear_programming_finding_the_intersection_of_two_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the Intersection of Two Boundary Lines"}', 1),
  (442, 124, 'Why must an intersection point still be checked against the other constraints?', 'text', 1, 'A point can lie on two boundaries but violate another restriction.', '{"why":"A feasible corner must satisfy every constraint, not just the two equations that produced it.","sol":"Step 1: The intersection satisfies the two equations used to find it.\nStep 2: A linear programming problem may have additional constraints.\nStep 3: The point must satisfy those as well.\nStep 4: Therefore the intersection is only a candidate until checked.","steps":["Step 1: The intersection satisfies the two equations used to find it.","Step 2: A linear programming problem may have additional constraints.","Step 3: The point must satisfy those as well.","Step 4: Therefore the intersection is only a candidate until checked."],"options":[],"conceptId":"math_linear_programming_finding_the_intersection_of_two_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the Intersection of Two Boundary Lines"}', 2),
  (443, 125, 'Is (6,4) feasible for x + y ≤ 10, x + 2y ≤ 14, x ≥ 0 and y ≥ 0?', 'text', 1, 'Test every condition.', '{"why":"The point satisfies every constraint.","sol":"Step 1: 6 + 4 = 10, so the first condition is true.\nStep 2: 6 + 2(4) = 14, so the second condition is true.\nStep 3: 6 ≥ 0 is true.\nStep 4: 4 ≥ 0 is true.\nStep 5: Therefore the point is feasible.","steps":["Step 1: 6 + 4 = 10, so the first condition is true.","Step 2: 6 + 2(4) = 14, so the second condition is true.","Step 3: 6 ≥ 0 is true.","Step 4: 4 ≥ 0 is true.","Step 5: Therefore the point is feasible."],"options":[],"conceptId":"math_linear_programming_checking_an_intersection_against_all_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Checking an Intersection Against All Constraints"}', 0),
  (444, 125, 'Is (4,5) feasible for x + y ≤ 10 and x ≥ 5?', 'text', 1, 'One constraint fails.', '{"why":"A single violated constraint makes the point infeasible.","sol":"Step 1: 4 + 5 = 9, so x + y ≤ 10 is true.\nStep 2: But 4 ≥ 5 is false.\nStep 3: Therefore the point is not feasible.","steps":["Step 1: 4 + 5 = 9, so x + y ≤ 10 is true.","Step 2: But 4 ≥ 5 is false.","Step 3: Therefore the point is not feasible."],"options":[],"conceptId":"math_linear_programming_checking_an_intersection_against_all_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Checking an Intersection Against All Constraints"}', 1),
  (445, 125, 'Can (-2,4) be a feasible point when x ≥ 0 is a constraint?', 'text', 1, 'Check the x-coordinate.', '{"why":"The point violates the non-negativity constraint.","sol":"Step 1: The x-coordinate is -2.\nStep 2: The constraint requires x ≥ 0.\nStep 3: -2 ≥ 0 is false.\nStep 4: Therefore the point cannot be feasible.","steps":["Step 1: The x-coordinate is -2.","Step 2: The constraint requires x ≥ 0.","Step 3: -2 ≥ 0 is false.","Step 4: Therefore the point cannot be feasible."],"options":[],"conceptId":"math_linear_programming_checking_an_intersection_against_all_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Checking an Intersection Against All Constraints"}', 2),
  (446, 126, 'Find the three corner points for x + y ≤ 6, x ≥ 0 and y ≥ 0.', 'text', 1, 'Find the two intercepts and include the origin.', '{"why":"The boundary and the coordinate axes form the triangular feasible region.","sol":"Step 1: x-intercept: set y = 0, giving x = 6 → (6,0).\nStep 2: y-intercept: set x = 0, giving y = 6 → (0,6).\nStep 3: The axes meet at (0,0).\nStep 4: Therefore the corners are (0,0), (6,0), and (0,6).","steps":["Step 1: x-intercept: set y = 0, giving x = 6 → (6,0).","Step 2: y-intercept: set x = 0, giving y = 6 → (0,6).","Step 3: The axes meet at (0,0).","Step 4: Therefore the corners are (0,0), (6,0), and (0,6)."],"options":[],"conceptId":"math_linear_programming_finding_corner_points_from_axes_and_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding Corner Points from Axes and Boundary Lines"}', 0),
  (447, 126, 'Find the axis corner points for 2x + y ≤ 12, x ≥ 0 and y ≥ 0.', 'text', 1, 'Find both intercepts.', '{"why":"These are the points where the boundary and axes meet.","sol":"Step 1: Set y = 0: 2x = 12, so x = 6 → (6,0).\nStep 2: Set x = 0: y = 12 → (0,12).\nStep 3: The origin is also a corner.","steps":["Step 1: Set y = 0: 2x = 12, so x = 6 → (6,0).","Step 2: Set x = 0: y = 12 → (0,12).","Step 3: The origin is also a corner."],"options":[],"conceptId":"math_linear_programming_finding_corner_points_from_axes_and_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding Corner Points from Axes and Boundary Lines"}', 1),
  (448, 126, 'Why is (0,0) often a corner point when x ≥ 0 and y ≥ 0?', 'text', 1, 'Where do the x-axis and y-axis meet?', '{"why":"The non-negativity constraints make the axes boundaries of the feasible region.","sol":"Step 1: x ≥ 0 restricts the graph to the non-negative x side.\nStep 2: y ≥ 0 restricts it to the non-negative y side.\nStep 3: The two axes meet at (0,0).\nStep 4: Therefore the origin can form a corner of the feasible region.","steps":["Step 1: x ≥ 0 restricts the graph to the non-negative x side.","Step 2: y ≥ 0 restricts it to the non-negative y side.","Step 3: The two axes meet at (0,0).","Step 4: Therefore the origin can form a corner of the feasible region."],"options":[],"conceptId":"math_linear_programming_finding_corner_points_from_axes_and_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding Corner Points from Axes and Boundary Lines"}', 2),
  (449, 127, 'A product gives KSh 400 profit per unit of x and KSh 300 profit per unit of y. What is the objective function?', 'text', 1, 'Multiply each profit per unit by the number of units.', '{"why":"The objective function represents the total profit.","sol":"Step 1: Profit from x units = 400x.\nStep 2: Profit from y units = 300y.\nStep 3: Add the two amounts.\nStep 4: Therefore P = 400x + 300y.","steps":["Step 1: Profit from x units = 400x.","Step 2: Profit from y units = 300y.","Step 3: Add the two amounts.","Step 4: Therefore P = 400x + 300y."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of an Objective Function"}', 0),
  (450, 127, 'A company spends KSh 200 on each unit of x and KSh 500 on each unit of y. Write the total cost.', 'text', 1, 'Cost = cost per unit × number of units.', '{"why":"The expression represents the total cost.","sol":"Step 1: Cost of x units = 200x.\nStep 2: Cost of y units = 500y.\nStep 3: Add them.\nStep 4: C = 200x + 500y.","steps":["Step 1: Cost of x units = 200x.","Step 2: Cost of y units = 500y.","Step 3: Add them.","Step 4: C = 200x + 500y."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of an Objective Function"}', 1),
  (451, 127, 'If P = 700x + 400y represents profit, and the aim is to obtain the greatest profit, what should be done to P?', 'text', 1, 'The greatest value is the maximum.', '{"why":"The objective is to make profit as large as possible.","sol":"Step 1: P represents profit.\nStep 2: The aim is to obtain the greatest profit.\nStep 3: Therefore P must be maximized.","steps":["Step 1: P represents profit.","Step 2: The aim is to obtain the greatest profit.","Step 3: Therefore P must be maximized."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of an Objective Function"}', 2),
  (452, 128, 'A company wants to obtain the greatest profit. What is the objective?', 'text', 1, 'What quantity is being made greatest?', '{"why":"Profit is the quantity the company wants to maximize.","sol":"Step 1: Read the phrase ''greatest profit''.\nStep 2: The quantity being considered is profit.\nStep 3: Therefore the objective is profit.","steps":["Step 1: Read the phrase ''greatest profit''.","Step 2: The quantity being considered is profit.","Step 3: Therefore the objective is profit."],"options":[],"conceptId":"math_linear_programming_identifying_the_objective_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Identifying the Objective in a Word Problem"}', 0),
  (453, 128, 'A manufacturer wants to spend the least amount of money. What is the objective?', 'text', 1, 'What quantity should be as small as possible?', '{"why":"The problem is trying to minimize the cost.","sol":"Step 1: The phrase ''least amount of money'' refers to expenditure or cost.\nStep 2: The amount must be made as small as possible.\nStep 3: Therefore the objective is cost.","steps":["Step 1: The phrase ''least amount of money'' refers to expenditure or cost.","Step 2: The amount must be made as small as possible.","Step 3: Therefore the objective is cost."],"options":[],"conceptId":"math_linear_programming_identifying_the_objective_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Identifying the Objective in a Word Problem"}', 1),
  (454, 128, 'A business wants the highest possible sales income. What is the objective?', 'text', 1, 'Sales income is another name for revenue.', '{"why":"Revenue is the quantity being made as large as possible.","sol":"Step 1: Sales income means revenue.\nStep 2: The word ''highest'' means maximum.\nStep 3: Therefore the objective is to maximize revenue.","steps":["Step 1: Sales income means revenue.","Step 2: The word ''highest'' means maximum.","Step 3: Therefore the objective is to maximize revenue."],"options":[],"conceptId":"math_linear_programming_identifying_the_objective_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Identifying the Objective in a Word Problem"}', 2),
  (455, 129, 'A pen gives KSh 20 profit and a book gives KSh 50 profit. If x pens and y books are sold, form the profit function.', 'text', 1, 'Multiply each unit profit by its quantity.', '{"why":"Total profit is the sum of the profits from both products.","sol":"Step 1: Pen profit = 20x.\nStep 2: Book profit = 50y.\nStep 3: Add the two profits.\nStep 4: P = 20x + 50y.","steps":["Step 1: Pen profit = 20x.","Step 2: Book profit = 50y.","Step 3: Add the two profits.","Step 4: P = 20x + 50y."],"options":[],"conceptId":"math_linear_programming_forming_a_profit_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Forming a Profit Objective Function"}', 0),
  (456, 129, 'A farmer earns KSh 900 per bag of maize and KSh 700 per bag of beans. Form the profit function.', 'text', 1, 'Let x be maize and y be beans.', '{"why":"Each coefficient represents the profit from one unit.","sol":"Step 1: Maize profit = 900x.\nStep 2: Bean profit = 700y.\nStep 3: Add the two.\nStep 4: P = 900x + 700y.","steps":["Step 1: Maize profit = 900x.","Step 2: Bean profit = 700y.","Step 3: Add the two.","Step 4: P = 900x + 700y."],"options":[],"conceptId":"math_linear_programming_forming_a_profit_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Forming a Profit Objective Function"}', 1),
  (457, 129, 'A shop earns KSh 150 on each shirt and KSh 250 on each jacket. Form the profit function.', 'text', 1, 'Use x for shirts and y for jackets.', '{"why":"The function adds the profit contributed by each product.","sol":"Step 1: Shirt profit = 150x.\nStep 2: Jacket profit = 250y.\nStep 3: Total profit = 150x + 250y.","steps":["Step 1: Shirt profit = 150x.","Step 2: Jacket profit = 250y.","Step 3: Total profit = 150x + 250y."],"options":[],"conceptId":"math_linear_programming_forming_a_profit_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Forming a Profit Objective Function"}', 2),
  (458, 130, 'A material costs KSh 400 per unit and another costs KSh 600 per unit. Form the total cost function.', 'text', 1, 'Let x and y be the quantities.', '{"why":"The total cost is the sum of the two individual costs.","sol":"Step 1: First material costs 400x.\nStep 2: Second material costs 600y.\nStep 3: Add them.\nStep 4: C = 400x + 600y.","steps":["Step 1: First material costs 400x.","Step 2: Second material costs 600y.","Step 3: Add them.","Step 4: C = 400x + 600y."],"options":[],"conceptId":"math_linear_programming_forming_a_cost_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Forming a Cost Objective Function"}', 0),
  (459, 130, 'Pens cost KSh 15 each and books cost KSh 80 each. Form the total cost function.', 'text', 1, 'Let x be pens and y be books.', '{"why":"Each coefficient is the cost of one unit.","sol":"Step 1: Pen cost = 15x.\nStep 2: Book cost = 80y.\nStep 3: Total cost = 15x + 80y.","steps":["Step 1: Pen cost = 15x.","Step 2: Book cost = 80y.","Step 3: Total cost = 15x + 80y."],"options":[],"conceptId":"math_linear_programming_forming_a_cost_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Forming a Cost Objective Function"}', 1),
  (460, 130, 'A company wants to spend the least possible amount and its cost function is C = 700x + 500y. What is the objective?', 'text', 1, 'Least means minimum.', '{"why":"The objective is to make the total cost as small as possible.","sol":"Step 1: C represents total cost.\nStep 2: The problem asks for the least cost.\nStep 3: Therefore C must be minimized.","steps":["Step 1: C represents total cost.","Step 2: The problem asks for the least cost.","Step 3: Therefore C must be minimized."],"options":[],"conceptId":"math_linear_programming_forming_a_cost_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Forming a Cost Objective Function"}', 2),
  (461, 131, 'A product sells for KSh 500 per unit and another sells for KSh 800 per unit. Form the revenue function.', 'text', 1, 'Revenue = selling price × quantity.', '{"why":"Revenue comes from multiplying selling price by the number sold.","sol":"Step 1: Revenue from the first product = 500x.\nStep 2: Revenue from the second product = 800y.\nStep 3: Add them.\nStep 4: R = 500x + 800y.","steps":["Step 1: Revenue from the first product = 500x.","Step 2: Revenue from the second product = 800y.","Step 3: Add them.","Step 4: R = 500x + 800y."],"options":[],"conceptId":"math_linear_programming_forming_a_revenue_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Forming a Revenue Objective Function"}', 0),
  (462, 131, 'A farmer sells maize at KSh 3,500 per bag and beans at KSh 4,000 per bag. Form the revenue function.', 'text', 1, 'Use x for maize and y for beans.', '{"why":"The coefficients are the selling prices per unit.","sol":"Step 1: Maize revenue = 3500x.\nStep 2: Bean revenue = 4000y.\nStep 3: Add the revenues.\nStep 4: R = 3500x + 4000y.","steps":["Step 1: Maize revenue = 3500x.","Step 2: Bean revenue = 4000y.","Step 3: Add the revenues.","Step 4: R = 3500x + 4000y."],"options":[],"conceptId":"math_linear_programming_forming_a_revenue_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Forming a Revenue Objective Function"}', 1),
  (463, 131, 'If R = 120x + 200y represents revenue and the aim is to get the highest revenue, what should be done?', 'text', 1, 'Highest means maximum.', '{"why":"The objective is to make revenue as large as possible.","sol":"Step 1: R represents revenue.\nStep 2: The aim is the highest revenue.\nStep 3: Therefore R should be maximized.","steps":["Step 1: R represents revenue.","Step 2: The aim is the highest revenue.","Step 3: Therefore R should be maximized."],"options":[],"conceptId":"math_linear_programming_forming_a_revenue_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Forming a Revenue Objective Function"}', 2),
  (464, 132, 'A product gives KSh 900 profit per unit. If x units are produced, what expression represents the profit?', 'text', 1, 'Multiply 900 by x.', '{"why":"The per-unit profit becomes the coefficient of x.","sol":"Step 1: Profit per unit = 900.\nStep 2: Number of units = x.\nStep 3: Total profit = 900 × x.\nStep 4: Therefore profit = 900x.","steps":["Step 1: Profit per unit = 900.","Step 2: Number of units = x.","Step 3: Total profit = 900 × x.","Step 4: Therefore profit = 900x."],"options":[],"conceptId":"math_linear_programming_translating_per_unit_wording_into_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating Per-Unit Wording into Coefficients"}', 0),
  (465, 132, 'A chair costs KSh 700 each. If y chairs are bought, write the cost.', 'text', 1, 'Cost = 700 × number of chairs.', '{"why":"The number 700 tells us the cost of each chair.","sol":"Step 1: Cost per chair = 700.\nStep 2: Number of chairs = y.\nStep 3: Total cost = 700 × y.\nStep 4: Therefore cost = 700y.","steps":["Step 1: Cost per chair = 700.","Step 2: Number of chairs = y.","Step 3: Total cost = 700 × y.","Step 4: Therefore cost = 700y."],"options":[],"conceptId":"math_linear_programming_translating_per_unit_wording_into_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating Per-Unit Wording into Coefficients"}', 1),
  (466, 132, 'A shirt gives KSh 250 profit each and a trouser gives KSh 400 profit each. Let x be shirts and y be trousers. Form the profit function.', 'text', 1, 'Use 250 with x and 400 with y.', '{"why":"Each per-unit profit becomes the coefficient of its corresponding variable.","sol":"Step 1: Shirt profit = 250x.\nStep 2: Trouser profit = 400y.\nStep 3: Add them.\nStep 4: P = 250x + 400y.","steps":["Step 1: Shirt profit = 250x.","Step 2: Trouser profit = 400y.","Step 3: Add them.","Step 4: P = 250x + 400y."],"options":[],"conceptId":"math_linear_programming_translating_per_unit_wording_into_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating Per-Unit Wording into Coefficients"}', 2),
  (467, 133, 'Find P = 400x + 200y at (3, 5).', 'text', 1, 'Use x = 3 and y = 5.', '{"why":"The coordinates replace x and y in the objective function.","sol":"Step 1: P = 400(3) + 200(5).\nStep 2: P = 1200 + 1000.\nStep 3: P = 2200.","steps":["Step 1: P = 400(3) + 200(5).","Step 2: P = 1200 + 1000.","Step 3: P = 2200."],"options":[],"conceptId":"math_linear_programming_evaluating_an_objective_function_at_a_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Evaluating an Objective Function at a Point"}', 0),
  (468, 133, 'Find C = 300x + 600y at (2, 4).', 'text', 1, 'Substitute x = 2 and y = 4.', '{"why":"The point tells us the values of x and y.","sol":"Step 1: C = 300(2) + 600(4).\nStep 2: C = 600 + 2400.\nStep 3: C = 3000.","steps":["Step 1: C = 300(2) + 600(4).","Step 2: C = 600 + 2400.","Step 3: C = 3000."],"options":[],"conceptId":"math_linear_programming_evaluating_an_objective_function_at_a_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Evaluating an Objective Function at a Point"}', 1),
  (469, 133, 'Find R = 800x + 500y at (4, 3).', 'text', 1, 'Replace x by 4 and y by 3.', '{"why":"Evaluating the objective means calculating its value at the given point.","sol":"Step 1: R = 800(4) + 500(3).\nStep 2: R = 3200 + 1500.\nStep 3: R = 4700.","steps":["Step 1: R = 800(4) + 500(3).","Step 2: R = 3200 + 1500.","Step 3: R = 4700."],"options":[],"conceptId":"math_linear_programming_evaluating_an_objective_function_at_a_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Evaluating an Objective Function at a Point"}', 2),
  (470, 134, 'P = 400x + 300y. Which point gives the greater profit: (2,3) or (4,1)?', 'text', 1, 'Calculate P at both points.', '{"why":"The second point produces the greater objective value.","sol":"Step 1: At (2,3): P = 400(2) + 300(3) = 800 + 900 = 1700.\nStep 2: At (4,1): P = 400(4) + 300(1) = 1600 + 300 = 1900.\nStep 3: Compare 1700 and 1900.\nStep 4: 1900 is greater.","steps":["Step 1: At (2,3): P = 400(2) + 300(3) = 800 + 900 = 1700.","Step 2: At (4,1): P = 400(4) + 300(1) = 1600 + 300 = 1900.","Step 3: Compare 1700 and 1900.","Step 4: 1900 is greater."],"options":[],"conceptId":"math_linear_programming_comparing_objective_values_at_two_points","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Comparing Objective Values at Two Points"}', 0),
  (471, 134, 'C = 500x + 200y. Which point gives the lower cost: (2,4) or (5,1)?', 'text', 1, 'Calculate both costs.', '{"why":"The first point gives the smaller cost.","sol":"Step 1: At (2,4): C = 500(2) + 200(4) = 1000 + 800 = 1800.\nStep 2: At (5,1): C = 500(5) + 200(1) = 2500 + 200 = 2700.\nStep 3: Compare 1800 and 2700.\nStep 4: 1800 is lower.","steps":["Step 1: At (2,4): C = 500(2) + 200(4) = 1000 + 800 = 1800.","Step 2: At (5,1): C = 500(5) + 200(1) = 2500 + 200 = 2700.","Step 3: Compare 1800 and 2700.","Step 4: 1800 is lower."],"options":[],"conceptId":"math_linear_programming_comparing_objective_values_at_two_points","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Comparing Objective Values at Two Points"}', 1),
  (472, 134, 'R = 300x + 400y. Compare (3,2) and (1,5).', 'text', 1, 'Evaluate R at each point.', '{"why":"The objective value at (1,5) is larger.","sol":"Step 1: At (3,2): R = 300(3) + 400(2) = 900 + 800 = 1700.\nStep 2: At (1,5): R = 300(1) + 400(5) = 300 + 2000 = 2300.\nStep 3: 2300 is greater than 1700.","steps":["Step 1: At (3,2): R = 300(3) + 400(2) = 900 + 800 = 1700.","Step 2: At (1,5): R = 300(1) + 400(5) = 300 + 2000 = 2300.","Step 3: 2300 is greater than 1700."],"options":[],"conceptId":"math_linear_programming_comparing_objective_values_at_two_points","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Comparing Objective Values at Two Points"}', 2),
  (473, 135, 'What does maximise P mean?', 'text', 1, 'Think about the word maximum.', '{"why":"Maximisation always seeks the largest objective value.","sol":"Step 1: Maximum means greatest.\nStep 2: P is the objective function.\nStep 3: Therefore maximise P means find the greatest possible value of P.","steps":["Step 1: Maximum means greatest.","Step 2: P is the objective function.","Step 3: Therefore maximise P means find the greatest possible value of P."],"options":[],"conceptId":"math_linear_programming_meaning_of_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of Maximisation"}', 0),
  (474, 135, 'P = 400x + 200y. If two feasible points give P = 1800 and P = 2200, which value is preferred when maximising P?', 'text', 1, 'Choose the larger value.', '{"why":"Maximisation chooses the greater objective value.","sol":"Step 1: The values are 1800 and 2200.\nStep 2: 2200 is greater than 1800.\nStep 3: Therefore 2200 is preferred.","steps":["Step 1: The values are 1800 and 2200.","Step 2: 2200 is greater than 1800.","Step 3: Therefore 2200 is preferred."],"options":[],"conceptId":"math_linear_programming_meaning_of_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of Maximisation"}', 1),
  (475, 135, 'A farmer wants maximum profit. If one feasible production plan gives KSh 8,000 and another gives KSh 9,500, which plan is better?', 'text', 1, 'Maximum profit means greater profit.', '{"why":"The objective is to obtain the greatest profit.","sol":"Step 1: Compare KSh 8,000 and KSh 9,500.\nStep 2: KSh 9,500 is greater.\nStep 3: Therefore the plan producing KSh 9,500 is better.","steps":["Step 1: Compare KSh 8,000 and KSh 9,500.","Step 2: KSh 9,500 is greater.","Step 3: Therefore the plan producing KSh 9,500 is better."],"options":[],"conceptId":"math_linear_programming_meaning_of_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of Maximisation"}', 2),
  (476, 136, 'What does minimise C mean?', 'text', 1, 'Think about the word minimum.', '{"why":"Minimisation seeks the lowest objective value.","sol":"Step 1: Minimum means smallest.\nStep 2: C is the objective function.\nStep 3: Therefore minimise C means find the smallest possible value of C.","steps":["Step 1: Minimum means smallest.","Step 2: C is the objective function.","Step 3: Therefore minimise C means find the smallest possible value of C."],"options":[],"conceptId":"math_linear_programming_meaning_of_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of Minimisation"}', 0),
  (477, 136, 'A company wants minimum cost. Two feasible plans cost KSh 3,500 and KSh 4,200. Which is preferred?', 'text', 1, 'Choose the lower cost.', '{"why":"Minimum cost means choosing the smaller cost.","sol":"Step 1: Compare 3500 and 4200.\nStep 2: 3500 is smaller.\nStep 3: Therefore the KSh 3,500 plan is preferred.","steps":["Step 1: Compare 3500 and 4200.","Step 2: 3500 is smaller.","Step 3: Therefore the KSh 3,500 plan is preferred."],"options":[],"conceptId":"math_linear_programming_meaning_of_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of Minimisation"}', 1),
  (478, 136, 'Three feasible solutions give costs of KSh 7,000, KSh 5,500 and KSh 6,200. What is the minimum cost?', 'text', 1, 'Find the smallest number.', '{"why":"The minimum is the smallest objective value.","sol":"Step 1: Compare 7000, 5500 and 6200.\nStep 2: 5500 is the smallest.\nStep 3: Therefore the minimum cost is KSh 5,500.","steps":["Step 1: Compare 7000, 5500 and 6200.","Step 2: 5500 is the smallest.","Step 3: Therefore the minimum cost is KSh 5,500."],"options":[],"conceptId":"math_linear_programming_meaning_of_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of Minimisation"}', 2),
  (479, 137, 'Three feasible plans give profits of KSh 4,000, KSh 6,000 and KSh 5,000. Which is optimal when profit is maximized?', 'text', 1, 'Choose the greatest profit.', '{"why":"Maximum profit requires the greatest feasible profit.","sol":"Step 1: Compare 4000, 6000 and 5000.\nStep 2: 6000 is the greatest.\nStep 3: Therefore the plan giving KSh 6,000 is optimal.","steps":["Step 1: Compare 4000, 6000 and 5000.","Step 2: 6000 is the greatest.","Step 3: Therefore the plan giving KSh 6,000 is optimal."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_optimal_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of an Optimal Solution"}', 0),
  (480, 137, 'Three feasible plans cost KSh 8,000, KSh 6,500 and KSh 7,200. Which is optimal when cost is minimized?', 'text', 1, 'Choose the smallest cost.', '{"why":"Minimum cost requires the smallest feasible cost.","sol":"Step 1: Compare 8000, 6500 and 7200.\nStep 2: 6500 is the smallest.\nStep 3: Therefore the KSh 6,500 plan is optimal.","steps":["Step 1: Compare 8000, 6500 and 7200.","Step 2: 6500 is the smallest.","Step 3: Therefore the KSh 6,500 plan is optimal."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_optimal_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of an Optimal Solution"}', 1),
  (481, 137, 'If two feasible points give objective values 3,200 and 3,800, which is optimal when maximizing?', 'text', 1, 'Maximum means greatest.', '{"why":"The greater objective value is preferred during maximisation.","sol":"Step 1: Compare 3200 and 3800.\nStep 2: 3800 is greater.\nStep 3: Therefore the point giving 3800 is optimal.","steps":["Step 1: Compare 3200 and 3800.","Step 2: 3800 is greater.","Step 3: Therefore the point giving 3800 is optimal."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_optimal_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of an Optimal Solution"}', 2),
  (482, 138, 'Why do we test corner points in a linear programming problem?', 'text', 1, 'Think about where the optimum occurs for a linear objective.', '{"why":"The corner-point method allows us to find the optimum without checking every feasible point.","sol":"Step 1: The feasible region contains many possible points.\nStep 2: The objective function is linear.\nStep 3: When an optimum exists, its best value occurs at a corner point.\nStep 4: Therefore we test the corner points.","steps":["Step 1: The feasible region contains many possible points.","Step 2: The objective function is linear.","Step 3: When an optimum exists, its best value occurs at a corner point.","Step 4: Therefore we test the corner points."],"options":[],"conceptId":"math_linear_programming_why_corner_points_are_tested","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Why Corner Points Are Tested"}', 0),
  (483, 138, 'A feasible region has four corner points. Should a point outside the region be tested as a possible optimum?', 'text', 1, 'First ask whether the point is feasible.', '{"why":"Only feasible points can be considered as solutions.","sol":"Step 1: An optimum must satisfy all constraints.\nStep 2: A point outside the feasible region violates at least one constraint.\nStep 3: Therefore it cannot be an allowed solution.","steps":["Step 1: An optimum must satisfy all constraints.","Step 2: A point outside the feasible region violates at least one constraint.","Step 3: Therefore it cannot be an allowed solution."],"options":[],"conceptId":"math_linear_programming_why_corner_points_are_tested","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Why Corner Points Are Tested"}', 1),
  (484, 138, 'A feasible region has corners A, B, C and D. What points should normally be tested for the optimum?', 'text', 1, 'Use the corner-point method.', '{"why":"The corner points are the candidates for the optimum.","sol":"Step 1: The feasible region has four corner points.\nStep 2: The objective should be evaluated at those corners.\nStep 3: Therefore test A, B, C and D.","steps":["Step 1: The feasible region has four corner points.","Step 2: The objective should be evaluated at those corners.","Step 3: Therefore test A, B, C and D."],"options":[],"conceptId":"math_linear_programming_why_corner_points_are_tested","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Why Corner Points Are Tested"}', 2),
  (485, 139, 'P = 300x + 200y. Find P at (4,2).', 'text', 1, 'Substitute x = 4 and y = 2.', '{"why":"The coordinates are substituted into the objective function.","sol":"Step 1: P = 300(4) + 200(2).\nStep 2: P = 1200 + 400.\nStep 3: P = 1600.","steps":["Step 1: P = 300(4) + 200(2).","Step 2: P = 1200 + 400.","Step 3: P = 1600."],"options":[],"conceptId":"math_linear_programming_evaluating_the_objective_at_every_corner_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Evaluating the Objective at Every Corner Point"}', 0),
  (486, 139, 'C = 500x + 100y. Find C at (3,5).', 'text', 1, 'Use x = 3 and y = 5.', '{"why":"Evaluating a corner means calculating the objective value at that point.","sol":"Step 1: C = 500(3) + 100(5).\nStep 2: C = 1500 + 500.\nStep 3: C = 2000.","steps":["Step 1: C = 500(3) + 100(5).","Step 2: C = 1500 + 500.","Step 3: C = 2000."],"options":[],"conceptId":"math_linear_programming_evaluating_the_objective_at_every_corner_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Evaluating the Objective at Every Corner Point"}', 1),
  (487, 139, 'P = 600x + 400y. Find P at (2,3).', 'text', 1, 'Replace x by 2 and y by 3.', '{"why":"The point gives the values of x and y used in the objective.","sol":"Step 1: P = 600(2) + 400(3).\nStep 2: P = 1200 + 1200.\nStep 3: P = 2400.","steps":["Step 1: P = 600(2) + 400(3).","Step 2: P = 1200 + 1200.","Step 3: P = 2400."],"options":[],"conceptId":"math_linear_programming_evaluating_the_objective_at_every_corner_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Evaluating the Objective at Every Corner Point"}', 2),
  (488, 140, 'The objective values at four corners are 900, 1400, 1800 and 1200. What is the maximum?', 'text', 1, 'Choose the greatest number.', '{"why":"Maximum means greatest.","sol":"Step 1: Compare 900, 1400, 1800 and 1200.\nStep 2: 1800 is the greatest.\nStep 3: Therefore the maximum is 1800.","steps":["Step 1: Compare 900, 1400, 1800 and 1200.","Step 2: 1800 is the greatest.","Step 3: Therefore the maximum is 1800."],"options":[],"conceptId":"math_linear_programming_finding_the_maximum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the Maximum from Corner Values"}', 0),
  (489, 140, 'A profit function gives 2,100, 2,700 and 2,400 at three feasible corners. Which gives maximum profit?', 'text', 1, 'Choose the largest profit.', '{"why":"The greatest profit is the maximum.","sol":"Step 1: Compare 2100, 2700 and 2400.\nStep 2: 2700 is greatest.\nStep 3: Therefore the second corner gives maximum profit.","steps":["Step 1: Compare 2100, 2700 and 2400.","Step 2: 2700 is greatest.","Step 3: Therefore the second corner gives maximum profit."],"options":[],"conceptId":"math_linear_programming_finding_the_maximum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the Maximum from Corner Values"}', 1),
  (490, 140, 'The corner values of P are 3,000, 2,500, 3,800 and 3,200. Which value is the maximum?', 'text', 1, 'Find the largest value.', '{"why":"Maximization selects the greatest objective value.","sol":"Step 1: Compare all four values.\nStep 2: 3800 is the greatest.\nStep 3: Therefore the maximum value is 3800.","steps":["Step 1: Compare all four values.","Step 2: 3800 is the greatest.","Step 3: Therefore the maximum value is 3800."],"options":[],"conceptId":"math_linear_programming_finding_the_maximum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the Maximum from Corner Values"}', 2),
  (491, 141, 'The objective values at four corners are 2,000, 1,500, 1,800 and 2,200. What is the minimum?', 'text', 1, 'Choose the smallest value.', '{"why":"Minimum means smallest.","sol":"Step 1: Compare 2000, 1500, 1800 and 2200.\nStep 2: 1500 is the smallest.\nStep 3: Therefore the minimum is 1500.","steps":["Step 1: Compare 2000, 1500, 1800 and 2200.","Step 2: 1500 is the smallest.","Step 3: Therefore the minimum is 1500."],"options":[],"conceptId":"math_linear_programming_finding_the_minimum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the Minimum from Corner Values"}', 0),
  (492, 141, 'Three feasible points give costs of KSh 4,000, KSh 3,200 and KSh 3,700. Which gives minimum cost?', 'text', 1, 'Choose the lowest cost.', '{"why":"Minimum cost means choosing the smallest feasible cost.","sol":"Step 1: Compare 4000, 3200 and 3700.\nStep 2: 3200 is the smallest.\nStep 3: Therefore the second point gives minimum cost.","steps":["Step 1: Compare 4000, 3200 and 3700.","Step 2: 3200 is the smallest.","Step 3: Therefore the second point gives minimum cost."],"options":[],"conceptId":"math_linear_programming_finding_the_minimum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the Minimum from Corner Values"}', 1),
  (493, 141, 'The corner values of C are 700, 900, 650 and 800. Which is the minimum?', 'text', 1, 'Find the smallest number.', '{"why":"Minimization selects the smallest objective value.","sol":"Step 1: Compare all four values.\nStep 2: 650 is the smallest.\nStep 3: Therefore the minimum is 650.","steps":["Step 1: Compare all four values.","Step 2: 650 is the smallest.","Step 3: Therefore the minimum is 650."],"options":[],"conceptId":"math_linear_programming_finding_the_minimum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the Minimum from Corner Values"}', 2),
  (494, 142, 'A maximum objective value of 5,000 occurs at (4,3). What is the optimal point?', 'text', 1, 'The optimal point is the point where the maximum occurs.', '{"why":"The optimal point identifies the variable values producing the best result.","sol":"Step 1: The maximum value is 5000.\nStep 2: It occurs at (4,3).\nStep 3: Therefore the optimal point is (4,3).","steps":["Step 1: The maximum value is 5000.","Step 2: It occurs at (4,3).","Step 3: Therefore the optimal point is (4,3)."],"options":[],"conceptId":"math_linear_programming_finding_the_optimal_point_and_optimal_value","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the Optimal Point and Optimal Value"}', 0),
  (495, 142, 'A minimum cost of KSh 2,400 occurs at (2,5). What is the minimum cost?', 'text', 1, 'The optimal value is the value of the objective.', '{"why":"The optimal value is the minimum value of the objective function.","sol":"Step 1: The problem states that the minimum cost is 2400.\nStep 2: Therefore the optimal value is KSh 2,400.","steps":["Step 1: The problem states that the minimum cost is 2400.","Step 2: Therefore the optimal value is KSh 2,400."],"options":[],"conceptId":"math_linear_programming_finding_the_optimal_point_and_optimal_value","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the Optimal Point and Optimal Value"}', 1),
  (496, 142, 'Maximum profit is KSh 8,000 at (5,2). State both the optimal point and optimal value.', 'text', 1, 'Give both pieces of information.', '{"why":"A complete optimisation answer identifies both the quantities and the resulting objective value.","sol":"Step 1: The point is (5,2).\nStep 2: The maximum profit is KSh 8,000.\nStep 3: Therefore report both.","steps":["Step 1: The point is (5,2).","Step 2: The maximum profit is KSh 8,000.","Step 3: Therefore report both."],"options":[],"conceptId":"math_linear_programming_finding_the_optimal_point_and_optimal_value","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the Optimal Point and Optimal Value"}', 2),
  (497, 143, 'P = 400x + 300y. The corner points are (0,0), (5,0), (3,4), (0,4). Which point gives the maximum P?', 'text', 1, 'Evaluate P at all four points.', '{"why":"The point (3,4) gives the greatest objective value.","sol":"Step 1: At (0,0): P = 0.\nStep 2: At (5,0): P = 400(5) = 2000.\nStep 3: At (3,4): P = 400(3) + 300(4) = 1200 + 1200 = 2400.\nStep 4: At (0,4): P = 1200.\nStep 5: The greatest value is 2400.","steps":["Step 1: At (0,0): P = 0.","Step 2: At (5,0): P = 400(5) = 2000.","Step 3: At (3,4): P = 400(3) + 300(4) = 1200 + 1200 = 2400.","Step 4: At (0,4): P = 1200.","Step 5: The greatest value is 2400."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Maximisation"}', 0),
  (498, 143, 'P = 600x + 200y. The corners are (0,0), (4,0), (3,2), (0,3). Find the maximum P.', 'text', 1, 'Calculate P at every corner.', '{"why":"The corner (4,0) gives the greatest objective value.","sol":"Step 1: At (0,0): P = 0.\nStep 2: At (4,0): P = 600(4) = 2400.\nStep 3: At (3,2): P = 600(3) + 200(2) = 1800 + 400 = 2200.\nStep 4: At (0,3): P = 600.\nStep 5: The greatest value is 2400.","steps":["Step 1: At (0,0): P = 0.","Step 2: At (4,0): P = 600(4) = 2400.","Step 3: At (3,2): P = 600(3) + 200(2) = 1800 + 400 = 2200.","Step 4: At (0,3): P = 600.","Step 5: The greatest value is 2400."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Maximisation"}', 1),
  (499, 143, 'P = 300x + 500y. The corners are (0,0), (6,0), (4,3), (0,5). Find the optimal point and maximum P.', 'text', 1, 'Evaluate P at all four corners.', '{"why":"The optimal point is the feasible corner producing the greatest objective value.","sol":"Step 1: At (0,0): P = 0.\nStep 2: At (6,0): P = 300(6) = 1800.\nStep 3: At (4,3): P = 300(4) + 500(3) = 1200 + 1500 = 2700.\nStep 4: At (0,5): P = 500(5) = 2500.\nStep 5: The greatest value is 2700.\nStep 6: Therefore the optimal point is (4,3).","steps":["Step 1: At (0,0): P = 0.","Step 2: At (6,0): P = 300(6) = 1800.","Step 3: At (4,3): P = 300(4) + 500(3) = 1200 + 1500 = 2700.","Step 4: At (0,5): P = 500(5) = 2500.","Step 5: The greatest value is 2700.","Step 6: Therefore the optimal point is (4,3)."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Maximisation"}', 2),
  (500, 144, 'C = 300x + 200y. The corner points are (1,1), (4,1), (3,3), (1,4). Find the minimum cost.', 'text', 1, 'Evaluate C at every corner and choose the smallest.', '{"why":"The point (1,1) produces the smallest feasible cost.","sol":"Step 1: At (1,1): C = 300 + 200 = 500.\nStep 2: At (4,1): C = 1200 + 200 = 1400.\nStep 3: At (3,3): C = 900 + 600 = 1500.\nStep 4: At (1,4): C = 300 + 800 = 1100.\nStep 5: The smallest value is 500.","steps":["Step 1: At (1,1): C = 300 + 200 = 500.","Step 2: At (4,1): C = 1200 + 200 = 1400.","Step 3: At (3,3): C = 900 + 600 = 1500.","Step 4: At (1,4): C = 300 + 800 = 1100.","Step 5: The smallest value is 500."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Minimisation"}', 0);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (501, 144, 'C = 500x + 400y. The corners are (1,2), (4,2), (3,5). Which gives the minimum?', 'text', 1, 'Calculate all three costs.', '{"why":"The first point gives the smallest objective value.","sol":"Step 1: At (1,2): C = 500 + 800 = 1300.\nStep 2: At (4,2): C = 2000 + 800 = 2800.\nStep 3: At (3,5): C = 1500 + 2000 = 3500.\nStep 4: The smallest value is 1300.","steps":["Step 1: At (1,2): C = 500 + 800 = 1300.","Step 2: At (4,2): C = 2000 + 800 = 2800.","Step 3: At (3,5): C = 1500 + 2000 = 3500.","Step 4: The smallest value is 1300."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Minimisation"}', 1),
  (502, 144, 'C = 200x + 600y. The corners are (2,1), (5,1), (4,3), (2,4). Find the optimal point and minimum C.', 'text', 1, 'Evaluate C at each corner.', '{"why":"The optimal point is the feasible corner with the smallest objective value.","sol":"Step 1: At (2,1): C = 200(2) + 600(1) = 400 + 600 = 1000.\nStep 2: At (5,1): C = 1000 + 600 = 1600.\nStep 3: At (4,3): C = 800 + 1800 = 2600.\nStep 4: At (2,4): C = 400 + 2400 = 2800.\nStep 5: The smallest value is 1000.","steps":["Step 1: At (2,1): C = 200(2) + 600(1) = 400 + 600 = 1000.","Step 2: At (5,1): C = 1000 + 600 = 1600.","Step 3: At (4,3): C = 800 + 1800 = 2600.","Step 4: At (2,4): C = 400 + 2400 = 2800.","Step 5: The smallest value is 1000."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Minimisation"}', 2),
  (503, 145, 'A feasible region has corners (0,0), (5,0), (3,4), (0,6). P = 300x + 400y. Find the maximum P.', 'text', 1, 'Evaluate P at all four corners.', '{"why":"The corner (3,4) produces the greatest objective value.","sol":"Step 1: At (0,0): P = 0.\nStep 2: At (5,0): P = 300(5) = 1500.\nStep 3: At (3,4): P = 300(3) + 400(4) = 900 + 1600 = 2500.\nStep 4: At (0,6): P = 400(6) = 2400.\nStep 5: The greatest value is 2500.","steps":["Step 1: At (0,0): P = 0.","Step 2: At (5,0): P = 300(5) = 1500.","Step 3: At (3,4): P = 300(3) + 400(4) = 900 + 1600 = 2500.","Step 4: At (0,6): P = 400(6) = 2400.","Step 5: The greatest value is 2500."],"options":[],"conceptId":"math_linear_programming_complete_linear_programming_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Complete Linear Programming Solution"}', 0),
  (504, 145, 'A feasible region has corners (1,1), (5,1), (4,3), (1,4). C = 200x + 300y. Find the minimum C.', 'text', 1, 'Evaluate C at each corner.', '{"why":"The point (1,1) gives the smallest feasible cost.","sol":"Step 1: At (1,1): C = 200 + 300 = 500.\nStep 2: At (5,1): C = 1000 + 300 = 1300.\nStep 3: At (4,3): C = 800 + 900 = 1700.\nStep 4: At (1,4): C = 200 + 1200 = 1400.\nStep 5: The smallest value is 500.","steps":["Step 1: At (1,1): C = 200 + 300 = 500.","Step 2: At (5,1): C = 1000 + 300 = 1300.","Step 3: At (4,3): C = 800 + 900 = 1700.","Step 4: At (1,4): C = 200 + 1200 = 1400.","Step 5: The smallest value is 500."],"options":[],"conceptId":"math_linear_programming_complete_linear_programming_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Complete Linear Programming Solution"}', 1),
  (505, 145, 'Why must you check every relevant corner point before declaring the maximum or minimum?', 'text', 1, 'Could an unchecked corner have a better value?', '{"why":"Checking every relevant corner prevents us from missing the best feasible solution.","sol":"Step 1: Each corner is a candidate for the optimum.\nStep 2: An unchecked corner could have a greater value when maximizing.\nStep 3: It could also have a smaller value when minimizing.\nStep 4: Therefore all relevant corner points must be evaluated.","steps":["Step 1: Each corner is a candidate for the optimum.","Step 2: An unchecked corner could have a greater value when maximizing.","Step 3: It could also have a smaller value when minimizing.","Step 4: Therefore all relevant corner points must be evaluated."],"options":[],"conceptId":"math_linear_programming_complete_linear_programming_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Complete Linear Programming Solution"}', 2),
  (506, 146, 'A shop sells shirts and trousers. Let x represent shirts and y represent trousers. What does x represent?', 'text', 1, 'Read the variable definition.', '{"why":"A decision variable must have a clearly defined meaning.","sol":"Step 1: The problem defines x as the number of shirts.\nStep 2: Therefore x represents the number of shirts.","steps":["Step 1: The problem defines x as the number of shirts.","Step 2: Therefore x represents the number of shirts."],"options":[],"conceptId":"math_linear_programming_defining_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Defining Decision Variables"}', 0),
  (507, 146, 'A farmer produces maize and beans. Define x as maize and y as beans.', 'text', 1, 'State exactly what each variable counts.', '{"why":"Clear variable definitions make the later mathematical model understandable.","sol":"Step 1: Let x represent the number of bags of maize.\nStep 2: Let y represent the number of bags of beans.","steps":["Step 1: Let x represent the number of bags of maize.","Step 2: Let y represent the number of bags of beans."],"options":[],"conceptId":"math_linear_programming_defining_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Defining Decision Variables"}', 1),
  (508, 146, 'A factory makes tables and chairs. What could x and y represent?', 'text', 1, 'Use the two products as the two variables.', '{"why":"The variables represent the quantities the factory chooses to produce.","sol":"Step 1: Let x represent the number of tables.\nStep 2: Let y represent the number of chairs.","steps":["Step 1: Let x represent the number of tables.","Step 2: Let y represent the number of chairs."],"options":[],"conceptId":"math_linear_programming_defining_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Defining Decision Variables"}', 2),
  (509, 147, 'A farmer can plant at most 40 acres. If x is the number of acres planted, write the inequality.', 'text', 1, 'At most means no more than.', '{"why":"At most means the quantity cannot exceed the stated limit.","sol":"Step 1: The maximum allowed is 40.\nStep 2: The planted area can be 40 or less.\nStep 3: Therefore x ≤ 40.","steps":["Step 1: The maximum allowed is 40.","Step 2: The planted area can be 40 or less.","Step 3: Therefore x ≤ 40."],"options":[],"conceptId":"math_linear_programming_translating_at_most_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating ''At Most'' into an Inequality"}', 0),
  (510, 147, 'A truck can carry at most 500 kg. If x kg is loaded, write the inequality.', 'text', 1, 'Can the load be greater than 500 kg?', '{"why":"The load must not exceed 500 kg.","sol":"Step 1: The maximum load is 500 kg.\nStep 2: The load may be less than or equal to 500 kg.\nStep 3: Therefore x ≤ 500.","steps":["Step 1: The maximum load is 500 kg.","Step 2: The load may be less than or equal to 500 kg.","Step 3: Therefore x ≤ 500."],"options":[],"conceptId":"math_linear_programming_translating_at_most_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating ''At Most'' into an Inequality"}', 1),
  (511, 147, 'A school has at most 60 computers. If x and y are two types of computers, write the total constraint.', 'text', 1, 'Add the two quantities.', '{"why":"The total is limited to 60 or fewer.","sol":"Step 1: The total number of computers is x + y.\nStep 2: The total cannot exceed 60.\nStep 3: Therefore x + y ≤ 60.","steps":["Step 1: The total number of computers is x + y.","Step 2: The total cannot exceed 60.","Step 3: Therefore x + y ≤ 60."],"options":[],"conceptId":"math_linear_programming_translating_at_most_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating ''At Most'' into an Inequality"}', 2),
  (512, 148, 'A factory must produce at least 50 units. If x is the number produced, write the inequality.', 'text', 1, 'At least means no less than.', '{"why":"At least means the quantity must not fall below the stated amount.","sol":"Step 1: The required minimum is 50.\nStep 2: The number produced can be 50 or more.\nStep 3: Therefore x ≥ 50.","steps":["Step 1: The required minimum is 50.","Step 2: The number produced can be 50 or more.","Step 3: Therefore x ≥ 50."],"options":[],"conceptId":"math_linear_programming_translating_at_least_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating ''At Least'' into an Inequality"}', 0),
  (513, 148, 'A farmer must produce at least 100 bags of maize and beans combined. If x and y are the quantities, write the inequality.', 'text', 1, 'Add the two quantities.', '{"why":"The combined production must be 100 or greater.","sol":"Step 1: Total production = x + y.\nStep 2: The total must be at least 100.\nStep 3: Therefore x + y ≥ 100.","steps":["Step 1: Total production = x + y.","Step 2: The total must be at least 100.","Step 3: Therefore x + y ≥ 100."],"options":[],"conceptId":"math_linear_programming_translating_at_least_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating ''At Least'' into an Inequality"}', 1),
  (514, 148, 'A school requires at least 20 computers. If x represents the number of computers, write the inequality.', 'text', 1, 'The number cannot be below 20.', '{"why":"At least describes a lower limit.","sol":"Step 1: Minimum required = 20.\nStep 2: The number may be 20 or more.\nStep 3: Therefore x ≥ 20.","steps":["Step 1: Minimum required = 20.","Step 2: The number may be 20 or more.","Step 3: Therefore x ≥ 20."],"options":[],"conceptId":"math_linear_programming_translating_at_least_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating ''At Least'' into an Inequality"}', 2),
  (515, 149, 'A table uses 4 hours and a chair uses 2 hours. There are at most 40 hours available. Form the constraint.', 'text', 1, 'Total time used must not exceed 40.', '{"why":"The total machine time cannot exceed the available 40 hours.","sol":"Step 1: Tables use 4x hours.\nStep 2: Chairs use 2y hours.\nStep 3: Total = 4x + 2y.\nStep 4: At most 40 means ≤ 40.\nStep 5: Therefore 4x + 2y ≤ 40.","steps":["Step 1: Tables use 4x hours.","Step 2: Chairs use 2y hours.","Step 3: Total = 4x + 2y.","Step 4: At most 40 means ≤ 40.","Step 5: Therefore 4x + 2y ≤ 40."],"options":[],"conceptId":"math_linear_programming_translating_a_resource_limit_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating a Resource Limit into a Constraint"}', 0),
  (516, 149, 'A product A uses 3 kg and product B uses 5 kg. There are 90 kg available. Form the constraint.', 'text', 1, 'Multiply each material use by its quantity.', '{"why":"The total material used must not exceed the available material.","sol":"Step 1: A uses 3x kg.\nStep 2: B uses 5y kg.\nStep 3: Total = 3x + 5y.\nStep 4: The total cannot exceed 90 kg.\nStep 5: Therefore 3x + 5y ≤ 90.","steps":["Step 1: A uses 3x kg.","Step 2: B uses 5y kg.","Step 3: Total = 3x + 5y.","Step 4: The total cannot exceed 90 kg.","Step 5: Therefore 3x + 5y ≤ 90."],"options":[],"conceptId":"math_linear_programming_translating_a_resource_limit_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating a Resource Limit into a Constraint"}', 1),
  (517, 149, 'Product A costs KSh 100 and product B costs KSh 250. The budget is KSh 5,000. Form the constraint.', 'text', 1, 'Total cost must not exceed the budget.', '{"why":"Production spending cannot exceed the available budget.","sol":"Step 1: Cost of A = 100x.\nStep 2: Cost of B = 250y.\nStep 3: Total cost = 100x + 250y.\nStep 4: The budget is 5000.\nStep 5: Therefore 100x + 250y ≤ 5000.","steps":["Step 1: Cost of A = 100x.","Step 2: Cost of B = 250y.","Step 3: Total cost = 100x + 250y.","Step 4: The budget is 5000.","Step 5: Therefore 100x + 250y ≤ 5000."],"options":[],"conceptId":"math_linear_programming_translating_a_resource_limit_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating a Resource Limit into a Constraint"}', 2),
  (518, 150, 'A factory must produce at least 30 items. If x is the number produced, write the constraint.', 'text', 1, 'At least means ≥.', '{"why":"The production requirement gives a lower limit.","sol":"Step 1: The minimum is 30.\nStep 2: Production must be 30 or greater.\nStep 3: Therefore x ≥ 30.","steps":["Step 1: The minimum is 30.","Step 2: Production must be 30 or greater.","Step 3: Therefore x ≥ 30."],"options":[],"conceptId":"math_linear_programming_translating_a_production_requirement_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating a Production Requirement into a Constraint"}', 0),
  (519, 150, 'A factory can produce at most 80 items. If x and y are two products, write the constraint.', 'text', 1, 'At most means ≤.', '{"why":"The total production cannot exceed 80.","sol":"Step 1: Total production = x + y.\nStep 2: The maximum allowed is 80.\nStep 3: Therefore x + y ≤ 80.","steps":["Step 1: Total production = x + y.","Step 2: The maximum allowed is 80.","Step 3: Therefore x + y ≤ 80."],"options":[],"conceptId":"math_linear_programming_translating_a_production_requirement_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating a Production Requirement into a Constraint"}', 1),
  (520, 150, 'A company must produce at least 100 units of two products combined. Write the constraint.', 'text', 1, 'Add the quantities first.', '{"why":"The company must reach a minimum total production of 100.","sol":"Step 1: Let x and y be the quantities.\nStep 2: Combined production = x + y.\nStep 3: At least 100 means ≥ 100.\nStep 4: Therefore x + y ≥ 100.","steps":["Step 1: Let x and y be the quantities.","Step 2: Combined production = x + y.","Step 3: At least 100 means ≥ 100.","Step 4: Therefore x + y ≥ 100."],"options":[],"conceptId":"math_linear_programming_translating_a_production_requirement_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating a Production Requirement into a Constraint"}', 2),
  (521, 151, 'If x represents the number of tables produced, what condition must x satisfy?', 'text', 1, 'Can the number of tables be negative?', '{"why":"A quantity being counted cannot be negative.","sol":"Step 1: The number of tables cannot be negative.\nStep 2: Therefore x must be zero or positive.\nStep 3: So x ≥ 0.","steps":["Step 1: The number of tables cannot be negative.","Step 2: Therefore x must be zero or positive.","Step 3: So x ≥ 0."],"options":[],"conceptId":"math_linear_programming_translating_non_negativity_conditions","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating Non-Negativity Conditions"}', 0),
  (522, 151, 'If x represents shirts and y represents trousers, write the non-negativity constraints.', 'text', 1, 'Write one condition for each variable.', '{"why":"Both decision variables represent quantities.","sol":"Step 1: The number of shirts cannot be negative: x ≥ 0.\nStep 2: The number of trousers cannot be negative: y ≥ 0.","steps":["Step 1: The number of shirts cannot be negative: x ≥ 0.","Step 2: The number of trousers cannot be negative: y ≥ 0."],"options":[],"conceptId":"math_linear_programming_translating_non_negativity_conditions","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating Non-Negativity Conditions"}', 1),
  (523, 151, 'Why is x ≥ 0 normally included in a production model?', 'text', 1, 'Think about what x represents.', '{"why":"Non-negativity keeps the mathematical model consistent with the meaning of the variables.","sol":"Step 1: x represents a quantity such as products produced.\nStep 2: A negative quantity has no physical meaning here.\nStep 3: Therefore x must be zero or positive.","steps":["Step 1: x represents a quantity such as products produced.","Step 2: A negative quantity has no physical meaning here.","Step 3: Therefore x must be zero or positive."],"options":[],"conceptId":"math_linear_programming_translating_non_negativity_conditions","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating Non-Negativity Conditions"}', 2),
  (524, 152, 'A table gives KSh 600 profit and a chair gives KSh 400 profit. Let x be tables and y be chairs. Form the profit function.', 'text', 1, 'Multiply each unit profit by its quantity.', '{"why":"Each unit profit becomes the coefficient of its variable.","sol":"Step 1: Table profit = 600x.\nStep 2: Chair profit = 400y.\nStep 3: Total profit = 600x + 400y.","steps":["Step 1: Table profit = 600x.","Step 2: Chair profit = 400y.","Step 3: Total profit = 600x + 400y."],"options":[],"conceptId":"math_linear_programming_translating_profit_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating Profit Wording into an Objective Function"}', 0),
  (525, 152, 'A farmer earns KSh 1,200 per maize bag and KSh 900 per bean bag. Form the objective function for maximum profit.', 'text', 1, 'Let x be maize and y be beans.', '{"why":"The function represents total profit and the aim is to make it as large as possible.","sol":"Step 1: Maize profit = 1200x.\nStep 2: Bean profit = 900y.\nStep 3: Total profit = 1200x + 900y.\nStep 4: The word maximum means this function is maximized.","steps":["Step 1: Maize profit = 1200x.","Step 2: Bean profit = 900y.","Step 3: Total profit = 1200x + 900y.","Step 4: The word maximum means this function is maximized."],"options":[],"conceptId":"math_linear_programming_translating_profit_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating Profit Wording into an Objective Function"}', 1),
  (526, 152, 'A bakery earns KSh 30 per loaf and KSh 80 per cake. Write the objective for maximum profit.', 'text', 1, 'Use x for loaves and y for cakes.', '{"why":"The objective function adds the profit from both products.","sol":"Step 1: Loaf profit = 30x.\nStep 2: Cake profit = 80y.\nStep 3: Total profit = 30x + 80y.\nStep 4: Maximum profit means maximize P.","steps":["Step 1: Loaf profit = 30x.","Step 2: Cake profit = 80y.","Step 3: Total profit = 30x + 80y.","Step 4: Maximum profit means maximize P."],"options":[],"conceptId":"math_linear_programming_translating_profit_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating Profit Wording into an Objective Function"}', 2),
  (527, 153, 'Material A costs KSh 200 per unit and B costs KSh 400 per unit. Form the cost function.', 'text', 1, 'Multiply each cost per unit by its quantity.', '{"why":"The total cost is the sum of the two individual costs.","sol":"Step 1: A costs 200x.\nStep 2: B costs 400y.\nStep 3: Total cost = 200x + 400y.","steps":["Step 1: A costs 200x.","Step 2: B costs 400y.","Step 3: Total cost = 200x + 400y."],"options":[],"conceptId":"math_linear_programming_translating_cost_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating Cost Wording into an Objective Function"}', 0),
  (528, 153, 'A company wants the lowest cost. If C = 500x + 300y, what is the objective?', 'text', 1, 'Lowest means minimum.', '{"why":"Minimum cost means finding the smallest possible value of C.","sol":"Step 1: C represents total cost.\nStep 2: The company wants the lowest cost.\nStep 3: Therefore C must be minimized.","steps":["Step 1: C represents total cost.","Step 2: The company wants the lowest cost.","Step 3: Therefore C must be minimized."],"options":[],"conceptId":"math_linear_programming_translating_cost_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating Cost Wording into an Objective Function"}', 1),
  (529, 153, 'A notebook costs KSh 40 and a textbook KSh 200. If x notebooks and y textbooks are bought, write the objective for minimum cost.', 'text', 1, 'First form total cost.', '{"why":"The objective combines the cost of both types of items.","sol":"Step 1: Notebook cost = 40x.\nStep 2: Textbook cost = 200y.\nStep 3: Total cost = 40x + 200y.\nStep 4: Minimum cost means minimize C.","steps":["Step 1: Notebook cost = 40x.","Step 2: Textbook cost = 200y.","Step 3: Total cost = 40x + 200y.","Step 4: Minimum cost means minimize C."],"options":[],"conceptId":"math_linear_programming_translating_cost_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating Cost Wording into an Objective Function"}', 2),
  (530, 154, 'A factory makes tables and chairs. Let x be tables and y be chairs. Each table uses 2 hours and each chair 3 hours. There are at most 30 hours. Write the resource constraint.', 'text', 1, 'Total hours must not exceed 30.', '{"why":"The constraint represents the limited labour time.","sol":"Step 1: Tables use 2x hours.\nStep 2: Chairs use 3y hours.\nStep 3: Total = 2x + 3y.\nStep 4: At most 30 means ≤ 30.\nStep 5: Therefore 2x + 3y ≤ 30.","steps":["Step 1: Tables use 2x hours.","Step 2: Chairs use 3y hours.","Step 3: Total = 2x + 3y.","Step 4: At most 30 means ≤ 30.","Step 5: Therefore 2x + 3y ≤ 30."],"options":[],"conceptId":"math_linear_programming_building_a_complete_linear_programming_model","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Building a Complete Linear Programming Model"}', 0),
  (531, 154, 'A business earns KSh 400 per table and KSh 600 per chair. Write the profit objective.', 'text', 1, 'Multiply each profit by its quantity.', '{"why":"The objective represents total profit.","sol":"Step 1: Table profit = 400x.\nStep 2: Chair profit = 600y.\nStep 3: Total profit = 400x + 600y.\nStep 4: For maximum profit, maximize this expression.","steps":["Step 1: Table profit = 400x.","Step 2: Chair profit = 600y.","Step 3: Total profit = 400x + 600y.","Step 4: For maximum profit, maximize this expression."],"options":[],"conceptId":"math_linear_programming_building_a_complete_linear_programming_model","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Building a Complete Linear Programming Model"}', 1),
  (532, 154, 'Why are x ≥ 0 and y ≥ 0 included in the model?', 'text', 1, 'Think about what x and y represent.', '{"why":"Non-negativity connects the mathematical variables to their real meaning.","sol":"Step 1: x and y represent numbers of products.\nStep 2: Product quantities cannot be negative.\nStep 3: Therefore x and y must be non-negative.","steps":["Step 1: x and y represent numbers of products.","Step 2: Product quantities cannot be negative.","Step 3: Therefore x and y must be non-negative."],"options":[],"conceptId":"math_linear_programming_building_a_complete_linear_programming_model","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Building a Complete Linear Programming Model"}', 2),
  (533, 155, 'A farm has at most 50 acres. Maize uses 2 acres per bag and beans use 1 acre per bag. Form the land constraint.', 'text', 1, 'Total land used must not exceed 50.', '{"why":"The inequality represents the limited amount of land.","sol":"Step 1: Maize uses 2x acres.\nStep 2: Beans use y acres.\nStep 3: Total = 2x + y.\nStep 4: At most 50 means ≤ 50.\nStep 5: Therefore 2x + y ≤ 50.","steps":["Step 1: Maize uses 2x acres.","Step 2: Beans use y acres.","Step 3: Total = 2x + y.","Step 4: At most 50 means ≤ 50.","Step 5: Therefore 2x + y ≤ 50."],"options":[],"conceptId":"math_linear_programming_translating_a_full_word_problem_into_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating a Full Word Problem into Constraints"}', 0),
  (534, 155, 'A farmer must produce at least 20 bags of maize and beans combined. Form the production constraint.', 'text', 1, 'Add the two quantities.', '{"why":"The farmer must reach a minimum combined production.","sol":"Step 1: Total bags = x + y.\nStep 2: At least 20 means ≥ 20.\nStep 3: Therefore x + y ≥ 20.","steps":["Step 1: Total bags = x + y.","Step 2: At least 20 means ≥ 20.","Step 3: Therefore x + y ≥ 20."],"options":[],"conceptId":"math_linear_programming_translating_a_full_word_problem_into_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating a Full Word Problem into Constraints"}', 1),
  (535, 155, 'If x and y represent numbers of bags, what non-negativity conditions are required?', 'text', 1, 'Can a bag quantity be negative?', '{"why":"The variables represent quantities of physical products.","sol":"Step 1: The number of maize bags cannot be negative.\nStep 2: The number of bean bags cannot be negative.\nStep 3: Therefore x ≥ 0 and y ≥ 0.","steps":["Step 1: The number of maize bags cannot be negative.","Step 2: The number of bean bags cannot be negative.","Step 3: Therefore x ≥ 0 and y ≥ 0."],"options":[],"conceptId":"math_linear_programming_translating_a_full_word_problem_into_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating a Full Word Problem into Constraints"}', 2),
  (536, 156, 'Check whether (5,10) satisfies 2x + y ≤ 25.', 'text', 1, 'Substitute x = 5 and y = 10.', '{"why":"The point makes the inequality true.","sol":"Step 1: 2(5) + 10 ≤ 25.\nStep 2: 10 + 10 ≤ 25.\nStep 3: 20 ≤ 25.\nStep 4: The statement is true.","steps":["Step 1: 2(5) + 10 ≤ 25.","Step 2: 10 + 10 ≤ 25.","Step 3: 20 ≤ 25.","Step 4: The statement is true."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_proposed_production_plan_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Proposed Production Plan Is Feasible"}', 0),
  (537, 156, 'Check whether (10,8) satisfies x + y ≥ 20.', 'text', 1, 'Add the two coordinates.', '{"why":"The point fails the minimum-production constraint.","sol":"Step 1: 10 + 8 ≥ 20.\nStep 2: 18 ≥ 20.\nStep 3: This is false.","steps":["Step 1: 10 + 8 ≥ 20.","Step 2: 18 ≥ 20.","Step 3: This is false."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_proposed_production_plan_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Proposed Production Plan Is Feasible"}', 1),
  (538, 156, 'A point satisfies three constraints but fails one constraint. Is it feasible?', 'text', 1, 'Feasible means satisfying all restrictions.', '{"why":"One violated constraint is enough to make a point infeasible.","sol":"Step 1: A feasible point must satisfy every constraint.\nStep 2: The point fails one constraint.\nStep 3: Therefore it is not feasible.","steps":["Step 1: A feasible point must satisfy every constraint.","Step 2: The point fails one constraint.","Step 3: Therefore it is not feasible."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_proposed_production_plan_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Proposed Production Plan Is Feasible"}', 2),
  (539, 157, 'In the bakery problem, what does x represent?', 'text', 1, 'Look at the variable definition.', '{"why":"Every later equation depends on this variable meaning.","sol":"Step 1: x was defined as the number of loaves.\nStep 2: Therefore x represents the number of loaves.","steps":["Step 1: x was defined as the number of loaves.","Step 2: Therefore x represents the number of loaves."],"options":[],"conceptId":"math_linear_programming_building_a_linear_programming_model_from_a_complete_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Building a Linear Programming Model from a Complete Problem"}', 0),
  (540, 157, 'In the bakery problem, what inequality represents the labour limit?', 'text', 1, 'Bread uses 2 hours and cakes use 3 hours.', '{"why":"The inequality represents the limited labour resource.","sol":"Step 1: Bread uses 2x hours.\nStep 2: Cakes use 3y hours.\nStep 3: Total = 2x + 3y.\nStep 4: At most 60 means ≤ 60.\nStep 5: Therefore 2x + 3y ≤ 60.","steps":["Step 1: Bread uses 2x hours.","Step 2: Cakes use 3y hours.","Step 3: Total = 2x + 3y.","Step 4: At most 60 means ≤ 60.","Step 5: Therefore 2x + 3y ≤ 60."],"options":[],"conceptId":"math_linear_programming_building_a_linear_programming_model_from_a_complete_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Building a Linear Programming Model from a Complete Problem"}', 1),
  (541, 157, 'What is the complete objective function for the bakery?', 'text', 1, 'Use the profit per loaf and profit per cake.', '{"why":"The objective combines the profit contributions from both products.","sol":"Step 1: Bread profit = 40x.\nStep 2: Cake profit = 100y.\nStep 3: Total profit = 40x + 100y.\nStep 4: The aim is maximum profit.","steps":["Step 1: Bread profit = 40x.","Step 2: Cake profit = 100y.","Step 3: Total profit = 40x + 100y.","Step 4: The aim is maximum profit."],"options":[],"conceptId":"math_linear_programming_building_a_linear_programming_model_from_a_complete_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Building a Linear Programming Model from a Complete Problem"}', 2),
  (542, 158, 'In the fraction 7/12, what is the numerator?', 'text', 1, 'Look at the top number.', '{"why":"The numerator is the number written above the fraction bar.","sol":"Step 1: Identify the top number.\nStep 2: The top number is 7.","steps":["Step 1: Identify the top number.","Step 2: The top number is 7."],"options":[],"conceptId":"math_fractions_understanding_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Understanding Fractions"}', 0),
  (543, 158, 'In the fraction 7/12, what is the denominator?', 'text', 1, 'Look at the bottom number.', '{"why":"The denominator is the number written below the fraction bar.","sol":"Step 1: Identify the bottom number.\nStep 2: The bottom number is 12.","steps":["Step 1: Identify the bottom number.","Step 2: The bottom number is 12."],"options":[],"conceptId":"math_fractions_understanding_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Understanding Fractions"}', 1),
  (544, 158, 'Is 5/8 a proper or improper fraction?', 'text', 1, 'Compare numerator and denominator.', '{"why":"A proper fraction has a numerator smaller than its denominator.","sol":"Step 1: Numerator = 5.\nStep 2: Denominator = 8.\nStep 3: 5 is smaller than 8.","steps":["Step 1: Numerator = 5.","Step 2: Denominator = 8.","Step 3: 5 is smaller than 8."],"options":[],"conceptId":"math_fractions_understanding_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Understanding Fractions"}', 2),
  (545, 158, 'Convert 2 3/4 to an improper fraction.', 'text', 1, 'Multiply the whole number by the denominator first.', '{"why":"A mixed number is converted by multiplying the whole number by the denominator and adding the numerator.","sol":"Step 1: 2 × 4 = 8.\nStep 2: 8 + 3 = 11.\nStep 3: Keep denominator 4.\nStep 4: The result is 11/4.","steps":["Step 1: 2 × 4 = 8.","Step 2: 8 + 3 = 11.","Step 3: Keep denominator 4.","Step 4: The result is 11/4."],"options":[],"conceptId":"math_fractions_understanding_fractions","skillId":"math_fractions","subskillId":"math_fractions_q4","subject":"math","chapter":"fractions","topic":"Understanding Fractions"}', 3),
  (546, 159, 'Find an equivalent fraction to 3/4 with denominator 20.', 'text', 1, '4 must become 20.', '{"why":"Both numerator and denominator must be multiplied by the same factor.","sol":"Step 1: 4 × 5 = 20.\nStep 2: Multiply the numerator by 5.\nStep 3: 3 × 5 = 15.","steps":["Step 1: 4 × 5 = 20.","Step 2: Multiply the numerator by 5.","Step 3: 3 × 5 = 15."],"options":[],"conceptId":"math_fractions_equivalent_fractions_and_simplifying","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Equivalent Fractions and Simplifying"}', 0),
  (547, 159, 'Simplify 12/18.', 'text', 1, 'Find a common factor of 12 and 18.', '{"why":"Dividing numerator and denominator by their greatest common factor gives simplest form.","sol":"Step 1: The greatest common factor is 6.\nStep 2: 12 ÷ 6 = 2.\nStep 3: 18 ÷ 6 = 3.","steps":["Step 1: The greatest common factor is 6.","Step 2: 12 ÷ 6 = 2.","Step 3: 18 ÷ 6 = 3."],"options":[],"conceptId":"math_fractions_equivalent_fractions_and_simplifying","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Equivalent Fractions and Simplifying"}', 1),
  (548, 159, 'Are 2/3 and 8/12 equivalent?', 'text', 1, 'Simplify 8/12.', '{"why":"Equivalent fractions represent the same value.","sol":"Step 1: Divide 8 and 12 by 4.\nStep 2: 8/12 = 2/3.\nStep 3: Therefore the fractions have the same value.","steps":["Step 1: Divide 8 and 12 by 4.","Step 2: 8/12 = 2/3.","Step 3: Therefore the fractions have the same value."],"options":[],"conceptId":"math_fractions_equivalent_fractions_and_simplifying","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Equivalent Fractions and Simplifying"}', 2),
  (549, 160, 'Which is greater: 5/9 or 2/9?', 'text', 1, 'The denominators are already equal.', '{"why":"With equal positive denominators, the larger numerator gives the larger fraction.","sol":"Step 1: Both denominators are 9.\nStep 2: Compare numerators 5 and 2.\nStep 3: 5 > 2.","steps":["Step 1: Both denominators are 9.","Step 2: Compare numerators 5 and 2.","Step 3: 5 > 2."],"options":[],"conceptId":"math_fractions_comparing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Comparing Fractions"}', 0),
  (550, 160, 'Which is greater: 1/3 or 1/7?', 'text', 1, 'The numerators are equal.', '{"why":"For positive fractions with the same numerator, the smaller denominator gives the larger value.","sol":"Step 1: Both numerators are 1.\nStep 2: Compare denominators.\nStep 3: A third is larger than a seventh.","steps":["Step 1: Both numerators are 1.","Step 2: Compare denominators.","Step 3: A third is larger than a seventh."],"options":[],"conceptId":"math_fractions_comparing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Comparing Fractions"}', 1),
  (551, 160, 'Which is greater: 3/4 or 5/8?', 'text', 1, 'Use a common denominator.', '{"why":"Converting to a common denominator makes comparison direct.","sol":"Step 1: Convert 3/4 to eighths.\nStep 2: 3/4 = 6/8.\nStep 3: Compare 6/8 and 5/8.\nStep 4: 6/8 is greater.","steps":["Step 1: Convert 3/4 to eighths.","Step 2: 3/4 = 6/8.","Step 3: Compare 6/8 and 5/8.","Step 4: 6/8 is greater."],"options":[],"conceptId":"math_fractions_comparing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Comparing Fractions"}', 2),
  (552, 160, 'Which is greater: 4/7 or 5/9?', 'text', 1, 'Cross-multiply.', '{"why":"Cross-products can be compared when determining which of two positive fractions is larger.","sol":"Step 1: 4 × 9 = 36.\nStep 2: 5 × 7 = 35.\nStep 3: 36 > 35.","steps":["Step 1: 4 × 9 = 36.","Step 2: 5 × 7 = 35.","Step 3: 36 > 35."],"options":[],"conceptId":"math_fractions_comparing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q4","subject":"math","chapter":"fractions","topic":"Comparing Fractions"}', 3),
  (553, 161, 'Calculate 2/5 + 1/5.', 'text', 1, 'The denominators are already equal.', '{"why":"When denominators are equal, add only the numerators.","sol":"Step 1: Add numerators: 2 + 1 = 3.\nStep 2: Keep denominator 5.\nStep 3: Result = 3/5.","steps":["Step 1: Add numerators: 2 + 1 = 3.","Step 2: Keep denominator 5.","Step 3: Result = 3/5."],"options":[],"conceptId":"math_fractions_adding_and_subtracting_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Adding and Subtracting Fractions"}', 0),
  (554, 161, 'Calculate 1/2 + 1/4.', 'text', 1, 'Change 1/2 into quarters.', '{"why":"A common denominator is required before adding fractions.","sol":"Step 1: LCM of 2 and 4 = 4.\nStep 2: 1/2 = 2/4.\nStep 3: 2/4 + 1/4 = 3/4.","steps":["Step 1: LCM of 2 and 4 = 4.","Step 2: 1/2 = 2/4.","Step 3: 2/4 + 1/4 = 3/4."],"options":[],"conceptId":"math_fractions_adding_and_subtracting_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Adding and Subtracting Fractions"}', 1),
  (555, 161, 'Calculate 5/6 - 1/3.', 'text', 1, 'Convert 1/3 to sixths.', '{"why":"The fractions are first expressed with the same denominator.","sol":"Step 1: 1/3 = 2/6.\nStep 2: 5/6 - 2/6 = 3/6.\nStep 3: Simplify 3/6 to 1/2.","steps":["Step 1: 1/3 = 2/6.","Step 2: 5/6 - 2/6 = 3/6.","Step 3: Simplify 3/6 to 1/2."],"options":[],"conceptId":"math_fractions_adding_and_subtracting_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Adding and Subtracting Fractions"}', 2),
  (556, 161, 'Calculate 2/3 + 3/4.', 'text', 1, 'Use 12 as the common denominator.', '{"why":"The LCM of 3 and 4 is 12.","sol":"Step 1: 2/3 = 8/12.\nStep 2: 3/4 = 9/12.\nStep 3: 8/12 + 9/12 = 17/12.","steps":["Step 1: 2/3 = 8/12.","Step 2: 3/4 = 9/12.","Step 3: 8/12 + 9/12 = 17/12."],"options":[],"conceptId":"math_fractions_adding_and_subtracting_fractions","skillId":"math_fractions","subskillId":"math_fractions_q4","subject":"math","chapter":"fractions","topic":"Adding and Subtracting Fractions"}', 3),
  (557, 162, 'Calculate 3/5 × 2/7.', 'text', 1, 'Multiply straight across.', '{"why":"Fractions are multiplied by multiplying corresponding numerators and denominators.","sol":"Step 1: 3 × 2 = 6.\nStep 2: 5 × 7 = 35.\nStep 3: Write the result as 6/35.","steps":["Step 1: 3 × 2 = 6.","Step 2: 5 × 7 = 35.","Step 3: Write the result as 6/35."],"options":[],"conceptId":"math_fractions_multiplying_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Multiplying Fractions"}', 0),
  (558, 162, 'Calculate 2/3 × 3/4.', 'text', 1, 'Multiply and simplify.', '{"why":"The resulting fraction must be simplified.","sol":"Step 1: 2 × 3 = 6.\nStep 2: 3 × 4 = 12.\nStep 3: 6/12 = 1/2.","steps":["Step 1: 2 × 3 = 6.","Step 2: 3 × 4 = 12.","Step 3: 6/12 = 1/2."],"options":[],"conceptId":"math_fractions_multiplying_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Multiplying Fractions"}', 1),
  (559, 162, 'Calculate 4/9 × 3/8.', 'text', 1, 'Cancel common factors first.', '{"why":"Common factors can be cancelled before multiplication.","sol":"Step 1: Cancel 4 with 8 to get 1 and 2.\nStep 2: Cancel 3 with 9 to get 1 and 3.\nStep 3: Multiply 1/3 × 1/2.\nStep 4: Result = 1/6.","steps":["Step 1: Cancel 4 with 8 to get 1 and 2.","Step 2: Cancel 3 with 9 to get 1 and 3.","Step 3: Multiply 1/3 × 1/2.","Step 4: Result = 1/6."],"options":[],"conceptId":"math_fractions_multiplying_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Multiplying Fractions"}', 2),
  (560, 163, 'Calculate 3/4 ÷ 1/2.', 'text', 1, 'Flip the second fraction.', '{"why":"Dividing by a fraction is equivalent to multiplying by its reciprocal.","sol":"Step 1: Keep 3/4.\nStep 2: Change ÷ to ×.\nStep 3: Flip 1/2 to 2/1.\nStep 4: 3/4 × 2/1 = 6/4 = 3/2.","steps":["Step 1: Keep 3/4.","Step 2: Change ÷ to ×.","Step 3: Flip 1/2 to 2/1.","Step 4: 3/4 × 2/1 = 6/4 = 3/2."],"options":[],"conceptId":"math_fractions_dividing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Dividing Fractions"}', 0),
  (561, 163, 'Calculate 5/6 ÷ 1/3.', 'text', 1, 'The reciprocal of 1/3 is 3.', '{"why":"The second fraction is replaced by its reciprocal.","sol":"Step 1: 5/6 ÷ 1/3 = 5/6 × 3/1.\nStep 2: Multiply to get 15/6.\nStep 3: Simplify to 5/2.","steps":["Step 1: 5/6 ÷ 1/3 = 5/6 × 3/1.","Step 2: Multiply to get 15/6.","Step 3: Simplify to 5/2."],"options":[],"conceptId":"math_fractions_dividing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Dividing Fractions"}', 1),
  (562, 163, 'Calculate 2/5 ÷ 2/5.', 'text', 1, 'A non-zero number divided by itself equals 1.', '{"why":"Any non-zero number divided by itself equals 1.","sol":"Step 1: Flip the second fraction: 5/2.\nStep 2: 2/5 × 5/2.\nStep 3: Cancel common factors.\nStep 4: Result = 1.","steps":["Step 1: Flip the second fraction: 5/2.","Step 2: 2/5 × 5/2.","Step 3: Cancel common factors.","Step 4: Result = 1."],"options":[],"conceptId":"math_fractions_dividing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Dividing Fractions"}', 2),
  (563, 164, 'Convert 0.6 to a fraction in simplest form.', 'text', 1, 'Write it over 10.', '{"why":"One decimal place represents tenths.","sol":"Step 1: 0.6 = 6/10.\nStep 2: Divide numerator and denominator by 2.\nStep 3: 6/10 = 3/5.","steps":["Step 1: 0.6 = 6/10.","Step 2: Divide numerator and denominator by 2.","Step 3: 6/10 = 3/5."],"options":[],"conceptId":"math_fractions_decimals_and_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Decimals and Fractions"}', 0),
  (564, 164, 'Convert 0.75 to a fraction in simplest form.', 'text', 1, 'Write it over 100.', '{"why":"Two decimal places represent hundredths.","sol":"Step 1: 0.75 = 75/100.\nStep 2: Divide numerator and denominator by 25.\nStep 3: 75/100 = 3/4.","steps":["Step 1: 0.75 = 75/100.","Step 2: Divide numerator and denominator by 25.","Step 3: 75/100 = 3/4."],"options":[],"conceptId":"math_fractions_decimals_and_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Decimals and Fractions"}', 1),
  (565, 164, 'Convert 5/8 to a decimal.', 'text', 1, 'Divide 5 by 8.', '{"why":"A fraction can be converted to a decimal by dividing numerator by denominator.","sol":"Step 1: 5 ÷ 8.\nStep 2: 5/8 = 0.625.","steps":["Step 1: 5 ÷ 8.","Step 2: 5/8 = 0.625."],"options":[],"conceptId":"math_fractions_decimals_and_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Decimals and Fractions"}', 2),
  (566, 164, 'Convert 7/10 to a decimal.', 'text', 1, 'The denominator is already 10.', '{"why":"A denominator of 10 corresponds directly to one decimal place.","sol":"Step 1: 7/10 represents seven tenths.\nStep 2: Seven tenths is written as 0.7.","steps":["Step 1: 7/10 represents seven tenths.","Step 2: Seven tenths is written as 0.7."],"options":[],"conceptId":"math_fractions_decimals_and_fractions","skillId":"math_fractions","subskillId":"math_fractions_q4","subject":"math","chapter":"fractions","topic":"Decimals and Fractions"}', 3),
  (567, 165, 'Convert 0.666... to a fraction.', 'text', 1, 'Let x = 0.666... and multiply by 10.', '{"why":"Multiplication by 10 shifts a single repeating digit, allowing subtraction to eliminate the repetition.","sol":"Step 1: x = 0.666...\nStep 2: 10x = 6.666...\nStep 3: 10x − x = 6.\nStep 4: 9x = 6.\nStep 5: x = 6/9 = 2/3.","steps":["Step 1: x = 0.666...","Step 2: 10x = 6.666...","Step 3: 10x − x = 6.","Step 4: 9x = 6.","Step 5: x = 6/9 = 2/3."],"options":[],"conceptId":"math_fractions_recurring_decimals","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Recurring Decimals"}', 0),
  (568, 165, 'Convert 0.444... to a fraction.', 'text', 1, 'Use x = 0.444... and multiply by 10.', '{"why":"A single repeating digit is eliminated by subtracting x from 10x.","sol":"Step 1: x = 0.444...\nStep 2: 10x = 4.444...\nStep 3: 10x − x = 4.\nStep 4: 9x = 4.\nStep 5: x = 4/9.","steps":["Step 1: x = 0.444...","Step 2: 10x = 4.444...","Step 3: 10x − x = 4.","Step 4: 9x = 4.","Step 5: x = 4/9."],"options":[],"conceptId":"math_fractions_recurring_decimals","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Recurring Decimals"}', 1),
  (569, 165, 'Convert 0.121212... to a fraction.', 'text', 1, 'Two digits repeat, so use 100.', '{"why":"A two-digit repeating block requires multiplication by 100 to align the repeating parts.","sol":"Step 1: x = 0.121212...\nStep 2: 100x = 12.121212...\nStep 3: 100x − x = 12.\nStep 4: 99x = 12.\nStep 5: x = 12/99 = 4/33.","steps":["Step 1: x = 0.121212...","Step 2: 100x = 12.121212...","Step 3: 100x − x = 12.","Step 4: 99x = 12.","Step 5: x = 12/99 = 4/33."],"options":[],"conceptId":"math_fractions_recurring_decimals","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Recurring Decimals"}', 2),
  (570, 165, 'Convert 0.090909... to a fraction.', 'text', 1, 'The repeating block is 09.', '{"why":"The repeating block has two digits, so multiplying by 100 aligns the repeating portions.","sol":"Step 1: x = 0.090909...\nStep 2: 100x = 9.090909...\nStep 3: 100x − x = 9.\nStep 4: 99x = 9.\nStep 5: x = 9/99 = 1/11.","steps":["Step 1: x = 0.090909...","Step 2: 100x = 9.090909...","Step 3: 100x − x = 9.","Step 4: 99x = 9.","Step 5: x = 9/99 = 1/11."],"options":[],"conceptId":"math_fractions_recurring_decimals","skillId":"math_fractions","subskillId":"math_fractions_q4","subject":"math","chapter":"fractions","topic":"Recurring Decimals"}', 3),
  (571, 166, 'Find the area of a rectangle with length 8 cm and width 3 cm.', 'text', 1, 'Use A = l × w.', '{"why":"The area of a rectangle is found by multiplying its length by its width.","sol":"Step 1: Write the formula: A = l × w.\nStep 2: Substitute l = 8 and w = 3.\nStep 3: A = 8 × 3.\nStep 4: A = 24.","steps":["Step 1: Write the formula: A = l × w.","Step 2: Substitute l = 8 and w = 3.","Step 3: A = 8 × 3.","Step 4: A = 24."],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Area of Rectangles and Squares"}', 0),
  (572, 166, 'Find the area of a square with side 7 cm.', 'text', 1, 'A = side².', '{"why":"All sides of a square are equal, so its area is side × side.","sol":"Step 1: A = side × side.\nStep 2: A = 7 × 7.\nStep 3: A = 49.","steps":["Step 1: A = side × side.","Step 2: A = 7 × 7.","Step 3: A = 49."],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Area of Rectangles and Squares"}', 1),
  (573, 166, 'A rectangle has area 45 cm² and width 5 cm. Find its length.', 'text', 1, 'Length = area ÷ width.', '{"why":"The missing length is found by rearranging A = l × w.","sol":"Step 1: A = l × w.\nStep 2: 45 = l × 5.\nStep 3: Divide both sides by 5.\nStep 4: l = 9.","steps":["Step 1: A = l × w.","Step 2: 45 = l × 5.","Step 3: Divide both sides by 5.","Step 4: l = 9."],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Area of Rectangles and Squares"}', 2),
  (574, 166, 'A rectangle has length 9 cm and width 5 cm. What is its area?', 'text', 1, 'Multiply 9 by 5.', '{"why":"Area measures the two-dimensional space inside the rectangle.","sol":"Step 1: A = 9 × 5.\nStep 2: A = 45.","steps":["Step 1: A = 9 × 5.","Step 2: A = 45."],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q4","subject":"math","chapter":"measurement","topic":"Area of Rectangles and Squares"}', 3),
  (575, 166, 'Which formula gives the area of a rectangle?', 'text', 1, 'Think about its two dimensions.', '{"why":"Rectangle area is length multiplied by width.","sol":"Step 1: A rectangle has length and width.\nStep 2: Multiply the two dimensions.\nStep 3: A = l × w.","steps":["Step 1: A rectangle has length and width.","Step 2: Multiply the two dimensions.","Step 3: A = l × w."],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q5","subject":"math","chapter":"measurement","topic":"Area of Rectangles and Squares"}', 4),
  (576, 167, 'Find the area of a triangle with base 12 cm and height 4 cm.', 'text', 1, 'Use A = 1/2 × b × h.', '{"why":"Triangle area is half the product of its base and perpendicular height.","sol":"Step 1: A = 1/2 × 12 × 4.\nStep 2: 12 ÷ 2 = 6.\nStep 3: 6 × 4 = 24.","steps":["Step 1: A = 1/2 × 12 × 4.","Step 2: 12 ÷ 2 = 6.","Step 3: 6 × 4 = 24."],"options":[],"conceptId":"math_measurement_area_of_triangles","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Area of Triangles"}', 0),
  (577, 167, 'A triangle has base 14 cm and height 6 cm. Find its area.', 'text', 1, 'Multiply the base and height, then divide by 2.', '{"why":"The factor 1/2 is required because a triangle occupies half the corresponding base-height rectangle.","sol":"Step 1: A = 1/2 × 14 × 6.\nStep 2: 14 × 6 = 84.\nStep 3: 84 ÷ 2 = 42.","steps":["Step 1: A = 1/2 × 14 × 6.","Step 2: 14 × 6 = 84.","Step 3: 84 ÷ 2 = 42."],"options":[],"conceptId":"math_measurement_area_of_triangles","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Area of Triangles"}', 1),
  (578, 167, 'A triangle has area 40 cm² and base 10 cm. Find its perpendicular height.', 'text', 1, 'h = 2A ÷ b.', '{"why":"Rearranging A = 1/2bh gives h = 2A ÷ b.","sol":"Step 1: h = 2A ÷ b.\nStep 2: h = (2 × 40) ÷ 10.\nStep 3: h = 80 ÷ 10.\nStep 4: h = 8.","steps":["Step 1: h = 2A ÷ b.","Step 2: h = (2 × 40) ÷ 10.","Step 3: h = 80 ÷ 10.","Step 4: h = 8."],"options":[],"conceptId":"math_measurement_area_of_triangles","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Area of Triangles"}', 2),
  (579, 167, 'A triangle has area 24 cm² and height 6 cm. Find its base.', 'text', 1, 'b = 2A ÷ h.', '{"why":"The formula can be rearranged to find an unknown base.","sol":"Step 1: b = 2A ÷ h.\nStep 2: b = (2 × 24) ÷ 6.\nStep 3: b = 48 ÷ 6.\nStep 4: b = 8.","steps":["Step 1: b = 2A ÷ h.","Step 2: b = (2 × 24) ÷ 6.","Step 3: b = 48 ÷ 6.","Step 4: b = 8."],"options":[],"conceptId":"math_measurement_area_of_triangles","skillId":"math_measurement","subskillId":"math_measurement_q4","subject":"math","chapter":"measurement","topic":"Area of Triangles"}', 3),
  (580, 168, 'Find the volume of a cuboid measuring 8 cm × 3 cm × 2 cm.', 'text', 1, 'Multiply all three dimensions.', '{"why":"Cuboid volume is the product of its three dimensions.","sol":"Step 1: V = l × w × h.\nStep 2: V = 8 × 3 × 2.\nStep 3: V = 48.","steps":["Step 1: V = l × w × h.","Step 2: V = 8 × 3 × 2.","Step 3: V = 48."],"options":[],"conceptId":"math_measurement_volume_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Volume of Cubes and Cuboids"}', 0),
  (581, 168, 'Find the volume of a cube with side 5 cm.', 'text', 1, 'V = s³.', '{"why":"A cube has three equal dimensions, so its volume is side cubed.","sol":"Step 1: V = 5 × 5 × 5.\nStep 2: 5 × 5 = 25.\nStep 3: 25 × 5 = 125.","steps":["Step 1: V = 5 × 5 × 5.","Step 2: 5 × 5 = 25.","Step 3: 25 × 5 = 125."],"options":[],"conceptId":"math_measurement_volume_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Volume of Cubes and Cuboids"}', 1),
  (582, 168, 'A cuboid has volume 60 cm³, length 5 cm and width 3 cm. Find its height.', 'text', 1, 'h = V ÷ (lw).', '{"why":"Rearranging V = lwh gives h = V ÷ (lw).","sol":"Step 1: h = V ÷ (lw).\nStep 2: h = 60 ÷ (5 × 3).\nStep 3: h = 60 ÷ 15.\nStep 4: h = 4.","steps":["Step 1: h = V ÷ (lw).","Step 2: h = 60 ÷ (5 × 3).","Step 3: h = 60 ÷ 15.","Step 4: h = 4."],"options":[],"conceptId":"math_measurement_volume_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Volume of Cubes and Cuboids"}', 2),
  (583, 168, 'Which formula gives the volume of a cuboid?', 'text', 1, 'A cuboid has three dimensions.', '{"why":"Volume of a cuboid is the product of its length, width and height.","sol":"Step 1: Identify the three dimensions.\nStep 2: Multiply length, width and height.","steps":["Step 1: Identify the three dimensions.","Step 2: Multiply length, width and height."],"options":[],"conceptId":"math_measurement_volume_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q4","subject":"math","chapter":"measurement","topic":"Volume of Cubes and Cuboids"}', 3),
  (584, 169, 'Find the surface area of a cube with side 5 cm.', 'text', 1, 'Use SA = 6s².', '{"why":"A cube has six equal square faces.","sol":"Step 1: SA = 6 × 5².\nStep 2: 5² = 25.\nStep 3: 6 × 25 = 150.","steps":["Step 1: SA = 6 × 5².","Step 2: 5² = 25.","Step 3: 6 × 25 = 150."],"options":[],"conceptId":"math_measurement_surface_area_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Surface Area of Cubes and Cuboids"}', 0),
  (585, 169, 'Find the surface area of a cube with side 3 cm.', 'text', 1, 'Square the side, then multiply by 6.', '{"why":"The six faces of the cube each have area 9 cm².","sol":"Step 1: 3² = 9.\nStep 2: 6 × 9 = 54.","steps":["Step 1: 3² = 9.","Step 2: 6 × 9 = 54."],"options":[],"conceptId":"math_measurement_surface_area_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Surface Area of Cubes and Cuboids"}', 1),
  (586, 169, 'Find the surface area of a cuboid with length 4 cm, width 3 cm and height 2 cm.', 'text', 1, 'Use SA = 2(lw + lh + wh).', '{"why":"The three different face areas each occur twice.","sol":"Step 1: lw = 4 × 3 = 12.\nStep 2: lh = 4 × 2 = 8.\nStep 3: wh = 3 × 2 = 6.\nStep 4: Add: 12 + 8 + 6 = 26.\nStep 5: Multiply by 2: 2 × 26 = 52.","steps":["Step 1: lw = 4 × 3 = 12.","Step 2: lh = 4 × 2 = 8.","Step 3: wh = 3 × 2 = 6.","Step 4: Add: 12 + 8 + 6 = 26.","Step 5: Multiply by 2: 2 × 26 = 52."],"options":[],"conceptId":"math_measurement_surface_area_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Surface Area of Cubes and Cuboids"}', 2),
  (587, 169, 'Which formula gives the surface area of a cuboid?', 'text', 1, 'There are three pairs of equal faces.', '{"why":"A cuboid has two faces of each of its three different dimensions.","sol":"Step 1: Identify the three face areas: lw, lh and wh.\nStep 2: Add them.\nStep 3: Multiply by 2.","steps":["Step 1: Identify the three face areas: lw, lh and wh.","Step 2: Add them.","Step 3: Multiply by 2."],"options":[],"conceptId":"math_measurement_surface_area_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q4","subject":"math","chapter":"measurement","topic":"Surface Area of Cubes and Cuboids"}', 3),
  (588, 170, 'What unit should be used for the area of a rectangle measured in centimetres?', 'text', 1, 'Area uses squared units.', '{"why":"Area measures two dimensions, so its units are squared.","sol":"Step 1: The quantity is area.\nStep 2: Area uses square units.\nStep 3: Therefore the unit is cm².","steps":["Step 1: The quantity is area.","Step 2: Area uses square units.","Step 3: Therefore the unit is cm²."],"options":[],"conceptId":"math_measurement_measurement_units_and_dimensions","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Measurement Units and Dimensions"}', 0),
  (589, 170, 'What unit should be used for the volume of a cuboid measured in centimetres?', 'text', 1, 'Volume uses three dimensions.', '{"why":"Volume measures three dimensions, so its units are cubed.","sol":"Step 1: The quantity is volume.\nStep 2: Volume uses cubic units.\nStep 3: Therefore the unit is cm³.","steps":["Step 1: The quantity is volume.","Step 2: Volume uses cubic units.","Step 3: Therefore the unit is cm³."],"options":[],"conceptId":"math_measurement_measurement_units_and_dimensions","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Measurement Units and Dimensions"}', 1),
  (590, 170, 'Convert 1 m² to cm².', 'text', 1, '1 m = 100 cm, then square the conversion factor.', '{"why":"Area conversion factors must be squared.","sol":"Step 1: 1 m = 100 cm.\nStep 2: Square both sides.\nStep 3: 1 m² = 100² cm².\nStep 4: 100² = 10,000.","steps":["Step 1: 1 m = 100 cm.","Step 2: Square both sides.","Step 3: 1 m² = 100² cm².","Step 4: 100² = 10,000."],"options":[],"conceptId":"math_measurement_measurement_units_and_dimensions","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Measurement Units and Dimensions"}', 2),
  (591, 170, 'Convert 1 m³ to cm³.', 'text', 1, '1 m = 100 cm, then cube the conversion factor.', '{"why":"Volume conversion factors must be cubed.","sol":"Step 1: 1 m = 100 cm.\nStep 2: Cube both sides.\nStep 3: 1 m³ = 100³ cm³.\nStep 4: 100³ = 1,000,000.","steps":["Step 1: 1 m = 100 cm.","Step 2: Cube both sides.","Step 3: 1 m³ = 100³ cm³.","Step 4: 100³ = 1,000,000."],"options":[],"conceptId":"math_measurement_measurement_units_and_dimensions","skillId":"math_measurement","subskillId":"math_measurement_q4","subject":"math","chapter":"measurement","topic":"Measurement Units and Dimensions"}', 3),
  (592, 170, 'Which is larger: 1 m² or 100 cm²?', 'text', 1, 'Convert 1 m² into cm².', '{"why":"Squared units require the length conversion factor to be squared.","sol":"Step 1: 1 m² = 10,000 cm².\nStep 2: Compare 10,000 cm² and 100 cm².\nStep 3: 10,000 cm² is larger.","steps":["Step 1: 1 m² = 10,000 cm².","Step 2: Compare 10,000 cm² and 100 cm².","Step 3: 10,000 cm² is larger."],"options":[],"conceptId":"math_measurement_measurement_units_and_dimensions","skillId":"math_measurement","subskillId":"math_measurement_q5","subject":"math","chapter":"measurement","topic":"Measurement Units and Dimensions"}', 4),
  (593, 171, 'Find the distance between points (2,3) and (6,7)', 'text', 1, 'distance formula', '{"why":"Distance between two points is found using Euclidean formula","sol":"Step 1: Use d = √((x₂ − x₁)² + (y₂ − y₁)²)\nStep 2: Substitute values (6−2) and (7−3)\nStep 3: Compute 4² and 4²\nStep 4: Add results\nStep 5: Take square root","steps":["Step 1: Use d = √((x₂ − x₁)² + (y₂ − y₁)²)","Step 2: Substitute values (6−2) and (7−3)","Step 3: Compute 4² and 4²","Step 4: Add results","Step 5: Take square root"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 0),
  (594, 171, 'Find midpoint of (2,4) and (8,10)', 'text', 1, 'midpoint formula', '{"why":"Midpoint is average of coordinates","sol":"Step 1: Use M = ((x₁ + x₂)/2, (y₁ + y₂)/2)\nStep 2: Substitute values\nStep 3: Compute x-coordinate\nStep 4: Compute y-coordinate\nStep 5: Form midpoint","steps":["Step 1: Use M = ((x₁ + x₂)/2, (y₁ + y₂)/2)","Step 2: Substitute values","Step 3: Compute x-coordinate","Step 4: Compute y-coordinate","Step 5: Form midpoint"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 1),
  (595, 171, 'Determine the coordinates after moving from (3,5) by +4 in x and −2 in y', 'text', 1, 'translation', '{"why":"Translation shifts points by vector addition","sol":"Step 1: Start at (3,5)\nStep 2: Add 4 to x-coordinate\nStep 3: Subtract 2 from y-coordinate\nStep 4: Write new coordinates","steps":["Step 1: Start at (3,5)","Step 2: Add 4 to x-coordinate","Step 3: Subtract 2 from y-coordinate","Step 4: Write new coordinates"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 2),
  (596, 171, 'Find slope between points (1,2) and (5,10)', 'text', 1, 'rise over run', '{"why":"Slope measures rate of change between two points","sol":"Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)\nStep 2: Substitute values\nStep 3: Compute numerator 8\nStep 4: Compute denominator 4\nStep 5: Simplify fraction","steps":["Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)","Step 2: Substitute values","Step 3: Compute numerator 8","Step 4: Compute denominator 4","Step 5: Simplify fraction"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q4","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 3),
  (597, 171, 'Find equation of line passing through (0,0) with slope 3', 'text', 1, 'y = mx + c', '{"why":"Line equation is determined by slope and intercept","sol":"Step 1: Use y = mx + c\nStep 2: Substitute m = 3\nStep 3: Use point (0,0) to find c\nStep 4: Solve for c\nStep 5: Write final equation","steps":["Step 1: Use y = mx + c","Step 2: Substitute m = 3","Step 3: Use point (0,0) to find c","Step 4: Solve for c","Step 5: Write final equation"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q5","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 4),
  (598, 172, 'Locate the point (3, -2) on a coordinate plane and describe its movement from origin', 'text', 1, 'x then y movement', '{"why":"Coordinates represent horizontal (x) and vertical (y) displacement from origin","sol":"Step 1: Start at origin (0,0)\nStep 2: Move +3 units along x-axis\nStep 3: Move −2 units along y-axis\nStep 4: Mark final position on plane","steps":["Step 1: Start at origin (0,0)","Step 2: Move +3 units along x-axis","Step 3: Move −2 units along y-axis","Step 4: Mark final position on plane"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Plotting points"}', 0),
  (599, 172, 'Find coordinates after moving 5 units right and 4 units up from origin', 'text', 1, 'directional movement', '{"why":"Positive x and y values place the point in the first quadrant","sol":"Step 1: Start at (0,0)\nStep 2: Move +5 along x-axis\nStep 3: Move +4 along y-axis\nStep 4: Plot final point","steps":["Step 1: Start at (0,0)","Step 2: Move +5 along x-axis","Step 3: Move +4 along y-axis","Step 4: Plot final point"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Plotting points"}', 1),
  (600, 172, 'Determine location of point (0, -6) on coordinate plane', 'text', 1, 'axis identification', '{"why":"x = 0 means the point lies directly on the y-axis","sol":"Step 1: Check x = 0\nStep 2: Move only along y-axis\nStep 3: Locate negative direction\nStep 4: Identify axis position","steps":["Step 1: Check x = 0","Step 2: Move only along y-axis","Step 3: Locate negative direction","Step 4: Identify axis position"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Plotting points"}', 2),
  (601, 172, 'Determine location of point (4, 0) on coordinate plane', 'text', 1, 'axis rule', '{"why":"y = 0 means the point lies on the x-axis","sol":"Step 1: Check y = 0\nStep 2: Move only along x-axis\nStep 3: Locate positive direction\nStep 4: Identify axis position","steps":["Step 1: Check y = 0","Step 2: Move only along x-axis","Step 3: Locate positive direction","Step 4: Identify axis position"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q4","subject":"math","chapter":"graphs","topic":"Plotting points"}', 3),
  (602, 172, 'Identify the reference starting point for all coordinate plotting', 'text', 1, 'origin concept', '{"why":"All coordinates are measured from the origin","sol":"Step 1: Locate intersection of axes\nStep 2: Identify x = 0 and y = 0\nStep 3: Mark central reference point","steps":["Step 1: Locate intersection of axes","Step 2: Identify x = 0 and y = 0","Step 3: Mark central reference point"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q5","subject":"math","chapter":"graphs","topic":"Plotting points"}', 4),
  (603, 173, 'Plot a line graph for points (1,2), (2,3), (3,5)', 'text', 1, 'coordinate plotting', '{"why":"Increasing y-values show upward trend","sol":"Step 1: Draw x-axis and y-axis\nStep 2: Plot (1,2), (2,3), (3,5)\nStep 3: Check correct positions on plane\nStep 4: Join points in order with straight lines","steps":["Step 1: Draw x-axis and y-axis","Step 2: Plot (1,2), (2,3), (3,5)","Step 3: Check correct positions on plane","Step 4: Join points in order with straight lines"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Line graphs"}', 0),
  (604, 173, 'Identify change when graph goes from (1,5) to (3,5)', 'text', 1, 'constant value', '{"why":"Equal y-values form a horizontal line","sol":"Step 1: Compare y-values at both points\nStep 2: 5 and 5 are equal\nStep 3: Determine slope behavior\nStep 4: Classify trend","steps":["Step 1: Compare y-values at both points","Step 2: 5 and 5 are equal","Step 3: Determine slope behavior","Step 4: Classify trend"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Line graphs"}', 1),
  (605, 173, 'Determine trend of points (1,4), (2,3), (3,2)', 'text', 1, 'decreasing pattern', '{"why":"Y-values reduce as x increases","sol":"Step 1: Observe y-values\nStep 2: 4 → 3 → 2\nStep 3: Check direction of change\nStep 4: Classify graph behavior","steps":["Step 1: Observe y-values","Step 2: 4 → 3 → 2","Step 3: Check direction of change","Step 4: Classify graph behavior"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Line graphs"}', 2),
  (606, 173, 'Find slope between points (1,1) and (4,7)', 'text', 1, 'rise over run', '{"why":"Slope measures rate of change in a line graph","sol":"Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)\nStep 2: Substitute values\nStep 3: Compute 7 − 1 = 6\nStep 4: Compute 4 − 1 = 3\nStep 5: Simplify fraction","steps":["Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)","Step 2: Substitute values","Step 3: Compute 7 − 1 = 6","Step 4: Compute 4 − 1 = 3","Step 5: Simplify fraction"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q4","subject":"math","chapter":"graphs","topic":"Line graphs"}', 3),
  (607, 173, 'Find missing point pattern if graph is linear: (1,2), (2,?), (3,6)', 'text', 1, 'linear pattern', '{"why":"Linear graphs have constant rate of change","sol":"Step 1: Observe change from 1 to 3 in x\nStep 2: Observe change from 2 to 6 in y\nStep 3: Determine pattern increase\nStep 4: Find middle value","steps":["Step 1: Observe change from 1 to 3 in x","Step 2: Observe change from 2 to 6 in y","Step 3: Determine pattern increase","Step 4: Find middle value"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q5","subject":"math","chapter":"graphs","topic":"Line graphs"}', 4),
  (608, 174, 'Find gradient when rise = 12 and run = 3', 'text', 1, 'm = rise ÷ run', '{"why":"Gradient measures vertical change per unit horizontal change","sol":"Step 1: Write m = rise ÷ run\nStep 2: Substitute m = 12 ÷ 3\nStep 3: Compute division\nStep 4: Simplify result","steps":["Step 1: Write m = rise ÷ run","Step 2: Substitute m = 12 ÷ 3","Step 3: Compute division","Step 4: Simplify result"],"options":[],"conceptId":"math_graphs_gradient","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Gradient"}', 0),
  (609, 174, 'Find gradient between points (2,5) and (6,1)', 'text', 1, 'use coordinate formula', '{"why":"Gradient is found using change in y over change in x","sol":"Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)\nStep 2: Substitute values (1 − 5)/(6 − 2)\nStep 3: Compute numerator −4\nStep 4: Compute denominator 4\nStep 5: Simplify fraction","steps":["Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)","Step 2: Substitute values (1 − 5)/(6 − 2)","Step 3: Compute numerator −4","Step 4: Compute denominator 4","Step 5: Simplify fraction"],"options":[],"conceptId":"math_graphs_gradient","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Gradient"}', 1),
  (610, 174, 'Interpret gradient m = -3 in a line', 'text', 1, 'direction', '{"why":"Negative gradient shows downward movement from left to right","sol":"Step 1: Identify sign of gradient\nStep 2: m < 0 indicates negative slope\nStep 3: For each 1 step right, y decreases by 3\nStep 4: Describe direction","steps":["Step 1: Identify sign of gradient","Step 2: m < 0 indicates negative slope","Step 3: For each 1 step right, y decreases by 3","Step 4: Describe direction"],"options":[],"conceptId":"math_graphs_gradient","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Gradient"}', 2),
  (611, 174, 'Interpret gradient m = 0', 'text', 1, 'flat line', '{"why":"Zero gradient means constant y-value across x","sol":"Step 1: Check gradient value\nStep 2: m = 0 means no vertical change\nStep 3: y-value remains constant\nStep 4: Describe graph","steps":["Step 1: Check gradient value","Step 2: m = 0 means no vertical change","Step 3: y-value remains constant","Step 4: Describe graph"],"options":[],"conceptId":"math_graphs_gradient","skillId":"math_graphs","subskillId":"math_graphs_q4","subject":"math","chapter":"graphs","topic":"Gradient"}', 3),
  (612, 175, 'Why are graphs important?', 'text', 1, 'show data visually', '{"why":"Graphs convert numerical data into visual form, making patterns and trends easier to understand","sol":"Step 1: Identify key concept: Define the required principles for Applications of graphs.\nStep 2: Apply governing rule: Graphs convert numerical data into visual form, making patterns and trends easier to understand\nStep 3: State the final conclusion: data visualization","steps":["Step 1: Identify key concept: Define the required principles for Applications of graphs.","Step 2: Apply governing rule: Graphs convert numerical data into visual form, making patterns and trends easier to understand","Step 3: State the final conclusion: data visualization"],"options":[],"conceptId":"math_graphs_applications_of_graphs","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Applications of graphs"}', 0),
  (613, 175, 'What do graphs help us identify?', 'text', 1, 'look at shape of graph', '{"why":"Graphs show how data changes over time or categories, revealing hidden patterns","sol":"Step 1: Identify key concept: Define the required principles for Applications of graphs.\nStep 2: Apply governing rule: Graphs show how data changes over time or categories, revealing hidden patterns\nStep 3: State the final conclusion: patterns and trends","steps":["Step 1: Identify key concept: Define the required principles for Applications of graphs.","Step 2: Apply governing rule: Graphs show how data changes over time or categories, revealing hidden patterns","Step 3: State the final conclusion: patterns and trends"],"options":[],"conceptId":"math_graphs_applications_of_graphs","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Applications of graphs"}', 1),
  (614, 175, 'Give one real-life use of graphs', 'text', 1, 'daily applications', '{"why":"Graphs are widely used to analyze weather, sales, population, and scientific data","sol":"Step 1: Identify key concept: Define the required principles for Applications of graphs.\nStep 2: Apply governing rule: Graphs are widely used to analyze weather, sales, population, and scientific data\nStep 3: State the final conclusion: weather forecasting or business analysis","steps":["Step 1: Identify key concept: Define the required principles for Applications of graphs.","Step 2: Apply governing rule: Graphs are widely used to analyze weather, sales, population, and scientific data","Step 3: State the final conclusion: weather forecasting or business analysis"],"options":[],"conceptId":"math_graphs_applications_of_graphs","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Applications of graphs"}', 2),
  (615, 176, 'Simplify the ratio 24:36', 'text', 1, 'HCF method', '{"why":"Ratios are simplified by dividing both terms by their highest common factor","sol":"Step 1: Find HCF of 24 and 36\nStep 2: HCF = 12\nStep 3: Divide both terms by 12\nStep 4: 24 ÷ 12 and 36 ÷ 12\nStep 5: Write simplified ratio","steps":["Step 1: Find HCF of 24 and 36","Step 2: HCF = 12","Step 3: Divide both terms by 12","Step 4: 24 ÷ 12 and 36 ÷ 12","Step 5: Write simplified ratio"],"options":[],"conceptId":"math_ratio_ratio_basics","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Ratio basics"}', 0),
  (616, 176, 'Divide 60 in the ratio 2:3', 'text', 1, 'total parts method', '{"why":"Total is split according to ratio parts","sol":"Step 1: Add ratio parts 2 + 3 = 5\nStep 2: Divide 60 by 5\nStep 3: One part = 12\nStep 4: Multiply 2 × 12 and 3 × 12\nStep 5: Find each share","steps":["Step 1: Add ratio parts 2 + 3 = 5","Step 2: Divide 60 by 5","Step 3: One part = 12","Step 4: Multiply 2 × 12 and 3 × 12","Step 5: Find each share"],"options":[],"conceptId":"math_ratio_ratio_basics","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Ratio basics"}', 1),
  (617, 176, 'Find ratio of 45 to 15 in simplest form', 'text', 1, 'divide both terms', '{"why":"Simplification reduces ratio to smallest whole numbers","sol":"Step 1: Write ratio 45:15\nStep 2: Find HCF = 15\nStep 3: Divide both terms by 15\nStep 4: Simplify result","steps":["Step 1: Write ratio 45:15","Step 2: Find HCF = 15","Step 3: Divide both terms by 15","Step 4: Simplify result"],"options":[],"conceptId":"math_ratio_ratio_basics","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Ratio basics"}', 2),
  (618, 176, 'Check if ratios 4:6 and 2:3 are equivalent', 'text', 1, 'compare simplified forms', '{"why":"Equivalent ratios reduce to the same simplest form","sol":"Step 1: Simplify 4:6\nStep 2: Divide both by 2 → 2:3\nStep 3: Compare with 2:3\nStep 4: Conclude equivalence","steps":["Step 1: Simplify 4:6","Step 2: Divide both by 2 → 2:3","Step 3: Compare with 2:3","Step 4: Conclude equivalence"],"options":[],"conceptId":"math_ratio_ratio_basics","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Ratio basics"}', 3),
  (619, 177, 'Divide 120 in the ratio 3:2', 'text', 1, 'total parts method', '{"why":"Total is distributed proportionally using ratio parts","sol":"Step 1: Add ratio parts 3 + 2 = 5\nStep 2: Divide 120 by 5\nStep 3: One part = 24\nStep 4: Multiply 3 × 24\nStep 5: Multiply 2 × 24\nStep 6: Write final split","steps":["Step 1: Add ratio parts 3 + 2 = 5","Step 2: Divide 120 by 5","Step 3: One part = 24","Step 4: Multiply 3 × 24","Step 5: Multiply 2 × 24","Step 6: Write final split"],"options":[],"conceptId":"math_ratio_dividing_in_ratio","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Dividing in ratio"}', 0),
  (620, 177, 'Divide 250 in the ratio 5:3', 'text', 1, 'part value method', '{"why":"Each share is proportional to its ratio weight","sol":"Step 1: Add ratio parts 5 + 3 = 8\nStep 2: Divide 250 by 8\nStep 3: One part = 31.25\nStep 4: Multiply 5 × 31.25\nStep 5: Multiply 3 × 31.25\nStep 6: Write final values","steps":["Step 1: Add ratio parts 5 + 3 = 8","Step 2: Divide 250 by 8","Step 3: One part = 31.25","Step 4: Multiply 5 × 31.25","Step 5: Multiply 3 × 31.25","Step 6: Write final values"],"options":[],"conceptId":"math_ratio_dividing_in_ratio","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Dividing in ratio"}', 1),
  (621, 177, 'Check if 40:60 simplifies correctly to 2:3', 'text', 1, 'simplification check', '{"why":"Both ratios represent the same proportional relationship","sol":"Step 1: Write ratio 40:60\nStep 2: Find HCF = 20\nStep 3: Divide both terms by 20\nStep 4: Get simplified form\nStep 5: Compare with 2:3","steps":["Step 1: Write ratio 40:60","Step 2: Find HCF = 20","Step 3: Divide both terms by 20","Step 4: Get simplified form","Step 5: Compare with 2:3"],"options":[],"conceptId":"math_ratio_dividing_in_ratio","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Dividing in ratio"}', 2),
  (622, 177, 'Find value of one part if 84 is divided in ratio 2:5', 'text', 1, 'total parts method', '{"why":"Each unit of ratio is found by dividing total by sum of parts","sol":"Step 1: Add ratio parts 2 + 5 = 7\nStep 2: Divide 84 by 7\nStep 3: One part = 12\nStep 4: Use part value for distribution","steps":["Step 1: Add ratio parts 2 + 5 = 7","Step 2: Divide 84 by 7","Step 3: One part = 12","Step 4: Use part value for distribution"],"options":[],"conceptId":"math_ratio_dividing_in_ratio","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Dividing in ratio"}', 3),
  (623, 178, 'Solve for x: 6:9 = x:27', 'text', 1, 'cross multiplication', '{"why":"Cross multiplication removes ratios and forms a solvable equation","sol":"Step 1: Write proportion 6/9 = x/27\nStep 2: Cross multiply → 6 × 27 = 9x\nStep 3: Compute 162 = 9x\nStep 4: Divide both sides by 9\nStep 5: Solve for x","steps":["Step 1: Write proportion 6/9 = x/27","Step 2: Cross multiply → 6 × 27 = 9x","Step 3: Compute 162 = 9x","Step 4: Divide both sides by 9","Step 5: Solve for x"],"options":[],"conceptId":"math_ratio_proportion","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Proportion"}', 0),
  (624, 178, 'Solve for x: 8:12 = 20:x', 'text', 1, 'diagonal multiplication', '{"why":"Proportions are solved by equating cross products","sol":"Step 1: Write 8/12 = 20/x\nStep 2: Cross multiply → 8x = 240\nStep 3: Divide both sides by 8\nStep 4: Solve for x","steps":["Step 1: Write 8/12 = 20/x","Step 2: Cross multiply → 8x = 240","Step 3: Divide both sides by 8","Step 4: Solve for x"],"options":[],"conceptId":"math_ratio_proportion","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Proportion"}', 1),
  (625, 178, 'Check if 3:5 and 12:20 form a proportion', 'text', 1, 'simplify ratio', '{"why":"Equivalent ratios form a valid proportion","sol":"Step 1: Simplify 12:20 by dividing by 4\nStep 2: Get 3:5\nStep 3: Compare both ratios\nStep 4: Confirm equality","steps":["Step 1: Simplify 12:20 by dividing by 4","Step 2: Get 3:5","Step 3: Compare both ratios","Step 4: Confirm equality"],"options":[],"conceptId":"math_ratio_proportion","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Proportion"}', 2),
  (626, 178, 'What is the value of x in 7/ x = 14/28', 'text', 1, 'cross multiply', '{"why":"Cross multiplication converts proportion into linear equation","sol":"Step 1: Cross multiply → 7 × 28 = 14x\nStep 2: Compute 196 = 14x\nStep 3: Divide both sides by 14\nStep 4: Solve for x","steps":["Step 1: Cross multiply → 7 × 28 = 14x","Step 2: Compute 196 = 14x","Step 3: Divide both sides by 14","Step 4: Solve for x"],"options":[],"conceptId":"math_ratio_proportion","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Proportion"}', 3),
  (627, 179, 'If 6 notebooks cost 90, find the cost of 1 notebook', 'text', 1, 'unit rate', '{"why":"Unit cost is found by dividing total cost by number of items","sol":"Step 1: Write total cost = 90 and quantity = 6\nStep 2: Compute 90 ÷ 6\nStep 3: Find cost per notebook\nStep 4: State unit price","steps":["Step 1: Write total cost = 90 and quantity = 6","Step 2: Compute 90 ÷ 6","Step 3: Find cost per notebook","Step 4: State unit price"],"options":[],"conceptId":"math_ratio_direct_proportion","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Direct proportion"}', 0),
  (628, 179, 'Find k if y = kx, when y = 36 and x = 9', 'text', 1, 'constant of proportionality', '{"why":"k represents constant ratio between y and x","sol":"Step 1: Write y = kx\nStep 2: Substitute 36 = k × 9\nStep 3: Divide both sides by 9\nStep 4: Solve for k","steps":["Step 1: Write y = kx","Step 2: Substitute 36 = k × 9","Step 3: Divide both sides by 9","Step 4: Solve for k"],"options":[],"conceptId":"math_ratio_direct_proportion","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Direct proportion"}', 1),
  (629, 179, 'If y = 5x, find y when x = 7', 'text', 1, 'substitution', '{"why":"Direct proportion uses substitution into linear equation","sol":"Step 1: Write equation y = 5x\nStep 2: Substitute x = 7\nStep 3: Multiply 5 × 7\nStep 4: Compute y value","steps":["Step 1: Write equation y = 5x","Step 2: Substitute x = 7","Step 3: Multiply 5 × 7","Step 4: Compute y value"],"options":[],"conceptId":"math_ratio_direct_proportion","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Direct proportion"}', 2),
  (630, 179, 'If x doubles in y = 3x, what happens to y when x changes from 4 to 8?', 'text', 1, 'scaling', '{"why":"In direct proportion, scaling x scales y by same factor","sol":"Step 1: Compute y when x = 4 → y = 3 × 4\nStep 2: Compute y when x = 8 → y = 3 × 8\nStep 3: Compare both results\nStep 4: Identify relationship","steps":["Step 1: Compute y when x = 4 → y = 3 × 4","Step 2: Compute y when x = 8 → y = 3 × 8","Step 3: Compare both results","Step 4: Identify relationship"],"options":[],"conceptId":"math_ratio_direct_proportion","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Direct proportion"}', 3),
  (631, 180, 'If y is inversely proportional to x and x = 6, y = 12, find k in x × y = k', 'text', 1, 'constant of inverse proportion', '{"why":"In inverse proportion, the product of x and y stays constant","sol":"Step 1: Write k = x × y\nStep 2: Substitute values k = 6 × 12\nStep 3: Multiply to find k","steps":["Step 1: Write k = x × y","Step 2: Substitute values k = 6 × 12","Step 3: Multiply to find k"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 0),
  (632, 180, 'If x = 9 and y = 8 in an inverse proportion, find k', 'text', 1, 'multiply values', '{"why":"Inverse proportion means x × y remains constant","sol":"Step 1: Write k = x × y\nStep 2: Substitute k = 9 × 8\nStep 3: Compute product","steps":["Step 1: Write k = x × y","Step 2: Substitute k = 9 × 8","Step 3: Compute product"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 1),
  (633, 180, 'If y is inversely proportional to x and x = 3, y = 20, find k', 'text', 1, 'constant product rule', '{"why":"The product of variables remains unchanged in inverse proportion","sol":"Step 1: Use k = x × y\nStep 2: Substitute 3 × 20\nStep 3: Calculate k","steps":["Step 1: Use k = x × y","Step 2: Substitute 3 × 20","Step 3: Calculate k"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 2),
  (634, 180, 'If x = 5 and y = 14 in inverse proportion, determine k', 'text', 1, 'multiply', '{"why":"Inverse proportion keeps product of variables constant","sol":"Step 1: Write formula k = x × y\nStep 2: Substitute values 5 × 14\nStep 3: Compute result","steps":["Step 1: Write formula k = x × y","Step 2: Substitute values 5 × 14","Step 3: Compute result"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 3),
  (635, 180, 'If y is inversely proportional to x and x = 2, y = 30, find k', 'text', 1, 'constant product', '{"why":"Inverse proportion is defined by a constant product relationship","sol":"Step 1: Write k = x × y\nStep 2: Substitute 2 × 30\nStep 3: Multiply to get k","steps":["Step 1: Write k = x × y","Step 2: Substitute 2 × 30","Step 3: Multiply to get k"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q5","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 4),
  (636, 181, 'A teacher records the marks 34, 47, 51 and 63 for four learners. What do these recorded values represent?', 'text', 1, 'Think about what recorded observations are called.', '{"why":"The marks are recorded information, so they form a data set.","sol":"Step 1: The numbers are recorded observations.\nStep 2: A collection of recorded observations is called data.","steps":["Step 1: The numbers are recorded observations.","Step 2: A collection of recorded observations is called data."],"options":[],"conceptId":"math_statistics_meaning_of_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Meaning of Data"}', 0),
  (637, 181, 'A class records the favourite fruits of its learners as mango, banana, orange and mango. Are these observations data?', 'text', 1, 'Data does not have to be numerical.', '{"why":"Data can be numerical or non-numerical.","sol":"Step 1: The fruit names are recorded observations.\nStep 2: Recorded observations are data even when they are words rather than numbers.","steps":["Step 1: The fruit names are recorded observations.","Step 2: Recorded observations are data even when they are words rather than numbers."],"options":[],"conceptId":"math_statistics_meaning_of_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Meaning of Data"}', 1),
  (638, 181, 'A learner writes 12, 15, 9 and 20 after counting the books read by four learners. What are these values?', 'text', 1, 'They are recorded observations.', '{"why":"The numbers are recorded information collected for a purpose.","sol":"Step 1: The learner has recorded four observations.\nStep 2: Those observations form a data set.","steps":["Step 1: The learner has recorded four observations.","Step 2: Those observations form a data set."],"options":[],"conceptId":"math_statistics_meaning_of_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Meaning of Data"}', 2),
  (639, 182, 'A teacher calculates the average mark of a class from the recorded test scores. Is the teacher using data or statistics?', 'text', 1, 'The marks are data. What is being done to the marks?', '{"why":"The teacher is performing a statistical operation on collected data.","sol":"Step 1: The recorded marks are data.\nStep 2: Calculating an average is analysing the data.\nStep 3: Analysing data is part of statistics.","steps":["Step 1: The recorded marks are data.","Step 2: Calculating an average is analysing the data.","Step 3: Analysing data is part of statistics."],"options":[],"conceptId":"math_statistics_meaning_of_statistics","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Meaning of Statistics"}', 0),
  (640, 182, 'A school records the ages of 100 learners. Are the recorded ages themselves statistics?', 'text', 1, 'Separate the information collected from what we do with it.', '{"why":"The recorded ages are the raw information being used in statistics.","sol":"Step 1: The ages are recorded observations.\nStep 2: Recorded observations are data.\nStep 3: They become part of statistical work when they are organised, analysed or interpreted.","steps":["Step 1: The ages are recorded observations.","Step 2: Recorded observations are data.","Step 3: They become part of statistical work when they are organised, analysed or interpreted."],"options":[],"conceptId":"math_statistics_meaning_of_statistics","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Meaning of Statistics"}', 1),
  (641, 182, 'A learner draws a graph from a table of collected marks. Is this part of statistics?', 'text', 1, 'Think about representing data.', '{"why":"Representing data is one of the main activities in statistics.","sol":"Step 1: The marks are data.\nStep 2: The learner is representing the data graphically.\nStep 3: Representation of data is part of statistics.","steps":["Step 1: The marks are data.","Step 2: The learner is representing the data graphically.","Step 3: Representation of data is part of statistics."],"options":[],"conceptId":"math_statistics_meaning_of_statistics","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Meaning of Statistics"}', 2),
  (642, 183, 'A learner asks 20 classmates how much money they spend on lunch each day and records their answers. Is this primary or secondary data?', 'text', 1, 'Who collected the information?', '{"why":"It was collected directly by the investigator.","sol":"Step 1: The learner directly asked the classmates.\nStep 2: The learner collected the information for the investigation.\nStep 3: Therefore, the data is primary data.","steps":["Step 1: The learner directly asked the classmates.","Step 2: The learner collected the information for the investigation.","Step 3: Therefore, the data is primary data."],"options":[],"conceptId":"math_statistics_primary_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Primary Data"}', 0),
  (643, 183, 'A teacher measures the heights of learners in her class for a school investigation. What type of data is collected?', 'text', 1, 'The teacher is collecting the measurements directly.', '{"why":"The measurements come directly from the original investigation.","sol":"Step 1: The teacher measures the learners herself.\nStep 2: The measurements are collected directly.\nStep 3: Therefore, they are primary data.","steps":["Step 1: The teacher measures the learners herself.","Step 2: The measurements are collected directly.","Step 3: Therefore, they are primary data."],"options":[],"conceptId":"math_statistics_primary_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Primary Data"}', 1),
  (644, 183, 'A researcher interviews 50 farmers and records their answers. Is the information primary data?', 'text', 1, 'Look at who obtained the information.', '{"why":"The researcher collected the information directly.","sol":"Step 1: The researcher directly interviews the farmers.\nStep 2: The researcher obtains the information firsthand.\nStep 3: Therefore, the information is primary data.","steps":["Step 1: The researcher directly interviews the farmers.","Step 2: The researcher obtains the information firsthand.","Step 3: Therefore, the information is primary data."],"options":[],"conceptId":"math_statistics_primary_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Primary Data"}', 2),
  (645, 184, 'A student uses population figures from a published government report. Is this primary or secondary data?', 'text', 1, 'Did the student collect the population figures herself?', '{"why":"The information was collected previously by another source.","sol":"Step 1: The figures had already been collected and published.\nStep 2: The student is using existing information.\nStep 3: Therefore, the data is secondary data.","steps":["Step 1: The figures had already been collected and published.","Step 2: The student is using existing information.","Step 3: Therefore, the data is secondary data."],"options":[],"conceptId":"math_statistics_secondary_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Secondary Data"}', 0),
  (646, 184, 'A researcher uses rainfall records collected by another organisation five years earlier. What type of data is this?', 'text', 1, 'The researcher did not originally collect the measurements.', '{"why":"The researcher is using previously collected information.","sol":"Step 1: The rainfall measurements already existed.\nStep 2: Another organisation collected them.\nStep 3: Therefore, they are secondary data for the researcher.","steps":["Step 1: The rainfall measurements already existed.","Step 2: Another organisation collected them.","Step 3: Therefore, they are secondary data for the researcher."],"options":[],"conceptId":"math_statistics_secondary_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Secondary Data"}', 1),
  (647, 184, 'A learner measures today''s temperature herself and records it. Is this secondary data?', 'text', 1, 'Who collected the measurement?', '{"why":"The learner collected the measurement directly.","sol":"Step 1: The learner directly measures the temperature.\nStep 2: The measurement is collected firsthand.\nStep 3: Therefore, it is primary data, not secondary data.","steps":["Step 1: The learner directly measures the temperature.","Step 2: The measurement is collected firsthand.","Step 3: Therefore, it is primary data, not secondary data."],"options":[],"conceptId":"math_statistics_secondary_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Secondary Data"}', 2),
  (648, 185, 'A school records the favourite subjects of learners as Mathematics, English, Biology and Physics. What type of data is this?', 'text', 1, 'Are the values measurements or categories?', '{"why":"The observations describe categories rather than numerical measurements.","sol":"Step 1: The values are names of subjects.\nStep 2: Subject names are categories.\nStep 3: Therefore, the data is qualitative.","steps":["Step 1: The values are names of subjects.","Step 2: Subject names are categories.","Step 3: Therefore, the data is qualitative."],"options":[],"conceptId":"math_statistics_qualitative_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Qualitative Data"}', 0),
  (649, 185, 'A survey records eye colours as brown, black and blue. Is this qualitative data?', 'text', 1, 'Eye colour is a category.', '{"why":"Eye colour describes a category or quality.","sol":"Step 1: The observations identify types of eye colour.\nStep 2: These are categories.\nStep 3: Therefore, the data is qualitative.","steps":["Step 1: The observations identify types of eye colour.","Step 2: These are categories.","Step 3: Therefore, the data is qualitative."],"options":[],"conceptId":"math_statistics_qualitative_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Qualitative Data"}', 1),
  (650, 185, 'A survey records transport methods as bus, walking, bicycle and motorcycle. What type of data is this?', 'text', 1, 'Look at what the observations represent.', '{"why":"The observations are categories describing types of transport.","sol":"Step 1: Each response identifies a transport category.\nStep 2: The responses are not measurements.\nStep 3: Therefore, the data is qualitative.","steps":["Step 1: Each response identifies a transport category.","Step 2: The responses are not measurements.","Step 3: Therefore, the data is qualitative."],"options":[],"conceptId":"math_statistics_qualitative_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Qualitative Data"}', 2),
  (651, 186, 'A teacher records the marks 45, 56, 72 and 81. What type of data are the marks?', 'text', 1, 'The observations are numerical.', '{"why":"The marks are numerical values.","sol":"Step 1: The observations are numbers.\nStep 2: They represent measured or counted quantities.\nStep 3: Therefore, the data is quantitative.","steps":["Step 1: The observations are numbers.","Step 2: They represent measured or counted quantities.","Step 3: Therefore, the data is quantitative."],"options":[],"conceptId":"math_statistics_quantitative_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Quantitative Data"}', 0),
  (652, 186, 'A survey records the number of siblings for five learners as 0, 2, 1, 3 and 4. What type of data is this?', 'text', 1, 'The numbers are counts.', '{"why":"The observations are numerical counts.","sol":"Step 1: Each value counts the number of siblings.\nStep 2: Counts are numerical data.\nStep 3: Therefore, the data is quantitative.","steps":["Step 1: Each value counts the number of siblings.","Step 2: Counts are numerical data.","Step 3: Therefore, the data is quantitative."],"options":[],"conceptId":"math_statistics_quantitative_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Quantitative Data"}', 1),
  (653, 186, 'A teacher records the heights of learners in centimetres. Is this quantitative data?', 'text', 1, 'Height is measured using numbers.', '{"why":"Height is a numerical measurement.","sol":"Step 1: Height is measured numerically.\nStep 2: The measurements are expressed in centimetres.\nStep 3: Therefore, the data is quantitative.","steps":["Step 1: Height is measured numerically.","Step 2: The measurements are expressed in centimetres.","Step 3: Therefore, the data is quantitative."],"options":[],"conceptId":"math_statistics_quantitative_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Quantitative Data"}', 2),
  (654, 187, 'The number of books owned by learners is recorded. Is this discrete or continuous data?', 'text', 1, 'Are books counted or measured?', '{"why":"The number of books is obtained by counting separate objects.","sol":"Step 1: Books are counted.\nStep 2: A learner can have 4 books or 5 books, but not 4.5 books as a count of complete books.\nStep 3: Therefore, the data is discrete.","steps":["Step 1: Books are counted.","Step 2: A learner can have 4 books or 5 books, but not 4.5 books as a count of complete books.","Step 3: Therefore, the data is discrete."],"options":[],"conceptId":"math_statistics_discrete_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Discrete Data"}', 0),
  (655, 187, 'A school records the number of learners in each class. What type of quantitative data is this?', 'text', 1, 'Learners are counted.', '{"why":"The number of learners is a count.","sol":"Step 1: The school counts the learners.\nStep 2: The values are separate whole-number counts.\nStep 3: Therefore, the data is discrete.","steps":["Step 1: The school counts the learners.","Step 2: The values are separate whole-number counts.","Step 3: Therefore, the data is discrete."],"options":[],"conceptId":"math_statistics_discrete_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Discrete Data"}', 1),
  (656, 187, 'A team records the number of goals scored in each match. Is the number of goals discrete?', 'text', 1, 'Can goals be counted?', '{"why":"The number of goals is a count of separate events.","sol":"Step 1: Goals occur as separate events.\nStep 2: The number of goals is counted.\nStep 3: Therefore, the data is discrete.","steps":["Step 1: Goals occur as separate events.","Step 2: The number of goals is counted.","Step 3: Therefore, the data is discrete."],"options":[],"conceptId":"math_statistics_discrete_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Discrete Data"}', 2),
  (657, 188, 'The heights of learners are measured in centimetres. Is height discrete or continuous?', 'text', 1, 'Height is measured, not counted.', '{"why":"Height can take measured values within a range.","sol":"Step 1: Height is obtained by measurement.\nStep 2: A height such as 160 cm can be measured more precisely as 160.4 cm.\nStep 3: Therefore, height is continuous data.","steps":["Step 1: Height is obtained by measurement.","Step 2: A height such as 160 cm can be measured more precisely as 160.4 cm.","Step 3: Therefore, height is continuous data."],"options":[],"conceptId":"math_statistics_continuous_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Continuous Data"}', 0),
  (658, 188, 'The time taken by runners to complete a race is recorded. Is time discrete or continuous?', 'text', 1, 'Can time have values between two whole numbers?', '{"why":"Time can take many possible values within an interval.","sol":"Step 1: Time is measured.\nStep 2: A runner can take 12.1 seconds, 12.15 seconds, 12.153 seconds, and so on.\nStep 3: Therefore, time is continuous.","steps":["Step 1: Time is measured.","Step 2: A runner can take 12.1 seconds, 12.15 seconds, 12.153 seconds, and so on.","Step 3: Therefore, time is continuous."],"options":[],"conceptId":"math_statistics_continuous_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Continuous Data"}', 1),
  (659, 188, 'The mass of bags of maize is measured. What type of data is the mass?', 'text', 1, 'Mass is measured using units such as kilograms.', '{"why":"Mass can take measured values between whole numbers.","sol":"Step 1: Mass is obtained by measurement.\nStep 2: It can have decimal values such as 49.5 kg.\nStep 3: Therefore, mass is continuous data.","steps":["Step 1: Mass is obtained by measurement.","Step 2: It can have decimal values such as 49.5 kg.","Step 3: Therefore, mass is continuous data."],"options":[],"conceptId":"math_statistics_continuous_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Continuous Data"}', 2),
  (660, 189, 'A school wants to study the heights of all 800 learners in the school. What is the population?', 'text', 1, 'Identify the complete group being studied.', '{"why":"The population is the complete group that the investigation is about.","sol":"Step 1: The investigation concerns all learners in the school.\nStep 2: There are 800 learners.\nStep 3: Therefore, all 800 learners form the population.","steps":["Step 1: The investigation concerns all learners in the school.","Step 2: There are 800 learners.","Step 3: Therefore, all 800 learners form the population."],"options":[],"conceptId":"math_statistics_population","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Population"}', 0),
  (661, 189, 'A factory wants to study all 2,000 bottles produced on Monday. What is the population?', 'text', 1, 'Look for the entire group under investigation.', '{"why":"The population is the complete set of objects being studied.","sol":"Step 1: The investigation concerns bottles produced on Monday.\nStep 2: There were 2,000 such bottles.\nStep 3: Therefore, all 2,000 bottles form the population.","steps":["Step 1: The investigation concerns bottles produced on Monday.","Step 2: There were 2,000 such bottles.","Step 3: Therefore, all 2,000 bottles form the population."],"options":[],"conceptId":"math_statistics_population","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Population"}', 1),
  (662, 189, 'A researcher wants to study all Form 2 learners in a school. Are five selected Form 2 learners the population?', 'text', 1, 'Compare five learners with the complete group.', '{"why":"The population is the entire group being studied, not just part of it.","sol":"Step 1: The investigation concerns all Form 2 learners.\nStep 2: Five learners are only part of the complete group.\nStep 3: Therefore, the five learners are not the population.","steps":["Step 1: The investigation concerns all Form 2 learners.","Step 2: Five learners are only part of the complete group.","Step 3: Therefore, the five learners are not the population."],"options":[],"conceptId":"math_statistics_population","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Population"}', 2),
  (663, 190, 'A school has 1,200 learners and a researcher selects 120 learners for a study. What is the sample?', 'text', 1, 'The sample is the selected part.', '{"why":"A sample is the selected part of the population.","sol":"Step 1: The population contains all 1,200 learners.\nStep 2: The researcher selected 120 learners.\nStep 3: Therefore, the 120 selected learners form the sample.","steps":["Step 1: The population contains all 1,200 learners.","Step 2: The researcher selected 120 learners.","Step 3: Therefore, the 120 selected learners form the sample."],"options":[],"conceptId":"math_statistics_sample","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Sample"}', 0),
  (664, 190, 'A factory produces 4,000 items and an inspector checks 100 of them. What is the population?', 'text', 1, 'The population is the complete group.', '{"why":"The population is the complete group under investigation.","sol":"Step 1: All 4,000 items were produced.\nStep 2: Only 100 were selected for inspection.\nStep 3: Therefore, the population is all 4,000 items.","steps":["Step 1: All 4,000 items were produced.","Step 2: Only 100 were selected for inspection.","Step 3: Therefore, the population is all 4,000 items."],"options":[],"conceptId":"math_statistics_sample","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Sample"}', 1),
  (665, 190, 'A researcher wants to study 2,000 students but selects 200 students for the investigation. Which group is the sample?', 'text', 1, 'Which group was actually selected?', '{"why":"The sample is the selected subset of the population.","sol":"Step 1: The 2,000 students form the complete population.\nStep 2: The researcher selected 200 students.\nStep 3: Therefore, the 200 selected students form the sample.","steps":["Step 1: The 2,000 students form the complete population.","Step 2: The researcher selected 200 students.","Step 3: Therefore, the 200 selected students form the sample."],"options":[],"conceptId":"math_statistics_sample","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Sample"}', 2),
  (666, 191, 'A teacher asks learners which subjects they like most. What is the source of the data?', 'text', 1, 'Who provides the information?', '{"why":"The source is the person or record from which the information comes.","sol":"Step 1: The teacher asks the learners.\nStep 2: The learners provide the answers.\nStep 3: Therefore, the learners are the source of the data.","steps":["Step 1: The teacher asks the learners.","Step 2: The learners provide the answers.","Step 3: Therefore, the learners are the source of the data."],"options":[],"conceptId":"math_statistics_sources_of_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Sources of Data"}', 0),
  (667, 191, 'A researcher uses a school''s admission records to find the number of learners enrolled. What is the source?', 'text', 1, 'Where did the information come from?', '{"why":"The records contain the information being used.","sol":"Step 1: The researcher did not create the original records.\nStep 2: The information comes from the school''s admission records.\nStep 3: Therefore, the records are the source.","steps":["Step 1: The researcher did not create the original records.","Step 2: The information comes from the school''s admission records.","Step 3: Therefore, the records are the source."],"options":[],"conceptId":"math_statistics_sources_of_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Sources of Data"}', 1),
  (668, 191, 'A researcher measures the heights of learners. Are the measuring instruments the main source of the data?', 'text', 1, 'The instrument measures, but whose height is being recorded?', '{"why":"The instrument is a collection tool; the source is the group from which the information originates.","sol":"Step 1: The instrument is used to obtain the measurements.\nStep 2: The measurements describe the learners.\nStep 3: Therefore, the learners are the source, while the instrument is a tool for collecting the data.","steps":["Step 1: The instrument is used to obtain the measurements.","Step 2: The measurements describe the learners.","Step 3: Therefore, the learners are the source, while the instrument is a tool for collecting the data."],"options":[],"conceptId":"math_statistics_sources_of_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Sources of Data"}', 2),
  (669, 192, 'A researcher gives 100 learners a form containing questions and collects their completed answers. Which method is being used?', 'text', 1, 'Think about a written set of questions.', '{"why":"A questionnaire collects information through a set of questions.","sol":"Step 1: The learners are given questions to answer.\nStep 2: Their answers are collected using a form.\nStep 3: Therefore, the method is a questionnaire.","steps":["Step 1: The learners are given questions to answer.","Step 2: Their answers are collected using a form.","Step 3: Therefore, the method is a questionnaire."],"options":[],"conceptId":"math_statistics_methods_of_collecting_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Methods of Collecting Data"}', 0),
  (670, 192, 'A researcher watches vehicles passing a road and records their numbers. Which method is being used?', 'text', 1, 'The researcher is watching and recording.', '{"why":"The information is obtained by watching and recording events.","sol":"Step 1: The researcher does not ask the drivers questions.\nStep 2: The researcher watches what happens.\nStep 3: Therefore, the method is observation.","steps":["Step 1: The researcher does not ask the drivers questions.","Step 2: The researcher watches what happens.","Step 3: Therefore, the method is observation."],"options":[],"conceptId":"math_statistics_methods_of_collecting_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Methods of Collecting Data"}', 1),
  (671, 192, 'A teacher uses a measuring tape to record the heights of learners. Which method is used?', 'text', 1, 'What is the teacher doing to obtain the values?', '{"why":"The values are obtained by directly measuring a characteristic.","sol":"Step 1: The teacher uses an instrument.\nStep 2: The teacher obtains numerical values by measuring height.\nStep 3: Therefore, the method is measurement.","steps":["Step 1: The teacher uses an instrument.","Step 2: The teacher obtains numerical values by measuring height.","Step 3: Therefore, the method is measurement."],"options":[],"conceptId":"math_statistics_methods_of_collecting_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Methods of Collecting Data"}', 2),
  (672, 193, 'A value occurs 8 times. How many tally marks should be recorded?', 'text', 1, 'Separate the 8 observations into groups of five.', '{"why":"Tally marks record each occurrence, with groups of five making counting easier.","sol":"Step 1: The first five observations make one group of five.\nStep 2: There are 3 observations remaining.\nStep 3: Therefore, the tally represents 5 + 3 = 8.","steps":["Step 1: The first five observations make one group of five.","Step 2: There are 3 observations remaining.","Step 3: Therefore, the tally represents 5 + 3 = 8."],"options":[],"conceptId":"math_statistics_tally_marks","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Tally Marks"}', 0),
  (673, 193, 'A value has tally marks representing 5 + 5 + 2 observations. What is its frequency?', 'text', 1, 'Add the groups.', '{"why":"The frequency is the total number represented by all the tally groups.","sol":"Step 1: The first group represents 5.\nStep 2: The second group represents 5.\nStep 3: The remaining marks represent 2.\nStep 4: 5 + 5 + 2 = 12.","steps":["Step 1: The first group represents 5.","Step 2: The second group represents 5.","Step 3: The remaining marks represent 2.","Step 4: 5 + 5 + 2 = 12."],"options":[],"conceptId":"math_statistics_tally_marks","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Tally Marks"}', 1),
  (674, 193, 'A tally shows one group of five and four additional marks. What frequency does it represent?', 'text', 1, 'A complete tally group represents 5.', '{"why":"The tally represents nine occurrences.","sol":"Step 1: One complete group = 5.\nStep 2: Four additional marks = 4.\nStep 3: 5 + 4 = 9.","steps":["Step 1: One complete group = 5.","Step 2: Four additional marks = 4.","Step 3: 5 + 4 = 9."],"options":[],"conceptId":"math_statistics_tally_marks","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Tally Marks"}', 2),
  (675, 194, 'Find the frequency of 7 in the data: 3, 7, 5, 7, 2, 7, 4.', 'text', 1, 'Count how many times 7 appears.', '{"why":"Frequency is the number of times a value occurs.","sol":"Step 1: Read through the data.\nStep 2: The value 7 appears in the second position.\nStep 3: It appears again in the fourth position.\nStep 4: It appears again in the sixth position.\nStep 5: Therefore, it appears 3 times.","steps":["Step 1: Read through the data.","Step 2: The value 7 appears in the second position.","Step 3: It appears again in the fourth position.","Step 4: It appears again in the sixth position.","Step 5: Therefore, it appears 3 times."],"options":[],"conceptId":"math_statistics_frequency","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Frequency"}', 0),
  (676, 194, 'Find the frequency of 4 in: 4, 2, 5, 4, 6, 4, 1, 4.', 'text', 1, 'Count every occurrence of 4.', '{"why":"The value 4 occurs four times.","sol":"Step 1: 4 appears first.\nStep 2: 4 appears again in the fourth position.\nStep 3: 4 appears again in the sixth position.\nStep 4: 4 appears again in the eighth position.\nStep 5: Therefore, the frequency is 4.","steps":["Step 1: 4 appears first.","Step 2: 4 appears again in the fourth position.","Step 3: 4 appears again in the sixth position.","Step 4: 4 appears again in the eighth position.","Step 5: Therefore, the frequency is 4."],"options":[],"conceptId":"math_statistics_frequency","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Frequency"}', 1),
  (677, 194, 'In the data 2, 2, 3, 4, 2, 5, 6, 2, what is the frequency of 2?', 'text', 1, 'Count all the 2s.', '{"why":"The value 2 occurs four times.","sol":"Step 1: There is a 2 in the first position.\nStep 2: There is a 2 in the second position.\nStep 3: There is a 2 in the fifth position.\nStep 4: There is a 2 in the eighth position.\nStep 5: Therefore, the frequency is 4.","steps":["Step 1: There is a 2 in the first position.","Step 2: There is a 2 in the second position.","Step 3: There is a 2 in the fifth position.","Step 4: There is a 2 in the eighth position.","Step 5: Therefore, the frequency is 4."],"options":[],"conceptId":"math_statistics_frequency","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Frequency"}', 2),
  (678, 195, 'For the data 1, 2, 1, 3, 2, 1, identify the frequency of 1.', 'text', 1, 'Count the number of times 1 occurs.', '{"why":"The frequency tells us how many observations have the value 1.","sol":"Step 1: The value 1 occurs first.\nStep 2: It occurs again in the third position.\nStep 3: It occurs again in the sixth position.\nStep 4: Therefore, its frequency is 3.","steps":["Step 1: The value 1 occurs first.","Step 2: It occurs again in the third position.","Step 3: It occurs again in the sixth position.","Step 4: Therefore, its frequency is 3."],"options":[],"conceptId":"math_statistics_frequency_distribution_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Frequency Distribution Table"}', 0),
  (679, 195, 'For the data 2, 4, 2, 5, 4, 2, what is the frequency of 4?', 'text', 1, 'Count the 4s.', '{"why":"The value 4 appears twice.","sol":"Step 1: 4 occurs in the second position.\nStep 2: 4 occurs again in the fifth position.\nStep 3: Therefore, the frequency of 4 is 2.","steps":["Step 1: 4 occurs in the second position.","Step 2: 4 occurs again in the fifth position.","Step 3: Therefore, the frequency of 4 is 2."],"options":[],"conceptId":"math_statistics_frequency_distribution_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Frequency Distribution Table"}', 1),
  (680, 195, 'A frequency table has frequencies 3, 5, 2 and 4. How many observations are represented altogether?', 'text', 1, 'Add all frequencies.', '{"why":"The sum of all frequencies gives the total number of observations.","sol":"Step 1: Frequency 1 = 3.\nStep 2: Frequency 2 = 5.\nStep 3: Frequency 3 = 2.\nStep 4: Frequency 4 = 4.\nStep 5: 3 + 5 + 2 + 4 = 14.","steps":["Step 1: Frequency 1 = 3.","Step 2: Frequency 2 = 5.","Step 3: Frequency 3 = 2.","Step 4: Frequency 4 = 4.","Step 5: 3 + 5 + 2 + 4 = 14."],"options":[],"conceptId":"math_statistics_frequency_distribution_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Frequency Distribution Table"}', 2),
  (681, 196, 'Construct the frequencies for the data: 1, 2, 1, 3, 2, 1.', 'text', 1, 'List 1, 2 and 3, then count each.', '{"why":"Each frequency is obtained by counting that value in the original data.","sol":"Step 1: Value 1 occurs 3 times.\nStep 2: Value 2 occurs 2 times.\nStep 3: Value 3 occurs 1 time.\nStep 4: Therefore, the frequencies are 3, 2 and 1 respectively.","steps":["Step 1: Value 1 occurs 3 times.","Step 2: Value 2 occurs 2 times.","Step 3: Value 3 occurs 1 time.","Step 4: Therefore, the frequencies are 3, 2 and 1 respectively."],"options":[],"conceptId":"math_statistics_constructing_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Constructing an Ungrouped Frequency Table"}', 0),
  (682, 196, 'Construct the frequency table for 2, 4, 2, 3, 4, 2, 3, 4.', 'text', 1, 'The different values are 2, 3 and 4.', '{"why":"The frequency table summarises how often each distinct value occurs.","sol":"Step 1: 2 occurs 3 times.\nStep 2: 3 occurs 2 times.\nStep 3: 4 occurs 3 times.\nStep 4: The frequencies total 3 + 2 + 3 = 8, matching the 8 observations.","steps":["Step 1: 2 occurs 3 times.","Step 2: 3 occurs 2 times.","Step 3: 4 occurs 3 times.","Step 4: The frequencies total 3 + 2 + 3 = 8, matching the 8 observations."],"options":[],"conceptId":"math_statistics_constructing_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Constructing an Ungrouped Frequency Table"}', 1),
  (683, 196, 'A data set is 5, 6, 5, 7, 6, 5. What is the frequency of each value?', 'text', 1, 'Count each distinct value.', '{"why":"Each frequency comes directly from counting the original observations.","sol":"Step 1: 5 occurs 3 times.\nStep 2: 6 occurs 2 times.\nStep 3: 7 occurs 1 time.","steps":["Step 1: 5 occurs 3 times.","Step 2: 6 occurs 2 times.","Step 3: 7 occurs 1 time."],"options":[],"conceptId":"math_statistics_constructing_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Constructing an Ungrouped Frequency Table"}', 2),
  (684, 197, 'A frequency table shows that the value 4 has frequency 6. What does this mean?', 'text', 1, 'Frequency tells how many times the value occurs.', '{"why":"Frequency tells the number of observations having that value.","sol":"Step 1: The value is 4.\nStep 2: Its frequency is 6.\nStep 3: Therefore, 4 occurs six times.","steps":["Step 1: The value is 4.","Step 2: Its frequency is 6.","Step 3: Therefore, 4 occurs six times."],"options":[],"conceptId":"math_statistics_reading_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Reading an Ungrouped Frequency Table"}', 0),
  (685, 197, 'A table shows that the number of books 2 has frequency 8. How many learners have 2 books?', 'text', 1, 'The frequency tells you the number of learners.', '{"why":"The frequency tells how many observations have the value 2.","sol":"Step 1: The value 2 represents the number of books.\nStep 2: Its frequency is 8.\nStep 3: Therefore, 8 learners have 2 books.","steps":["Step 1: The value 2 represents the number of books.","Step 2: Its frequency is 8.","Step 3: Therefore, 8 learners have 2 books."],"options":[],"conceptId":"math_statistics_reading_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Reading an Ungrouped Frequency Table"}', 1),
  (686, 197, 'A value has frequency 12. Does this mean the value itself is 12?', 'text', 1, 'Separate value from frequency.', '{"why":"A frequency of 12 does not change the value; it tells how often the value occurs.","sol":"Step 1: The value identifies the observation.\nStep 2: The frequency tells how many times it occurs.\nStep 3: Therefore, a frequency of 12 means the observation occurs 12 times.","steps":["Step 1: The value identifies the observation.","Step 2: The frequency tells how many times it occurs.","Step 3: Therefore, a frequency of 12 means the observation occurs 12 times."],"options":[],"conceptId":"math_statistics_reading_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Reading an Ungrouped Frequency Table"}', 2),
  (687, 198, 'Find the total frequency: 4, 5, 3 and 8.', 'text', 1, 'Add all the frequencies.', '{"why":"The total frequency is the sum of all frequencies.","sol":"Step 1: 4 + 5 = 9.\nStep 2: 9 + 3 = 12.\nStep 3: 12 + 8 = 20.","steps":["Step 1: 4 + 5 = 9.","Step 2: 9 + 3 = 12.","Step 3: 12 + 8 = 20."],"options":[],"conceptId":"math_statistics_total_frequency","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Total Frequency"}', 0),
  (688, 198, 'A frequency table has frequencies 2, 7, 6 and 5. How many observations are represented?', 'text', 1, 'The total number of observations equals the total frequency.', '{"why":"Adding all frequencies gives the total number of observations.","sol":"Step 1: 2 + 7 = 9.\nStep 2: 9 + 6 = 15.\nStep 3: 15 + 5 = 20.","steps":["Step 1: 2 + 7 = 9.","Step 2: 9 + 6 = 15.","Step 3: 15 + 5 = 20."],"options":[],"conceptId":"math_statistics_total_frequency","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Total Frequency"}', 1),
  (689, 198, 'A raw data set contains 25 observations. A frequency table made from it has frequencies 5, 8, 4 and 7. Is the table complete?', 'text', 1, 'Compare the total frequency with 25.', '{"why":"A complete frequency table should have total frequency equal to the number of original observations.","sol":"Step 1: 5 + 8 + 4 + 7 = 24.\nStep 2: The original data contains 25 observations.\nStep 3: The frequency total is only 24.\nStep 4: Therefore, one observation is missing from the table.","steps":["Step 1: 5 + 8 + 4 + 7 = 24.","Step 2: The original data contains 25 observations.","Step 3: The frequency total is only 24.","Step 4: Therefore, one observation is missing from the table."],"options":[],"conceptId":"math_statistics_total_frequency","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Total Frequency"}', 2),
  (690, 199, 'A data set has 20 observations. A frequency table has frequencies 6, 8 and 6. Does the total-frequency check pass?', 'text', 1, 'Add the three frequencies.', '{"why":"The total frequency equals the number of original observations.","sol":"Step 1: 6 + 8 + 6 = 20.\nStep 2: The original data contains 20 observations.\nStep 3: The totals agree.","steps":["Step 1: 6 + 8 + 6 = 20.","Step 2: The original data contains 20 observations.","Step 3: The totals agree."],"options":[],"conceptId":"math_statistics_checking_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Checking a Frequency Table"}', 0),
  (691, 199, 'A data set contains 30 observations. A table has frequencies 9, 8 and 11. Is the table consistent with the total number of observations?', 'text', 1, 'Add 9, 8 and 11.', '{"why":"The frequencies do not add to the original total of 30.","sol":"Step 1: 9 + 8 = 17.\nStep 2: 17 + 11 = 28.\nStep 3: The table represents 28 observations, not 30.","steps":["Step 1: 9 + 8 = 17.","Step 2: 17 + 11 = 28.","Step 3: The table represents 28 observations, not 30."],"options":[],"conceptId":"math_statistics_checking_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Checking a Frequency Table"}', 1),
  (692, 199, 'A frequency table represents 18 observations and its frequencies are 5, 4, 6 and 3. What should you conclude?', 'text', 1, 'Check the sum.', '{"why":"The frequencies account for all 18 observations.","sol":"Step 1: 5 + 4 = 9.\nStep 2: 9 + 6 = 15.\nStep 3: 15 + 3 = 18.\nStep 4: The total agrees with the original number of observations.","steps":["Step 1: 5 + 4 = 9.","Step 2: 9 + 6 = 15.","Step 3: 15 + 3 = 18.","Step 4: The total agrees with the original number of observations."],"options":[],"conceptId":"math_statistics_checking_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Checking a Frequency Table"}', 2),
  (693, 200, 'A table represents 20 observations. Two frequencies are 6 and 9. Find the missing frequency.', 'text', 1, 'Subtract the known frequencies from the total.', '{"why":"All frequencies together must equal the total number of observations.","sol":"Step 1: Add the known frequencies: 6 + 9 = 15.\nStep 2: The total number of observations is 20.\nStep 3: Missing frequency = 20 - 15.\nStep 4: Therefore, the missing frequency is 5.","steps":["Step 1: Add the known frequencies: 6 + 9 = 15.","Step 2: The total number of observations is 20.","Step 3: Missing frequency = 20 - 15.","Step 4: Therefore, the missing frequency is 5."],"options":[],"conceptId":"math_statistics_finding_a_missing_frequency","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Finding a Missing Frequency"}', 0),
  (694, 200, 'A frequency table represents 30 observations. The known frequencies are 8, 7 and x. Find x.', 'text', 1, 'First find the total of the known frequencies.', '{"why":"The missing frequency must account for all observations not represented by the known frequencies.","sol":"Step 1: 8 + 7 = 15.\nStep 2: The table must contain 30 observations altogether.\nStep 3: x = 30 - 15.\nStep 4: Therefore, x = 15.","steps":["Step 1: 8 + 7 = 15.","Step 2: The table must contain 30 observations altogether.","Step 3: x = 30 - 15.","Step 4: Therefore, x = 15."],"options":[],"conceptId":"math_statistics_finding_a_missing_frequency","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Finding a Missing Frequency"}', 1),
  (695, 200, 'A table has a total frequency of 40. The known frequencies are 12, 9, 7 and x. Find x.', 'text', 1, 'Add the known frequencies first.', '{"why":"The missing frequency is whatever remains after accounting for the known frequencies.","sol":"Step 1: 12 + 9 + 7 = 28.\nStep 2: The total frequency is 40.\nStep 3: x = 40 - 28.\nStep 4: Therefore, x = 12.","steps":["Step 1: 12 + 9 + 7 = 28.","Step 2: The total frequency is 40.","Step 3: x = 40 - 28.","Step 4: Therefore, x = 12."],"options":[],"conceptId":"math_statistics_finding_a_missing_frequency","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Finding a Missing Frequency"}', 2),
  (696, 201, 'A teacher records learners'' ages using the intervals 10–12, 13–15 and 16–18. Is this grouped data?', 'text', 1, 'Are individual ages being listed separately?', '{"why":"Grouped data places observations into classes or intervals.","sol":"Step 1: The ages have been placed into intervals.\nStep 2: The intervals represent groups of possible values.\nStep 3: Therefore, the data is grouped data.","steps":["Step 1: The ages have been placed into intervals.","Step 2: The intervals represent groups of possible values.","Step 3: Therefore, the data is grouped data."],"options":[],"conceptId":"math_statistics_meaning_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Meaning of Grouped Data"}', 0),
  (697, 201, 'Which is grouped data: 12, 13, 14, 15 or 10–12, 13–15?', 'text', 1, 'Look for intervals.', '{"why":"Grouped data organises observations into intervals.","sol":"Step 1: 12, 13, 14, 15 are individual observations.\nStep 2: 10–12 and 13–15 are intervals.\nStep 3: Therefore, 10–12, 13–15 represents grouped data.","steps":["Step 1: 12, 13, 14, 15 are individual observations.","Step 2: 10–12 and 13–15 are intervals.","Step 3: Therefore, 10–12, 13–15 represents grouped data."],"options":[],"conceptId":"math_statistics_meaning_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Meaning of Grouped Data"}', 1),
  (698, 201, 'Why might 500 measurements be grouped into intervals?', 'text', 1, 'Think about making a large data set easier to read.', '{"why":"Grouping makes a large data set easier to handle.","sol":"Step 1: Listing 500 individual measurements can be difficult to read.\nStep 2: Grouping them into intervals summarises the data.\nStep 3: Therefore, grouping makes a large data set easier to organise and interpret.","steps":["Step 1: Listing 500 individual measurements can be difficult to read.","Step 2: Grouping them into intervals summarises the data.","Step 3: Therefore, grouping makes a large data set easier to organise and interpret."],"options":[],"conceptId":"math_statistics_meaning_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Meaning of Grouped Data"}', 2),
  (699, 202, 'Which of the following is a class interval: 17 or 15–19?', 'text', 1, 'A class interval represents a range.', '{"why":"A class interval contains a range of values.","sol":"Step 1: 17 represents one value.\nStep 2: 15–19 represents a range of values.\nStep 3: Therefore, 15–19 is the class interval.","steps":["Step 1: 17 represents one value.","Step 2: 15–19 represents a range of values.","Step 3: Therefore, 15–19 is the class interval."],"options":[],"conceptId":"math_statistics_class_interval","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Class Interval"}', 0),
  (700, 202, 'Which whole-number values are included in the class interval 20–24?', 'text', 1, 'Start at 20 and continue to 24.', '{"why":"The interval includes every whole-number value from 20 to 24.","sol":"Step 1: Start with 20.\nStep 2: Then 21, 22 and 23.\nStep 3: Finally 24.\nStep 4: Therefore, the values are 20, 21, 22, 23 and 24.","steps":["Step 1: Start with 20.","Step 2: Then 21, 22 and 23.","Step 3: Finally 24.","Step 4: Therefore, the values are 20, 21, 22, 23 and 24."],"options":[],"conceptId":"math_statistics_class_interval","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Class Interval"}', 1),
  (701, 202, 'In a table, the class intervals are 5–9, 10–14 and 15–19. Which interval contains the value 13?', 'text', 1, 'Check where 13 falls.', '{"why":"13 lies within the limits 10 and 14.","sol":"Step 1: 13 is greater than or equal to 10.\nStep 2: 13 is less than or equal to 14.\nStep 3: Therefore, 13 belongs to the interval 10–14.","steps":["Step 1: 13 is greater than or equal to 10.","Step 2: 13 is less than or equal to 14.","Step 3: Therefore, 13 belongs to the interval 10–14."],"options":[],"conceptId":"math_statistics_class_interval","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Class Interval"}', 2),
  (702, 203, 'Find the lower and upper class limits of 30–39.', 'text', 1, 'Look at the first and last values.', '{"why":"The class limits are the smallest and largest stated values.","sol":"Step 1: The first value is 30.\nStep 2: The last value is 39.\nStep 3: Therefore, lower limit = 30 and upper limit = 39.","steps":["Step 1: The first value is 30.","Step 2: The last value is 39.","Step 3: Therefore, lower limit = 30 and upper limit = 39."],"options":[],"conceptId":"math_statistics_class_limits","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Class Limits"}', 0),
  (703, 203, 'What is the upper class limit of 50–59?', 'text', 1, 'Look at the last value in the interval.', '{"why":"The upper limit is the largest stated value in the class.","sol":"Step 1: The interval starts at 50.\nStep 2: It ends at 59.\nStep 3: Therefore, the upper class limit is 59.","steps":["Step 1: The interval starts at 50.","Step 2: It ends at 59.","Step 3: Therefore, the upper class limit is 59."],"options":[],"conceptId":"math_statistics_class_limits","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Class Limits"}', 1),
  (704, 203, 'What is the lower class limit of 70–79?', 'text', 1, 'Look at the first value.', '{"why":"The lower limit is the smallest stated value in the class.","sol":"Step 1: The interval begins at 70.\nStep 2: Therefore, the lower class limit is 70.","steps":["Step 1: The interval begins at 70.","Step 2: Therefore, the lower class limit is 70."],"options":[],"conceptId":"math_statistics_class_limits","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Class Limits"}', 2),
  (705, 204, 'Find the class width of 5–9.', 'text', 1, 'Use upper limit − lower limit + 1.', '{"why":"The interval contains the five values 5, 6, 7, 8 and 9.","sol":"Step 1: Upper limit = 9.\nStep 2: Lower limit = 5.\nStep 3: 9 − 5 + 1 = 5.","steps":["Step 1: Upper limit = 9.","Step 2: Lower limit = 5.","Step 3: 9 − 5 + 1 = 5."],"options":[],"conceptId":"math_statistics_class_width","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Class Width"}', 0),
  (706, 204, 'Find the class width of 20–29.', 'text', 1, 'Subtract the lower limit from the upper limit, then add 1.', '{"why":"There are ten whole-number values from 20 through 29.","sol":"Step 1: 29 − 20 = 9.\nStep 2: 9 + 1 = 10.\nStep 3: Therefore, the class width is 10.","steps":["Step 1: 29 − 20 = 9.","Step 2: 9 + 1 = 10.","Step 3: Therefore, the class width is 10."],"options":[],"conceptId":"math_statistics_class_width","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Class Width"}', 1),
  (707, 204, 'A class interval is 50–54. What is its width?', 'text', 1, 'Count the whole-number values or use the formula.', '{"why":"The interval contains 50, 51, 52, 53 and 54.","sol":"Step 1: 54 − 50 + 1 = 5.\nStep 2: Therefore, the class width is 5.","steps":["Step 1: 54 − 50 + 1 = 5.","Step 2: Therefore, the class width is 5."],"options":[],"conceptId":"math_statistics_class_width","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Class Width"}', 2),
  (708, 205, 'Do the intervals 10–19 and 20–29 overlap?', 'text', 1, 'Check whether they share any whole-number values.', '{"why":"The intervals are separate, so each whole-number observation has one class.","sol":"Step 1: The first interval ends at 19.\nStep 2: The second begins at 20.\nStep 3: They share no values.","steps":["Step 1: The first interval ends at 19.","Step 2: The second begins at 20.","Step 3: They share no values."],"options":[],"conceptId":"math_statistics_non_overlapping_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Non-Overlapping Class Intervals"}', 0),
  (709, 205, 'Why is 10–20 and 20–30 a poor choice for whole-number classes?', 'text', 1, 'Think about the value 20.', '{"why":"An observation should not have two possible classes.","sol":"Step 1: 20 is included in 10–20.\nStep 2: 20 is also included in 20–30.\nStep 3: Therefore, the value 20 has two possible classes.","steps":["Step 1: 20 is included in 10–20.","Step 2: 20 is also included in 20–30.","Step 3: Therefore, the value 20 has two possible classes."],"options":[],"conceptId":"math_statistics_non_overlapping_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Non-Overlapping Class Intervals"}', 1),
  (710, 205, 'Which set is better for whole-number data: 30–39, 40–49 or 30–40, 40–50?', 'text', 1, 'Look for an overlapping boundary.', '{"why":"The classes do not overlap.","sol":"Step 1: 30–39 and 40–49 do not share a value.\nStep 2: 30–40 and 40–50 both contain 40.\nStep 3: Therefore, 30–39 and 40–49 is the better set.","steps":["Step 1: 30–39 and 40–49 do not share a value.","Step 2: 30–40 and 40–50 both contain 40.","Step 3: Therefore, 30–39 and 40–49 is the better set."],"options":[],"conceptId":"math_statistics_non_overlapping_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Non-Overlapping Class Intervals"}', 2),
  (711, 206, 'Find the boundary between the classes 20–29 and 30–39.', 'text', 1, 'Find the midpoint between 29 and 30.', '{"why":"29.5 is halfway between 29 and 30 and forms the common boundary.","sol":"Step 1: The upper limit of the first class is 29.\nStep 2: The lower limit of the next class is 30.\nStep 3: Find their midpoint: (29 + 30) ÷ 2.\nStep 4: 59 ÷ 2 = 29.5.","steps":["Step 1: The upper limit of the first class is 29.","Step 2: The lower limit of the next class is 30.","Step 3: Find their midpoint: (29 + 30) ÷ 2.","Step 4: 59 ÷ 2 = 29.5."],"options":[],"conceptId":"math_statistics_class_boundaries","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Class Boundaries"}', 0),
  (712, 206, 'What are the boundaries of the class 40–49?', 'text', 1, 'Move 0.5 below 40 and 0.5 above 49.', '{"why":"The boundaries extend halfway to the neighbouring whole-number values.","sol":"Step 1: The lower boundary is 40 − 0.5 = 39.5.\nStep 2: The upper boundary is 49 + 0.5 = 49.5.","steps":["Step 1: The lower boundary is 40 − 0.5 = 39.5.","Step 2: The upper boundary is 49 + 0.5 = 49.5."],"options":[],"conceptId":"math_statistics_class_boundaries","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Class Boundaries"}', 1),
  (713, 206, 'What is the difference between the class limit 29 and the boundary 29.5?', 'text', 1, 'One is an included whole-number value; the other separates classes.', '{"why":"Limits describe the stated values in a class, while boundaries separate continuous classes.","sol":"Step 1: 29 is the upper class limit of a whole-number class.\nStep 2: 29.5 is the boundary between that class and the next class.\nStep 3: Therefore, they have different roles.","steps":["Step 1: 29 is the upper class limit of a whole-number class.","Step 2: 29.5 is the boundary between that class and the next class.","Step 3: Therefore, they have different roles."],"options":[],"conceptId":"math_statistics_class_boundaries","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Class Boundaries"}', 2),
  (714, 207, 'The data ranges from 14 to 46. Using a class width of 10, which set of intervals can cover all the data?', 'text', 1, 'Start at a convenient value below 14.', '{"why":"These intervals cover the entire data range without overlapping.","sol":"Step 1: Start with 10–19.\nStep 2: Continue with 20–29.\nStep 3: Continue with 30–39.\nStep 4: Continue with 40–49.\nStep 5: The smallest value 14 and largest value 46 are both covered.","steps":["Step 1: Start with 10–19.","Step 2: Continue with 20–29.","Step 3: Continue with 30–39.","Step 4: Continue with 40–49.","Step 5: The smallest value 14 and largest value 46 are both covered."],"options":[],"conceptId":"math_statistics_constructing_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Constructing Class Intervals"}', 0),
  (715, 207, 'The data ranges from 31 to 68. Give class intervals of width 10 that cover the data.', 'text', 1, 'Start with an interval containing 31.', '{"why":"The intervals cover every value from 31 through 68.","sol":"Step 1: 31 belongs to 30–39.\nStep 2: Continue with 40–49.\nStep 3: Then 50–59.\nStep 4: Then 60–69.\nStep 5: The largest value 68 is included.","steps":["Step 1: 31 belongs to 30–39.","Step 2: Continue with 40–49.","Step 3: Then 50–59.","Step 4: Then 60–69.","Step 5: The largest value 68 is included."],"options":[],"conceptId":"math_statistics_constructing_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Constructing Class Intervals"}', 1),
  (716, 207, 'Why would 10–19, 20–29 and 30–39 be unsuitable for data containing the value 45?', 'text', 1, 'Check whether 45 belongs to any class.', '{"why":"Class intervals must cover every observation in the data set.","sol":"Step 1: 45 is greater than 39.\nStep 2: The last class ends at 39.\nStep 3: Therefore, 45 is not covered.\nStep 4: Another class must be added.","steps":["Step 1: 45 is greater than 39.","Step 2: The last class ends at 39.","Step 3: Therefore, 45 is not covered.","Step 4: Another class must be added."],"options":[],"conceptId":"math_statistics_constructing_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Constructing Class Intervals"}', 2),
  (717, 208, 'Find the midpoint of 10–19.', 'text', 1, 'Add the limits and divide by 2.', '{"why":"The midpoint is halfway between the two class limits.","sol":"Step 1: 10 + 19 = 29.\nStep 2: 29 ÷ 2 = 14.5.","steps":["Step 1: 10 + 19 = 29.","Step 2: 29 ÷ 2 = 14.5."],"options":[],"conceptId":"math_statistics_class_midpoint","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Class Midpoint"}', 0),
  (718, 208, 'Find the midpoint of 30–39.', 'text', 1, 'Use (lower limit + upper limit) ÷ 2.', '{"why":"34.5 is exactly halfway between 30 and 39.","sol":"Step 1: 30 + 39 = 69.\nStep 2: 69 ÷ 2 = 34.5.","steps":["Step 1: 30 + 39 = 69.","Step 2: 69 ÷ 2 = 34.5."],"options":[],"conceptId":"math_statistics_class_midpoint","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Class Midpoint"}', 1),
  (719, 208, 'Find the midpoint of 50–59.', 'text', 1, 'Add 50 and 59, then divide by 2.', '{"why":"The midpoint is the centre of the class interval.","sol":"Step 1: 50 + 59 = 109.\nStep 2: 109 ÷ 2 = 54.5.","steps":["Step 1: 50 + 59 = 109.","Step 2: 109 ÷ 2 = 54.5."],"options":[],"conceptId":"math_statistics_class_midpoint","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Class Midpoint"}', 2),
  (720, 209, 'The frequencies are 3, 5 and 4. Find the cumulative frequencies.', 'text', 1, 'Keep adding each new frequency to the previous total.', '{"why":"Each cumulative frequency includes all frequencies up to that point.","sol":"Step 1: First cumulative frequency = 3.\nStep 2: Second = 3 + 5 = 8.\nStep 3: Third = 8 + 4 = 12.","steps":["Step 1: First cumulative frequency = 3.","Step 2: Second = 3 + 5 = 8.","Step 3: Third = 8 + 4 = 12."],"options":[],"conceptId":"math_statistics_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Cumulative Frequency"}', 0),
  (721, 209, 'A frequency is 6 and the previous cumulative frequency is 9. What is the new cumulative frequency?', 'text', 1, 'Add the new frequency to the previous total.', '{"why":"Cumulative frequency is obtained by adding the current frequency to the previous running total.","sol":"Step 1: Previous cumulative frequency = 9.\nStep 2: New frequency = 6.\nStep 3: 9 + 6 = 15.","steps":["Step 1: Previous cumulative frequency = 9.","Step 2: New frequency = 6.","Step 3: 9 + 6 = 15."],"options":[],"conceptId":"math_statistics_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Cumulative Frequency"}', 1),
  (722, 209, 'A table has frequencies 2, 4, 7 and 3. What is the final cumulative frequency?', 'text', 1, 'The final cumulative frequency equals the total frequency.', '{"why":"The final cumulative frequency represents all observations in the table.","sol":"Step 1: 2 + 4 = 6.\nStep 2: 6 + 7 = 13.\nStep 3: 13 + 3 = 16.","steps":["Step 1: 2 + 4 = 6.","Step 2: 6 + 7 = 13.","Step 3: 13 + 3 = 16."],"options":[],"conceptId":"math_statistics_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Cumulative Frequency"}', 2),
  (723, 210, 'A table shows that the cumulative frequency at value 4 is 11. What does 11 mean?', 'text', 1, 'Think ''up to and including''.', '{"why":"Cumulative frequency is the running total up to that value.","sol":"Step 1: Cumulative frequency includes all frequencies before this value.\nStep 2: It also includes the frequency at value 4.\nStep 3: Therefore, 11 observations have values up to and including 4.","steps":["Step 1: Cumulative frequency includes all frequencies before this value.","Step 2: It also includes the frequency at value 4.","Step 3: Therefore, 11 observations have values up to and including 4."],"options":[],"conceptId":"math_statistics_reading_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Reading Cumulative Frequency"}', 0),
  (724, 210, 'The cumulative frequency at 20 is 18. What does this tell you?', 'text', 1, 'Translate the cumulative frequency into words.', '{"why":"Cumulative frequency represents the number of observations accumulated so far.","sol":"Step 1: The cumulative frequency is 18.\nStep 2: It counts all observations up to and including 20.\nStep 3: Therefore, 18 observations have values up to and including 20.","steps":["Step 1: The cumulative frequency is 18.","Step 2: It counts all observations up to and including 20.","Step 3: Therefore, 18 observations have values up to and including 20."],"options":[],"conceptId":"math_statistics_reading_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Reading Cumulative Frequency"}', 1),
  (725, 210, 'A table has cumulative frequencies 4, 9, 15 and 20. What is the total number of observations?', 'text', 1, 'Look at the final cumulative frequency.', '{"why":"The final cumulative frequency equals the total frequency.","sol":"Step 1: The final cumulative frequency includes every observation.\nStep 2: The final value is 20.\nStep 3: Therefore, there are 20 observations altogether.","steps":["Step 1: The final cumulative frequency includes every observation.","Step 2: The final value is 20.","Step 3: Therefore, there are 20 observations altogether."],"options":[],"conceptId":"math_statistics_reading_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Reading Cumulative Frequency"}', 2),
  (726, 211, 'Find the mean of 4, 6 and 8.', 'text', 1, 'Add the three values, then divide by 3.', '{"why":"The mean is the total shared equally among the three observations.","sol":"Step 1: 4 + 6 + 8 = 18.\nStep 2: There are 3 values.\nStep 3: Mean = 18 ÷ 3.\nStep 4: Mean = 6.","steps":["Step 1: 4 + 6 + 8 = 18.","Step 2: There are 3 values.","Step 3: Mean = 18 ÷ 3.","Step 4: Mean = 6."],"options":[],"conceptId":"math_statistics_31_meaning_of_the_mean","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"31. Meaning of the Mean"}', 0),
  (727, 211, 'Find the mean of 5, 7, 9 and 11.', 'text', 1, 'Find the total first.', '{"why":"The total of 32 is shared equally among 4 observations.","sol":"Step 1: 5 + 7 + 9 + 11 = 32.\nStep 2: There are 4 values.\nStep 3: Mean = 32 ÷ 4.\nStep 4: Mean = 8.","steps":["Step 1: 5 + 7 + 9 + 11 = 32.","Step 2: There are 4 values.","Step 3: Mean = 32 ÷ 4.","Step 4: Mean = 8."],"options":[],"conceptId":"math_statistics_31_meaning_of_the_mean","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"31. Meaning of the Mean"}', 1),
  (728, 211, 'Find the mean of 2, 6, 8, 9 and 10.', 'text', 1, 'Add all five values and divide by 5.', '{"why":"The mean represents the equal share of the total 35 among 5 observations.","sol":"Step 1: 2 + 6 + 8 + 9 + 10 = 35.\nStep 2: There are 5 values.\nStep 3: Mean = 35 ÷ 5.\nStep 4: Mean = 7.","steps":["Step 1: 2 + 6 + 8 + 9 + 10 = 35.","Step 2: There are 5 values.","Step 3: Mean = 35 ÷ 5.","Step 4: Mean = 7."],"options":[],"conceptId":"math_statistics_31_meaning_of_the_mean","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"31. Meaning of the Mean"}', 2),
  (729, 212, 'Find the mean of 8, 10, 12 and 14.', 'text', 1, 'There are 4 values.', '{"why":"The mean is the total divided by the number of observations.","sol":"Step 1: 8 + 10 + 12 + 14 = 44.\nStep 2: There are 4 observations.\nStep 3: Mean = 44 ÷ 4.\nStep 4: Mean = 11.","steps":["Step 1: 8 + 10 + 12 + 14 = 44.","Step 2: There are 4 observations.","Step 3: Mean = 44 ÷ 4.","Step 4: Mean = 11."],"options":[],"conceptId":"math_statistics_32_finding_mean_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"32. Finding Mean from Raw Data"}', 0),
  (730, 212, 'Find the mean of 5, 7, 12, 16 and 20.', 'text', 1, 'Add all five values before dividing by 5.', '{"why":"The five values have a total of 60, so each would receive 12 if the total were shared equally.","sol":"Step 1: 5 + 7 + 12 + 16 + 20 = 60.\nStep 2: There are 5 observations.\nStep 3: Mean = 60 ÷ 5.\nStep 4: Mean = 12.","steps":["Step 1: 5 + 7 + 12 + 16 + 20 = 60.","Step 2: There are 5 observations.","Step 3: Mean = 60 ÷ 5.","Step 4: Mean = 12."],"options":[],"conceptId":"math_statistics_32_finding_mean_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"32. Finding Mean from Raw Data"}', 1),
  (731, 212, 'The numbers of books read by four learners are 3, 5, 6 and 10. Find the mean.', 'text', 1, 'The number of observations is 4.', '{"why":"The total of 24 books is shared equally among 4 learners.","sol":"Step 1: 3 + 5 + 6 + 10 = 24.\nStep 2: There are 4 learners.\nStep 3: Mean = 24 ÷ 4.\nStep 4: Mean = 6.","steps":["Step 1: 3 + 5 + 6 + 10 = 24.","Step 2: There are 4 learners.","Step 3: Mean = 24 ÷ 4.","Step 4: Mean = 6."],"options":[],"conceptId":"math_statistics_32_finding_mean_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"32. Finding Mean from Raw Data"}', 2),
  (732, 213, 'The total of 5 observations is 40. Find the mean.', 'text', 1, 'Divide the total by 5.', '{"why":"The total 40 is divided into 5 equal shares.","sol":"Step 1: Total = 40.\nStep 2: Number of observations = 5.\nStep 3: Mean = 40 ÷ 5.\nStep 4: Mean = 8.","steps":["Step 1: Total = 40.","Step 2: Number of observations = 5.","Step 3: Mean = 40 ÷ 5.","Step 4: Mean = 8."],"options":[],"conceptId":"math_statistics_33_why_we_divide_by_the_number_of_values","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"33. Why We Divide by the Number of Values"}', 0),
  (733, 213, 'The total of 8 values is 64. Find the mean.', 'text', 1, 'Use total ÷ number of observations.', '{"why":"There are 8 observations, so the total is divided into 8 equal shares.","sol":"Step 1: Total = 64.\nStep 2: Number of observations = 8.\nStep 3: Mean = 64 ÷ 8.\nStep 4: Mean = 8.","steps":["Step 1: Total = 64.","Step 2: Number of observations = 8.","Step 3: Mean = 64 ÷ 8.","Step 4: Mean = 8."],"options":[],"conceptId":"math_statistics_33_why_we_divide_by_the_number_of_values","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"33. Why We Divide by the Number of Values"}', 1),
  (734, 213, 'A learner has four test scores with a total of 70. What is the mean score?', 'text', 1, 'There are 4 test scores.', '{"why":"The total score is shared equally across the four tests.","sol":"Step 1: Total score = 70.\nStep 2: Number of scores = 4.\nStep 3: Mean = 70 ÷ 4.\nStep 4: Mean = 17.5.","steps":["Step 1: Total score = 70.","Step 2: Number of scores = 4.","Step 3: Mean = 70 ÷ 4.","Step 4: Mean = 17.5."],"options":[],"conceptId":"math_statistics_33_why_we_divide_by_the_number_of_values","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"33. Why We Divide by the Number of Values"}', 2),
  (735, 214, 'Find the mean from this table: x = 2, 4 and f = 2, 1 respectively.', 'text', 1, 'The data is 2, 2, 4.', '{"why":"Frequency tells us how many times each value contributes to the total.","sol":"Step 1: The value 2 occurs twice: 2 + 2 = 4.\nStep 2: The value 4 occurs once: 4.\nStep 3: Total = 4 + 4 = 8.\nStep 4: Total frequency = 2 + 1 = 3.\nStep 5: Mean = 8 ÷ 3 = 2.67 approximately.","steps":["Step 1: The value 2 occurs twice: 2 + 2 = 4.","Step 2: The value 4 occurs once: 4.","Step 3: Total = 4 + 4 = 8.","Step 4: Total frequency = 2 + 1 = 3.","Step 5: Mean = 8 ÷ 3 = 2.67 approximately."],"options":[],"conceptId":"math_statistics_34_mean_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"34. Mean from an Ungrouped Frequency Table"}', 0),
  (736, 214, 'Find the mean when x = 3, 5 and f = 2, 3 respectively.', 'text', 1, 'Expand the frequencies first.', '{"why":"There are five observations altogether, so the total is divided by five.","sol":"Step 1: 3 occurs twice: 3 + 3 = 6.\nStep 2: 5 occurs three times: 5 + 5 + 5 = 15.\nStep 3: Total = 21.\nStep 4: Total frequency = 2 + 3 = 5.\nStep 5: Mean = 21 ÷ 5 = 4.2.","steps":["Step 1: 3 occurs twice: 3 + 3 = 6.","Step 2: 5 occurs three times: 5 + 5 + 5 = 15.","Step 3: Total = 21.","Step 4: Total frequency = 2 + 3 = 5.","Step 5: Mean = 21 ÷ 5 = 4.2."],"options":[],"conceptId":"math_statistics_34_mean_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"34. Mean from an Ungrouped Frequency Table"}', 1),
  (737, 214, 'Find the mean when x = 4, 6 and f = 1, 4 respectively.', 'text', 1, 'The value 6 occurs four times.', '{"why":"The frequency determines how many observations are represented by each value.","sol":"Step 1: 4 occurs once: 4.\nStep 2: 6 occurs four times: 6 + 6 + 6 + 6 = 24.\nStep 3: Total = 4 + 24 = 28.\nStep 4: Total frequency = 1 + 4 = 5.\nStep 5: Mean = 28 ÷ 5 = 5.6.","steps":["Step 1: 4 occurs once: 4.","Step 2: 6 occurs four times: 6 + 6 + 6 + 6 = 24.","Step 3: Total = 4 + 24 = 28.","Step 4: Total frequency = 1 + 4 = 5.","Step 5: Mean = 28 ÷ 5 = 5.6."],"options":[],"conceptId":"math_statistics_34_mean_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"34. Mean from an Ungrouped Frequency Table"}', 2),
  (738, 215, 'Find fx when x = 6 and f = 4.', 'text', 1, 'Use fx = f × x.', '{"why":"Four observations of 6 contribute 24 altogether.","sol":"Step 1: f = 4.\nStep 2: x = 6.\nStep 3: fx = 4 × 6.\nStep 4: fx = 24.","steps":["Step 1: f = 4.","Step 2: x = 6.","Step 3: fx = 4 × 6.","Step 4: fx = 24."],"options":[],"conceptId":"math_statistics_35_understanding_fx","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"35. Understanding fx"}', 0),
  (739, 215, 'Find fx when x = 9 and f = 5.', 'text', 1, 'Multiply 9 by 5.', '{"why":"Five occurrences of 9 have a combined total of 45.","sol":"Step 1: f = 5.\nStep 2: x = 9.\nStep 3: fx = 5 × 9.\nStep 4: fx = 45.","steps":["Step 1: f = 5.","Step 2: x = 9.","Step 3: fx = 5 × 9.","Step 4: fx = 45."],"options":[],"conceptId":"math_statistics_35_understanding_fx","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"35. Understanding fx"}', 1),
  (740, 215, 'For x = 4, 7 and f = 3, 2 respectively, find the two fx values.', 'text', 1, 'Multiply each x by its corresponding frequency.', '{"why":"Each value must be multiplied by its own frequency.","sol":"Step 1: For x = 4 and f = 3: fx = 3 × 4 = 12.\nStep 2: For x = 7 and f = 2: fx = 2 × 7 = 14.","steps":["Step 1: For x = 4 and f = 3: fx = 3 × 4 = 12.","Step 2: For x = 7 and f = 2: fx = 2 × 7 = 14."],"options":[],"conceptId":"math_statistics_35_understanding_fx","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"35. Understanding fx"}', 2),
  (741, 216, 'Find the mean from x = 2, 4 and f = 3, 2 respectively.', 'text', 1, 'Calculate fx first.', '{"why":"The formula divides the total represented value by the total number of observations.","sol":"Step 1: For x = 2: fx = 2 × 3 = 6.\nStep 2: For x = 4: fx = 4 × 2 = 8.\nStep 3: Σfx = 6 + 8 = 14.\nStep 4: Σf = 3 + 2 = 5.\nStep 5: Mean = 14 ÷ 5 = 2.8.","steps":["Step 1: For x = 2: fx = 2 × 3 = 6.","Step 2: For x = 4: fx = 4 × 2 = 8.","Step 3: Σfx = 6 + 8 = 14.","Step 4: Σf = 3 + 2 = 5.","Step 5: Mean = 14 ÷ 5 = 2.8."],"options":[],"conceptId":"math_statistics_36_finding_mean_using_fx_f","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"36. Finding Mean Using Σfx ÷ Σf"}', 0),
  (742, 216, 'Find the mean from x = 5, 10, 15 and f = 2, 3, 1 respectively.', 'text', 1, 'Find all three fx values.', '{"why":"The total represented value is 55 and there are 6 observations.","sol":"Step 1: 5 × 2 = 10.\nStep 2: 10 × 3 = 30.\nStep 3: 15 × 1 = 15.\nStep 4: Σfx = 10 + 30 + 15 = 55.\nStep 5: Σf = 2 + 3 + 1 = 6.\nStep 6: Mean = 55 ÷ 6 = 9.17 approximately.","steps":["Step 1: 5 × 2 = 10.","Step 2: 10 × 3 = 30.","Step 3: 15 × 1 = 15.","Step 4: Σfx = 10 + 30 + 15 = 55.","Step 5: Σf = 2 + 3 + 1 = 6.","Step 6: Mean = 55 ÷ 6 = 9.17 approximately."],"options":[],"conceptId":"math_statistics_36_finding_mean_using_fx_f","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"36. Finding Mean Using Σfx ÷ Σf"}', 1),
  (743, 216, 'Find the mean from x = 4, 8 and f = 5, 5 respectively.', 'text', 1, 'The total frequency is 10.', '{"why":"There are 10 observations whose combined value is 60.","sol":"Step 1: 4 × 5 = 20.\nStep 2: 8 × 5 = 40.\nStep 3: Σfx = 20 + 40 = 60.\nStep 4: Σf = 5 + 5 = 10.\nStep 5: Mean = 60 ÷ 10 = 6.","steps":["Step 1: 4 × 5 = 20.","Step 2: 8 × 5 = 40.","Step 3: Σfx = 20 + 40 = 60.","Step 4: Σf = 5 + 5 = 10.","Step 5: Mean = 60 ÷ 10 = 6."],"options":[],"conceptId":"math_statistics_36_finding_mean_using_fx_f","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"36. Finding Mean Using Σfx ÷ Σf"}', 2),
  (744, 217, 'Find the estimated mean for classes 0–9 and 10–19 with frequencies 2 and 3 respectively.', 'text', 1, 'First find the two midpoints.', '{"why":"Each class is represented by its midpoint because the individual observations inside the class are unknown.","sol":"Step 1: Midpoint of 0–9 = (0 + 9) ÷ 2 = 4.5.\nStep 2: Midpoint of 10–19 = (10 + 19) ÷ 2 = 14.5.\nStep 3: fx values are 4.5 × 2 = 9 and 14.5 × 3 = 43.5.\nStep 4: Σfx = 52.5.\nStep 5: Σf = 5.\nStep 6: Mean = 52.5 ÷ 5 = 10.5.","steps":["Step 1: Midpoint of 0–9 = (0 + 9) ÷ 2 = 4.5.","Step 2: Midpoint of 10–19 = (10 + 19) ÷ 2 = 14.5.","Step 3: fx values are 4.5 × 2 = 9 and 14.5 × 3 = 43.5.","Step 4: Σfx = 52.5.","Step 5: Σf = 5.","Step 6: Mean = 52.5 ÷ 5 = 10.5."],"options":[],"conceptId":"math_statistics_37_finding_mean_from_a_grouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"37. Finding Mean from a Grouped Frequency Table"}', 0),
  (745, 217, 'Find the estimated mean for classes 10–19, 20–29 with frequencies 2 and 4 respectively.', 'text', 1, 'Use midpoints 14.5 and 24.5.', '{"why":"The midpoint represents each class when calculating the estimated grouped mean.","sol":"Step 1: Midpoint of 10–19 = 14.5.\nStep 2: Midpoint of 20–29 = 24.5.\nStep 3: 14.5 × 2 = 29.\nStep 4: 24.5 × 4 = 98.\nStep 5: Σfx = 127.\nStep 6: Σf = 6.\nStep 7: Mean = 127 ÷ 6 = 21.17 approximately.","steps":["Step 1: Midpoint of 10–19 = 14.5.","Step 2: Midpoint of 20–29 = 24.5.","Step 3: 14.5 × 2 = 29.","Step 4: 24.5 × 4 = 98.","Step 5: Σfx = 127.","Step 6: Σf = 6.","Step 7: Mean = 127 ÷ 6 = 21.17 approximately."],"options":[],"conceptId":"math_statistics_37_finding_mean_from_a_grouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"37. Finding Mean from a Grouped Frequency Table"}', 1),
  (746, 217, 'Find the estimated mean for classes 20–29, 30–39 with frequencies 3 and 2 respectively.', 'text', 1, 'Find the midpoint of each class first.', '{"why":"The grouped mean is calculated from the representative midpoint of each class.","sol":"Step 1: Midpoint of 20–29 = 24.5.\nStep 2: Midpoint of 30–39 = 34.5.\nStep 3: 24.5 × 3 = 73.5.\nStep 4: 34.5 × 2 = 69.\nStep 5: Σfx = 142.5.\nStep 6: Σf = 5.\nStep 7: Mean = 142.5 ÷ 5 = 28.5.","steps":["Step 1: Midpoint of 20–29 = 24.5.","Step 2: Midpoint of 30–39 = 34.5.","Step 3: 24.5 × 3 = 73.5.","Step 4: 34.5 × 2 = 69.","Step 5: Σfx = 142.5.","Step 6: Σf = 5.","Step 7: Mean = 142.5 ÷ 5 = 28.5."],"options":[],"conceptId":"math_statistics_37_finding_mean_from_a_grouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"37. Finding Mean from a Grouped Frequency Table"}', 2),
  (747, 218, 'Find the midpoint of the class 5–14.', 'text', 1, 'Add the two class limits and divide by 2.', '{"why":"The midpoint is the central value between the two class limits.","sol":"Step 1: Lower limit = 5.\nStep 2: Upper limit = 14.\nStep 3: Midpoint = (5 + 14) ÷ 2.\nStep 4: Midpoint = 19 ÷ 2 = 9.5.","steps":["Step 1: Lower limit = 5.","Step 2: Upper limit = 14.","Step 3: Midpoint = (5 + 14) ÷ 2.","Step 4: Midpoint = 19 ÷ 2 = 9.5."],"options":[],"conceptId":"math_statistics_38_why_midpoints_are_used_for_grouped_mean","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"38. Why Midpoints Are Used for Grouped Mean"}', 0),
  (748, 218, 'Find the midpoint of 40–49.', 'text', 1, 'Use (lower limit + upper limit) ÷ 2.', '{"why":"44.5 is halfway between 40 and 49.","sol":"Step 1: 40 + 49 = 89.\nStep 2: 89 ÷ 2 = 44.5.\nStep 3: Therefore the midpoint is 44.5.","steps":["Step 1: 40 + 49 = 89.","Step 2: 89 ÷ 2 = 44.5.","Step 3: Therefore the midpoint is 44.5."],"options":[],"conceptId":"math_statistics_38_why_midpoints_are_used_for_grouped_mean","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"38. Why Midpoints Are Used for Grouped Mean"}', 1),
  (749, 218, 'Why is 24.5 used as the midpoint of the class 20–29?', 'text', 1, 'Calculate the midpoint.', '{"why":"24.5 is halfway between the lower and upper class limits.","sol":"Step 1: Lower limit = 20.\nStep 2: Upper limit = 29.\nStep 3: Midpoint = (20 + 29) ÷ 2.\nStep 4: Midpoint = 49 ÷ 2 = 24.5.","steps":["Step 1: Lower limit = 20.","Step 2: Upper limit = 29.","Step 3: Midpoint = (20 + 29) ÷ 2.","Step 4: Midpoint = 49 ÷ 2 = 24.5."],"options":[],"conceptId":"math_statistics_38_why_midpoints_are_used_for_grouped_mean","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"38. Why Midpoints Are Used for Grouped Mean"}', 2),
  (750, 219, 'The mean of 5, 7 and x is 9. Find x.', 'text', 1, 'Required total = 9 × 3.', '{"why":"The three values must have a total of 27 for their mean to be 9.","sol":"Step 1: Required total = 9 × 3 = 27.\nStep 2: Known total = 5 + 7 = 12.\nStep 3: x = 27 − 12.\nStep 4: x = 15.\nStep 5: Check: (5 + 7 + 15) ÷ 3 = 27 ÷ 3 = 9.","steps":["Step 1: Required total = 9 × 3 = 27.","Step 2: Known total = 5 + 7 = 12.","Step 3: x = 27 − 12.","Step 4: x = 15.","Step 5: Check: (5 + 7 + 15) ÷ 3 = 27 ÷ 3 = 9."],"options":[],"conceptId":"math_statistics_39_finding_a_missing_value_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"39. Finding a Missing Value from a Known Mean"}', 0);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (751, 219, 'The mean of four numbers is 10. Three numbers are 6, 11 and 8. Find the fourth number.', 'text', 1, 'First find the required total.', '{"why":"A mean of 10 for four values requires a total of 40.","sol":"Step 1: Required total = 10 × 4 = 40.\nStep 2: Known total = 6 + 11 + 8 = 25.\nStep 3: Missing value = 40 − 25.\nStep 4: Missing value = 15.","steps":["Step 1: Required total = 10 × 4 = 40.","Step 2: Known total = 6 + 11 + 8 = 25.","Step 3: Missing value = 40 − 25.","Step 4: Missing value = 15."],"options":[],"conceptId":"math_statistics_39_finding_a_missing_value_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"39. Finding a Missing Value from a Known Mean"}', 1),
  (752, 219, 'The mean of six numbers is 14. Five numbers are 10, 12, 15, 16 and 13. Find the missing number.', 'text', 1, 'Required total = 14 × 6.', '{"why":"The six values must total 84 to have a mean of 14.","sol":"Step 1: Required total = 14 × 6 = 84.\nStep 2: Known total = 10 + 12 + 15 + 16 + 13 = 66.\nStep 3: Missing value = 84 − 66.\nStep 4: Missing value = 18.","steps":["Step 1: Required total = 14 × 6 = 84.","Step 2: Known total = 10 + 12 + 15 + 16 + 13 = 66.","Step 3: Missing value = 84 − 66.","Step 4: Missing value = 18."],"options":[],"conceptId":"math_statistics_39_finding_a_missing_value_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"39. Finding a Missing Value from a Known Mean"}', 2),
  (753, 220, 'A table has x = 2 with frequency 1 and x = 6 with frequency f. The mean is 4. Find f.', 'text', 1, 'Use 4 = (2 + 6f) ÷ (1 + f).', '{"why":"The missing frequency must make the weighted mean equal to 4.","sol":"Step 1: 4 = (2 + 6f) ÷ (1 + f).\nStep 2: 4(1 + f) = 2 + 6f.\nStep 3: 4 + 4f = 2 + 6f.\nStep 4: 2 = 2f.\nStep 5: f = 1.","steps":["Step 1: 4 = (2 + 6f) ÷ (1 + f).","Step 2: 4(1 + f) = 2 + 6f.","Step 3: 4 + 4f = 2 + 6f.","Step 4: 2 = 2f.","Step 5: f = 1."],"options":[],"conceptId":"math_statistics_40_finding_a_missing_frequency_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"40. Finding a Missing Frequency from a Known Mean"}', 0),
  (754, 220, 'A table has x = 3 with frequency 2 and x = 7 with frequency f. The mean is 5. Find f.', 'text', 1, 'Write the weighted mean equation first.', '{"why":"A frequency of 2 makes the weighted mean equal to 5.","sol":"Step 1: Σfx = 3 × 2 + 7f = 6 + 7f.\nStep 2: Σf = 2 + f.\nStep 3: 5 = (6 + 7f) ÷ (2 + f).\nStep 4: 5(2 + f) = 6 + 7f.\nStep 5: 10 + 5f = 6 + 7f.\nStep 6: 4 = 2f.\nStep 7: f = 2.","steps":["Step 1: Σfx = 3 × 2 + 7f = 6 + 7f.","Step 2: Σf = 2 + f.","Step 3: 5 = (6 + 7f) ÷ (2 + f).","Step 4: 5(2 + f) = 6 + 7f.","Step 5: 10 + 5f = 6 + 7f.","Step 6: 4 = 2f.","Step 7: f = 2."],"options":[],"conceptId":"math_statistics_40_finding_a_missing_frequency_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"40. Finding a Missing Frequency from a Known Mean"}', 1),
  (755, 220, 'A table has x = 2 with frequency 3 and x = 8 with frequency f. The mean is 5. Find f.', 'text', 1, 'Use Σfx = 6 + 8f and Σf = 3 + f.', '{"why":"Three occurrences of 8 together with three occurrences of 2 produce a mean of 5.","sol":"Step 1: 5 = (6 + 8f) ÷ (3 + f).\nStep 2: 5(3 + f) = 6 + 8f.\nStep 3: 15 + 5f = 6 + 8f.\nStep 4: 9 = 3f.\nStep 5: f = 3.","steps":["Step 1: 5 = (6 + 8f) ÷ (3 + f).","Step 2: 5(3 + f) = 6 + 8f.","Step 3: 15 + 5f = 6 + 8f.","Step 4: 9 = 3f.","Step 5: f = 3."],"options":[],"conceptId":"math_statistics_40_finding_a_missing_frequency_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"40. Finding a Missing Frequency from a Known Mean"}', 2),
  (756, 221, 'Find the median of 4, 9, 2, 7 and 5.', 'text', 1, 'Arrange the values first.', '{"why":"The median is the middle value after ordering the data.","sol":"Step 1: Arrange the data: 2, 4, 5, 7, 9.\nStep 2: There are 5 values.\nStep 3: The middle value is 5.\nStep 4: Median = 5.","steps":["Step 1: Arrange the data: 2, 4, 5, 7, 9.","Step 2: There are 5 values.","Step 3: The middle value is 5.","Step 4: Median = 5."],"options":[],"conceptId":"math_statistics_41_meaning_of_the_median","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"41. Meaning of the Median"}', 0),
  (757, 221, 'Find the median of 11, 3, 8, 5 and 9.', 'text', 1, 'Put the values from smallest to largest.', '{"why":"The third value is the middle of five ordered observations.","sol":"Step 1: Ordered data: 3, 5, 8, 9, 11.\nStep 2: There are 5 values.\nStep 3: The middle value is 8.\nStep 4: Median = 8.","steps":["Step 1: Ordered data: 3, 5, 8, 9, 11.","Step 2: There are 5 values.","Step 3: The middle value is 8.","Step 4: Median = 8."],"options":[],"conceptId":"math_statistics_41_meaning_of_the_median","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"41. Meaning of the Median"}', 1),
  (758, 221, 'Find the median of 2, 7, 4, 10, 6, 9 and 5.', 'text', 1, 'There are 7 observations, so look for the fourth value after ordering.', '{"why":"Six has three observations below it and three above it.","sol":"Step 1: Ordered data: 2, 4, 5, 6, 7, 9, 10.\nStep 2: There are 7 values.\nStep 3: The fourth value is 6.\nStep 4: Median = 6.","steps":["Step 1: Ordered data: 2, 4, 5, 6, 7, 9, 10.","Step 2: There are 7 values.","Step 3: The fourth value is 6.","Step 4: Median = 6."],"options":[],"conceptId":"math_statistics_41_meaning_of_the_median","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"41. Meaning of the Median"}', 2),
  (759, 222, 'A dataset has 5 observations. What is the median position?', 'text', 1, 'Use (n + 1) ÷ 2.', '{"why":"For five ordered observations, the third observation has two values on each side.","sol":"Step 1: n = 5.\nStep 2: Median position = (5 + 1) ÷ 2.\nStep 3: Median position = 3.\nStep 4: Therefore the median is at the 3rd position.","steps":["Step 1: n = 5.","Step 2: Median position = (5 + 1) ÷ 2.","Step 3: Median position = 3.","Step 4: Therefore the median is at the 3rd position."],"options":[],"conceptId":"math_statistics_42_median_of_an_odd_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"42. Median of an Odd-Sized Dataset"}', 0),
  (760, 222, 'Find the median of 8, 2, 10, 5 and 6.', 'text', 1, 'There are 5 observations, so use the 3rd position.', '{"why":"The median is the value occupying the third position in five ordered observations.","sol":"Step 1: n = 5.\nStep 2: Median position = (5 + 1) ÷ 2 = 3rd.\nStep 3: Ordered data: 2, 5, 6, 8, 10.\nStep 4: The 3rd value is 6.\nStep 5: Median = 6.","steps":["Step 1: n = 5.","Step 2: Median position = (5 + 1) ÷ 2 = 3rd.","Step 3: Ordered data: 2, 5, 6, 8, 10.","Step 4: The 3rd value is 6.","Step 5: Median = 6."],"options":[],"conceptId":"math_statistics_42_median_of_an_odd_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"42. Median of an Odd-Sized Dataset"}', 1),
  (761, 222, 'Find the median of 12, 4, 8, 15, 6, 10 and 2.', 'text', 1, 'There are 7 observations, so the median is at the 4th position.', '{"why":"Eight has three ordered observations below it and three above it.","sol":"Step 1: n = 7.\nStep 2: Median position = (7 + 1) ÷ 2 = 4th.\nStep 3: Ordered data: 2, 4, 6, 8, 10, 12, 15.\nStep 4: The 4th value is 8.\nStep 5: Median = 8.","steps":["Step 1: n = 7.","Step 2: Median position = (7 + 1) ÷ 2 = 4th.","Step 3: Ordered data: 2, 4, 6, 8, 10, 12, 15.","Step 4: The 4th value is 8.","Step 5: Median = 8."],"options":[],"conceptId":"math_statistics_42_median_of_an_odd_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"42. Median of an Odd-Sized Dataset"}', 2),
  (762, 223, 'Find the median of 2, 4, 6 and 8.', 'text', 1, 'The two middle values are 4 and 6.', '{"why":"With four observations, the median is the average of the 2nd and 3rd values.","sol":"Step 1: The data is already ordered.\nStep 2: The two middle values are 4 and 6.\nStep 3: Median = (4 + 6) ÷ 2.\nStep 4: Median = 5.","steps":["Step 1: The data is already ordered.","Step 2: The two middle values are 4 and 6.","Step 3: Median = (4 + 6) ÷ 2.","Step 4: Median = 5."],"options":[],"conceptId":"math_statistics_43_median_of_an_even_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"43. Median of an Even-Sized Dataset"}', 0),
  (763, 223, 'Find the median of 3, 10, 7, 5, 2 and 8.', 'text', 1, 'Order the six values first.', '{"why":"The two central observations are 5 and 7, so their average is the median.","sol":"Step 1: Ordered data: 2, 3, 5, 7, 8, 10.\nStep 2: The two middle values are 5 and 7.\nStep 3: Median = (5 + 7) ÷ 2.\nStep 4: Median = 6.","steps":["Step 1: Ordered data: 2, 3, 5, 7, 8, 10.","Step 2: The two middle values are 5 and 7.","Step 3: Median = (5 + 7) ÷ 2.","Step 4: Median = 6."],"options":[],"conceptId":"math_statistics_43_median_of_an_even_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"43. Median of an Even-Sized Dataset"}', 1),
  (764, 223, 'Find the median of 4, 12, 8, 20, 10 and 6.', 'text', 1, 'There are six observations.', '{"why":"For an even-sized dataset, the median lies halfway between the two middle values.","sol":"Step 1: Ordered data: 4, 6, 8, 10, 12, 20.\nStep 2: The two middle values are 8 and 10.\nStep 3: Median = (8 + 10) ÷ 2.\nStep 4: Median = 9.","steps":["Step 1: Ordered data: 4, 6, 8, 10, 12, 20.","Step 2: The two middle values are 8 and 10.","Step 3: Median = (8 + 10) ÷ 2.","Step 4: Median = 9."],"options":[],"conceptId":"math_statistics_43_median_of_an_even_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"43. Median of an Even-Sized Dataset"}', 2),
  (765, 224, 'Find the median from x = 2, 4, 6 with frequencies 2, 3, 2 respectively.', 'text', 1, 'There are 7 observations. Find the 4th position.', '{"why":"The fourth ordered observation is represented by the value 4.","sol":"Step 1: Total frequency = 2 + 3 + 2 = 7.\nStep 2: Median position = (7 + 1) ÷ 2 = 4th.\nStep 3: Cumulative frequencies are 2, 5, 7.\nStep 4: The 4th observation lies at x = 4.\nStep 5: Median = 4.","steps":["Step 1: Total frequency = 2 + 3 + 2 = 7.","Step 2: Median position = (7 + 1) ÷ 2 = 4th.","Step 3: Cumulative frequencies are 2, 5, 7.","Step 4: The 4th observation lies at x = 4.","Step 5: Median = 4."],"options":[],"conceptId":"math_statistics_44_median_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"44. Median from an Ungrouped Frequency Table"}', 0),
  (766, 224, 'Find the median from x = 1, 3, 5 with frequencies 2, 4, 2 respectively.', 'text', 1, 'There are 8 observations, so inspect positions 4 and 5.', '{"why":"Both middle observations fall among the four occurrences of 3.","sol":"Step 1: Total frequency = 2 + 4 + 2 = 8.\nStep 2: Middle positions are 4th and 5th.\nStep 3: Cumulative frequency at x = 1 is 2.\nStep 4: Cumulative frequency at x = 3 is 6.\nStep 5: Therefore both the 4th and 5th observations are 3.\nStep 6: Median = 3.","steps":["Step 1: Total frequency = 2 + 4 + 2 = 8.","Step 2: Middle positions are 4th and 5th.","Step 3: Cumulative frequency at x = 1 is 2.","Step 4: Cumulative frequency at x = 3 is 6.","Step 5: Therefore both the 4th and 5th observations are 3.","Step 6: Median = 3."],"options":[],"conceptId":"math_statistics_44_median_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"44. Median from an Ungrouped Frequency Table"}', 1),
  (767, 224, 'Find the median from x = 10, 20, 30, 40 with frequencies 1, 2, 4, 2 respectively.', 'text', 1, 'There are 9 observations, so find the 5th position.', '{"why":"The cumulative frequency reaches 7 at 30, so the fifth observation is 30.","sol":"Step 1: Total frequency = 1 + 2 + 4 + 2 = 9.\nStep 2: Median position = (9 + 1) ÷ 2 = 5th.\nStep 3: Cumulative frequencies are 1, 3, 7, 9.\nStep 4: The 5th observation falls at x = 30.\nStep 5: Median = 30.","steps":["Step 1: Total frequency = 1 + 2 + 4 + 2 = 9.","Step 2: Median position = (9 + 1) ÷ 2 = 5th.","Step 3: Cumulative frequencies are 1, 3, 7, 9.","Step 4: The 5th observation falls at x = 30.","Step 5: Median = 30."],"options":[],"conceptId":"math_statistics_44_median_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"44. Median from an Ungrouped Frequency Table"}', 2),
  (768, 225, 'There are 7 observations. What is the median position?', 'text', 1, 'Use (n + 1) ÷ 2.', '{"why":"Seven ordered observations have one central position: the fourth.","sol":"Step 1: n = 7.\nStep 2: (7 + 1) ÷ 2 = 4.\nStep 3: The median is at the 4th position.","steps":["Step 1: n = 7.","Step 2: (7 + 1) ÷ 2 = 4.","Step 3: The median is at the 4th position."],"options":[],"conceptId":"math_statistics_45_finding_the_median_position","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"45. Finding the Median Position"}', 0),
  (769, 225, 'There are 10 observations. What are the two median positions?', 'text', 1, 'Find n ÷ 2, then add 1.', '{"why":"An even-sized dataset has two central observations.","sol":"Step 1: n ÷ 2 = 10 ÷ 2 = 5.\nStep 2: The first middle position is 5th.\nStep 3: The second middle position is 6th.\nStep 4: Therefore the middle positions are 5th and 6th.","steps":["Step 1: n ÷ 2 = 10 ÷ 2 = 5.","Step 2: The first middle position is 5th.","Step 3: The second middle position is 6th.","Step 4: Therefore the middle positions are 5th and 6th."],"options":[],"conceptId":"math_statistics_45_finding_the_median_position","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"45. Finding the Median Position"}', 1),
  (770, 225, 'There are 14 observations. What are the two middle positions?', 'text', 1, '14 ÷ 2 gives the first middle position.', '{"why":"The median for an even dataset lies between the two central positions.","sol":"Step 1: 14 ÷ 2 = 7.\nStep 2: First middle position = 7th.\nStep 3: Second middle position = 8th.\nStep 4: Therefore the middle positions are 7th and 8th.","steps":["Step 1: 14 ÷ 2 = 7.","Step 2: First middle position = 7th.","Step 3: Second middle position = 8th.","Step 4: Therefore the middle positions are 7th and 8th."],"options":[],"conceptId":"math_statistics_45_finding_the_median_position","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"45. Finding the Median Position"}', 2),
  (771, 226, 'Find the median class for classes 0–9, 10–19 and 20–29 with frequencies 3, 5 and 2.', 'text', 1, 'Find the total frequency and the middle position.', '{"why":"The middle observations fall inside the 10–19 class.","sol":"Step 1: Total frequency = 3 + 5 + 2 = 10.\nStep 2: Middle positions are 5th and 6th.\nStep 3: Cumulative frequencies are 3, 8, 10.\nStep 4: Both the 5th and 6th observations lie in 10–19.\nStep 5: Median class = 10–19.","steps":["Step 1: Total frequency = 3 + 5 + 2 = 10.","Step 2: Middle positions are 5th and 6th.","Step 3: Cumulative frequencies are 3, 8, 10.","Step 4: Both the 5th and 6th observations lie in 10–19.","Step 5: Median class = 10–19."],"options":[],"conceptId":"math_statistics_46_median_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"46. Median of Grouped Data"}', 0),
  (772, 226, 'Find the median class for classes 10–19, 20–29 and 30–39 with frequencies 2, 4 and 5.', 'text', 1, 'There are 11 observations.', '{"why":"The sixth observation is the last observation represented by the 20–29 class.","sol":"Step 1: Total frequency = 2 + 4 + 5 = 11.\nStep 2: Median position = (11 + 1) ÷ 2 = 6th.\nStep 3: Cumulative frequencies are 2, 6, 11.\nStep 4: The 6th observation is in the 20–29 class.\nStep 5: Median class = 20–29.","steps":["Step 1: Total frequency = 2 + 4 + 5 = 11.","Step 2: Median position = (11 + 1) ÷ 2 = 6th.","Step 3: Cumulative frequencies are 2, 6, 11.","Step 4: The 6th observation is in the 20–29 class.","Step 5: Median class = 20–29."],"options":[],"conceptId":"math_statistics_46_median_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"46. Median of Grouped Data"}', 1),
  (773, 226, 'Find the median class for classes 0–9, 10–19, 20–29 and 30–39 with frequencies 1, 3, 6 and 2.', 'text', 1, 'There are 12 observations, so inspect positions 6 and 7.', '{"why":"The cumulative frequency reaches 10 in the 20–29 class, containing both middle observations.","sol":"Step 1: Total frequency = 1 + 3 + 6 + 2 = 12.\nStep 2: Middle positions are 6th and 7th.\nStep 3: Cumulative frequencies are 1, 4, 10, 12.\nStep 4: Both the 6th and 7th observations lie in 20–29.\nStep 5: Median class = 20–29.","steps":["Step 1: Total frequency = 1 + 3 + 6 + 2 = 12.","Step 2: Middle positions are 6th and 7th.","Step 3: Cumulative frequencies are 1, 4, 10, 12.","Step 4: Both the 6th and 7th observations lie in 20–29.","Step 5: Median class = 20–29."],"options":[],"conceptId":"math_statistics_46_median_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"46. Median of Grouped Data"}', 2),
  (774, 227, 'Cumulative frequencies are 3, 8, 14 and 20. If the median position is 10th, which class contains the median?', 'text', 1, 'Find the first cumulative frequency that is at least 10.', '{"why":"The third class contains observations 9 through 14.","sol":"Step 1: The cumulative frequencies are 3, 8, 14 and 20.\nStep 2: The 10th observation is beyond 8.\nStep 3: The next cumulative frequency is 14.\nStep 4: Therefore the median is in the third class.","steps":["Step 1: The cumulative frequencies are 3, 8, 14 and 20.","Step 2: The 10th observation is beyond 8.","Step 3: The next cumulative frequency is 14.","Step 4: Therefore the median is in the third class."],"options":[],"conceptId":"math_statistics_47_identifying_the_median_class","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"47. Identifying the Median Class"}', 0),
  (775, 227, 'A grouped table has cumulative frequencies 4, 9, 15 and 21. If the median position is 8th, which class is the median class?', 'text', 1, 'Locate 8 using the cumulative frequencies.', '{"why":"The second class contains observations 5 through 9.","sol":"Step 1: The first cumulative frequency is 4, which is below 8.\nStep 2: The second cumulative frequency is 9, which reaches 8.\nStep 3: Therefore the median lies in the second class.","steps":["Step 1: The first cumulative frequency is 4, which is below 8.","Step 2: The second cumulative frequency is 9, which reaches 8.","Step 3: Therefore the median lies in the second class."],"options":[],"conceptId":"math_statistics_47_identifying_the_median_class","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"47. Identifying the Median Class"}', 1),
  (776, 227, 'Cumulative frequencies are 2, 7, 13 and 18. If the middle positions are 9th and 10th, which class contains both?', 'text', 1, 'Find where positions 9 and 10 fall.', '{"why":"The third class contains observations 8 through 13.","sol":"Step 1: The first two cumulative frequencies are 2 and 7.\nStep 2: The third cumulative frequency is 13.\nStep 3: Therefore positions 9 and 10 lie in the third class.\nStep 4: Median class = third class.","steps":["Step 1: The first two cumulative frequencies are 2 and 7.","Step 2: The third cumulative frequency is 13.","Step 3: Therefore positions 9 and 10 lie in the third class.","Step 4: Median class = third class."],"options":[],"conceptId":"math_statistics_47_identifying_the_median_class","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"47. Identifying the Median Class"}', 2),
  (777, 228, 'The values 5, 10 and 15 have frequencies 3, 2 and 4. Find the median.', 'text', 1, 'There are 9 observations, so find the 5th observation.', '{"why":"The cumulative frequency reaches 5 at the value 10.","sol":"Step 1: Total frequency = 3 + 2 + 4 = 9.\nStep 2: Median position = (9 + 1) ÷ 2 = 5th.\nStep 3: Cumulative frequencies are 3, 5, 9.\nStep 4: The 5th observation is 10.\nStep 5: Median = 10.","steps":["Step 1: Total frequency = 3 + 2 + 4 = 9.","Step 2: Median position = (9 + 1) ÷ 2 = 5th.","Step 3: Cumulative frequencies are 3, 5, 9.","Step 4: The 5th observation is 10.","Step 5: Median = 10."],"options":[],"conceptId":"math_statistics_48_using_cumulative_frequency_to_locate_the_median","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"48. Using Cumulative Frequency to Locate the Median"}', 0),
  (778, 228, 'The values 2, 4 and 6 have frequencies 2, 3 and 5. Find the median.', 'text', 1, 'There are 10 observations. Find the 5th and 6th positions.', '{"why":"The two middle observations are 4 and 6.","sol":"Step 1: Total frequency = 10.\nStep 2: Middle positions are 5th and 6th.\nStep 3: The cumulative frequencies are 2, 5, 10.\nStep 4: The 5th observation is 4.\nStep 5: The 6th observation is 6.\nStep 6: Median = (4 + 6) ÷ 2 = 5.","steps":["Step 1: Total frequency = 10.","Step 2: Middle positions are 5th and 6th.","Step 3: The cumulative frequencies are 2, 5, 10.","Step 4: The 5th observation is 4.","Step 5: The 6th observation is 6.","Step 6: Median = (4 + 6) ÷ 2 = 5."],"options":[],"conceptId":"math_statistics_48_using_cumulative_frequency_to_locate_the_median","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"48. Using Cumulative Frequency to Locate the Median"}', 1),
  (779, 228, 'The values 10, 20 and 30 have frequencies 2, 5 and 1. Find the median.', 'text', 1, 'There are 8 observations.', '{"why":"Both middle observations are among the five occurrences of 20.","sol":"Step 1: Total frequency = 8.\nStep 2: Middle positions are 4th and 5th.\nStep 3: The cumulative frequency at 20 is 7.\nStep 4: Therefore both positions 4 and 5 correspond to 20.\nStep 5: Median = 20.","steps":["Step 1: Total frequency = 8.","Step 2: Middle positions are 4th and 5th.","Step 3: The cumulative frequency at 20 is 7.","Step 4: Therefore both positions 4 and 5 correspond to 20.","Step 5: Median = 20."],"options":[],"conceptId":"math_statistics_48_using_cumulative_frequency_to_locate_the_median","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"48. Using Cumulative Frequency to Locate the Median"}', 2),
  (780, 229, 'For the data 2, 4, 6, 8, 10, find the mean and median.', 'text', 1, 'Calculate the mean and identify the middle value.', '{"why":"The dataset is balanced around 6, so both measures give the same value.","sol":"Step 1: Mean = (2 + 4 + 6 + 8 + 10) ÷ 5.\nStep 2: Mean = 30 ÷ 5 = 6.\nStep 3: The middle value is 6.\nStep 4: Median = 6.","steps":["Step 1: Mean = (2 + 4 + 6 + 8 + 10) ÷ 5.","Step 2: Mean = 30 ÷ 5 = 6.","Step 3: The middle value is 6.","Step 4: Median = 6."],"options":[],"conceptId":"math_statistics_49_comparing_median_and_mean","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"49. Comparing Median and Mean"}', 0),
  (781, 229, 'For the data 2, 3, 4, 5, 26, find the mean and median.', 'text', 1, 'The data is already ordered.', '{"why":"The extreme value 26 raises the mean, while the median remains the middle value.","sol":"Step 1: Mean = (2 + 3 + 4 + 5 + 26) ÷ 5.\nStep 2: Mean = 40 ÷ 5 = 8.\nStep 3: The middle value is 4.\nStep 4: Median = 4.","steps":["Step 1: Mean = (2 + 3 + 4 + 5 + 26) ÷ 5.","Step 2: Mean = 40 ÷ 5 = 8.","Step 3: The middle value is 4.","Step 4: Median = 4."],"options":[],"conceptId":"math_statistics_49_comparing_median_and_mean","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"49. Comparing Median and Mean"}', 1),
  (782, 229, 'Which measure is more affected by the value 100 in the data 5, 6, 7, 8, 100: mean or median?', 'text', 1, 'Calculate both or consider how each is found.', '{"why":"The mean uses every numerical value, so an extreme value can strongly affect it.","sol":"Step 1: Mean = 25.2.\nStep 2: Median = 7.\nStep 3: The mean changed substantially because 100 contributes directly to the total.\nStep 4: The median remains the middle position.","steps":["Step 1: Mean = 25.2.","Step 2: Median = 7.","Step 3: The mean changed substantially because 100 contributes directly to the total.","Step 4: The median remains the middle position."],"options":[],"conceptId":"math_statistics_49_comparing_median_and_mean","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"49. Comparing Median and Mean"}', 2),
  (783, 230, 'For the data 4, 5, 6, 7 and 8, which measure gives a good description of the centre: mean or median?', 'text', 1, 'Check whether there is an extreme value.', '{"why":"The data is balanced and contains no extreme observation.","sol":"Step 1: There is no unusually large or small value.\nStep 2: Mean = (4 + 5 + 6 + 7 + 8) ÷ 5 = 6.\nStep 3: Median = 6.\nStep 4: Both describe the centre well.","steps":["Step 1: There is no unusually large or small value.","Step 2: Mean = (4 + 5 + 6 + 7 + 8) ÷ 5 = 6.","Step 3: Median = 6.","Step 4: Both describe the centre well."],"options":[],"conceptId":"math_statistics_50_choosing_between_mean_and_median","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"50. Choosing Between Mean and Median"}', 0),
  (784, 230, 'For the data 3, 4, 5, 6 and 50, which measure better represents the centre of most observations?', 'text', 1, 'Calculate the mean and compare it with the median.', '{"why":"The extreme value 50 pulls the mean upward.","sol":"Step 1: Mean = (3 + 4 + 5 + 6 + 50) ÷ 5.\nStep 2: Mean = 68 ÷ 5 = 13.6.\nStep 3: Median = 5.\nStep 4: Most observations are between 3 and 6.\nStep 5: The median is closer to the centre of most observations.","steps":["Step 1: Mean = (3 + 4 + 5 + 6 + 50) ÷ 5.","Step 2: Mean = 68 ÷ 5 = 13.6.","Step 3: Median = 5.","Step 4: Most observations are between 3 and 6.","Step 5: The median is closer to the centre of most observations."],"options":[],"conceptId":"math_statistics_50_choosing_between_mean_and_median","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"50. Choosing Between Mean and Median"}', 1),
  (785, 230, 'A dataset contains one extremely large value compared with all the others. Which measure is generally less affected by that extreme value?', 'text', 1, 'Think about whether the measure uses every value or only position.', '{"why":"The median is based on position rather than adding every value.","sol":"Step 1: The mean uses every value in its calculation.\nStep 2: An extremely large value therefore changes the total.\nStep 3: The median depends on the middle position.\nStep 4: Therefore the median is generally less affected.","steps":["Step 1: The mean uses every value in its calculation.","Step 2: An extremely large value therefore changes the total.","Step 3: The median depends on the middle position.","Step 4: Therefore the median is generally less affected."],"options":[],"conceptId":"math_statistics_50_choosing_between_mean_and_median","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"50. Choosing Between Mean and Median"}', 2),
  (786, 231, 'Find the mode of 2, 3, 3, 5 and 7.', 'text', 1, 'Count how many times each value occurs.', '{"why":"The mode is the value occurring most frequently.","sol":"Step 1: 2 occurs once.\nStep 2: 3 occurs twice.\nStep 3: 5 occurs once.\nStep 4: 7 occurs once.\nStep 5: The highest frequency is 2 for the value 3.","steps":["Step 1: 2 occurs once.","Step 2: 3 occurs twice.","Step 3: 5 occurs once.","Step 4: 7 occurs once.","Step 5: The highest frequency is 2 for the value 3."],"options":[],"conceptId":"math_statistics_51_meaning_of_the_mode","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"51. Meaning of the Mode"}', 0),
  (787, 231, 'Find the mode of 4, 6, 6, 8, 9, 6.', 'text', 1, 'Which value appears most often?', '{"why":"Six has the highest frequency.","sol":"Step 1: 4 occurs once.\nStep 2: 6 occurs three times.\nStep 3: 8 occurs once.\nStep 4: 9 occurs once.\nStep 5: Therefore the mode is 6.","steps":["Step 1: 4 occurs once.","Step 2: 6 occurs three times.","Step 3: 8 occurs once.","Step 4: 9 occurs once.","Step 5: Therefore the mode is 6."],"options":[],"conceptId":"math_statistics_51_meaning_of_the_mode","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"51. Meaning of the Mode"}', 1),
  (788, 231, 'Find the mode of 5, 5, 7, 8, 9, 5, 10.', 'text', 1, 'Count the occurrences of 5.', '{"why":"Five occurs more often than every other value.","sol":"Step 1: 5 occurs three times.\nStep 2: 7 occurs once.\nStep 3: 8 occurs once.\nStep 4: 9 occurs once.\nStep 5: 10 occurs once.\nStep 6: Therefore the mode is 5.","steps":["Step 1: 5 occurs three times.","Step 2: 7 occurs once.","Step 3: 8 occurs once.","Step 4: 9 occurs once.","Step 5: 10 occurs once.","Step 6: Therefore the mode is 5."],"options":[],"conceptId":"math_statistics_51_meaning_of_the_mode","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"51. Meaning of the Mode"}', 2),
  (789, 232, 'Find the mode of 3, 5, 3, 7, 3 and 9.', 'text', 1, 'Count each value.', '{"why":"Three occurs more frequently than every other value.","sol":"Step 1: 3 occurs three times.\nStep 2: 5 occurs once.\nStep 3: 7 occurs once.\nStep 4: 9 occurs once.\nStep 5: Therefore the mode is 3.","steps":["Step 1: 3 occurs three times.","Step 2: 5 occurs once.","Step 3: 7 occurs once.","Step 4: 9 occurs once.","Step 5: Therefore the mode is 3."],"options":[],"conceptId":"math_statistics_52_finding_mode_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"52. Finding Mode from Raw Data"}', 0),
  (790, 232, 'Find the mode of 2, 4, 4, 6, 4, 8 and 9.', 'text', 1, 'Find the value with the highest frequency.', '{"why":"Four has the highest frequency of three.","sol":"Step 1: 2 occurs once.\nStep 2: 4 occurs three times.\nStep 3: 6 occurs once.\nStep 4: 8 occurs once.\nStep 5: 9 occurs once.\nStep 6: Therefore the mode is 4.","steps":["Step 1: 2 occurs once.","Step 2: 4 occurs three times.","Step 3: 6 occurs once.","Step 4: 8 occurs once.","Step 5: 9 occurs once.","Step 6: Therefore the mode is 4."],"options":[],"conceptId":"math_statistics_52_finding_mode_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"52. Finding Mode from Raw Data"}', 1),
  (791, 232, 'Find the mode of 2, 2, 3, 3, 5, 7.', 'text', 1, 'Check whether one value occurs more often than the others.', '{"why":"Both 2 and 3 occur twice, which is the highest frequency.","sol":"Step 1: 2 occurs twice.\nStep 2: 3 occurs twice.\nStep 3: 5 occurs once.\nStep 4: 7 occurs once.\nStep 5: The highest frequency is 2.\nStep 6: Therefore the dataset has two modes: 2 and 3.","steps":["Step 1: 2 occurs twice.","Step 2: 3 occurs twice.","Step 3: 5 occurs once.","Step 4: 7 occurs once.","Step 5: The highest frequency is 2.","Step 6: Therefore the dataset has two modes: 2 and 3."],"options":[],"conceptId":"math_statistics_52_finding_mode_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"52. Finding Mode from Raw Data"}', 2),
  (792, 233, 'Find the mode from x = 2, 4, 6 with frequencies 3, 7, 2 respectively.', 'text', 1, 'Find the largest frequency.', '{"why":"The value 4 occurs seven times, more than any other value.","sol":"Step 1: The frequencies are 3, 7 and 2.\nStep 2: The largest frequency is 7.\nStep 3: Frequency 7 belongs to x = 4.\nStep 4: Mode = 4.","steps":["Step 1: The frequencies are 3, 7 and 2.","Step 2: The largest frequency is 7.","Step 3: Frequency 7 belongs to x = 4.","Step 4: Mode = 4."],"options":[],"conceptId":"math_statistics_53_mode_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"53. Mode from an Ungrouped Frequency Table"}', 0),
  (793, 233, 'Find the mode from x = 5, 10, 15 with frequencies 2, 6, 4 respectively.', 'text', 1, 'The mode corresponds to the highest frequency.', '{"why":"Ten has the highest frequency.","sol":"Step 1: The frequencies are 2, 6 and 4.\nStep 2: The largest frequency is 6.\nStep 3: Frequency 6 belongs to x = 10.\nStep 4: Mode = 10.","steps":["Step 1: The frequencies are 2, 6 and 4.","Step 2: The largest frequency is 6.","Step 3: Frequency 6 belongs to x = 10.","Step 4: Mode = 10."],"options":[],"conceptId":"math_statistics_53_mode_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"53. Mode from an Ungrouped Frequency Table"}', 1),
  (794, 233, 'Find the mode from x = 1, 2, 3, 4 with frequencies 3, 5, 5, 2.', 'text', 1, 'There are two equal highest frequencies.', '{"why":"Both values occur with the highest frequency.","sol":"Step 1: The largest frequency is 5.\nStep 2: x = 2 has frequency 5.\nStep 3: x = 3 also has frequency 5.\nStep 4: Therefore the modes are 2 and 3.","steps":["Step 1: The largest frequency is 5.","Step 2: x = 2 has frequency 5.","Step 3: x = 3 also has frequency 5.","Step 4: Therefore the modes are 2 and 3."],"options":[],"conceptId":"math_statistics_53_mode_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"53. Mode from an Ungrouped Frequency Table"}', 2),
  (795, 234, 'Find the modal class for classes 0–9, 10–19 and 20–29 with frequencies 4, 9 and 6.', 'text', 1, 'Find the class with the largest frequency.', '{"why":"The modal class is the class with the highest frequency.","sol":"Step 1: The frequencies are 4, 9 and 6.\nStep 2: The largest frequency is 9.\nStep 3: Frequency 9 belongs to 10–19.\nStep 4: Modal class = 10–19.","steps":["Step 1: The frequencies are 4, 9 and 6.","Step 2: The largest frequency is 9.","Step 3: Frequency 9 belongs to 10–19.","Step 4: Modal class = 10–19."],"options":[],"conceptId":"math_statistics_54_identifying_the_modal_class","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"54. Identifying the Modal Class"}', 0),
  (796, 234, 'Find the modal class for classes 10–14, 15–19, 20–24 and 25–29 with frequencies 3, 5, 8 and 4.', 'text', 1, 'Look for frequency 8.', '{"why":"The 20–24 class contains the greatest number of observations.","sol":"Step 1: The largest frequency is 8.\nStep 2: Frequency 8 belongs to class 20–24.\nStep 3: Modal class = 20–24.","steps":["Step 1: The largest frequency is 8.","Step 2: Frequency 8 belongs to class 20–24.","Step 3: Modal class = 20–24."],"options":[],"conceptId":"math_statistics_54_identifying_the_modal_class","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"54. Identifying the Modal Class"}', 1),
  (797, 234, 'Classes 0–9, 10–19, 20–29 and 30–39 have frequencies 5, 7, 7 and 3. Identify the modal classes.', 'text', 1, 'Check which classes share the highest frequency.', '{"why":"Both classes have the highest frequency.","sol":"Step 1: The highest frequency is 7.\nStep 2: 10–19 has frequency 7.\nStep 3: 20–29 also has frequency 7.\nStep 4: Therefore both are modal classes.","steps":["Step 1: The highest frequency is 7.","Step 2: 10–19 has frequency 7.","Step 3: 20–29 also has frequency 7.","Step 4: Therefore both are modal classes."],"options":[],"conceptId":"math_statistics_54_identifying_the_modal_class","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"54. Identifying the Modal Class"}', 2),
  (798, 235, 'Find the mean, median and mode of 2, 3, 3, 4 and 8.', 'text', 1, 'Calculate each measure separately.', '{"why":"Each measure uses a different method to describe the dataset.","sol":"Step 1: Mean = (2 + 3 + 3 + 4 + 8) ÷ 5 = 20 ÷ 5 = 4.\nStep 2: The middle value is 3, so median = 3.\nStep 3: The value 3 occurs twice, so mode = 3.","steps":["Step 1: Mean = (2 + 3 + 3 + 4 + 8) ÷ 5 = 20 ÷ 5 = 4.","Step 2: The middle value is 3, so median = 3.","Step 3: The value 3 occurs twice, so mode = 3."],"options":[],"conceptId":"math_statistics_55_comparing_mean_median_and_mode","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"55. Comparing Mean, Median and Mode"}', 0),
  (799, 235, 'Find the mean, median and mode of 4, 5, 5, 5 and 6.', 'text', 1, 'Notice that 5 occurs most frequently.', '{"why":"All three measures happen to give the same value.","sol":"Step 1: Mean = (4 + 5 + 5 + 5 + 6) ÷ 5 = 25 ÷ 5 = 5.\nStep 2: Median = 5.\nStep 3: Mode = 5 because 5 occurs three times.","steps":["Step 1: Mean = (4 + 5 + 5 + 5 + 6) ÷ 5 = 25 ÷ 5 = 5.","Step 2: Median = 5.","Step 3: Mode = 5 because 5 occurs three times."],"options":[],"conceptId":"math_statistics_55_comparing_mean_median_and_mode","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"55. Comparing Mean, Median and Mode"}', 1),
  (800, 235, 'Find the mean, median and mode of 1, 2, 2, 3 and 12.', 'text', 1, 'The data is already ordered.', '{"why":"The extreme value 12 affects the mean but does not change the middle position or most frequent value.","sol":"Step 1: Mean = (1 + 2 + 2 + 3 + 12) ÷ 5 = 20 ÷ 5 = 4.\nStep 2: Median = 2.\nStep 3: Mode = 2 because it occurs twice.","steps":["Step 1: Mean = (1 + 2 + 2 + 3 + 12) ÷ 5 = 20 ÷ 5 = 4.","Step 2: Median = 2.","Step 3: Mode = 2 because it occurs twice."],"options":[],"conceptId":"math_statistics_55_comparing_mean_median_and_mode","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"55. Comparing Mean, Median and Mode"}', 2),
  (801, 236, 'Find the range of 2, 5, 7, 9 and 11.', 'text', 1, 'Subtract the smallest value from the largest.', '{"why":"Range measures the distance between the largest and smallest values.","sol":"Step 1: Largest value = 11.\nStep 2: Smallest value = 2.\nStep 3: Range = 11 − 2.\nStep 4: Range = 9.","steps":["Step 1: Largest value = 11.","Step 2: Smallest value = 2.","Step 3: Range = 11 − 2.","Step 4: Range = 9."],"options":[],"conceptId":"math_statistics_56_meaning_of_range","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"56. Meaning of Range"}', 0),
  (802, 236, 'Find the range of 15, 8, 20, 12 and 5.', 'text', 1, 'Identify 20 and 5 first.', '{"why":"The largest value is 15 units above the smallest value.","sol":"Step 1: Largest value = 20.\nStep 2: Smallest value = 5.\nStep 3: Range = 20 − 5.\nStep 4: Range = 15.","steps":["Step 1: Largest value = 20.","Step 2: Smallest value = 5.","Step 3: Range = 20 − 5.","Step 4: Range = 15."],"options":[],"conceptId":"math_statistics_56_meaning_of_range","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"56. Meaning of Range"}', 1),
  (803, 236, 'Find the range of 7, 7, 7, 7.', 'text', 1, 'The largest and smallest values are the same.', '{"why":"There is no spread because every observation has the same value.","sol":"Step 1: Largest value = 7.\nStep 2: Smallest value = 7.\nStep 3: Range = 7 − 7.\nStep 4: Range = 0.","steps":["Step 1: Largest value = 7.","Step 2: Smallest value = 7.","Step 3: Range = 7 − 7.","Step 4: Range = 0."],"options":[],"conceptId":"math_statistics_56_meaning_of_range","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"56. Meaning of Range"}', 2),
  (804, 237, 'Find the range of 4, 10, 7, 15 and 6.', 'text', 1, 'Largest minus smallest.', '{"why":"The range is the distance from the smallest observation to the largest.","sol":"Step 1: Largest = 15.\nStep 2: Smallest = 4.\nStep 3: Range = 15 − 4.\nStep 4: Range = 11.","steps":["Step 1: Largest = 15.","Step 2: Smallest = 4.","Step 3: Range = 15 − 4.","Step 4: Range = 11."],"options":[],"conceptId":"math_statistics_57_finding_range_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"57. Finding Range from Raw Data"}', 0),
  (805, 237, 'Find the range of 22, 8, 31, 14 and 5.', 'text', 1, 'Find 31 and 5.', '{"why":"The largest and smallest values determine the range.","sol":"Step 1: Largest = 31.\nStep 2: Smallest = 5.\nStep 3: Range = 31 − 5.\nStep 4: Range = 26.","steps":["Step 1: Largest = 31.","Step 2: Smallest = 5.","Step 3: Range = 31 − 5.","Step 4: Range = 26."],"options":[],"conceptId":"math_statistics_57_finding_range_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"57. Finding Range from Raw Data"}', 1),
  (806, 237, 'Find the range of −5, 2, 4, −1 and 8.', 'text', 1, 'The smallest value is negative.', '{"why":"Subtracting a negative value increases the distance between the extremes.","sol":"Step 1: Largest = 8.\nStep 2: Smallest = −5.\nStep 3: Range = 8 − (−5).\nStep 4: Range = 8 + 5.\nStep 5: Range = 13.","steps":["Step 1: Largest = 8.","Step 2: Smallest = −5.","Step 3: Range = 8 − (−5).","Step 4: Range = 8 + 5.","Step 5: Range = 13."],"options":[],"conceptId":"math_statistics_57_finding_range_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"57. Finding Range from Raw Data"}', 2),
  (807, 238, 'Find the range from x = 2, 5, 8 with frequencies 4, 3, 2.', 'text', 1, 'Ignore the frequencies when calculating the range.', '{"why":"Range depends on the smallest and largest values, not their frequencies.","sol":"Step 1: Smallest value = 2.\nStep 2: Largest value = 8.\nStep 3: Range = 8 − 2.\nStep 4: Range = 6.","steps":["Step 1: Smallest value = 2.","Step 2: Largest value = 8.","Step 3: Range = 8 − 2.","Step 4: Range = 6."],"options":[],"conceptId":"math_statistics_58_finding_range_from_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"58. Finding Range from a Frequency Table"}', 0),
  (808, 238, 'Find the range from x = 10, 20, 35, 40 with frequencies 2, 4, 3, 1.', 'text', 1, 'Use 10 and 40.', '{"why":"The extreme values are 10 and 40.","sol":"Step 1: Smallest value = 10.\nStep 2: Largest value = 40.\nStep 3: Range = 40 − 10.\nStep 4: Range = 30.","steps":["Step 1: Smallest value = 10.","Step 2: Largest value = 40.","Step 3: Range = 40 − 10.","Step 4: Range = 30."],"options":[],"conceptId":"math_statistics_58_finding_range_from_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"58. Finding Range from a Frequency Table"}', 1),
  (809, 238, 'Find the range from x = −2, 4 and 9 with frequencies 3, 5 and 2.', 'text', 1, 'Subtract the negative smallest value.', '{"why":"The distance from −2 to 9 is 11.","sol":"Step 1: Largest = 9.\nStep 2: Smallest = −2.\nStep 3: Range = 9 − (−2).\nStep 4: Range = 11.","steps":["Step 1: Largest = 9.","Step 2: Smallest = −2.","Step 3: Range = 9 − (−2).","Step 4: Range = 11."],"options":[],"conceptId":"math_statistics_58_finding_range_from_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"58. Finding Range from a Frequency Table"}', 2),
  (810, 239, 'Dataset A is 2, 5, 7, 10. Dataset B is 1, 4, 8, 15. Which has the greater range?', 'text', 1, 'Calculate both ranges.', '{"why":"Dataset B has a larger distance between its smallest and largest values.","sol":"Step 1: Range A = 10 − 2 = 8.\nStep 2: Range B = 15 − 1 = 14.\nStep 3: 14 is greater than 8.\nStep 4: Therefore Dataset B has the greater range.","steps":["Step 1: Range A = 10 − 2 = 8.","Step 2: Range B = 15 − 1 = 14.","Step 3: 14 is greater than 8.","Step 4: Therefore Dataset B has the greater range."],"options":[],"conceptId":"math_statistics_59_comparing_two_data_sets_using_range","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"59. Comparing Two Data Sets Using Range"}', 0),
  (811, 239, 'Dataset A has smallest value 10 and largest value 25. Dataset B has smallest value 5 and largest value 18. Which has the smaller range?', 'text', 1, 'Find both ranges.', '{"why":"Dataset B''s extreme values are 13 units apart.","sol":"Step 1: Range A = 25 − 10 = 15.\nStep 2: Range B = 18 − 5 = 13.\nStep 3: 13 is smaller than 15.\nStep 4: Therefore Dataset B has the smaller range.","steps":["Step 1: Range A = 25 − 10 = 15.","Step 2: Range B = 18 − 5 = 13.","Step 3: 13 is smaller than 15.","Step 4: Therefore Dataset B has the smaller range."],"options":[],"conceptId":"math_statistics_59_comparing_two_data_sets_using_range","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"59. Comparing Two Data Sets Using Range"}', 1),
  (812, 239, 'Dataset A has range 7. Dataset B has range 12. Which dataset has greater spread according to the range?', 'text', 1, 'Compare 7 and 12.', '{"why":"A larger range indicates a larger distance between the extreme values.","sol":"Step 1: Range A = 7.\nStep 2: Range B = 12.\nStep 3: 12 is greater than 7.\nStep 4: Therefore Dataset B has greater spread.","steps":["Step 1: Range A = 7.","Step 2: Range B = 12.","Step 3: 12 is greater than 7.","Step 4: Therefore Dataset B has greater spread."],"options":[],"conceptId":"math_statistics_59_comparing_two_data_sets_using_range","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"59. Comparing Two Data Sets Using Range"}', 2),
  (813, 240, 'The data is 3, 5, 7, 9. A value of 20 is added. What is the new range?', 'text', 1, '20 becomes the new largest value.', '{"why":"The new value 20 becomes the largest observation.","sol":"Step 1: New largest value = 20.\nStep 2: Smallest value = 3.\nStep 3: New range = 20 − 3.\nStep 4: New range = 17.","steps":["Step 1: New largest value = 20.","Step 2: Smallest value = 3.","Step 3: New range = 20 − 3.","Step 4: New range = 17."],"options":[],"conceptId":"math_statistics_60_effect_of_an_extreme_value_on_range","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"60. Effect of an Extreme Value on Range"}', 0),
  (814, 240, 'The data is 4, 8, 10, 12. A value of 6 is added. What is the new range?', 'text', 1, 'Does 6 become the smallest or largest value?', '{"why":"Adding a value inside the existing extremes does not change the range.","sol":"Step 1: Original smallest = 4.\nStep 2: Original largest = 12.\nStep 3: The new value 6 lies between 4 and 12.\nStep 4: New range = 12 − 4 = 8.","steps":["Step 1: Original smallest = 4.","Step 2: Original largest = 12.","Step 3: The new value 6 lies between 4 and 12.","Step 4: New range = 12 − 4 = 8."],"options":[],"conceptId":"math_statistics_60_effect_of_an_extreme_value_on_range","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"60. Effect of an Extreme Value on Range"}', 1),
  (815, 240, 'The data is 10, 12, 15, 18. A value of 2 is added. What is the new range?', 'text', 1, '2 becomes the new smallest value.', '{"why":"The new value 2 extends the lower extreme of the dataset.","sol":"Step 1: New smallest value = 2.\nStep 2: Largest value = 18.\nStep 3: New range = 18 − 2.\nStep 4: New range = 16.","steps":["Step 1: New smallest value = 2.","Step 2: Largest value = 18.","Step 3: New range = 18 − 2.","Step 4: New range = 16."],"options":[],"conceptId":"math_statistics_60_effect_of_an_extreme_value_on_range","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"60. Effect of an Extreme Value on Range"}', 2),
  (816, 241, 'A bar graph shows 12 learners chose Biology. What does the height of the Biology bar represent?', 'text', 1, 'Read the value represented by the Biology bar.', '{"why":"The height of a bar represents the frequency or quantity for that category.","sol":"Step 1: Find the Biology category.\nStep 2: Read the height of its bar.\nStep 3: The height represents the number of learners.\nStep 4: The value is 12.","steps":["Step 1: Find the Biology category.","Step 2: Read the height of its bar.","Step 3: The height represents the number of learners.","Step 4: The value is 12."],"options":[],"conceptId":"math_statistics_reading_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Reading a Bar Graph"}', 0),
  (817, 241, 'A bar graph shows 25 books for Monday and 18 books for Tuesday. How many more books were recorded on Monday?', 'text', 1, 'Subtract Tuesday''s value from Monday''s value.', '{"why":"The difference between the two bar heights is 7.","sol":"Step 1: Monday = 25.\nStep 2: Tuesday = 18.\nStep 3: Difference = 25 − 18.\nStep 4: 25 − 18 = 7.","steps":["Step 1: Monday = 25.","Step 2: Tuesday = 18.","Step 3: Difference = 25 − 18.","Step 4: 25 − 18 = 7."],"options":[],"conceptId":"math_statistics_reading_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Reading a Bar Graph"}', 1),
  (818, 241, 'The bars for A, B and C have heights 9, 14 and 11 respectively. Which category has the greatest frequency?', 'text', 1, 'Find the greatest bar height.', '{"why":"The tallest bar represents the greatest frequency.","sol":"Step 1: A = 9.\nStep 2: B = 14.\nStep 3: C = 11.\nStep 4: The greatest value is 14.\nStep 5: Therefore B has the greatest frequency.","steps":["Step 1: A = 9.","Step 2: B = 14.","Step 3: C = 11.","Step 4: The greatest value is 14.","Step 5: Therefore B has the greatest frequency."],"options":[],"conceptId":"math_statistics_reading_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Reading a Bar Graph"}', 2),
  (819, 242, 'A table contains A = 5, B = 10 and C = 15. What should be the height of the bar for B?', 'text', 1, 'The bar height equals the frequency.', '{"why":"Each bar must reach the frequency of its category.","sol":"Step 1: Find the value for B.\nStep 2: B has a frequency of 10.\nStep 3: Therefore the B bar must reach 10.","steps":["Step 1: Find the value for B.","Step 2: B has a frequency of 10.","Step 3: Therefore the B bar must reach 10."],"options":[],"conceptId":"math_statistics_constructing_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Constructing a Bar Graph"}', 0),
  (820, 242, 'A dataset has frequencies 10, 20, 30 and 40. Give a suitable simple vertical scale.', 'text', 1, 'The largest value is 40.', '{"why":"The scale covers all values using equal intervals.","sol":"Step 1: Find the largest value: 40.\nStep 2: Use equal intervals on the vertical axis.\nStep 3: A suitable scale is 0, 10, 20, 30, 40.","steps":["Step 1: Find the largest value: 40.","Step 2: Use equal intervals on the vertical axis.","Step 3: A suitable scale is 0, 10, 20, 30, 40."],"options":[],"conceptId":"math_statistics_constructing_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Constructing a Bar Graph"}', 1),
  (821, 242, 'A category has frequency 18. If the vertical scale is marked every 5 units, where should its bar end?', 'text', 1, 'The bar must represent exactly 18.', '{"why":"The bar height must represent the actual frequency, even when it lies between scale marks.","sol":"Step 1: The scale has marks at 15 and 20.\nStep 2: 18 lies between 15 and 20.\nStep 3: Draw the bar to the level representing 18.","steps":["Step 1: The scale has marks at 15 and 20.","Step 2: 18 lies between 15 and 20.","Step 3: Draw the bar to the level representing 18."],"options":[],"conceptId":"math_statistics_constructing_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Constructing a Bar Graph"}', 2),
  (822, 243, 'A histogram has a bar of height 12 for the class 30–39. What does 12 represent?', 'text', 1, 'The vertical axis represents frequency.', '{"why":"Histogram bar height represents the frequency of the class.","sol":"Step 1: Find the class 30–39.\nStep 2: Its bar has height 12.\nStep 3: The height represents frequency.\nStep 4: Therefore 12 observations are in the class.","steps":["Step 1: Find the class 30–39.","Step 2: Its bar has height 12.","Step 3: The height represents frequency.","Step 4: Therefore 12 observations are in the class."],"options":[],"conceptId":"math_statistics_reading_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Reading a Histogram"}', 0),
  (823, 243, 'The frequencies of three histogram classes are 4, 11 and 7. Which class has the tallest bar?', 'text', 1, 'Find the greatest frequency.', '{"why":"The greatest frequency produces the tallest bar.","sol":"Step 1: Compare 4, 11 and 7.\nStep 2: The greatest frequency is 11.\nStep 3: Therefore the class with frequency 11 has the tallest bar.","steps":["Step 1: Compare 4, 11 and 7.","Step 2: The greatest frequency is 11.","Step 3: Therefore the class with frequency 11 has the tallest bar."],"options":[],"conceptId":"math_statistics_reading_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Reading a Histogram"}', 1),
  (824, 243, 'A histogram shows 6 observations in the class 40–49. How many observations belong to this class?', 'text', 1, 'Read the frequency from the bar.', '{"why":"Frequency tells how many observations belong to a class.","sol":"Step 1: Locate the class 40–49.\nStep 2: Its frequency is 6.\nStep 3: Therefore there are 6 observations in the class.","steps":["Step 1: Locate the class 40–49.","Step 2: Its frequency is 6.","Step 3: Therefore there are 6 observations in the class."],"options":[],"conceptId":"math_statistics_reading_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Reading a Histogram"}', 2),
  (825, 244, 'A grouped table has classes 0–9, 10–19 and 20–29 with frequencies 3, 6 and 5. What are the heights of the three histogram bars?', 'text', 1, 'Bar height equals frequency.', '{"why":"Each histogram bar reaches its class frequency.","sol":"Step 1: 0–9 has frequency 3.\nStep 2: 10–19 has frequency 6.\nStep 3: 20–29 has frequency 5.\nStep 4: Therefore the bar heights are 3, 6 and 5.","steps":["Step 1: 0–9 has frequency 3.","Step 2: 10–19 has frequency 6.","Step 3: 20–29 has frequency 5.","Step 4: Therefore the bar heights are 3, 6 and 5."],"options":[],"conceptId":"math_statistics_constructing_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Constructing a Histogram"}', 0),
  (826, 244, 'What boundary comes immediately between the classes 20–29 and 30–39?', 'text', 1, 'Find the midpoint between 29 and 30.', '{"why":"Class boundaries remove the gap between consecutive whole-number class limits.","sol":"Step 1: The upper limit of the first class is 29.\nStep 2: The lower limit of the next class is 30.\nStep 3: The boundary is halfway between them.\nStep 4: 29.5 is the boundary.","steps":["Step 1: The upper limit of the first class is 29.","Step 2: The lower limit of the next class is 30.","Step 3: The boundary is halfway between them.","Step 4: 29.5 is the boundary."],"options":[],"conceptId":"math_statistics_constructing_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Constructing a Histogram"}', 1),
  (827, 244, 'A histogram has frequencies 5, 9 and 7. Which bar should be tallest?', 'text', 1, 'Find the greatest frequency.', '{"why":"The largest frequency gives the tallest histogram bar.","sol":"Step 1: Compare 5, 9 and 7.\nStep 2: The greatest value is 9.\nStep 3: Therefore the bar with frequency 9 is tallest.","steps":["Step 1: Compare 5, 9 and 7.","Step 2: The greatest value is 9.","Step 3: Therefore the bar with frequency 9 is tallest."],"options":[],"conceptId":"math_statistics_constructing_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Constructing a Histogram"}', 2),
  (828, 245, 'A graph shows the number of learners choosing Mathematics, English and Biology. Should it be a bar graph or histogram?', 'text', 1, 'Are the values categories or numerical intervals?', '{"why":"Bar graphs represent separate categories.","sol":"Step 1: Mathematics, English and Biology are categories.\nStep 2: They are not numerical class intervals.\nStep 3: Therefore a bar graph is appropriate.","steps":["Step 1: Mathematics, English and Biology are categories.","Step 2: They are not numerical class intervals.","Step 3: Therefore a bar graph is appropriate."],"options":[],"conceptId":"math_statistics_bar_graph_versus_histogram","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Bar Graph versus Histogram"}', 0),
  (829, 245, 'Marks are grouped into 0–9, 10–19 and 20–29. Which graph is appropriate?', 'text', 1, 'These are numerical intervals.', '{"why":"Histograms represent grouped numerical data.","sol":"Step 1: The data are marks.\nStep 2: The marks have been grouped into numerical intervals.\nStep 3: Therefore a histogram is appropriate.","steps":["Step 1: The data are marks.","Step 2: The marks have been grouped into numerical intervals.","Step 3: Therefore a histogram is appropriate."],"options":[],"conceptId":"math_statistics_bar_graph_versus_histogram","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Bar Graph versus Histogram"}', 1),
  (830, 245, 'Why do histogram bars touch while bar graph bars normally have spaces?', 'text', 1, 'Think about what the horizontal axis represents.', '{"why":"The touching bars show that the numerical intervals are continuous or consecutive.","sol":"Step 1: Bar graphs represent separate categories.\nStep 2: Histograms represent consecutive numerical intervals.\nStep 3: Consecutive intervals join one another.\nStep 4: Therefore histogram bars touch.","steps":["Step 1: Bar graphs represent separate categories.","Step 2: Histograms represent consecutive numerical intervals.","Step 3: Consecutive intervals join one another.","Step 4: Therefore histogram bars touch."],"options":[],"conceptId":"math_statistics_bar_graph_versus_histogram","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Bar Graph versus Histogram"}', 2),
  (831, 246, 'A point on a frequency polygon is (25, 8). What is its frequency?', 'text', 1, 'The second coordinate represents frequency.', '{"why":"The vertical coordinate of a frequency polygon point represents frequency.","sol":"Step 1: The point is (25, 8).\nStep 2: The first coordinate is the midpoint.\nStep 3: The second coordinate is the frequency.\nStep 4: Therefore frequency = 8.","steps":["Step 1: The point is (25, 8).","Step 2: The first coordinate is the midpoint.","Step 3: The second coordinate is the frequency.","Step 4: Therefore frequency = 8."],"options":[],"conceptId":"math_statistics_reading_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Reading a Frequency Polygon"}', 0),
  (832, 246, 'A frequency polygon has points with frequencies 3, 9 and 5. Which point is highest?', 'text', 1, 'The largest frequency gives the highest point.', '{"why":"Higher frequency is represented by a higher point.","sol":"Step 1: Compare 3, 9 and 5.\nStep 2: The largest value is 9.\nStep 3: Therefore the point with frequency 9 is highest.","steps":["Step 1: Compare 3, 9 and 5.","Step 2: The largest value is 9.","Step 3: Therefore the point with frequency 9 is highest."],"options":[],"conceptId":"math_statistics_reading_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Reading a Frequency Polygon"}', 1),
  (833, 246, 'A point is plotted at (14.5, 6). What does 14.5 represent?', 'text', 1, 'Look at the first coordinate.', '{"why":"Frequency polygons plot frequency against class midpoint.","sol":"Step 1: The point is (14.5, 6).\nStep 2: The first coordinate gives the horizontal position.\nStep 3: In a frequency polygon this represents the class midpoint.\nStep 4: Therefore 14.5 is the class midpoint.","steps":["Step 1: The point is (14.5, 6).","Step 2: The first coordinate gives the horizontal position.","Step 3: In a frequency polygon this represents the class midpoint.","Step 4: Therefore 14.5 is the class midpoint."],"options":[],"conceptId":"math_statistics_reading_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Reading a Frequency Polygon"}', 2),
  (834, 247, 'Find the midpoint of the class 10–19.', 'text', 1, 'Use (lower limit + upper limit) ÷ 2.', '{"why":"The midpoint is the average of the two class limits.","sol":"Step 1: Lower limit = 10.\nStep 2: Upper limit = 19.\nStep 3: Midpoint = (10 + 19) ÷ 2.\nStep 4: Midpoint = 29 ÷ 2 = 14.5.","steps":["Step 1: Lower limit = 10.","Step 2: Upper limit = 19.","Step 3: Midpoint = (10 + 19) ÷ 2.","Step 4: Midpoint = 29 ÷ 2 = 14.5."],"options":[],"conceptId":"math_statistics_constructing_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Constructing a Frequency Polygon"}', 0),
  (835, 247, 'A class has midpoint 24.5 and frequency 6. What point should be plotted?', 'text', 1, 'Use (midpoint, frequency).', '{"why":"Frequency polygons plot class midpoint against frequency.","sol":"Step 1: Horizontal coordinate = midpoint = 24.5.\nStep 2: Vertical coordinate = frequency = 6.\nStep 3: Therefore the point is (24.5, 6).","steps":["Step 1: Horizontal coordinate = midpoint = 24.5.","Step 2: Vertical coordinate = frequency = 6.","Step 3: Therefore the point is (24.5, 6)."],"options":[],"conceptId":"math_statistics_constructing_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Constructing a Frequency Polygon"}', 1),
  (836, 247, 'For the class 30–39 with frequency 9, what point is plotted?', 'text', 1, 'First find the midpoint.', '{"why":"The midpoint becomes the x-coordinate and frequency becomes the y-coordinate.","sol":"Step 1: Midpoint = (30 + 39) ÷ 2.\nStep 2: Midpoint = 69 ÷ 2.\nStep 3: Midpoint = 34.5.\nStep 4: Frequency = 9.\nStep 5: Therefore the point is (34.5, 9).","steps":["Step 1: Midpoint = (30 + 39) ÷ 2.","Step 2: Midpoint = 69 ÷ 2.","Step 3: Midpoint = 34.5.","Step 4: Frequency = 9.","Step 5: Therefore the point is (34.5, 9)."],"options":[],"conceptId":"math_statistics_constructing_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Constructing a Frequency Polygon"}', 2),
  (837, 248, 'A frequency polygon has frequencies 4, 9 and 6. Which class has the greatest frequency?', 'text', 1, 'Find the largest frequency.', '{"why":"The highest point represents the greatest frequency.","sol":"Step 1: Compare 4, 9 and 6.\nStep 2: The largest is 9.\nStep 3: Therefore the class represented by frequency 9 has the greatest frequency.","steps":["Step 1: Compare 4, 9 and 6.","Step 2: The largest is 9.","Step 3: Therefore the class represented by frequency 9 has the greatest frequency."],"options":[],"conceptId":"math_statistics_interpreting_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Interpreting a Frequency Polygon"}', 0),
  (838, 248, 'Two consecutive classes have frequencies 10 and 7. How many fewer observations are in the second class?', 'text', 1, 'Subtract the smaller frequency from the larger one.', '{"why":"The second class contains 3 fewer observations.","sol":"Step 1: First class = 10.\nStep 2: Second class = 7.\nStep 3: Difference = 10 − 7.\nStep 4: Difference = 3.","steps":["Step 1: First class = 10.","Step 2: Second class = 7.","Step 3: Difference = 10 − 7.","Step 4: Difference = 3."],"options":[],"conceptId":"math_statistics_interpreting_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Interpreting a Frequency Polygon"}', 1),
  (839, 248, 'A frequency polygon reaches its highest point at midpoint 44.5. What does this tell you?', 'text', 1, 'Think about what the highest point means.', '{"why":"The highest point of a frequency polygon corresponds to the greatest frequency.","sol":"Step 1: The highest point represents the greatest frequency.\nStep 2: Its midpoint is 44.5.\nStep 3: Therefore the class centred at 44.5 has the greatest frequency.","steps":["Step 1: The highest point represents the greatest frequency.","Step 2: Its midpoint is 44.5.","Step 3: Therefore the class centred at 44.5 has the greatest frequency."],"options":[],"conceptId":"math_statistics_interpreting_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Interpreting a Frequency Polygon"}', 2),
  (840, 249, 'Representation A has frequencies 4, 7, 6. Representation B also has 4, 7, 6. Do they agree?', 'text', 1, 'Compare corresponding frequencies.', '{"why":"The two representations contain the same frequencies for every class.","sol":"Step 1: First frequency: 4 = 4.\nStep 2: Second frequency: 7 = 7.\nStep 3: Third frequency: 6 = 6.\nStep 4: All corresponding frequencies agree.","steps":["Step 1: First frequency: 4 = 4.","Step 2: Second frequency: 7 = 7.","Step 3: Third frequency: 6 = 6.","Step 4: All corresponding frequencies agree."],"options":[],"conceptId":"math_statistics_comparing_two_data_representations","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Comparing Two Data Representations"}', 0),
  (841, 249, 'One representation gives a frequency of 9 while another gives 6 for the same class. What is the difference?', 'text', 1, 'Subtract 6 from 9.', '{"why":"The representations disagree by 3 observations for that class.","sol":"Step 1: First frequency = 9.\nStep 2: Second frequency = 6.\nStep 3: Difference = 9 − 6.\nStep 4: Difference = 3.","steps":["Step 1: First frequency = 9.","Step 2: Second frequency = 6.","Step 3: Difference = 9 − 6.","Step 4: Difference = 3."],"options":[],"conceptId":"math_statistics_comparing_two_data_representations","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Comparing Two Data Representations"}', 1),
  (842, 249, 'Why should corresponding class frequencies be compared when checking two graphs?', 'text', 1, 'Think about what a graph is representing.', '{"why":"Matching corresponding frequencies verifies that the representations agree.","sol":"Step 1: Each graph represents frequencies for particular classes.\nStep 2: The same class must have the same frequency if the graphs represent the same data.\nStep 3: Therefore corresponding classes must be compared.","steps":["Step 1: Each graph represents frequencies for particular classes.","Step 2: The same class must have the same frequency if the graphs represent the same data.","Step 3: Therefore corresponding classes must be compared."],"options":[],"conceptId":"math_statistics_comparing_two_data_representations","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Comparing Two Data Representations"}', 2),
  (843, 250, 'A school wants to compare the number of learners in four houses. Which representation is appropriate?', 'text', 1, 'The houses are separate categories.', '{"why":"Bar graphs are appropriate for comparing separate categories.","sol":"Step 1: The data are grouped by house.\nStep 2: Each house is a separate category.\nStep 3: A bar graph is suitable for separate categories.","steps":["Step 1: The data are grouped by house.","Step 2: Each house is a separate category.","Step 3: A bar graph is suitable for separate categories."],"options":[],"conceptId":"math_statistics_choosing_the_appropriate_data_representation","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Choosing the Appropriate Data Representation"}', 0),
  (844, 250, 'Marks are grouped as 0–9, 10–19, 20–29 and 30–39. Which representation is appropriate?', 'text', 1, 'These are numerical class intervals.', '{"why":"Histograms represent grouped numerical intervals.","sol":"Step 1: The data are marks.\nStep 2: They are grouped into numerical intervals.\nStep 3: A histogram is suitable for grouped numerical data.","steps":["Step 1: The data are marks.","Step 2: They are grouped into numerical intervals.","Step 3: A histogram is suitable for grouped numerical data."],"options":[],"conceptId":"math_statistics_choosing_the_appropriate_data_representation","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Choosing the Appropriate Data Representation"}', 1),
  (845, 250, 'A teacher wants to show frequencies plotted against class midpoints and joined by straight lines. Which representation should be used?', 'text', 1, 'This description defines one particular graph.', '{"why":"A frequency polygon plots frequency against class midpoint and joins the points.","sol":"Step 1: The horizontal values are class midpoints.\nStep 2: The vertical values are frequencies.\nStep 3: The points are joined by straight lines.\nStep 4: This is a frequency polygon.","steps":["Step 1: The horizontal values are class midpoints.","Step 2: The vertical values are frequencies.","Step 3: The points are joined by straight lines.","Step 4: This is a frequency polygon."],"options":[],"conceptId":"math_statistics_choosing_the_appropriate_data_representation","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Choosing the Appropriate Data Representation"}', 2),
  (846, 251, 'A coin is tossed once. Is this a probability experiment?', 'text', 1, 'Ask whether the possible outcomes are known but the actual result is unknown.', '{"why":"A probability experiment has known possible outcomes but an uncertain actual outcome.","sol":"Step 1: The possible outcomes are Head and Tail.\nStep 2: The actual result is not known before the coin is tossed.\nStep 3: Therefore, it is a probability experiment.","steps":["Step 1: The possible outcomes are Head and Tail.","Step 2: The actual result is not known before the coin is tossed.","Step 3: Therefore, it is a probability experiment."],"options":[],"conceptId":"math_probability_probability_experiment","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Probability Experiment"}', 0),
  (847, 251, 'A six-sided die is rolled once. Is this a probability experiment?', 'text', 1, 'List what can happen before deciding.', '{"why":"The possible outcomes are known, but the actual outcome cannot be predicted with certainty.","sol":"Step 1: The possible outcomes are 1, 2, 3, 4, 5 and 6.\nStep 2: The number that will appear is not known before the roll.\nStep 3: Therefore, it is a probability experiment.","steps":["Step 1: The possible outcomes are 1, 2, 3, 4, 5 and 6.","Step 2: The number that will appear is not known before the roll.","Step 3: Therefore, it is a probability experiment."],"options":[],"conceptId":"math_probability_probability_experiment","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Probability Experiment"}', 1),
  (848, 251, 'A bag contains red and green balls. One ball is drawn without looking. Explain why this is a probability experiment.', 'text', 1, 'Think about what is known and what is unknown.', '{"why":"Probability experiments involve uncertainty about which known possible outcome will occur.","sol":"Step 1: The possible outcomes include red and green.\nStep 2: The colour of the ball is not known before the draw.\nStep 3: Therefore, the draw is a probability experiment.","steps":["Step 1: The possible outcomes include red and green.","Step 2: The colour of the ball is not known before the draw.","Step 3: Therefore, the draw is a probability experiment."],"options":[],"conceptId":"math_probability_probability_experiment","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Probability Experiment"}', 2),
  (849, 252, 'A coin is tossed once. List all possible outcomes.', 'text', 1, 'A coin has two possible results.', '{"why":"These are the two possible results of one coin toss.","sol":"Step 1: A coin can land on Head.\nStep 2: A coin can land on Tail.\nStep 3: Therefore the outcomes are {H, T}.","steps":["Step 1: A coin can land on Head.","Step 2: A coin can land on Tail.","Step 3: Therefore the outcomes are {H, T}."],"options":[],"conceptId":"math_probability_outcomes_of_an_experiment","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Outcomes of an Experiment"}', 0),
  (850, 252, 'A standard die is rolled once. List all possible outcomes.', 'text', 1, 'A standard die has six numbered faces.', '{"why":"Each face of the die represents one possible outcome.","sol":"Step 1: The die can show 1.\nStep 2: It can show 2, 3, 4, 5 or 6.\nStep 3: Therefore the outcomes are {1, 2, 3, 4, 5, 6}.","steps":["Step 1: The die can show 1.","Step 2: It can show 2, 3, 4, 5 or 6.","Step 3: Therefore the outcomes are {1, 2, 3, 4, 5, 6}."],"options":[],"conceptId":"math_probability_outcomes_of_an_experiment","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Outcomes of an Experiment"}', 1),
  (851, 252, 'A bag contains red, blue and yellow balls. One ball is selected. What are the possible colour outcomes?', 'text', 1, 'Record colours, not individual balls.', '{"why":"The question asks for possible colour outcomes.","sol":"Step 1: A red ball may be selected.\nStep 2: A blue ball may be selected.\nStep 3: A yellow ball may be selected.\nStep 4: Therefore the outcomes are {Red, Blue, Yellow}.","steps":["Step 1: A red ball may be selected.","Step 2: A blue ball may be selected.","Step 3: A yellow ball may be selected.","Step 4: Therefore the outcomes are {Red, Blue, Yellow}."],"options":[],"conceptId":"math_probability_outcomes_of_an_experiment","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Outcomes of an Experiment"}', 2),
  (852, 253, 'A coin is tossed 8 times and gives H, T, H, H, T, H, T, H. How many Heads occurred?', 'text', 1, 'Count every H.', '{"why":"Frequency tells us how many times an outcome occurred.","sol":"Step 1: The Heads are in positions 1, 3, 4, 6 and 8.\nStep 2: There are 5 Heads.\nStep 3: Therefore, the frequency of Heads is 5.","steps":["Step 1: The Heads are in positions 1, 3, 4, 6 and 8.","Step 2: There are 5 Heads.","Step 3: Therefore, the frequency of Heads is 5."],"options":[],"conceptId":"math_probability_recording_experimental_results","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Recording Experimental Results"}', 0),
  (853, 253, 'A die is rolled 10 times. The number 4 appears 3 times. What is the frequency of 4?', 'text', 1, 'Frequency means the number of times an outcome occurs.', '{"why":"The frequency of an outcome is simply how many times it occurred.","sol":"Step 1: The number 4 occurred 3 times.\nStep 2: Therefore, its frequency is 3.","steps":["Step 1: The number 4 occurred 3 times.","Step 2: Therefore, its frequency is 3."],"options":[],"conceptId":"math_probability_recording_experimental_results","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Recording Experimental Results"}', 1),
  (854, 253, 'A coin is tossed 20 times. Heads occur 11 times. How many Tails occurred?', 'text', 1, 'Every trial gives either Head or Tail.', '{"why":"The Head and Tail frequencies must add to the total number of tosses.","sol":"Step 1: Total tosses = 20.\nStep 2: Heads = 11.\nStep 3: Tails = 20 − 11.\nStep 4: Tails = 9.","steps":["Step 1: Total tosses = 20.","Step 2: Heads = 11.","Step 3: Tails = 20 − 11.","Step 4: Tails = 9."],"options":[],"conceptId":"math_probability_recording_experimental_results","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Recording Experimental Results"}', 2),
  (855, 254, 'A coin is tossed 50 times and Heads occur 27 times. Find the experimental probability of Heads.', 'text', 1, 'Use frequency of Heads ÷ total tosses.', '{"why":"Experimental probability uses the observed frequency divided by the total number of trials.","sol":"Step 1: Heads occurred 27 times.\nStep 2: Total tosses = 50.\nStep 3: P(Head) = 27 ÷ 50.\nStep 4: P(Head) = 27/50.","steps":["Step 1: Heads occurred 27 times.","Step 2: Total tosses = 50.","Step 3: P(Head) = 27 ÷ 50.","Step 4: P(Head) = 27/50."],"options":[],"conceptId":"math_probability_calculating_experimental_probability","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Calculating Experimental Probability"}', 0),
  (856, 254, 'A die is rolled 40 times and the number 3 appears 7 times. Find the experimental probability of rolling 3.', 'text', 1, 'Divide 7 by 40.', '{"why":"The observed frequency of 3 is 7 out of 40 rolls.","sol":"Step 1: Frequency of 3 = 7.\nStep 2: Total trials = 40.\nStep 3: P(3) = 7 ÷ 40.\nStep 4: P(3) = 7/40.","steps":["Step 1: Frequency of 3 = 7.","Step 2: Total trials = 40.","Step 3: P(3) = 7 ÷ 40.","Step 4: P(3) = 7/40."],"options":[],"conceptId":"math_probability_calculating_experimental_probability","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Calculating Experimental Probability"}', 1),
  (857, 254, 'A spinner is spun 25 times and lands on blue 10 times. Find the experimental probability of blue.', 'text', 1, 'Observed blue outcomes ÷ total spins.', '{"why":"The experiment produced 10 blue results in 25 trials.","sol":"Step 1: Blue occurred 10 times.\nStep 2: Total spins = 25.\nStep 3: P(Blue) = 10 ÷ 25.\nStep 4: P(Blue) = 2/5.","steps":["Step 1: Blue occurred 10 times.","Step 2: Total spins = 25.","Step 3: P(Blue) = 10 ÷ 25.","Step 4: P(Blue) = 2/5."],"options":[],"conceptId":"math_probability_calculating_experimental_probability","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Calculating Experimental Probability"}', 2),
  (858, 255, 'A fair coin has a theoretical probability of 1/2 of getting Head. In 10 tosses, Head occurs 7 times. Find the experimental probability.', 'text', 1, 'Use observed Heads ÷ total tosses.', '{"why":"Experimental probability is calculated from the actual results of the experiment.","sol":"Step 1: Heads occurred 7 times.\nStep 2: Total tosses = 10.\nStep 3: Experimental probability = 7 ÷ 10.\nStep 4: Experimental probability = 7/10.","steps":["Step 1: Heads occurred 7 times.","Step 2: Total tosses = 10.","Step 3: Experimental probability = 7 ÷ 10.","Step 4: Experimental probability = 7/10."],"options":[],"conceptId":"math_probability_comparing_experimental_and_theoretical_probability","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Comparing Experimental and Theoretical Probability"}', 0),
  (859, 255, 'A fair die has a theoretical probability of 1/6 of rolling a 6. In 60 rolls, 12 sixes occur. Find the experimental probability.', 'text', 1, 'Divide the number of sixes by the number of rolls.', '{"why":"The experimental probability comes from the observed frequency, not the theoretical value.","sol":"Step 1: Six occurred 12 times.\nStep 2: Total rolls = 60.\nStep 3: Experimental probability = 12 ÷ 60.\nStep 4: Experimental probability = 1/5.","steps":["Step 1: Six occurred 12 times.","Step 2: Total rolls = 60.","Step 3: Experimental probability = 12 ÷ 60.","Step 4: Experimental probability = 1/5."],"options":[],"conceptId":"math_probability_comparing_experimental_and_theoretical_probability","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Comparing Experimental and Theoretical Probability"}', 1),
  (860, 255, 'A fair coin is tossed 100 times and gives 49 Heads. Is the experimental probability close to the theoretical probability of 1/2?', 'text', 1, 'Calculate the experimental probability first.', '{"why":"A large number of trials often produces an experimental probability close to the theoretical probability.","sol":"Step 1: Experimental probability = 49 ÷ 100.\nStep 2: Experimental probability = 0.49.\nStep 3: Theoretical probability = 0.50.\nStep 4: The difference is 0.01.\nStep 5: Therefore, the experimental probability is close to the theoretical probability.","steps":["Step 1: Experimental probability = 49 ÷ 100.","Step 2: Experimental probability = 0.49.","Step 3: Theoretical probability = 0.50.","Step 4: The difference is 0.01.","Step 5: Therefore, the experimental probability is close to the theoretical probability."],"options":[],"conceptId":"math_probability_comparing_experimental_and_theoretical_probability","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Comparing Experimental and Theoretical Probability"}', 2),
  (861, 256, 'A coin is tossed once. Write the probability space.', 'text', 1, 'Think of every result that can occur when one coin is tossed.', '{"why":"A single coin toss has exactly two possible outcomes: Head and Tail.","sol":"Step 1: A coin can land showing a Head or a Tail.\nStep 2: Write both possible outcomes.\nStep 3: Therefore S = {H, T}.","steps":["Step 1: A coin can land showing a Head or a Tail.","Step 2: Write both possible outcomes.","Step 3: Therefore S = {H, T}."],"options":[],"conceptId":"math_probability_complete_probability_space","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Complete Probability Space"}', 0),
  (862, 256, 'A standard die is rolled once. Write the probability space.', 'text', 1, 'A standard die has six numbered faces.', '{"why":"Any one of the six faces can appear when the die is rolled.","sol":"Step 1: The smallest number on the die is 1.\nStep 2: The numbers continue through 2, 3, 4 and 5.\nStep 3: The largest number is 6.\nStep 4: Therefore S = {1, 2, 3, 4, 5, 6}.","steps":["Step 1: The smallest number on the die is 1.","Step 2: The numbers continue through 2, 3, 4 and 5.","Step 3: The largest number is 6.","Step 4: Therefore S = {1, 2, 3, 4, 5, 6}."],"options":[],"conceptId":"math_probability_complete_probability_space","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Complete Probability Space"}', 1),
  (863, 256, 'A card is chosen from cards labelled A, B, C and D. Write the probability space.', 'text', 1, 'List every label that can be selected.', '{"why":"The probability space contains every possible result of selecting one card.","sol":"Step 1: The possible cards are A, B, C and D.\nStep 2: Each one is a possible result of the experiment.\nStep 3: Therefore S = {A, B, C, D}.","steps":["Step 1: The possible cards are A, B, C and D.","Step 2: Each one is a possible result of the experiment.","Step 3: Therefore S = {A, B, C, D}."],"options":[],"conceptId":"math_probability_complete_probability_space","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Complete Probability Space"}', 2),
  (864, 257, 'A spinner has four equal sections labelled 1, 2, 3 and 4. List all possible outcomes.', 'text', 1, 'Every label on the spinner can be obtained.', '{"why":"Every labelled section is a possible outcome.","sol":"Step 1: The spinner contains section 1.\nStep 2: It also contains sections 2, 3 and 4.\nStep 3: Any of these sections can be selected.\nStep 4: Therefore S = {1, 2, 3, 4}.","steps":["Step 1: The spinner contains section 1.","Step 2: It also contains sections 2, 3 and 4.","Step 3: Any of these sections can be selected.","Step 4: Therefore S = {1, 2, 3, 4}."],"options":[],"conceptId":"math_probability_listing_outcomes_of_a_single_experiment","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Listing Outcomes of a Single Experiment"}', 0),
  (865, 257, 'One letter is selected from {M, N, P}. List the probability space.', 'text', 1, 'The selected letter can be M, N or P.', '{"why":"These are all the choices available in the experiment.","sol":"Step 1: M is a possible result.\nStep 2: N is a possible result.\nStep 3: P is a possible result.\nStep 4: Therefore S = {M, N, P}.","steps":["Step 1: M is a possible result.","Step 2: N is a possible result.","Step 3: P is a possible result.","Step 4: Therefore S = {M, N, P}."],"options":[],"conceptId":"math_probability_listing_outcomes_of_a_single_experiment","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Listing Outcomes of a Single Experiment"}', 1),
  (866, 257, 'A die is rolled once. A student writes {1, 2, 3, 4, 5}. Is this a complete probability space?', 'text', 1, 'Check whether every possible die result has been included.', '{"why":"A complete probability space for one die must include 6.","sol":"Step 1: A standard die can produce 1, 2, 3, 4, 5 or 6.\nStep 2: The student''s list does not contain 6.\nStep 3: Therefore one possible outcome is missing.\nStep 4: The list is not complete.","steps":["Step 1: A standard die can produce 1, 2, 3, 4, 5 or 6.","Step 2: The student''s list does not contain 6.","Step 3: Therefore one possible outcome is missing.","Step 4: The list is not complete."],"options":[],"conceptId":"math_probability_listing_outcomes_of_a_single_experiment","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Listing Outcomes of a Single Experiment"}', 2),
  (867, 258, 'A coin is tossed twice. Write the complete probability space.', 'text', 1, 'Start with H on the first toss, then T on the first toss.', '{"why":"Each of the two tosses can be H or T, producing four ordered outcomes.","sol":"Step 1: If the first toss is H, the second toss can be H or T: HH, HT.\nStep 2: If the first toss is T, the second toss can be H or T: TH, TT.\nStep 3: Combine all four outcomes.\nStep 4: Therefore S = {HH, HT, TH, TT}.","steps":["Step 1: If the first toss is H, the second toss can be H or T: HH, HT.","Step 2: If the first toss is T, the second toss can be H or T: TH, TT.","Step 3: Combine all four outcomes.","Step 4: Therefore S = {HH, HT, TH, TT}."],"options":[],"conceptId":"math_probability_probability_space_for_two_coin_tosses","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Probability Space for Two Coin Tosses"}', 0),
  (868, 258, 'A student says that HH and TT are the only possible outcomes when a coin is tossed twice. What is wrong?', 'text', 1, 'Consider what happens when the two tosses are different.', '{"why":"Two tosses can have different results, not only matching results.","sol":"Step 1: The first toss can be H and the second T, giving HT.\nStep 2: The first toss can also be T and the second H, giving TH.\nStep 3: Therefore HT and TH are also possible.\nStep 4: The student''s list is incomplete.","steps":["Step 1: The first toss can be H and the second T, giving HT.","Step 2: The first toss can also be T and the second H, giving TH.","Step 3: Therefore HT and TH are also possible.","Step 4: The student''s list is incomplete."],"options":[],"conceptId":"math_probability_probability_space_for_two_coin_tosses","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Probability Space for Two Coin Tosses"}', 1),
  (869, 258, 'Explain why HT and TH are different outcomes.', 'text', 1, 'Look at the order of the two tosses.', '{"why":"An outcome of a repeated experiment records what happened at each stage.","sol":"Step 1: HT means H occurs first and T occurs second.\nStep 2: TH means T occurs first and H occurs second.\nStep 3: The order of the results is different.\nStep 4: Therefore they represent different outcomes.","steps":["Step 1: HT means H occurs first and T occurs second.","Step 2: TH means T occurs first and H occurs second.","Step 3: The order of the results is different.","Step 4: Therefore they represent different outcomes."],"options":[],"conceptId":"math_probability_probability_space_for_two_coin_tosses","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Probability Space for Two Coin Tosses"}', 2),
  (870, 259, 'A die is rolled and then a coin is tossed. List all possible outcomes.', 'text', 1, 'For every die result, attach H and T.', '{"why":"Each of the 6 die results can be followed by either H or T.","sol":"Step 1: The die can give 1, 2, 3, 4, 5 or 6.\nStep 2: For each die result, the coin can give H or T.\nStep 3: Therefore the outcomes are 1H, 1T, 2H, 2T, 3H, 3T, 4H, 4T, 5H, 5T, 6H, 6T.\nStep 4: There are 12 outcomes.","steps":["Step 1: The die can give 1, 2, 3, 4, 5 or 6.","Step 2: For each die result, the coin can give H or T.","Step 3: Therefore the outcomes are 1H, 1T, 2H, 2T, 3H, 3T, 4H, 4T, 5H, 5T, 6H, 6T.","Step 4: There are 12 outcomes."],"options":[],"conceptId":"math_probability_systematically_listing_two_stage_outcomes","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Systematically Listing Two-Stage Outcomes"}', 0),
  (871, 259, 'A spinner has A or B. A coin is then tossed. List all possible outcomes.', 'text', 1, 'Start with A, then start with B.', '{"why":"Every first-stage outcome must be paired with every possible second-stage outcome.","sol":"Step 1: If the spinner gives A, the coin can give H or T: AH, AT.\nStep 2: If the spinner gives B, the coin can give H or T: BH, BT.\nStep 3: Therefore S = {AH, AT, BH, BT}.","steps":["Step 1: If the spinner gives A, the coin can give H or T: AH, AT.","Step 2: If the spinner gives B, the coin can give H or T: BH, BT.","Step 3: Therefore S = {AH, AT, BH, BT}."],"options":[],"conceptId":"math_probability_systematically_listing_two_stage_outcomes","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Systematically Listing Two-Stage Outcomes"}', 1),
  (872, 259, 'A two-stage experiment has first-stage outcomes P and Q, and second-stage outcomes 1, 2 and 3. List all possible outcomes.', 'text', 1, 'Pair P with all three numbers, then Q with all three numbers.', '{"why":"There are 2 choices at the first stage and 3 choices at the second stage, giving 6 combinations.","sol":"Step 1: Starting with P gives P1, P2 and P3.\nStep 2: Starting with Q gives Q1, Q2 and Q3.\nStep 3: Combine the outcomes.\nStep 4: Therefore S = {P1, P2, P3, Q1, Q2, Q3}.","steps":["Step 1: Starting with P gives P1, P2 and P3.","Step 2: Starting with Q gives Q1, Q2 and Q3.","Step 3: Combine the outcomes.","Step 4: Therefore S = {P1, P2, P3, Q1, Q2, Q3}."],"options":[],"conceptId":"math_probability_systematically_listing_two_stage_outcomes","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Systematically Listing Two-Stage Outcomes"}', 2),
  (873, 260, 'A fair die is rolled. Find the probability of getting 5.', 'text', 1, 'First write the complete probability space.', '{"why":"One of the six equally likely die outcomes is 5.","sol":"Step 1: The probability space is {1, 2, 3, 4, 5, 6}.\nStep 2: Only 5 is favourable, so there is 1 favourable outcome.\nStep 3: There are 6 possible outcomes in total.\nStep 4: Therefore P(5) = 1/6.","steps":["Step 1: The probability space is {1, 2, 3, 4, 5, 6}.","Step 2: Only 5 is favourable, so there is 1 favourable outcome.","Step 3: There are 6 possible outcomes in total.","Step 4: Therefore P(5) = 1/6."],"options":[],"conceptId":"math_probability_theoretical_probability_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Theoretical Probability from a Probability Space"}', 0),
  (874, 260, 'A fair die is rolled. Find the probability of getting an odd number.', 'text', 1, 'Identify the odd outcomes in {1, 2, 3, 4, 5, 6}.', '{"why":"Three of the six equally likely die outcomes are odd.","sol":"Step 1: The odd outcomes are 1, 3 and 5.\nStep 2: There are 3 favourable outcomes.\nStep 3: There are 6 total outcomes.\nStep 4: Therefore P(odd) = 3/6.\nStep 5: Simplify 3/6 by dividing by 3.\nStep 6: P(odd) = 1/2.","steps":["Step 1: The odd outcomes are 1, 3 and 5.","Step 2: There are 3 favourable outcomes.","Step 3: There are 6 total outcomes.","Step 4: Therefore P(odd) = 3/6.","Step 5: Simplify 3/6 by dividing by 3.","Step 6: P(odd) = 1/2."],"options":[],"conceptId":"math_probability_theoretical_probability_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Theoretical Probability from a Probability Space"}', 1),
  (875, 260, 'A fair coin is tossed twice. Find the probability of getting exactly two tails.', 'text', 1, 'Use the probability space for two coin tosses.', '{"why":"TT is the only outcome containing two tails.","sol":"Step 1: The probability space is {HH, HT, TH, TT}.\nStep 2: Exactly two tails occurs only in TT.\nStep 3: There is 1 favourable outcome.\nStep 4: There are 4 total outcomes.\nStep 5: Therefore P(two tails) = 1/4.","steps":["Step 1: The probability space is {HH, HT, TH, TT}.","Step 2: Exactly two tails occurs only in TT.","Step 3: There is 1 favourable outcome.","Step 4: There are 4 total outcomes.","Step 5: Therefore P(two tails) = 1/4."],"options":[],"conceptId":"math_probability_theoretical_probability_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Theoretical Probability from a Probability Space"}', 2),
  (876, 261, 'A standard die is rolled. What is the probability of getting 9?', 'text', 1, 'Check whether 9 is one of the possible die outcomes.', '{"why":"A standard die cannot produce 9.","sol":"Step 1: The possible outcomes are 1, 2, 3, 4, 5 and 6.\nStep 2: 9 is not a possible outcome.\nStep 3: Therefore there are 0 favourable outcomes.\nStep 4: P(9) = 0/6 = 0.","steps":["Step 1: The possible outcomes are 1, 2, 3, 4, 5 and 6.","Step 2: 9 is not a possible outcome.","Step 3: Therefore there are 0 favourable outcomes.","Step 4: P(9) = 0/6 = 0."],"options":[],"conceptId":"math_probability_impossible_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Impossible Events"}', 0),
  (877, 261, 'A bag contains only red and blue balls. One ball is selected. What is the probability of selecting a green ball?', 'text', 1, 'Is green one of the possible colours in the bag?', '{"why":"There is no green ball available to be selected.","sol":"Step 1: The only possible colours are red and blue.\nStep 2: Green is not in the bag.\nStep 3: Therefore selecting green is impossible.\nStep 4: The probability is 0.","steps":["Step 1: The only possible colours are red and blue.","Step 2: Green is not in the bag.","Step 3: Therefore selecting green is impossible.","Step 4: The probability is 0."],"options":[],"conceptId":"math_probability_impossible_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Impossible Events"}', 1),
  (878, 261, 'A coin is tossed once. What is the probability of getting both Head and Tail?', 'text', 1, 'A single toss produces only one result.', '{"why":"One coin toss gives one outcome, not two outcomes at the same time.","sol":"Step 1: The possible outcomes are H and T.\nStep 2: One toss cannot produce H and T simultaneously.\nStep 3: Therefore the event is impossible.\nStep 4: Its probability is 0.","steps":["Step 1: The possible outcomes are H and T.","Step 2: One toss cannot produce H and T simultaneously.","Step 3: Therefore the event is impossible.","Step 4: Its probability is 0."],"options":[],"conceptId":"math_probability_impossible_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Impossible Events"}', 2),
  (879, 262, 'A standard die is rolled. Find the probability of getting a number less than 7.', 'text', 1, 'Check every possible result of the die.', '{"why":"Every possible result of a standard die is less than 7.","sol":"Step 1: The outcomes are 1, 2, 3, 4, 5 and 6.\nStep 2: Every one of these numbers is less than 7.\nStep 3: Therefore there are 6 favourable outcomes out of 6.\nStep 4: P(number less than 7) = 6/6 = 1.","steps":["Step 1: The outcomes are 1, 2, 3, 4, 5 and 6.","Step 2: Every one of these numbers is less than 7.","Step 3: Therefore there are 6 favourable outcomes out of 6.","Step 4: P(number less than 7) = 6/6 = 1."],"options":[],"conceptId":"math_probability_certain_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Certain Events"}', 0),
  (880, 262, 'A coin is tossed once. What is the probability of getting either Head or Tail?', 'text', 1, 'These are the only two possible outcomes.', '{"why":"A coin must show either Head or Tail when tossed.","sol":"Step 1: The probability space is {H, T}.\nStep 2: Both possible outcomes satisfy the event.\nStep 3: Therefore there are 2 favourable outcomes out of 2.\nStep 4: P(event) = 2/2 = 1.","steps":["Step 1: The probability space is {H, T}.","Step 2: Both possible outcomes satisfy the event.","Step 3: Therefore there are 2 favourable outcomes out of 2.","Step 4: P(event) = 2/2 = 1."],"options":[],"conceptId":"math_probability_certain_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Certain Events"}', 1),
  (881, 262, 'Cards labelled 2, 4 and 6 are placed in a bag. One card is selected. Find the probability of selecting an even number.', 'text', 1, 'Check each card.', '{"why":"Every available card contains an even number.","sol":"Step 1: The possible outcomes are 2, 4 and 6.\nStep 2: All three numbers are even.\nStep 3: Therefore there are 3 favourable outcomes out of 3.\nStep 4: P(even) = 3/3 = 1.","steps":["Step 1: The possible outcomes are 2, 4 and 6.","Step 2: All three numbers are even.","Step 3: Therefore there are 3 favourable outcomes out of 3.","Step 4: P(even) = 3/3 = 1."],"options":[],"conceptId":"math_probability_certain_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Certain Events"}', 2),
  (882, 263, 'Which of the following can be a probability: 0, 0.4, 1 or 1.3?', 'text', 1, 'A probability must lie from 0 to 1 inclusive.', '{"why":"Valid probabilities satisfy 0 ≤ P(E) ≤ 1.","sol":"Step 1: 0 is allowed because an impossible event has probability 0.\nStep 2: 0.4 is between 0 and 1.\nStep 3: 1 is allowed because a certain event has probability 1.\nStep 4: 1.3 is greater than 1 and therefore cannot be a probability.","steps":["Step 1: 0 is allowed because an impossible event has probability 0.","Step 2: 0.4 is between 0 and 1.","Step 3: 1 is allowed because a certain event has probability 1.","Step 4: 1.3 is greater than 1 and therefore cannot be a probability."],"options":[],"conceptId":"math_probability_probability_between_0_and_1","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Probability Between 0 and 1"}', 0),
  (883, 263, 'Can 1.2 be the probability of an event? Explain.', 'text', 1, 'Compare 1.2 with the upper limit of probability.', '{"why":"A probability cannot be greater than 1.","sol":"Step 1: The greatest possible probability is 1.\nStep 2: 1.2 is greater than 1.\nStep 3: Therefore 1.2 cannot represent a probability.","steps":["Step 1: The greatest possible probability is 1.","Step 2: 1.2 is greater than 1.","Step 3: Therefore 1.2 cannot represent a probability."],"options":[],"conceptId":"math_probability_probability_between_0_and_1","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Probability Between 0 and 1"}', 1),
  (884, 263, 'Can -0.3 be the probability of an event? Explain.', 'text', 1, 'Compare -0.3 with the lower limit of probability.', '{"why":"A probability cannot be negative.","sol":"Step 1: The smallest possible probability is 0.\nStep 2: -0.3 is less than 0.\nStep 3: Therefore -0.3 cannot represent a probability.","steps":["Step 1: The smallest possible probability is 0.","Step 2: -0.3 is less than 0.","Step 3: Therefore -0.3 cannot represent a probability."],"options":[],"conceptId":"math_probability_probability_between_0_and_1","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Probability Between 0 and 1"}', 2),
  (885, 264, 'What does a probability of 0 mean?', 'text', 1, 'Think about whether the event can happen.', '{"why":"Probability 0 represents an event that cannot occur.","sol":"Step 1: A probability of 0 is the lowest possible probability.\nStep 2: An event with probability 0 cannot happen.\nStep 3: Therefore the event is impossible.","steps":["Step 1: A probability of 0 is the lowest possible probability.","Step 2: An event with probability 0 cannot happen.","Step 3: Therefore the event is impossible."],"options":[],"conceptId":"math_probability_interpreting_probability_values","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Interpreting Probability Values"}', 0),
  (886, 264, 'What does a probability of 1 mean?', 'text', 1, 'Think about the highest possible probability.', '{"why":"Probability 1 represents an event that must occur.","sol":"Step 1: A probability of 1 is the highest possible probability.\nStep 2: An event with probability 1 must happen.\nStep 3: Therefore the event is certain.","steps":["Step 1: A probability of 1 is the highest possible probability.","Step 2: An event with probability 1 must happen.","Step 3: Therefore the event is certain."],"options":[],"conceptId":"math_probability_interpreting_probability_values","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Interpreting Probability Values"}', 1),
  (887, 264, 'Which event is more certain: Event A with probability 0.2 or Event B with probability 0.8?', 'text', 1, 'Compare the two values.', '{"why":"A larger probability represents a greater likelihood of the event occurring.","sol":"Step 1: Event A has probability 0.2.\nStep 2: Event B has probability 0.8.\nStep 3: 0.8 is closer to 1 than 0.2.\nStep 4: Therefore Event B is more likely to occur.","steps":["Step 1: Event A has probability 0.2.","Step 2: Event B has probability 0.8.","Step 3: 0.8 is closer to 1 than 0.2.","Step 4: Therefore Event B is more likely to occur."],"options":[],"conceptId":"math_probability_interpreting_probability_values","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Interpreting Probability Values"}', 2),
  (888, 265, 'Is 0.65 a valid probability?', 'text', 1, 'Check whether 0.65 lies between 0 and 1.', '{"why":"0.65 lies within the probability range from 0 to 1.","sol":"Step 1: 0.65 is greater than 0.\nStep 2: 0.65 is less than 1.\nStep 3: Therefore 0 ≤ 0.65 ≤ 1.\nStep 4: So 0.65 is a valid probability.","steps":["Step 1: 0.65 is greater than 0.","Step 2: 0.65 is less than 1.","Step 3: Therefore 0 ≤ 0.65 ≤ 1.","Step 4: So 0.65 is a valid probability."],"options":[],"conceptId":"math_probability_checking_whether_a_probability_is_valid","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Checking Whether a Probability Is Valid"}', 0),
  (889, 265, 'Is -1/3 a valid probability?', 'text', 1, 'A probability cannot be less than 0.', '{"why":"Probabilities cannot be negative.","sol":"Step 1: -1/3 is less than 0.\nStep 2: Therefore it violates the lower limit.\nStep 3: So -1/3 cannot be a probability.","steps":["Step 1: -1/3 is less than 0.","Step 2: Therefore it violates the lower limit.","Step 3: So -1/3 cannot be a probability."],"options":[],"conceptId":"math_probability_checking_whether_a_probability_is_valid","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Checking Whether a Probability Is Valid"}', 1),
  (890, 265, 'Is 7/6 a valid probability?', 'text', 1, 'Compare 7/6 with 1.', '{"why":"The value is greater than the maximum possible probability, 1.","sol":"Step 1: 7/6 is greater than 6/6.\nStep 2: 6/6 = 1.\nStep 3: Therefore 7/6 > 1.\nStep 4: A probability cannot be greater than 1.\nStep 5: So 7/6 is not a valid probability.","steps":["Step 1: 7/6 is greater than 6/6.","Step 2: 6/6 = 1.","Step 3: Therefore 7/6 > 1.","Step 4: A probability cannot be greater than 1.","Step 5: So 7/6 is not a valid probability."],"options":[],"conceptId":"math_probability_checking_whether_a_probability_is_valid","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Checking Whether a Probability Is Valid"}', 2),
  (891, 266, 'A coin is tossed once. Are getting Head and getting Tail mutually exclusive?', 'text', 1, 'Can one toss produce both results at the same time?', '{"why":"Head and Tail cannot occur together in one coin toss.","sol":"Step 1: One coin toss produces one result.\nStep 2: The result can be Head or Tail.\nStep 3: It cannot be Head and Tail at the same time.\nStep 4: Therefore the events are mutually exclusive.","steps":["Step 1: One coin toss produces one result.","Step 2: The result can be Head or Tail.","Step 3: It cannot be Head and Tail at the same time.","Step 4: Therefore the events are mutually exclusive."],"options":[],"conceptId":"math_probability_meaning_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Meaning of Mutually Exclusive Events"}', 0),
  (892, 266, 'A die is rolled once. Are getting 2 and getting 6 mutually exclusive?', 'text', 1, 'Can one roll have both 2 and 6 as its result?', '{"why":"A single die roll cannot produce two different numbers.","sol":"Step 1: One die roll produces one number.\nStep 2: The result cannot be both 2 and 6.\nStep 3: Therefore the two events cannot occur together.\nStep 4: They are mutually exclusive.","steps":["Step 1: One die roll produces one number.","Step 2: The result cannot be both 2 and 6.","Step 3: Therefore the two events cannot occur together.","Step 4: They are mutually exclusive."],"options":[],"conceptId":"math_probability_meaning_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Meaning of Mutually Exclusive Events"}', 1),
  (893, 266, 'One card is selected. Are selecting a red card and selecting a blue card mutually exclusive?', 'text', 1, 'Only one card is selected.', '{"why":"One selected card cannot belong to two different colours at the same time.","sol":"Step 1: Only one card is selected.\nStep 2: That card cannot be red and blue at the same time.\nStep 3: Therefore the two events cannot happen together.\nStep 4: They are mutually exclusive.","steps":["Step 1: Only one card is selected.","Step 2: That card cannot be red and blue at the same time.","Step 3: Therefore the two events cannot happen together.","Step 4: They are mutually exclusive."],"options":[],"conceptId":"math_probability_meaning_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Meaning of Mutually Exclusive Events"}', 2),
  (894, 267, 'A die is rolled once. Event A is getting {1, 2, 3}. Event B is getting {4, 5, 6}. Are they mutually exclusive?', 'text', 1, 'Look for a number appearing in both sets.', '{"why":"The two events have no outcome in common.","sol":"Step 1: Event A contains 1, 2 and 3.\nStep 2: Event B contains 4, 5 and 6.\nStep 3: There is no common outcome.\nStep 4: Therefore the events are mutually exclusive.","steps":["Step 1: Event A contains 1, 2 and 3.","Step 2: Event B contains 4, 5 and 6.","Step 3: There is no common outcome.","Step 4: Therefore the events are mutually exclusive."],"options":[],"conceptId":"math_probability_identifying_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Identifying Mutually Exclusive Events"}', 0),
  (895, 267, 'A die is rolled once. Event A is getting {2, 4, 6}. Event B is getting {1, 2, 3}. Are they mutually exclusive?', 'text', 1, 'Check whether the two sets have a common number.', '{"why":"The events share the outcome 2.","sol":"Step 1: Event A contains 2, 4 and 6.\nStep 2: Event B contains 1, 2 and 3.\nStep 3: The number 2 appears in both events.\nStep 4: Therefore both events can occur when the die shows 2.\nStep 5: They are not mutually exclusive.","steps":["Step 1: Event A contains 2, 4 and 6.","Step 2: Event B contains 1, 2 and 3.","Step 3: The number 2 appears in both events.","Step 4: Therefore both events can occur when the die shows 2.","Step 5: They are not mutually exclusive."],"options":[],"conceptId":"math_probability_identifying_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Identifying Mutually Exclusive Events"}', 1),
  (896, 267, 'A die is rolled once. Event A is getting a number less than 3. Event B is getting a number greater than 4. Are they mutually exclusive?', 'text', 1, 'Write the outcomes belonging to each event.', '{"why":"No die result can be both less than 3 and greater than 4.","sol":"Step 1: Numbers less than 3 are {1, 2}.\nStep 2: Numbers greater than 4 are {5, 6}.\nStep 3: There is no common outcome.\nStep 4: Therefore the events are mutually exclusive.","steps":["Step 1: Numbers less than 3 are {1, 2}.","Step 2: Numbers greater than 4 are {5, 6}.","Step 3: There is no common outcome.","Step 4: Therefore the events are mutually exclusive."],"options":[],"conceptId":"math_probability_identifying_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Identifying Mutually Exclusive Events"}', 2),
  (897, 268, 'Given S = {1, 2, 3, 4, 5, 6}, A = {1, 2} and B = {3, 4}, determine whether A and B are mutually exclusive.', 'text', 1, 'Look for a common outcome.', '{"why":"The two events do not share any possible outcome.","sol":"Step 1: Event A contains 1 and 2.\nStep 2: Event B contains 3 and 4.\nStep 3: There is no outcome common to both events.\nStep 4: Therefore A and B are mutually exclusive.","steps":["Step 1: Event A contains 1 and 2.","Step 2: Event B contains 3 and 4.","Step 3: There is no outcome common to both events.","Step 4: Therefore A and B are mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events from a Probability Space"}', 0),
  (898, 268, 'Given S = {1, 2, 3, 4, 5, 6}, A = {2, 4} and B = {1, 3, 5}, determine whether A and B are mutually exclusive.', 'text', 1, 'Compare the two sets.', '{"why":"The events have no common outcome.","sol":"Step 1: A contains 2 and 4.\nStep 2: B contains 1, 3 and 5.\nStep 3: There is no number common to both.\nStep 4: Therefore A and B are mutually exclusive.","steps":["Step 1: A contains 2 and 4.","Step 2: B contains 1, 3 and 5.","Step 3: There is no number common to both.","Step 4: Therefore A and B are mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events from a Probability Space"}', 1),
  (899, 268, 'Given S = {1, 2, 3, 4, 5, 6}, A = {2, 3} and B = {3, 5}, determine whether A and B are mutually exclusive.', 'text', 1, 'Check the number 3.', '{"why":"The events share the outcome 3.","sol":"Step 1: Event A contains 2 and 3.\nStep 2: Event B contains 3 and 5.\nStep 3: The outcome 3 belongs to both events.\nStep 4: Therefore both events can occur when the outcome is 3.\nStep 5: They are not mutually exclusive.","steps":["Step 1: Event A contains 2 and 3.","Step 2: Event B contains 3 and 5.","Step 3: The outcome 3 belongs to both events.","Step 4: Therefore both events can occur when the outcome is 3.","Step 5: They are not mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events from a Probability Space"}', 2),
  (900, 269, 'A die is rolled once. A is getting an odd number and B is getting an even number. Are A and B mutually exclusive?', 'text', 1, 'Can one number be both odd and even?', '{"why":"A number cannot be both odd and even.","sol":"Step 1: The possible results are 1, 2, 3, 4, 5 and 6.\nStep 2: Odd results are 1, 3 and 5.\nStep 3: Even results are 2, 4 and 6.\nStep 4: No result is both odd and even.\nStep 5: Therefore A and B are mutually exclusive.","steps":["Step 1: The possible results are 1, 2, 3, 4, 5 and 6.","Step 2: Odd results are 1, 3 and 5.","Step 3: Even results are 2, 4 and 6.","Step 4: No result is both odd and even.","Step 5: Therefore A and B are mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_in_an_experiment","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events in an Experiment"}', 0),
  (901, 269, 'A die is rolled once. A is getting 1 and B is getting an even number. Are A and B mutually exclusive?', 'text', 1, 'Is 1 an even number?', '{"why":"Getting 1 cannot occur at the same time as getting an even number.","sol":"Step 1: Event A happens only when the result is 1.\nStep 2: Event B happens when the result is 2, 4 or 6.\nStep 3: The result 1 is not even.\nStep 4: Therefore no result can make both events happen.\nStep 5: They are mutually exclusive.","steps":["Step 1: Event A happens only when the result is 1.","Step 2: Event B happens when the result is 2, 4 or 6.","Step 3: The result 1 is not even.","Step 4: Therefore no result can make both events happen.","Step 5: They are mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_in_an_experiment","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events in an Experiment"}', 1),
  (902, 269, 'A die is rolled once. A is getting an even number and B is getting a number greater than 3. Are A and B mutually exclusive?', 'text', 1, 'Try the outcome 4.', '{"why":"The outcome 4 belongs to both events.","sol":"Step 1: 4 is an even number.\nStep 2: 4 is also greater than 3.\nStep 3: Therefore outcome 4 makes both A and B happen.\nStep 4: So the events can happen together.\nStep 5: They are not mutually exclusive.","steps":["Step 1: 4 is an even number.","Step 2: 4 is also greater than 3.","Step 3: Therefore outcome 4 makes both A and B happen.","Step 4: So the events can happen together.","Step 5: They are not mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_in_an_experiment","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events in an Experiment"}', 2),
  (903, 270, 'A = {1, 2} and B = {4, 5}. Are the events mutually exclusive?', 'text', 1, 'Check whether A and B have a common outcome.', '{"why":"The two events cannot occur from the same outcome.","sol":"Step 1: A contains 1 and 2.\nStep 2: B contains 4 and 5.\nStep 3: There is no common outcome.\nStep 4: Therefore the events are mutually exclusive.","steps":["Step 1: A contains 1 and 2.","Step 2: B contains 4 and 5.","Step 3: There is no common outcome.","Step 4: Therefore the events are mutually exclusive."],"options":[],"conceptId":"math_probability_testing_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Testing Mutually Exclusive Events"}', 0),
  (904, 270, 'A = {2, 3, 4} and B = {4, 5, 6}. Are the events mutually exclusive?', 'text', 1, 'Look carefully at both sets.', '{"why":"The events share outcome 4.","sol":"Step 1: A contains 2, 3 and 4.\nStep 2: B contains 4, 5 and 6.\nStep 3: The outcome 4 appears in both sets.\nStep 4: Therefore both events can occur for the same outcome.\nStep 5: They are not mutually exclusive.","steps":["Step 1: A contains 2, 3 and 4.","Step 2: B contains 4, 5 and 6.","Step 3: The outcome 4 appears in both sets.","Step 4: Therefore both events can occur for the same outcome.","Step 5: They are not mutually exclusive."],"options":[],"conceptId":"math_probability_testing_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Testing Mutually Exclusive Events"}', 1),
  (905, 270, 'A = {1, 3, 5} and B = {2, 4, 6}. Are the events mutually exclusive?', 'text', 1, 'Compare every outcome in A with the outcomes in B.', '{"why":"The two events have no common outcome.","sol":"Step 1: A contains 1, 3 and 5.\nStep 2: B contains 2, 4 and 6.\nStep 3: No outcome appears in both sets.\nStep 4: Therefore the events are mutually exclusive.","steps":["Step 1: A contains 1, 3 and 5.","Step 2: B contains 2, 4 and 6.","Step 3: No outcome appears in both sets.","Step 4: Therefore the events are mutually exclusive."],"options":[],"conceptId":"math_probability_testing_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Testing Mutually Exclusive Events"}', 2),
  (906, 271, 'A fair coin is tossed twice. If the first toss is Head, does this change the probability of Head on the second toss?', 'text', 1, 'The first toss does not change the coin.', '{"why":"The two coin tosses are independent.","sol":"Step 1: A fair coin has P(Head) = 1/2.\nStep 2: The first toss produces Head.\nStep 3: The second toss is still a toss of the same fair coin.\nStep 4: Therefore P(Head on the second toss) remains 1/2.\nStep 5: The first result did not affect the second probability.","steps":["Step 1: A fair coin has P(Head) = 1/2.","Step 2: The first toss produces Head.","Step 3: The second toss is still a toss of the same fair coin.","Step 4: Therefore P(Head on the second toss) remains 1/2.","Step 5: The first result did not affect the second probability."],"options":[],"conceptId":"math_probability_meaning_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Meaning of Independent Events"}', 0),
  (907, 271, 'A die is rolled twice. The first roll is 4. Does this change the probability of getting 6 on the second roll?', 'text', 1, 'Ask whether the first roll changes the die.', '{"why":"The first die roll does not affect the second roll.","sol":"Step 1: A standard die has six possible results.\nStep 2: The first roll gives 4.\nStep 3: The die still has all six faces for the second roll.\nStep 4: Therefore P(6 on the second roll) is still 1/6.","steps":["Step 1: A standard die has six possible results.","Step 2: The first roll gives 4.","Step 3: The die still has all six faces for the second roll.","Step 4: Therefore P(6 on the second roll) is still 1/6."],"options":[],"conceptId":"math_probability_meaning_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Meaning of Independent Events"}', 1),
  (908, 271, 'A coin is tossed and then a die is rolled. Does getting Head on the coin change the probability of getting 5 on the die?', 'text', 1, 'Does the coin result change the die?', '{"why":"The two experiments do not affect each other''s probabilities.","sol":"Step 1: Getting Head is an outcome of the coin experiment.\nStep 2: The die still has six possible outcomes.\nStep 3: Therefore the probability of 5 on the die remains 1/6.\nStep 4: The coin result does not affect the die.","steps":["Step 1: Getting Head is an outcome of the coin experiment.","Step 2: The die still has six possible outcomes.","Step 3: Therefore the probability of 5 on the die remains 1/6.","Step 4: The coin result does not affect the die."],"options":[],"conceptId":"math_probability_meaning_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Meaning of Independent Events"}', 2),
  (909, 272, 'A coin is tossed twice. Are getting Head on the first toss and Head on the second toss independent events?', 'text', 1, 'Does the first toss change the second toss?', '{"why":"The result of the first toss does not affect the second toss.","sol":"Step 1: The first toss does not change the coin.\nStep 2: The second toss still has P(Head) = 1/2.\nStep 3: Therefore knowing the first result does not change the second probability.\nStep 4: The events are independent.","steps":["Step 1: The first toss does not change the coin.","Step 2: The second toss still has P(Head) = 1/2.","Step 3: Therefore knowing the first result does not change the second probability.","Step 4: The events are independent."],"options":[],"conceptId":"math_probability_recognising_independent_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Recognising Independent Events"}', 0),
  (910, 272, 'A die is rolled twice. Are getting 3 first and 6 second independent events?', 'text', 1, 'Does rolling 3 remove anything from the die?', '{"why":"One die roll does not affect a later die roll.","sol":"Step 1: The first roll gives 3.\nStep 2: The die still has all six faces for the second roll.\nStep 3: The probability of 6 remains 1/6.\nStep 4: Therefore the events are independent.","steps":["Step 1: The first roll gives 3.","Step 2: The die still has all six faces for the second roll.","Step 3: The probability of 6 remains 1/6.","Step 4: Therefore the events are independent."],"options":[],"conceptId":"math_probability_recognising_independent_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Recognising Independent Events"}', 1),
  (911, 272, 'A bag contains 3 red balls and 2 blue balls. One ball is selected and kept outside the bag. Is the colour of the second selection independent of the first selection?', 'text', 1, 'Does removing the first ball change the contents of the bag?', '{"why":"Removing the first ball changes the composition of the bag.","sol":"Step 1: There are initially 5 balls.\nStep 2: The first ball is not returned.\nStep 3: Therefore only 4 balls remain.\nStep 4: The numbers of red and blue balls remaining depend on the first colour selected.\nStep 5: Therefore the second probability can change.\nStep 6: The selections are not independent.","steps":["Step 1: There are initially 5 balls.","Step 2: The first ball is not returned.","Step 3: Therefore only 4 balls remain.","Step 4: The numbers of red and blue balls remaining depend on the first colour selected.","Step 5: Therefore the second probability can change.","Step 6: The selections are not independent."],"options":[],"conceptId":"math_probability_recognising_independent_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Recognising Independent Events"}', 2),
  (912, 273, 'A bag contains 4 red balls and 1 blue ball. A ball is selected, replaced, and another ball is selected. What is the probability of red on the second selection?', 'text', 1, 'The first ball is returned before the second selection.', '{"why":"Replacement restores the original contents of the bag.","sol":"Step 1: There are 4 red and 1 blue ball initially.\nStep 2: The first ball is replaced.\nStep 3: Therefore the bag still has 4 red and 1 blue ball.\nStep 4: Total balls = 4 + 1 = 5.\nStep 5: P(Red on second selection) = 4/5.","steps":["Step 1: There are 4 red and 1 blue ball initially.","Step 2: The first ball is replaced.","Step 3: Therefore the bag still has 4 red and 1 blue ball.","Step 4: Total balls = 4 + 1 = 5.","Step 5: P(Red on second selection) = 4/5."],"options":[],"conceptId":"math_probability_independence_with_replacement","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Independence With Replacement"}', 0),
  (913, 273, 'A bag contains 2 green balls and 3 yellow balls. A green ball is selected and replaced. What is the probability of yellow on the second selection?', 'text', 1, 'The green ball is returned before the second selection.', '{"why":"Replacing the first ball leaves the second selection with the original probabilities.","sol":"Step 1: Initially there are 2 green and 3 yellow balls.\nStep 2: The green ball is replaced.\nStep 3: The bag therefore still contains 2 green and 3 yellow balls.\nStep 4: Total balls = 5.\nStep 5: P(Yellow) = 3/5.","steps":["Step 1: Initially there are 2 green and 3 yellow balls.","Step 2: The green ball is replaced.","Step 3: The bag therefore still contains 2 green and 3 yellow balls.","Step 4: Total balls = 5.","Step 5: P(Yellow) = 3/5."],"options":[],"conceptId":"math_probability_independence_with_replacement","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Independence With Replacement"}', 1),
  (914, 273, 'A bag contains 5 red balls and 5 blue balls. A ball is selected and replaced. Does the first selection change the probability of red on the second selection?', 'text', 1, 'Compare the bag before and after replacement.', '{"why":"Replacement restores exactly the original collection.","sol":"Step 1: Initially there are 5 red and 5 blue balls.\nStep 2: The selected ball is returned.\nStep 3: The bag again contains 5 red and 5 blue balls.\nStep 4: Therefore P(Red on the second selection) remains 5/10 = 1/2.\nStep 5: The first selection does not change the second probability.","steps":["Step 1: Initially there are 5 red and 5 blue balls.","Step 2: The selected ball is returned.","Step 3: The bag again contains 5 red and 5 blue balls.","Step 4: Therefore P(Red on the second selection) remains 5/10 = 1/2.","Step 5: The first selection does not change the second probability."],"options":[],"conceptId":"math_probability_independence_with_replacement","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Independence With Replacement"}', 2),
  (915, 274, 'A bag contains 4 red balls and 2 blue balls. A red ball is selected and not replaced. What is the probability of red on the second selection?', 'text', 1, 'Remove one red ball before calculating the second probability.', '{"why":"Removing the first red ball changes both the number of red balls and the total number of balls.","sol":"Step 1: Initially there are 4 red and 2 blue balls.\nStep 2: One red ball is removed.\nStep 3: Red balls remaining = 4 - 1 = 3.\nStep 4: Total balls remaining = 6 - 1 = 5.\nStep 5: Therefore P(Red on second selection) = 3/5.","steps":["Step 1: Initially there are 4 red and 2 blue balls.","Step 2: One red ball is removed.","Step 3: Red balls remaining = 4 - 1 = 3.","Step 4: Total balls remaining = 6 - 1 = 5.","Step 5: Therefore P(Red on second selection) = 3/5."],"options":[],"conceptId":"math_probability_independence_without_replacement","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Independence Without Replacement"}', 0),
  (916, 274, 'A bag contains 3 green balls and 2 yellow balls. A yellow ball is selected and not replaced. What is the probability of green on the second selection?', 'text', 1, 'Removing a yellow ball leaves all the green balls in the bag.', '{"why":"The total number of balls changes after the first ball is removed.","sol":"Step 1: Initially there are 3 green and 2 yellow balls.\nStep 2: One yellow ball is removed.\nStep 3: Green balls remaining = 3.\nStep 4: Total balls remaining = 5 - 1 = 4.\nStep 5: Therefore P(Green on second selection) = 3/4.","steps":["Step 1: Initially there are 3 green and 2 yellow balls.","Step 2: One yellow ball is removed.","Step 3: Green balls remaining = 3.","Step 4: Total balls remaining = 5 - 1 = 4.","Step 5: Therefore P(Green on second selection) = 3/4."],"options":[],"conceptId":"math_probability_independence_without_replacement","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Independence Without Replacement"}', 1),
  (917, 274, 'A bag contains 5 red and 1 blue ball. A red ball is selected and not replaced. Was the probability of selecting red changed?', 'text', 1, 'Compare the original and second-selection probabilities.', '{"why":"Removing a red ball changes the composition of the bag.","sol":"Step 1: Initially P(Red) = 5/6.\nStep 2: After one red is removed, 4 red balls remain.\nStep 3: There are now 5 balls in total.\nStep 4: The second probability is 4/5.\nStep 5: Since 5/6 is different from 4/5, the probability changed.","steps":["Step 1: Initially P(Red) = 5/6.","Step 2: After one red is removed, 4 red balls remain.","Step 3: There are now 5 balls in total.","Step 4: The second probability is 4/5.","Step 5: Since 5/6 is different from 4/5, the probability changed."],"options":[],"conceptId":"math_probability_independence_without_replacement","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Independence Without Replacement"}', 2),
  (918, 275, 'A fair die is rolled twice. Are the two rolls independent or dependent?', 'text', 1, 'Does the first roll change the die?', '{"why":"The first roll does not affect the second roll.","sol":"Step 1: The first roll produces one number.\nStep 2: Nothing is removed from or added to the die.\nStep 3: The die still has the same six possible outcomes.\nStep 4: Therefore the second probability is unchanged.\nStep 5: The rolls are independent.","steps":["Step 1: The first roll produces one number.","Step 2: Nothing is removed from or added to the die.","Step 3: The die still has the same six possible outcomes.","Step 4: Therefore the second probability is unchanged.","Step 5: The rolls are independent."],"options":[],"conceptId":"math_probability_distinguishing_independent_and_dependent_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Distinguishing Independent and Dependent Events"}', 0),
  (919, 275, 'A ball is selected from a bag and kept outside. A second ball is selected. Are the two selections independent or dependent?', 'text', 1, 'Does removing the first ball change the bag?', '{"why":"The first selection changes the contents available for the second selection.","sol":"Step 1: The first ball is removed from the bag.\nStep 2: The contents of the bag therefore change.\nStep 3: The probability of the second selection can change.\nStep 4: Therefore the selections are dependent.","steps":["Step 1: The first ball is removed from the bag.","Step 2: The contents of the bag therefore change.","Step 3: The probability of the second selection can change.","Step 4: Therefore the selections are dependent."],"options":[],"conceptId":"math_probability_distinguishing_independent_and_dependent_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Distinguishing Independent and Dependent Events"}', 1),
  (920, 275, 'A ball is selected from a bag, returned to the bag, and the bag is mixed. A second ball is selected. Are the selections independent or dependent?', 'text', 1, 'Compare the contents before the first and second selections.', '{"why":"Replacement restores the original conditions before the second selection.","sol":"Step 1: The first ball is selected.\nStep 2: It is returned to the bag.\nStep 3: The original collection is restored.\nStep 4: Therefore the probabilities for the second selection remain unchanged.\nStep 5: The selections are independent.","steps":["Step 1: The first ball is selected.","Step 2: It is returned to the bag.","Step 3: The original collection is restored.","Step 4: Therefore the probabilities for the second selection remain unchanged.","Step 5: The selections are independent."],"options":[],"conceptId":"math_probability_distinguishing_independent_and_dependent_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Distinguishing Independent and Dependent Events"}', 2),
  (921, 276, 'A fair die is rolled. Find the probability of getting 1 or 4.', 'text', 1, 'Getting 1 and getting 4 are mutually exclusive.', '{"why":"There are two separate favourable outcomes, 1 and 4, out of six.","sol":"Step 1: P(1) = 1/6.\nStep 2: P(4) = 1/6.\nStep 3: The two events are mutually exclusive.\nStep 4: Therefore P(1 or 4) = 1/6 + 1/6.\nStep 5: P(1 or 4) = 2/6 = 1/3.","steps":["Step 1: P(1) = 1/6.","Step 2: P(4) = 1/6.","Step 3: The two events are mutually exclusive.","Step 4: Therefore P(1 or 4) = 1/6 + 1/6.","Step 5: P(1 or 4) = 2/6 = 1/3."],"options":[],"conceptId":"math_probability_adding_probabilities_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Adding Probabilities of Mutually Exclusive Events"}', 0),
  (922, 276, 'A fair die is rolled. Find the probability of getting 3 or 6.', 'text', 1, 'Find each probability, then add them.', '{"why":"Getting 3 and getting 6 are mutually exclusive outcomes.","sol":"Step 1: P(3) = 1/6.\nStep 2: P(6) = 1/6.\nStep 3: The events cannot occur together in one roll.\nStep 4: Therefore P(3 or 6) = 1/6 + 1/6.\nStep 5: P(3 or 6) = 2/6 = 1/3.","steps":["Step 1: P(3) = 1/6.","Step 2: P(6) = 1/6.","Step 3: The events cannot occur together in one roll.","Step 4: Therefore P(3 or 6) = 1/6 + 1/6.","Step 5: P(3 or 6) = 2/6 = 1/3."],"options":[],"conceptId":"math_probability_adding_probabilities_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Adding Probabilities of Mutually Exclusive Events"}', 1),
  (923, 276, 'A fair die is rolled. Find the probability of getting an odd number or an even number.', 'text', 1, 'Odd and even outcomes together cover all six die results.', '{"why":"Every possible die result is either odd or even.","sol":"Step 1: P(Odd) = 3/6 = 1/2.\nStep 2: P(Even) = 3/6 = 1/2.\nStep 3: Odd and even are mutually exclusive.\nStep 4: Therefore P(Odd or Even) = 1/2 + 1/2.\nStep 5: P(Odd or Even) = 1.","steps":["Step 1: P(Odd) = 3/6 = 1/2.","Step 2: P(Even) = 3/6 = 1/2.","Step 3: Odd and even are mutually exclusive.","Step 4: Therefore P(Odd or Even) = 1/2 + 1/2.","Step 5: P(Odd or Even) = 1."],"options":[],"conceptId":"math_probability_adding_probabilities_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Adding Probabilities of Mutually Exclusive Events"}', 2),
  (924, 277, 'A fair die is rolled. Event A is {1, 2}. Event B is {5}. Find P(A or B).', 'text', 1, 'Count the favourable outcomes in both events.', '{"why":"There are three favourable outcomes: 1, 2 and 5.","sol":"Step 1: A has two favourable outcomes: 1 and 2.\nStep 2: B has one favourable outcome: 5.\nStep 3: The events are mutually exclusive.\nStep 4: Therefore P(A) = 2/6 and P(B) = 1/6.\nStep 5: P(A or B) = 2/6 + 1/6.\nStep 6: P(A or B) = 3/6 = 1/2.","steps":["Step 1: A has two favourable outcomes: 1 and 2.","Step 2: B has one favourable outcome: 5.","Step 3: The events are mutually exclusive.","Step 4: Therefore P(A) = 2/6 and P(B) = 1/6.","Step 5: P(A or B) = 2/6 + 1/6.","Step 6: P(A or B) = 3/6 = 1/2."],"options":[],"conceptId":"math_probability_the_addition_law_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"The Addition Law from a Probability Space"}', 0),
  (925, 277, 'A fair die is rolled. Event A is {1, 3, 5}. Event B is {2}. Find P(A or B).', 'text', 1, 'The two events have no common outcome.', '{"why":"The favourable outcomes are 1, 3, 5 and 2, giving four out of six.","sol":"Step 1: A has 3 favourable outcomes.\nStep 2: Therefore P(A) = 3/6 = 1/2.\nStep 3: B has 1 favourable outcome.\nStep 4: Therefore P(B) = 1/6.\nStep 5: P(A or B) = 1/2 + 1/6.\nStep 6: 1/2 = 3/6.\nStep 7: Therefore P(A or B) = 3/6 + 1/6 = 4/6 = 2/3.","steps":["Step 1: A has 3 favourable outcomes.","Step 2: Therefore P(A) = 3/6 = 1/2.","Step 3: B has 1 favourable outcome.","Step 4: Therefore P(B) = 1/6.","Step 5: P(A or B) = 1/2 + 1/6.","Step 6: 1/2 = 3/6.","Step 7: Therefore P(A or B) = 3/6 + 1/6 = 4/6 = 2/3."],"options":[],"conceptId":"math_probability_the_addition_law_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"The Addition Law from a Probability Space"}', 1),
  (926, 277, 'A fair die is rolled. Event A is {1, 2, 3}. Event B is {5, 6}. Find P(A or B).', 'text', 1, 'Add the probabilities because there is no overlap.', '{"why":"Five of the six possible die outcomes belong to A or B.","sol":"Step 1: P(A) = 3/6 = 1/2.\nStep 2: P(B) = 2/6 = 1/3.\nStep 3: A and B are mutually exclusive.\nStep 4: Therefore P(A or B) = 1/2 + 1/3.\nStep 5: 1/2 = 3/6 and 1/3 = 2/6.\nStep 6: Therefore P(A or B) = 5/6.","steps":["Step 1: P(A) = 3/6 = 1/2.","Step 2: P(B) = 2/6 = 1/3.","Step 3: A and B are mutually exclusive.","Step 4: Therefore P(A or B) = 1/2 + 1/3.","Step 5: 1/2 = 3/6 and 1/3 = 2/6.","Step 6: Therefore P(A or B) = 5/6."],"options":[],"conceptId":"math_probability_the_addition_law_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"The Addition Law from a Probability Space"}', 2),
  (927, 278, 'A fair coin is tossed twice. Find the probability of getting Head on both tosses.', 'text', 1, 'The two tosses are independent.', '{"why":"Both independent events must occur, so their probabilities are multiplied.","sol":"Step 1: P(Head on first toss) = 1/2.\nStep 2: P(Head on second toss) = 1/2.\nStep 3: The tosses are independent.\nStep 4: Therefore P(H and H) = 1/2 × 1/2.\nStep 5: P(H and H) = 1/4.","steps":["Step 1: P(Head on first toss) = 1/2.","Step 2: P(Head on second toss) = 1/2.","Step 3: The tosses are independent.","Step 4: Therefore P(H and H) = 1/2 × 1/2.","Step 5: P(H and H) = 1/4."],"options":[],"conceptId":"math_probability_multiplying_probabilities_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Multiplying Probabilities of Independent Events"}', 0),
  (928, 278, 'A fair die is rolled twice. Find the probability of getting 3 on both rolls.', 'text', 1, 'Each roll has probability 1/6 of giving 3.', '{"why":"The probability of each independent 3 must occur, so the probabilities are multiplied.","sol":"Step 1: P(3 on first roll) = 1/6.\nStep 2: P(3 on second roll) = 1/6.\nStep 3: The two rolls are independent.\nStep 4: Therefore P(3 and 3) = 1/6 × 1/6.\nStep 5: P(3 and 3) = 1/36.","steps":["Step 1: P(3 on first roll) = 1/6.","Step 2: P(3 on second roll) = 1/6.","Step 3: The two rolls are independent.","Step 4: Therefore P(3 and 3) = 1/6 × 1/6.","Step 5: P(3 and 3) = 1/36."],"options":[],"conceptId":"math_probability_multiplying_probabilities_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Multiplying Probabilities of Independent Events"}', 1),
  (929, 278, 'A fair coin is tossed and a fair die is rolled. Find the probability of getting Tail and 2.', 'text', 1, 'Find each probability separately, then multiply.', '{"why":"The two independent events must both occur.","sol":"Step 1: P(Tail) = 1/2.\nStep 2: P(2) = 1/6.\nStep 3: The coin toss and die roll are independent.\nStep 4: Therefore P(Tail and 2) = 1/2 × 1/6.\nStep 5: P(Tail and 2) = 1/12.","steps":["Step 1: P(Tail) = 1/2.","Step 2: P(2) = 1/6.","Step 3: The coin toss and die roll are independent.","Step 4: Therefore P(Tail and 2) = 1/2 × 1/6.","Step 5: P(Tail and 2) = 1/12."],"options":[],"conceptId":"math_probability_multiplying_probabilities_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Multiplying Probabilities of Independent Events"}', 2),
  (930, 279, 'A fair coin is tossed twice. Find the probability of getting Tail on both tosses.', 'text', 1, 'Each Tail has probability 1/2 and the tosses are independent.', '{"why":"Both independent Tail events must occur.","sol":"Step 1: P(Tail on first toss) = 1/2.\nStep 2: P(Tail on second toss) = 1/2.\nStep 3: The tosses are independent.\nStep 4: Therefore P(T and T) = 1/2 × 1/2.\nStep 5: P(T and T) = 1/4.","steps":["Step 1: P(Tail on first toss) = 1/2.","Step 2: P(Tail on second toss) = 1/2.","Step 3: The tosses are independent.","Step 4: Therefore P(T and T) = 1/2 × 1/2.","Step 5: P(T and T) = 1/4."],"options":[],"conceptId":"math_probability_multiplication_law_with_independent_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Multiplication Law with Independent Events"}', 0),
  (931, 279, 'A fair die is rolled twice. Find the probability of getting an odd number on both rolls.', 'text', 1, 'There are 3 odd numbers out of 6 on each roll.', '{"why":"The probability of an odd result is 1/2 on each independent roll.","sol":"Step 1: Odd outcomes are 1, 3 and 5.\nStep 2: Therefore P(Odd) = 3/6 = 1/2.\nStep 3: The same probability applies to the second roll.\nStep 4: The rolls are independent.\nStep 5: Therefore P(Odd and Odd) = 1/2 × 1/2 = 1/4.","steps":["Step 1: Odd outcomes are 1, 3 and 5.","Step 2: Therefore P(Odd) = 3/6 = 1/2.","Step 3: The same probability applies to the second roll.","Step 4: The rolls are independent.","Step 5: Therefore P(Odd and Odd) = 1/2 × 1/2 = 1/4."],"options":[],"conceptId":"math_probability_multiplication_law_with_independent_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Multiplication Law with Independent Events"}', 1),
  (932, 279, 'A fair coin is tossed and a fair die is rolled. Find the probability of Tail and an even number.', 'text', 1, 'P(Tail) = 1/2 and P(Even) = 3/6.', '{"why":"The independent probabilities are multiplied.","sol":"Step 1: P(Tail) = 1/2.\nStep 2: The even die outcomes are 2, 4 and 6.\nStep 3: Therefore P(Even) = 3/6 = 1/2.\nStep 4: The coin and die experiments are independent.\nStep 5: Therefore P(Tail and Even) = 1/2 × 1/2.\nStep 6: The answer is 1/4.","steps":["Step 1: P(Tail) = 1/2.","Step 2: The even die outcomes are 2, 4 and 6.","Step 3: Therefore P(Even) = 3/6 = 1/2.","Step 4: The coin and die experiments are independent.","Step 5: Therefore P(Tail and Even) = 1/2 × 1/2.","Step 6: The answer is 1/4."],"options":[],"conceptId":"math_probability_multiplication_law_with_independent_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Multiplication Law with Independent Events"}', 2),
  (933, 280, 'A fair die is rolled. Find the probability of getting 1 or 3. Should you add or multiply?', 'text', 1, 'Can 1 and 3 occur on the same roll?', '{"why":"The events are mutually exclusive.","sol":"Step 1: A single die roll gives one number.\nStep 2: It cannot give both 1 and 3.\nStep 3: Therefore the events are mutually exclusive.\nStep 4: For mutually exclusive events asking for ''or'', we add.\nStep 5: P(1 or 3) = 1/6 + 1/6 = 1/3.","steps":["Step 1: A single die roll gives one number.","Step 2: It cannot give both 1 and 3.","Step 3: Therefore the events are mutually exclusive.","Step 4: For mutually exclusive events asking for ''or'', we add.","Step 5: P(1 or 3) = 1/6 + 1/6 = 1/3."],"options":[],"conceptId":"math_probability_choosing_addition_or_multiplication","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Choosing Addition or Multiplication"}', 0),
  (934, 280, 'A fair coin is tossed twice. Find the probability of getting Head on both tosses. Should you add or multiply?', 'text', 1, 'Both events must happen, and the tosses are independent.', '{"why":"Both independent events must occur.","sol":"Step 1: We need Head on the first toss and Head on the second toss.\nStep 2: The two tosses are independent.\nStep 3: For independent events asking for both events, we multiply.\nStep 4: P(H and H) = 1/2 × 1/2 = 1/4.","steps":["Step 1: We need Head on the first toss and Head on the second toss.","Step 2: The two tosses are independent.","Step 3: For independent events asking for both events, we multiply.","Step 4: P(H and H) = 1/2 × 1/2 = 1/4."],"options":[],"conceptId":"math_probability_choosing_addition_or_multiplication","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Choosing Addition or Multiplication"}', 1),
  (935, 280, 'A fair die is rolled twice. Find the probability of getting 6 on both rolls. Should you add or multiply?', 'text', 1, 'Both rolls must produce 6.', '{"why":"The two independent events must both happen.","sol":"Step 1: P(6 on the first roll) = 1/6.\nStep 2: P(6 on the second roll) = 1/6.\nStep 3: The two rolls are independent.\nStep 4: Therefore we multiply.\nStep 5: P(6 and 6) = 1/6 × 1/6 = 1/36.","steps":["Step 1: P(6 on the first roll) = 1/6.","Step 2: P(6 on the second roll) = 1/6.","Step 3: The two rolls are independent.","Step 4: Therefore we multiply.","Step 5: P(6 and 6) = 1/6 × 1/6 = 1/36."],"options":[],"conceptId":"math_probability_choosing_addition_or_multiplication","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Choosing Addition or Multiplication"}', 2),
  (936, 281, 'A coin is tossed twice. How many complete paths are possible?', 'text', 1, 'List HH, HT, TH and TT.', '{"why":"A complete path contains the result of both tosses.","sol":"Step 1: The first toss has 2 possible results: H or T.\nStep 2: Each first result can be followed by H or T.\nStep 3: The complete paths are HH, HT, TH and TT.\nStep 4: Therefore there are 4 complete paths.","steps":["Step 1: The first toss has 2 possible results: H or T.","Step 2: Each first result can be followed by H or T.","Step 3: The complete paths are HH, HT, TH and TT.","Step 4: Therefore there are 4 complete paths."],"options":[],"conceptId":"math_probability_reading_a_probability_tree_diagram","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Reading a Probability Tree Diagram"}', 0),
  (937, 281, 'A die is rolled twice. How many complete paths are possible?', 'text', 1, 'There are 6 choices at each stage.', '{"why":"Every first-roll result can be paired with every second-roll result.","sol":"Step 1: The first roll has 6 possible results.\nStep 2: For each first result, the second roll has 6 possible results.\nStep 3: Number of complete paths = 6 × 6.\nStep 4: 6 × 6 = 36.","steps":["Step 1: The first roll has 6 possible results.","Step 2: For each first result, the second roll has 6 possible results.","Step 3: Number of complete paths = 6 × 6.","Step 4: 6 × 6 = 36."],"options":[],"conceptId":"math_probability_reading_a_probability_tree_diagram","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Reading a Probability Tree Diagram"}', 1),
  (938, 281, 'For two coin tosses, is HT a branch or a complete path?', 'text', 1, 'HT contains results from both stages.', '{"why":"A complete path contains an outcome from every stage.","sol":"Step 1: The first letter H gives the first-stage result.\nStep 2: The second letter T gives the second-stage result.\nStep 3: Therefore HT describes the entire experiment.","steps":["Step 1: The first letter H gives the first-stage result.","Step 2: The second letter T gives the second-stage result.","Step 3: Therefore HT describes the entire experiment."],"options":[],"conceptId":"math_probability_reading_a_probability_tree_diagram","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Reading a Probability Tree Diagram"}', 2),
  (939, 282, 'A coin is tossed twice. How many branches leave the first stage?', 'text', 1, 'What can one coin toss produce?', '{"why":"The first toss has exactly two possible outcomes.","sol":"Step 1: One coin toss can produce Head or Tail.\nStep 2: Therefore the first stage has two possible results.\nStep 3: Each possible result needs one branch.","steps":["Step 1: One coin toss can produce Head or Tail.","Step 2: Therefore the first stage has two possible results.","Step 3: Each possible result needs one branch."],"options":[],"conceptId":"math_probability_building_a_two_stage_probability_tree","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Building a Two-Stage Probability Tree"}', 0),
  (940, 282, 'A die is rolled and then a coin is tossed. How many complete paths are possible?', 'text', 1, 'Multiply the number of choices at each stage.', '{"why":"Every one of the 6 die outcomes can be paired with either H or T.","sol":"Step 1: The die has 6 possible results.\nStep 2: The coin has 2 possible results.\nStep 3: Each die result can be followed by either coin result.\nStep 4: 6 × 2 = 12.","steps":["Step 1: The die has 6 possible results.","Step 2: The coin has 2 possible results.","Step 3: Each die result can be followed by either coin result.","Step 4: 6 × 2 = 12."],"options":[],"conceptId":"math_probability_building_a_two_stage_probability_tree","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Building a Two-Stage Probability Tree"}', 1),
  (941, 282, 'A spinner has R, B and G and is spun twice. List all paths beginning with B.', 'text', 1, 'After B, the second result can still be R, B or G.', '{"why":"Each possible second-stage result creates one path from B.","sol":"Step 1: The first result is fixed as B.\nStep 2: The second result can be R, B or G.\nStep 3: Therefore the paths are BR, BB and BG.","steps":["Step 1: The first result is fixed as B.","Step 2: The second result can be R, B or G.","Step 3: Therefore the paths are BR, BB and BG."],"options":[],"conceptId":"math_probability_building_a_two_stage_probability_tree","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Building a Two-Stage Probability Tree"}', 2),
  (942, 283, 'A fair die is rolled. What probability should be written on the branch for getting 4?', 'text', 1, 'There are 6 equally likely die outcomes.', '{"why":"One of the six equally likely outcomes is 4.","sol":"Step 1: A fair die has 6 equally likely outcomes.\nStep 2: Only one outcome is 4.\nStep 3: Therefore P(4) = 1/6.","steps":["Step 1: A fair die has 6 equally likely outcomes.","Step 2: Only one outcome is 4.","Step 3: Therefore P(4) = 1/6."],"options":[],"conceptId":"math_probability_probabilities_on_tree_branches","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Probabilities on Tree Branches"}', 0),
  (943, 283, 'A bag has 4 red balls and 6 blue balls. Find P(R).', 'text', 1, 'First find the total number of balls.', '{"why":"Probability equals favourable outcomes divided by total outcomes.","sol":"Step 1: Total balls = 4 + 6 = 10.\nStep 2: There are 4 red balls.\nStep 3: P(R) = 4/10.\nStep 4: Simplify 4/10 to 2/5.","steps":["Step 1: Total balls = 4 + 6 = 10.","Step 2: There are 4 red balls.","Step 3: P(R) = 4/10.","Step 4: Simplify 4/10 to 2/5."],"options":[],"conceptId":"math_probability_probabilities_on_tree_branches","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Probabilities on Tree Branches"}', 1),
  (944, 283, 'A box has 2 green, 3 yellow and 5 blue counters. Check the branch probabilities.', 'text', 1, 'Calculate each probability and add them.', '{"why":"All possible first-stage outcomes must account for the whole probability.","sol":"Step 1: Total = 2 + 3 + 5 = 10.\nStep 2: P(G) = 2/10, P(Y) = 3/10, P(B) = 5/10.\nStep 3: Add them: 2/10 + 3/10 + 5/10.\nStep 4: The result is 10/10 = 1.","steps":["Step 1: Total = 2 + 3 + 5 = 10.","Step 2: P(G) = 2/10, P(Y) = 3/10, P(B) = 5/10.","Step 3: Add them: 2/10 + 3/10 + 5/10.","Step 4: The result is 10/10 = 1."],"options":[],"conceptId":"math_probability_probabilities_on_tree_branches","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Probabilities on Tree Branches"}', 2),
  (945, 284, 'A fair coin is tossed twice. Find P(HH).', 'text', 1, 'Follow H on the first stage and H on the second stage.', '{"why":"Both heads must occur along the same complete path.","sol":"Step 1: P(H on first toss) = 1/2.\nStep 2: P(H on second toss) = 1/2.\nStep 3: Multiply along the path.\nStep 4: P(HH) = 1/2 × 1/2 = 1/4.","steps":["Step 1: P(H on first toss) = 1/2.","Step 2: P(H on second toss) = 1/2.","Step 3: Multiply along the path.","Step 4: P(HH) = 1/2 × 1/2 = 1/4."],"options":[],"conceptId":"math_probability_probability_along_a_complete_path","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Probability Along a Complete Path"}', 0),
  (946, 284, 'A fair coin is tossed twice. Find P(HT).', 'text', 1, 'Multiply the probability of H by the probability of T.', '{"why":"HT is one complete path through the two-stage experiment.","sol":"Step 1: P(H) = 1/2.\nStep 2: P(T) = 1/2.\nStep 3: P(HT) = 1/2 × 1/2.\nStep 4: P(HT) = 1/4.","steps":["Step 1: P(H) = 1/2.","Step 2: P(T) = 1/2.","Step 3: P(HT) = 1/2 × 1/2.","Step 4: P(HT) = 1/4."],"options":[],"conceptId":"math_probability_probability_along_a_complete_path","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Probability Along a Complete Path"}', 1),
  (947, 284, 'A fair die is rolled and then a fair coin is tossed. Find P(6H).', 'text', 1, 'P(6) = 1/6 and P(H) = 1/2.', '{"why":"The path requires both a 6 and then a Head.","sol":"Step 1: P(6) = 1/6.\nStep 2: P(H) = 1/2.\nStep 3: Multiply along the complete path.\nStep 4: P(6H) = 1/6 × 1/2 = 1/12.","steps":["Step 1: P(6) = 1/6.","Step 2: P(H) = 1/2.","Step 3: Multiply along the complete path.","Step 4: P(6H) = 1/6 × 1/2 = 1/12."],"options":[],"conceptId":"math_probability_probability_along_a_complete_path","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Probability Along a Complete Path"}', 2),
  (948, 285, 'A bag has 3 red and 2 blue balls. A ball is replaced after the first draw. Find P(RR).', 'text', 1, 'Replacement means there are still 3 red out of 5.', '{"why":"Replacement restores the original contents before the second draw.","sol":"Step 1: First P(R) = 3/5.\nStep 2: The red ball is replaced, so the bag returns to 3 red and 2 blue.\nStep 3: Second P(R) = 3/5.\nStep 4: P(RR) = 3/5 × 3/5 = 9/25.","steps":["Step 1: First P(R) = 3/5.","Step 2: The red ball is replaced, so the bag returns to 3 red and 2 blue.","Step 3: Second P(R) = 3/5.","Step 4: P(RR) = 3/5 × 3/5 = 9/25."],"options":[],"conceptId":"math_probability_tree_diagrams_with_replacement","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Tree Diagrams With Replacement"}', 0),
  (949, 285, 'Using the same bag with replacement, find P(RB).', 'text', 1, 'Both stages have the original probabilities.', '{"why":"The replacement means 2 blue balls are still available for the second draw.","sol":"Step 1: First P(R) = 3/5.\nStep 2: The ball is replaced.\nStep 3: Second P(B) = 2/5.\nStep 4: P(RB) = 3/5 × 2/5 = 6/25.","steps":["Step 1: First P(R) = 3/5.","Step 2: The ball is replaced.","Step 3: Second P(B) = 2/5.","Step 4: P(RB) = 3/5 × 2/5 = 6/25."],"options":[],"conceptId":"math_probability_tree_diagrams_with_replacement","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Tree Diagrams With Replacement"}', 1),
  (950, 285, 'With replacement, what is P(BB) for a bag with 3 red and 2 blue balls?', 'text', 1, 'P(B) is 2/5 on both stages.', '{"why":"The number of blue balls returns to 2 before the second selection.","sol":"Step 1: First P(B) = 2/5.\nStep 2: The selected blue ball is replaced.\nStep 3: Second P(B) = 2/5.\nStep 4: P(BB) = 2/5 × 2/5 = 4/25.","steps":["Step 1: First P(B) = 2/5.","Step 2: The selected blue ball is replaced.","Step 3: Second P(B) = 2/5.","Step 4: P(BB) = 2/5 × 2/5 = 4/25."],"options":[],"conceptId":"math_probability_tree_diagrams_with_replacement","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Tree Diagrams With Replacement"}', 2),
  (951, 286, 'A bag has 3 red and 2 blue balls. A red ball is removed without replacement. What is P(R) on the second draw?', 'text', 1, 'One red has already been removed.', '{"why":"Without replacement, the first red is no longer available.","sol":"Step 1: Initially there are 3 red and 2 blue, giving 5 balls.\nStep 2: One red is removed.\nStep 3: Red remaining = 3 − 1 = 2.\nStep 4: Total remaining = 5 − 1 = 4.\nStep 5: Therefore P(R) = 2/4 = 1/2.","steps":["Step 1: Initially there are 3 red and 2 blue, giving 5 balls.","Step 2: One red is removed.","Step 3: Red remaining = 3 − 1 = 2.","Step 4: Total remaining = 5 − 1 = 4.","Step 5: Therefore P(R) = 2/4 = 1/2."],"options":[],"conceptId":"math_probability_tree_diagrams_without_replacement","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Tree Diagrams Without Replacement"}', 0),
  (952, 286, 'A bag has 3 red and 2 blue balls. Find P(RR) without replacement.', 'text', 1, 'Use 3/5 first, then 2/4.', '{"why":"The number of red balls falls from 3 to 2 after the first red is removed.","sol":"Step 1: First P(R) = 3/5.\nStep 2: After removing red, 2 red remain out of 4 balls.\nStep 3: Second P(R) = 2/4.\nStep 4: P(RR) = 3/5 × 2/4.\nStep 5: P(RR) = 6/20 = 3/10.","steps":["Step 1: First P(R) = 3/5.","Step 2: After removing red, 2 red remain out of 4 balls.","Step 3: Second P(R) = 2/4.","Step 4: P(RR) = 3/5 × 2/4.","Step 5: P(RR) = 6/20 = 3/10."],"options":[],"conceptId":"math_probability_tree_diagrams_without_replacement","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Tree Diagrams Without Replacement"}', 1),
  (953, 286, 'A bag has 3 red and 2 blue balls. Find P(BB) without replacement.', 'text', 1, 'After removing the first blue, only 1 blue remains.', '{"why":"Without replacement, one blue ball disappears after the first blue selection.","sol":"Step 1: First P(B) = 2/5.\nStep 2: After removing blue, 1 blue remains out of 4 balls.\nStep 3: Second P(B) = 1/4.\nStep 4: P(BB) = 2/5 × 1/4.\nStep 5: P(BB) = 2/20 = 1/10.","steps":["Step 1: First P(B) = 2/5.","Step 2: After removing blue, 1 blue remains out of 4 balls.","Step 3: Second P(B) = 1/4.","Step 4: P(BB) = 2/5 × 1/4.","Step 5: P(BB) = 2/20 = 1/10."],"options":[],"conceptId":"math_probability_tree_diagrams_without_replacement","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Tree Diagrams Without Replacement"}', 2),
  (954, 287, 'How many rows are in A = [[4,7,2],[1,5,9]]?', 'text', 1, 'Count the horizontal lines, not the individual numbers.', '{"why":"Each horizontal line of entries forms one row.","sol":"Step 1: The first row is [4,7,2].\nStep 2: The second row is [1,5,9].\nStep 3: There are 2 horizontal rows.","steps":["Step 1: The first row is [4,7,2].","Step 2: The second row is [1,5,9].","Step 3: There are 2 horizontal rows."],"options":[],"conceptId":"math_matrices_introduction_to_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Introduction to Matrices"}', 0),
  (955, 287, 'How many columns are in B = [[3,8],[1,6],[5,9]]?', 'text', 1, 'Count the vertical positions from left to right.', '{"why":"Entries directly above and below one another occupy the same column.","sol":"Step 1: The first column contains 3, 1 and 5.\nStep 2: The second column contains 8, 6 and 9.\nStep 3: There are 2 vertical columns.","steps":["Step 1: The first column contains 3, 1 and 5.","Step 2: The second column contains 8, 6 and 9.","Step 3: There are 2 vertical columns."],"options":[],"conceptId":"math_matrices_introduction_to_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Introduction to Matrices"}', 1),
  (956, 287, 'A = [[2,4,6,8],[1,3,5,7]]. State the number of rows and columns.', 'text', 1, 'Count horizontal lines first, then entries across a row.', '{"why":"Rows are counted horizontally and columns vertically.","sol":"Step 1: There are 2 horizontal lines, so there are 2 rows.\nStep 2: Each row has 4 entries.\nStep 3: The matrix therefore has 4 columns.","steps":["Step 1: There are 2 horizontal lines, so there are 2 rows.","Step 2: Each row has 4 entries.","Step 3: The matrix therefore has 4 columns."],"options":[],"conceptId":"math_matrices_introduction_to_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Introduction to Matrices"}', 2),
  (957, 287, 'Which is a row: [2,5,8] or [[2],[5],[8]]?', 'text', 1, 'A row is arranged horizontally.', '{"why":"A row is a horizontal arrangement of entries.","sol":"Step 1: [2,5,8] places the entries side by side.\nStep 2: The entries in [[2],[5],[8]] are arranged vertically.\nStep 3: Therefore [2,5,8] is a row.","steps":["Step 1: [2,5,8] places the entries side by side.","Step 2: The entries in [[2],[5],[8]] are arranged vertically.","Step 3: Therefore [2,5,8] is a row."],"options":[],"conceptId":"math_matrices_introduction_to_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Introduction to Matrices"}', 3),
  (958, 288, 'Find the order of A = [[4,7,2],[1,5,9]].', 'text', 1, 'Count the rows first and the columns second.', '{"why":"The order of a matrix is written as rows × columns.","sol":"Step 1: There are 2 horizontal rows.\nStep 2: There are 3 entries across each row, so there are 3 columns.\nStep 3: Write rows first: 2 × 3.","steps":["Step 1: There are 2 horizontal rows.","Step 2: There are 3 entries across each row, so there are 3 columns.","Step 3: Write rows first: 2 × 3."],"options":[],"conceptId":"math_matrices_order_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Order of a Matrix"}', 0),
  (959, 288, 'Find the order of B = [[1,2],[3,4],[5,6],[7,8]].', 'text', 1, 'Count the horizontal lines before the vertical positions.', '{"why":"The first number in the order always gives the number of rows.","sol":"Step 1: There are 4 horizontal rows.\nStep 2: There are 2 columns.\nStep 3: Write the row count first: 4 × 2.","steps":["Step 1: There are 4 horizontal rows.","Step 2: There are 2 columns.","Step 3: Write the row count first: 4 × 2."],"options":[],"conceptId":"math_matrices_order_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Order of a Matrix"}', 1),
  (960, 288, 'A matrix has 5 rows and 3 columns. State its order.', 'text', 1, 'Do not reverse the two numbers.', '{"why":"Rows are written first and columns second.","sol":"Step 1: Rows = 5.\nStep 2: Columns = 3.\nStep 3: Order = 5 × 3.","steps":["Step 1: Rows = 5.","Step 2: Columns = 3.","Step 3: Order = 5 × 3."],"options":[],"conceptId":"math_matrices_order_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Order of a Matrix"}', 2),
  (961, 288, 'How many entries are in a matrix of order 4 × 3?', 'text', 1, 'Each of the 4 rows contains 3 entries.', '{"why":"The total number of entries is the number of rows multiplied by the number of columns.","sol":"Step 1: There are 4 rows.\nStep 2: Each row contains 3 entries.\nStep 3: Total entries = 3 + 3 + 3 + 3 = 12.\nStep 4: Equivalently, 4 × 3 = 12.","steps":["Step 1: There are 4 rows.","Step 2: Each row contains 3 entries.","Step 3: Total entries = 3 + 3 + 3 + 3 = 12.","Step 4: Equivalently, 4 × 3 = 12."],"options":[],"conceptId":"math_matrices_order_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Order of a Matrix"}', 3),
  (962, 289, 'Given A = [[4,7,2],[9,5,6],[1,8,3]], find a₂₃.', 'text', 1, 'Select row 2 first, then the third entry in that row.', '{"why":"The subscripts mean row 2, column 3.","sol":"Step 1: Row 2 is [9,5,6].\nStep 2: The first entry is 9, the second is 5 and the third is 6.\nStep 3: Therefore a₂₃ = 6.","steps":["Step 1: Row 2 is [9,5,6].","Step 2: The first entry is 9, the second is 5 and the third is 6.","Step 3: Therefore a₂₃ = 6."],"options":[],"conceptId":"math_matrices_elements_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Elements of a Matrix"}', 0),
  (963, 289, 'Given A = [[4,7,2],[9,5,6],[1,8,3]], find a₃₁.', 'text', 1, 'Go to the third row and choose its first entry.', '{"why":"The first subscript identifies row 3; the second identifies column 1.","sol":"Step 1: Row 3 is [1,8,3].\nStep 2: Column 1 is the first entry in that row.\nStep 3: The first entry is 1.","steps":["Step 1: Row 3 is [1,8,3].","Step 2: Column 1 is the first entry in that row.","Step 3: The first entry is 1."],"options":[],"conceptId":"math_matrices_elements_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Elements of a Matrix"}', 1),
  (964, 289, 'Given A = [[4,7,2],[9,5,6],[1,8,3]], find a₁₂.', 'text', 1, 'Select row 1 and then count to column 2.', '{"why":"a₁₂ refers to the entry in row 1, column 2.","sol":"Step 1: Row 1 is [4,7,2].\nStep 2: The second entry in row 1 is 7.\nStep 3: Therefore a₁₂ = 7.","steps":["Step 1: Row 1 is [4,7,2].","Step 2: The second entry in row 1 is 7.","Step 3: Therefore a₁₂ = 7."],"options":[],"conceptId":"math_matrices_elements_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Elements of a Matrix"}', 2),
  (965, 289, 'Given B = [[2,-1,5],[4,3,7]], find b₁₂.', 'text', 1, 'Do not drop the negative sign from an entry.', '{"why":"The element is -1, and its negative sign is part of its value.","sol":"Step 1: Row 1 is [2,-1,5].\nStep 2: Column 2 selects the second entry.\nStep 3: The second entry is -1.","steps":["Step 1: Row 1 is [2,-1,5].","Step 2: Column 2 selects the second entry.","Step 3: The second entry is -1."],"options":[],"conceptId":"math_matrices_elements_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Elements of a Matrix"}', 3),
  (966, 290, 'What type of matrix is A = [[3,5,7]]?', 'text', 1, 'Count the rows in the entire matrix.', '{"why":"A row matrix has exactly one row.","sol":"Step 1: The entries 3, 5 and 7 are on one horizontal line.\nStep 2: There is exactly 1 row.\nStep 3: Therefore A is a row matrix.","steps":["Step 1: The entries 3, 5 and 7 are on one horizontal line.","Step 2: There is exactly 1 row.","Step 3: Therefore A is a row matrix."],"options":[],"conceptId":"math_matrices_row_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Row Matrix"}', 0),
  (967, 290, 'Find the order of B = [[2,-4,6,8]].', 'text', 1, 'Count rows first and entries across second.', '{"why":"The order is the number of rows followed by the number of columns.","sol":"Step 1: There is 1 horizontal row.\nStep 2: There are 4 entries across the row.\nStep 3: Order = 1 × 4.","steps":["Step 1: There is 1 horizontal row.","Step 2: There are 4 entries across the row.","Step 3: Order = 1 × 4."],"options":[],"conceptId":"math_matrices_row_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Row Matrix"}', 1),
  (968, 290, 'Is C = [[1,2],[3,4]] a row matrix?', 'text', 1, 'A row matrix must have exactly one row.', '{"why":"A matrix with two rows does not meet the definition of a row matrix.","sol":"Step 1: The first horizontal line is [1,2].\nStep 2: The second horizontal line is [3,4].\nStep 3: There are 2 rows, not 1.\nStep 4: Therefore C is not a row matrix.","steps":["Step 1: The first horizontal line is [1,2].","Step 2: The second horizontal line is [3,4].","Step 3: There are 2 rows, not 1.","Step 4: Therefore C is not a row matrix."],"options":[],"conceptId":"math_matrices_row_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Row Matrix"}', 2),
  (969, 290, 'Write a row matrix containing 6, -3 and 10.', 'text', 1, 'Place all three entries on one horizontal line.', '{"why":"All entries are arranged in one horizontal row.","sol":"Step 1: A row matrix has one row.\nStep 2: Place 6, -3 and 10 side by side.\nStep 3: The resulting matrix is [6,-3,10].","steps":["Step 1: A row matrix has one row.","Step 2: Place 6, -3 and 10 side by side.","Step 3: The resulting matrix is [6,-3,10]."],"options":[],"conceptId":"math_matrices_row_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Row Matrix"}', 3),
  (970, 291, 'What type of matrix is A = [[3],[5],[7]]?', 'text', 1, 'Count the vertical columns.', '{"why":"A column matrix has exactly one column.","sol":"Step 1: The entries 3, 5 and 7 are arranged vertically.\nStep 2: There is exactly 1 column.\nStep 3: Therefore A is a column matrix.","steps":["Step 1: The entries 3, 5 and 7 are arranged vertically.","Step 2: There is exactly 1 column.","Step 3: Therefore A is a column matrix."],"options":[],"conceptId":"math_matrices_column_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Column Matrix"}', 0),
  (971, 291, 'Find the order of B = [[2],[-4],[6],[8]].', 'text', 1, 'Count the horizontal rows first.', '{"why":"The order records rows first and columns second.","sol":"Step 1: There are 4 horizontal positions, so there are 4 rows.\nStep 2: There is only 1 vertical column.\nStep 3: Order = 4 × 1.","steps":["Step 1: There are 4 horizontal positions, so there are 4 rows.","Step 2: There is only 1 vertical column.","Step 3: Order = 4 × 1."],"options":[],"conceptId":"math_matrices_column_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Column Matrix"}', 1),
  (972, 291, 'Is C = [[1,2],[3,4],[5,6]] a column matrix?', 'text', 1, 'Count the columns, not the rows.', '{"why":"C has two columns, so it is not a column matrix.","sol":"Step 1: The first column contains 1, 3 and 5.\nStep 2: The second column contains 2, 4 and 6.\nStep 3: There are 2 columns.\nStep 4: A column matrix must have exactly 1 column.","steps":["Step 1: The first column contains 1, 3 and 5.","Step 2: The second column contains 2, 4 and 6.","Step 3: There are 2 columns.","Step 4: A column matrix must have exactly 1 column."],"options":[],"conceptId":"math_matrices_column_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Column Matrix"}', 2),
  (973, 291, 'Write a column matrix containing 7, -1 and 5 in that order.', 'text', 1, 'Put each entry on a new line, keeping the given order.', '{"why":"The entries are arranged vertically in one column.","sol":"Step 1: Place 7 in the first row.\nStep 2: Place -1 in the second row.\nStep 3: Place 5 in the third row.\nStep 4: Use one vertical column.","steps":["Step 1: Place 7 in the first row.","Step 2: Place -1 in the second row.","Step 3: Place 5 in the third row.","Step 4: Use one vertical column."],"options":[],"conceptId":"math_matrices_column_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Column Matrix"}', 3),
  (974, 292, 'Determine whether A = [[4,7],[2,5]] is a square matrix.', 'text', 1, 'Compare the number of rows with the number of columns.', '{"why":"A square matrix has an equal number of rows and columns.","sol":"Step 1: A has 2 rows.\nStep 2: A has 2 columns.\nStep 3: Since the number of rows equals the number of columns, A is square.","steps":["Step 1: A has 2 rows.","Step 2: A has 2 columns.","Step 3: Since the number of rows equals the number of columns, A is square."],"options":[],"conceptId":"math_matrices_square_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Square Matrix"}', 0),
  (975, 292, 'Determine whether B = [[3,8,1],[5,2,7]] is a square matrix.', 'text', 1, 'Count both dimensions.', '{"why":"The matrix has 2 rows but 3 columns.","sol":"Step 1: B has 2 rows.\nStep 2: B has 3 columns.\nStep 3: 2 is not equal to 3.\nStep 4: Therefore B is not square.","steps":["Step 1: B has 2 rows.","Step 2: B has 3 columns.","Step 3: 2 is not equal to 3.","Step 4: Therefore B is not square."],"options":[],"conceptId":"math_matrices_square_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Square Matrix"}', 1),
  (976, 292, 'A matrix has order 4 × 4. Is it a square matrix?', 'text', 1, 'For a square matrix, the two dimensions must be equal.', '{"why":"A 4 × 4 matrix has the same number of rows and columns.","sol":"Step 1: The matrix has 4 rows.\nStep 2: The matrix has 4 columns.\nStep 3: 4 equals 4.\nStep 4: Therefore the matrix is square.","steps":["Step 1: The matrix has 4 rows.","Step 2: The matrix has 4 columns.","Step 3: 4 equals 4.","Step 4: Therefore the matrix is square."],"options":[],"conceptId":"math_matrices_square_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Square Matrix"}', 2),
  (977, 292, 'A student says [[1,2,3],[4,5,6]] is square because it contains 6 numbers arranged evenly. Is the student correct?', 'text', 1, 'The number of entries is not the test for being square.', '{"why":"Being square depends on equal rows and columns, not on the total number of entries.","sol":"Step 1: The matrix has 2 rows.\nStep 2: It has 3 columns.\nStep 3: A square matrix requires the number of rows to equal the number of columns.\nStep 4: 2 is not equal to 3.\nStep 5: Therefore the student is incorrect.","steps":["Step 1: The matrix has 2 rows.","Step 2: It has 3 columns.","Step 3: A square matrix requires the number of rows to equal the number of columns.","Step 4: 2 is not equal to 3.","Step 5: Therefore the student is incorrect."],"options":[],"conceptId":"math_matrices_square_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Square Matrix"}', 3),
  (978, 293, 'Is [[0,0],[0,0]] a zero matrix?', 'text', 1, 'Check every entry.', '{"why":"Every element of the matrix is zero.","sol":"Step 1: The first row contains only zeros.\nStep 2: The second row contains only zeros.\nStep 3: Every element is zero.\nStep 4: Therefore it is a zero matrix.","steps":["Step 1: The first row contains only zeros.","Step 2: The second row contains only zeros.","Step 3: Every element is zero.","Step 4: Therefore it is a zero matrix."],"options":[],"conceptId":"math_matrices_zero_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Zero Matrix"}', 0),
  (979, 293, 'Is [[0,0,0],[0,0,0]] a zero matrix?', 'text', 1, 'The matrix does not have to be square.', '{"why":"A zero matrix can be rectangular; all that matters is that every entry is zero.","sol":"Step 1: There are 2 rows and 3 columns.\nStep 2: Every entry is zero.\nStep 3: The dimensions do not affect whether it is a zero matrix.\nStep 4: Therefore it is a zero matrix.","steps":["Step 1: There are 2 rows and 3 columns.","Step 2: Every entry is zero.","Step 3: The dimensions do not affect whether it is a zero matrix.","Step 4: Therefore it is a zero matrix."],"options":[],"conceptId":"math_matrices_zero_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Zero Matrix"}', 1),
  (980, 293, 'Is [[0,0],[0,4]] a zero matrix?', 'text', 1, 'Look carefully at every entry.', '{"why":"A single non-zero element means the matrix is not a zero matrix.","sol":"Step 1: Three entries are zero.\nStep 2: The bottom-right entry is 4.\nStep 3: 4 is not zero.\nStep 4: Therefore not every entry is zero.","steps":["Step 1: Three entries are zero.","Step 2: The bottom-right entry is 4.","Step 3: 4 is not zero.","Step 4: Therefore not every entry is zero."],"options":[],"conceptId":"math_matrices_zero_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Zero Matrix"}', 2),
  (981, 293, 'Write a zero matrix of order 2 × 3.', 'text', 1, 'Use 2 rows, 3 columns, and put zero in every position.', '{"why":"It has the required dimensions and every element is zero.","sol":"Step 1: Create 2 horizontal rows.\nStep 2: Put 3 entries in each row.\nStep 3: Make every entry zero.\nStep 4: The matrix is [[0,0,0],[0,0,0]].","steps":["Step 1: Create 2 horizontal rows.","Step 2: Put 3 entries in each row.","Step 3: Make every entry zero.","Step 4: The matrix is [[0,0,0],[0,0,0]]."],"options":[],"conceptId":"math_matrices_zero_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Zero Matrix"}', 3),
  (982, 294, 'Is [[4,0,0],[0,7,0],[0,0,9]] a diagonal matrix?', 'text', 1, 'Check the entries outside the main diagonal.', '{"why":"Every off-diagonal entry is zero.","sol":"Step 1: The main diagonal is 4, 7, 9.\nStep 2: Every entry outside that diagonal is zero.\nStep 3: Therefore the matrix satisfies the definition of a diagonal matrix.","steps":["Step 1: The main diagonal is 4, 7, 9.","Step 2: Every entry outside that diagonal is zero.","Step 3: Therefore the matrix satisfies the definition of a diagonal matrix."],"options":[],"conceptId":"math_matrices_diagonal_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Diagonal Matrix"}', 0),
  (983, 294, 'Is [[3,0,0],[0,4,2],[0,0,7]] diagonal?', 'text', 1, 'Look at row 2, column 3.', '{"why":"The off-diagonal entry 2 violates the definition.","sol":"Step 1: The main diagonal is 3, 4, 7.\nStep 2: The entry in row 2, column 3 is 2.\nStep 3: That entry is outside the main diagonal.\nStep 4: A diagonal matrix requires it to be zero.\nStep 5: Therefore the matrix is not diagonal.","steps":["Step 1: The main diagonal is 3, 4, 7.","Step 2: The entry in row 2, column 3 is 2.","Step 3: That entry is outside the main diagonal.","Step 4: A diagonal matrix requires it to be zero.","Step 5: Therefore the matrix is not diagonal."],"options":[],"conceptId":"math_matrices_diagonal_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Diagonal Matrix"}', 1),
  (984, 294, 'Is [[5,0],[0,0]] a diagonal matrix?', 'text', 1, 'A zero is allowed on the main diagonal.', '{"why":"Diagonal entries may be zero; only off-diagonal entries must be zero.","sol":"Step 1: The main diagonal contains 5 and 0.\nStep 2: The only entry outside the main diagonal is 0.\nStep 3: Therefore all off-diagonal entries are zero.\nStep 4: The matrix is diagonal.","steps":["Step 1: The main diagonal contains 5 and 0.","Step 2: The only entry outside the main diagonal is 0.","Step 3: Therefore all off-diagonal entries are zero.","Step 4: The matrix is diagonal."],"options":[],"conceptId":"math_matrices_diagonal_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Diagonal Matrix"}', 2),
  (985, 294, 'A student says [[0,0],[0,0]] cannot be diagonal because the diagonal entries are zero. Is the student correct?', 'text', 1, 'The definition places the restriction on entries outside the diagonal.', '{"why":"A zero matrix is also a diagonal matrix because all of its off-diagonal entries are zero.","sol":"Step 1: The main diagonal contains 0 and 0.\nStep 2: Both entries outside the main diagonal are also zero.\nStep 3: There is no requirement that diagonal entries be non-zero.\nStep 4: Therefore the matrix is diagonal.","steps":["Step 1: The main diagonal contains 0 and 0.","Step 2: Both entries outside the main diagonal are also zero.","Step 3: There is no requirement that diagonal entries be non-zero.","Step 4: Therefore the matrix is diagonal."],"options":[],"conceptId":"math_matrices_diagonal_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Diagonal Matrix"}', 3),
  (986, 295, 'Is [[1,0],[0,1]] an identity matrix?', 'text', 1, 'Check the diagonal and the entries outside it.', '{"why":"It satisfies both identity-matrix conditions.","sol":"Step 1: The matrix is square: 2 rows and 2 columns.\nStep 2: The main diagonal contains 1 and 1.\nStep 3: The off-diagonal entries are both 0.\nStep 4: Therefore it is I₂.","steps":["Step 1: The matrix is square: 2 rows and 2 columns.","Step 2: The main diagonal contains 1 and 1.","Step 3: The off-diagonal entries are both 0.","Step 4: Therefore it is I₂."],"options":[],"conceptId":"math_matrices_identity_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Identity Matrix"}', 0),
  (987, 295, 'Is [[1,0],[0,2]] an identity matrix?', 'text', 1, 'Check every entry on the main diagonal.', '{"why":"The diagonal must contain only 1s.","sol":"Step 1: The main diagonal contains 1 and 2.\nStep 2: An identity matrix requires every diagonal entry to be 1.\nStep 3: The second diagonal entry is 2.\nStep 4: Therefore it is not an identity matrix.","steps":["Step 1: The main diagonal contains 1 and 2.","Step 2: An identity matrix requires every diagonal entry to be 1.","Step 3: The second diagonal entry is 2.","Step 4: Therefore it is not an identity matrix."],"options":[],"conceptId":"math_matrices_identity_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Identity Matrix"}', 1),
  (988, 295, 'Is [[1,0],[1,1]] an identity matrix?', 'text', 1, 'The diagonal is correct, but check outside the diagonal.', '{"why":"Every off-diagonal entry must be zero.","sol":"Step 1: The main diagonal contains 1 and 1.\nStep 2: The bottom-left entry is outside the main diagonal.\nStep 3: That entry is 1, but it must be 0.\nStep 4: Therefore the matrix is not an identity matrix.","steps":["Step 1: The main diagonal contains 1 and 1.","Step 2: The bottom-left entry is outside the main diagonal.","Step 3: That entry is 1, but it must be 0.","Step 4: Therefore the matrix is not an identity matrix."],"options":[],"conceptId":"math_matrices_identity_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Identity Matrix"}', 2),
  (989, 295, 'Which matrix is I₃: A = [[1,0,0],[0,1,0],[0,0,1]] or B = [[1,0,0],[0,2,0],[0,0,1]]?', 'text', 1, 'The diagonal of an identity matrix must contain only 1s.', '{"why":"A has 1s on the entire main diagonal and zeros everywhere else.","sol":"Step 1: For A, the main diagonal is 1, 1, 1 and all other entries are zero.\nStep 2: For B, the main diagonal is 1, 2, 1.\nStep 3: The 2 in B violates the identity-matrix condition.\nStep 4: Therefore A is I₃.","steps":["Step 1: For A, the main diagonal is 1, 1, 1 and all other entries are zero.","Step 2: For B, the main diagonal is 1, 2, 1.","Step 3: The 2 in B violates the identity-matrix condition.","Step 4: Therefore A is I₃."],"options":[],"conceptId":"math_matrices_identity_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Identity Matrix"}', 3),
  (990, 296, 'Are A = [[2,5],[7,9]] and B = [[2,5],[7,9]] equal?', 'text', 1, 'First compare their orders, then compare corresponding entries.', '{"why":"The matrices have the same order and all corresponding elements are equal.","sol":"Step 1: Both matrices have order 2 × 2.\nStep 2: Compare 2 with 2: equal.\nStep 3: Compare 5 with 5: equal.\nStep 4: Compare 7 with 7: equal.\nStep 5: Compare 9 with 9: equal.\nStep 6: All corresponding elements are equal.","steps":["Step 1: Both matrices have order 2 × 2.","Step 2: Compare 2 with 2: equal.","Step 3: Compare 5 with 5: equal.","Step 4: Compare 7 with 7: equal.","Step 5: Compare 9 with 9: equal.","Step 6: All corresponding elements are equal."],"options":[],"conceptId":"math_matrices_equality_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Equality of Matrices"}', 0),
  (991, 296, 'Are A = [[2,5],[7,9]] and B = [[2,5],[7,4]] equal?', 'text', 1, 'Look for even one corresponding pair that is different.', '{"why":"All corresponding elements must be equal; one mismatch makes the matrices unequal.","sol":"Step 1: Both matrices have order 2 × 2.\nStep 2: The first three corresponding entries agree.\nStep 3: Compare the bottom-right entries: 9 and 4.\nStep 4: Since 9 is not equal to 4, the matrices are not equal.","steps":["Step 1: Both matrices have order 2 × 2.","Step 2: The first three corresponding entries agree.","Step 3: Compare the bottom-right entries: 9 and 4.","Step 4: Since 9 is not equal to 4, the matrices are not equal."],"options":[],"conceptId":"math_matrices_equality_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Equality of Matrices"}', 1),
  (992, 296, 'If [[x,4],[2,9]] = [[7,4],[2,9]], find x.', 'text', 1, 'Equal matrices have equal corresponding elements.', '{"why":"Corresponding elements of equal matrices must have the same value.","sol":"Step 1: Compare the top-left entries.\nStep 2: The first matrix has x there.\nStep 3: The second matrix has 7 there.\nStep 4: Therefore x = 7.\nStep 5: The remaining corresponding entries already agree.","steps":["Step 1: Compare the top-left entries.","Step 2: The first matrix has x there.","Step 3: The second matrix has 7 there.","Step 4: Therefore x = 7.","Step 5: The remaining corresponding entries already agree."],"options":[],"conceptId":"math_matrices_equality_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Equality of Matrices"}', 2),
  (993, 296, 'Can a 2 × 3 matrix be equal to a 3 × 2 matrix?', 'text', 1, 'Compare the orders before looking at the entries.', '{"why":"Equal matrices must have exactly the same number of rows and columns.","sol":"Step 1: The first matrix has order 2 × 3.\nStep 2: The second matrix has order 3 × 2.\nStep 3: Their orders are different.\nStep 4: Matrices with different orders cannot be equal.","steps":["Step 1: The first matrix has order 2 × 3.","Step 2: The second matrix has order 3 × 2.","Step 3: Their orders are different.","Step 4: Matrices with different orders cannot be equal."],"options":[],"conceptId":"math_matrices_equality_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Equality of Matrices"}', 3),
  (994, 296, 'A student says [[1,2],[3,4]] and [[2,1],[4,3]] are equal because they contain the same four numbers. Is the student correct?', 'text', 1, 'Equality depends on corresponding positions, not merely the numbers present.', '{"why":"The same numbers must also occur in the same corresponding positions.","sol":"Step 1: Both matrices have order 2 × 2.\nStep 2: Compare the top-left entries: 1 and 2.\nStep 3: They are different.\nStep 4: Therefore the matrices are not equal.","steps":["Step 1: Both matrices have order 2 × 2.","Step 2: Compare the top-left entries: 1 and 2.","Step 3: They are different.","Step 4: Therefore the matrices are not equal."],"options":[],"conceptId":"math_matrices_equality_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q5","subject":"math","chapter":"matrices","topic":"Equality of Matrices"}', 4),
  (995, 297, 'Find [[2,5],[7,3]] + [[4,1],[6,8]].', 'text', 1, 'Add entries occupying the same position.', '{"why":"Matrix addition is performed element-by-element at corresponding positions.","sol":"Step 1: Top-left: 2 + 4 = 6.\nStep 2: Top-right: 5 + 1 = 6.\nStep 3: Bottom-left: 7 + 6 = 13.\nStep 4: Bottom-right: 3 + 8 = 11.\nStep 5: Place each result in its original position.","steps":["Step 1: Top-left: 2 + 4 = 6.","Step 2: Top-right: 5 + 1 = 6.","Step 3: Bottom-left: 7 + 6 = 13.","Step 4: Bottom-right: 3 + 8 = 11.","Step 5: Place each result in its original position."],"options":[],"conceptId":"math_matrices_matrix_addition","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Matrix Addition"}', 0),
  (996, 297, 'Find [[5,-3],[4,6]] + [[-2,7],[8,-1]].', 'text', 1, 'Treat each negative number as part of the calculation.', '{"why":"Corresponding elements are added, including their signs.","sol":"Step 1: 5 + (-2) = 3.\nStep 2: -3 + 7 = 4.\nStep 3: 4 + 8 = 12.\nStep 4: 6 + (-1) = 5.\nStep 5: Therefore the result is [[3,4],[12,5]].","steps":["Step 1: 5 + (-2) = 3.","Step 2: -3 + 7 = 4.","Step 3: 4 + 8 = 12.","Step 4: 6 + (-1) = 5.","Step 5: Therefore the result is [[3,4],[12,5]]."],"options":[],"conceptId":"math_matrices_matrix_addition","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Matrix Addition"}', 1),
  (997, 297, 'Can a 2 × 3 matrix be added to a 3 × 2 matrix?', 'text', 1, 'Matrix addition requires the same order.', '{"why":"Matrices must have the same order before they can be added.","sol":"Step 1: The first matrix has order 2 × 3.\nStep 2: The second has order 3 × 2.\nStep 3: Their orders are different.\nStep 4: Therefore corresponding positions cannot be matched.","steps":["Step 1: The first matrix has order 2 × 3.","Step 2: The second has order 3 × 2.","Step 3: Their orders are different.","Step 4: Therefore corresponding positions cannot be matched."],"options":[],"conceptId":"math_matrices_matrix_addition","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Matrix Addition"}', 2),
  (998, 297, 'A student calculates [[1,2],[3,4]] + [[5,6],[7,8]] as [[6,8],[10,12]]. Explain whether the answer is correct.', 'text', 1, 'Check each corresponding position.', '{"why":"Every corresponding pair has been added correctly and placed in the correct position.","sol":"Step 1: Top-left: 1 + 5 = 6.\nStep 2: Top-right: 2 + 6 = 8.\nStep 3: Bottom-left: 3 + 7 = 10.\nStep 4: Bottom-right: 4 + 8 = 12.\nStep 5: Every entry is correct.","steps":["Step 1: Top-left: 1 + 5 = 6.","Step 2: Top-right: 2 + 6 = 8.","Step 3: Bottom-left: 3 + 7 = 10.","Step 4: Bottom-right: 4 + 8 = 12.","Step 5: Every entry is correct."],"options":[],"conceptId":"math_matrices_matrix_addition","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Matrix Addition"}', 3),
  (999, 298, 'Find [[9,7],[6,5]] - [[4,2],[1,3]].', 'text', 1, 'Subtract the second matrix from the first at each corresponding position.', '{"why":"Matrix subtraction is performed position by position.","sol":"Step 1: 9 - 4 = 5.\nStep 2: 7 - 2 = 5.\nStep 3: 6 - 1 = 5.\nStep 4: 5 - 3 = 2.\nStep 5: Therefore the result is [[5,5],[5,2]].","steps":["Step 1: 9 - 4 = 5.","Step 2: 7 - 2 = 5.","Step 3: 6 - 1 = 5.","Step 4: 5 - 3 = 2.","Step 5: Therefore the result is [[5,5],[5,2]]."],"options":[],"conceptId":"math_matrices_matrix_subtraction","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Matrix Subtraction"}', 0),
  (1000, 298, 'Find [[4,-2],[3,8]] - [[7,-5],[1,4]].', 'text', 1, 'Pay special attention to -2 - (-5).', '{"why":"Subtracting a negative number is equivalent to adding its positive value.","sol":"Step 1: 4 - 7 = -3.\nStep 2: -2 - (-5) = -2 + 5 = 3.\nStep 3: 3 - 1 = 2.\nStep 4: 8 - 4 = 4.","steps":["Step 1: 4 - 7 = -3.","Step 2: -2 - (-5) = -2 + 5 = 3.","Step 3: 3 - 1 = 2.","Step 4: 8 - 4 = 4."],"options":[],"conceptId":"math_matrices_matrix_subtraction","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Matrix Subtraction"}', 1);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (1001, 298, 'Given A = [[8,5],[6,4]] and B = [[3,2],[1,7]], find A - B.', 'text', 1, 'The first matrix always supplies the number being subtracted from.', '{"why":"A - B means corresponding elements of B are subtracted from corresponding elements of A.","sol":"Step 1: 8 - 3 = 5.\nStep 2: 5 - 2 = 3.\nStep 3: 6 - 1 = 5.\nStep 4: 4 - 7 = -3.","steps":["Step 1: 8 - 3 = 5.","Step 2: 5 - 2 = 3.","Step 3: 6 - 1 = 5.","Step 4: 4 - 7 = -3."],"options":[],"conceptId":"math_matrices_matrix_subtraction","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Matrix Subtraction"}', 2),
  (1002, 298, 'Can a 2 × 2 matrix be subtracted from a 2 × 3 matrix?', 'text', 1, 'Compare their orders.', '{"why":"Both matrices must have the same order.","sol":"Step 1: The first matrix has 2 rows and 2 columns.\nStep 2: The second has 2 rows and 3 columns.\nStep 3: Their orders are different.\nStep 4: Therefore subtraction is not defined.","steps":["Step 1: The first matrix has 2 rows and 2 columns.","Step 2: The second has 2 rows and 3 columns.","Step 3: Their orders are different.","Step 4: Therefore subtraction is not defined."],"options":[],"conceptId":"math_matrices_matrix_subtraction","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Matrix Subtraction"}', 3),
  (1003, 299, 'Find 3[[2,4],[3,5]].', 'text', 1, 'Multiply every entry by 3.', '{"why":"A scalar multiplies every element of the matrix.","sol":"Step 1: 3 × 2 = 6.\nStep 2: 3 × 4 = 12.\nStep 3: 3 × 3 = 9.\nStep 4: 3 × 5 = 15.\nStep 5: Keep the results in their original positions.","steps":["Step 1: 3 × 2 = 6.","Step 2: 3 × 4 = 12.","Step 3: 3 × 3 = 9.","Step 4: 3 × 5 = 15.","Step 5: Keep the results in their original positions."],"options":[],"conceptId":"math_matrices_scalar_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Scalar Multiplication"}', 0),
  (1004, 299, 'Find -2[[3,-4],[5,1]].', 'text', 1, 'Apply -2 separately to each entry.', '{"why":"The negative scalar changes the sign of positive entries and must also be applied to negative entries.","sol":"Step 1: -2 × 3 = -6.\nStep 2: -2 × (-4) = 8.\nStep 3: -2 × 5 = -10.\nStep 4: -2 × 1 = -2.","steps":["Step 1: -2 × 3 = -6.","Step 2: -2 × (-4) = 8.","Step 3: -2 × 5 = -10.","Step 4: -2 × 1 = -2."],"options":[],"conceptId":"math_matrices_scalar_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Scalar Multiplication"}', 1),
  (1005, 299, 'If A is a 2 × 3 matrix, what is the order of 5A?', 'text', 1, 'Scalar multiplication changes values, not dimensions.', '{"why":"Scalar multiplication does not change the order of a matrix.","sol":"Step 1: A has 2 rows and 3 columns.\nStep 2: Multiplying each entry by 5 does not create or remove entries.\nStep 3: Therefore 5A still has 2 rows and 3 columns.","steps":["Step 1: A has 2 rows and 3 columns.","Step 2: Multiplying each entry by 5 does not create or remove entries.","Step 3: Therefore 5A still has 2 rows and 3 columns."],"options":[],"conceptId":"math_matrices_scalar_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Scalar Multiplication"}', 2),
  (1006, 299, 'Find 0[[7,-2],[4,9]].', 'text', 1, 'Every number multiplied by zero becomes zero.', '{"why":"Multiplying every element by zero produces the zero matrix.","sol":"Step 1: 0 × 7 = 0.\nStep 2: 0 × (-2) = 0.\nStep 3: 0 × 4 = 0.\nStep 4: 0 × 9 = 0.\nStep 5: Therefore every element becomes zero.","steps":["Step 1: 0 × 7 = 0.","Step 2: 0 × (-2) = 0.","Step 3: 0 × 4 = 0.","Step 4: 0 × 9 = 0.","Step 5: Therefore every element becomes zero."],"options":[],"conceptId":"math_matrices_scalar_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Scalar Multiplication"}', 3),
  (1007, 300, 'Find AB where A = [[2,3],[1,5]] and B = [[4,1],[2,3]].', 'text', 1, 'For each answer entry, use a row from A and a column from B.', '{"why":"Each result entry comes from the dot product of a row of A with a column of B.","sol":"Step 1: Top-left: (2×4) + (3×2) = 8 + 6 = 14.\nStep 2: Top-right: (2×1) + (3×3) = 2 + 9 = 11.\nStep 3: Bottom-left: (1×4) + (5×2) = 4 + 10 = 14.\nStep 4: Bottom-right: (1×1) + (5×3) = 1 + 15 = 16.\nStep 5: Therefore AB = [[14,11],[14,16]].","steps":["Step 1: Top-left: (2×4) + (3×2) = 8 + 6 = 14.","Step 2: Top-right: (2×1) + (3×3) = 2 + 9 = 11.","Step 3: Bottom-left: (1×4) + (5×2) = 4 + 10 = 14.","Step 4: Bottom-right: (1×1) + (5×3) = 1 + 15 = 16.","Step 5: Therefore AB = [[14,11],[14,16]]."],"options":[],"conceptId":"math_matrices_matrix_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Matrix Multiplication"}', 0),
  (1008, 300, 'Can a 2 × 3 matrix be multiplied by a 2 × 2 matrix?', 'text', 1, 'Compare the columns of the first matrix with the rows of the second.', '{"why":"For AB to exist, the number of columns in A must equal the number of rows in B.","sol":"Step 1: The first matrix has 3 columns.\nStep 2: The second matrix has 2 rows.\nStep 3: The inner dimensions are 3 and 2.\nStep 4: Since 3 is not equal to 2, multiplication is not possible.","steps":["Step 1: The first matrix has 3 columns.","Step 2: The second matrix has 2 rows.","Step 3: The inner dimensions are 3 and 2.","Step 4: Since 3 is not equal to 2, multiplication is not possible."],"options":[],"conceptId":"math_matrices_matrix_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Matrix Multiplication"}', 1),
  (1009, 300, 'Find the top-left entry of AB if A = [[1,2,3],[4,5,6]] and B = [[2,1],[0,3],[1,2]].', 'text', 1, 'Use row 1 of A and column 1 of B.', '{"why":"The top-left entry is the dot product of the first row of A and first column of B.","sol":"Step 1: Row 1 of A is [1,2,3].\nStep 2: Column 1 of B is [2,0,1].\nStep 3: Multiply corresponding values: (1×2), (2×0), (3×1).\nStep 4: Add: 2 + 0 + 3 = 5.","steps":["Step 1: Row 1 of A is [1,2,3].","Step 2: Column 1 of B is [2,0,1].","Step 3: Multiply corresponding values: (1×2), (2×0), (3×1).","Step 4: Add: 2 + 0 + 3 = 5."],"options":[],"conceptId":"math_matrices_matrix_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Matrix Multiplication"}', 2),
  (1010, 300, 'A student calculates the top-left entry of [[2,3],[1,5]] × [[4,1],[2,3]] as 2 × 4 = 8. What is wrong?', 'text', 1, 'One product is not enough.', '{"why":"Matrix multiplication requires multiplying all corresponding row-column pairs and adding the products.","sol":"Step 1: The top-left entry requires row 1 of the first matrix and column 1 of the second.\nStep 2: Those values are [2,3] and [4,2].\nStep 3: Calculate both products: 2×4 = 8 and 3×2 = 6.\nStep 4: Add the products: 8 + 6 = 14.\nStep 5: Therefore 8 is incomplete.","steps":["Step 1: The top-left entry requires row 1 of the first matrix and column 1 of the second.","Step 2: Those values are [2,3] and [4,2].","Step 3: Calculate both products: 2×4 = 8 and 3×2 = 6.","Step 4: Add the products: 8 + 6 = 14.","Step 5: Therefore 8 is incomplete."],"options":[],"conceptId":"math_matrices_matrix_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Matrix Multiplication"}', 3),
  (1011, 301, 'Find the transpose of A = [2 5 7; 1 4 6].', 'text', 1, 'Turn the first row into the first column and the second row into the second column.', '{"why":"Each row of the original matrix becomes the corresponding column of its transpose.","sol":"Step 1: The first row is 2, 5, 7.\nStep 2: Write 2, 5, 7 vertically as the first column.\nStep 3: The second row is 1, 4, 6.\nStep 4: Write 1, 4, 6 vertically as the second column.\nStep 5: Therefore Aᵀ = [2 1; 5 4; 7 6].","steps":["Step 1: The first row is 2, 5, 7.","Step 2: Write 2, 5, 7 vertically as the first column.","Step 3: The second row is 1, 4, 6.","Step 4: Write 1, 4, 6 vertically as the second column.","Step 5: Therefore Aᵀ = [2 1; 5 4; 7 6]."],"options":[],"conceptId":"math_matrices_transpose_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Transpose of a Matrix"}', 0),
  (1012, 301, 'Find the transpose of B = [3 8; 5 1; 7 4].', 'text', 1, 'There are three rows, so each of the three rows becomes a column.', '{"why":"The transpose changes the orientation of every row from horizontal to vertical.","sol":"Step 1: Row 1 is 3, 8, so it becomes column 1.\nStep 2: Row 2 is 5, 1, so it becomes column 2.\nStep 3: Row 3 is 7, 4, so it becomes column 3.\nStep 4: Therefore Bᵀ = [3 5 7; 8 1 4].","steps":["Step 1: Row 1 is 3, 8, so it becomes column 1.","Step 2: Row 2 is 5, 1, so it becomes column 2.","Step 3: Row 3 is 7, 4, so it becomes column 3.","Step 4: Therefore Bᵀ = [3 5 7; 8 1 4]."],"options":[],"conceptId":"math_matrices_transpose_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Transpose of a Matrix"}', 1),
  (1013, 301, 'Find the transpose of C = [-2 4; 6 -5].', 'text', 1, 'Do not change the negative signs. Only move the entries.', '{"why":"Transposition changes positions, not values or signs.","sol":"Step 1: The first row is -2, 4.\nStep 2: It becomes the first column: -2, 4.\nStep 3: The second row is 6, -5.\nStep 4: It becomes the second column: 6, -5.\nStep 5: Therefore Cᵀ = [-2 6; 4 -5].","steps":["Step 1: The first row is -2, 4.","Step 2: It becomes the first column: -2, 4.","Step 3: The second row is 6, -5.","Step 4: It becomes the second column: 6, -5.","Step 5: Therefore Cᵀ = [-2 6; 4 -5]."],"options":[],"conceptId":"math_matrices_transpose_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Transpose of a Matrix"}', 2),
  (1014, 301, 'Find the transpose of D = [1 2 3; 4 5 6; 7 8 9].', 'text', 1, 'Move row 1 to column 1, row 2 to column 2, and row 3 to column 3.', '{"why":"Every row becomes the corresponding column.","sol":"Step 1: Row 1, 1 2 3, becomes column 1.\nStep 2: Row 2, 4 5 6, becomes column 2.\nStep 3: Row 3, 7 8 9, becomes column 3.\nStep 4: Therefore Dᵀ = [1 4 7; 2 5 8; 3 6 9].","steps":["Step 1: Row 1, 1 2 3, becomes column 1.","Step 2: Row 2, 4 5 6, becomes column 2.","Step 3: Row 3, 7 8 9, becomes column 3.","Step 4: Therefore Dᵀ = [1 4 7; 2 5 8; 3 6 9]."],"options":[],"conceptId":"math_matrices_transpose_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Transpose of a Matrix"}', 3),
  (1015, 301, 'A = [4 7; 2 9]. Which matrix is Aᵀ?', 'text', 1, 'The 4 stays in the top-left position. The 7 and 2 exchange their positions.', '{"why":"Transposition swaps the row and column position of each entry.","sol":"Step 1: The first row 4, 7 becomes the first column.\nStep 2: The second row 2, 9 becomes the second column.\nStep 3: So the transpose is [4 2; 7 9].","steps":["Step 1: The first row 4, 7 becomes the first column.","Step 2: The second row 2, 9 becomes the second column.","Step 3: So the transpose is [4 2; 7 9]."],"options":[],"conceptId":"math_matrices_transpose_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q5","subject":"math","chapter":"matrices","topic":"Transpose of a Matrix"}', 4),
  (1016, 302, 'Find A + B if A = [2 5; 7 1] and B = [4 3; 6 8].', 'text', 1, 'Add entries occupying the same positions.', '{"why":"Matrix addition is performed entry-by-entry using corresponding positions.","sol":"Step 1: Top-left: 2 + 4 = 6.\nStep 2: Top-right: 5 + 3 = 8.\nStep 3: Bottom-left: 7 + 6 = 13.\nStep 4: Bottom-right: 1 + 8 = 9.\nStep 5: Therefore A + B = [6 8; 13 9].","steps":["Step 1: Top-left: 2 + 4 = 6.","Step 2: Top-right: 5 + 3 = 8.","Step 3: Bottom-left: 7 + 6 = 13.","Step 4: Bottom-right: 1 + 8 = 9.","Step 5: Therefore A + B = [6 8; 13 9]."],"options":[],"conceptId":"math_matrices_addition_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Addition of Matrices"}', 0),
  (1017, 302, 'Find P + Q if P = [6 -3; -2 5] and Q = [-4 7; 8 -1].', 'text', 1, 'Remember that adding a negative number is ordinary integer addition.', '{"why":"Each corresponding pair of entries is added independently.","sol":"Step 1: 6 + (-4) = 2.\nStep 2: -3 + 7 = 4.\nStep 3: -2 + 8 = 6.\nStep 4: 5 + (-1) = 4.\nStep 5: Therefore P + Q = [2 4; 6 4].","steps":["Step 1: 6 + (-4) = 2.","Step 2: -3 + 7 = 4.","Step 3: -2 + 8 = 6.","Step 4: 5 + (-1) = 4.","Step 5: Therefore P + Q = [2 4; 6 4]."],"options":[],"conceptId":"math_matrices_addition_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Addition of Matrices"}', 1),
  (1018, 302, 'Can [1 2; 3 4] be added to [5 6 7; 8 9 10]?', 'text', 1, 'Compare the sizes of the two matrices.', '{"why":"Two matrices must have the same size before matrix addition is possible.","sol":"Step 1: The first matrix has 2 rows and 2 columns.\nStep 2: The second matrix has 2 rows and 3 columns.\nStep 3: Their sizes are different.\nStep 4: Therefore corresponding positions cannot be matched throughout.\nStep 5: The matrices cannot be added.","steps":["Step 1: The first matrix has 2 rows and 2 columns.","Step 2: The second matrix has 2 rows and 3 columns.","Step 3: Their sizes are different.","Step 4: Therefore corresponding positions cannot be matched throughout.","Step 5: The matrices cannot be added."],"options":[],"conceptId":"math_matrices_addition_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Addition of Matrices"}', 2),
  (1019, 302, 'Find X + Y if X = [1 4 7; 2 5 8] and Y = [3 2 1; 6 4 2].', 'text', 1, 'Add each position separately.', '{"why":"Corresponding entries are added while their positions remain unchanged.","sol":"Step 1: 1 + 3 = 4.\nStep 2: 4 + 2 = 6.\nStep 3: 7 + 1 = 8.\nStep 4: 2 + 6 = 8.\nStep 5: 5 + 4 = 9.\nStep 6: 8 + 2 = 10.\nStep 7: Therefore X + Y = [4 6 8; 8 9 10].","steps":["Step 1: 1 + 3 = 4.","Step 2: 4 + 2 = 6.","Step 3: 7 + 1 = 8.","Step 4: 2 + 6 = 8.","Step 5: 5 + 4 = 9.","Step 6: 8 + 2 = 10.","Step 7: Therefore X + Y = [4 6 8; 8 9 10]."],"options":[],"conceptId":"math_matrices_addition_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Addition of Matrices"}', 3),
  (1020, 303, 'Find A - B if A = [9 7; 5 3] and B = [4 2; 1 6].', 'text', 1, 'Subtract corresponding entries: A entry minus B entry.', '{"why":"Matrix subtraction is performed position by position.","sol":"Step 1: 9 - 4 = 5.\nStep 2: 7 - 2 = 5.\nStep 3: 5 - 1 = 4.\nStep 4: 3 - 6 = -3.\nStep 5: Therefore A - B = [5 5; 4 -3].","steps":["Step 1: 9 - 4 = 5.","Step 2: 7 - 2 = 5.","Step 3: 5 - 1 = 4.","Step 4: 3 - 6 = -3.","Step 5: Therefore A - B = [5 5; 4 -3]."],"options":[],"conceptId":"math_matrices_subtraction_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Subtraction of Matrices"}', 0),
  (1021, 303, 'Find P - Q if P = [6 -2; -4 7] and Q = [-3 5; 2 -1].', 'text', 1, 'Be especially careful when subtracting negative numbers.', '{"why":"The subtraction follows the order P minus Q at every corresponding position.","sol":"Step 1: 6 - (-3) = 9.\nStep 2: -2 - 5 = -7.\nStep 3: -4 - 2 = -6.\nStep 4: 7 - (-1) = 8.\nStep 5: Therefore P - Q = [9 -7; -6 8].","steps":["Step 1: 6 - (-3) = 9.","Step 2: -2 - 5 = -7.","Step 3: -4 - 2 = -6.","Step 4: 7 - (-1) = 8.","Step 5: Therefore P - Q = [9 -7; -6 8]."],"options":[],"conceptId":"math_matrices_subtraction_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Subtraction of Matrices"}', 1),
  (1022, 303, 'Using A = [8 5; 3 1] and B = [2 4; 6 7], find A - B.', 'text', 1, 'Keep A first throughout the calculation.', '{"why":"Changing the order of subtraction changes the signs of the corresponding differences.","sol":"Step 1: 8 - 2 = 6.\nStep 2: 5 - 4 = 1.\nStep 3: 3 - 6 = -3.\nStep 4: 1 - 7 = -6.\nStep 5: Therefore A - B = [6 1; -3 -6].","steps":["Step 1: 8 - 2 = 6.","Step 2: 5 - 4 = 1.","Step 3: 3 - 6 = -3.","Step 4: 1 - 7 = -6.","Step 5: Therefore A - B = [6 1; -3 -6]."],"options":[],"conceptId":"math_matrices_subtraction_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Subtraction of Matrices"}', 2),
  (1023, 303, 'Can a 2 × 2 matrix be subtracted from a 2 × 3 matrix?', 'text', 1, 'Check whether the two matrices have the same size.', '{"why":"Matrices must have the same size for subtraction.","sol":"Step 1: The first matrix has 2 rows and 2 columns.\nStep 2: The second matrix has 2 rows and 3 columns.\nStep 3: Their sizes are different.\nStep 4: Therefore matrix subtraction is not defined.","steps":["Step 1: The first matrix has 2 rows and 2 columns.","Step 2: The second matrix has 2 rows and 3 columns.","Step 3: Their sizes are different.","Step 4: Therefore matrix subtraction is not defined."],"options":[],"conceptId":"math_matrices_subtraction_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Subtraction of Matrices"}', 3),
  (1024, 304, 'Find 3A if A = [2 4; 5 1].', 'text', 1, 'Multiply every entry by 3.', '{"why":"Scalar multiplication applies the scalar to every entry of the matrix.","sol":"Step 1: 3 × 2 = 6.\nStep 2: 3 × 4 = 12.\nStep 3: 3 × 5 = 15.\nStep 4: 3 × 1 = 3.\nStep 5: Therefore 3A = [6 12; 15 3].","steps":["Step 1: 3 × 2 = 6.","Step 2: 3 × 4 = 12.","Step 3: 3 × 5 = 15.","Step 4: 3 × 1 = 3.","Step 5: Therefore 3A = [6 12; 15 3]."],"options":[],"conceptId":"math_matrices_scalar_multiplication_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Scalar Multiplication of a Matrix"}', 0),
  (1025, 304, 'Find -2B if B = [3 -4; -5 2].', 'text', 1, 'Multiply each entry by -2 and carefully handle the signs.', '{"why":"The negative scalar changes the sign of each non-zero entry according to multiplication rules.","sol":"Step 1: -2 × 3 = -6.\nStep 2: -2 × (-4) = 8.\nStep 3: -2 × (-5) = 10.\nStep 4: -2 × 2 = -4.\nStep 5: Therefore -2B = [-6 8; 10 -4].","steps":["Step 1: -2 × 3 = -6.","Step 2: -2 × (-4) = 8.","Step 3: -2 × (-5) = 10.","Step 4: -2 × 2 = -4.","Step 5: Therefore -2B = [-6 8; 10 -4]."],"options":[],"conceptId":"math_matrices_scalar_multiplication_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Scalar Multiplication of a Matrix"}', 1),
  (1026, 304, 'Find 1/2 C if C = [6 10; 4 8].', 'text', 1, 'Half of each entry is the same as multiplying each entry by 1/2.', '{"why":"A scalar multiplies every entry independently.","sol":"Step 1: Half of 6 is 3.\nStep 2: Half of 10 is 5.\nStep 3: Half of 4 is 2.\nStep 4: Half of 8 is 4.\nStep 5: Therefore 1/2 C = [3 5; 2 4].","steps":["Step 1: Half of 6 is 3.","Step 2: Half of 10 is 5.","Step 3: Half of 4 is 2.","Step 4: Half of 8 is 4.","Step 5: Therefore 1/2 C = [3 5; 2 4]."],"options":[],"conceptId":"math_matrices_scalar_multiplication_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Scalar Multiplication of a Matrix"}', 2),
  (1027, 304, 'Find 4D if D = [1 -2 3; 0 5 -1].', 'text', 1, 'There are six entries, so all six must be multiplied by 4.', '{"why":"Every entry receives the same scalar multiplication.","sol":"Step 1: 4 × 1 = 4.\nStep 2: 4 × (-2) = -8.\nStep 3: 4 × 3 = 12.\nStep 4: 4 × 0 = 0.\nStep 5: 4 × 5 = 20.\nStep 6: 4 × (-1) = -4.\nStep 7: Therefore 4D = [4 -8 12; 0 20 -4].","steps":["Step 1: 4 × 1 = 4.","Step 2: 4 × (-2) = -8.","Step 3: 4 × 3 = 12.","Step 4: 4 × 0 = 0.","Step 5: 4 × 5 = 20.","Step 6: 4 × (-1) = -4.","Step 7: Therefore 4D = [4 -8 12; 0 20 -4]."],"options":[],"conceptId":"math_matrices_scalar_multiplication_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Scalar Multiplication of a Matrix"}', 3),
  (1028, 305, 'Find AB if A = [2 3; 1 4] and B = [5 2; 6 1].', 'text', 1, 'For each answer position, use a row from A and a column from B.', '{"why":"Each entry is formed by multiplying corresponding entries of one row and one column, then adding the products.","sol":"Step 1: Top-left: (2 × 5) + (3 × 6) = 10 + 18 = 28.\nStep 2: Top-right: (2 × 2) + (3 × 1) = 4 + 3 = 7.\nStep 3: Bottom-left: (1 × 5) + (4 × 6) = 5 + 24 = 29.\nStep 4: Bottom-right: (1 × 2) + (4 × 1) = 2 + 4 = 6.\nStep 5: Therefore AB = [28 7; 29 6].","steps":["Step 1: Top-left: (2 × 5) + (3 × 6) = 10 + 18 = 28.","Step 2: Top-right: (2 × 2) + (3 × 1) = 4 + 3 = 7.","Step 3: Bottom-left: (1 × 5) + (4 × 6) = 5 + 24 = 29.","Step 4: Bottom-right: (1 × 2) + (4 × 1) = 2 + 4 = 6.","Step 5: Therefore AB = [28 7; 29 6]."],"options":[],"conceptId":"math_matrices_multiplication_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Multiplication of Matrices"}', 0),
  (1029, 305, 'Find the top-left entry of AB if A = [4 1; 2 3] and B = [7 5; 6 8].', 'text', 1, 'Use row 1 of A and column 1 of B.', '{"why":"A matrix product entry is obtained from a row-column multiplication.","sol":"Step 1: Row 1 of A is [4 1].\nStep 2: Column 1 of B is [7; 6].\nStep 3: Multiply: 4 × 7 = 28 and 1 × 6 = 6.\nStep 4: Add: 28 + 6 = 34.\nStep 5: Therefore the top-left entry is 34.","steps":["Step 1: Row 1 of A is [4 1].","Step 2: Column 1 of B is [7; 6].","Step 3: Multiply: 4 × 7 = 28 and 1 × 6 = 6.","Step 4: Add: 28 + 6 = 34.","Step 5: Therefore the top-left entry is 34."],"options":[],"conceptId":"math_matrices_multiplication_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Multiplication of Matrices"}', 1),
  (1030, 305, 'Find AB if A = [3 2; 1 4] and B = [5; 6].', 'text', 1, 'There is only one column in B, so each row of A produces one answer.', '{"why":"Each row of A is combined with the single column of B.","sol":"Step 1: First row: (3 × 5) + (2 × 6) = 15 + 12 = 27.\nStep 2: Second row: (1 × 5) + (4 × 6) = 5 + 24 = 29.\nStep 3: Therefore AB = [27; 29].","steps":["Step 1: First row: (3 × 5) + (2 × 6) = 15 + 12 = 27.","Step 2: Second row: (1 × 5) + (4 × 6) = 5 + 24 = 29.","Step 3: Therefore AB = [27; 29]."],"options":[],"conceptId":"math_matrices_multiplication_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Multiplication of Matrices"}', 2),
  (1031, 305, 'Can A = [1 2 3; 4 5 6] be multiplied by B = [7 8; 9 10] in the order AB?', 'text', 1, 'Compare the number of columns in A with the number of rows in B.', '{"why":"Matrix multiplication requires the number of columns of the first matrix to equal the number of rows of the second matrix.","sol":"Step 1: A has 3 columns.\nStep 2: B has 2 rows.\nStep 3: For AB to exist, these two numbers must be equal.\nStep 4: Since 3 is not equal to 2, AB cannot be formed.","steps":["Step 1: A has 3 columns.","Step 2: B has 2 rows.","Step 3: For AB to exist, these two numbers must be equal.","Step 4: Since 3 is not equal to 2, AB cannot be formed."],"options":[],"conceptId":"math_matrices_multiplication_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Multiplication of Matrices"}', 3),
  (1032, 306, 'Find the determinant of A = [3 2; 5 4].', 'text', 1, 'Use ad - bc.', '{"why":"For a 2 × 2 matrix [a b; c d], the determinant is ad - bc.","sol":"Step 1: Multiply the main diagonal: 3 × 4 = 12.\nStep 2: Multiply the other diagonal: 2 × 5 = 10.\nStep 3: Subtract: 12 - 10 = 2.\nStep 4: Therefore det(A) = 2.","steps":["Step 1: Multiply the main diagonal: 3 × 4 = 12.","Step 2: Multiply the other diagonal: 2 × 5 = 10.","Step 3: Subtract: 12 - 10 = 2.","Step 4: Therefore det(A) = 2."],"options":[],"conceptId":"math_matrices_determinant_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Determinant of a 2 × 2 Matrix"}', 0),
  (1033, 306, 'Find the determinant of B = [2 7; 5 3].', 'text', 1, 'Calculate 2 × 3 first, then subtract 7 × 5.', '{"why":"The determinant uses the difference between the two diagonal products.","sol":"Step 1: 2 × 3 = 6.\nStep 2: 7 × 5 = 35.\nStep 3: 6 - 35 = -29.\nStep 4: Therefore det(B) = -29.","steps":["Step 1: 2 × 3 = 6.","Step 2: 7 × 5 = 35.","Step 3: 6 - 35 = -29.","Step 4: Therefore det(B) = -29."],"options":[],"conceptId":"math_matrices_determinant_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Determinant of a 2 × 2 Matrix"}', 1),
  (1034, 306, 'Find the determinant of C = [-2 4; 3 -5].', 'text', 1, 'Be careful with the two negative entries.', '{"why":"The negative signs are handled during ordinary multiplication before the final subtraction.","sol":"Step 1: (-2) × (-5) = 10.\nStep 2: 4 × 3 = 12.\nStep 3: 10 - 12 = -2.\nStep 4: Therefore det(C) = -2.","steps":["Step 1: (-2) × (-5) = 10.","Step 2: 4 × 3 = 12.","Step 3: 10 - 12 = -2.","Step 4: Therefore det(C) = -2."],"options":[],"conceptId":"math_matrices_determinant_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Determinant of a 2 × 2 Matrix"}', 2),
  (1035, 306, 'Find the determinant of D = [2 4; 1 2].', 'text', 1, 'Multiply the two diagonal pairs and subtract.', '{"why":"The two diagonal products are equal, so their difference is zero.","sol":"Step 1: 2 × 2 = 4.\nStep 2: 4 × 1 = 4.\nStep 3: 4 - 4 = 0.\nStep 4: Therefore det(D) = 0.","steps":["Step 1: 2 × 2 = 4.","Step 2: 4 × 1 = 4.","Step 3: 4 - 4 = 0.","Step 4: Therefore det(D) = 0."],"options":[],"conceptId":"math_matrices_determinant_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Determinant of a 2 × 2 Matrix"}', 3),
  (1036, 306, 'Which calculation gives the determinant of [5 2; 3 4]?', 'text', 1, 'Identify a, b, c and d before applying ad - bc.', '{"why":"The determinant is ad - bc, so the second diagonal product must be subtracted.","sol":"Step 1: a = 5, b = 2, c = 3, d = 4.\nStep 2: ad = 5 × 4 = 20.\nStep 3: bc = 2 × 3 = 6.\nStep 4: Therefore det(A) = 20 - 6 = 14.","steps":["Step 1: a = 5, b = 2, c = 3, d = 4.","Step 2: ad = 5 × 4 = 20.","Step 3: bc = 2 × 3 = 6.","Step 4: Therefore det(A) = 20 - 6 = 14."],"options":[],"conceptId":"math_matrices_determinant_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q5","subject":"math","chapter":"matrices","topic":"Determinant of a 2 × 2 Matrix"}', 4),
  (1037, 307, 'Find the determinant of A = [1 2 3; 0 4 5; 1 0 6].', 'text', 1, 'Expand along the first row using the signs +, -, +.', '{"why":"The determinant is obtained by expanding along the first row and calculating each 2 × 2 minor.","sol":"Step 1: First minor: (4 × 6) - (5 × 0) = 24.\nStep 2: First contribution: 1 × 24 = 24.\nStep 3: Second minor: (0 × 6) - (5 × 1) = -5.\nStep 4: Second contribution: -2 × (-5) = 10.\nStep 5: Third minor: (0 × 0) - (4 × 1) = -4.\nStep 6: Third contribution: 3 × (-4) = -12.\nStep 7: det(A) = 24 + 10 - 12 = 22.","steps":["Step 1: First minor: (4 × 6) - (5 × 0) = 24.","Step 2: First contribution: 1 × 24 = 24.","Step 3: Second minor: (0 × 6) - (5 × 1) = -5.","Step 4: Second contribution: -2 × (-5) = 10.","Step 5: Third minor: (0 × 0) - (4 × 1) = -4.","Step 6: Third contribution: 3 × (-4) = -12.","Step 7: det(A) = 24 + 10 - 12 = 22."],"options":[],"conceptId":"math_matrices_determinant_of_a_3_3_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Determinant of a 3 × 3 Matrix"}', 0),
  (1038, 307, 'Find the determinant of B = [2 0 1; 3 4 5; 1 2 6].', 'text', 1, 'The middle first-row entry is zero, so its entire contribution is zero.', '{"why":"Each first-row entry is combined with the determinant of the 2 × 2 matrix left after removing its row and column.","sol":"Step 1: First minor: (4 × 6) - (5 × 2) = 14.\nStep 2: First contribution: 2 × 14 = 28.\nStep 3: Second contribution: 0.\nStep 4: Third minor: (3 × 2) - (4 × 1) = 2.\nStep 5: Third contribution: 1 × 2 = 2.\nStep 6: det(B) = 28 + 0 + 2 = 30.","steps":["Step 1: First minor: (4 × 6) - (5 × 2) = 14.","Step 2: First contribution: 2 × 14 = 28.","Step 3: Second contribution: 0.","Step 4: Third minor: (3 × 2) - (4 × 1) = 2.","Step 5: Third contribution: 1 × 2 = 2.","Step 6: det(B) = 28 + 0 + 2 = 30."],"options":[],"conceptId":"math_matrices_determinant_of_a_3_3_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Determinant of a 3 × 3 Matrix"}', 1),
  (1039, 307, 'Find the determinant of C = [1 2 0; 3 4 5; 6 7 8].', 'text', 1, 'Use +, -, + across the first row.', '{"why":"The signs in the first-row expansion are positive, negative, positive.","sol":"Step 1: First contribution: 1[(4 × 8) - (5 × 7)] = -3.\nStep 2: Second contribution: -2[(3 × 8) - (5 × 6)] = -2(-6) = 12.\nStep 3: Third contribution is zero.\nStep 4: det(C) = -3 + 12 = 9.","steps":["Step 1: First contribution: 1[(4 × 8) - (5 × 7)] = -3.","Step 2: Second contribution: -2[(3 × 8) - (5 × 6)] = -2(-6) = 12.","Step 3: Third contribution is zero.","Step 4: det(C) = -3 + 12 = 9."],"options":[],"conceptId":"math_matrices_determinant_of_a_3_3_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Determinant of a 3 × 3 Matrix"}', 2),
  (1040, 308, 'Determine whether A = [2 4; 1 2] is singular or non-singular.', 'text', 1, 'Find the determinant first.', '{"why":"A square matrix is singular when its determinant is zero.","sol":"Step 1: det(A) = (2 × 2) - (4 × 1).\nStep 2: det(A) = 4 - 4 = 0.\nStep 3: A determinant of zero means the matrix is singular.","steps":["Step 1: det(A) = (2 × 2) - (4 × 1).","Step 2: det(A) = 4 - 4 = 0.","Step 3: A determinant of zero means the matrix is singular."],"options":[],"conceptId":"math_matrices_singular_and_non_singular_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Singular and Non-Singular Matrices"}', 0),
  (1041, 308, 'Determine whether B = [3 2; 5 4] is singular or non-singular.', 'text', 1, 'Calculate 3 × 4 - 2 × 5.', '{"why":"A non-zero determinant means the matrix is non-singular.","sol":"Step 1: det(B) = (3 × 4) - (2 × 5).\nStep 2: det(B) = 12 - 10 = 2.\nStep 3: 2 is not zero.\nStep 4: Therefore B is non-singular.","steps":["Step 1: det(B) = (3 × 4) - (2 × 5).","Step 2: det(B) = 12 - 10 = 2.","Step 3: 2 is not zero.","Step 4: Therefore B is non-singular."],"options":[],"conceptId":"math_matrices_singular_and_non_singular_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Singular and Non-Singular Matrices"}', 1),
  (1042, 308, 'Find x if [x 2; 3 6] is singular.', 'text', 1, 'Set the determinant equal to zero.', '{"why":"Singularity requires the determinant to equal zero.","sol":"Step 1: det(A) = (x × 6) - (2 × 3).\nStep 2: 6x - 6 = 0.\nStep 3: 6x = 6.\nStep 4: x = 1.","steps":["Step 1: det(A) = (x × 6) - (2 × 3).","Step 2: 6x - 6 = 0.","Step 3: 6x = 6.","Step 4: x = 1."],"options":[],"conceptId":"math_matrices_singular_and_non_singular_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Singular and Non-Singular Matrices"}', 2),
  (1043, 308, 'Find x if [x 1; 2 3] is singular.', 'text', 1, 'Set 3x - 2 equal to zero.', '{"why":"The value of x must make the determinant equal to zero.","sol":"Step 1: det(A) = 3x - 2.\nStep 2: 3x - 2 = 0.\nStep 3: 3x = 2.\nStep 4: x = 2/3.","steps":["Step 1: det(A) = 3x - 2.","Step 2: 3x - 2 = 0.","Step 3: 3x = 2.","Step 4: x = 2/3."],"options":[],"conceptId":"math_matrices_singular_and_non_singular_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Singular and Non-Singular Matrices"}', 3),
  (1044, 309, 'Find the inverse of A = [3 2; 1 4].', 'text', 1, 'First calculate the determinant.', '{"why":"The inverse of a 2 × 2 matrix follows the fixed inverse formula.","sol":"Step 1: det(A) = 3 × 4 - 2 × 1 = 10.\nStep 2: Swap 3 and 4.\nStep 3: Change 2 to -2 and 1 to -1.\nStep 4: Multiply the resulting matrix by 1/10.\nStep 5: A⁻¹ = [2/5 -1/5; -1/10 3/10].","steps":["Step 1: det(A) = 3 × 4 - 2 × 1 = 10.","Step 2: Swap 3 and 4.","Step 3: Change 2 to -2 and 1 to -1.","Step 4: Multiply the resulting matrix by 1/10.","Step 5: A⁻¹ = [2/5 -1/5; -1/10 3/10]."],"options":[],"conceptId":"math_matrices_inverse_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Inverse of a 2 × 2 Matrix"}', 0),
  (1045, 309, 'Find the inverse of B = [2 1; 5 3].', 'text', 1, 'The determinant is 1.', '{"why":"The determinant is 1, so the reciprocal factor is also 1.","sol":"Step 1: det(B) = 2 × 3 - 1 × 5 = 1.\nStep 2: Swap 2 and 3.\nStep 3: Change 1 to -1 and 5 to -5.\nStep 4: Multiply by 1/1.\nStep 5: B⁻¹ = [3 -1; -5 2].","steps":["Step 1: det(B) = 2 × 3 - 1 × 5 = 1.","Step 2: Swap 2 and 3.","Step 3: Change 1 to -1 and 5 to -5.","Step 4: Multiply by 1/1.","Step 5: B⁻¹ = [3 -1; -5 2]."],"options":[],"conceptId":"math_matrices_inverse_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Inverse of a 2 × 2 Matrix"}', 1),
  (1046, 309, 'Does C = [2 4; 1 2] have an inverse?', 'text', 1, 'Calculate its determinant.', '{"why":"A 2 × 2 matrix cannot have an inverse when its determinant is zero.","sol":"Step 1: det(C) = 2 × 2 - 4 × 1.\nStep 2: det(C) = 0.\nStep 3: An inverse requires a non-zero determinant.\nStep 4: Therefore C has no inverse.","steps":["Step 1: det(C) = 2 × 2 - 4 × 1.","Step 2: det(C) = 0.","Step 3: An inverse requires a non-zero determinant.","Step 4: Therefore C has no inverse."],"options":[],"conceptId":"math_matrices_inverse_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Inverse of a 2 × 2 Matrix"}', 2),
  (1047, 309, 'Find the inverse of D = [4 1; 2 1].', 'text', 1, 'The determinant is 2.', '{"why":"The inverse is obtained by rearranging the entries and multiplying by the reciprocal of the determinant.","sol":"Step 1: det(D) = 4 × 1 - 1 × 2 = 2.\nStep 2: Swap 4 and 1.\nStep 3: Change 1 to -1 and 2 to -2.\nStep 4: Multiply by 1/2.\nStep 5: D⁻¹ = [1/2 -1/2; -1 2].","steps":["Step 1: det(D) = 4 × 1 - 1 × 2 = 2.","Step 2: Swap 4 and 1.","Step 3: Change 1 to -1 and 2 to -2.","Step 4: Multiply by 1/2.","Step 5: D⁻¹ = [1/2 -1/2; -1 2]."],"options":[],"conceptId":"math_matrices_inverse_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Inverse of a 2 × 2 Matrix"}', 3),
  (1048, 310, 'Find X if X + [2 3; 4 5] = [7 9; 10 12].', 'text', 1, 'Subtract the known matrix from both sides.', '{"why":"Subtracting the known matrix isolates X.","sol":"Step 1: 7 - 2 = 5.\nStep 2: 9 - 3 = 6.\nStep 3: 10 - 4 = 6.\nStep 4: 12 - 5 = 7.\nStep 5: Therefore X = [5 6; 6 7].","steps":["Step 1: 7 - 2 = 5.","Step 2: 9 - 3 = 6.","Step 3: 10 - 4 = 6.","Step 4: 12 - 5 = 7.","Step 5: Therefore X = [5 6; 6 7]."],"options":[],"conceptId":"math_matrices_solving_matrix_equations","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Solving Matrix Equations"}', 0),
  (1049, 310, 'Find X if 3X = [12 15; 9 18].', 'text', 1, 'Divide every entry by 3.', '{"why":"The scalar 3 affects every entry, so every entry is divided by 3 to isolate X.","sol":"Step 1: 12 ÷ 3 = 4.\nStep 2: 15 ÷ 3 = 5.\nStep 3: 9 ÷ 3 = 3.\nStep 4: 18 ÷ 3 = 6.\nStep 5: Therefore X = [4 5; 3 6].","steps":["Step 1: 12 ÷ 3 = 4.","Step 2: 15 ÷ 3 = 5.","Step 3: 9 ÷ 3 = 3.","Step 4: 18 ÷ 3 = 6.","Step 5: Therefore X = [4 5; 3 6]."],"options":[],"conceptId":"math_matrices_solving_matrix_equations","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Solving Matrix Equations"}', 1),
  (1050, 310, 'Find X if X - [3 1; 2 4] = [5 7; 8 6].', 'text', 1, 'Add the known matrix to both sides.', '{"why":"Adding the subtracted matrix reverses the subtraction and isolates X.","sol":"Step 1: 5 + 3 = 8.\nStep 2: 7 + 1 = 8.\nStep 3: 8 + 2 = 10.\nStep 4: 6 + 4 = 10.\nStep 5: Therefore X = [8 8; 10 10].","steps":["Step 1: 5 + 3 = 8.","Step 2: 7 + 1 = 8.","Step 3: 8 + 2 = 10.","Step 4: 6 + 4 = 10.","Step 5: Therefore X = [8 8; 10 10]."],"options":[],"conceptId":"math_matrices_solving_matrix_equations","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Solving Matrix Equations"}', 2),
  (1051, 310, 'Find x and y if [x 4; 7 y] + [3 2; 1 5] = [8 6; 8 12].', 'text', 1, 'Use the top-left position to find x and the bottom-right position to find y.', '{"why":"Each unknown is determined by comparing the corresponding entries.","sol":"Step 1: Top-left: x + 3 = 8.\nStep 2: Therefore x = 5.\nStep 3: Bottom-right: y + 5 = 12.\nStep 4: Therefore y = 7.","steps":["Step 1: Top-left: x + 3 = 8.","Step 2: Therefore x = 5.","Step 3: Bottom-right: y + 5 = 12.","Step 4: Therefore y = 7."],"options":[],"conceptId":"math_matrices_solving_matrix_equations","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Solving Matrix Equations"}', 3),
  (1052, 311, 'Find the vector AB if A(2,3) and B(7,5).', 'text', 1, 'Final point minus starting point.', '{"why":"The vector from A to B is found by subtracting the coordinates of A from the coordinates of B.","sol":"Step 1: Starting point A = (2,3)\nStep 2: Final point B = (7,5)\nStep 3: Subtract x-coordinates: 7 - 2 = 5\nStep 4: Subtract y-coordinates: 5 - 3 = 2\nStep 5: Therefore AB = (5,2)","steps":["Step 1: Starting point A = (2,3)","Step 2: Final point B = (7,5)","Step 3: Subtract x-coordinates: 7 - 2 = 5","Step 4: Subtract y-coordinates: 5 - 3 = 2","Step 5: Therefore AB = (5,2)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 0),
  (1053, 311, 'Find the vector PQ if P(-3,4) and Q(2,-1).', 'text', 1, 'Subtract P from Q.', '{"why":"Vector PQ describes the movement from P to Q.","sol":"Step 1: Starting point P = (-3,4)\nStep 2: Final point Q = (2,-1)\nStep 3: x-component: 2 - (-3) = 5\nStep 4: y-component: -1 - 4 = -5\nStep 5: Therefore PQ = (5,-5)","steps":["Step 1: Starting point P = (-3,4)","Step 2: Final point Q = (2,-1)","Step 3: x-component: 2 - (-3) = 5","Step 4: y-component: -1 - 4 = -5","Step 5: Therefore PQ = (5,-5)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 1),
  (1054, 311, 'Find the vector CD if C(6,-2) and D(1,4).', 'text', 1, 'Use final point minus starting point.', '{"why":"Subtracting the starting coordinates from the final coordinates gives the vector.","sol":"Step 1: Starting point C = (6,-2)\nStep 2: Final point D = (1,4)\nStep 3: x-component: 1 - 6 = -5\nStep 4: y-component: 4 - (-2) = 6\nStep 5: Therefore CD = (-5,6)","steps":["Step 1: Starting point C = (6,-2)","Step 2: Final point D = (1,4)","Step 3: x-component: 1 - 6 = -5","Step 4: y-component: 4 - (-2) = 6","Step 5: Therefore CD = (-5,6)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 2),
  (1055, 311, 'If A(2,3) and B(7,5), find BA.', 'text', 1, 'BA moves from B back to A.', '{"why":"Reversing the direction of a vector changes the signs of both components.","sol":"Step 1: Starting point B = (7,5)\nStep 2: Final point A = (2,3)\nStep 3: x-component: 2 - 7 = -5\nStep 4: y-component: 3 - 5 = -2\nStep 5: Therefore BA = (-5,-2)","steps":["Step 1: Starting point B = (7,5)","Step 2: Final point A = (2,3)","Step 3: x-component: 2 - 7 = -5","Step 4: y-component: 3 - 5 = -2","Step 5: Therefore BA = (-5,-2)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q4","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 3),
  (1056, 311, 'If AB = (4,-3), what is BA?', 'text', 1, 'The reverse vector is the negative of the original.', '{"why":"BA = -AB, so reversing a vector changes the signs of both components.","sol":"Step 1: AB = (4,-3)\nStep 2: Reverse the direction\nStep 3: Change both signs\nStep 4: BA = (-4,3)","steps":["Step 1: AB = (4,-3)","Step 2: Reverse the direction","Step 3: Change both signs","Step 4: BA = (-4,3)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q5","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 4),
  (1057, 311, 'A point A is (1,2). A vector AB is (5,3). Find the coordinates of B.', 'text', 1, 'Move from A by the vector AB.', '{"why":"The vector tells us how far and in which direction to move from A to reach B.","sol":"Step 1: Start at A = (1,2)\nStep 2: Add the x-component: 1 + 5 = 6\nStep 3: Add the y-component: 2 + 3 = 5\nStep 4: Therefore B = (6,5)","steps":["Step 1: Start at A = (1,2)","Step 2: Add the x-component: 1 + 5 = 6","Step 3: Add the y-component: 2 + 3 = 5","Step 4: Therefore B = (6,5)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q6","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 5),
  (1058, 312, 'In the directed line segment A → B, which point is the starting point?', 'text', 1, 'Follow the direction of the arrow.', '{"why":"The starting point is where the vector begins before following the arrow.","sol":"Step 1: The arrow points from A toward B.\nStep 2: Therefore the vector begins at A.\nStep 3: A is the starting point.","steps":["Step 1: The arrow points from A toward B.","Step 2: Therefore the vector begins at A.","Step 3: A is the starting point."],"options":[],"conceptId":"math_vectors_a_vector_as_a_directed_line_segment","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"A Vector as a Directed Line Segment"}', 0),
  (1059, 312, 'In P ← Q, which point is the starting point?', 'text', 1, 'The arrow points toward P.', '{"why":"The arrowhead shows the direction of movement, so the vector starts at Q.","sol":"Step 1: The arrowhead points toward P.\nStep 2: Therefore the vector is moving from Q toward P.\nStep 3: The vector starts at Q.","steps":["Step 1: The arrowhead points toward P.","Step 2: Therefore the vector is moving from Q toward P.","Step 3: The vector starts at Q."],"options":[],"conceptId":"math_vectors_a_vector_as_a_directed_line_segment","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"A Vector as a Directed Line Segment"}', 1),
  (1060, 312, 'Two directed line segments have equal lengths but point in opposite directions. Are they the same vector?', 'text', 1, 'A vector needs both magnitude and direction.', '{"why":"Equal magnitude alone is not enough; vectors must also have the same direction.","sol":"Step 1: Equal lengths mean equal magnitudes.\nStep 2: However, the directions are opposite.\nStep 3: Therefore the vectors are not the same.","steps":["Step 1: Equal lengths mean equal magnitudes.","Step 2: However, the directions are opposite.","Step 3: Therefore the vectors are not the same."],"options":[],"conceptId":"math_vectors_a_vector_as_a_directed_line_segment","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"A Vector as a Directed Line Segment"}', 2),
  (1061, 313, 'A vector moves from A to B. Write its vector notation.', 'text', 1, 'Write the starting point first.', '{"why":"The notation ⃗AB represents movement from A to B.","sol":"Step 1: The vector starts at A.\nStep 2: It ends at B.\nStep 3: Write the starting point first and ending point second.","steps":["Step 1: The vector starts at A.","Step 2: It ends at B.","Step 3: Write the starting point first and ending point second."],"options":[],"conceptId":"math_vectors_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Vector Notation"}', 0),
  (1062, 313, 'A vector moves from X to Y. Which notation represents it: ⃗XY or ⃗YX?', 'text', 1, 'The first letter must be the starting point.', '{"why":"The order of the letters records the direction.","sol":"Step 1: The vector starts at X.\nStep 2: The vector ends at Y.\nStep 3: Therefore X must come first.","steps":["Step 1: The vector starts at X.","Step 2: The vector ends at Y.","Step 3: Therefore X must come first."],"options":[],"conceptId":"math_vectors_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Vector Notation"}', 1),
  (1063, 313, 'What does ⃗PQ mean?', 'text', 1, 'Read the letters from left to right.', '{"why":"Two-point vector notation records the starting point followed by the ending point.","sol":"Step 1: The first letter is P.\nStep 2: The second letter is Q.\nStep 3: Therefore the vector starts at P and ends at Q.","steps":["Step 1: The first letter is P.","Step 2: The second letter is Q.","Step 3: Therefore the vector starts at P and ends at Q."],"options":[],"conceptId":"math_vectors_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Vector Notation"}', 2),
  (1064, 314, 'A vector starts at P and ends at Q. Name it.', 'text', 1, 'Put the starting point first.', '{"why":"A vector is named by writing its initial point followed by its terminal point.","sol":"Step 1: Starting point = P.\nStep 2: Ending point = Q.\nStep 3: Therefore the vector is ⃗PQ.","steps":["Step 1: Starting point = P.","Step 2: Ending point = Q.","Step 3: Therefore the vector is ⃗PQ."],"options":[],"conceptId":"math_vectors_naming_a_vector_from_its_initial_and_terminal_points","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Naming a Vector from Its Initial and Terminal Points"}', 0),
  (1065, 314, 'A vector starts at X and ends at Y. A student writes ⃗YX. Is this correct?', 'text', 1, 'Compare the order with the actual direction.', '{"why":"⃗YX represents movement from Y to X, which is the opposite direction.","sol":"Step 1: The vector starts at X.\nStep 2: The vector ends at Y.\nStep 3: The correct order is X then Y.\nStep 4: Therefore ⃗XY is correct, not ⃗YX.","steps":["Step 1: The vector starts at X.","Step 2: The vector ends at Y.","Step 3: The correct order is X then Y.","Step 4: Therefore ⃗XY is correct, not ⃗YX."],"options":[],"conceptId":"math_vectors_naming_a_vector_from_its_initial_and_terminal_points","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Naming a Vector from Its Initial and Terminal Points"}', 1),
  (1066, 314, 'In the directed segment B ← A, what is the vector name?', 'text', 1, 'The arrow points toward B.', '{"why":"The arrow determines the direction, not the position of the letters on the page.","sol":"Step 1: The arrowhead is at B.\nStep 2: Therefore the vector moves from A to B.\nStep 3: Write A first and B second.","steps":["Step 1: The arrowhead is at B.","Step 2: Therefore the vector moves from A to B.","Step 3: Write A first and B second."],"options":[],"conceptId":"math_vectors_naming_a_vector_from_its_initial_and_terminal_points","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Naming a Vector from Its Initial and Terminal Points"}', 2),
  (1067, 315, 'Vector A has magnitude 10 N east. Vector B has magnitude 10 N east. Are they equivalent?', 'text', 1, 'Check both magnitude and direction.', '{"why":"Equivalent vectors have the same magnitude and the same direction.","sol":"Step 1: Vector A has magnitude 10 N.\nStep 2: Vector B has magnitude 10 N.\nStep 3: Both point east.\nStep 4: Therefore they have the same magnitude and direction.","steps":["Step 1: Vector A has magnitude 10 N.","Step 2: Vector B has magnitude 10 N.","Step 3: Both point east.","Step 4: Therefore they have the same magnitude and direction."],"options":[],"conceptId":"math_vectors_equivalent_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Equivalent Vectors"}', 0),
  (1068, 315, 'Vector A has magnitude 6 m north. Vector B has magnitude 6 m south. Are they equivalent?', 'text', 1, 'Their magnitudes are equal. What about their directions?', '{"why":"Equal magnitude is not enough; equivalent vectors must also have the same direction.","sol":"Step 1: Both vectors have magnitude 6 m.\nStep 2: A points north.\nStep 3: B points south.\nStep 4: The directions are opposite.\nStep 5: Therefore they are not equivalent.","steps":["Step 1: Both vectors have magnitude 6 m.","Step 2: A points north.","Step 3: B points south.","Step 4: The directions are opposite.","Step 5: Therefore they are not equivalent."],"options":[],"conceptId":"math_vectors_equivalent_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Equivalent Vectors"}', 1),
  (1069, 315, 'Two vectors have the same magnitude and direction but are drawn at different positions on a page. Can they still be equivalent?', 'text', 1, 'Does the starting position form part of the definition of an equivalent vector?', '{"why":"Equivalent vectors can be drawn in different positions as long as magnitude and direction are unchanged.","sol":"Step 1: Compare their magnitudes.\nStep 2: They are the same.\nStep 3: Compare their directions.\nStep 4: They are also the same.\nStep 5: Their positions are different, but position does not prevent equivalence.","steps":["Step 1: Compare their magnitudes.","Step 2: They are the same.","Step 3: Compare their directions.","Step 4: They are also the same.","Step 5: Their positions are different, but position does not prevent equivalence."],"options":[],"conceptId":"math_vectors_equivalent_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Equivalent Vectors"}', 2),
  (1070, 316, 'A vector is 12 m east. What is its opposite vector?', 'text', 1, 'Keep the magnitude and reverse the direction.', '{"why":"Opposite vectors have the same magnitude but opposite directions.","sol":"Step 1: The original magnitude is 12 m.\nStep 2: Keep the magnitude at 12 m.\nStep 3: The opposite of east is west.\nStep 4: Therefore the opposite vector is 12 m west.","steps":["Step 1: The original magnitude is 12 m.","Step 2: Keep the magnitude at 12 m.","Step 3: The opposite of east is west.","Step 4: Therefore the opposite vector is 12 m west."],"options":[],"conceptId":"math_vectors_opposite_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Opposite Vectors"}', 0),
  (1071, 316, 'If ⃗a = 8 N upward, what is -⃗a?', 'text', 1, 'The negative sign reverses the direction.', '{"why":"A negative vector has the same magnitude but points in the opposite direction.","sol":"Step 1: The magnitude of ⃗a is 8 N.\nStep 2: Keep the magnitude as 8 N.\nStep 3: Reverse upward to downward.\nStep 4: Therefore -⃗a = 8 N downward.","steps":["Step 1: The magnitude of ⃗a is 8 N.","Step 2: Keep the magnitude as 8 N.","Step 3: Reverse upward to downward.","Step 4: Therefore -⃗a = 8 N downward."],"options":[],"conceptId":"math_vectors_opposite_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Opposite Vectors"}', 1),
  (1072, 316, 'If ⃗AB represents movement from A to B, which vector represents the opposite direction?', 'text', 1, 'Reverse the starting and ending points.', '{"why":"Reversing the direction changes the vector from ⃗AB to ⃗BA.","sol":"Step 1: ⃗AB means movement from A to B.\nStep 2: The opposite movement must be from B to A.\nStep 3: Therefore the opposite vector is ⃗BA.","steps":["Step 1: ⃗AB means movement from A to B.","Step 2: The opposite movement must be from B to A.","Step 3: Therefore the opposite vector is ⃗BA."],"options":[],"conceptId":"math_vectors_opposite_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Opposite Vectors"}', 2),
  (1073, 317, 'Which of the following is a scalar quantity: mass, force, displacement, or velocity?', 'text', 1, 'Ask whether the quantity requires a direction.', '{"why":"A scalar quantity is completely described by its magnitude without direction.","sol":"Step 1: Mass tells us how much matter an object contains.\nStep 2: Mass does not require a direction.\nStep 3: Therefore, mass is the scalar quantity.","steps":["Step 1: Mass tells us how much matter an object contains.","Step 2: Mass does not require a direction.","Step 3: Therefore, mass is the scalar quantity."],"options":[],"conceptId":"math_vectors_scalar_quantities","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Scalar Quantities"}', 0),
  (1074, 317, 'A student spends 30 minutes studying. Is the 30 minutes a scalar quantity?', 'text', 1, 'Does time require a direction?', '{"why":"Time has magnitude but does not require direction.","sol":"Step 1: The quantity being described is time.\nStep 2: The student studied for 30 minutes.\nStep 3: No direction is required to describe the time.\nStep 4: Therefore, time is scalar.","steps":["Step 1: The quantity being described is time.","Step 2: The student studied for 30 minutes.","Step 3: No direction is required to describe the time.","Step 4: Therefore, time is scalar."],"options":[],"conceptId":"math_vectors_scalar_quantities","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Scalar Quantities"}', 1),
  (1075, 317, 'A bottle contains 2 litres of water. Is volume a scalar quantity?', 'text', 1, 'Does volume need a direction?', '{"why":"Volume is described by its amount only.","sol":"Step 1: The quantity is volume.\nStep 2: The amount of water is 2 litres.\nStep 3: A direction is not needed to describe the volume.\nStep 4: Therefore, volume is scalar.","steps":["Step 1: The quantity is volume.","Step 2: The amount of water is 2 litres.","Step 3: A direction is not needed to describe the volume.","Step 4: Therefore, volume is scalar."],"options":[],"conceptId":"math_vectors_scalar_quantities","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Scalar Quantities"}', 2),
  (1076, 318, 'A person walks 12 m east. What is the magnitude and what is the direction?', 'text', 1, 'The number gives magnitude; the word describing the way gives direction.', '{"why":"A vector is described using both magnitude and direction.","sol":"Step 1: The distance given is 12 m.\nStep 2: Therefore the magnitude is 12 m.\nStep 3: The direction given is east.","steps":["Step 1: The distance given is 12 m.","Step 2: Therefore the magnitude is 12 m.","Step 3: The direction given is east."],"options":[],"conceptId":"math_vectors_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Vector Quantities"}', 0),
  (1077, 318, 'A force of 20 N acts downward. What is its magnitude?', 'text', 1, 'Ignore the direction for this question.', '{"why":"Magnitude tells us the size or amount of the vector quantity.","sol":"Step 1: The force is given as 20 N downward.\nStep 2: The numerical size of the force is 20 N.\nStep 3: Therefore its magnitude is 20 N.","steps":["Step 1: The force is given as 20 N downward.","Step 2: The numerical size of the force is 20 N.","Step 3: Therefore its magnitude is 20 N."],"options":[],"conceptId":"math_vectors_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Vector Quantities"}', 1),
  (1078, 318, 'A displacement is 8 km west. What information identifies its direction?', 'text', 1, 'Look for the word that tells which way the movement occurred.', '{"why":"Direction tells us which way the vector points.","sol":"Step 1: The displacement is given as 8 km west.\nStep 2: 8 km gives the magnitude.\nStep 3: West gives the direction.","steps":["Step 1: The displacement is given as 8 km west.","Step 2: 8 km gives the magnitude.","Step 3: West gives the direction."],"options":[],"conceptId":"math_vectors_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Vector Quantities"}', 2),
  (1079, 319, 'Classify mass as scalar or vector.', 'text', 1, 'Does mass need a direction?', '{"why":"Mass has magnitude only and does not require direction.","sol":"Step 1: Mass tells us the amount of matter in an object.\nStep 2: A direction is not needed.\nStep 3: Therefore mass is scalar.","steps":["Step 1: Mass tells us the amount of matter in an object.","Step 2: A direction is not needed.","Step 3: Therefore mass is scalar."],"options":[],"conceptId":"math_vectors_scalar_vs_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Scalar vs Vector Quantities"}', 0),
  (1080, 319, 'Classify displacement as scalar or vector.', 'text', 1, 'Does displacement need direction?', '{"why":"Displacement requires both magnitude and direction.","sol":"Step 1: Displacement describes a change in position.\nStep 2: The change in position must have a size and a direction.\nStep 3: Therefore displacement is vector.","steps":["Step 1: Displacement describes a change in position.","Step 2: The change in position must have a size and a direction.","Step 3: Therefore displacement is vector."],"options":[],"conceptId":"math_vectors_scalar_vs_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Scalar vs Vector Quantities"}', 1),
  (1081, 319, 'A runner''s speed is 12 m/s. Is speed scalar or vector?', 'text', 1, 'Does speed itself tell you which direction the runner is moving?', '{"why":"Speed gives magnitude of motion without direction.","sol":"Step 1: Speed tells how fast the runner is moving.\nStep 2: The value 12 m/s does not specify a direction.\nStep 3: Therefore speed is scalar.","steps":["Step 1: Speed tells how fast the runner is moving.","Step 2: The value 12 m/s does not specify a direction.","Step 3: Therefore speed is scalar."],"options":[],"conceptId":"math_vectors_scalar_vs_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Scalar vs Vector Quantities"}', 2),
  (1082, 320, 'A force of 25 N acts upward. What is its magnitude?', 'text', 1, 'The direction is not needed to find magnitude.', '{"why":"Magnitude is the size of the vector quantity.","sol":"Step 1: The force is given as 25 N upward.\nStep 2: 25 N gives the size of the force.\nStep 3: Upward gives the direction.\nStep 4: Therefore the magnitude is 25 N.","steps":["Step 1: The force is given as 25 N upward.","Step 2: 25 N gives the size of the force.","Step 3: Upward gives the direction.","Step 4: Therefore the magnitude is 25 N."],"options":[],"conceptId":"math_vectors_magnitude_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Magnitude of a Vector"}', 0),
  (1083, 320, 'A displacement is 14 km west. What is its magnitude?', 'text', 1, 'Separate the amount from the direction.', '{"why":"The numerical size of the displacement is its magnitude.","sol":"Step 1: 14 km gives the amount of displacement.\nStep 2: West gives the direction.\nStep 3: Therefore the magnitude is 14 km.","steps":["Step 1: 14 km gives the amount of displacement.","Step 2: West gives the direction.","Step 3: Therefore the magnitude is 14 km."],"options":[],"conceptId":"math_vectors_magnitude_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Magnitude of a Vector"}', 1),
  (1084, 320, 'A velocity is 30 m/s south. What is its magnitude?', 'text', 1, 'South describes direction.', '{"why":"Magnitude is the size of a vector, while south is its direction.","sol":"Step 1: The velocity is 30 m/s south.\nStep 2: 30 m/s gives the numerical size.\nStep 3: South gives direction.\nStep 4: Therefore the magnitude is 30 m/s.","steps":["Step 1: The velocity is 30 m/s south.","Step 2: 30 m/s gives the numerical size.","Step 3: South gives direction.","Step 4: Therefore the magnitude is 30 m/s."],"options":[],"conceptId":"math_vectors_magnitude_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Magnitude of a Vector"}', 2),
  (1085, 321, 'A displacement is 18 m east. What is its direction?', 'text', 1, 'Look for the word that tells which way the displacement points.', '{"why":"The direction is the part of the vector description that tells which way it points.","sol":"Step 1: The displacement is written as 18 m east.\nStep 2: 18 m is the magnitude.\nStep 3: East tells us the direction.","steps":["Step 1: The displacement is written as 18 m east.","Step 2: 18 m is the magnitude.","Step 3: East tells us the direction."],"options":[],"conceptId":"math_vectors_direction_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Direction of a Vector"}', 0),
  (1086, 321, 'A force of 50 N acts downward. What is the direction of the force?', 'text', 1, '50 N tells you the size. Which word tells you the way?', '{"why":"Direction describes the way in which the vector acts.","sol":"Step 1: 50 N gives the magnitude.\nStep 2: Downward tells us which way the force acts.\nStep 3: Therefore the direction is downward.","steps":["Step 1: 50 N gives the magnitude.","Step 2: Downward tells us which way the force acts.","Step 3: Therefore the direction is downward."],"options":[],"conceptId":"math_vectors_direction_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Direction of a Vector"}', 1),
  (1087, 321, 'Two vectors have magnitudes of 12 m. One points east and the other points west. Do they have the same direction?', 'text', 1, 'Compare east and west.', '{"why":"Vectors with the same magnitude can still have different directions.","sol":"Step 1: The first vector points east.\nStep 2: The second vector points west.\nStep 3: East and west are opposite directions.\nStep 4: Therefore their directions are not the same.","steps":["Step 1: The first vector points east.","Step 2: The second vector points west.","Step 3: East and west are opposite directions.","Step 4: Therefore their directions are not the same."],"options":[],"conceptId":"math_vectors_direction_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Direction of a Vector"}', 2),
  (1088, 322, 'What does the column vector (3, 5) represent?', 'text', 1, 'Read the top number first, then the bottom number.', '{"why":"The top component gives horizontal movement and the bottom component gives vertical movement.","sol":"Step 1: The top number is 3, so move 3 units right.\nStep 2: The bottom number is 5, so move 5 units up.\nStep 3: Therefore the vector represents 3 units right and 5 units up.","steps":["Step 1: The top number is 3, so move 3 units right.","Step 2: The bottom number is 5, so move 5 units up.","Step 3: Therefore the vector represents 3 units right and 5 units up."],"options":[],"conceptId":"math_vectors_column_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Column Vector Notation"}', 0),
  (1089, 322, 'What movement is represented by the column vector (-2, 4)?', 'text', 1, 'A negative horizontal component means left.', '{"why":"The negative sign reverses the horizontal direction.","sol":"Step 1: The top number is -2.\nStep 2: Therefore move 2 units left.\nStep 3: The bottom number is 4.\nStep 4: Therefore move 4 units up.","steps":["Step 1: The top number is -2.","Step 2: Therefore move 2 units left.","Step 3: The bottom number is 4.","Step 4: Therefore move 4 units up."],"options":[],"conceptId":"math_vectors_column_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Column Vector Notation"}', 1),
  (1090, 322, 'What movement is represented by the column vector (7, -3)?', 'text', 1, 'The negative bottom component means downward movement.', '{"why":"The top component controls horizontal movement and the bottom component controls vertical movement.","sol":"Step 1: The top number is 7, so move 7 units right.\nStep 2: The bottom number is -3, so move 3 units down.","steps":["Step 1: The top number is 7, so move 7 units right.","Step 2: The bottom number is -3, so move 3 units down."],"options":[],"conceptId":"math_vectors_column_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Column Vector Notation"}', 2),
  (1091, 323, 'Interpret the column vector (-6, -4).', 'text', 1, 'Look at the sign of each component.', '{"why":"Negative horizontal means left and negative vertical means down.","sol":"Step 1: The horizontal component is -6, so move 6 units left.\nStep 2: The vertical component is -4, so move 4 units down.","steps":["Step 1: The horizontal component is -6, so move 6 units left.","Step 2: The vertical component is -4, so move 4 units down."],"options":[],"conceptId":"math_vectors_reading_a_column_vector_as_movement","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Reading a Column Vector as Movement"}', 0),
  (1092, 323, 'Write the column vector for 8 units right and 3 units down.', 'text', 1, 'Right is positive and down is negative.', '{"why":"Horizontal movement is written first, followed by vertical movement.","sol":"Step 1: Horizontal movement = 8 units right, so the first component is +8.\nStep 2: Vertical movement = 3 units down, so the second component is -3.\nStep 3: Therefore the column vector is (8, -3).","steps":["Step 1: Horizontal movement = 8 units right, so the first component is +8.","Step 2: Vertical movement = 3 units down, so the second component is -3.","Step 3: Therefore the column vector is (8, -3)."],"options":[],"conceptId":"math_vectors_reading_a_column_vector_as_movement","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Reading a Column Vector as Movement"}', 1),
  (1093, 323, 'Write the column vector for 5 units left and 2 units up.', 'text', 1, 'Left is negative; up is positive.', '{"why":"The signs record the directions of the two components.","sol":"Step 1: Horizontal movement = 5 units left, so the first component is -5.\nStep 2: Vertical movement = 2 units up, so the second component is +2.\nStep 3: Therefore the vector is (-5, 2).","steps":["Step 1: Horizontal movement = 5 units left, so the first component is -5.","Step 2: Vertical movement = 2 units up, so the second component is +2.","Step 3: Therefore the vector is (-5, 2)."],"options":[],"conceptId":"math_vectors_reading_a_column_vector_as_movement","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Reading a Column Vector as Movement"}', 2),
  (1094, 324, 'What is the horizontal component of (6, -2)?', 'text', 1, 'The horizontal component is always the top entry.', '{"why":"The first component of a two-dimensional column vector represents horizontal movement.","sol":"Step 1: A column vector is written with horizontal movement first.\nStep 2: The top entry is 6.\nStep 3: Therefore the horizontal component is 6.","steps":["Step 1: A column vector is written with horizontal movement first.","Step 2: The top entry is 6.","Step 3: Therefore the horizontal component is 6."],"options":[],"conceptId":"math_vectors_horizontal_and_vertical_components","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Horizontal and Vertical Components"}', 0),
  (1095, 324, 'What is the vertical component of (-3, 8)?', 'text', 1, 'The vertical component is the bottom entry.', '{"why":"The second component represents vertical movement.","sol":"Step 1: The bottom entry represents vertical movement.\nStep 2: The bottom entry is 8.\nStep 3: Therefore the vertical component is 8.","steps":["Step 1: The bottom entry represents vertical movement.","Step 2: The bottom entry is 8.","Step 3: Therefore the vertical component is 8."],"options":[],"conceptId":"math_vectors_horizontal_and_vertical_components","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Horizontal and Vertical Components"}', 1),
  (1096, 324, 'A vector has horizontal component -7 and vertical component -5. Write it as a column vector.', 'text', 1, 'Put horizontal first and vertical second.', '{"why":"Column-vector notation places the horizontal component above the vertical component.","sol":"Step 1: Horizontal component = -7.\nStep 2: Vertical component = -5.\nStep 3: Place -7 on top and -5 underneath.","steps":["Step 1: Horizontal component = -7.","Step 2: Vertical component = -5.","Step 3: Place -7 on top and -5 underneath."],"options":[],"conceptId":"math_vectors_horizontal_and_vertical_components","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Horizontal and Vertical Components"}', 2),
  (1097, 325, 'A vector moves 8 units right and 5 units up. Write its column vector.', 'text', 1, 'Both directions are positive.', '{"why":"The geometric movement is converted directly into horizontal and vertical components.","sol":"Step 1: Right gives horizontal component +8.\nStep 2: Up gives vertical component +5.\nStep 3: Put horizontal first and vertical second.","steps":["Step 1: Right gives horizontal component +8.","Step 2: Up gives vertical component +5.","Step 3: Put horizontal first and vertical second."],"options":[],"conceptId":"math_vectors_representing_a_geometric_vector_as_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Representing a Geometric Vector as a Column Vector"}', 0),
  (1098, 325, 'A vector moves 4 units left and 6 units down. Write its column vector.', 'text', 1, 'Both left and down have negative signs.', '{"why":"Left and down represent negative movement on the coordinate plane.","sol":"Step 1: Left gives horizontal component -4.\nStep 2: Down gives vertical component -6.\nStep 3: Therefore the column vector is (-4, -6).","steps":["Step 1: Left gives horizontal component -4.","Step 2: Down gives vertical component -6.","Step 3: Therefore the column vector is (-4, -6)."],"options":[],"conceptId":"math_vectors_representing_a_geometric_vector_as_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Representing a Geometric Vector as a Column Vector"}', 1),
  (1099, 325, 'A vector moves 9 units right and 3 units down. Write its column vector.', 'text', 1, 'Right is positive; down is negative.', '{"why":"The signs record the direction of each component.","sol":"Step 1: Horizontal component = +9.\nStep 2: Vertical component = -3.\nStep 3: Therefore the vector is (9, -3).","steps":["Step 1: Horizontal component = +9.","Step 2: Vertical component = -3.","Step 3: Therefore the vector is (9, -3)."],"options":[],"conceptId":"math_vectors_representing_a_geometric_vector_as_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Representing a Geometric Vector as a Column Vector"}', 2),
  (1100, 326, 'Find the column vector from A(2, 1) to B(7, 4).', 'text', 1, 'Calculate B − A, coordinate by coordinate.', '{"why":"The vector records the change from the starting point to the destination.","sol":"Step 1: Horizontal change = 7 - 2 = 5.\nStep 2: Vertical change = 4 - 1 = 3.\nStep 3: Therefore the vector is (5, 3).","steps":["Step 1: Horizontal change = 7 - 2 = 5.","Step 2: Vertical change = 4 - 1 = 3.","Step 3: Therefore the vector is (5, 3)."],"options":[],"conceptId":"math_vectors_finding_the_column_vector_between_two_points","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding the Column Vector Between Two Points"}', 0),
  (1101, 326, 'Find the column vector from P(6, 5) to Q(2, 1).', 'text', 1, 'Use final coordinate minus starting coordinate.', '{"why":"Negative components show that the movement is left and down.","sol":"Step 1: Horizontal change = 2 - 6 = -4.\nStep 2: Vertical change = 1 - 5 = -4.\nStep 3: Therefore the vector is (-4, -4).","steps":["Step 1: Horizontal change = 2 - 6 = -4.","Step 2: Vertical change = 1 - 5 = -4.","Step 3: Therefore the vector is (-4, -4)."],"options":[],"conceptId":"math_vectors_finding_the_column_vector_between_two_points","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding the Column Vector Between Two Points"}', 1),
  (1102, 326, 'Find the column vector from C(-3, 2) to D(4, -1).', 'text', 1, 'Subtract C''s coordinates from D''s coordinates.', '{"why":"The vector describes the exact horizontal and vertical changes needed to move from C to D.","sol":"Step 1: Horizontal change = 4 - (-3) = 7.\nStep 2: Vertical change = -1 - 2 = -3.\nStep 3: Therefore the vector is (7, -3).","steps":["Step 1: Horizontal change = 4 - (-3) = 7.","Step 2: Vertical change = -1 - 2 = -3.","Step 3: Therefore the vector is (7, -3)."],"options":[],"conceptId":"math_vectors_finding_the_column_vector_between_two_points","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding the Column Vector Between Two Points"}', 2),
  (1103, 327, 'What is the position vector of point A called if A is any point on a Cartesian plane?', 'text', 1, 'A position vector starts at the origin.', '{"why":"A position vector of A is the vector drawn from the origin O to A.","sol":"Step 1: The origin is O.\nStep 2: The position vector must start at O.\nStep 3: It ends at A.\nStep 4: Therefore the position vector is OA.","steps":["Step 1: The origin is O.","Step 2: The position vector must start at O.","Step 3: It ends at A.","Step 4: Therefore the position vector is OA."],"options":[],"conceptId":"math_vectors_meaning_of_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Meaning of a Position Vector"}', 0),
  (1104, 327, 'Point B is at (-2, 4). Which vector represents its position vector?', 'text', 1, 'Start at O and finish at B.', '{"why":"The position vector of a point always runs from the origin to that point.","sol":"Step 1: The starting point is the origin O.\nStep 2: The ending point is B.\nStep 3: Therefore the position vector is OB.","steps":["Step 1: The starting point is the origin O.","Step 2: The ending point is B.","Step 3: Therefore the position vector is OB."],"options":[],"conceptId":"math_vectors_meaning_of_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Meaning of a Position Vector"}', 1),
  (1105, 327, 'Point C is at (5, -3). Explain what OC represents.', 'text', 1, 'Think about where the vector starts and finishes.', '{"why":"A position vector describes the location of its endpoint relative to the origin.","sol":"Step 1: OC starts at the origin O.\nStep 2: It finishes at point C.\nStep 3: Therefore it describes the position of C relative to the origin.","steps":["Step 1: OC starts at the origin O.","Step 2: It finishes at point C.","Step 3: Therefore it describes the position of C relative to the origin."],"options":[],"conceptId":"math_vectors_meaning_of_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Meaning of a Position Vector"}', 2),
  (1106, 328, 'A = (6, 4). Find OA.', 'text', 1, 'Use the coordinates directly.', '{"why":"The coordinates of A are the components of its position vector.","sol":"Step 1: A = (6, 4).\nStep 2: The x-coordinate is 6.\nStep 3: The y-coordinate is 4.\nStep 4: Therefore OA = (6, 4).","steps":["Step 1: A = (6, 4).","Step 2: The x-coordinate is 6.","Step 3: The y-coordinate is 4.","Step 4: Therefore OA = (6, 4)."],"options":[],"conceptId":"math_vectors_finding_a_position_vector_from_coordinates","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding a Position Vector from Coordinates"}', 0),
  (1107, 328, 'B = (-5, 3). Find OB.', 'text', 1, 'Keep the negative sign.', '{"why":"The x-coordinate -5 means the vector moves 5 units to the left.","sol":"Step 1: B = (-5, 3).\nStep 2: The horizontal component is -5.\nStep 3: The vertical component is 3.\nStep 4: Therefore OB = (-5, 3).","steps":["Step 1: B = (-5, 3).","Step 2: The horizontal component is -5.","Step 3: The vertical component is 3.","Step 4: Therefore OB = (-5, 3)."],"options":[],"conceptId":"math_vectors_finding_a_position_vector_from_coordinates","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding a Position Vector from Coordinates"}', 1),
  (1108, 328, 'C = (2, -7). Find OC.', 'text', 1, 'The negative number is the vertical component.', '{"why":"The coordinates directly give the horizontal and vertical components of the position vector.","sol":"Step 1: C = (2, -7).\nStep 2: The horizontal component is 2.\nStep 3: The vertical component is -7.\nStep 4: Therefore OC = (2, -7).","steps":["Step 1: C = (2, -7).","Step 2: The horizontal component is 2.","Step 3: The vertical component is -7.","Step 4: Therefore OC = (2, -7)."],"options":[],"conceptId":"math_vectors_finding_a_position_vector_from_coordinates","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding a Position Vector from Coordinates"}', 2),
  (1109, 329, 'OA = (5, 8). Find the coordinates of A.', 'text', 1, 'The two components become the two coordinates.', '{"why":"The components of a position vector give the coordinates of its endpoint.","sol":"Step 1: The first component is 5, so x = 5.\nStep 2: The second component is 8, so y = 8.\nStep 3: Therefore A = (5, 8).","steps":["Step 1: The first component is 5, so x = 5.","Step 2: The second component is 8, so y = 8.","Step 3: Therefore A = (5, 8)."],"options":[],"conceptId":"math_vectors_finding_coordinates_from_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding Coordinates from a Position Vector"}', 0),
  (1110, 329, 'OB = (-3, 7). Find the coordinates of B.', 'text', 1, 'Keep the negative x-coordinate.', '{"why":"The negative first component means B lies to the left of the origin.","sol":"Step 1: The first component is -3.\nStep 2: The second component is 7.\nStep 3: Therefore B = (-3, 7).","steps":["Step 1: The first component is -3.","Step 2: The second component is 7.","Step 3: Therefore B = (-3, 7)."],"options":[],"conceptId":"math_vectors_finding_coordinates_from_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding Coordinates from a Position Vector"}', 1),
  (1111, 329, 'OC = (-4, -2). Find the coordinates of C.', 'text', 1, 'Both components are negative.', '{"why":"Both negative components are retained because they describe C''s position relative to the origin.","sol":"Step 1: The first component is -4.\nStep 2: The second component is -2.\nStep 3: Therefore C = (-4, -2).","steps":["Step 1: The first component is -4.","Step 2: The second component is -2.","Step 3: Therefore C = (-4, -2)."],"options":[],"conceptId":"math_vectors_finding_coordinates_from_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding Coordinates from a Position Vector"}', 2),
  (1112, 330, 'A = (1, 4) and B = (6, 9). Find AB.', 'text', 1, 'Use AB = OB - OA.', '{"why":"The vector from A to B is found by subtracting A''s position vector from B''s.","sol":"Step 1: OA = (1, 4).\nStep 2: OB = (6, 9).\nStep 3: AB = OB - OA.\nStep 4: AB = (6, 9) - (1, 4).\nStep 5: Horizontal: 6 - 1 = 5.\nStep 6: Vertical: 9 - 4 = 5.\nStep 7: Therefore AB = (5, 5).","steps":["Step 1: OA = (1, 4).","Step 2: OB = (6, 9).","Step 3: AB = OB - OA.","Step 4: AB = (6, 9) - (1, 4).","Step 5: Horizontal: 6 - 1 = 5.","Step 6: Vertical: 9 - 4 = 5.","Step 7: Therefore AB = (5, 5)."],"options":[],"conceptId":"math_vectors_finding_a_vector_between_two_points_using_position_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding a Vector Between Two Points Using Position Vectors"}', 0),
  (1113, 330, 'A = (-2, 5) and B = (4, 1). Find AB.', 'text', 1, 'Subtract (-2, 5) from (4, 1).', '{"why":"The positive horizontal component means right, while the negative vertical component means down.","sol":"Step 1: OA = (-2, 5).\nStep 2: OB = (4, 1).\nStep 3: AB = OB - OA.\nStep 4: AB = (4, 1) - (-2, 5).\nStep 5: Horizontal: 4 - (-2) = 6.\nStep 6: Vertical: 1 - 5 = -4.\nStep 7: Therefore AB = (6, -4).","steps":["Step 1: OA = (-2, 5).","Step 2: OB = (4, 1).","Step 3: AB = OB - OA.","Step 4: AB = (4, 1) - (-2, 5).","Step 5: Horizontal: 4 - (-2) = 6.","Step 6: Vertical: 1 - 5 = -4.","Step 7: Therefore AB = (6, -4)."],"options":[],"conceptId":"math_vectors_finding_a_vector_between_two_points_using_position_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding a Vector Between Two Points Using Position Vectors"}', 1),
  (1114, 330, 'A = (5, -1) and B = (-2, 3). Find AB.', 'text', 1, 'Destination minus starting point.', '{"why":"The vector moves 7 units left and 4 units up from A to B.","sol":"Step 1: OA = (5, -1).\nStep 2: OB = (-2, 3).\nStep 3: AB = OB - OA.\nStep 4: AB = (-2, 3) - (5, -1).\nStep 5: Horizontal: -2 - 5 = -7.\nStep 6: Vertical: 3 - (-1) = 4.\nStep 7: Therefore AB = (-7, 4).","steps":["Step 1: OA = (5, -1).","Step 2: OB = (-2, 3).","Step 3: AB = OB - OA.","Step 4: AB = (-2, 3) - (5, -1).","Step 5: Horizontal: -2 - 5 = -7.","Step 6: Vertical: 3 - (-1) = 4.","Step 7: Therefore AB = (-7, 4)."],"options":[],"conceptId":"math_vectors_finding_a_vector_between_two_points_using_position_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding a Vector Between Two Points Using Position Vectors"}', 2),
  (1115, 331, 'A = (1, 2) and AB = (3, 4). Find B.', 'text', 1, 'Use OB = OA + AB.', '{"why":"Starting at A and moving by AB gives the position of B.","sol":"Step 1: OA = (1, 2).\nStep 2: AB = (3, 4).\nStep 3: OB = OA + AB.\nStep 4: OB = (1, 2) + (3, 4).\nStep 5: Horizontal: 1 + 3 = 4.\nStep 6: Vertical: 2 + 4 = 6.\nStep 7: Therefore B = (4, 6).","steps":["Step 1: OA = (1, 2).","Step 2: AB = (3, 4).","Step 3: OB = OA + AB.","Step 4: OB = (1, 2) + (3, 4).","Step 5: Horizontal: 1 + 3 = 4.","Step 6: Vertical: 2 + 4 = 6.","Step 7: Therefore B = (4, 6)."],"options":[],"conceptId":"math_vectors_finding_an_unknown_point_using_a_vector_and_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding an Unknown Point Using a Vector and a Position Vector"}', 0),
  (1116, 331, 'A = (-2, 5) and AB = (6, -3). Find B.', 'text', 1, 'Add the components of OA and AB.', '{"why":"The movement AB is applied to the starting position A.","sol":"Step 1: OA = (-2, 5).\nStep 2: AB = (6, -3).\nStep 3: OB = OA + AB.\nStep 4: OB = (-2, 5) + (6, -3).\nStep 5: Horizontal: -2 + 6 = 4.\nStep 6: Vertical: 5 + (-3) = 2.\nStep 7: Therefore B = (4, 2).","steps":["Step 1: OA = (-2, 5).","Step 2: AB = (6, -3).","Step 3: OB = OA + AB.","Step 4: OB = (-2, 5) + (6, -3).","Step 5: Horizontal: -2 + 6 = 4.","Step 6: Vertical: 5 + (-3) = 2.","Step 7: Therefore B = (4, 2)."],"options":[],"conceptId":"math_vectors_finding_an_unknown_point_using_a_vector_and_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding an Unknown Point Using a Vector and a Position Vector"}', 1),
  (1117, 331, 'A = (8, -4) and AB = (-5, 7). Find B.', 'text', 1, 'Remember that adding a negative number means moving in the opposite direction.', '{"why":"Starting at (8, -4), moving 5 units left and 7 units up reaches (3, 3).","sol":"Step 1: OA = (8, -4).\nStep 2: AB = (-5, 7).\nStep 3: OB = OA + AB.\nStep 4: OB = (8, -4) + (-5, 7).\nStep 5: Horizontal: 8 + (-5) = 3.\nStep 6: Vertical: -4 + 7 = 3.\nStep 7: Therefore B = (3, 3).","steps":["Step 1: OA = (8, -4).","Step 2: AB = (-5, 7).","Step 3: OB = OA + AB.","Step 4: OB = (8, -4) + (-5, 7).","Step 5: Horizontal: 8 + (-5) = 3.","Step 6: Vertical: -4 + 7 = 3.","Step 7: Therefore B = (3, 3)."],"options":[],"conceptId":"math_vectors_finding_an_unknown_point_using_a_vector_and_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding an Unknown Point Using a Vector and a Position Vector"}', 2),
  (1118, 332, 'A vector represents 4 units to the right and another represents 3 units to the right. What is their resultant movement?', 'text', 1, 'Both movements are in the same direction.', '{"why":"Two movements in the same direction combine by adding their magnitudes.","sol":"Step 1: The first movement is 4 units right.\nStep 2: The second movement is 3 units right.\nStep 3: Add the two movements: 4 + 3 = 7.\nStep 4: Therefore the resultant movement is 7 units right.","steps":["Step 1: The first movement is 4 units right.","Step 2: The second movement is 3 units right.","Step 3: Add the two movements: 4 + 3 = 7.","Step 4: Therefore the resultant movement is 7 units right."],"options":[],"conceptId":"math_vectors_meaning_of_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Meaning of Vector Addition"}', 0),
  (1119, 332, 'A vector represents 5 units upward and another represents 6 units upward. Find the resultant movement.', 'text', 1, 'Both vectors point upward.', '{"why":"The movements have the same direction, so their magnitudes are added.","sol":"Step 1: First movement = 5 units up.\nStep 2: Second movement = 6 units up.\nStep 3: Add them: 5 + 6 = 11.\nStep 4: Therefore the resultant movement is 11 units upward.","steps":["Step 1: First movement = 5 units up.","Step 2: Second movement = 6 units up.","Step 3: Add them: 5 + 6 = 11.","Step 4: Therefore the resultant movement is 11 units upward."],"options":[],"conceptId":"math_vectors_meaning_of_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Meaning of Vector Addition"}', 1),
  (1120, 332, 'A movement of 3 units right is followed by a movement of 4 units up. Are the two movements added by simply calculating 3 + 4 = 7 units in one direction?', 'text', 1, 'The two movements are in different directions.', '{"why":"Vectors have direction, so movements in different directions cannot be treated like ordinary scalar quantities.","sol":"Step 1: The first movement is horizontal.\nStep 2: The second movement is vertical.\nStep 3: They therefore affect different components of the movement.\nStep 4: The resultant must preserve both the horizontal and vertical parts.","steps":["Step 1: The first movement is horizontal.","Step 2: The second movement is vertical.","Step 3: They therefore affect different components of the movement.","Step 4: The resultant must preserve both the horizontal and vertical parts."],"options":[],"conceptId":"math_vectors_meaning_of_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Meaning of Vector Addition"}', 2),
  (1121, 333, 'Vector a is 5 units right and vector b is 2 units right. Find a + b.', 'text', 1, 'Join the vectors head-to-tail.', '{"why":"The two vectors point in the same direction, so their movements combine directly.","sol":"Step 1: a moves 5 units right.\nStep 2: b moves 2 units right.\nStep 3: The total movement is 5 + 2 = 7 units right.\nStep 4: Therefore a + b = 7 units right.","steps":["Step 1: a moves 5 units right.","Step 2: b moves 2 units right.","Step 3: The total movement is 5 + 2 = 7 units right.","Step 4: Therefore a + b = 7 units right."],"options":[],"conceptId":"math_vectors_geometric_addition_of_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Geometric Addition of Vectors"}', 0),
  (1122, 333, 'Vector a is 3 units up and vector b is 4 units up. Find a + b.', 'text', 1, 'Add the two upward movements.', '{"why":"The two vectors have the same direction.","sol":"Step 1: a moves 3 units up.\nStep 2: b moves 4 units up.\nStep 3: Total upward movement = 3 + 4 = 7.\nStep 4: Therefore a + b = 7 units up.","steps":["Step 1: a moves 3 units up.","Step 2: b moves 4 units up.","Step 3: Total upward movement = 3 + 4 = 7.","Step 4: Therefore a + b = 7 units up."],"options":[],"conceptId":"math_vectors_geometric_addition_of_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Geometric Addition of Vectors"}', 1),
  (1123, 333, 'Vector a is 6 units right and vector b is 2 units up. Describe the resultant a + b.', 'text', 1, 'Keep both movements.', '{"why":"The resultant contains the combined horizontal and vertical movements.","sol":"Step 1: a contributes 6 units horizontally.\nStep 2: b contributes 2 units vertically.\nStep 3: Therefore the resultant has horizontal component 6.\nStep 4: The resultant has vertical component 2.\nStep 5: So a + b = (6, 2).","steps":["Step 1: a contributes 6 units horizontally.","Step 2: b contributes 2 units vertically.","Step 3: Therefore the resultant has horizontal component 6.","Step 4: The resultant has vertical component 2.","Step 5: So a + b = (6, 2)."],"options":[],"conceptId":"math_vectors_geometric_addition_of_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Geometric Addition of Vectors"}', 2),
  (1124, 334, 'Add (2, 4) and (3, 5).', 'text', 1, 'Add horizontal components together and vertical components together.', '{"why":"Corresponding vector components are added separately.","sol":"Step 1: Horizontal: 2 + 3 = 5.\nStep 2: Vertical: 4 + 5 = 9.\nStep 3: Therefore the resultant is (5, 9).","steps":["Step 1: Horizontal: 2 + 3 = 5.","Step 2: Vertical: 4 + 5 = 9.","Step 3: Therefore the resultant is (5, 9)."],"options":[],"conceptId":"math_vectors_column_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Column Vector Addition"}', 0),
  (1125, 334, 'Add (-3, 5) and (7, 2).', 'text', 1, 'Be careful with the negative first component.', '{"why":"The horizontal components combine to give 4 and the vertical components combine to give 7.","sol":"Step 1: Horizontal: -3 + 7 = 4.\nStep 2: Vertical: 5 + 2 = 7.\nStep 3: Therefore the resultant is (4, 7).","steps":["Step 1: Horizontal: -3 + 7 = 4.","Step 2: Vertical: 5 + 2 = 7.","Step 3: Therefore the resultant is (4, 7)."],"options":[],"conceptId":"math_vectors_column_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Column Vector Addition"}', 1),
  (1126, 334, 'Add (8, -4) and (-3, 6).', 'text', 1, 'Treat -4 and -3 as signed numbers.', '{"why":"Vector components are ordinary signed numbers, so normal integer addition applies to each component.","sol":"Step 1: Horizontal: 8 + (-3) = 5.\nStep 2: Vertical: -4 + 6 = 2.\nStep 3: Therefore the resultant is (5, 2).","steps":["Step 1: Horizontal: 8 + (-3) = 5.","Step 2: Vertical: -4 + 6 = 2.","Step 3: Therefore the resultant is (5, 2)."],"options":[],"conceptId":"math_vectors_column_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Column Vector Addition"}', 2),
  (1127, 335, 'Find the resultant of (4, 2) and (3, 5).', 'text', 1, 'Add the two vectors component by component.', '{"why":"The resultant contains the total horizontal and vertical movement.","sol":"Step 1: Horizontal: 4 + 3 = 7.\nStep 2: Vertical: 2 + 5 = 7.\nStep 3: Therefore the resultant is (7, 7).","steps":["Step 1: Horizontal: 4 + 3 = 7.","Step 2: Vertical: 2 + 5 = 7.","Step 3: Therefore the resultant is (7, 7)."],"options":[],"conceptId":"math_vectors_finding_a_resultant_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding a Resultant Vector"}', 0),
  (1128, 335, 'Find the resultant of (-5, 3) and (2, 4).', 'text', 1, 'Keep the negative sign on the first horizontal component.', '{"why":"The total horizontal movement is 3 units left and the total vertical movement is 7 units up.","sol":"Step 1: Horizontal: -5 + 2 = -3.\nStep 2: Vertical: 3 + 4 = 7.\nStep 3: Therefore the resultant is (-3, 7).","steps":["Step 1: Horizontal: -5 + 2 = -3.","Step 2: Vertical: 3 + 4 = 7.","Step 3: Therefore the resultant is (-3, 7)."],"options":[],"conceptId":"math_vectors_finding_a_resultant_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding a Resultant Vector"}', 1),
  (1129, 335, 'Find the resultant of (1, 2), (3, -1), and (-2, 5).', 'text', 1, 'You can combine the vectors one pair at a time.', '{"why":"Adding the three vectors gives a total movement of 2 units horizontally and 6 units vertically.","sol":"Step 1: First add (1, 2) and (3, -1).\nStep 2: (1, 2) + (3, -1) = (4, 1).\nStep 3: Now add (-2, 5).\nStep 4: (4, 1) + (-2, 5) = (2, 6).\nStep 5: Therefore the resultant is (2, 6).","steps":["Step 1: First add (1, 2) and (3, -1).","Step 2: (1, 2) + (3, -1) = (4, 1).","Step 3: Now add (-2, 5).","Step 4: (4, 1) + (-2, 5) = (2, 6).","Step 5: Therefore the resultant is (2, 6)."],"options":[],"conceptId":"math_vectors_finding_a_resultant_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding a Resultant Vector"}', 2),
  (1130, 336, 'AB = (4, 2) and BC = (3, 5). Find AC.', 'text', 1, 'To go from A to C, follow A to B and then B to C.', '{"why":"The route from A to C consists of the movement A to B followed by B to C.","sol":"Step 1: AC = AB + BC.\nStep 2: AC = (4, 2) + (3, 5).\nStep 3: Horizontal: 4 + 3 = 7.\nStep 4: Vertical: 2 + 5 = 7.\nStep 5: Therefore AC = (7, 7).","steps":["Step 1: AC = AB + BC.","Step 2: AC = (4, 2) + (3, 5).","Step 3: Horizontal: 4 + 3 = 7.","Step 4: Vertical: 2 + 5 = 7.","Step 5: Therefore AC = (7, 7)."],"options":[],"conceptId":"math_vectors_vector_addition_in_geometrical_problems","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Vector Addition in Geometrical Problems"}', 0),
  (1131, 336, 'AB = (-2, 4) and BC = (5, -1). Find AC.', 'text', 1, 'Add the two consecutive vectors.', '{"why":"The resultant combines both movements along the route from A to C.","sol":"Step 1: AC = AB + BC.\nStep 2: AC = (-2, 4) + (5, -1).\nStep 3: Horizontal: -2 + 5 = 3.\nStep 4: Vertical: 4 + (-1) = 3.\nStep 5: Therefore AC = (3, 3).","steps":["Step 1: AC = AB + BC.","Step 2: AC = (-2, 4) + (5, -1).","Step 3: Horizontal: -2 + 5 = 3.","Step 4: Vertical: 4 + (-1) = 3.","Step 5: Therefore AC = (3, 3)."],"options":[],"conceptId":"math_vectors_vector_addition_in_geometrical_problems","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Vector Addition in Geometrical Problems"}', 1),
  (1132, 336, 'In triangle ABC, AB = (6, -2) and BC = (-3, 7). Find AC.', 'text', 1, 'Travel from A to B and then from B to C.', '{"why":"Adding consecutive vectors gives the direct resultant from the first point to the final point.","sol":"Step 1: AC = AB + BC.\nStep 2: AC = (6, -2) + (-3, 7).\nStep 3: Horizontal: 6 + (-3) = 3.\nStep 4: Vertical: -2 + 7 = 5.\nStep 5: Therefore AC = (3, 5).","steps":["Step 1: AC = AB + BC.","Step 2: AC = (6, -2) + (-3, 7).","Step 3: Horizontal: 6 + (-3) = 3.","Step 4: Vertical: -2 + 7 = 5.","Step 5: Therefore AC = (3, 5)."],"options":[],"conceptId":"math_vectors_vector_addition_in_geometrical_problems","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Vector Addition in Geometrical Problems"}', 2),
  (1133, 337, 'A vector is 9 units right and another is 4 units right. Find the difference.', 'text', 1, 'Subtract the second movement from the first.', '{"why":"Subtracting the smaller rightward movement from the larger one leaves 5 units right.","sol":"Step 1: First movement = 9 units right.\nStep 2: Second movement = 4 units right.\nStep 3: 9 - 4 = 5.\nStep 4: Therefore the difference is 5 units right.","steps":["Step 1: First movement = 9 units right.","Step 2: Second movement = 4 units right.","Step 3: 9 - 4 = 5.","Step 4: Therefore the difference is 5 units right."],"options":[],"conceptId":"math_vectors_meaning_of_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Meaning of Vector Subtraction"}', 0),
  (1134, 337, 'A vector is 10 units upward and another is 6 units upward. Find the difference.', 'text', 1, 'Both movements are vertical.', '{"why":"The vertical movement is reduced by 6 units.","sol":"Step 1: First movement = 10 units up.\nStep 2: Second movement = 6 units up.\nStep 3: 10 - 6 = 4.\nStep 4: Therefore the difference is 4 units upward.","steps":["Step 1: First movement = 10 units up.","Step 2: Second movement = 6 units up.","Step 3: 10 - 6 = 4.","Step 4: Therefore the difference is 4 units upward."],"options":[],"conceptId":"math_vectors_meaning_of_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Meaning of Vector Subtraction"}', 1),
  (1135, 337, 'Find (8, 6) - (3, 2).', 'text', 1, 'Subtract corresponding components.', '{"why":"Vector subtraction acts separately on the horizontal and vertical components.","sol":"Step 1: Horizontal: 8 - 3 = 5.\nStep 2: Vertical: 6 - 2 = 4.\nStep 3: Therefore the difference is (5, 4).","steps":["Step 1: Horizontal: 8 - 3 = 5.","Step 2: Vertical: 6 - 2 = 4.","Step 3: Therefore the difference is (5, 4)."],"options":[],"conceptId":"math_vectors_meaning_of_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Meaning of Vector Subtraction"}', 2),
  (1136, 338, 'Find the negative of (5, 3).', 'text', 1, 'Change the sign of both components.', '{"why":"Changing both signs reverses both horizontal and vertical directions.","sol":"Step 1: The vector is (5, 3).\nStep 2: Change 5 to -5.\nStep 3: Change 3 to -3.\nStep 4: Therefore the negative vector is (-5, -3).","steps":["Step 1: The vector is (5, 3).","Step 2: Change 5 to -5.","Step 3: Change 3 to -3.","Step 4: Therefore the negative vector is (-5, -3)."],"options":[],"conceptId":"math_vectors_negative_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Negative Vectors"}', 0),
  (1137, 338, 'Find the negative of (-4, 7).', 'text', 1, 'Both signs must change.', '{"why":"The negative vector points in the exact opposite direction.","sol":"Step 1: -4 becomes 4.\nStep 2: 7 becomes -7.\nStep 3: Therefore the negative vector is (4, -7).","steps":["Step 1: -4 becomes 4.","Step 2: 7 becomes -7.","Step 3: Therefore the negative vector is (4, -7)."],"options":[],"conceptId":"math_vectors_negative_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Negative Vectors"}', 1),
  (1138, 338, 'If a = (2, -6), find -a.', 'text', 1, 'Reverse the sign of each component.', '{"why":"Both components change sign when a vector is reversed.","sol":"Step 1: a = (2, -6).\nStep 2: 2 becomes -2.\nStep 3: -6 becomes 6.\nStep 4: Therefore -a = (-2, 6).","steps":["Step 1: a = (2, -6).","Step 2: 2 becomes -2.","Step 3: -6 becomes 6.","Step 4: Therefore -a = (-2, 6)."],"options":[],"conceptId":"math_vectors_negative_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Negative Vectors"}', 2),
  (1139, 339, 'a = (7, 4) and b = (2, 1). Find a - b using the negative of b.', 'text', 1, 'First find -b.', '{"why":"Subtracting b is equivalent to adding the vector pointing opposite to b.","sol":"Step 1: b = (2, 1).\nStep 2: -b = (-2, -1).\nStep 3: a - b = a + (-b).\nStep 4: (7, 4) + (-2, -1) = (5, 3).\nStep 5: Therefore a - b = (5, 3).","steps":["Step 1: b = (2, 1).","Step 2: -b = (-2, -1).","Step 3: a - b = a + (-b).","Step 4: (7, 4) + (-2, -1) = (5, 3).","Step 5: Therefore a - b = (5, 3)."],"options":[],"conceptId":"math_vectors_geometric_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Geometric Vector Subtraction"}', 0),
  (1140, 339, 'a = (6, 2) and b = (-3, 4). Find a - b.', 'text', 1, 'Reverse both components of b first.', '{"why":"The negative of (-3, 4) is (3, -4), which is then added to a.","sol":"Step 1: b = (-3, 4).\nStep 2: -b = (3, -4).\nStep 3: a - b = a + (-b).\nStep 4: (6, 2) + (3, -4) = (9, -2).\nStep 5: Therefore a - b = (9, -2).","steps":["Step 1: b = (-3, 4).","Step 2: -b = (3, -4).","Step 3: a - b = a + (-b).","Step 4: (6, 2) + (3, -4) = (9, -2).","Step 5: Therefore a - b = (9, -2)."],"options":[],"conceptId":"math_vectors_geometric_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Geometric Vector Subtraction"}', 1),
  (1141, 339, 'a = (-4, 5) and b = (2, -3). Find a - b.', 'text', 1, 'Change the signs of b before adding.', '{"why":"Subtracting b means adding its opposite vector.","sol":"Step 1: b = (2, -3).\nStep 2: -b = (-2, 3).\nStep 3: a - b = a + (-b).\nStep 4: (-4, 5) + (-2, 3) = (-6, 8).\nStep 5: Therefore a - b = (-6, 8).","steps":["Step 1: b = (2, -3).","Step 2: -b = (-2, 3).","Step 3: a - b = a + (-b).","Step 4: (-4, 5) + (-2, 3) = (-6, 8).","Step 5: Therefore a - b = (-6, 8)."],"options":[],"conceptId":"math_vectors_geometric_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Geometric Vector Subtraction"}', 2),
  (1142, 340, 'Find (9, 7) - (4, 3).', 'text', 1, 'Subtract corresponding components.', '{"why":"Each component is subtracted from the corresponding component.","sol":"Step 1: Horizontal: 9 - 4 = 5.\nStep 2: Vertical: 7 - 3 = 4.\nStep 3: Therefore the answer is (5, 4).","steps":["Step 1: Horizontal: 9 - 4 = 5.","Step 2: Vertical: 7 - 3 = 4.","Step 3: Therefore the answer is (5, 4)."],"options":[],"conceptId":"math_vectors_column_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Column Vector Subtraction"}', 0),
  (1143, 340, 'Find (5, 2) - (-3, 4).', 'text', 1, 'Remember that subtracting a negative number becomes addition.', '{"why":"5 - (-3) becomes 5 + 3, while the vertical component remains 2 - 4.","sol":"Step 1: Horizontal: 5 - (-3) = 8.\nStep 2: Vertical: 2 - 4 = -2.\nStep 3: Therefore the answer is (8, -2).","steps":["Step 1: Horizontal: 5 - (-3) = 8.","Step 2: Vertical: 2 - 4 = -2.","Step 3: Therefore the answer is (8, -2)."],"options":[],"conceptId":"math_vectors_column_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Column Vector Subtraction"}', 1),
  (1144, 340, 'Find (-6, 3) - (2, -5).', 'text', 1, 'Work on each component separately.', '{"why":"Subtracting -5 from 3 gives 8.","sol":"Step 1: Horizontal: -6 - 2 = -8.\nStep 2: Vertical: 3 - (-5) = 8.\nStep 3: Therefore the answer is (-8, 8).","steps":["Step 1: Horizontal: -6 - 2 = -8.","Step 2: Vertical: 3 - (-5) = 8.","Step 3: Therefore the answer is (-8, 8)."],"options":[],"conceptId":"math_vectors_column_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Column Vector Subtraction"}', 2),
  (1145, 341, 'a = (7, 5) and b = (2, 1). Find a - b.', 'text', 1, 'Start with a.', '{"why":"The requested order is a minus b.","sol":"Step 1: a - b = (7, 5) - (2, 1).\nStep 2: Horizontal: 7 - 2 = 5.\nStep 3: Vertical: 5 - 1 = 4.\nStep 4: Therefore a - b = (5, 4).","steps":["Step 1: a - b = (7, 5) - (2, 1).","Step 2: Horizontal: 7 - 2 = 5.","Step 3: Vertical: 5 - 1 = 4.","Step 4: Therefore a - b = (5, 4)."],"options":[],"conceptId":"math_vectors_finding_the_difference_between_two_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding the Difference Between Two Vectors"}', 0),
  (1146, 341, 'a = (-4, 6) and b = (3, 2). Find a - b.', 'text', 1, 'Subtract the components of b from the corresponding components of a.', '{"why":"The negative horizontal component results from -4 - 3.","sol":"Step 1: a - b = (-4, 6) - (3, 2).\nStep 2: Horizontal: -4 - 3 = -7.\nStep 3: Vertical: 6 - 2 = 4.\nStep 4: Therefore a - b = (-7, 4).","steps":["Step 1: a - b = (-4, 6) - (3, 2).","Step 2: Horizontal: -4 - 3 = -7.","Step 3: Vertical: 6 - 2 = 4.","Step 4: Therefore a - b = (-7, 4)."],"options":[],"conceptId":"math_vectors_finding_the_difference_between_two_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding the Difference Between Two Vectors"}', 1),
  (1147, 341, 'a = (6, -2) and b = (-3, 5). Find a - b.', 'text', 1, 'Be especially careful with the two negative numbers.', '{"why":"Subtracting the negative horizontal component gives 9, while the vertical components give -7.","sol":"Step 1: a - b = (6, -2) - (-3, 5).\nStep 2: Horizontal: 6 - (-3) = 9.\nStep 3: Vertical: -2 - 5 = -7.\nStep 4: Therefore a - b = (9, -7).","steps":["Step 1: a - b = (6, -2) - (-3, 5).","Step 2: Horizontal: 6 - (-3) = 9.","Step 3: Vertical: -2 - 5 = -7.","Step 4: Therefore a - b = (9, -7)."],"options":[],"conceptId":"math_vectors_finding_the_difference_between_two_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding the Difference Between Two Vectors"}', 2),
  (1148, 342, 'Given a = (5, 2), find 3a.', 'text', 1, 'Multiply both components by 3.', '{"why":"A scalar multiplies every component of the vector.","sol":"Step 1: Start with a = (5, 2).\nStep 2: Multiply each component by 3: 3a = (3 × 5, 3 × 2).\nStep 3: Calculate: 3a = (15, 6).","steps":["Step 1: Start with a = (5, 2).","Step 2: Multiply each component by 3: 3a = (3 × 5, 3 × 2).","Step 3: Calculate: 3a = (15, 6)."],"options":[],"conceptId":"math_vectors_meaning_of_scalar_multiplication","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Meaning of Scalar Multiplication"}', 0),
  (1149, 342, 'Given b = (-4, 3), find 2b.', 'text', 1, 'Multiply -4 and 3 separately by 2.', '{"why":"Both components are multiplied by the scalar.","sol":"Step 1: Start with b = (-4, 3).\nStep 2: 2b = (2 × -4, 2 × 3).\nStep 3: Therefore 2b = (-8, 6).","steps":["Step 1: Start with b = (-4, 3).","Step 2: 2b = (2 × -4, 2 × 3).","Step 3: Therefore 2b = (-8, 6)."],"options":[],"conceptId":"math_vectors_meaning_of_scalar_multiplication","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Meaning of Scalar Multiplication"}', 1),
  (1150, 342, 'Given c = (6, -5), find 4c.', 'text', 1, 'Multiply 6 and -5 by 4.', '{"why":"Scalar multiplication applies to every component.","sol":"Step 1: 4c = (4 × 6, 4 × -5).\nStep 2: 4 × 6 = 24.\nStep 3: 4 × -5 = -20.\nStep 4: Therefore 4c = (24, -20).","steps":["Step 1: 4c = (4 × 6, 4 × -5).","Step 2: 4 × 6 = 24.","Step 3: 4 × -5 = -20.","Step 4: Therefore 4c = (24, -20)."],"options":[],"conceptId":"math_vectors_meaning_of_scalar_multiplication","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Meaning of Scalar Multiplication"}', 2),
  (1151, 343, 'Is (10, 15) a scalar multiple of (2, 3)?', 'text', 1, 'Divide corresponding components.', '{"why":"Both components are multiplied by the same scalar, 5.","sol":"Step 1: 10 ÷ 2 = 5.\nStep 2: 15 ÷ 3 = 5.\nStep 3: The same scalar is obtained.\nStep 4: Therefore (10, 15) = 5(2, 3).","steps":["Step 1: 10 ÷ 2 = 5.","Step 2: 15 ÷ 3 = 5.","Step 3: The same scalar is obtained.","Step 4: Therefore (10, 15) = 5(2, 3)."],"options":[],"conceptId":"math_vectors_recognising_a_scalar_multiple","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Recognising a Scalar Multiple"}', 0),
  (1152, 343, 'Is (-8, 12) a scalar multiple of (-2, 3)?', 'text', 1, 'Find the multiplier from each component.', '{"why":"Both components have the same scalar multiplier.","sol":"Step 1: -8 ÷ -2 = 4.\nStep 2: 12 ÷ 3 = 4.\nStep 3: The same multiplier is obtained.\nStep 4: Therefore (-8, 12) = 4(-2, 3).","steps":["Step 1: -8 ÷ -2 = 4.","Step 2: 12 ÷ 3 = 4.","Step 3: The same multiplier is obtained.","Step 4: Therefore (-8, 12) = 4(-2, 3)."],"options":[],"conceptId":"math_vectors_recognising_a_scalar_multiple","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Recognising a Scalar Multiple"}', 1),
  (1153, 343, 'Is (12, 15) a scalar multiple of (3, 4)?', 'text', 1, 'Compare 12 ÷ 3 with 15 ÷ 4.', '{"why":"A scalar multiple requires one common multiplier.","sol":"Step 1: 12 ÷ 3 = 4.\nStep 2: 15 ÷ 4 = 3.75.\nStep 3: The multipliers are different.\nStep 4: Therefore (12, 15) is not a scalar multiple of (3, 4).","steps":["Step 1: 12 ÷ 3 = 4.","Step 2: 15 ÷ 4 = 3.75.","Step 3: The multipliers are different.","Step 4: Therefore (12, 15) is not a scalar multiple of (3, 4)."],"options":[],"conceptId":"math_vectors_recognising_a_scalar_multiple","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Recognising a Scalar Multiple"}', 2),
  (1154, 344, 'Simplify 4a + 3a.', 'text', 1, 'Both terms contain a.', '{"why":"Like vector terms can be combined by adding their scalar coefficients.","sol":"Step 1: The terms are like terms because both contain a.\nStep 2: Add the coefficients: 4 + 3 = 7.\nStep 3: Therefore 4a + 3a = 7a.","steps":["Step 1: The terms are like terms because both contain a.","Step 2: Add the coefficients: 4 + 3 = 7.","Step 3: Therefore 4a + 3a = 7a."],"options":[],"conceptId":"math_vectors_adding_like_vector_terms","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Adding Like Vector Terms"}', 0),
  (1155, 344, 'Simplify 8b + 5b.', 'text', 1, 'Add 8 and 5.', '{"why":"The vector b remains while its coefficients are added.","sol":"Step 1: Both terms contain b.\nStep 2: 8 + 5 = 13.\nStep 3: Therefore 8b + 5b = 13b.","steps":["Step 1: Both terms contain b.","Step 2: 8 + 5 = 13.","Step 3: Therefore 8b + 5b = 13b."],"options":[],"conceptId":"math_vectors_adding_like_vector_terms","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Adding Like Vector Terms"}', 1),
  (1156, 344, 'Simplify 2c + 9c.', 'text', 1, 'Treat c as the common vector.', '{"why":"Like vector terms are combined by adding their coefficients.","sol":"Step 1: Both terms contain c.\nStep 2: 2 + 9 = 11.\nStep 3: Therefore 2c + 9c = 11c.","steps":["Step 1: Both terms contain c.","Step 2: 2 + 9 = 11.","Step 3: Therefore 2c + 9c = 11c."],"options":[],"conceptId":"math_vectors_adding_like_vector_terms","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Adding Like Vector Terms"}', 2),
  (1157, 345, 'Find the magnitude of a = (6, 8).', 'text', 1, 'Use |a| = √(x² + y²).', '{"why":"The magnitude is the hypotenuse formed by the two components.","sol":"Step 1: |a| = √(6² + 8²).\nStep 2: |a| = √(36 + 64).\nStep 3: |a| = √100.\nStep 4: |a| = 10.","steps":["Step 1: |a| = √(6² + 8²).","Step 2: |a| = √(36 + 64).","Step 3: |a| = √100.","Step 4: |a| = 10."],"options":[],"conceptId":"math_vectors_magnitude_from_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Magnitude from a Column Vector"}', 0),
  (1158, 345, 'Find the magnitude of b = (-5, 12).', 'text', 1, 'Remember that (-5)² is positive.', '{"why":"Squaring the negative component makes its contribution positive.","sol":"Step 1: |b| = √((-5)² + 12²).\nStep 2: |b| = √(25 + 144).\nStep 3: |b| = √169.\nStep 4: |b| = 13.","steps":["Step 1: |b| = √((-5)² + 12²).","Step 2: |b| = √(25 + 144).","Step 3: |b| = √169.","Step 4: |b| = 13."],"options":[],"conceptId":"math_vectors_magnitude_from_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Magnitude from a Column Vector"}', 1),
  (1159, 345, 'Find the magnitude of c = (8, 15).', 'text', 1, 'Square both components, add, then take the square root.', '{"why":"The vector length is obtained from Pythagoras'' theorem.","sol":"Step 1: |c| = √(8² + 15²).\nStep 2: |c| = √(64 + 225).\nStep 3: |c| = √289.\nStep 4: |c| = 17.","steps":["Step 1: |c| = √(8² + 15²).","Step 2: |c| = √(64 + 225).","Step 3: |c| = √289.","Step 4: |c| = 17."],"options":[],"conceptId":"math_vectors_magnitude_from_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Magnitude from a Column Vector"}', 2),
  (1160, 346, 'Find gradient of curve using dy/dx at a point', 'text', 1, 'differentiate then substitute', '{"why":"Gradient of a curve is found using differentiation at a specific point","sol":"Step 1: Start with function y = f(x)\nStep 2: Differentiate to find dy/dx\nStep 3: Substitute the given x-value\nStep 4: Compute gradient at that point","steps":["Step 1: Start with function y = f(x)","Step 2: Differentiate to find dy/dx","Step 3: Substitute the given x-value","Step 4: Compute gradient at that point"],"options":[],"conceptId":"math_calculus_gradient_of_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Gradient of a Curve"}', 0),
  (1161, 346, 'Find dy/dx for y = x² and evaluate at x = 3', 'text', 1, 'power rule', '{"why":"Derivative gives slope of tangent at a point","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: Substitute x = 3\nStep 3: Compute 2 × 3\nStep 4: Get final gradient","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: Substitute x = 3","Step 3: Compute 2 × 3","Step 4: Get final gradient"],"options":[],"conceptId":"math_calculus_gradient_of_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Gradient of a Curve"}', 1),
  (1162, 346, 'Find gradient of y = 2x + 3', 'text', 1, 'linear function rule', '{"why":"In linear equations, gradient is the coefficient of x","sol":"Step 1: Identify equation y = mx + c\nStep 2: Recognize coefficient of x\nStep 3: Extract m value\nStep 4: State gradient","steps":["Step 1: Identify equation y = mx + c","Step 2: Recognize coefficient of x","Step 3: Extract m value","Step 4: State gradient"],"options":[],"conceptId":"math_calculus_gradient_of_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Gradient of a Curve"}', 2),
  (1163, 346, 'Find dy/dx of y = 3x² at x = 2', 'text', 1, 'power rule', '{"why":"Derivative gives instantaneous rate of change","sol":"Step 1: Differentiate y = 3x² → dy/dx = 6x\nStep 2: Substitute x = 2\nStep 3: Multiply 6 × 2\nStep 4: Compute gradient","steps":["Step 1: Differentiate y = 3x² → dy/dx = 6x","Step 2: Substitute x = 2","Step 3: Multiply 6 × 2","Step 4: Compute gradient"],"options":[],"conceptId":"math_calculus_gradient_of_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Gradient of a Curve"}', 3),
  (1164, 347, 'Find rate of change of y with respect to x for y = 3x² at x = 2', 'text', 1, 'differentiate then substitute', '{"why":"Rate of change is found using differentiation and substitution","sol":"Step 1: Start with y = 3x²\nStep 2: Differentiate → dy/dx = 6x\nStep 3: Substitute x = 2\nStep 4: Compute 6 × 2\nStep 5: Final value of rate of change","steps":["Step 1: Start with y = 3x²","Step 2: Differentiate → dy/dx = 6x","Step 3: Substitute x = 2","Step 4: Compute 6 × 2","Step 5: Final value of rate of change"],"options":[],"conceptId":"math_calculus_rate_of_change","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Rate of Change"}', 0),
  (1165, 347, 'Find dy/dx for y = 5x at any point', 'text', 1, 'linear rule', '{"why":"Linear functions have constant rate of change equal to slope","sol":"Step 1: Identify y = mx form\nStep 2: Differentiate → dy/dx = 5\nStep 3: Note constant slope\nStep 4: State rate of change","steps":["Step 1: Identify y = mx form","Step 2: Differentiate → dy/dx = 5","Step 3: Note constant slope","Step 4: State rate of change"],"options":[],"conceptId":"math_calculus_rate_of_change","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Rate of Change"}', 1),
  (1166, 347, 'A car travels distance s = 4t². Find speed at t = 3', 'text', 1, 'differentiate distance', '{"why":"Speed is rate of change of distance with respect to time","sol":"Step 1: Start with s = 4t²\nStep 2: Differentiate → ds/dt = 8t\nStep 3: Substitute t = 3\nStep 4: Compute 8 × 3\nStep 5: Final speed value","steps":["Step 1: Start with s = 4t²","Step 2: Differentiate → ds/dt = 8t","Step 3: Substitute t = 3","Step 4: Compute 8 × 3","Step 5: Final speed value"],"options":[],"conceptId":"math_calculus_rate_of_change","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Rate of Change"}', 2),
  (1167, 347, 'Find rate of change of y = x³ at x = 1', 'text', 1, 'power rule', '{"why":"Derivative gives instantaneous rate of change","sol":"Step 1: Differentiate y = x³ → dy/dx = 3x²\nStep 2: Substitute x = 1\nStep 3: Compute 3 × 1²\nStep 4: Final value","steps":["Step 1: Differentiate y = x³ → dy/dx = 3x²","Step 2: Substitute x = 1","Step 3: Compute 3 × 1²","Step 4: Final value"],"options":[],"conceptId":"math_calculus_rate_of_change","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Rate of Change"}', 3),
  (1168, 348, 'Find turning point and determine maximum/minimum for y = -x² + 6x - 5', 'text', 1, 'differentiate and classify', '{"why":"Negative x² means the parabola opens downward, giving a maximum","sol":"Step 1: Differentiate y = -x² + 6x - 5 → dy/dx = -2x + 6\nStep 2: Set dy/dx = 0 → -2x + 6 = 0\nStep 3: Solve → 2x = 6\nStep 4: x = 3\nStep 5: Since coefficient of x² is negative, curve opens downward\nStep 6: Therefore turning point is a maximum","steps":["Step 1: Differentiate y = -x² + 6x - 5 → dy/dx = -2x + 6","Step 2: Set dy/dx = 0 → -2x + 6 = 0","Step 3: Solve → 2x = 6","Step 4: x = 3","Step 5: Since coefficient of x² is negative, curve opens downward","Step 6: Therefore turning point is a maximum"],"options":[],"conceptId":"math_calculus_maxima_and_minima","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Maxima and Minima"}', 0),
  (1169, 348, 'Find maximum point of y = -2x² + 8x + 1', 'text', 1, 'dy/dx = 0', '{"why":"Vertex gives highest value because parabola opens downward","sol":"Step 1: Differentiate → dy/dx = -4x + 8\nStep 2: Set dy/dx = 0 → -4x + 8 = 0\nStep 3: Solve → 4x = 8\nStep 4: x = 2\nStep 5: Substitute into original function → y = -2(2²) + 8(2) + 1\nStep 6: y = -8 + 16 + 1 = 9","steps":["Step 1: Differentiate → dy/dx = -4x + 8","Step 2: Set dy/dx = 0 → -4x + 8 = 0","Step 3: Solve → 4x = 8","Step 4: x = 2","Step 5: Substitute into original function → y = -2(2²) + 8(2) + 1","Step 6: y = -8 + 16 + 1 = 9"],"options":[],"conceptId":"math_calculus_maxima_and_minima","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Maxima and Minima"}', 1),
  (1170, 348, 'Find minimum point of y = x² + 8x + 12', 'text', 1, 'complete or differentiate', '{"why":"Positive x² means parabola opens upward giving a minimum","sol":"Step 1: Differentiate → dy/dx = 2x + 8\nStep 2: Set dy/dx = 0 → 2x + 8 = 0\nStep 3: Solve → 2x = -8\nStep 4: x = -4\nStep 5: Substitute into function → y = (-4)² + 8(-4) + 12\nStep 6: y = 16 - 32 + 12 = -4","steps":["Step 1: Differentiate → dy/dx = 2x + 8","Step 2: Set dy/dx = 0 → 2x + 8 = 0","Step 3: Solve → 2x = -8","Step 4: x = -4","Step 5: Substitute into function → y = (-4)² + 8(-4) + 12","Step 6: y = 16 - 32 + 12 = -4"],"options":[],"conceptId":"math_calculus_maxima_and_minima","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Maxima and Minima"}', 2),
  (1171, 348, 'Find stationary point of y = x² - 10x + 25 and classify it', 'text', 1, 'perfect square form', '{"why":"Perfect square quadratic always has a minimum vertex","sol":"Step 1: Differentiate → dy/dx = 2x - 10\nStep 2: Set dy/dx = 0 → 2x - 10 = 0\nStep 3: Solve → 2x = 10\nStep 4: x = 5\nStep 5: Substitute → y = 25 - 50 + 25 = 0\nStep 6: Since coefficient of x² is positive, it is a minimum","steps":["Step 1: Differentiate → dy/dx = 2x - 10","Step 2: Set dy/dx = 0 → 2x - 10 = 0","Step 3: Solve → 2x = 10","Step 4: x = 5","Step 5: Substitute → y = 25 - 50 + 25 = 0","Step 6: Since coefficient of x² is positive, it is a minimum"],"options":[],"conceptId":"math_calculus_maxima_and_minima","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Maxima and Minima"}', 3),
  (1172, 348, 'Find maximum value of y = 3x - x²', 'text', 1, 'rearrange quadratic', '{"why":"Negative x² ensures a maximum at vertex","sol":"Step 1: Rewrite y = -x² + 3x\nStep 2: Differentiate → dy/dx = -2x + 3\nStep 3: Set dy/dx = 0 → -2x + 3 = 0\nStep 4: Solve → 2x = 3\nStep 5: x = 3/2\nStep 6: Substitute → y = 3(3/2) - (3/2)²\nStep 7: y = 9/2 - 9/4 = 9/4","steps":["Step 1: Rewrite y = -x² + 3x","Step 2: Differentiate → dy/dx = -2x + 3","Step 3: Set dy/dx = 0 → -2x + 3 = 0","Step 4: Solve → 2x = 3","Step 5: x = 3/2","Step 6: Substitute → y = 3(3/2) - (3/2)²","Step 7: y = 9/2 - 9/4 = 9/4"],"options":[],"conceptId":"math_calculus_maxima_and_minima","skillId":"math_calculus","subskillId":"math_calculus_q5","subject":"math","chapter":"calculus","topic":"Maxima and Minima"}', 4),
  (1173, 349, 'Find slope of tangent to y = x² at x = 4', 'text', 1, 'differentiate and substitute', '{"why":"Derivative gives slope of tangent at a point","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: Substitute x = 4\nStep 3: Compute 2 × 4\nStep 4: Final slope value","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: Substitute x = 4","Step 3: Compute 2 × 4","Step 4: Final slope value"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 0),
  (1174, 349, 'If tangent slope is 3, what is slope of normal?', 'text', 1, 'negative reciprocal', '{"why":"Perpendicular lines have slopes that multiply to -1","sol":"Step 1: Identify tangent slope m = 3\nStep 2: Use formula slope(normal) = -1/m\nStep 3: Compute -1/3\nStep 4: Final result","steps":["Step 1: Identify tangent slope m = 3","Step 2: Use formula slope(normal) = -1/m","Step 3: Compute -1/3","Step 4: Final result"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 1),
  (1175, 349, 'Find equation of tangent to y = x² at (2, 4)', 'text', 1, 'point-slope form', '{"why":"Tangent is a straight line touching the curve at a point","sol":"Step 1: Differentiate to find slope at x = 2\nStep 2: dy/dx = 2x → slope = 4\nStep 3: Use point (2, 4) and slope 4\nStep 4: Equation: y - 4 = 4(x - 2)\nStep 5: Simplify → y = 4x - 4","steps":["Step 1: Differentiate to find slope at x = 2","Step 2: dy/dx = 2x → slope = 4","Step 3: Use point (2, 4) and slope 4","Step 4: Equation: y - 4 = 4(x - 2)","Step 5: Simplify → y = 4x - 4"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 2),
  (1176, 349, 'Find equation of tangent slope for y = x² at x = 2', 'text', 1, 'differentiate then substitute', '{"why":"Tangent slope is found using derivative at a point","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: Substitute x = 2\nStep 3: Compute 2 × 2\nStep 4: Tangent slope = 4","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: Substitute x = 2","Step 3: Compute 2 × 2","Step 4: Tangent slope = 4"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 3),
  (1177, 349, 'Find equation of normal slope if tangent slope is 3', 'text', 1, 'negative reciprocal', '{"why":"Normal is perpendicular to tangent, so slopes multiply to -1","sol":"Step 1: Identify tangent slope m = 3\nStep 2: Apply normal formula = -1/m\nStep 3: Substitute values → -1/3\nStep 4: Simplify result","steps":["Step 1: Identify tangent slope m = 3","Step 2: Apply normal formula = -1/m","Step 3: Substitute values → -1/3","Step 4: Simplify result"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q5","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 4),
  (1178, 349, 'Find slope of tangent for y = 3x² + 2x at x = 1', 'text', 1, 'differentiate first', '{"why":"Derivative gives slope of tangent at a point","sol":"Step 1: Differentiate y → dy/dx = 6x + 2\nStep 2: Substitute x = 1\nStep 3: Compute 6(1) + 2\nStep 4: Final slope = 8","steps":["Step 1: Differentiate y → dy/dx = 6x + 2","Step 2: Substitute x = 1","Step 3: Compute 6(1) + 2","Step 4: Final slope = 8"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q6","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 5),
  (1179, 349, 'Find normal slope if tangent slope is -5', 'text', 1, 'negative reciprocal rule', '{"why":"Normal is perpendicular so slope is negative reciprocal","sol":"Step 1: Tangent slope m = -5\nStep 2: Apply formula -1/m\nStep 3: Compute -1 / (-5)\nStep 4: Simplify result","steps":["Step 1: Tangent slope m = -5","Step 2: Apply formula -1/m","Step 3: Compute -1 / (-5)","Step 4: Simplify result"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q7","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 6),
  (1180, 349, 'Find equation of tangent to y = x² at point (2, 4)', 'text', 1, 'first find slope, then use point-slope form', '{"why":"Tangent is a line touching curve at a point; its slope is the derivative value at that point","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: Substitute x = 2 → slope m = 4\nStep 3: Use point (2, 4) in y - y₁ = m(x - x₁)\nStep 4: Equation becomes y - 4 = 4(x - 2)\nStep 5: Simplify → y = 4x - 4","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: Substitute x = 2 → slope m = 4","Step 3: Use point (2, 4) in y - y₁ = m(x - x₁)","Step 4: Equation becomes y - 4 = 4(x - 2)","Step 5: Simplify → y = 4x - 4"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q8","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 7),
  (1181, 349, 'Find equation of normal to y = x² at (2, 4)', 'text', 1, 'use perpendicular slope', '{"why":"Normal is perpendicular to tangent at the same point, hence negative reciprocal slope","sol":"Step 1: Slope of tangent at x = 2 is m = 4\nStep 2: Normal slope is perpendicular → -1/4\nStep 3: Use point (2, 4) in y - y₁ = m(x - x₁)\nStep 4: Equation: y - 4 = -1/4(x - 2)\nStep 5: Simplify to standard form","steps":["Step 1: Slope of tangent at x = 2 is m = 4","Step 2: Normal slope is perpendicular → -1/4","Step 3: Use point (2, 4) in y - y₁ = m(x - x₁)","Step 4: Equation: y - 4 = -1/4(x - 2)","Step 5: Simplify to standard form"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q9","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 8),
  (1182, 349, 'Find x-intercept of tangent to y = x² at x = 3', 'text', 1, 'first find tangent equation', '{"why":"The tangent line has a specific slope and passes through the point, allowing its intercepts to be calculated","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: At x = 3, slope m = 2(3) = 6\nStep 3: Point is (3, 3²) = (3, 9)\nStep 4: Tangent equation: y - 9 = 6(x - 3)\nStep 5: Set y = 0 to find x-intercept → -9 = 6x - 18\nStep 6: Solve for x → x = 9/6 = 3/2","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: At x = 3, slope m = 2(3) = 6","Step 3: Point is (3, 3²) = (3, 9)","Step 4: Tangent equation: y - 9 = 6(x - 3)","Step 5: Set y = 0 to find x-intercept → -9 = 6x - 18","Step 6: Solve for x → x = 9/6 = 3/2"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q10","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 9),
  (1183, 349, 'At what x-value is tangent to y = x² parallel to line y = 4x + 1?', 'text', 1, 'slopes must be equal', '{"why":"Parallel lines have equal slopes, so we equate tangent slope to line slope and solve for x","sol":"Step 1: Slope of given line is 4\nStep 2: Slope of tangent is derivative dy/dx = 2x\nStep 3: Set slopes equal → 2x = 4\nStep 4: Solve for x → x = 2","steps":["Step 1: Slope of given line is 4","Step 2: Slope of tangent is derivative dy/dx = 2x","Step 3: Set slopes equal → 2x = 4","Step 4: Solve for x → x = 2"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q11","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 10),
  (1184, 349, 'Find the perpendicular distance from origin (0, 0) to tangent of y = x² at x = 4', 'text', 1, 'find tangent equation first', '{"why":"Perpendicular distance formula is used to find distance from origin to the calculated tangent line","sol":"Step 1: At x = 4, slope m = 2(4) = 8\nStep 2: Point is (4, 4²) = (4, 16)\nStep 3: Tangent equation: y - 16 = 8(x - 4) → 8x - y - 16 = 0\nStep 4: Use distance formula from point (x₀, y₀) to line Ax + By + C = 0: distance = |Ax₀ + By₀ + C| / sqrt(A² + B²)\nStep 5: For origin (0, 0) and line 8x - y - 16 = 0 → distance = |-16| / sqrt(8² + (-1)²)\nStep 6: Simplify → distance = 16 / sqrt(65)","steps":["Step 1: At x = 4, slope m = 2(4) = 8","Step 2: Point is (4, 4²) = (4, 16)","Step 3: Tangent equation: y - 16 = 8(x - 4) → 8x - y - 16 = 0","Step 4: Use distance formula from point (x₀, y₀) to line Ax + By + C = 0: distance = |Ax₀ + By₀ + C| / sqrt(A² + B²)","Step 5: For origin (0, 0) and line 8x - y - 16 = 0 → distance = |-16| / sqrt(8² + (-1)²)","Step 6: Simplify → distance = 16 / sqrt(65)"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q12","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 11),
  (1185, 350, 'Why is differentiation important?', 'text', 1, 'rate of change', '{"why":"It quantifies how one variable changes with respect to another","sol":"Step 1: Identify key concept: Define the required principles for Applications of Differentiation.\nStep 2: Apply governing rule: It quantifies how one variable changes with respect to another\nStep 3: State the final conclusion: measures change","steps":["Step 1: Identify key concept: Define the required principles for Applications of Differentiation.","Step 2: Apply governing rule: It quantifies how one variable changes with respect to another","Step 3: State the final conclusion: measures change"],"options":[],"conceptId":"math_calculus_applications_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Applications of Differentiation"}', 0),
  (1186, 350, 'Give real-life use', 'text', 1, 'motion or business', '{"why":"Used in physics for velocity and in economics for maximizing profit","sol":"Step 1: Identify key concept: Define the required principles for Applications of Differentiation.\nStep 2: Apply governing rule: Used in physics for velocity and in economics for maximizing profit\nStep 3: State the final conclusion: speed or profit optimization","steps":["Step 1: Identify key concept: Define the required principles for Applications of Differentiation.","Step 2: Apply governing rule: Used in physics for velocity and in economics for maximizing profit","Step 3: State the final conclusion: speed or profit optimization"],"options":[],"conceptId":"math_calculus_applications_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Applications of Differentiation"}', 1),
  (1187, 350, 'What does f''(x) represent?', 'text', 1, 'derivative meaning', '{"why":"It represents instantaneous rate of change of a function","sol":"Step 1: Identify key concept: Define the required principles for Applications of Differentiation.\nStep 2: Apply governing rule: It represents instantaneous rate of change of a function\nStep 3: State the final conclusion: rate of change or slope","steps":["Step 1: Identify key concept: Define the required principles for Applications of Differentiation.","Step 2: Apply governing rule: It represents instantaneous rate of change of a function","Step 3: State the final conclusion: rate of change or slope"],"options":[],"conceptId":"math_calculus_applications_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Applications of Differentiation"}', 2),
  (1188, 351, 'Evaluate ∫ x dx', 'text', 1, 'power rule integration', '{"why":"Integration is reverse of differentiation using power rule","sol":"Step 1: Increase power of x by 1 → x¹ becomes x²\nStep 2: Divide by new power → x² / 2\nStep 3: Add constant of integration C\nStep 4: Final expression","steps":["Step 1: Increase power of x by 1 → x¹ becomes x²","Step 2: Divide by new power → x² / 2","Step 3: Add constant of integration C","Step 4: Final expression"],"options":[],"conceptId":"math_calculus_area_under_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Area Under a Curve"}', 0),
  (1189, 351, 'Evaluate ∫ x² dx', 'text', 1, 'increase power', '{"why":"Power rule: add 1 to exponent then divide","sol":"Step 1: Increase exponent → x² becomes x³\nStep 2: Divide by new exponent → x³ / 3\nStep 3: Add constant C\nStep 4: Write final result","steps":["Step 1: Increase exponent → x² becomes x³","Step 2: Divide by new exponent → x³ / 3","Step 3: Add constant C","Step 4: Write final result"],"options":[],"conceptId":"math_calculus_area_under_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Area Under a Curve"}', 1),
  (1190, 351, 'Evaluate definite integral ∫ from 0 to 2 of x dx', 'text', 1, 'area under curve', '{"why":"Definite integrals give net area under curve","sol":"Step 1: Find integral of x → x²/2\nStep 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2\nStep 3: Substitute lower limit 0 → 0²/2 = 0\nStep 4: Subtract upper - lower → 2 - 0\nStep 5: Final answer","steps":["Step 1: Find integral of x → x²/2","Step 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2","Step 3: Substitute lower limit 0 → 0²/2 = 0","Step 4: Subtract upper - lower → 2 - 0","Step 5: Final answer"],"options":[],"conceptId":"math_calculus_area_under_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Area Under a Curve"}', 2),
  (1191, 351, 'Evaluate ∫ 3x² dx', 'text', 1, 'constant multiple rule', '{"why":"Constant multiples remain unchanged in integration","sol":"Step 1: Keep constant 3 outside\nStep 2: Integrate x² → x³/3\nStep 3: Multiply → 3 × (x³/3)\nStep 4: Simplify expression\nStep 5: Add +C","steps":["Step 1: Keep constant 3 outside","Step 2: Integrate x² → x³/3","Step 3: Multiply → 3 × (x³/3)","Step 4: Simplify expression","Step 5: Add +C"],"options":[],"conceptId":"math_calculus_area_under_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Area Under a Curve"}', 3),
  (1192, 352, 'Evaluate ∫ x dx', 'text', 1, 'power rule integration', '{"why":"Integration is reverse of differentiation using power rule","sol":"Step 1: Increase power of x by 1 → x¹ becomes x²\nStep 2: Divide by new power → x² / 2\nStep 3: Add constant of integration C\nStep 4: Final expression","steps":["Step 1: Increase power of x by 1 → x¹ becomes x²","Step 2: Divide by new power → x² / 2","Step 3: Add constant of integration C","Step 4: Final expression"],"options":[],"conceptId":"math_calculus_indefinite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Indefinite Integrals"}', 0),
  (1193, 352, 'Evaluate ∫ x² dx', 'text', 1, 'increase power', '{"why":"Power rule: add 1 to exponent then divide","sol":"Step 1: Increase exponent → x² becomes x³\nStep 2: Divide by new exponent → x³ / 3\nStep 3: Add constant C\nStep 4: Write final result","steps":["Step 1: Increase exponent → x² becomes x³","Step 2: Divide by new exponent → x³ / 3","Step 3: Add constant C","Step 4: Write final result"],"options":[],"conceptId":"math_calculus_indefinite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Indefinite Integrals"}', 1),
  (1194, 352, 'Evaluate definite integral ∫ from 0 to 2 of x dx', 'text', 1, 'area under curve', '{"why":"Definite integrals give net area under curve","sol":"Step 1: Find integral of x → x²/2\nStep 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2\nStep 3: Substitute lower limit 0 → 0²/2 = 0\nStep 4: Subtract upper - lower → 2 - 0\nStep 5: Final answer","steps":["Step 1: Find integral of x → x²/2","Step 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2","Step 3: Substitute lower limit 0 → 0²/2 = 0","Step 4: Subtract upper - lower → 2 - 0","Step 5: Final answer"],"options":[],"conceptId":"math_calculus_indefinite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Indefinite Integrals"}', 2),
  (1195, 352, 'Evaluate ∫ 3x² dx', 'text', 1, 'constant multiple rule', '{"why":"Constant multiples remain unchanged in integration","sol":"Step 1: Keep constant 3 outside\nStep 2: Integrate x² → x³/3\nStep 3: Multiply → 3 × (x³/3)\nStep 4: Simplify expression\nStep 5: Add +C","steps":["Step 1: Keep constant 3 outside","Step 2: Integrate x² → x³/3","Step 3: Multiply → 3 × (x³/3)","Step 4: Simplify expression","Step 5: Add +C"],"options":[],"conceptId":"math_calculus_indefinite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Indefinite Integrals"}', 3),
  (1196, 352, 'Why does integration represent area under a curve?', 'text', 1, 'limit of rectangles', '{"why":"Integration is the limit of summing thin rectangles","sol":"Step 1: Divide area under curve into small rectangles\nStep 2: Approximate each rectangle’s area\nStep 3: Increase number of rectangles\nStep 4: Make width approach zero\nStep 5: Sum becomes exact area","steps":["Step 1: Divide area under curve into small rectangles","Step 2: Approximate each rectangle’s area","Step 3: Increase number of rectangles","Step 4: Make width approach zero","Step 5: Sum becomes exact area"],"options":[],"conceptId":"math_calculus_indefinite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q5","subject":"math","chapter":"calculus","topic":"Indefinite Integrals"}', 4),
  (1197, 353, 'Evaluate definite integral ∫ from 1 to 2 of x dx', 'text', 1, 'definite integral with limits', '{"why":"Definite integrals calculate net area under a curve between two points","sol":"Step 1: Find antiderivative of x → x²/2\nStep 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2\nStep 3: Substitute lower limit 1 → (1²)/2 = 1/2\nStep 4: Subtract upper limit value from lower limit value\nStep 5: Result = 2 - 1/2 = 3/2","steps":["Step 1: Find antiderivative of x → x²/2","Step 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2","Step 3: Substitute lower limit 1 → (1²)/2 = 1/2","Step 4: Subtract upper limit value from lower limit value","Step 5: Result = 2 - 1/2 = 3/2"],"options":[],"conceptId":"math_calculus_definite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Definite Integrals"}', 0),
  (1198, 353, 'Find area under y = x² from 0 to 3', 'text', 1, 'use definite integral', '{"why":"Definite integral of a function over an interval gives the area under that curve","sol":"Step 1: Set up integral ∫ from 0 to 3 of x² dx\nStep 2: Integrate x² → x³/3\nStep 3: Apply limits → (3³/3) - (0³/3)\nStep 4: Simplify → 27/3 - 0\nStep 5: Final area = 9","steps":["Step 1: Set up integral ∫ from 0 to 3 of x² dx","Step 2: Integrate x² → x³/3","Step 3: Apply limits → (3³/3) - (0³/3)","Step 4: Simplify → 27/3 - 0","Step 5: Final area = 9"],"options":[],"conceptId":"math_calculus_definite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Definite Integrals"}', 1),
  (1199, 353, 'Evaluate ∫ from 0 to 1 of (2x + 1) dx', 'text', 1, 'integrate term by term', '{"why":"Integrate each term separately and evaluate over the given interval","sol":"Step 1: Integrate 2x → x²\nStep 2: Integrate 1 → x\nStep 3: Combine → x² + x\nStep 4: Apply limits [0, 1] → (1² + 1) - (0² + 0)\nStep 5: Result = 2 - 0 = 2","steps":["Step 1: Integrate 2x → x²","Step 2: Integrate 1 → x","Step 3: Combine → x² + x","Step 4: Apply limits [0, 1] → (1² + 1) - (0² + 0)","Step 5: Result = 2 - 0 = 2"],"options":[],"conceptId":"math_calculus_definite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Definite Integrals"}', 2),
  (1200, 353, 'What is difference between ∫ x dx and ∫₀¹ x dx?', 'text', 1, 'limits vs no limits', '{"why":"Limits define the interval and produce a single value instead of a function","sol":"Step 1: ∫ x dx has no limits\nStep 2: Result is family of functions → x²/2 + C\nStep 3: ∫₀¹ x dx has limits\nStep 4: Result is numerical value → 1/2\nStep 5: Compare both results","steps":["Step 1: ∫ x dx has no limits","Step 2: Result is family of functions → x²/2 + C","Step 3: ∫₀¹ x dx has limits","Step 4: Result is numerical value → 1/2","Step 5: Compare both results"],"options":[],"conceptId":"math_calculus_definite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Definite Integrals"}', 3),
  (1201, 354, 'Find ∫ (2x) dx and verify relationship with differentiation', 'text', 1, 'reverse of derivative', '{"why":"Integration reverses differentiation","sol":"Step 1: Recognize 2x as derivative of x²\nStep 2: Apply integration rule → increase power of x\nStep 3: ∫ 2x dx = x² + C\nStep 4: Differentiate result → d/dx(x² + C)\nStep 5: Get 2x (original function)","steps":["Step 1: Recognize 2x as derivative of x²","Step 2: Apply integration rule → increase power of x","Step 3: ∫ 2x dx = x² + C","Step 4: Differentiate result → d/dx(x² + C)","Step 5: Get 2x (original function)"],"options":[],"conceptId":"math_calculus_integration_as_reverse_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Integration as Reverse of Differentiation"}', 0),
  (1202, 354, 'Find function if ∫ f(x) dx = x³/3 + C', 'text', 1, 'differentiate result', '{"why":"Differentiation reverses integration","sol":"Step 1: Differentiate both sides\nStep 2: d/dx (x³/3 + C)\nStep 3: Apply power rule → (3x²)/3\nStep 4: Simplify result\nStep 5: Get f(x)","steps":["Step 1: Differentiate both sides","Step 2: d/dx (x³/3 + C)","Step 3: Apply power rule → (3x²)/3","Step 4: Simplify result","Step 5: Get f(x)"],"options":[],"conceptId":"math_calculus_integration_as_reverse_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Integration as Reverse of Differentiation"}', 1),
  (1203, 354, 'Show that integration adds a constant using ∫ 0 dx', 'text', 1, 'constant rule', '{"why":"Derivative removes constants, integration restores them","sol":"Step 1: Integrate 0 → ∫ 0 dx\nStep 2: Result is constant C\nStep 3: Differentiate C\nStep 4: d/dx(C) = 0\nStep 5: Confirm relationship","steps":["Step 1: Integrate 0 → ∫ 0 dx","Step 2: Result is constant C","Step 3: Differentiate C","Step 4: d/dx(C) = 0","Step 5: Confirm relationship"],"options":[],"conceptId":"math_calculus_integration_as_reverse_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Integration as Reverse of Differentiation"}', 2),
  (1204, 354, 'If d/dx (x² + 5) = 2x, find integral of 2x', 'text', 1, 'inverse process', '{"why":"Integration reconstructs original function up to a constant","sol":"Step 1: Recognize 2x as derivative of x²\nStep 2: Integrate 2x → x²\nStep 3: Add constant C\nStep 4: Final expression","steps":["Step 1: Recognize 2x as derivative of x²","Step 2: Integrate 2x → x²","Step 3: Add constant C","Step 4: Final expression"],"options":[],"conceptId":"math_calculus_integration_as_reverse_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Integration as Reverse of Differentiation"}', 3),
  (1205, 355, 'Find ∫ (2x) dx and verify relationship with differentiation', 'text', 1, 'reverse of derivative', '{"why":"Integration reverses differentiation","sol":"Step 1: Recognize 2x as derivative of x²\nStep 2: Apply integration rule → increase power of x\nStep 3: ∫ 2x dx = x² + C\nStep 4: Differentiate result → d/dx(x² + C)\nStep 5: Get 2x (original function)","steps":["Step 1: Recognize 2x as derivative of x²","Step 2: Apply integration rule → increase power of x","Step 3: ∫ 2x dx = x² + C","Step 4: Differentiate result → d/dx(x² + C)","Step 5: Get 2x (original function)"],"options":[],"conceptId":"math_calculus_applications_of_integration","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Applications of Integration"}', 0),
  (1206, 355, 'Find function if ∫ f(x) dx = x³/3 + C', 'text', 1, 'differentiate result', '{"why":"Differentiation reverses integration","sol":"Step 1: Differentiate both sides\nStep 2: d/dx (x³/3 + C)\nStep 3: Apply power rule → (3x²)/3\nStep 4: Simplify result\nStep 5: Get f(x)","steps":["Step 1: Differentiate both sides","Step 2: d/dx (x³/3 + C)","Step 3: Apply power rule → (3x²)/3","Step 4: Simplify result","Step 5: Get f(x)"],"options":[],"conceptId":"math_calculus_applications_of_integration","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Applications of Integration"}', 1),
  (1207, 355, 'Show that integration adds a constant using ∫ 0 dx', 'text', 1, 'constant rule', '{"why":"Derivative removes constants, integration restores them","sol":"Step 1: Integrate 0 → ∫ 0 dx\nStep 2: Result is constant C\nStep 3: Differentiate C\nStep 4: d/dx(C) = 0\nStep 5: Confirm relationship","steps":["Step 1: Integrate 0 → ∫ 0 dx","Step 2: Result is constant C","Step 3: Differentiate C","Step 4: d/dx(C) = 0","Step 5: Confirm relationship"],"options":[],"conceptId":"math_calculus_applications_of_integration","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Applications of Integration"}', 2),
  (1208, 355, 'If d/dx (x² + 5) = 2x, find integral of 2x', 'text', 1, 'inverse process', '{"why":"Integration reconstructs original function up to a constant","sol":"Step 1: Recognize 2x as derivative of x²\nStep 2: Integrate 2x → x²\nStep 3: Add constant C\nStep 4: Final expression","steps":["Step 1: Recognize 2x as derivative of x²","Step 2: Integrate 2x → x²","Step 3: Add constant C","Step 4: Final expression"],"options":[],"conceptId":"math_calculus_applications_of_integration","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Applications of Integration"}', 3),
  (1209, 356, 'A person walks 10 m forward and 10 m back. Find distance and displacement.', 'text', 1, 'Distance = total path, Displacement = change in position', '{"why":"Distance is total path covered, while displacement depends on change in position.","sol":"Step 1: Forward distance = 10 m\nStep 2: Backward distance = 10 m\nStep 3: Total distance = 10 + 10 = 20 m\nStep 4: Final position = starting point\nStep 5: Displacement = 0 m","steps":["Step 1: Forward distance = 10 m","Step 2: Backward distance = 10 m","Step 3: Total distance = 10 + 10 = 20 m","Step 4: Final position = starting point","Step 5: Displacement = 0 m"],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 0),
  (1210, 356, 'Why can displacement be zero but distance not?', 'text', 1, 'starting and ending point', '{"why":"If you return to the starting point, displacement becomes zero but distance still adds up.","sol":"Step 1: Identify key concept: Define the required principles for Displacement & Distance.\nStep 2: Apply governing rule: If you return to the starting point, displacement becomes zero but distance still adds up.\nStep 3: State the final conclusion: Because distance measures total path travelled, while displacement depends only on initial and final position.","steps":["Step 1: Identify key concept: Define the required principles for Displacement & Distance.","Step 2: Apply governing rule: If you return to the starting point, displacement becomes zero but distance still adds up.","Step 3: State the final conclusion: Because distance measures total path travelled, while displacement depends only on initial and final position."],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 1),
  (1211, 356, 'A car moves 30 m east and then 40 m east. Find distance and displacement.', 'text', 1, 'same direction → add directly', '{"why":"When motion is in one direction, distance equals displacement.","sol":"Step 1: Distance = 30 + 40 = 70 m\nStep 2: Both in same direction (east)\nStep 3: Displacement = 70 m east","steps":["Step 1: Distance = 30 + 40 = 70 m","Step 2: Both in same direction (east)","Step 3: Displacement = 70 m east"],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 2),
  (1212, 356, 'A person walks 15 m north then 5 m south. Find distance and displacement.', 'text', 1, 'opposite directions → subtract', '{"why":"Displacement depends on net movement, not total path.","sol":"Step 1: Distance = 15 + 5 = 20 m\nStep 2: Net movement = 15 - 5 = 10 m\nStep 3: Direction = north","steps":["Step 1: Distance = 15 + 5 = 20 m","Step 2: Net movement = 15 - 5 = 10 m","Step 3: Direction = north"],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 3),
  (1213, 356, 'A car travels 100 m east, then 100 m west. Find distance and displacement.', 'text', 1, 'returns to start', '{"why":"Opposite equal movements cancel displacement.","sol":"Step 1: Distance = 100 + 100 = 200 m\nStep 2: Final position = starting point\nStep 3: Displacement = 0 m","steps":["Step 1: Distance = 100 + 100 = 200 m","Step 2: Final position = starting point","Step 3: Displacement = 0 m"],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 4),
  (1214, 356, 'A person walks 8 m east, then 6 m west. Find displacement.', 'text', 1, 'subtract opposite directions', '{"why":"Displacement is the net movement considering direction.","sol":"Step 1: Identify directions → east and west\nStep 2: Subtract → 8 - 6 = 2\nStep 3: Direction = east","steps":["Step 1: Identify directions → east and west","Step 2: Subtract → 8 - 6 = 2","Step 3: Direction = east"],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 5),
  (1215, 357, 'A runner covers 200 m in 25 s. Find speed.', 'text', 1, 'Use speed = distance ÷ time', '{"why":"Speed is the rate of covering distance per unit time.","sol":"Step 1: Identify values → s = 200 m, t = 25 s\nStep 2: Substitute → v = 200 ÷ 25\nStep 3: Calculate → v = 8 m/s","steps":["Step 1: Identify values → s = 200 m, t = 25 s","Step 2: Substitute → v = 200 ÷ 25","Step 3: Calculate → v = 8 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Speed"}', 0),
  (1216, 357, 'A car travels 360 km in 6 hours. Find speed.', 'text', 1, 'distance ÷ time', '{"why":"Speed in km/h is calculated using total distance divided by total time.","sol":"Step 1: s = 360 km, t = 6 h\nStep 2: v = 360 ÷ 6\nStep 3: v = 60 km/h","steps":["Step 1: s = 360 km, t = 6 h","Step 2: v = 360 ÷ 6","Step 3: v = 60 km/h"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Speed"}', 1),
  (1217, 357, 'A body moves 500 m in 50 s. Find speed.', 'text', 1, 'v = s / t', '{"why":"Speed measures how fast distance is covered.","sol":"Step 1: s = 500 m, t = 50 s\nStep 2: v = 500 ÷ 50\nStep 3: v = 10 m/s","steps":["Step 1: s = 500 m, t = 50 s","Step 2: v = 500 ÷ 50","Step 3: v = 10 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Speed"}', 2),
  (1218, 357, 'A cyclist moves 120 km in 4 hours. Find speed.', 'text', 1, 'distance ÷ time', '{"why":"Speed is distance divided by time.","sol":"Step 1: s = 120 km, t = 4 h\nStep 2: v = 120 ÷ 4\nStep 3: v = 30 km/h","steps":["Step 1: s = 120 km, t = 4 h","Step 2: v = 120 ÷ 4","Step 3: v = 30 km/h"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Speed"}', 3),
  (1219, 357, 'A car travels 75 m in 5 s. Find speed.', 'text', 1, 'v = s / t', '{"why":"Speed is proportional to distance and inversely proportional to time.","sol":"Step 1: s = 75 m, t = 5 s\nStep 2: v = 75 ÷ 5\nStep 3: v = 15 m/s","steps":["Step 1: s = 75 m, t = 5 s","Step 2: v = 75 ÷ 5","Step 3: v = 15 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Speed"}', 4),
  (1220, 357, 'A train covers 900 m in 30 s. Find speed.', 'text', 1, 'distance ÷ time', '{"why":"Speed measures how quickly distance is covered.","sol":"Step 1: s = 900 m, t = 30 s\nStep 2: v = 900 ÷ 30\nStep 3: v = 30 m/s","steps":["Step 1: s = 900 m, t = 30 s","Step 2: v = 900 ÷ 30","Step 3: v = 30 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Speed"}', 5),
  (1221, 357, 'A car covers 1.2 km in 60 s. Find speed in m/s.', 'text', 1, 'convert km to m first', '{"why":"Always convert distance into SI units before calculating speed.","sol":"Step 1: Convert 1.2 km → 1200 m\nStep 2: t = 60 s\nStep 3: v = 1200 ÷ 60\nStep 4: v = 20 m/s","steps":["Step 1: Convert 1.2 km → 1200 m","Step 2: t = 60 s","Step 3: v = 1200 ÷ 60","Step 4: v = 20 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Speed"}', 6),
  (1222, 358, 'A car travels 150 m in 5 s. Find its velocity.', 'text', 1, 'Use v = distance ÷ time', '{"why":"Velocity is the rate of change of displacement with time.","sol":"Step 1: Identify values → s = 150 m, t = 5 s\nStep 2: Substitute into formula → v = 150 ÷ 5\nStep 3: Calculate → v = 30 m/s","steps":["Step 1: Identify values → s = 150 m, t = 5 s","Step 2: Substitute into formula → v = 150 ÷ 5","Step 3: Calculate → v = 30 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Velocity"}', 0),
  (1223, 358, 'A runner covers 100 m in 20 s. Find velocity.', 'text', 1, 'Use v = s / t', '{"why":"Velocity tells how fast and in what direction an object moves.","sol":"Step 1: s = 100 m, t = 20 s\nStep 2: v = 100 ÷ 20\nStep 3: v = 5 m/s","steps":["Step 1: s = 100 m, t = 20 s","Step 2: v = 100 ÷ 20","Step 3: v = 5 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Velocity"}', 1),
  (1224, 358, 'A body moves with velocity 12 m/s for 8 s. Find distance covered.', 'text', 1, 'Use s = v × t', '{"why":"Distance is product of velocity and time when motion is uniform.","sol":"Step 1: v = 12 m/s, t = 8 s\nStep 2: s = 12 × 8\nStep 3: s = 96 m","steps":["Step 1: v = 12 m/s, t = 8 s","Step 2: s = 12 × 8","Step 3: s = 96 m"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Velocity"}', 2),
  (1225, 358, 'A train moves 300 m in 10 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity depends on displacement per time.","sol":"Step 1: s = 300 m, t = 10 s\nStep 2: v = 300 ÷ 10\nStep 3: v = 30 m/s","steps":["Step 1: s = 300 m, t = 10 s","Step 2: v = 300 ÷ 10","Step 3: v = 30 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Velocity"}', 3),
  (1226, 358, 'A car covers 240 m in 12 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity shows rate of motion.","sol":"Step 1: s = 240 m, t = 12 s\nStep 2: v = 240 ÷ 12\nStep 3: v = 20 m/s","steps":["Step 1: s = 240 m, t = 12 s","Step 2: v = 240 ÷ 12","Step 3: v = 20 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Velocity"}', 4),
  (1227, 358, 'A cyclist moves 60 m in 6 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity is constant motion over time.","sol":"Step 1: s = 60 m, t = 6 s\nStep 2: v = 60 ÷ 6\nStep 3: v = 10 m/s","steps":["Step 1: s = 60 m, t = 6 s","Step 2: v = 60 ÷ 6","Step 3: v = 10 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Velocity"}', 5),
  (1228, 358, 'A body travels 500 m in 25 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity is displacement per time.","sol":"Step 1: s = 500 m, t = 25 s\nStep 2: v = 500 ÷ 25\nStep 3: v = 20 m/s","steps":["Step 1: s = 500 m, t = 25 s","Step 2: v = 500 ÷ 25","Step 3: v = 20 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Velocity"}', 6),
  (1229, 358, 'A car moves at 15 m/s for 10 s. Find distance.', 'text', 1, 's = vt', '{"why":"Distance is product of velocity and time.","sol":"Step 1: v = 15 m/s, t = 10 s\nStep 2: s = 15 × 10\nStep 3: s = 150 m","steps":["Step 1: v = 15 m/s, t = 10 s","Step 2: s = 15 × 10","Step 3: s = 150 m"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q8","subject":"physics","chapter":"motion","topic":"Velocity"}', 7),
  (1230, 358, 'A runner moves 200 m in 40 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity measures how fast distance is covered.","sol":"Step 1: s = 200 m, t = 40 s\nStep 2: v = 200 ÷ 40\nStep 3: v = 5 m/s","steps":["Step 1: s = 200 m, t = 40 s","Step 2: v = 200 ÷ 40","Step 3: v = 5 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q9","subject":"physics","chapter":"motion","topic":"Velocity"}', 8),
  (1231, 358, 'A vehicle covers 360 m in 18 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity is displacement per time.","sol":"Step 1: s = 360 m, t = 18 s\nStep 2: v = 360 ÷ 18\nStep 3: v = 20 m/s","steps":["Step 1: s = 360 m, t = 18 s","Step 2: v = 360 ÷ 18","Step 3: v = 20 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q10","subject":"physics","chapter":"motion","topic":"Velocity"}', 9),
  (1232, 359, 'A car speeds up from 0 m/s to 20 m/s in 5 s. Find acceleration.', 'text', 1, 'Use a = (v - u) / t', '{"why":"Acceleration measures change in velocity per unit time.","sol":"Step 1: Identify values → u = 0 m/s, v = 20 m/s, t = 5 s\nStep 2: Substitute into formula → a = (20 - 0) / 5\nStep 3: Calculate → a = 4 m/s²","steps":["Step 1: Identify values → u = 0 m/s, v = 20 m/s, t = 5 s","Step 2: Substitute into formula → a = (20 - 0) / 5","Step 3: Calculate → a = 4 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Acceleration"}', 0),
  (1233, 359, 'A car slows from 30 m/s to 10 m/s in 5 s. Find acceleration.', 'text', 1, 'Use a = (v - u) / t', '{"why":"Negative acceleration means the object is slowing down.","sol":"Step 1: u = 30 m/s, v = 10 m/s, t = 5 s\nStep 2: a = (10 - 30) / 5\nStep 3: a = -20 / 5\nStep 4: a = -4 m/s²","steps":["Step 1: u = 30 m/s, v = 10 m/s, t = 5 s","Step 2: a = (10 - 30) / 5","Step 3: a = -20 / 5","Step 4: a = -4 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Acceleration"}', 1),
  (1234, 359, 'A bike increases speed from 5 m/s to 25 m/s in 10 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"The bike is speeding up uniformly.","sol":"Step 1: u = 5, v = 25, t = 10\nStep 2: a = (25 - 5) / 10\nStep 3: a = 20 / 10\nStep 4: a = 2 m/s²","steps":["Step 1: u = 5, v = 25, t = 10","Step 2: a = (25 - 5) / 10","Step 3: a = 20 / 10","Step 4: a = 2 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Acceleration"}', 2),
  (1235, 359, 'A train slows from 40 m/s to 20 m/s in 8 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"The train is decelerating.","sol":"Step 1: u = 40, v = 20, t = 8\nStep 2: a = (20 - 40) / 8\nStep 3: a = -20 / 8\nStep 4: a = -2.5 m/s²","steps":["Step 1: u = 40, v = 20, t = 8","Step 2: a = (20 - 40) / 8","Step 3: a = -20 / 8","Step 4: a = -2.5 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Acceleration"}', 3),
  (1236, 359, 'A car accelerates from 10 m/s to 30 m/s in 4 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Speed increases steadily over time.","sol":"Step 1: u = 10, v = 30, t = 4\nStep 2: a = (30 - 10) / 4\nStep 3: a = 20 / 4\nStep 4: a = 5 m/s²","steps":["Step 1: u = 10, v = 30, t = 4","Step 2: a = (30 - 10) / 4","Step 3: a = 20 / 4","Step 4: a = 5 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Acceleration"}', 4),
  (1237, 359, 'A body slows from 50 m/s to 10 m/s in 8 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Large negative acceleration shows rapid slowing.","sol":"Step 1: u = 50, v = 10, t = 8\nStep 2: a = (10 - 50) / 8\nStep 3: a = -40 / 8\nStep 4: a = -5 m/s²","steps":["Step 1: u = 50, v = 10, t = 8","Step 2: a = (10 - 50) / 8","Step 3: a = -40 / 8","Step 4: a = -5 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Acceleration"}', 5),
  (1238, 359, 'A motorcycle increases speed from 12 m/s to 24 m/s in 6 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Acceleration is constant during motion.","sol":"Step 1: u = 12, v = 24, t = 6\nStep 2: a = (24 - 12) / 6\nStep 3: a = 12 / 6\nStep 4: a = 2 m/s²","steps":["Step 1: u = 12, v = 24, t = 6","Step 2: a = (24 - 12) / 6","Step 3: a = 12 / 6","Step 4: a = 2 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Acceleration"}', 6),
  (1239, 359, 'A bus slows from 60 m/s to 30 m/s in 10 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Bus is decelerating uniformly.","sol":"Step 1: u = 60, v = 30, t = 10\nStep 2: a = (30 - 60) / 10\nStep 3: a = -30 / 10\nStep 4: a = -3 m/s²","steps":["Step 1: u = 60, v = 30, t = 10","Step 2: a = (30 - 60) / 10","Step 3: a = -30 / 10","Step 4: a = -3 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q8","subject":"physics","chapter":"motion","topic":"Acceleration"}', 7),
  (1240, 359, 'A car increases speed from 8 m/s to 32 m/s in 12 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Speed increases steadily.","sol":"Step 1: u = 8, v = 32, t = 12\nStep 2: a = (32 - 8) / 12\nStep 3: a = 24 / 12\nStep 4: a = 2 m/s²","steps":["Step 1: u = 8, v = 32, t = 12","Step 2: a = (32 - 8) / 12","Step 3: a = 24 / 12","Step 4: a = 2 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q9","subject":"physics","chapter":"motion","topic":"Acceleration"}', 8),
  (1241, 359, 'A train slows from 70 m/s to 40 m/s in 15 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Train slows down steadily.","sol":"Step 1: u = 70, v = 40, t = 15\nStep 2: a = (40 - 70) / 15\nStep 3: a = -30 / 15\nStep 4: a = -2 m/s²","steps":["Step 1: u = 70, v = 40, t = 15","Step 2: a = (40 - 70) / 15","Step 3: a = -30 / 15","Step 4: a = -2 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q10","subject":"physics","chapter":"motion","topic":"Acceleration"}', 9),
  (1242, 359, 'A car goes from 15 m/s to 45 m/s in 6 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Car gains speed quickly.","sol":"Step 1: u = 15, v = 45, t = 6\nStep 2: a = (45 - 15) / 6\nStep 3: a = 30 / 6\nStep 4: a = 5 m/s²","steps":["Step 1: u = 15, v = 45, t = 6","Step 2: a = (45 - 15) / 6","Step 3: a = 30 / 6","Step 4: a = 5 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q11","subject":"physics","chapter":"motion","topic":"Acceleration"}', 10),
  (1243, 359, 'A vehicle slows from 25 m/s to 5 m/s in 5 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Vehicle is slowing down steadily.","sol":"Step 1: u = 25, v = 5, t = 5\nStep 2: a = (5 - 25) / 5\nStep 3: a = -20 / 5\nStep 4: a = -4 m/s²","steps":["Step 1: u = 25, v = 5, t = 5","Step 2: a = (5 - 25) / 5","Step 3: a = -20 / 5","Step 4: a = -4 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q12","subject":"physics","chapter":"motion","topic":"Acceleration"}', 11),
  (1244, 360, 'A body starts from rest and accelerates at 2 m/s² for 6 s. Find final velocity.', 'text', 1, 'Use v = u + at', '{"why":"Acceleration increases velocity over time from rest.","sol":"Step 1: Identify values → u = 0 m/s, a = 2 m/s², t = 6 s\nStep 2: Substitute → v = 0 + (2 × 6)\nStep 3: Multiply → v = 12 m/s","steps":["Step 1: Identify values → u = 0 m/s, a = 2 m/s², t = 6 s","Step 2: Substitute → v = 0 + (2 × 6)","Step 3: Multiply → v = 12 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 0),
  (1245, 360, 'A car moves with u = 5 m/s, a = 3 m/s², t = 4 s. Find final velocity.', 'text', 1, 'Use v = u + at', '{"why":"Acceleration adds to initial velocity over time.","sol":"Step 1: Identify values → u = 5, a = 3, t = 4\nStep 2: Multiply → a × t = 12\nStep 3: Add → v = 5 + 12 = 17 m/s","steps":["Step 1: Identify values → u = 5, a = 3, t = 4","Step 2: Multiply → a × t = 12","Step 3: Add → v = 5 + 12 = 17 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 1),
  (1246, 360, 'A body has u = 20 m/s, a = -2 m/s², t = 5 s. Find final velocity.', 'text', 1, 'Negative acceleration means deceleration', '{"why":"Negative acceleration reduces velocity over time.","sol":"Step 1: u = 20, a = -2, t = 5\nStep 2: Multiply → -2 × 5 = -10\nStep 3: v = 20 - 10 = 10 m/s","steps":["Step 1: u = 20, a = -2, t = 5","Step 2: Multiply → -2 × 5 = -10","Step 3: v = 20 - 10 = 10 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 2),
  (1247, 360, 'A body has u = 0 m/s, a = 4 m/s², t = 3 s. Find displacement.', 'text', 1, 'Use s = ut + 1/2 at²', '{"why":"Displacement increases as object accelerates from rest.","sol":"Step 1: u = 0, a = 4, t = 3\nStep 2: ut = 0\nStep 3: t² = 9\nStep 4: s = 1/2 × 4 × 9\nStep 5: s = 2 × 9 = 18 m","steps":["Step 1: u = 0, a = 4, t = 3","Step 2: ut = 0","Step 3: t² = 9","Step 4: s = 1/2 × 4 × 9","Step 5: s = 2 × 9 = 18 m"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 3),
  (1248, 360, 'A body moves with u = 8 m/s, a = 2 m/s², t = 5 s. Find displacement.', 'text', 1, 'Use s = ut + 1/2 at²', '{"why":"Displacement is total distance covered under acceleration.","sol":"Step 1: ut = 8 × 5 = 40\nStep 2: t² = 25\nStep 3: 1/2 × 2 × 25 = 25\nStep 4: s = 40 + 25 = 65 m","steps":["Step 1: ut = 8 × 5 = 40","Step 2: t² = 25","Step 3: 1/2 × 2 × 25 = 25","Step 4: s = 40 + 25 = 65 m"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 4),
  (1249, 360, 'A body has u = 10 m/s, v = 30 m/s, a = 4 m/s². Find time.', 'text', 1, 'Use v = u + at', '{"why":"Time is found from change in velocity divided by acceleration.","sol":"Step 1: v = 30, u = 10, a = 4\nStep 2: v - u = 20\nStep 3: t = 20 / 4\nStep 4: t = 5 s","steps":["Step 1: v = 30, u = 10, a = 4","Step 2: v - u = 20","Step 3: t = 20 / 4","Step 4: t = 5 s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 5),
  (1250, 360, 'A body has u = 4 m/s, v = 20 m/s, s = 24 m. Find acceleration.', 'text', 1, 'Use v² = u² + 2as', '{"why":"This equation links velocity change with displacement and acceleration.","sol":"Step 1: 20² = 400\nStep 2: 4² = 16\nStep 3: 400 = 16 + 2a(24)\nStep 4: 400 - 16 = 384\nStep 5: 384 = 48a\nStep 6: a = 8 m/s²","steps":["Step 1: 20² = 400","Step 2: 4² = 16","Step 3: 400 = 16 + 2a(24)","Step 4: 400 - 16 = 384","Step 5: 384 = 48a","Step 6: a = 8 m/s²"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 6);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (1251, 360, 'A body has u = 15 m/s, v = 5 m/s, s = 20 m. Find acceleration.', 'text', 1, 'Use v² = u² + 2as', '{"why":"Negative acceleration means the object is slowing down.","sol":"Step 1: 5² = 25\nStep 2: 15² = 225\nStep 3: 25 = 225 + 2a(20)\nStep 4: 25 - 225 = 40a\nStep 5: -200 = 40a\nStep 6: a = -5 m/s²","steps":["Step 1: 5² = 25","Step 2: 15² = 225","Step 3: 25 = 225 + 2a(20)","Step 4: 25 - 225 = 40a","Step 5: -200 = 40a","Step 6: a = -5 m/s²"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q8","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 7),
  (1252, 360, 'A body starts from rest and travels 50 m in 5 s. Find acceleration.', 'text', 1, 'Use s = ut + 1/2 at²', '{"why":"Used when initial velocity is zero.","sol":"Step 1: u = 0, s = 50, t = 5\nStep 2: s = 1/2 a t²\nStep 3: 50 = 1/2 a × 25\nStep 4: 50 = 12.5a\nStep 5: a = 4 m/s²","steps":["Step 1: u = 0, s = 50, t = 5","Step 2: s = 1/2 a t²","Step 3: 50 = 1/2 a × 25","Step 4: 50 = 12.5a","Step 5: a = 4 m/s²"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q9","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 8),
  (1253, 360, 'A body has u = 6 m/s, a = 2 m/s², t = 8 s. Find final velocity.', 'text', 1, 'Use v = u + at', '{"why":"Final velocity depends on initial velocity plus acceleration effect.","sol":"Step 1: a × t = 16\nStep 2: v = 6 + 16\nStep 3: v = 22 m/s","steps":["Step 1: a × t = 16","Step 2: v = 6 + 16","Step 3: v = 22 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q10","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 9),
  (1254, 360, 'A car starts from rest and accelerates at 3 m/s² for 5 s. Find final velocity.', 'text', 1, 'Use v = u + at', '{"why":"Acceleration increases velocity over time, so final velocity depends on initial velocity plus change due to acceleration.","sol":"Step 1: Identify values → u = 0 m/s, a = 3 m/s², t = 5 s\nStep 2: Substitute into formula → v = 0 + (3 × 5)\nStep 3: Multiply → v = 15 m/s","steps":["Step 1: Identify values → u = 0 m/s, a = 3 m/s², t = 5 s","Step 2: Substitute into formula → v = 0 + (3 × 5)","Step 3: Multiply → v = 15 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q11","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 10),
  (1255, 360, 'A body moves with u = 10 m/s, a = 2 m/s², t = 4 s. Find displacement.', 'text', 1, 'Use s = ut + 1/2 at²', '{"why":"Displacement under acceleration includes both initial motion and extra distance due to speeding up.","sol":"Step 1: Identify values → u = 10 m/s, a = 2 m/s², t = 4 s\nStep 2: Calculate first term → ut = 10 × 4 = 40\nStep 3: Calculate second term → 1/2 × 2 × 4²\nStep 4: Square time → 4² = 16\nStep 5: Multiply → 1/2 × 2 × 16 = 16\nStep 6: Add both terms → 40 + 16 = 56 m","steps":["Step 1: Identify values → u = 10 m/s, a = 2 m/s², t = 4 s","Step 2: Calculate first term → ut = 10 × 4 = 40","Step 3: Calculate second term → 1/2 × 2 × 4²","Step 4: Square time → 4² = 16","Step 5: Multiply → 1/2 × 2 × 16 = 16","Step 6: Add both terms → 40 + 16 = 56 m"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q12","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 11),
  (1256, 360, 'When do we use v² = u² + 2as?', 'text', 1, 'no time given', '{"why":"This equation is used when you need to relate velocity, acceleration, and displacement without involving time.","sol":"Step 1: Identify key concept: Define the required principles for Equations of Motion.\nStep 2: Apply governing rule: This equation is used when you need to relate velocity, acceleration, and displacement without involving time.\nStep 3: State the final conclusion: When time is not given in the problem.","steps":["Step 1: Identify key concept: Define the required principles for Equations of Motion.","Step 2: Apply governing rule: This equation is used when you need to relate velocity, acceleration, and displacement without involving time.","Step 3: State the final conclusion: When time is not given in the problem."],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q13","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 12),
  (1257, 361, 'What is the role of friction when walking?', 'text', 1, 'grip between surfaces', '{"why":"Friction acts opposite to slipping and allows the foot to push against the ground, enabling forward motion.","sol":"Step 1: Identify key concept: Define the required principles for Friction.\nStep 2: Apply governing rule: Friction acts opposite to slipping and allows the foot to push against the ground, enabling forward motion.\nStep 3: State the final conclusion: It provides grip between shoe and ground, preventing slipping and allowing forward movement.","steps":["Step 1: Identify key concept: Define the required principles for Friction.","Step 2: Apply governing rule: Friction acts opposite to slipping and allows the foot to push against the ground, enabling forward motion.","Step 3: State the final conclusion: It provides grip between shoe and ground, preventing slipping and allowing forward movement."],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q1","subject":"physics","chapter":"forces","topic":"Friction"}', 0),
  (1258, 361, 'Why do smooth surfaces have less friction?', 'text', 1, 'surface irregularities', '{"why":"Friction is caused by microscopic bumps on surfaces. Smoother surfaces reduce interlocking between these bumps.","sol":"Step 1: Identify key concept: Define the required principles for Friction.\nStep 2: Apply governing rule: Friction is caused by microscopic bumps on surfaces. Smoother surfaces reduce interlocking between these bumps.\nStep 3: State the final conclusion: Because they have fewer irregularities, so surfaces slide more easily.","steps":["Step 1: Identify key concept: Define the required principles for Friction.","Step 2: Apply governing rule: Friction is caused by microscopic bumps on surfaces. Smoother surfaces reduce interlocking between these bumps.","Step 3: State the final conclusion: Because they have fewer irregularities, so surfaces slide more easily."],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q2","subject":"physics","chapter":"forces","topic":"Friction"}', 1),
  (1259, 361, 'Is friction always bad? Explain.', 'text', 1, 'useful and harmful effects', '{"why":"Friction is both useful (movement control) and harmful (wear and energy loss), depending on the situation.","sol":"Step 1: Identify key concept: Define the required principles for Friction.\nStep 2: Apply governing rule: Friction is both useful (movement control) and harmful (wear and energy loss), depending on the situation.\nStep 3: State the final conclusion: No, friction is necessary for walking, braking, writing, and many daily activities.","steps":["Step 1: Identify key concept: Define the required principles for Friction.","Step 2: Apply governing rule: Friction is both useful (movement control) and harmful (wear and energy loss), depending on the situation.","Step 3: State the final conclusion: No, friction is necessary for walking, braking, writing, and many daily activities."],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q3","subject":"physics","chapter":"forces","topic":"Friction"}', 2),
  (1260, 361, 'A force of 50 N is applied to move a box, and friction force is 20 N. Find the resultant force.', 'text', 1, 'net force = applied force − friction', '{"why":"Friction opposes motion, reducing the effective force.","sol":"Step 1: Identify values → applied force = 50 N, friction = 20 N\nStep 2: Apply formula → F_net = 50 − 20\nStep 3: Calculate → F_net = 30 N","steps":["Step 1: Identify values → applied force = 50 N, friction = 20 N","Step 2: Apply formula → F_net = 50 − 20","Step 3: Calculate → F_net = 30 N"],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q4","subject":"physics","chapter":"forces","topic":"Friction"}', 3),
  (1261, 361, 'A 10 kg object is pulled with a force of 15 N against friction. Will it move?', 'text', 1, 'compare forces', '{"why":"An object moves only when applied force exceeds friction.","sol":"Step 1: Identify applied force = 15 N\nStep 2: Compare with friction (assume friction = 15 N threshold)\nStep 3: If equal or less → no acceleration\nStep 4: Conclusion → object is just about to move or stays at rest","steps":["Step 1: Identify applied force = 15 N","Step 2: Compare with friction (assume friction = 15 N threshold)","Step 3: If equal or less → no acceleration","Step 4: Conclusion → object is just about to move or stays at rest"],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q5","subject":"physics","chapter":"forces","topic":"Friction"}', 4),
  (1262, 361, 'A box is pushed with 25 N and friction is 10 N. Find net force and motion direction.', 'text', 1, 'net force = difference', '{"why":"Net force determines both magnitude and direction of motion.","sol":"Step 1: Applied force = 25 N, friction = 10 N\nStep 2: F_net = 25 − 10\nStep 3: F_net = 15 N\nStep 4: Direction is same as applied force","steps":["Step 1: Applied force = 25 N, friction = 10 N","Step 2: F_net = 25 − 10","Step 3: F_net = 15 N","Step 4: Direction is same as applied force"],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q6","subject":"physics","chapter":"forces","topic":"Friction"}', 5),
  (1263, 361, 'A surface has friction of 6 N. A force of 6 N is applied. What happens?', 'text', 1, 'balanced forces', '{"why":"When forces are balanced, there is no change in motion.","sol":"Step 1: Applied = 6 N, friction = 6 N\nStep 2: F_net = 6 − 6\nStep 3: F_net = 0 N\nStep 4: No acceleration occurs","steps":["Step 1: Applied = 6 N, friction = 6 N","Step 2: F_net = 6 − 6","Step 3: F_net = 0 N","Step 4: No acceleration occurs"],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q7","subject":"physics","chapter":"forces","topic":"Friction"}', 6),
  (1264, 361, 'A 5 kg object is pushed with 40 N and friction is 15 N. Find acceleration (take g not needed).', 'text', 1, 'F = ma and net force first', '{"why":"Acceleration depends on net force after friction is considered.","sol":"Step 1: Find net force → 40 − 15 = 25 N\nStep 2: Use F = ma\nStep 3: a = F/m = 25/5\nStep 4: a = 5 m/s²","steps":["Step 1: Find net force → 40 − 15 = 25 N","Step 2: Use F = ma","Step 3: a = F/m = 25/5","Step 4: a = 5 m/s²"],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q8","subject":"physics","chapter":"forces","topic":"Friction"}', 7),
  (1265, 362, 'A mass of 8 kg is hanging on a rope. Find its weight.', 'text', 1, 'Use W = mg', '{"why":"Weight is the gravitational force acting on a mass.","sol":"Step 1: Identify values → m = 8 kg, g = 10 m/s²\nStep 2: Substitute → W = 8 × 10\nStep 3: Multiply → W = 80 N","steps":["Step 1: Identify values → m = 8 kg, g = 10 m/s²","Step 2: Substitute → W = 8 × 10","Step 3: Multiply → W = 80 N"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q1","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 0),
  (1266, 362, 'What happens to weight on the Moon?', 'text', 1, 'gravity is weaker', '{"why":"Mass stays constant, but weight changes because it depends on gravitational field strength.","sol":"Step 1: Identify key concept: Define the required principles for Tension & Weight.\nStep 2: Apply governing rule: Mass stays constant, but weight changes because it depends on gravitational field strength.\nStep 3: State the final conclusion: Weight decreases because gravitational field strength is lower.","steps":["Step 1: Identify key concept: Define the required principles for Tension & Weight.","Step 2: Apply governing rule: Mass stays constant, but weight changes because it depends on gravitational field strength.","Step 3: State the final conclusion: Weight decreases because gravitational field strength is lower."],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q2","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 1),
  (1267, 362, 'What direction does tension act?', 'text', 1, 'along rope', '{"why":"Tension is a pulling force transmitted through a string, rope, or cable.","sol":"Step 1: Identify key concept: Define the required principles for Tension & Weight.\nStep 2: Apply governing rule: Tension is a pulling force transmitted through a string, rope, or cable.\nStep 3: State the final conclusion: Along the rope, always pulling away from the object.","steps":["Step 1: Identify key concept: Define the required principles for Tension & Weight.","Step 2: Apply governing rule: Tension is a pulling force transmitted through a string, rope, or cable.","Step 3: State the final conclusion: Along the rope, always pulling away from the object."],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q3","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 2),
  (1268, 362, 'A 5 kg object is on Earth. Find its weight.', 'text', 1, 'W = mg', '{"why":"Weight increases directly with mass.","sol":"Step 1: m = 5 kg, g = 10 m/s²\nStep 2: W = 5 × 10\nStep 3: W = 50 N","steps":["Step 1: m = 5 kg, g = 10 m/s²","Step 2: W = 5 × 10","Step 3: W = 50 N"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q4","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 3),
  (1269, 362, 'A 12 kg object is lifted on Earth. Find its weight.', 'text', 1, 'W = mg', '{"why":"Weight is the force due to gravity acting on a mass.","sol":"Step 1: m = 12 kg, g = 10 m/s²\nStep 2: W = 12 × 10\nStep 3: W = 120 N","steps":["Step 1: m = 12 kg, g = 10 m/s²","Step 2: W = 12 × 10","Step 3: W = 120 N"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q5","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 4),
  (1270, 362, 'A 3 kg object is on the Moon where g = 1.6 m/s². Find its weight.', 'text', 1, 'use W = mg', '{"why":"Weight depends on gravitational field strength.","sol":"Step 1: m = 3 kg, g = 1.6 m/s²\nStep 2: W = 3 × 1.6\nStep 3: W = 4.8 N","steps":["Step 1: m = 3 kg, g = 1.6 m/s²","Step 2: W = 3 × 1.6","Step 3: W = 4.8 N"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q6","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 5),
  (1271, 362, 'A 6 kg object experiences a force of 60 N. Find acceleration.', 'text', 1, 'Use F = ma', '{"why":"Acceleration depends on force and mass.","sol":"Step 1: F = 60 N, m = 6 kg\nStep 2: a = F / m\nStep 3: a = 60 / 6\nStep 4: a = 10 m/s²","steps":["Step 1: F = 60 N, m = 6 kg","Step 2: a = F / m","Step 3: a = 60 / 6","Step 4: a = 10 m/s²"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q7","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 6),
  (1272, 362, 'A 10 kg object has weight 100 N. Find gravitational field strength.', 'text', 1, 'g = W / m', '{"why":"Gravitational field strength is weight per unit mass.","sol":"Step 1: W = 100 N, m = 10 kg\nStep 2: g = 100 / 10\nStep 3: g = 10 m/s²","steps":["Step 1: W = 100 N, m = 10 kg","Step 2: g = 100 / 10","Step 3: g = 10 m/s²"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q8","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 7),
  (1273, 362, 'Why do objects fall towards Earth?', 'text', 1, 'attractive force', '{"why":"Gravity pulls all objects with mass toward the center of the Earth.","sol":"Step 1: Identify key concept: Define the required principles for Tension & Weight.\nStep 2: Apply governing rule: Gravity pulls all objects with mass toward the center of the Earth.\nStep 3: State the final conclusion: Because Earth exerts a gravitational force on all objects.","steps":["Step 1: Identify key concept: Define the required principles for Tension & Weight.","Step 2: Apply governing rule: Gravity pulls all objects with mass toward the center of the Earth.","Step 3: State the final conclusion: Because Earth exerts a gravitational force on all objects."],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q9","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 8),
  (1274, 362, 'A 2 kg object is taken to a planet where g = 5 m/s². Find its weight.', 'text', 1, 'W = mg', '{"why":"Weight changes with gravitational field strength.","sol":"Step 1: m = 2 kg, g = 5 m/s²\nStep 2: W = 2 × 5\nStep 3: W = 10 N","steps":["Step 1: m = 2 kg, g = 5 m/s²","Step 2: W = 2 × 5","Step 3: W = 10 N"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q10","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 9),
  (1275, 363, 'What force keeps a car moving in a circular path?', 'text', 1, 'towards centre', '{"why":"Friction between the tyres and the road acts towards the centre of the circle, keeping the car in circular motion.","sol":"Step 1: Identify key concept: Define the required principles for Circular Motion.\nStep 2: Apply governing rule: Friction between the tyres and the road acts towards the centre of the circle, keeping the car in circular motion.\nStep 3: State the final conclusion: Friction provides centripetal force.","steps":["Step 1: Identify key concept: Define the required principles for Circular Motion.","Step 2: Apply governing rule: Friction between the tyres and the road acts towards the centre of the circle, keeping the car in circular motion.","Step 3: State the final conclusion: Friction provides centripetal force."],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q1","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 0),
  (1276, 363, 'What provides centripetal force for a satellite?', 'text', 1, 'Earth attraction', '{"why":"The gravitational force between Earth and the satellite acts as the centripetal force that keeps it in orbit.","sol":"Step 1: Identify key concept: Define the required principles for Circular Motion.\nStep 2: Apply governing rule: The gravitational force between Earth and the satellite acts as the centripetal force that keeps it in orbit.\nStep 3: State the final conclusion: Gravity.","steps":["Step 1: Identify key concept: Define the required principles for Circular Motion.","Step 2: Apply governing rule: The gravitational force between Earth and the satellite acts as the centripetal force that keeps it in orbit.","Step 3: State the final conclusion: Gravity."],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q2","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 1),
  (1277, 363, 'Why are roads banked on curves?', 'text', 1, 'safe turning', '{"why":"Banking provides an additional component of normal reaction force towards the centre, reducing dependence on friction.","sol":"Step 1: Identify key concept: Define the required principles for Circular Motion.\nStep 2: Apply governing rule: Banking provides an additional component of normal reaction force towards the centre, reducing dependence on friction.\nStep 3: State the final conclusion: To reduce reliance on friction and help vehicles turn safely at higher speeds.","steps":["Step 1: Identify key concept: Define the required principles for Circular Motion.","Step 2: Apply governing rule: Banking provides an additional component of normal reaction force towards the centre, reducing dependence on friction.","Step 3: State the final conclusion: To reduce reliance on friction and help vehicles turn safely at higher speeds."],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q3","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 2),
  (1278, 363, 'What happens if a string holding a rotating stone breaks?', 'text', 1, 'inertia', '{"why":"When the centripetal force is removed, the stone continues in the direction it was moving at that instant.","sol":"Step 1: Identify key concept: Define the required principles for Circular Motion.\nStep 2: Apply governing rule: When the centripetal force is removed, the stone continues in the direction it was moving at that instant.\nStep 3: State the final conclusion: The stone moves in a straight line due to inertia.","steps":["Step 1: Identify key concept: Define the required principles for Circular Motion.","Step 2: Apply governing rule: When the centripetal force is removed, the stone continues in the direction it was moving at that instant.","Step 3: State the final conclusion: The stone moves in a straight line due to inertia."],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q4","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 3),
  (1279, 363, 'A car moves in a circle of radius 10 m at a speed of 5 m/s. Find centripetal acceleration.', 'text', 1, 'use a = v²/r', '{"why":"Centripetal acceleration depends on speed and radius of the circular path.","sol":"Step 1: Identify values → v = 5 m/s, r = 10 m\nStep 2: Apply formula → a = v² / r\nStep 3: Square velocity → 5² = 25\nStep 4: Substitute → a = 25 / 10\nStep 5: Calculate → a = 2.5 m/s²","steps":["Step 1: Identify values → v = 5 m/s, r = 10 m","Step 2: Apply formula → a = v² / r","Step 3: Square velocity → 5² = 25","Step 4: Substitute → a = 25 / 10","Step 5: Calculate → a = 2.5 m/s²"],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q5","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 4),
  (1280, 363, 'A stone of mass 2 kg moves in a circle of radius 4 m at speed 3 m/s. Find centripetal force.', 'text', 1, 'use F = mv²/r', '{"why":"Centripetal force increases with mass and speed, and decreases with radius.","sol":"Step 1: m = 2 kg, v = 3 m/s, r = 4 m\nStep 2: Square velocity → 3² = 9\nStep 3: Apply formula → F = (2 × 9) / 4\nStep 4: Multiply → F = 18 / 4\nStep 5: Final answer → F = 4.5 N","steps":["Step 1: m = 2 kg, v = 3 m/s, r = 4 m","Step 2: Square velocity → 3² = 9","Step 3: Apply formula → F = (2 × 9) / 4","Step 4: Multiply → F = 18 / 4","Step 5: Final answer → F = 4.5 N"],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q6","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 5),
  (1281, 363, 'A satellite orbits Earth at constant speed. If gravity is 800 N, what force keeps it in orbit?', 'text', 1, 'centripetal = gravity', '{"why":"For satellites, gravity alone provides the centripetal force.","sol":"Step 1: Identify forces acting → gravity acts inward\nStep 2: Recognize circular motion condition\nStep 3: Centripetal force equals gravitational force\nStep 4: Therefore F = 800 N","steps":["Step 1: Identify forces acting → gravity acts inward","Step 2: Recognize circular motion condition","Step 3: Centripetal force equals gravitational force","Step 4: Therefore F = 800 N"],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q7","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 6),
  (1282, 363, 'Why does an object in circular motion need a force?', 'text', 1, 'changing direction', '{"why":"Even if speed is constant, velocity changes due to continuous change in direction, requiring centripetal force.","sol":"Step 1: Identify key concept: Define the required principles for Circular Motion.\nStep 2: Apply governing rule: Even if speed is constant, velocity changes due to continuous change in direction, requiring centripetal force.\nStep 3: State the final conclusion: Because its direction is constantly changing.","steps":["Step 1: Identify key concept: Define the required principles for Circular Motion.","Step 2: Apply governing rule: Even if speed is constant, velocity changes due to continuous change in direction, requiring centripetal force.","Step 3: State the final conclusion: Because its direction is constantly changing."],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q8","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 7),
  (1283, 364, 'What is the value of g on Earth?', 'text', 1, 'acceleration due to gravity', '{"why":"The standard value of gravitational acceleration on Earth is approximately 9.8 m/s², often rounded to 10 m/s² in basic calculations.","sol":"Step 1: Identify key concept: Define the required principles for Gravitation.\nStep 2: Apply governing rule: The standard value of gravitational acceleration on Earth is approximately 9.8 m/s², often rounded to 10 m/s² in basic calculations.\nStep 3: State the final conclusion: 10 m/s² (approx)","steps":["Step 1: Identify key concept: Define the required principles for Gravitation.","Step 2: Apply governing rule: The standard value of gravitational acceleration on Earth is approximately 9.8 m/s², often rounded to 10 m/s² in basic calculations.","Step 3: State the final conclusion: 10 m/s² (approx)"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q1","subject":"physics","chapter":"forces","topic":"Gravitation"}', 0),
  (1284, 364, 'What happens to gravitational force when distance increases?', 'text', 1, 'inverse square law', '{"why":"Gravitational force is inversely proportional to the square of the distance between two masses, meaning it becomes weaker as distance increases.","sol":"Step 1: Identify key concept: Define the required principles for Gravitation.\nStep 2: Apply governing rule: Gravitational force is inversely proportional to the square of the distance between two masses, meaning it becomes weaker as distance increases.\nStep 3: State the final conclusion: It decreases rapidly (inverse square law).","steps":["Step 1: Identify key concept: Define the required principles for Gravitation.","Step 2: Apply governing rule: Gravitational force is inversely proportional to the square of the distance between two masses, meaning it becomes weaker as distance increases.","Step 3: State the final conclusion: It decreases rapidly (inverse square law)."],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q2","subject":"physics","chapter":"forces","topic":"Gravitation"}', 1),
  (1285, 364, 'Is gravity only on Earth? Explain.', 'text', 1, 'universal force', '{"why":"Gravity is a universal force that attracts all objects with mass, not just those on Earth.","sol":"Step 1: Identify key concept: Define the required principles for Gravitation.\nStep 2: Apply governing rule: Gravity is a universal force that attracts all objects with mass, not just those on Earth.\nStep 3: State the final conclusion: No, gravity exists between all objects with mass in the universe.","steps":["Step 1: Identify key concept: Define the required principles for Gravitation.","Step 2: Apply governing rule: Gravity is a universal force that attracts all objects with mass, not just those on Earth.","Step 3: State the final conclusion: No, gravity exists between all objects with mass in the universe."],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q3","subject":"physics","chapter":"forces","topic":"Gravitation"}', 2),
  (1286, 364, 'A mass of 2 kg is acted on by gravity. Find its weight on Earth.', 'text', 1, 'use W = mg', '{"why":"Weight is the gravitational force acting on an object.","sol":"Step 1: Identify values → m = 2 kg, g = 10 m/s²\nStep 2: Apply formula → W = m × g\nStep 3: Substitute → W = 2 × 10\nStep 4: Calculate → W = 20 N","steps":["Step 1: Identify values → m = 2 kg, g = 10 m/s²","Step 2: Apply formula → W = m × g","Step 3: Substitute → W = 2 × 10","Step 4: Calculate → W = 20 N"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q4","subject":"physics","chapter":"forces","topic":"Gravitation"}', 3),
  (1287, 364, 'A 5 kg object is on Earth. Find its weight.', 'text', 1, 'W = mg', '{"why":"Weight increases with mass.","sol":"Step 1: m = 5 kg, g = 10 m/s²\nStep 2: W = 5 × 10\nStep 3: W = 50 N","steps":["Step 1: m = 5 kg, g = 10 m/s²","Step 2: W = 5 × 10","Step 3: W = 50 N"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q5","subject":"physics","chapter":"forces","topic":"Gravitation"}', 4),
  (1288, 364, 'A 3 kg object is taken to the Moon where g = 1.6 m/s². Find weight.', 'text', 1, 'W = mg', '{"why":"Weight depends on gravitational field strength.","sol":"Step 1: m = 3 kg, g = 1.6 m/s²\nStep 2: W = 3 × 1.6\nStep 3: W = 4.8 N","steps":["Step 1: m = 3 kg, g = 1.6 m/s²","Step 2: W = 3 × 1.6","Step 3: W = 4.8 N"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q6","subject":"physics","chapter":"forces","topic":"Gravitation"}', 5),
  (1289, 364, 'A planet has g = 20 m/s². Find weight of a 2 kg object.', 'text', 1, 'W = mg', '{"why":"Stronger gravity produces greater weight.","sol":"Step 1: m = 2 kg, g = 20 m/s²\nStep 2: W = 2 × 20\nStep 3: W = 40 N","steps":["Step 1: m = 2 kg, g = 20 m/s²","Step 2: W = 2 × 20","Step 3: W = 40 N"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q7","subject":"physics","chapter":"forces","topic":"Gravitation"}', 6),
  (1290, 364, 'Why do objects fall towards Earth?', 'text', 1, 'attractive force', '{"why":"Gravity pulls all objects with mass towards the center of Earth.","sol":"Step 1: Identify key concept: Define the required principles for Gravitation.\nStep 2: Apply governing rule: Gravity pulls all objects with mass towards the center of Earth.\nStep 3: State the final conclusion: Because Earth exerts a gravitational force on all objects.","steps":["Step 1: Identify key concept: Define the required principles for Gravitation.","Step 2: Apply governing rule: Gravity pulls all objects with mass towards the center of Earth.","Step 3: State the final conclusion: Because Earth exerts a gravitational force on all objects."],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q8","subject":"physics","chapter":"forces","topic":"Gravitation"}', 7),
  (1291, 364, 'What is the difference between mass and weight?', 'text', 1, 'gravity dependence', '{"why":"Mass is the amount of matter, while weight is the force due to gravity.","sol":"Step 1: Identify key concept: Define the required principles for Gravitation.\nStep 2: Apply governing rule: Mass is the amount of matter, while weight is the force due to gravity.\nStep 3: State the final conclusion: Mass is constant, weight depends on gravity.","steps":["Step 1: Identify key concept: Define the required principles for Gravitation.","Step 2: Apply governing rule: Mass is the amount of matter, while weight is the force due to gravity.","Step 3: State the final conclusion: Mass is constant, weight depends on gravity."],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q9","subject":"physics","chapter":"forces","topic":"Gravitation"}', 8),
  (1292, 364, 'A 4 kg object is taken from Earth (g = 10 m/s²) to a planet where g = 5 m/s². Find change in weight.', 'text', 1, 'W = mg', '{"why":"Weight decreases when gravitational field strength decreases.","sol":"Step 1: Earth weight → W₁ = 4 × 10 = 40 N\nStep 2: New weight → W₂ = 4 × 5 = 20 N\nStep 3: Change in weight → 40 - 20\nStep 4: Result → 20 N decrease","steps":["Step 1: Earth weight → W₁ = 4 × 10 = 40 N","Step 2: New weight → W₂ = 4 × 5 = 20 N","Step 3: Change in weight → 40 - 20","Step 4: Result → 20 N decrease"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q10","subject":"physics","chapter":"forces","topic":"Gravitation"}', 9),
  (1293, 365, 'State Newton’s First Law of Motion.', 'text', 1, 'inertia', '{"why":"This law is also called the law of inertia because objects resist changes in their state of motion.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: This law is also called the law of inertia because objects resist changes in their state of motion.\nStep 3: State the final conclusion: An object remains at rest or in uniform motion unless acted upon by a net external force.","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: This law is also called the law of inertia because objects resist changes in their state of motion.","Step 3: State the final conclusion: An object remains at rest or in uniform motion unless acted upon by a net external force."],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q1","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 0),
  (1294, 365, 'What is the formula for Newton’s Second Law?', 'text', 1, 'force, mass, acceleration', '{"why":"Force is directly proportional to mass and acceleration of an object.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: Force is directly proportional to mass and acceleration of an object.\nStep 3: State the final conclusion: F = ma","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: Force is directly proportional to mass and acceleration of an object.","Step 3: State the final conclusion: F = ma"],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q2","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 1),
  (1295, 365, 'Why do rockets move upward?', 'text', 1, 'action-reaction', '{"why":"Newton’s Third Law explains rocket propulsion through equal and opposite forces.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: Newton’s Third Law explains rocket propulsion through equal and opposite forces.\nStep 3: State the final conclusion: Because of action-reaction: gases are pushed downward, and the rocket is pushed upward.","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: Newton’s Third Law explains rocket propulsion through equal and opposite forces.","Step 3: State the final conclusion: Because of action-reaction: gases are pushed downward, and the rocket is pushed upward."],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q3","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 2),
  (1296, 365, 'A force of 10N acts on a mass of 2kg. Find acceleration.', 'text', 1, 'use F = ma', '{"why":"Acceleration increases when force increases or mass decreases.","sol":"Step 1: Write values → F = 10N, m = 2kg\nStep 2: Apply formula → a = F/m\nStep 3: Substitute → a = 10/2\nStep 4: Calculate → a = 5 m/s²","steps":["Step 1: Write values → F = 10N, m = 2kg","Step 2: Apply formula → a = F/m","Step 3: Substitute → a = 10/2","Step 4: Calculate → a = 5 m/s²"],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q4","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 3),
  (1297, 365, 'A 4kg object accelerates at 3 m/s². Find force.', 'text', 1, 'F = ma', '{"why":"Force depends on both mass and acceleration.","sol":"Step 1: m = 4kg, a = 3 m/s²\nStep 2: Substitute → F = 4 × 3\nStep 3: Calculate → F = 12N","steps":["Step 1: m = 4kg, a = 3 m/s²","Step 2: Substitute → F = 4 × 3","Step 3: Calculate → F = 12N"],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q5","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 4),
  (1298, 365, 'What does Newton’s Third Law state?', 'text', 1, 'action-reaction', '{"why":"Forces always occur in pairs acting on different objects.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: Forces always occur in pairs acting on different objects.\nStep 3: State the final conclusion: For every action, there is an equal and opposite reaction.","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: Forces always occur in pairs acting on different objects.","Step 3: State the final conclusion: For every action, there is an equal and opposite reaction."],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q6","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 5),
  (1299, 365, 'A 6kg object is acted on by a 12N force. Find acceleration.', 'text', 1, 'F = ma', '{"why":"Acceleration is directly proportional to force.","sol":"Step 1: F = 12N, m = 6kg\nStep 2: a = F/m\nStep 3: a = 12/6\nStep 4: a = 2 m/s²","steps":["Step 1: F = 12N, m = 6kg","Step 2: a = F/m","Step 3: a = 12/6","Step 4: a = 2 m/s²"],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q7","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 6),
  (1300, 365, 'Why do passengers move forward when a bus stops suddenly?', 'text', 1, 'inertia', '{"why":"The lower part stops with the bus, but the upper body continues moving.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: The lower part stops with the bus, but the upper body continues moving.\nStep 3: State the final conclusion: Because of inertia, their bodies continue moving forward.","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: The lower part stops with the bus, but the upper body continues moving.","Step 3: State the final conclusion: Because of inertia, their bodies continue moving forward."],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q8","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 7),
  (1301, 365, 'A force of 30N produces an acceleration of 5 m/s². Find mass.', 'text', 1, 'rearrange F = ma', '{"why":"Mass is resistance to acceleration.","sol":"Step 1: F = 30N, a = 5 m/s²\nStep 2: m = F/a\nStep 3: m = 30/5\nStep 4: m = 6kg","steps":["Step 1: F = 30N, a = 5 m/s²","Step 2: m = F/a","Step 3: m = 30/5","Step 4: m = 6kg"],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q9","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 8),
  (1302, 365, 'What is inertia?', 'text', 1, 'resistance to change', '{"why":"More mass means more inertia.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: More mass means more inertia.\nStep 3: State the final conclusion: The tendency of an object to resist changes in its state of motion.","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: More mass means more inertia.","Step 3: State the final conclusion: The tendency of an object to resist changes in its state of motion."],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q10","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 9),
  (1303, 366, 'A force of 20N moves an object 3m. Find work done.', 'text', 1, 'Use W = F × d', '{"why":"Work is done when a force causes displacement in its direction.","sol":"Step 1: Identify values → F = 20 N, d = 3 m\nStep 2: Write formula → W = F × d\nStep 3: Substitute values → W = 20 × 3\nStep 4: Calculate → W = 60 J","steps":["Step 1: Identify values → F = 20 N, d = 3 m","Step 2: Write formula → W = F × d","Step 3: Substitute values → W = 20 × 3","Step 4: Calculate → W = 60 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q1","subject":"physics","chapter":"energy","topic":"Work"}', 0),
  (1304, 366, 'Why is no work done when pushing a wall?', 'text', 1, 'no movement', '{"why":"Work requires both force and movement in the direction of the force. A wall does not move, so displacement is zero.","sol":"Step 1: Identify key concept: Define the required principles for Work.\nStep 2: Apply governing rule: Work requires both force and movement in the direction of the force. A wall does not move, so displacement is zero.\nStep 3: State the final conclusion: Because there is no displacement, so work done is zero.","steps":["Step 1: Identify key concept: Define the required principles for Work.","Step 2: Apply governing rule: Work requires both force and movement in the direction of the force. A wall does not move, so displacement is zero.","Step 3: State the final conclusion: Because there is no displacement, so work done is zero."],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q2","subject":"physics","chapter":"energy","topic":"Work"}', 1),
  (1305, 366, 'Do machines reduce total work done? Explain.', 'text', 1, 'energy conservation', '{"why":"Machines make work easier by changing force and distance, but they do not reduce total energy required due to conservation of energy.","sol":"Step 1: Identify key concept: Define the required principles for Work.\nStep 2: Apply governing rule: Machines make work easier by changing force and distance, but they do not reduce total energy required due to conservation of energy.\nStep 3: State the final conclusion: No, machines only change force and distance; total work remains the same (ignoring losses).","steps":["Step 1: Identify key concept: Define the required principles for Work.","Step 2: Apply governing rule: Machines make work easier by changing force and distance, but they do not reduce total energy required due to conservation of energy.","Step 3: State the final conclusion: No, machines only change force and distance; total work remains the same (ignoring losses)."],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q3","subject":"physics","chapter":"energy","topic":"Work"}', 2),
  (1306, 366, 'A force of 10N moves an object 6m. Find work done.', 'text', 1, 'W = F × d', '{"why":"Work increases when force or distance increases.","sol":"Step 1: F = 10 N, d = 6 m\nStep 2: W = 10 × 6\nStep 3: W = 60 J","steps":["Step 1: F = 10 N, d = 6 m","Step 2: W = 10 × 6","Step 3: W = 60 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q4","subject":"physics","chapter":"energy","topic":"Work"}', 3),
  (1307, 366, 'A force of 15N moves an object 4m. Find work done.', 'text', 1, 'W = Fd', '{"why":"Work depends directly on force and displacement.","sol":"Step 1: F = 15 N, d = 4 m\nStep 2: W = 15 × 4\nStep 3: W = 60 J","steps":["Step 1: F = 15 N, d = 4 m","Step 2: W = 15 × 4","Step 3: W = 60 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q5","subject":"physics","chapter":"energy","topic":"Work"}', 4),
  (1308, 366, 'A force of 25N moves an object 2m. Find work done.', 'text', 1, 'W = F × d', '{"why":"Work increases with force applied.","sol":"Step 1: F = 25 N, d = 2 m\nStep 2: W = 25 × 2\nStep 3: W = 50 J","steps":["Step 1: F = 25 N, d = 2 m","Step 2: W = 25 × 2","Step 3: W = 50 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q6","subject":"physics","chapter":"energy","topic":"Work"}', 5),
  (1309, 366, 'A force of 30N moves an object 5m. Find work done.', 'text', 1, 'W = Fd', '{"why":"More force or distance means more work done.","sol":"Step 1: F = 30 N, d = 5 m\nStep 2: W = 30 × 5\nStep 3: W = 150 J","steps":["Step 1: F = 30 N, d = 5 m","Step 2: W = 30 × 5","Step 3: W = 150 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q7","subject":"physics","chapter":"energy","topic":"Work"}', 6),
  (1310, 366, 'A force of 40N moves an object 1.5m. Find work done.', 'text', 1, 'W = Fd', '{"why":"Work can involve decimal distances.","sol":"Step 1: F = 40 N, d = 1.5 m\nStep 2: W = 40 × 1.5\nStep 3: W = 60 J","steps":["Step 1: F = 40 N, d = 1.5 m","Step 2: W = 40 × 1.5","Step 3: W = 60 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q8","subject":"physics","chapter":"energy","topic":"Work"}', 7),
  (1311, 366, 'A force of 12N moves an object 8m. Find work done.', 'text', 1, 'W = Fd', '{"why":"Work depends on both force and displacement.","sol":"Step 1: F = 12 N, d = 8 m\nStep 2: W = 12 × 8\nStep 3: W = 96 J","steps":["Step 1: F = 12 N, d = 8 m","Step 2: W = 12 × 8","Step 3: W = 96 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q9","subject":"physics","chapter":"energy","topic":"Work"}', 8),
  (1312, 366, 'A force of 50N moves an object 0.5m. Find work done.', 'text', 1, 'W = Fd', '{"why":"Even small distances produce work when force is large.","sol":"Step 1: F = 50 N, d = 0.5 m\nStep 2: W = 50 × 0.5\nStep 3: W = 25 J","steps":["Step 1: F = 50 N, d = 0.5 m","Step 2: W = 50 × 0.5","Step 3: W = 25 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q10","subject":"physics","chapter":"energy","topic":"Work"}', 9),
  (1313, 367, 'A machine uses 500J in 5s. Find power.', 'text', 1, 'Use P = W/t', '{"why":"Power is the rate of energy transfer per unit time.","sol":"Step 1: Identify values → W = 500 J, t = 5 s\nStep 2: Write formula → P = W / t\nStep 3: Substitute → P = 500 / 5\nStep 4: Calculate → P = 100 W","steps":["Step 1: Identify values → W = 500 J, t = 5 s","Step 2: Write formula → P = W / t","Step 3: Substitute → P = 500 / 5","Step 4: Calculate → P = 100 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q1","subject":"physics","chapter":"energy","topic":"Power"}', 0),
  (1314, 367, 'What is the unit of power?', 'text', 1, 'SI unit', '{"why":"Power is measured in watts, where 1 watt = 1 joule per second.","sol":"Step 1: Identify key concept: Define the required principles for Power.\nStep 2: Apply governing rule: Power is measured in watts, where 1 watt = 1 joule per second.\nStep 3: State the final conclusion: Watt (W)","steps":["Step 1: Identify key concept: Define the required principles for Power.","Step 2: Apply governing rule: Power is measured in watts, where 1 watt = 1 joule per second.","Step 3: State the final conclusion: Watt (W)"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q2","subject":"physics","chapter":"energy","topic":"Power"}', 1),
  (1315, 367, 'Why do power companies use high voltage transmission?', 'text', 1, 'reduce energy loss', '{"why":"Higher voltage reduces current, and since power loss in cables depends on I²R, lower current reduces energy wasted as heat.","sol":"Step 1: Identify key concept: Define the required principles for Power.\nStep 2: Apply governing rule: Higher voltage reduces current, and since power loss in cables depends on I²R, lower current reduces energy wasted as heat.\nStep 3: State the final conclusion: To reduce current and minimize energy loss (I²R losses).","steps":["Step 1: Identify key concept: Define the required principles for Power.","Step 2: Apply governing rule: Higher voltage reduces current, and since power loss in cables depends on I²R, lower current reduces energy wasted as heat.","Step 3: State the final conclusion: To reduce current and minimize energy loss (I²R losses)."],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q3","subject":"physics","chapter":"energy","topic":"Power"}', 2),
  (1316, 367, 'A device uses 1200 J of energy in 6 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power measures how quickly energy is used.","sol":"Step 1: W = 1200 J, t = 6 s\nStep 2: P = 1200 / 6\nStep 3: P = 200 W","steps":["Step 1: W = 1200 J, t = 6 s","Step 2: P = 1200 / 6","Step 3: P = 200 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q4","subject":"physics","chapter":"energy","topic":"Power"}', 3),
  (1317, 367, 'A motor does 3000 J of work in 10 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power shows energy transfer rate.","sol":"Step 1: W = 3000 J, t = 10 s\nStep 2: P = 3000 / 10\nStep 3: P = 300 W","steps":["Step 1: W = 3000 J, t = 10 s","Step 2: P = 3000 / 10","Step 3: P = 300 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q5","subject":"physics","chapter":"energy","topic":"Power"}', 4),
  (1318, 367, 'A bulb uses 600 J in 3 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Electrical devices convert energy per second.","sol":"Step 1: W = 600 J, t = 3 s\nStep 2: P = 600 / 3\nStep 3: P = 200 W","steps":["Step 1: W = 600 J, t = 3 s","Step 2: P = 600 / 3","Step 3: P = 200 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q6","subject":"physics","chapter":"energy","topic":"Power"}', 5),
  (1319, 367, 'A heater uses 4500 J in 15 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power depends on how fast energy is used.","sol":"Step 1: W = 4500 J, t = 15 s\nStep 2: P = 4500 / 15\nStep 3: P = 300 W","steps":["Step 1: W = 4500 J, t = 15 s","Step 2: P = 4500 / 15","Step 3: P = 300 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q7","subject":"physics","chapter":"energy","topic":"Power"}', 6),
  (1320, 367, 'A machine uses 9000 J in 30 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power is energy per unit time.","sol":"Step 1: W = 9000 J, t = 30 s\nStep 2: P = 9000 / 30\nStep 3: P = 300 W","steps":["Step 1: W = 9000 J, t = 30 s","Step 2: P = 9000 / 30","Step 3: P = 300 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q8","subject":"physics","chapter":"energy","topic":"Power"}', 7),
  (1321, 367, 'A motor transfers 1500 J in 5 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power is directly proportional to energy and inversely to time.","sol":"Step 1: W = 1500 J, t = 5 s\nStep 2: P = 1500 / 5\nStep 3: P = 300 W","steps":["Step 1: W = 1500 J, t = 5 s","Step 2: P = 1500 / 5","Step 3: P = 300 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q9","subject":"physics","chapter":"energy","topic":"Power"}', 8),
  (1322, 367, 'A device uses 2400 J in 8 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power tells how fast energy is used.","sol":"Step 1: W = 2400 J, t = 8 s\nStep 2: P = 2400 / 8\nStep 3: P = 300 W","steps":["Step 1: W = 2400 J, t = 8 s","Step 2: P = 2400 / 8","Step 3: P = 300 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q10","subject":"physics","chapter":"energy","topic":"Power"}', 9),
  (1323, 367, 'A generator produces 10000 J in 20 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Generators convert mechanical energy into electrical power.","sol":"Step 1: W = 10000 J, t = 20 s\nStep 2: P = 10000 / 20\nStep 3: P = 500 W","steps":["Step 1: W = 10000 J, t = 20 s","Step 2: P = 10000 / 20","Step 3: P = 500 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q11","subject":"physics","chapter":"energy","topic":"Power"}', 10),
  (1324, 368, 'What happens to energy when a car moves?', 'text', 1, 'fuel transformation', '{"why":"The fuel in the car contains chemical energy which is released during combustion and transformed into motion (kinetic energy) and heat energy due to engine friction.","sol":"Step 1: Identify key concept: Define the required principles for Energy Conversion.\nStep 2: Apply governing rule: The fuel in the car contains chemical energy which is released during combustion and transformed into motion (kinetic energy) and heat energy due to engine friction.\nStep 3: State the final conclusion: Chemical energy is converted into kinetic energy and heat.","steps":["Step 1: Identify key concept: Define the required principles for Energy Conversion.","Step 2: Apply governing rule: The fuel in the car contains chemical energy which is released during combustion and transformed into motion (kinetic energy) and heat energy due to engine friction.","Step 3: State the final conclusion: Chemical energy is converted into kinetic energy and heat."],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q1","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 0),
  (1325, 368, 'Is energy ever destroyed?', 'text', 1, 'law of conservation', '{"why":"According to the law of conservation of energy, energy cannot be created or destroyed, only transformed from one form to another.","sol":"Step 1: Identify key concept: Define the required principles for Energy Conversion.\nStep 2: Apply governing rule: According to the law of conservation of energy, energy cannot be created or destroyed, only transformed from one form to another.\nStep 3: State the final conclusion: No, energy is always conserved and only changes form.","steps":["Step 1: Identify key concept: Define the required principles for Energy Conversion.","Step 2: Apply governing rule: According to the law of conservation of energy, energy cannot be created or destroyed, only transformed from one form to another.","Step 3: State the final conclusion: No, energy is always conserved and only changes form."],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q2","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 1),
  (1326, 368, 'What energy change happens in a falling object?', 'text', 1, 'height to motion', '{"why":"As an object falls, its stored potential energy due to height is converted into kinetic energy as it gains speed.","sol":"Step 1: Identify key concept: Define the required principles for Energy Conversion.\nStep 2: Apply governing rule: As an object falls, its stored potential energy due to height is converted into kinetic energy as it gains speed.\nStep 3: State the final conclusion: Gravitational potential energy → kinetic energy","steps":["Step 1: Identify key concept: Define the required principles for Energy Conversion.","Step 2: Apply governing rule: As an object falls, its stored potential energy due to height is converted into kinetic energy as it gains speed.","Step 3: State the final conclusion: Gravitational potential energy → kinetic energy"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q3","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 2),
  (1327, 368, 'A 2 kg object is lifted to a height of 5 m. Find its potential energy (g = 10 m/s²).', 'text', 1, 'Use PE = mgh', '{"why":"Potential energy depends on mass, height, and gravitational field strength.","sol":"Step 1: Identify values → m = 2 kg, g = 10 m/s², h = 5 m\nStep 2: Substitute into formula → PE = 2 × 10 × 5\nStep 3: Multiply → PE = 100 J","steps":["Step 1: Identify values → m = 2 kg, g = 10 m/s², h = 5 m","Step 2: Substitute into formula → PE = 2 × 10 × 5","Step 3: Multiply → PE = 100 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q4","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 3),
  (1328, 368, 'A 3 kg object moves at 4 m/s. Find kinetic energy.', 'text', 1, 'Use KE = 1/2 mv²', '{"why":"Kinetic energy increases with velocity squared.","sol":"Step 1: m = 3 kg, v = 4 m/s\nStep 2: Square velocity → 4² = 16\nStep 3: Substitute → KE = 1/2 × 3 × 16\nStep 4: Multiply → KE = 24 J","steps":["Step 1: m = 3 kg, v = 4 m/s","Step 2: Square velocity → 4² = 16","Step 3: Substitute → KE = 1/2 × 3 × 16","Step 4: Multiply → KE = 24 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q5","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 4),
  (1329, 368, 'A car engine does 5000 J of work in 10 seconds. Find power.', 'text', 1, 'Use P = W/t', '{"why":"Power is the rate of energy transfer per second.","sol":"Step 1: W = 5000 J, t = 10 s\nStep 2: Substitute → P = 5000 / 10\nStep 3: Calculate → P = 500 W","steps":["Step 1: W = 5000 J, t = 10 s","Step 2: Substitute → P = 5000 / 10","Step 3: Calculate → P = 500 W"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q6","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 5),
  (1330, 368, 'A 4 kg object is lifted 3 m high. Find potential energy.', 'text', 1, 'PE = mgh', '{"why":"Higher mass or height increases potential energy.","sol":"Step 1: m = 4 kg, g = 10 m/s², h = 3 m\nStep 2: Substitute → PE = 4 × 10 × 3\nStep 3: Multiply → PE = 120 J","steps":["Step 1: m = 4 kg, g = 10 m/s², h = 3 m","Step 2: Substitute → PE = 4 × 10 × 3","Step 3: Multiply → PE = 120 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q7","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 6),
  (1331, 368, 'A 5 kg object moves at 2 m/s. Find kinetic energy.', 'text', 1, 'KE = 1/2 mv²', '{"why":"Even small velocity changes affect kinetic energy significantly.","sol":"Step 1: m = 5 kg, v = 2 m/s\nStep 2: v² = 4\nStep 3: KE = 1/2 × 5 × 4\nStep 4: KE = 10 J","steps":["Step 1: m = 5 kg, v = 2 m/s","Step 2: v² = 4","Step 3: KE = 1/2 × 5 × 4","Step 4: KE = 10 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q8","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 7),
  (1332, 368, 'A machine converts 2000 J of energy in 4 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power measures how fast energy is used or transferred.","sol":"Step 1: W = 2000 J, t = 4 s\nStep 2: P = 2000 / 4\nStep 3: P = 500 W","steps":["Step 1: W = 2000 J, t = 4 s","Step 2: P = 2000 / 4","Step 3: P = 500 W"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q9","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 8),
  (1333, 368, 'A 1 kg object falls from 10 m. Find potential energy before falling.', 'text', 1, 'PE = mgh', '{"why":"All potential energy becomes kinetic energy during fall.","sol":"Step 1: m = 1 kg, g = 10 m/s², h = 10 m\nStep 2: PE = 1 × 10 × 10\nStep 3: PE = 100 J","steps":["Step 1: m = 1 kg, g = 10 m/s², h = 10 m","Step 2: PE = 1 × 10 × 10","Step 3: PE = 100 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q10","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 9),
  (1334, 368, 'A system has 600 J of energy input and 150 J is lost as heat. Find useful energy output.', 'text', 1, 'useful = input - loss', '{"why":"Some energy is always lost, usually as heat or sound.","sol":"Step 1: Input = 600 J\nStep 2: Loss = 150 J\nStep 3: Useful = 600 - 150\nStep 4: Useful = 450 J","steps":["Step 1: Input = 600 J","Step 2: Loss = 150 J","Step 3: Useful = 600 - 150","Step 4: Useful = 450 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q11","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 10),
  (1335, 369, 'A 2kg object falls from 5m. Find total energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"mgh = 2 × 10 × 5 = 100J","steps":["Step 1: Identify the given values: mass (m) = 2kg, height (h) = 5m, and gravitational acceleration (g) ≈ 10m/s².","Step 2: Recall the formula for gravitational potential energy: PE = m × g × h.","Step 3: Substitute the known values into the equation: PE = 2 × 10 × 5.","Step 4: Calculate the final value to find the total mechanical energy: 100 Joules (100J)."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q1","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 0),
  (1336, 369, 'A 5kg object is lifted to a height of 8m. Calculate its potential energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"PE = mgh = 5 × 10 × 8 = 400J","steps":["Step 1: Identify the values: m = 5kg, h = 8m, g = 10m/s².","Step 2: Recall the formula PE = m × g × h.","Step 3: Substitute the values: PE = 5 × 10 × 8.","Step 4: Calculate the answer: 400 Joules."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q2","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 1),
  (1337, 369, 'A 4kg object moves at 6m/s. Find its kinetic energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"KE = ½mv² = ½ × 4 × 6² = 72J","steps":["Step 1: Identify the mass (4kg) and velocity (6m/s).","Step 2: Recall the formula KE = ½mv².","Step 3: Square the velocity: 6² = 36.","Step 4: Calculate: ½ × 4 × 36 = 72J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q3","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 2),
  (1338, 369, 'A car of mass 1000kg travels at 20m/s. Calculate its kinetic energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"KE = ½ × 1000 × 20² = 200000J","steps":["Step 1: Identify m = 1000kg and v = 20m/s.","Step 2: Recall KE = ½mv².","Step 3: Square the speed: 20² = 400.","Step 4: Calculate: ½ × 1000 × 400 = 200000J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q4","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 3),
  (1339, 369, 'A 10N force moves an object through 6m. Calculate the work done.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Work = Force × Distance = 10 × 6 = 60J","steps":["Step 1: Identify force = 10N and distance = 6m.","Step 2: Recall the formula Work = Force × Distance.","Step 3: Substitute the values: 10 × 6.","Step 4: Calculate the work done: 60J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q5","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 4),
  (1340, 369, 'A machine does 500J of work in 10 seconds. Calculate its power.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Power = Work ÷ Time = 500 ÷ 10 = 50W","steps":["Step 1: Identify work = 500J and time = 10s.","Step 2: Recall the formula Power = Work ÷ Time.","Step 3: Substitute the values into the formula.","Step 4: Divide 500 by 10 to obtain 50W."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q6","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 5),
  (1341, 369, 'A 3kg object is raised 15m above the ground. Find its potential energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"PE = 3 × 10 × 15 = 450J","steps":["Step 1: Identify m = 3kg, h = 15m, g = 10m/s².","Step 2: Recall PE = mgh.","Step 3: Substitute: 3 × 10 × 15.","Step 4: Calculate: 450J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q7","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 6),
  (1342, 369, 'A 6kg object moves with a speed of 5m/s. Find its kinetic energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"KE = ½ × 6 × 5² = 75J","steps":["Step 1: Identify mass and velocity.","Step 2: Recall KE = ½mv².","Step 3: Square the velocity: 5² = 25.","Step 4: Calculate: ½ × 6 × 25 = 75J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q8","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 7),
  (1343, 369, 'A 50N force pushes a box for 12m. Calculate the work done.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Work = 50 × 12 = 600J","steps":["Step 1: Identify force = 50N and distance = 12m.","Step 2: Recall Work = Force × Distance.","Step 3: Multiply the given values.","Step 4: The work done is 600J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q9","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 8),
  (1344, 369, 'A motor produces 2400J of work in 60 seconds. Find its power.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Power = 2400 ÷ 60 = 40W","steps":["Step 1: Identify work = 2400J and time = 60s.","Step 2: Recall Power = Work ÷ Time.","Step 3: Substitute the values.","Step 4: Divide 2400 by 60 to get 40W."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q10","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 9),
  (1345, 369, 'A 7kg object is placed 9m above the ground. Calculate its potential energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"PE = 7 × 10 × 9 = 630J","steps":["Step 1: Identify m = 7kg, h = 9m.","Step 2: Recall PE = mgh.","Step 3: Substitute the values using g = 10m/s².","Step 4: Calculate 630J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q11","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 10),
  (1346, 369, 'A cyclist and bicycle have a combined mass of 80kg and move at 10m/s. Calculate the kinetic energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"KE = ½ × 80 × 10² = 4000J","steps":["Step 1: Identify mass = 80kg and velocity = 10m/s.","Step 2: Recall KE = ½mv².","Step 3: Square the velocity: 10² = 100.","Step 4: Calculate: ½ × 80 × 100 = 4000J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q12","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 11),
  (1347, 369, 'A crane lifts a 200kg load by 5m. Calculate the gain in potential energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"PE = 200 × 10 × 5 = 10000J","steps":["Step 1: Identify m = 200kg and h = 5m.","Step 2: Recall PE = mgh.","Step 3: Substitute the values.","Step 4: Calculate the gain in potential energy: 10000J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q13","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 12),
  (1348, 369, 'A machine uses 1500J of energy in 30 seconds. Find its power output.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Power = 1500 ÷ 30 = 50W","steps":["Step 1: Identify work = 1500J and time = 30s.","Step 2: Recall Power = Work ÷ Time.","Step 3: Substitute the values.","Step 4: Divide 1500 by 30 to get 50W."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q14","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 13),
  (1349, 369, 'A 12N force moves an object 15m. Calculate the work done.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Work = 12 × 15 = 180J","steps":["Step 1: Identify force = 12N and distance = 15m.","Step 2: Recall Work = Force × Distance.","Step 3: Substitute the values.","Step 4: Calculate: 180J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q15","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 14),
  (1350, 370, 'A 2 kg object moves at 3 m/s. Find kinetic energy.', 'text', 1, 'Use KE = ½mv²', '{"why":"Kinetic energy depends on mass and the square of velocity.","sol":"Step 1: Identify values → m = 2 kg, v = 3 m/s\nStep 2: Substitute into formula → KE = 1/2 × 2 × 3²\nStep 3: Square velocity → 3² = 9\nStep 4: Multiply → KE = 1 × 9\nStep 5: Final answer → KE = 9 J","steps":["Step 1: Identify values → m = 2 kg, v = 3 m/s","Step 2: Substitute into formula → KE = 1/2 × 2 × 3²","Step 3: Square velocity → 3² = 9","Step 4: Multiply → KE = 1 × 9","Step 5: Final answer → KE = 9 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q1","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 0),
  (1351, 370, 'A 3 kg object is raised to a height of 4 m. Find potential energy.', 'text', 1, 'Use PE = mgh', '{"why":"Potential energy depends on mass, height, and gravity.","sol":"Step 1: Identify values → m = 3 kg, g = 10 m/s², h = 4 m\nStep 2: Substitute → PE = 3 × 10 × 4\nStep 3: Multiply → PE = 120 J","steps":["Step 1: Identify values → m = 3 kg, g = 10 m/s², h = 4 m","Step 2: Substitute → PE = 3 × 10 × 4","Step 3: Multiply → PE = 120 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q2","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 1),
  (1352, 370, 'What happens to potential energy when an object falls?', 'text', 1, 'energy conversion', '{"why":"As height decreases, potential energy is transformed into motion energy.","sol":"Step 1: Identify key concept: Define the required principles for Kinetic & Potential Energy.\nStep 2: Apply governing rule: As height decreases, potential energy is transformed into motion energy.\nStep 3: State the final conclusion: It is converted into kinetic energy.","steps":["Step 1: Identify key concept: Define the required principles for Kinetic & Potential Energy.","Step 2: Apply governing rule: As height decreases, potential energy is transformed into motion energy.","Step 3: State the final conclusion: It is converted into kinetic energy."],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q3","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 2),
  (1353, 370, 'A 5 kg object moves at 4 m/s. Find kinetic energy.', 'text', 1, 'KE = ½mv²', '{"why":"Kinetic energy increases with mass and velocity squared.","sol":"Step 1: m = 5 kg, v = 4 m/s\nStep 2: Substitute → KE = 1/2 × 5 × 4²\nStep 3: 4² = 16\nStep 4: KE = 2.5 × 16\nStep 5: KE = 40 J","steps":["Step 1: m = 5 kg, v = 4 m/s","Step 2: Substitute → KE = 1/2 × 5 × 4²","Step 3: 4² = 16","Step 4: KE = 2.5 × 16","Step 5: KE = 40 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q4","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 3),
  (1354, 370, 'A 2 kg object is lifted to 6 m. Find potential energy.', 'text', 1, 'PE = mgh', '{"why":"Higher height increases potential energy.","sol":"Step 1: m = 2 kg, g = 10, h = 6 m\nStep 2: Substitute → PE = 2 × 10 × 6\nStep 3: Calculate → PE = 120 J","steps":["Step 1: m = 2 kg, g = 10, h = 6 m","Step 2: Substitute → PE = 2 × 10 × 6","Step 3: Calculate → PE = 120 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q5","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 4),
  (1355, 370, 'A 4 kg object moves at 2 m/s. Find kinetic energy.', 'text', 1, 'KE = ½mv²', '{"why":"Kinetic energy depends on velocity squared.","sol":"Step 1: m = 4 kg, v = 2 m/s\nStep 2: Substitute → KE = 1/2 × 4 × 2²\nStep 3: 2² = 4\nStep 4: KE = 2 × 4\nStep 5: KE = 8 J","steps":["Step 1: m = 4 kg, v = 2 m/s","Step 2: Substitute → KE = 1/2 × 4 × 2²","Step 3: 2² = 4","Step 4: KE = 2 × 4","Step 5: KE = 8 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q6","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 5),
  (1356, 370, 'A 1 kg object is lifted 10 m high. Find potential energy.', 'text', 1, 'PE = mgh', '{"why":"Potential energy increases with both height and mass because more work is needed to lift an object higher in a gravitational field.","sol":"Step 1: Identify values → m = 1 kg, g = 10 m/s², h = 10 m\nStep 2: Substitute into formula → PE = 1 × 10 × 10\nStep 3: Multiply → PE = 100 J","steps":["Step 1: Identify values → m = 1 kg, g = 10 m/s², h = 10 m","Step 2: Substitute into formula → PE = 1 × 10 × 10","Step 3: Multiply → PE = 100 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q7","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 6),
  (1357, 371, 'A wave travels at 15 m/s and has frequency 3 Hz. Find wavelength.', 'text', 1, 'Use v = fλ', '{"why":"Wavelength is found by dividing wave speed by frequency.","sol":"Step 1: Identify values → v = 15 m/s, f = 3 Hz\nStep 2: Use formula → λ = v / f\nStep 3: Substitute → λ = 15 / 3\nStep 4: Calculate → λ = 5 m","steps":["Step 1: Identify values → v = 15 m/s, f = 3 Hz","Step 2: Use formula → λ = v / f","Step 3: Substitute → λ = 15 / 3","Step 4: Calculate → λ = 5 m"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Wave properties"}', 0),
  (1358, 371, 'A wave has wavelength 4 m and frequency 6 Hz. Find wave speed.', 'text', 1, 'Use v = fλ', '{"why":"Wave speed is the product of frequency and wavelength.","sol":"Step 1: Identify values → f = 6 Hz, λ = 4 m\nStep 2: Use formula → v = f × λ\nStep 3: Substitute → v = 6 × 4\nStep 4: Calculate → v = 24 m/s","steps":["Step 1: Identify values → f = 6 Hz, λ = 4 m","Step 2: Use formula → v = f × λ","Step 3: Substitute → v = 6 × 4","Step 4: Calculate → v = 24 m/s"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Wave properties"}', 1),
  (1359, 371, 'Time period is 0.5 s. Find frequency.', 'text', 1, 'f = 1/T', '{"why":"Frequency is the number of waves per second.","sol":"Step 1: Identify time period → T = 0.5 s\nStep 2: Use formula → f = 1 / T\nStep 3: Substitute → f = 1 / 0.5\nStep 4: Calculate → f = 2 Hz","steps":["Step 1: Identify time period → T = 0.5 s","Step 2: Use formula → f = 1 / T","Step 3: Substitute → f = 1 / 0.5","Step 4: Calculate → f = 2 Hz"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Wave properties"}', 2),
  (1360, 371, 'A wave has speed 40 m/s and wavelength 8 m. Find frequency.', 'text', 1, 'f = v/λ', '{"why":"Frequency equals speed divided by wavelength.","sol":"Step 1: Identify values → v = 40 m/s, λ = 8 m\nStep 2: Use formula → f = v / λ\nStep 3: Substitute → f = 40 / 8\nStep 4: Calculate → f = 5 Hz","steps":["Step 1: Identify values → v = 40 m/s, λ = 8 m","Step 2: Use formula → f = v / λ","Step 3: Substitute → f = 40 / 8","Step 4: Calculate → f = 5 Hz"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q4","subject":"physics","chapter":"waves","topic":"Wave properties"}', 3),
  (1361, 371, 'A wave has frequency 10 Hz and speed 50 m/s. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength is speed divided by frequency.","sol":"Step 1: Identify values → v = 50 m/s, f = 10 Hz\nStep 2: Apply formula → λ = v / f\nStep 3: Substitute → λ = 50 / 10\nStep 4: Calculate → λ = 5 m","steps":["Step 1: Identify values → v = 50 m/s, f = 10 Hz","Step 2: Apply formula → λ = v / f","Step 3: Substitute → λ = 50 / 10","Step 4: Calculate → λ = 5 m"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q5","subject":"physics","chapter":"waves","topic":"Wave properties"}', 4),
  (1362, 371, 'A wave takes 2 s to complete 1 cycle. Find frequency.', 'text', 1, 'T = 1/f', '{"why":"Frequency is inversely proportional to time period.","sol":"Step 1: Identify time period → T = 2 s\nStep 2: Use formula → f = 1 / T\nStep 3: Substitute → f = 1 / 2\nStep 4: Calculate → f = 0.5 Hz","steps":["Step 1: Identify time period → T = 2 s","Step 2: Use formula → f = 1 / T","Step 3: Substitute → f = 1 / 2","Step 4: Calculate → f = 0.5 Hz"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q6","subject":"physics","chapter":"waves","topic":"Wave properties"}', 5),
  (1363, 371, 'A wave has wavelength 2 m and speed 12 m/s. Find frequency.', 'text', 1, 'f = v/λ', '{"why":"Frequency is found by dividing speed by wavelength.","sol":"Step 1: Identify values → v = 12 m/s, λ = 2 m\nStep 2: Apply formula → f = v / λ\nStep 3: Substitute → f = 12 / 2\nStep 4: Calculate → f = 6 Hz","steps":["Step 1: Identify values → v = 12 m/s, λ = 2 m","Step 2: Apply formula → f = v / λ","Step 3: Substitute → f = 12 / 2","Step 4: Calculate → f = 6 Hz"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q7","subject":"physics","chapter":"waves","topic":"Wave properties"}', 6),
  (1364, 371, 'A wave has frequency 50 Hz and wavelength 0.2 m. Find speed.', 'text', 1, 'v = fλ', '{"why":"Wave speed equals frequency times wavelength.","sol":"Step 1: Identify values → f = 50 Hz, λ = 0.2 m\nStep 2: Apply formula → v = f × λ\nStep 3: Substitute → v = 50 × 0.2\nStep 4: Calculate → v = 10 m/s","steps":["Step 1: Identify values → f = 50 Hz, λ = 0.2 m","Step 2: Apply formula → v = f × λ","Step 3: Substitute → v = 50 × 0.2","Step 4: Calculate → v = 10 m/s"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q8","subject":"physics","chapter":"waves","topic":"Wave properties"}', 7),
  (1365, 371, 'A wave travels 100 m in 5 s. Find its speed.', 'text', 1, 'speed = distance/time', '{"why":"Speed is distance divided by time.","sol":"Step 1: Identify values → d = 100 m, t = 5 s\nStep 2: Use formula → v = d / t\nStep 3: Substitute → v = 100 / 5\nStep 4: Calculate → v = 20 m/s","steps":["Step 1: Identify values → d = 100 m, t = 5 s","Step 2: Use formula → v = d / t","Step 3: Substitute → v = 100 / 5","Step 4: Calculate → v = 20 m/s"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q9","subject":"physics","chapter":"waves","topic":"Wave properties"}', 8),
  (1366, 371, 'A wave has speed 30 m/s and frequency 5 Hz. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength equals speed divided by frequency.","sol":"Step 1: Identify values → v = 30 m/s, f = 5 Hz\nStep 2: Apply formula → λ = v / f\nStep 3: Substitute → λ = 30 / 5\nStep 4: Calculate → λ = 6 m","steps":["Step 1: Identify values → v = 30 m/s, f = 5 Hz","Step 2: Apply formula → λ = v / f","Step 3: Substitute → λ = 30 / 5","Step 4: Calculate → λ = 6 m"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q10","subject":"physics","chapter":"waves","topic":"Wave properties"}', 9),
  (1367, 372, 'A sound wave has frequency 200 Hz and wavelength 1.5 m. Find speed.', 'text', 1, 'Use v = fλ', '{"why":"Speed of sound is found by multiplying frequency and wavelength.","sol":"Step 1: Identify values → f = 200 Hz, λ = 1.5 m\nStep 2: Apply formula → v = fλ\nStep 3: Substitute → v = 200 × 1.5\nStep 4: Calculate → v = 300 m/s","steps":["Step 1: Identify values → f = 200 Hz, λ = 1.5 m","Step 2: Apply formula → v = fλ","Step 3: Substitute → v = 200 × 1.5","Step 4: Calculate → v = 300 m/s"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Sound waves"}', 0),
  (1368, 372, 'A sound wave has frequency 100 Hz and wavelength 2 m. Find speed.', 'text', 1, 'v = fλ', '{"why":"Wave speed depends on both frequency and wavelength.","sol":"Step 1: f = 100 Hz, λ = 2 m\nStep 2: v = fλ\nStep 3: v = 100 × 2\nStep 4: v = 200 m/s","steps":["Step 1: f = 100 Hz, λ = 2 m","Step 2: v = fλ","Step 3: v = 100 × 2","Step 4: v = 200 m/s"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Sound waves"}', 1),
  (1369, 372, 'A sound wave travels at 340 m/s and has frequency 170 Hz. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength is speed divided by frequency.","sol":"Step 1: v = 340 m/s, f = 170 Hz\nStep 2: λ = v/f\nStep 3: λ = 340/170\nStep 4: λ = 2 m","steps":["Step 1: v = 340 m/s, f = 170 Hz","Step 2: λ = v/f","Step 3: λ = 340/170","Step 4: λ = 2 m"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Sound waves"}', 2),
  (1370, 372, 'A sound wave has wavelength 0.5 m and speed 150 m/s. Find frequency.', 'text', 1, 'f = v/λ', '{"why":"Frequency is calculated by dividing speed by wavelength.","sol":"Step 1: v = 150 m/s, λ = 0.5 m\nStep 2: f = v/λ\nStep 3: f = 150/0.5\nStep 4: f = 300 Hz","steps":["Step 1: v = 150 m/s, λ = 0.5 m","Step 2: f = v/λ","Step 3: f = 150/0.5","Step 4: f = 300 Hz"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q4","subject":"physics","chapter":"waves","topic":"Sound waves"}', 3),
  (1371, 372, 'Why can''t sound travel in space?', 'text', 1, 'no particles', '{"why":"Sound needs particles to vibrate, but space is a vacuum with no particles.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Sound needs particles to vibrate, but space is a vacuum with no particles.\nStep 3: State the final conclusion: Because there is no medium for sound waves to travel through.","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Sound needs particles to vibrate, but space is a vacuum with no particles.","Step 3: State the final conclusion: Because there is no medium for sound waves to travel through."],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q5","subject":"physics","chapter":"waves","topic":"Sound waves"}', 4),
  (1372, 372, 'What determines loudness of sound?', 'text', 1, 'wave height', '{"why":"Greater amplitude means louder sound, lower amplitude means softer sound.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Greater amplitude means louder sound, lower amplitude means softer sound.\nStep 3: State the final conclusion: Amplitude","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Greater amplitude means louder sound, lower amplitude means softer sound.","Step 3: State the final conclusion: Amplitude"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q6","subject":"physics","chapter":"waves","topic":"Sound waves"}', 5),
  (1373, 372, 'What determines pitch of sound?', 'text', 1, 'frequency', '{"why":"High frequency produces high pitch sound and low frequency produces low pitch.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: High frequency produces high pitch sound and low frequency produces low pitch.\nStep 3: State the final conclusion: Frequency","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: High frequency produces high pitch sound and low frequency produces low pitch.","Step 3: State the final conclusion: Frequency"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q7","subject":"physics","chapter":"waves","topic":"Sound waves"}', 6),
  (1374, 372, 'What is a sound wave?', 'text', 1, 'vibration', '{"why":"Sound waves travel through air, liquids, or solids by particle vibration.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Sound waves travel through air, liquids, or solids by particle vibration.\nStep 3: State the final conclusion: A sound wave is a mechanical wave produced by vibrations of particles.","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Sound waves travel through air, liquids, or solids by particle vibration.","Step 3: State the final conclusion: A sound wave is a mechanical wave produced by vibrations of particles."],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q8","subject":"physics","chapter":"waves","topic":"Sound waves"}', 7),
  (1375, 372, 'What type of wave is sound?', 'text', 1, 'mechanical', '{"why":"Sound requires a medium to travel, so it is a mechanical wave.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Sound requires a medium to travel, so it is a mechanical wave.\nStep 3: State the final conclusion: A mechanical wave","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Sound requires a medium to travel, so it is a mechanical wave.","Step 3: State the final conclusion: A mechanical wave"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q9","subject":"physics","chapter":"waves","topic":"Sound waves"}', 8),
  (1376, 372, 'A sound wave has frequency 50 Hz and speed 340 m/s. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength depends on speed and frequency.","sol":"Step 1: v = 340 m/s, f = 50 Hz\nStep 2: λ = v/f\nStep 3: λ = 340/50\nStep 4: λ = 6.8 m","steps":["Step 1: v = 340 m/s, f = 50 Hz","Step 2: λ = v/f","Step 3: λ = 340/50","Step 4: λ = 6.8 m"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q10","subject":"physics","chapter":"waves","topic":"Sound waves"}', 9),
  (1377, 372, 'What is echo?', 'text', 1, 'reflection of sound', '{"why":"Sound reflects off surfaces and returns to the listener after a delay.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Sound reflects off surfaces and returns to the listener after a delay.\nStep 3: State the final conclusion: Echo is the reflection of sound waves.","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Sound reflects off surfaces and returns to the listener after a delay.","Step 3: State the final conclusion: Echo is the reflection of sound waves."],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q11","subject":"physics","chapter":"waves","topic":"Sound waves"}', 10),
  (1378, 372, 'Why is sound faster in solids than in air?', 'text', 1, 'particle spacing', '{"why":"Closer particles transfer vibrations faster in solids than in gases.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Closer particles transfer vibrations faster in solids than in gases.\nStep 3: State the final conclusion: Because particles are closer together in solids.","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Closer particles transfer vibrations faster in solids than in gases.","Step 3: State the final conclusion: Because particles are closer together in solids."],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q12","subject":"physics","chapter":"waves","topic":"Sound waves"}', 11),
  (1379, 373, 'A light wave has frequency 4 × 10^14 Hz and wavelength 7.5 × 10^-7 m. Find speed.', 'text', 1, 'Use v = fλ', '{"why":"Wave speed is the product of frequency and wavelength.","sol":"Step 1: Identify values → f = 4 × 10^14 Hz, λ = 7.5 × 10^-7 m\nStep 2: Write formula → v = fλ\nStep 3: Substitute → v = (4 × 10^14)(7.5 × 10^-7)\nStep 4: Multiply numbers → 4 × 7.5 = 30\nStep 5: Add powers → 10^14 × 10^-7 = 10^7\nStep 6: Final result → v = 3 × 10^8 m/s","steps":["Step 1: Identify values → f = 4 × 10^14 Hz, λ = 7.5 × 10^-7 m","Step 2: Write formula → v = fλ","Step 3: Substitute → v = (4 × 10^14)(7.5 × 10^-7)","Step 4: Multiply numbers → 4 × 7.5 = 30","Step 5: Add powers → 10^14 × 10^-7 = 10^7","Step 6: Final result → v = 3 × 10^8 m/s"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Light waves"}', 0),
  (1380, 373, 'A wave has frequency 2 × 10^6 Hz and wavelength 0.15 m. Find speed.', 'text', 1, 'v = fλ', '{"why":"Speed is directly proportional to frequency and wavelength.","sol":"Step 1: f = 2 × 10^6 Hz, λ = 0.15 m\nStep 2: v = fλ\nStep 3: v = (2 × 10^6) × 0.15\nStep 4: 2 × 0.15 = 0.3\nStep 5: v = 0.3 × 10^6\nStep 6: v = 3 × 10^5 m/s","steps":["Step 1: f = 2 × 10^6 Hz, λ = 0.15 m","Step 2: v = fλ","Step 3: v = (2 × 10^6) × 0.15","Step 4: 2 × 0.15 = 0.3","Step 5: v = 0.3 × 10^6","Step 6: v = 3 × 10^5 m/s"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Light waves"}', 1),
  (1381, 373, 'A wave travels at 340 m/s and has frequency 170 Hz. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength is found by dividing speed by frequency.","sol":"Step 1: Identify values → v = 340 m/s, f = 170 Hz\nStep 2: Write formula → λ = v/f\nStep 3: Substitute → λ = 340/170\nStep 4: Calculate → λ = 2 m","steps":["Step 1: Identify values → v = 340 m/s, f = 170 Hz","Step 2: Write formula → λ = v/f","Step 3: Substitute → λ = 340/170","Step 4: Calculate → λ = 2 m"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Light waves"}', 2),
  (1382, 373, 'A wave has wavelength 0.5 m and speed 200 m/s. Find frequency.', 'text', 1, 'f = v/λ', '{"why":"Frequency is speed divided by wavelength.","sol":"Step 1: v = 200 m/s, λ = 0.5 m\nStep 2: f = v/λ\nStep 3: f = 200/0.5\nStep 4: f = 400 Hz","steps":["Step 1: v = 200 m/s, λ = 0.5 m","Step 2: f = v/λ","Step 3: f = 200/0.5","Step 4: f = 400 Hz"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q4","subject":"physics","chapter":"waves","topic":"Light waves"}', 3),
  (1383, 373, 'A wave has frequency 5 × 10^5 Hz and speed 1 × 10^8 m/s. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength increases when frequency decreases.","sol":"Step 1: v = 1 × 10^8, f = 5 × 10^5\nStep 2: λ = v/f\nStep 3: λ = (1 × 10^8) / (5 × 10^5)\nStep 4: 1/5 = 0.2\nStep 5: 10^8 / 10^5 = 10^3\nStep 6: λ = 0.2 × 10^3 = 200 m","steps":["Step 1: v = 1 × 10^8, f = 5 × 10^5","Step 2: λ = v/f","Step 3: λ = (1 × 10^8) / (5 × 10^5)","Step 4: 1/5 = 0.2","Step 5: 10^8 / 10^5 = 10^3","Step 6: λ = 0.2 × 10^3 = 200 m"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q5","subject":"physics","chapter":"waves","topic":"Light waves"}', 4),
  (1384, 373, 'A wave has wavelength 3 m and frequency 50 Hz. Find speed.', 'text', 1, 'v = fλ', '{"why":"Wave speed is product of frequency and wavelength.","sol":"Step 1: f = 50 Hz, λ = 3 m\nStep 2: v = fλ\nStep 3: v = 50 × 3\nStep 4: v = 150 m/s","steps":["Step 1: f = 50 Hz, λ = 3 m","Step 2: v = fλ","Step 3: v = 50 × 3","Step 4: v = 150 m/s"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q6","subject":"physics","chapter":"waves","topic":"Light waves"}', 5),
  (1385, 373, 'A light wave has frequency 6 × 10^14 Hz and wavelength 5 × 10^-7 m. Find speed.', 'text', 1, 'v = fλ', '{"why":"Light speed in vacuum is constant.","sol":"Step 1: f = 6 × 10^14, λ = 5 × 10^-7\nStep 2: v = fλ\nStep 3: Multiply → 6 × 5 = 30\nStep 4: Add powers → 10^14 × 10^-7 = 10^7\nStep 5: v = 3 × 10^8 m/s","steps":["Step 1: f = 6 × 10^14, λ = 5 × 10^-7","Step 2: v = fλ","Step 3: Multiply → 6 × 5 = 30","Step 4: Add powers → 10^14 × 10^-7 = 10^7","Step 5: v = 3 × 10^8 m/s"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q7","subject":"physics","chapter":"waves","topic":"Light waves"}', 6),
  (1386, 373, 'A wave travels 600 m in 3 seconds. Find its speed.', 'text', 1, 'v = d/t', '{"why":"Speed is distance divided by time.","sol":"Step 1: d = 600 m, t = 3 s\nStep 2: v = d/t\nStep 3: v = 600/3\nStep 4: v = 200 m/s","steps":["Step 1: d = 600 m, t = 3 s","Step 2: v = d/t","Step 3: v = 600/3","Step 4: v = 200 m/s"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q8","subject":"physics","chapter":"waves","topic":"Light waves"}', 7),
  (1387, 373, 'A wave has speed 300 m/s and wavelength 0.6 m. Find frequency.', 'text', 1, 'f = v/λ', '{"why":"Frequency depends on speed and wavelength.","sol":"Step 1: v = 300 m/s, λ = 0.6 m\nStep 2: f = v/λ\nStep 3: f = 300/0.6\nStep 4: f = 500 Hz","steps":["Step 1: v = 300 m/s, λ = 0.6 m","Step 2: f = v/λ","Step 3: f = 300/0.6","Step 4: f = 500 Hz"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q9","subject":"physics","chapter":"waves","topic":"Light waves"}', 8),
  (1388, 373, 'Why can light travel in space?', 'text', 1, 'no medium required', '{"why":"Unlike sound, light can travel through a vacuum because it does not rely on particles.","sol":"Step 1: Identify key concept: Define the required principles for Light waves.\nStep 2: Apply governing rule: Unlike sound, light can travel through a vacuum because it does not rely on particles.\nStep 3: State the final conclusion: Because light is an electromagnetic wave that does not need a medium.","steps":["Step 1: Identify key concept: Define the required principles for Light waves.","Step 2: Apply governing rule: Unlike sound, light can travel through a vacuum because it does not rely on particles.","Step 3: State the final conclusion: Because light is an electromagnetic wave that does not need a medium."],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q10","subject":"physics","chapter":"waves","topic":"Light waves"}', 9),
  (1389, 374, 'Why does light bend in water?', 'text', 1, 'change of medium', '{"why":"When light passes from air into water, its speed decreases, causing it to change direction (refraction).","sol":"Step 1: Identify key concept: Define the required principles for Reflection & refraction.\nStep 2: Apply governing rule: When light passes from air into water, its speed decreases, causing it to change direction (refraction).\nStep 3: State the final conclusion: Because its speed changes when entering a different medium.","steps":["Step 1: Identify key concept: Define the required principles for Reflection & refraction.","Step 2: Apply governing rule: When light passes from air into water, its speed decreases, causing it to change direction (refraction).","Step 3: State the final conclusion: Because its speed changes when entering a different medium."],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 0),
  (1390, 374, 'A ray of light hits a mirror at 60°. Find angle of reflection.', 'text', 1, 'law of reflection', '{"why":"The law of reflection states that the angle of incidence equals the angle of reflection.","sol":"Step 1: Identify angle of incidence → i = 60°\nStep 2: Use law of reflection → i = r\nStep 3: Substitute values → r = 60°","steps":["Step 1: Identify angle of incidence → i = 60°","Step 2: Use law of reflection → i = r","Step 3: Substitute values → r = 60°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 1),
  (1391, 374, 'A light ray strikes a mirror at 30°. Calculate the angle of reflection.', 'text', 1, 'law of reflection', '{"why":"Reflection follows the law i = r, meaning angles are equal.","sol":"Step 1: Identify angle of incidence → i = 30°\nStep 2: Apply law of reflection → i = r\nStep 3: Substitute values → r = 30°","steps":["Step 1: Identify angle of incidence → i = 30°","Step 2: Apply law of reflection → i = r","Step 3: Substitute values → r = 30°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 2),
  (1392, 374, 'A ray hits a mirror at 45°. What is the angle between the incident ray and reflected ray?', 'text', 1, 'sum of angles', '{"why":"The angle between incident and reflected rays equals twice the angle of incidence.","sol":"Step 1: Identify incidence angle → i = 45°\nStep 2: Reflection angle → r = 45°\nStep 3: Add angles → 45° + 45°\nStep 4: Result = 90°","steps":["Step 1: Identify incidence angle → i = 45°","Step 2: Reflection angle → r = 45°","Step 3: Add angles → 45° + 45°","Step 4: Result = 90°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q4","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 3),
  (1393, 374, 'A light ray travels from air into glass and slows down. What happens to its direction?', 'text', 1, 'refraction effect', '{"why":"When light enters a denser medium, it slows down and bends towards the normal line.","sol":"Step 1: Light enters denser medium (air → glass)\nStep 2: Speed decreases\nStep 3: Ray bends towards the normal\nStep 4: New direction is closer to normal line","steps":["Step 1: Light enters denser medium (air → glass)","Step 2: Speed decreases","Step 3: Ray bends towards the normal","Step 4: New direction is closer to normal line"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q5","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 4),
  (1394, 374, 'Why does light bend in water?', 'text', 1, 'change of medium', '{"why":"When light passes from air into water, its speed decreases, causing it to change direction (refraction).","sol":"Step 1: Identify key concept: Define the required principles for Reflection & refraction.\nStep 2: Apply governing rule: When light passes from air into water, its speed decreases, causing it to change direction (refraction).\nStep 3: State the final conclusion: Because its speed changes when entering a different medium.","steps":["Step 1: Identify key concept: Define the required principles for Reflection & refraction.","Step 2: Apply governing rule: When light passes from air into water, its speed decreases, causing it to change direction (refraction).","Step 3: State the final conclusion: Because its speed changes when entering a different medium."],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q7","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 5),
  (1395, 374, 'A ray of light hits a mirror at 60°. Find the angle of reflection.', 'text', 1, 'law of reflection', '{"why":"The law of reflection states that angle of incidence equals angle of reflection.","sol":"Step 1: Identify angle of incidence → i = 60°\nStep 2: Apply law of reflection → i = r\nStep 3: Substitute values → r = 60°","steps":["Step 1: Identify angle of incidence → i = 60°","Step 2: Apply law of reflection → i = r","Step 3: Substitute values → r = 60°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q8","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 6),
  (1396, 374, 'A ray of light strikes a plane mirror at 35°. Calculate the angle of reflection.', 'text', 1, 'i = r', '{"why":"Reflection obeys i = r at all times.","sol":"Step 1: Given angle of incidence → i = 35°\nStep 2: Apply law of reflection → r = i\nStep 3: Substitute → r = 35°","steps":["Step 1: Given angle of incidence → i = 35°","Step 2: Apply law of reflection → r = i","Step 3: Substitute → r = 35°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q9","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 7),
  (1397, 374, 'A light ray is incident on a mirror at 40°. Find the angle between the incident ray and reflected ray.', 'text', 1, 'geometry of reflection', '{"why":"The geometry of reflection gives angle between incident and reflected rays as 2i.","sol":"Step 1: Identify incidence angle → i = 40°\nStep 2: Use relation → angle between rays = 2i\nStep 3: Substitute → 2 × 40°\nStep 4: Calculate → 80°","steps":["Step 1: Identify incidence angle → i = 40°","Step 2: Use relation → angle between rays = 2i","Step 3: Substitute → 2 × 40°","Step 4: Calculate → 80°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q10","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 8),
  (1398, 374, 'A ray passes from air into glass. Refractive index of glass is 1.5. If angle of incidence is 30°, calculate angle of refraction.', 'text', 1, 'Snell’s law', '{"why":"Snell’s law relates angles of incidence and refraction using refractive indices.","sol":"Step 1: Identify values → n1 = 1 (air), n2 = 1.5, i = 30°\nStep 2: Apply Snell’s law → 1 × sin30° = 1.5 × sin r\nStep 3: Substitute → 0.5 = 1.5 sin r\nStep 4: Solve → sin r = 0.333\nStep 5: Find r → r ≈ 19.5°","steps":["Step 1: Identify values → n1 = 1 (air), n2 = 1.5, i = 30°","Step 2: Apply Snell’s law → 1 × sin30° = 1.5 × sin r","Step 3: Substitute → 0.5 = 1.5 sin r","Step 4: Solve → sin r = 0.333","Step 5: Find r → r ≈ 19.5°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q11","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 9),
  (1399, 374, 'A ray enters glass (n = 1.5) from air at 45°. Find angle of refraction.', 'text', 1, 'Snell’s law', '{"why":"Light bends towards the normal when entering a denser medium.","sol":"Step 1: n1 = 1, n2 = 1.5, i = 45°\nStep 2: Apply formula → sin r = (1 × sin45°)/1.5\nStep 3: sin45° = 0.707\nStep 4: sin r = 0.707/1.5 = 0.471\nStep 5: r ≈ 28.1°","steps":["Step 1: n1 = 1, n2 = 1.5, i = 45°","Step 2: Apply formula → sin r = (1 × sin45°)/1.5","Step 3: sin45° = 0.707","Step 4: sin r = 0.707/1.5 = 0.471","Step 5: r ≈ 28.1°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q12","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 10),
  (1400, 375, 'Why does sound bend around corners?', 'text', 1, 'wave spreading', '{"why":"Diffraction is the spreading of waves when they pass around obstacles or through gaps.","sol":"Step 1: Identify wave type → sound is a wave\nStep 2: Waves can bend when passing obstacles\nStep 3: This bending is called diffraction\nStep 4: Apply concept → sound spreads around corners","steps":["Step 1: Identify wave type → sound is a wave","Step 2: Waves can bend when passing obstacles","Step 3: This bending is called diffraction","Step 4: Apply concept → sound spreads around corners"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 0),
  (1401, 375, 'What happens in destructive interference?', 'text', 1, 'opposite phases', '{"why":"Destructive interference occurs when waves meet out of phase and reduce total amplitude.","sol":"Step 1: Two waves meet\nStep 2: One crest meets a trough\nStep 3: They cancel each other partially or fully\nStep 4: Resulting amplitude decreases","steps":["Step 1: Two waves meet","Step 2: One crest meets a trough","Step 3: They cancel each other partially or fully","Step 4: Resulting amplitude decreases"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 1),
  (1402, 375, 'If two identical waves meet crest to crest, what happens?', 'text', 1, 'same phase', '{"why":"Constructive interference occurs when waves combine in phase, increasing total amplitude.","sol":"Step 1: Identify phase → crest meets crest\nStep 2: Waves are in phase\nStep 3: Add amplitudes\nStep 4: Result = increased amplitude","steps":["Step 1: Identify phase → crest meets crest","Step 2: Waves are in phase","Step 3: Add amplitudes","Step 4: Result = increased amplitude"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 2),
  (1403, 375, 'Two identical waves each have amplitude 3 cm. They meet crest to crest. Find resultant amplitude.', 'text', 1, 'Use constructive interference (add amplitudes)', '{"why":"Constructive interference increases amplitude when waves meet in phase.","sol":"Step 1: Identify amplitudes → A1 = 3 cm, A2 = 3 cm\nStep 2: Waves meet crest to crest → constructive interference\nStep 3: Apply formula → A_result = A1 + A2\nStep 4: Substitute → A_result = 3 + 3\nStep 5: Calculate → A_result = 6 cm","steps":["Step 1: Identify amplitudes → A1 = 3 cm, A2 = 3 cm","Step 2: Waves meet crest to crest → constructive interference","Step 3: Apply formula → A_result = A1 + A2","Step 4: Substitute → A_result = 3 + 3","Step 5: Calculate → A_result = 6 cm"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q5","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 3),
  (1404, 375, 'Two waves of amplitude 5 cm and 3 cm meet crest to trough. Find resultant amplitude.', 'text', 1, 'Use destructive interference (subtract amplitudes)', '{"why":"Destructive interference reduces amplitude when waves are out of phase.","sol":"Step 1: Identify amplitudes → A1 = 5 cm, A2 = 3 cm\nStep 2: Crest meets trough → destructive interference\nStep 3: Apply formula → A_result = A1 - A2\nStep 4: Substitute → A_result = 5 - 3\nStep 5: Calculate → A_result = 2 cm","steps":["Step 1: Identify amplitudes → A1 = 5 cm, A2 = 3 cm","Step 2: Crest meets trough → destructive interference","Step 3: Apply formula → A_result = A1 - A2","Step 4: Substitute → A_result = 5 - 3","Step 5: Calculate → A_result = 2 cm"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q6","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 4),
  (1405, 375, 'A wave travels 340 m in 2 seconds. Find its speed.', 'text', 1, 'Use speed = distance ÷ time', '{"why":"Wave speed is distance covered per unit time.","sol":"Step 1: Identify values → d = 340 m, t = 2 s\nStep 2: Write formula → v = d / t\nStep 3: Substitute → v = 340 / 2\nStep 4: Calculate → v = 170 m/s","steps":["Step 1: Identify values → d = 340 m, t = 2 s","Step 2: Write formula → v = d / t","Step 3: Substitute → v = 340 / 2","Step 4: Calculate → v = 170 m/s"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q7","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 5),
  (1406, 376, 'A charge of 18C flows in 3s. Find current.', 'text', 1, 'Use I = Q / t', '{"why":"Current is the rate of flow of charge per unit time.","sol":"Step 1: Identify values → Q = 18C, t = 3s\nStep 2: Write formula → I = Q / t\nStep 3: Substitute values → I = 18 / 3\nStep 4: Calculate → I = 6A","steps":["Step 1: Identify values → Q = 18C, t = 3s","Step 2: Write formula → I = Q / t","Step 3: Substitute values → I = 18 / 3","Step 4: Calculate → I = 6A"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 0),
  (1407, 376, 'Find current if V = 12V and R = 3Ω.', 'text', 1, 'Use Ohm''s Law I = V / R', '{"why":"Ohm''s Law relates voltage, current, and resistance.","sol":"Step 1: Identify values → V = 12V, R = 3Ω\nStep 2: Write formula → I = V / R\nStep 3: Substitute values → I = 12 / 3\nStep 4: Calculate → I = 4A","steps":["Step 1: Identify values → V = 12V, R = 3Ω","Step 2: Write formula → I = V / R","Step 3: Substitute values → I = 12 / 3","Step 4: Calculate → I = 4A"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 1),
  (1408, 376, 'Find the resistance if V = 24V and I = 6A.', 'text', 1, 'Use R = V / I', '{"why":"Resistance opposes the flow of electric current.","sol":"Step 1: Identify values → V = 24V, I = 6A\nStep 2: Write formula → R = V / I\nStep 3: Substitute values → R = 24 / 6\nStep 4: Calculate → R = 4Ω","steps":["Step 1: Identify values → V = 24V, I = 6A","Step 2: Write formula → R = V / I","Step 3: Substitute values → R = 24 / 6","Step 4: Calculate → R = 4Ω"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 2),
  (1409, 376, 'Find the voltage if I = 5A and R = 8Ω.', 'text', 1, 'Use V = IR', '{"why":"Voltage is the electrical energy supplied per unit charge.","sol":"Step 1: Identify values → I = 5A, R = 8Ω\nStep 2: Write formula → V = IR\nStep 3: Substitute values → V = 5 × 8\nStep 4: Calculate → V = 40V","steps":["Step 1: Identify values → I = 5A, R = 8Ω","Step 2: Write formula → V = IR","Step 3: Substitute values → V = 5 × 8","Step 4: Calculate → V = 40V"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 3),
  (1410, 376, 'A charge of 60C flows in 12s. Find the current.', 'text', 1, 'Use I = Q / t', '{"why":"Current tells us how much charge passes a point each second.","sol":"Step 1: Identify values → Q = 60C, t = 12s\nStep 2: Write formula → I = Q / t\nStep 3: Substitute values → I = 60 / 12\nStep 4: Calculate → I = 5A","steps":["Step 1: Identify values → Q = 60C, t = 12s","Step 2: Write formula → I = Q / t","Step 3: Substitute values → I = 60 / 12","Step 4: Calculate → I = 5A"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q5","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 4),
  (1411, 376, 'A bulb uses 120W at 240V. Find the current.', 'text', 1, 'Use P = VI', '{"why":"Power equals voltage multiplied by current.","sol":"Step 1: Identify values → P = 120W, V = 240V\nStep 2: Rearrange formula → I = P / V\nStep 3: Substitute values → I = 120 / 240\nStep 4: Calculate → I = 0.5A","steps":["Step 1: Identify values → P = 120W, V = 240V","Step 2: Rearrange formula → I = P / V","Step 3: Substitute values → I = 120 / 240","Step 4: Calculate → I = 0.5A"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q6","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 5),
  (1412, 376, 'A circuit has V = 18V and I = 3A. Find the power.', 'text', 1, 'Use P = VI', '{"why":"Electrical power is the rate at which electrical energy is used.","sol":"Step 1: Identify values → V = 18V, I = 3A\nStep 2: Write formula → P = VI\nStep 3: Substitute values → P = 18 × 3\nStep 4: Calculate → P = 54W","steps":["Step 1: Identify values → V = 18V, I = 3A","Step 2: Write formula → P = VI","Step 3: Substitute values → P = 18 × 3","Step 4: Calculate → P = 54W"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q7","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 6),
  (1413, 376, 'An appliance uses 1000J of energy in 50s. Find the power.', 'text', 1, 'Use P = E / t', '{"why":"Power measures how quickly energy is transferred.","sol":"Step 1: Identify values → E = 1000J, t = 50s\nStep 2: Write formula → P = E / t\nStep 3: Substitute values → P = 1000 / 50\nStep 4: Calculate → P = 20W","steps":["Step 1: Identify values → E = 1000J, t = 50s","Step 2: Write formula → P = E / t","Step 3: Substitute values → P = 1000 / 50","Step 4: Calculate → P = 20W"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q8","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 7),
  (1414, 376, 'A resistor of 5Ω carries a current of 4A. Find the voltage.', 'text', 1, 'Use V = IR', '{"why":"Voltage across a resistor depends on current and resistance.","sol":"Step 1: Identify values → I = 4A, R = 5Ω\nStep 2: Write formula → V = IR\nStep 3: Substitute values → V = 4 × 5\nStep 4: Calculate → V = 20V","steps":["Step 1: Identify values → I = 4A, R = 5Ω","Step 2: Write formula → V = IR","Step 3: Substitute values → V = 4 × 5","Step 4: Calculate → V = 20V"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q9","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 8),
  (1415, 376, 'Find the resistance if V = 30V and I = 5A.', 'text', 1, 'Use R = V / I', '{"why":"Resistance determines how much a material opposes current flow.","sol":"Step 1: Identify values → V = 30V, I = 5A\nStep 2: Write formula → R = V / I\nStep 3: Substitute values → R = 30 / 5\nStep 4: Calculate → R = 6Ω","steps":["Step 1: Identify values → V = 30V, I = 5A","Step 2: Write formula → R = V / I","Step 3: Substitute values → R = 30 / 5","Step 4: Calculate → R = 6Ω"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q10","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 9),
  (1416, 376, 'A battery supplies 48V to a 12Ω resistor. Find the current.', 'text', 1, 'Use I = V / R', '{"why":"Current increases when voltage increases or resistance decreases.","sol":"Step 1: Identify values → V = 48V, R = 12Ω\nStep 2: Write formula → I = V / R\nStep 3: Substitute values → I = 48 / 12\nStep 4: Calculate → I = 4A","steps":["Step 1: Identify values → V = 48V, R = 12Ω","Step 2: Write formula → I = V / R","Step 3: Substitute values → I = 48 / 12","Step 4: Calculate → I = 4A"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q11","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 10),
  (1417, 377, 'In a parallel circuit, branch currents are 2A, 3A and 5A. Find total current.', 'text', 1, 'Add all branch currents', '{"why":"In parallel circuits, total current is the sum of currents in all branches.","sol":"I(total) = 2 + 3 + 5 = 10A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: In parallel circuits, total current is the sum of currents in all branches.","Step 3: State the final conclusion: 10A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 0),
  (1418, 377, 'A series circuit has a current of 3A. What is the current through each resistor?', 'text', 1, 'Series = same current everywhere', '{"why":"In a series circuit, current is the same at all points because there is only one path.","sol":"I1 = I2 = I3 = 3A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: In a series circuit, current is the same at all points because there is only one path.","Step 3: State the final conclusion: 3A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 1),
  (1419, 377, 'A voltage of 12V is applied across a resistor of 4Ω. Find the current.', 'text', 1, 'Use Ohm’s Law: I = V / R', '{"why":"Ohm’s Law states that current equals voltage divided by resistance.","sol":"I = 12 / 4 = 3A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Ohm’s Law states that current equals voltage divided by resistance.","Step 3: State the final conclusion: 3A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 2),
  (1420, 377, 'Find resistance if voltage is 20V and current is 5A.', 'text', 1, 'Use R = V / I', '{"why":"Resistance is found by dividing voltage by current.","sol":"R = 20 / 5 = 4Ω","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Resistance is found by dividing voltage by current.","Step 3: State the final conclusion: 4Ω"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 3),
  (1421, 377, 'A circuit has two branches carrying 1.5A and 2.5A. Find total current.', 'text', 1, 'Sum branch currents', '{"why":"Total current in a parallel circuit is the sum of all branch currents.","sol":"1.5 + 2.5 = 4A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Total current in a parallel circuit is the sum of all branch currents.","Step 3: State the final conclusion: 4A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q5","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 4),
  (1422, 377, 'If a 9V battery pushes 3A through a circuit, find resistance.', 'text', 1, 'R = V / I', '{"why":"Divide voltage by current to get resistance.","sol":"R = 9 / 3 = 3Ω","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Divide voltage by current to get resistance.","Step 3: State the final conclusion: 3Ω"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q6","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 5),
  (1423, 377, 'In a parallel circuit, total current is 8A. If one branch is 3A, find the other branch current.', 'text', 1, 'Subtract known current', '{"why":"Total current equals sum of branch currents, so subtract to find missing value.","sol":"8 - 3 = 5A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Total current equals sum of branch currents, so subtract to find missing value.","Step 3: State the final conclusion: 5A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q7","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 6),
  (1424, 377, 'A resistor has 6Ω resistance and current of 2A. Find voltage.', 'text', 1, 'Use V = IR', '{"why":"Voltage equals current multiplied by resistance.","sol":"V = 2 × 6 = 12V","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Voltage equals current multiplied by resistance.","Step 3: State the final conclusion: 12V"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q8","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 7),
  (1425, 377, 'Two identical bulbs in series each carry 1.5A. What is total current?', 'text', 1, 'Series current rule', '{"why":"In series circuits, current is constant throughout the circuit.","sol":"Same current flows in series circuit","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: In series circuits, current is constant throughout the circuit.","Step 3: State the final conclusion: 1.5A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q9","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 8),
  (1426, 377, 'A circuit has 3 parallel branches carrying 2A, 2A and 6A. Find total current.', 'text', 1, 'Add all values', '{"why":"Total current in parallel circuits is the sum of branch currents.","sol":"2 + 2 + 6 = 10A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Total current in parallel circuits is the sum of branch currents.","Step 3: State the final conclusion: 10A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q10","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 9),
  (1427, 378, 'What is a magnetic field?', 'text', 1, 'region of influence', '{"why":"Magnetic fields are invisible but can be detected through their effects on materials like iron or compass needles.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Magnetic fields are invisible but can be detected through their effects on materials like iron or compass needles.\nStep 3: State the final conclusion: A region around a magnet or current-carrying conductor where magnetic forces can be experienced.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Magnetic fields are invisible but can be detected through their effects on materials like iron or compass needles.","Step 3: State the final conclusion: A region around a magnet or current-carrying conductor where magnetic forces can be experienced."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 0),
  (1428, 378, 'What do magnetic field lines show?', 'text', 1, 'direction + strength', '{"why":"Closer field lines indicate a stronger magnetic field, and the direction shows how a north pole would move.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Closer field lines indicate a stronger magnetic field, and the direction shows how a north pole would move.\nStep 3: State the final conclusion: They show the direction and strength of a magnetic field.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Closer field lines indicate a stronger magnetic field, and the direction shows how a north pole would move.","Step 3: State the final conclusion: They show the direction and strength of a magnetic field."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 1),
  (1429, 378, 'In which direction do magnetic field lines flow outside a magnet?', 'text', 1, 'N to S', '{"why":"Outside the magnet, field lines always go from North to South, and inside they return from South to North.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Outside the magnet, field lines always go from North to South, and inside they return from South to North.\nStep 3: State the final conclusion: From North pole to South pole.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Outside the magnet, field lines always go from North to South, and inside they return from South to North.","Step 3: State the final conclusion: From North pole to South pole."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 2),
  (1430, 378, 'What are magnetic domains?', 'text', 1, 'tiny magnets', '{"why":"Each domain acts like a dipole, and their alignment determines whether a material is magnetised.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Each domain acts like a dipole, and their alignment determines whether a material is magnetised.\nStep 3: State the final conclusion: Small regions inside a material that behave like tiny magnets.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Each domain acts like a dipole, and their alignment determines whether a material is magnetised.","Step 3: State the final conclusion: Small regions inside a material that behave like tiny magnets."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 3),
  (1431, 378, 'Why is a material unmagnetised?', 'text', 1, 'random orientation', '{"why":"Randomly arranged domains cancel each other’s magnetic effects, resulting in no overall magnetism.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Randomly arranged domains cancel each other’s magnetic effects, resulting in no overall magnetism.\nStep 3: State the final conclusion: Because its magnetic domains are randomly arranged.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Randomly arranged domains cancel each other’s magnetic effects, resulting in no overall magnetism.","Step 3: State the final conclusion: Because its magnetic domains are randomly arranged."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q5","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 4),
  (1432, 378, 'What happens to magnetic domains when a material is magnetised?', 'text', 1, 'alignment', '{"why":"Aligned domains reinforce each other, producing a strong net magnetic field.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Aligned domains reinforce each other, producing a strong net magnetic field.\nStep 3: State the final conclusion: They align in the same direction.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Aligned domains reinforce each other, producing a strong net magnetic field.","Step 3: State the final conclusion: They align in the same direction."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q6","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 5),
  (1433, 378, 'Why is repulsion the only sure test for polarity?', 'text', 1, 'attraction is not enough', '{"why":"Only repulsion confirms that two poles are the same type (N–N or S–S).","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Only repulsion confirms that two poles are the same type (N–N or S–S).\nStep 3: State the final conclusion: Because attraction can occur with both poles, but repulsion only occurs between like poles.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Only repulsion confirms that two poles are the same type (N–N or S–S).","Step 3: State the final conclusion: Because attraction can occur with both poles, but repulsion only occurs between like poles."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q7","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 6),
  (1434, 378, 'What causes demagnetisation?', 'text', 1, 'heat, shock, AC', '{"why":"These disturb the alignment of magnetic domains, reducing or removing magnetism.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: These disturb the alignment of magnetic domains, reducing or removing magnetism.\nStep 3: State the final conclusion: Heat, hammering, or alternating current.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: These disturb the alignment of magnetic domains, reducing or removing magnetism.","Step 3: State the final conclusion: Heat, hammering, or alternating current."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q8","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 7),
  (1435, 378, 'Why does a compass needle align north-south?', 'text', 1, 'Earth is a magnet', '{"why":"The compass aligns with Earth’s magnetic field, showing that Earth behaves like a giant magnet.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: The compass aligns with Earth’s magnetic field, showing that Earth behaves like a giant magnet.\nStep 3: State the final conclusion: Because Earth has a magnetic field.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: The compass aligns with Earth’s magnetic field, showing that Earth behaves like a giant magnet.","Step 3: State the final conclusion: Because Earth has a magnetic field."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q9","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 8),
  (1436, 378, 'How does stroking magnetise a material?', 'text', 1, 'domain alignment', '{"why":"Repeated stroking forces domains to line up, creating a net magnetic field.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Repeated stroking forces domains to line up, creating a net magnetic field.\nStep 3: State the final conclusion: It aligns magnetic domains in one direction.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Repeated stroking forces domains to line up, creating a net magnetic field.","Step 3: State the final conclusion: It aligns magnetic domains in one direction."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q10","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 9),
  (1437, 379, 'What is electromagnetism?', 'text', 1, 'electricity + magnetism', '{"why":"Electric current produces a magnetic field around a conductor, showing the link between electricity and magnetism.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Electric current produces a magnetic field around a conductor, showing the link between electricity and magnetism.\nStep 3: State the final conclusion: Electromagnetism is the relationship between electric current and magnetic fields.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Electric current produces a magnetic field around a conductor, showing the link between electricity and magnetism.","Step 3: State the final conclusion: Electromagnetism is the relationship between electric current and magnetic fields."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 0),
  (1438, 379, 'What happens when current flows in a wire?', 'text', 1, 'magnetic field forms', '{"why":"Moving electric charges (current) generate a magnetic field around the conductor.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Moving electric charges (current) generate a magnetic field around the conductor.\nStep 3: State the final conclusion: A magnetic field is produced around the wire.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Moving electric charges (current) generate a magnetic field around the conductor.","Step 3: State the final conclusion: A magnetic field is produced around the wire."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 1),
  (1439, 379, 'Why is a solenoid stronger than a straight wire?', 'text', 1, 'many loops', '{"why":"Each loop produces a magnetic field and they add together, making the overall field stronger.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Each loop produces a magnetic field and they add together, making the overall field stronger.\nStep 3: State the final conclusion: Because magnetic fields from each coil turn combine.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Each loop produces a magnetic field and they add together, making the overall field stronger.","Step 3: State the final conclusion: Because magnetic fields from each coil turn combine."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 2),
  (1440, 379, 'How do you increase the strength of an electromagnet?', 'text', 1, 'current, turns, core', '{"why":"All these factors increase the strength of the magnetic field produced.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: All these factors increase the strength of the magnetic field produced.\nStep 3: State the final conclusion: Increase current, increase number of coil turns, and use a soft iron core.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: All these factors increase the strength of the magnetic field produced.","Step 3: State the final conclusion: Increase current, increase number of coil turns, and use a soft iron core."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 3),
  (1441, 379, 'What is the role of a soft iron core in an electromagnet?', 'text', 1, 'magnetic enhancement', '{"why":"Soft iron becomes magnetized easily and concentrates magnetic field lines.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Soft iron becomes magnetized easily and concentrates magnetic field lines.\nStep 3: State the final conclusion: It increases the strength of the magnetic field.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Soft iron becomes magnetized easily and concentrates magnetic field lines.","Step 3: State the final conclusion: It increases the strength of the magnetic field."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q5","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 4),
  (1442, 379, 'Why does reversing current reverse magnetic field direction?', 'text', 1, 'direction of charge flow', '{"why":"Changing current direction changes the motion of charges, reversing the field.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Changing current direction changes the motion of charges, reversing the field.\nStep 3: State the final conclusion: Because magnetic field direction depends on current direction.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Changing current direction changes the motion of charges, reversing the field.","Step 3: State the final conclusion: Because magnetic field direction depends on current direction."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q6","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 5),
  (1443, 379, 'What is produced around a current-carrying conductor?', 'text', 1, 'invisible force field', '{"why":"Electric current generates a circular magnetic field around the conductor.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Electric current generates a circular magnetic field around the conductor.\nStep 3: State the final conclusion: A magnetic field.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Electric current generates a circular magnetic field around the conductor.","Step 3: State the final conclusion: A magnetic field."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q7","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 6),
  (1444, 379, 'Why do electromagnets stop working when current is switched off?', 'text', 1, 'temporary magnet', '{"why":"Without current, moving charges stop, so the magnetic field disappears.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Without current, moving charges stop, so the magnetic field disappears.\nStep 3: State the final conclusion: Because the magnetic field depends on electric current.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Without current, moving charges stop, so the magnetic field disappears.","Step 3: State the final conclusion: Because the magnetic field depends on electric current."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q8","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 7),
  (1445, 380, 'A voltage of 20V produces a current of 5A. Find the resistance.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"R = V / I = 20 / 5 = 4Ω","steps":["Step 1: Identify the given values: V = 20V and I = 5A.","Step 2: Recall Ohm''s Law for resistance: R = V / I.","Step 3: Substitute the values: R = 20 / 5.","Step 4: Calculate: R = 4Ω."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 0),
  (1446, 380, 'Find the current if V = 12V and R = 3Ω.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = V / R = 12 / 3 = 4A","steps":["Step 1: Identify the given values: V = 12V and R = 3Ω.","Step 2: Recall the formula: I = V / R.","Step 3: Substitute the values: I = 12 / 3.","Step 4: Calculate: I = 4A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 1),
  (1447, 380, 'State Ohm''s Law.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Current is directly proportional to voltage provided the temperature remains constant.","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Current is directly proportional to voltage provided the temperature remains constant."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 2),
  (1448, 380, 'A battery supplies 24V to a resistor of 6Ω. Find the current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = V / R = 24 / 6 = 4A","steps":["Step 1: Identify V = 24V and R = 6Ω.","Step 2: Use the formula I = V / R.","Step 3: Substitute the values: I = 24 / 6.","Step 4: Calculate: I = 4A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 3),
  (1449, 380, 'A current of 2A flows through a resistor of 10Ω. Find the voltage.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"V = IR = 2 × 10 = 20V","steps":["Step 1: Identify I = 2A and R = 10Ω.","Step 2: Recall the formula: V = IR.","Step 3: Substitute the values: V = 2 × 10.","Step 4: Calculate: V = 20V."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q5","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 4),
  (1450, 380, 'A resistor has a voltage of 18V and a current of 3A. Find its resistance.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"R = V / I = 18 / 3 = 6Ω","steps":["Step 1: Identify V = 18V and I = 3A.","Step 2: Recall the formula: R = V / I.","Step 3: Substitute the values: R = 18 / 3.","Step 4: Calculate: R = 6Ω."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q6","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 5),
  (1451, 380, 'A charge of 40C passes through a conductor in 8 seconds. Find the current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = Q / t = 40 / 8 = 5A","steps":["Step 1: Identify Q = 40C and t = 8s.","Step 2: Recall the formula: I = Q / t.","Step 3: Substitute the values: I = 40 / 8.","Step 4: Calculate: I = 5A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q7","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 6),
  (1452, 380, 'A charge of 72C flows for 9 seconds. Calculate the current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = Q / t = 72 / 9 = 8A","steps":["Step 1: Identify Q = 72C and t = 9s.","Step 2: Recall the formula: I = Q / t.","Step 3: Substitute the values: I = 72 / 9.","Step 4: Calculate: I = 8A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q8","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 7),
  (1453, 380, 'A current of 5A flows for 12 seconds. Find the charge transferred.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Q = It = 5 × 12 = 60C","steps":["Step 1: Identify I = 5A and t = 12s.","Step 2: Recall the formula: Q = It.","Step 3: Substitute the values: Q = 5 × 12.","Step 4: Calculate: Q = 60C."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q9","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 8),
  (1454, 380, 'A current of 3A flows for 15 seconds. Calculate the charge.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Q = It = 3 × 15 = 45C","steps":["Step 1: Identify I = 3A and t = 15s.","Step 2: Recall the formula: Q = It.","Step 3: Substitute the values: Q = 3 × 15.","Step 4: Calculate: Q = 45C."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q10","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 9),
  (1455, 380, 'An electric heater operates at 240V and draws a current of 5A. Find the power.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"P = VI = 240 × 5 = 1200W","steps":["Step 1: Identify V = 240V and I = 5A.","Step 2: Recall the formula: P = VI.","Step 3: Substitute the values: P = 240 × 5.","Step 4: Calculate: P = 1200W."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q11","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 10),
  (1456, 380, 'A bulb operates at 12V and draws 2A. Calculate its power.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"P = VI = 12 × 2 = 24W","steps":["Step 1: Identify V = 12V and I = 2A.","Step 2: Recall the formula: P = VI.","Step 3: Substitute the values: P = 12 × 2.","Step 4: Calculate: P = 24W."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q12","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 11),
  (1457, 380, 'A motor uses 600W from a 200V supply. Find the current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = P / V = 600 / 200 = 3A","steps":["Step 1: Identify P = 600W and V = 200V.","Step 2: Rearrange the power formula: I = P / V.","Step 3: Substitute the values: I = 600 / 200.","Step 4: Calculate: I = 3A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q13","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 12),
  (1458, 380, 'An appliance consumes 1000W on a 250V supply. Find the current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = P / V = 1000 / 250 = 4A","steps":["Step 1: Identify P = 1000W and V = 250V.","Step 2: Use the formula: I = P / V.","Step 3: Substitute the values: I = 1000 / 250.","Step 4: Calculate: I = 4A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q14","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 13),
  (1459, 380, 'A resistor carries a current of 8A when connected to a 40V supply. Find the resistance.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"R = V / I = 40 / 8 = 5Ω","steps":["Step 1: Identify V = 40V and I = 8A.","Step 2: Recall the formula: R = V / I.","Step 3: Substitute the values: R = 40 / 8.","Step 4: Calculate: R = 5Ω."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q15","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 14),
  (1460, 380, 'What is electric current?', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Electric current is the rate of flow of electric charge through a conductor.","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Electric current is the rate of flow of electric charge through a conductor."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q16","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 15),
  (1461, 380, 'State the SI unit of electric current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The SI unit of electric current is the ampere (A).","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The SI unit of electric current is the ampere (A)."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q17","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 16),
  (1462, 380, 'State the SI unit of resistance.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The SI unit of resistance is the ohm (Ω).","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The SI unit of resistance is the ohm (Ω)."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q18","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 17),
  (1463, 380, 'State the SI unit of voltage.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The SI unit of voltage is the volt (V).","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The SI unit of voltage is the volt (V)."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q19","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 18),
  (1464, 380, 'What instrument is used to measure electric current?', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: An ammeter is used to measure electric current.","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: An ammeter is used to measure electric current."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q20","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 19),
  (1465, 381, 'Why do ships float on water?', 'text', 1, 'Focus on the core principle of Fluids.', '{"why":"A floating object remains in equilibrium when the buoyant force equals its weight.","sol":"Step 1: Recall that water exerts an upward force called upthrust (buoyant force).\nStep 2: Compare the ship''s weight with the upthrust acting on it.\nStep 3: When the upthrust equals the weight of the ship, the ship floats.\nStep 4: The large hollow shape of a ship displaces enough water to produce sufficient upthrust.","steps":["Step 1: Recall that water exerts an upward force called upthrust (buoyant force).","Step 2: Compare the ship''s weight with the upthrust acting on it.","Step 3: When the upthrust equals the weight of the ship, the ship floats.","Step 4: The large hollow shape of a ship displaces enough water to produce sufficient upthrust."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q1","subject":"physics","chapter":"fluids","topic":"Fluids"}', 0),
  (1466, 381, 'Why does a stone sink in water?', 'text', 1, 'Focus on the core principle of Fluids.', '{"why":"Objects sink when the downward force exceeds the buoyant force.","sol":"Step 1: Identify the weight of the stone acting downward.\nStep 2: Identify the upthrust provided by the water acting upward.\nStep 3: Compare the two forces.\nStep 4: Since the stone''s weight is greater than the upthrust, it sinks.","steps":["Step 1: Identify the weight of the stone acting downward.","Step 2: Identify the upthrust provided by the water acting upward.","Step 3: Compare the two forces.","Step 4: Since the stone''s weight is greater than the upthrust, it sinks."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q2","subject":"physics","chapter":"fluids","topic":"Fluids"}', 1),
  (1467, 381, 'State Archimedes'' Principle.', 'text', 1, 'Focus on the core principle of Fluids.', '{"why":"This principle explains floating and sinking.","sol":"Step 1: Consider an object immersed in a fluid.\nStep 2: The object displaces some of the fluid.\nStep 3: The displaced fluid has weight.\nStep 4: The upthrust equals the weight of the displaced fluid.","steps":["Step 1: Consider an object immersed in a fluid.","Step 2: The object displaces some of the fluid.","Step 3: The displaced fluid has weight.","Step 4: The upthrust equals the weight of the displaced fluid."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q3","subject":"physics","chapter":"fluids","topic":"Fluids"}', 2),
  (1468, 381, 'Why is it easier to swim in seawater than in fresh water?', 'text', 1, 'Focus on the core principle of Fluids.', '{"why":"Greater density increases the buoyant force.","sol":"Step 1: Compare the densities of seawater and fresh water.\nStep 2: Note that seawater is denser because of dissolved salts.\nStep 3: Denser water produces a greater upthrust.\nStep 4: Greater upthrust makes floating easier.","steps":["Step 1: Compare the densities of seawater and fresh water.","Step 2: Note that seawater is denser because of dissolved salts.","Step 3: Denser water produces a greater upthrust.","Step 4: Greater upthrust makes floating easier."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q4","subject":"physics","chapter":"fluids","topic":"Fluids"}', 3),
  (1469, 381, 'A force of 200N acts on an area of 4m². Calculate the pressure.', 'text', 1, 'Pressure = Force ÷ Area', '{"why":"Pressure is the force acting per unit area.","sol":"Step 1: Identify the values: Force = 200N and Area = 4m².\nStep 2: Write the formula: P = F ÷ A.\nStep 3: Substitute the values: P = 200 ÷ 4.\nStep 4: Calculate: P = 50 Pa.","steps":["Step 1: Identify the values: Force = 200N and Area = 4m².","Step 2: Write the formula: P = F ÷ A.","Step 3: Substitute the values: P = 200 ÷ 4.","Step 4: Calculate: P = 50 Pa."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q5","subject":"physics","chapter":"fluids","topic":"Fluids"}', 4),
  (1470, 381, 'A force of 150N acts on an area of 3m². Find the pressure.', 'text', 1, 'Use P = F ÷ A', '{"why":"Pressure increases when force increases or area decreases.","sol":"Step 1: Identify Force = 150N and Area = 3m².\nStep 2: Write the formula P = F ÷ A.\nStep 3: Substitute: P = 150 ÷ 3.\nStep 4: Calculate: P = 50 Pa.","steps":["Step 1: Identify Force = 150N and Area = 3m².","Step 2: Write the formula P = F ÷ A.","Step 3: Substitute: P = 150 ÷ 3.","Step 4: Calculate: P = 50 Pa."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q6","subject":"physics","chapter":"fluids","topic":"Fluids"}', 5),
  (1471, 381, 'A pressure of 80Pa acts over an area of 5m². Calculate the force.', 'text', 1, 'Force = Pressure × Area', '{"why":"Force equals pressure multiplied by area.","sol":"Step 1: Identify Pressure = 80Pa and Area = 5m².\nStep 2: Write the formula: F = PA.\nStep 3: Substitute: F = 80 × 5.\nStep 4: Calculate: F = 400N.","steps":["Step 1: Identify Pressure = 80Pa and Area = 5m².","Step 2: Write the formula: F = PA.","Step 3: Substitute: F = 80 × 5.","Step 4: Calculate: F = 400N."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q7","subject":"physics","chapter":"fluids","topic":"Fluids"}', 6),
  (1472, 381, 'A pressure of 300Pa is produced by a force of 600N. Find the area.', 'text', 1, 'Area = Force ÷ Pressure', '{"why":"Area is obtained by dividing force by pressure.","sol":"Step 1: Identify Force = 600N and Pressure = 300Pa.\nStep 2: Rearrange the formula: A = F ÷ P.\nStep 3: Substitute: A = 600 ÷ 300.\nStep 4: Calculate: A = 2m².","steps":["Step 1: Identify Force = 600N and Pressure = 300Pa.","Step 2: Rearrange the formula: A = F ÷ P.","Step 3: Substitute: A = 600 ÷ 300.","Step 4: Calculate: A = 2m²."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q8","subject":"physics","chapter":"fluids","topic":"Fluids"}', 7),
  (1473, 381, 'A force of 900N acts on an area of 9m². Calculate the pressure.', 'text', 1, 'Use P = F ÷ A', '{"why":"Pressure is directly proportional to force and inversely proportional to area.","sol":"Step 1: Identify Force = 900N and Area = 9m².\nStep 2: Write the formula P = F ÷ A.\nStep 3: Substitute: P = 900 ÷ 9.\nStep 4: Calculate: P = 100 Pa.","steps":["Step 1: Identify Force = 900N and Area = 9m².","Step 2: Write the formula P = F ÷ A.","Step 3: Substitute: P = 900 ÷ 9.","Step 4: Calculate: P = 100 Pa."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q9","subject":"physics","chapter":"fluids","topic":"Fluids"}', 8),
  (1474, 381, 'A pressure of 250Pa acts over an area of 8m². Find the force.', 'text', 1, 'Use F = PA', '{"why":"Increasing either pressure or area increases the force.","sol":"Step 1: Identify Pressure = 250Pa and Area = 8m².\nStep 2: Write the formula F = PA.\nStep 3: Substitute: F = 250 × 8.\nStep 4: Calculate: F = 2000N.","steps":["Step 1: Identify Pressure = 250Pa and Area = 8m².","Step 2: Write the formula F = PA.","Step 3: Substitute: F = 250 × 8.","Step 4: Calculate: F = 2000N."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q10","subject":"physics","chapter":"fluids","topic":"Fluids"}', 9),
  (1475, 381, 'A force of 360N acts on an area of 12m². Find the pressure.', 'text', 1, 'Use P = F ÷ A', '{"why":"Pressure is measured in pascals (Pa).","sol":"Step 1: Identify Force = 360N and Area = 12m².\nStep 2: Write the formula P = F ÷ A.\nStep 3: Substitute: P = 360 ÷ 12.\nStep 4: Calculate: P = 30 Pa.","steps":["Step 1: Identify Force = 360N and Area = 12m².","Step 2: Write the formula P = F ÷ A.","Step 3: Substitute: P = 360 ÷ 12.","Step 4: Calculate: P = 30 Pa."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q11","subject":"physics","chapter":"fluids","topic":"Fluids"}', 10),
  (1476, 382, 'What is radioactivity?', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"Unstable nuclei lose excess energy by emitting radiation to become more stable.","sol":"Step 1: Recall that some atomic nuclei are unstable.\nStep 2: An unstable nucleus emits radiation without any external influence.\nStep 3: This emission may include alpha particles, beta particles, or gamma rays.\nStep 4: The process continues until the nucleus becomes more stable.","steps":["Step 1: Recall that some atomic nuclei are unstable.","Step 2: An unstable nucleus emits radiation without any external influence.","Step 3: This emission may include alpha particles, beta particles, or gamma rays.","Step 4: The process continues until the nucleus becomes more stable."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q1","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 0),
  (1477, 382, 'What is an alpha particle?', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"Alpha particles are emitted by heavy unstable nuclei.","sol":"Step 1: Recall the three common types of radioactive emissions.\nStep 2: Identify that an alpha particle contains protons and neutrons.\nStep 3: State its composition.\nStep 4: Give the definition.","steps":["Step 1: Recall the three common types of radioactive emissions.","Step 2: Identify that an alpha particle contains protons and neutrons.","Step 3: State its composition.","Step 4: Give the definition."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q2","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 1),
  (1478, 382, 'What is a beta particle?', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"Beta decay helps unstable nuclei achieve greater stability.","sol":"Step 1: Recall radioactive emissions.\nStep 2: Identify the beta particle as a fast-moving electron.\nStep 3: State that it is emitted from the nucleus.\nStep 4: Give the definition.","steps":["Step 1: Recall radioactive emissions.","Step 2: Identify the beta particle as a fast-moving electron.","Step 3: State that it is emitted from the nucleus.","Step 4: Give the definition."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q3","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 2),
  (1479, 382, 'What are gamma rays?', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"Gamma rays carry excess energy away from unstable nuclei.","sol":"Step 1: Recall that gamma rays are a type of radiation.\nStep 2: Identify that they are electromagnetic waves.\nStep 3: Note that they have no mass and no charge.\nStep 4: State the definition.","steps":["Step 1: Recall that gamma rays are a type of radiation.","Step 2: Identify that they are electromagnetic waves.","Step 3: Note that they have no mass and no charge.","Step 4: State the definition."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q4","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 3),
  (1480, 382, 'State one property of alpha particles.', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"They contain two positively charged protons.","sol":"Step 1: Recall the characteristics of alpha particles.\nStep 2: Identify one property.\nStep 3: State the property clearly.","steps":["Step 1: Recall the characteristics of alpha particles.","Step 2: Identify one property.","Step 3: State the property clearly."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q5","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 4),
  (1481, 382, 'Why are gamma rays more penetrating than alpha particles?', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"They interact less with matter than charged particles.","sol":"Step 1: Compare the masses of alpha particles and gamma rays.\nStep 2: Recall that gamma rays have no mass or charge.\nStep 3: Less interaction with matter allows deeper penetration.\nStep 4: State the conclusion.","steps":["Step 1: Compare the masses of alpha particles and gamma rays.","Step 2: Recall that gamma rays have no mass or charge.","Step 3: Less interaction with matter allows deeper penetration.","Step 4: State the conclusion."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q6","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 5),
  (1482, 382, 'Name two applications of modern physics.', 'text', 1, 'Think medicine and energy.', '{"why":"Both rely on atomic and nuclear physics.","sol":"Step 1: Identify one medical application.\nStep 2: Identify one energy application.\nStep 3: State both applications.","steps":["Step 1: Identify one medical application.","Step 2: Identify one energy application.","Step 3: State both applications."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q7","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 6),
  (1483, 382, 'State one medical application of radioactivity.', 'text', 1, 'Think hospitals.', '{"why":"Radiation destroys cancer cells.","sol":"Step 1: Recall how radiation is used in medicine.\nStep 2: Identify one example.\nStep 3: State the application.","steps":["Step 1: Recall how radiation is used in medicine.","Step 2: Identify one example.","Step 3: State the application."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q8","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 7),
  (1484, 382, 'State one industrial application of radioactivity.', 'text', 1, 'Think manufacturing.', '{"why":"Radiation helps monitor product quality.","sol":"Step 1: Recall industrial uses of radiation.\nStep 2: Identify one example.\nStep 3: State the application.","steps":["Step 1: Recall industrial uses of radiation.","Step 2: Identify one example.","Step 3: State the application."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q9","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 8),
  (1485, 382, 'State one agricultural application of radioactivity.', 'text', 1, 'Think crops.', '{"why":"Radiation can produce useful genetic variations.","sol":"Step 1: Recall how radiation is used in agriculture.\nStep 2: Identify one use.\nStep 3: State the application.","steps":["Step 1: Recall how radiation is used in agriculture.","Step 2: Identify one use.","Step 3: State the application."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q10","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 9),
  (1486, 382, 'State one disadvantage of radioactivity.', 'text', 1, 'Think health effects.', '{"why":"Ionising radiation damages body cells and DNA.","sol":"Step 1: Recall the harmful effects of radiation.\nStep 2: Identify one effect.\nStep 3: State the disadvantage.","steps":["Step 1: Recall the harmful effects of radiation.","Step 2: Identify one effect.","Step 3: State the disadvantage."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q11","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 10),
  (1487, 382, 'Why must radioactive materials be handled carefully?', 'text', 1, 'Think safety.', '{"why":"Proper handling reduces exposure and protects human health.","sol":"Step 1: Recall that radiation can damage living tissue.\nStep 2: Consider long-term exposure effects.\nStep 3: State why safety precautions are necessary.","steps":["Step 1: Recall that radiation can damage living tissue.","Step 2: Consider long-term exposure effects.","Step 3: State why safety precautions are necessary."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q12","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 11),
  (1488, 383, 'What are cathode rays?', 'text', 1, 'Focus on the core principle of Cathode Rays and Cathode Ray Tube.', '{"why":"Cathode rays consist of negatively charged electrons.","sol":"Step 1: Recall that a cathode ray tube contains a cathode and an anode in a vacuum.\nStep 2: Electrons are emitted from the cathode when a high voltage is applied.\nStep 3: The electrons travel across the vacuum toward the anode.\nStep 4: These moving electrons are called cathode rays.","steps":["Step 1: Recall that a cathode ray tube contains a cathode and an anode in a vacuum.","Step 2: Electrons are emitted from the cathode when a high voltage is applied.","Step 3: The electrons travel across the vacuum toward the anode.","Step 4: These moving electrons are called cathode rays."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 0),
  (1489, 383, 'State two properties of cathode rays.', 'text', 1, 'Focus on the core principle of Cathode Rays and Cathode Ray Tube.', '{"why":"These properties were demonstrated using cathode ray tubes.","sol":"Step 1: Recall the characteristics of cathode rays.\nStep 2: Identify that they travel in straight lines.\nStep 3: Identify that they are negatively charged.\nStep 4: State both properties.","steps":["Step 1: Recall the characteristics of cathode rays.","Step 2: Identify that they travel in straight lines.","Step 3: Identify that they are negatively charged.","Step 4: State both properties."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 1),
  (1490, 383, 'Why do cathode rays produce shadows?', 'text', 1, 'Focus on the core principle of Cathode Rays and Cathode Ray Tube.', '{"why":"Straight-line motion causes shadow formation.","sol":"Step 1: Recall that cathode rays travel in straight lines.\nStep 2: Place an object in their path.\nStep 3: The object blocks the rays.\nStep 4: A shadow forms behind the object.","steps":["Step 1: Recall that cathode rays travel in straight lines.","Step 2: Place an object in their path.","Step 3: The object blocks the rays.","Step 4: A shadow forms behind the object."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 2),
  (1491, 383, 'Why do cathode rays cause fluorescence?', 'text', 1, 'Focus on the core principle of Cathode Rays and Cathode Ray Tube.', '{"why":"The kinetic energy of electrons is converted into light energy.","sol":"Step 1: Cathode rays strike a fluorescent material.\nStep 2: The electrons transfer energy to the material.\nStep 3: The material emits visible light.\nStep 4: The screen glows.","steps":["Step 1: Cathode rays strike a fluorescent material.","Step 2: The electrons transfer energy to the material.","Step 3: The material emits visible light.","Step 4: The screen glows."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q4","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 3),
  (1492, 383, 'Why can cathode rays turn a light paddle wheel?', 'text', 1, 'Focus on the core principle of Cathode Rays and Cathode Ray Tube.', '{"why":"This demonstrates that cathode rays are particles.","sol":"Step 1: Recall that cathode rays are streams of particles.\nStep 2: The particles strike the paddle wheel.\nStep 3: They transfer momentum to the wheel.\nStep 4: The wheel rotates.","steps":["Step 1: Recall that cathode rays are streams of particles.","Step 2: The particles strike the paddle wheel.","Step 3: They transfer momentum to the wheel.","Step 4: The wheel rotates."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q5","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 4),
  (1493, 383, 'Why are cathode rays deflected in electric fields?', 'text', 1, 'Think about their charge.', '{"why":"Charged particles experience forces in electric fields.","sol":"Step 1: Recall that cathode rays are electrons.\nStep 2: Electrons have a negative charge.\nStep 3: Electric fields exert forces on charged particles.\nStep 4: Therefore, cathode rays are deflected toward the positive plate.","steps":["Step 1: Recall that cathode rays are electrons.","Step 2: Electrons have a negative charge.","Step 3: Electric fields exert forces on charged particles.","Step 4: Therefore, cathode rays are deflected toward the positive plate."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q6","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 5),
  (1494, 383, 'Why are cathode rays deflected by magnetic fields?', 'text', 1, 'Think about moving charges.', '{"why":"Magnetic fields affect moving charged particles.","sol":"Step 1: Recall that cathode rays are moving electrons.\nStep 2: Moving charges experience magnetic forces.\nStep 3: The magnetic field changes their direction.\nStep 4: The rays are deflected.","steps":["Step 1: Recall that cathode rays are moving electrons.","Step 2: Moving charges experience magnetic forces.","Step 3: The magnetic field changes their direction.","Step 4: The rays are deflected."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q7","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 6),
  (1495, 383, 'What happens when cathode rays strike a metal target?', 'text', 1, 'Think X-rays.', '{"why":"Rapid deceleration of electrons produces X-rays.","sol":"Step 1: Cathode rays move at very high speed.\nStep 2: They collide with the metal target.\nStep 3: They lose energy suddenly.\nStep 4: X-rays are produced.","steps":["Step 1: Cathode rays move at very high speed.","Step 2: They collide with the metal target.","Step 3: They lose energy suddenly.","Step 4: X-rays are produced."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q8","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 7),
  (1496, 383, 'Why is a vacuum needed in a cathode ray tube?', 'text', 1, 'Think collisions.', '{"why":"The rays can travel efficiently only in a vacuum.","sol":"Step 1: Recall that air contains many particles.\nStep 2: Electrons would collide with air molecules.\nStep 3: These collisions would reduce their energy.\nStep 4: A vacuum allows electrons to travel freely.","steps":["Step 1: Recall that air contains many particles.","Step 2: Electrons would collide with air molecules.","Step 3: These collisions would reduce their energy.","Step 4: A vacuum allows electrons to travel freely."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q9","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 8),
  (1497, 383, 'How do cathode rays demonstrate that electrons are particles?', 'text', 1, 'Think mass and momentum.', '{"why":"Objects with mass behave as particles.","sol":"Step 1: Observe that cathode rays can move a light paddle wheel.\nStep 2: Only particles with mass can transfer momentum.\nStep 3: The wheel rotates after being struck.\nStep 4: Therefore, cathode rays are particles.","steps":["Step 1: Observe that cathode rays can move a light paddle wheel.","Step 2: Only particles with mass can transfer momentum.","Step 3: The wheel rotates after being struck.","Step 4: Therefore, cathode rays are particles."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q10","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 9),
  (1498, 384, 'What is photoelectric emission?', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"Photons transfer their energy to electrons in the metal, causing them to escape if energy exceeds work function.","sol":"Step 1: Identify incident radiation (light of sufficient frequency).\nStep 2: Identify the surface (metal surface).\nStep 3: State the emission of electrons (photoelectrons).","steps":["Step 1: Identify incident radiation (light of sufficient frequency).","Step 2: Identify the surface (metal surface).","Step 3: State the emission of electrons (photoelectrons)."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 0),
  (1499, 384, 'Define threshold frequency (f₀) in photoelectric effect.', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"If light frequency is below threshold frequency, individual photon energy is less than the work function.","sol":"Step 1: Consider the frequency of incident radiation.\nStep 2: Define the minimum boundary required for emission.\nStep 3: Explain that light below this frequency causes no electron ejection regardless of intensity.","steps":["Step 1: Consider the frequency of incident radiation.","Step 2: Define the minimum boundary required for emission.","Step 3: Explain that light below this frequency causes no electron ejection regardless of intensity."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 1),
  (1500, 384, 'Define the work function (φ) of a metal.', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"Electrons are bound to metal atoms and require a specific threshold energy to escape.","sol":"Step 1: Consider the binding energy of electrons in a metal.\nStep 2: Define the minimum energy required.\nStep 3: State that it is the minimum energy needed to free an electron from the metal surface.","steps":["Step 1: Consider the binding energy of electrons in a metal.","Step 2: Define the minimum energy required.","Step 3: State that it is the minimum energy needed to free an electron from the metal surface."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 2);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (1501, 384, 'State Einstein''s photoelectric equation.', 'text', 1, 'Think energy of photon = work function + max kinetic energy.', '{"why":"Incident photon energy (hf) is used to overcome work function (φ) and any remaining energy becomes kinetic energy of photoelectron.","sol":"Step 1: Write photon energy (hf).\nStep 2: Equate to work function (φ) plus maximum kinetic energy (KEmax).\nStep 3: State equation: hf = φ + KEmax or KEmax = hf - φ.","steps":["Step 1: Write photon energy (hf).","Step 2: Equate to work function (φ) plus maximum kinetic energy (KEmax).","Step 3: State equation: hf = φ + KEmax or KEmax = hf - φ."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q4","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 3),
  (1502, 384, 'What effect does increasing the intensity of incident light have on photoelectric emission?', 'text', 1, 'Think number of photons vs energy per photon.', '{"why":"Intensity determines the photon flux, while light frequency determines individual photon energy.","sol":"Step 1: Understand that higher intensity means more photons per second.\nStep 2: State that each photon interacts with one electron.\nStep 3: Conclude that more photoelectrons are emitted per second (photocurrent), but max kinetic energy stays constant.","steps":["Step 1: Understand that higher intensity means more photons per second.","Step 2: State that each photon interacts with one electron.","Step 3: Conclude that more photoelectrons are emitted per second (photocurrent), but max kinetic energy stays constant."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q5","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 4),
  (1503, 384, 'Why does light below threshold frequency fail to emit electrons even if intensity is increased?', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"Photoelectric absorption is a one-to-one photon-electron interaction.","sol":"Step 1: Recognize that one photon interacts with one electron.\nStep 2: Note that if individual photon energy (hf) < work function (φ), no energy accumulates.\nStep 3: Conclude that increasing intensity only supplies more low-energy photons.","steps":["Step 1: Recognize that one photon interacts with one electron.","Step 2: Note that if individual photon energy (hf) < work function (φ), no energy accumulates.","Step 3: Conclude that increasing intensity only supplies more low-energy photons."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q6","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 5),
  (1504, 384, 'Calculate the energy of a photon of light with frequency 6.0 × 10¹⁴ Hz. (Planck''s constant h = 6.63 × 10⁻³⁴ J·s)', 'text', 1, 'Use E = hf', '{"why":"Photon energy is directly proportional to frequency via Planck''s constant.","sol":"Step 1: Identify h = 6.63 × 10⁻³⁴ J·s and f = 6.0 × 10¹⁴ Hz.\nStep 2: Apply formula E = h × f.\nStep 3: Substitute: E = (6.63 × 10⁻³⁴) × (6.0 × 10¹⁴).\nStep 4: Calculate: E = 3.978 × 10⁻¹⁹ J.","steps":["Step 1: Identify h = 6.63 × 10⁻³⁴ J·s and f = 6.0 × 10¹⁴ Hz.","Step 2: Apply formula E = h × f.","Step 3: Substitute: E = (6.63 × 10⁻³⁴) × (6.0 × 10¹⁴).","Step 4: Calculate: E = 3.978 × 10⁻¹⁹ J."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q7","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 6),
  (1505, 384, 'A metal has a work function of 2.5 × 10⁻¹⁹ J. If incident light delivers photon energy of 4.2 × 10⁻¹⁹ J, find the maximum kinetic energy of the emitted photoelectrons.', 'text', 1, 'Use KEmax = hf - φ', '{"why":"The excess energy above the work function becomes the maximum kinetic energy of the emitted photoelectron.","sol":"Step 1: Identify photon energy E = hf = 4.2 × 10⁻¹⁹ J.\nStep 2: Identify work function φ = 2.5 × 10⁻¹⁹ J.\nStep 3: Apply KEmax = hf - φ.\nStep 4: Calculate KEmax = (4.2 × 10⁻¹⁹) - (2.5 × 10⁻¹⁹) = 1.7 × 10⁻¹⁹ J.","steps":["Step 1: Identify photon energy E = hf = 4.2 × 10⁻¹⁹ J.","Step 2: Identify work function φ = 2.5 × 10⁻¹⁹ J.","Step 3: Apply KEmax = hf - φ.","Step 4: Calculate KEmax = (4.2 × 10⁻¹⁹) - (2.5 × 10⁻¹⁹) = 1.7 × 10⁻¹⁹ J."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q8","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 7),
  (1506, 384, 'What is stopping potential in the photoelectric effect?', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"At stopping potential, work done against electric field equals maximum kinetic energy of photoelectrons (eVs = KEmax).","sol":"Step 1: Define opposing electric potential applied to anode.\nStep 2: State the minimum retarding potential that stops the fastest photoelectrons.\nStep 3: Relate to maximum kinetic energy (eVs = KEmax).","steps":["Step 1: Define opposing electric potential applied to anode.","Step 2: State the minimum retarding potential that stops the fastest photoelectrons.","Step 3: Relate to maximum kinetic energy (eVs = KEmax)."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q9","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 8),
  (1507, 384, 'State two practical applications of photoelectric emission.', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"These devices convert incident light energy directly into electrical signals using photoelectric principles.","sol":"Step 1: Identify technology utilizing light detection.\nStep 2: Give solar cells / solar panels.\nStep 3: Give light sensors in cameras or automatic doors.","steps":["Step 1: Identify technology utilizing light detection.","Step 2: Give solar cells / solar panels.","Step 3: Give light sensors in cameras or automatic doors."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q10","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 9),
  (1508, 385, 'What is chemistry?', 'text', 1, 'Focus on the core principle of Meaning of Chemistry.', '{"why":"Core definition","sol":"Step 1: Identify matter\nStep 2: Study composition\nStep 3: Study changes","steps":["Step 1: Identify matter","Step 2: Study composition","Step 3: Study changes"],"options":[],"conceptId":"chemistry_introduction_meaning_of_chemistry","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q1","subject":"chemistry","chapter":"introduction","topic":"Meaning of Chemistry"}', 0),
  (1509, 385, 'What is matter?', 'text', 1, 'Focus on the core principle of Meaning of Chemistry.', '{"why":"Foundation concept","sol":"Step 1: Has mass\nStep 2: Occupies space","steps":["Step 1: Has mass","Step 2: Occupies space"],"options":[],"conceptId":"chemistry_introduction_meaning_of_chemistry","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q2","subject":"chemistry","chapter":"introduction","topic":"Meaning of Chemistry"}', 1),
  (1510, 385, 'Why is chemistry important?', 'text', 1, 'Focus on the core principle of Meaning of Chemistry.', '{"why":"Application","sol":"Step 1: Explains substances\nStep 2: Helps medicine\nStep 3: Supports industry","steps":["Step 1: Explains substances","Step 2: Helps medicine","Step 3: Supports industry"],"options":[],"conceptId":"chemistry_introduction_meaning_of_chemistry","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q3","subject":"chemistry","chapter":"introduction","topic":"Meaning of Chemistry"}', 2),
  (1511, 385, 'What is a chemical change?', 'text', 1, 'Focus on the core principle of Meaning of Chemistry.', '{"why":"Concept clarity","sol":"Step 1: Identify reaction\nStep 2: New substance formed","steps":["Step 1: Identify reaction","Step 2: New substance formed"],"options":[],"conceptId":"chemistry_introduction_meaning_of_chemistry","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q4","subject":"chemistry","chapter":"introduction","topic":"Meaning of Chemistry"}', 3),
  (1512, 385, 'Why does structure affect properties?', 'text', 1, 'Focus on the core principle of Meaning of Chemistry.', '{"why":"Advanced understanding","sol":"Step 1: Arrangement matters\nStep 2: Affects bonding\nStep 3: Changes behavior","steps":["Step 1: Arrangement matters","Step 2: Affects bonding","Step 3: Changes behavior"],"options":[],"conceptId":"chemistry_introduction_meaning_of_chemistry","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q5","subject":"chemistry","chapter":"introduction","topic":"Meaning of Chemistry"}', 4),
  (1513, 386, 'Why should safety rules be followed in a laboratory?', 'text', 1, 'Focus on the core principle of Laboratory Safety and Apparatus.', '{"why":"Safety importance","sol":"Step 1: Identify possible dangers\nStep 2: Understand prevention\nStep 3: Link to safety","steps":["Step 1: Identify possible dangers","Step 2: Understand prevention","Step 3: Link to safety"],"options":[],"conceptId":"chemistry_introduction_laboratory_safety_and_apparatus","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q1","subject":"chemistry","chapter":"introduction","topic":"Laboratory Safety and Apparatus"}', 0),
  (1514, 386, 'Why should you not smell chemicals directly?', 'text', 1, 'Focus on the core principle of Laboratory Safety and Apparatus.', '{"why":"Health protection","sol":"Step 1: Chemicals may be toxic\nStep 2: Direct inhalation is dangerous","steps":["Step 1: Chemicals may be toxic","Step 2: Direct inhalation is dangerous"],"options":[],"conceptId":"chemistry_introduction_laboratory_safety_and_apparatus","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q2","subject":"chemistry","chapter":"introduction","topic":"Laboratory Safety and Apparatus"}', 1),
  (1515, 386, 'Why is a round-bottom flask used for heating?', 'text', 1, 'Focus on the core principle of Laboratory Safety and Apparatus.', '{"why":"Efficiency","sol":"Step 1: Shape distributes heat\nStep 2: Prevents cracking","steps":["Step 1: Shape distributes heat","Step 2: Prevents cracking"],"options":[],"conceptId":"chemistry_introduction_laboratory_safety_and_apparatus","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q3","subject":"chemistry","chapter":"introduction","topic":"Laboratory Safety and Apparatus"}', 2),
  (1516, 386, 'Why is a burette used in titration?', 'text', 1, 'Focus on the core principle of Laboratory Safety and Apparatus.', '{"why":"Accuracy","sol":"Step 1: Requires precision\nStep 2: Measures small volumes accurately","steps":["Step 1: Requires precision","Step 2: Measures small volumes accurately"],"options":[],"conceptId":"chemistry_introduction_laboratory_safety_and_apparatus","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q4","subject":"chemistry","chapter":"introduction","topic":"Laboratory Safety and Apparatus"}', 3),
  (1517, 386, 'Why is a pipette important?', 'text', 1, 'Focus on the core principle of Laboratory Safety and Apparatus.', '{"why":"Precision","sol":"Step 1: Transfers liquids\nStep 2: Needs exact measurement","steps":["Step 1: Transfers liquids","Step 2: Needs exact measurement"],"options":[],"conceptId":"chemistry_introduction_laboratory_safety_and_apparatus","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q5","subject":"chemistry","chapter":"introduction","topic":"Laboratory Safety and Apparatus"}', 4),
  (1518, 386, 'What is the use of a desiccator?', 'text', 1, 'Focus on the core principle of Laboratory Safety and Apparatus.', '{"why":"Preservation","sol":"Step 1: Remove moisture\nStep 2: Keep substances dry","steps":["Step 1: Remove moisture","Step 2: Keep substances dry"],"options":[],"conceptId":"chemistry_introduction_laboratory_safety_and_apparatus","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q6","subject":"chemistry","chapter":"introduction","topic":"Laboratory Safety and Apparatus"}', 5),
  (1519, 387, 'What is a solid?', 'text', 1, 'Focus on the core principle of States of Matter.', '{"why":"Definition based on particle arrangement","sol":"Step 1: Particles tightly packed\nStep 2: Cannot move freely\nStep 3: Fixed shape and volume","steps":["Step 1: Particles tightly packed","Step 2: Cannot move freely","Step 3: Fixed shape and volume"],"options":[],"conceptId":"chemistry_matter_states_of_matter","skillId":"chemistry_matter","subskillId":"chemistry_matter_q1","subject":"chemistry","chapter":"matter","topic":"States of Matter"}', 0),
  (1520, 387, 'What is a gas?', 'text', 1, 'Focus on the core principle of States of Matter.', '{"why":"Particle spacing and movement","sol":"Step 1: Particles far apart\nStep 2: Move freely\nStep 3: No fixed shape or volume","steps":["Step 1: Particles far apart","Step 2: Move freely","Step 3: No fixed shape or volume"],"options":[],"conceptId":"chemistry_matter_states_of_matter","skillId":"chemistry_matter","subskillId":"chemistry_matter_q2","subject":"chemistry","chapter":"matter","topic":"States of Matter"}', 1),
  (1521, 387, 'Why do liquids flow?', 'text', 1, 'Focus on the core principle of States of Matter.', '{"why":"Structure determines behavior","sol":"Step 1: Particles are loosely packed\nStep 2: Particles can move past each other","steps":["Step 1: Particles are loosely packed","Step 2: Particles can move past each other"],"options":[],"conceptId":"chemistry_matter_states_of_matter","skillId":"chemistry_matter","subskillId":"chemistry_matter_q3","subject":"chemistry","chapter":"matter","topic":"States of Matter"}', 2),
  (1522, 387, 'Why are gases compressible?', 'text', 1, 'Focus on the core principle of States of Matter.', '{"why":"Particle spacing","sol":"Step 1: Large spaces between particles\nStep 2: Particles can be pushed closer","steps":["Step 1: Large spaces between particles","Step 2: Particles can be pushed closer"],"options":[],"conceptId":"chemistry_matter_states_of_matter","skillId":"chemistry_matter","subskillId":"chemistry_matter_q4","subject":"chemistry","chapter":"matter","topic":"States of Matter"}', 3),
  (1523, 387, 'Explain melting using particle theory', 'text', 1, 'Focus on the core principle of States of Matter.', '{"why":"Energy and motion","sol":"Step 1: Heat is added\nStep 2: Particles gain energy\nStep 3: Particles move more freely","steps":["Step 1: Heat is added","Step 2: Particles gain energy","Step 3: Particles move more freely"],"options":[],"conceptId":"chemistry_matter_states_of_matter","skillId":"chemistry_matter","subskillId":"chemistry_matter_q5","subject":"chemistry","chapter":"matter","topic":"States of Matter"}', 4),
  (1524, 387, 'What is sublimation?', 'text', 1, 'Focus on the core principle of States of Matter.', '{"why":"Direct state change","sol":"Step 1: Solid gains energy\nStep 2: Changes directly to gas","steps":["Step 1: Solid gains energy","Step 2: Changes directly to gas"],"options":[],"conceptId":"chemistry_matter_states_of_matter","skillId":"chemistry_matter","subskillId":"chemistry_matter_q6","subject":"chemistry","chapter":"matter","topic":"States of Matter"}', 5),
  (1525, 387, 'What is deposition?', 'text', 1, 'Focus on the core principle of States of Matter.', '{"why":"Reverse of sublimation","sol":"Step 1: Gas loses energy\nStep 2: Changes directly to solid","steps":["Step 1: Gas loses energy","Step 2: Changes directly to solid"],"options":[],"conceptId":"chemistry_matter_states_of_matter","skillId":"chemistry_matter","subskillId":"chemistry_matter_q7","subject":"chemistry","chapter":"matter","topic":"States of Matter"}', 6),
  (1526, 388, 'Calculate heat required to raise temperature of 2kg water from 20°C to 50°C (c = 4200 J/kg°C)', 'text', 1, 'Focus on the core principle of Phase Changes (Advanced).', '{"why":"Heat calculation","sol":"Step 1: Use Q = mcΔT\nStep 2: m = 2kg, c = 4200, ΔT = (50-20)=30\nStep 3: Q = 2 × 4200 × 30\nStep 4: Q = 252000 J","steps":["Step 1: Use Q = mcΔT","Step 2: m = 2kg, c = 4200, ΔT = (50-20)=30","Step 3: Q = 2 × 4200 × 30","Step 4: Q = 252000 J"],"options":[],"conceptId":"chemistry_matter_phase_changes_advanced","skillId":"chemistry_matter","subskillId":"chemistry_matter_q1","subject":"chemistry","chapter":"matter","topic":"Phase Changes (Advanced)"}', 0),
  (1527, 388, 'Calculate heat needed to melt 1kg of ice (L = 334000 J/kg)', 'text', 1, 'Focus on the core principle of Phase Changes (Advanced).', '{"why":"Latent heat of fusion","sol":"Step 1: Use Q = mL\nStep 2: Q = 1 × 334000\nStep 3: Q = 334000 J","steps":["Step 1: Use Q = mL","Step 2: Q = 1 × 334000","Step 3: Q = 334000 J"],"options":[],"conceptId":"chemistry_matter_phase_changes_advanced","skillId":"chemistry_matter","subskillId":"chemistry_matter_q2","subject":"chemistry","chapter":"matter","topic":"Phase Changes (Advanced)"}', 1),
  (1528, 388, 'Explain what happens during melting on a graph', 'text', 1, 'Focus on the core principle of Phase Changes (Advanced).', '{"why":"Latent heat","sol":"Step 1: Temperature stays constant\nStep 2: Energy breaks bonds\nStep 3: Solid becomes liquid","steps":["Step 1: Temperature stays constant","Step 2: Energy breaks bonds","Step 3: Solid becomes liquid"],"options":[],"conceptId":"chemistry_matter_phase_changes_advanced","skillId":"chemistry_matter","subskillId":"chemistry_matter_q3","subject":"chemistry","chapter":"matter","topic":"Phase Changes (Advanced)"}', 2),
  (1529, 388, 'Warm water at 25°C is placed in a room at 10°C. After time, what happens?', 'text', 1, 'Focus on the core principle of Phase Changes (Advanced).', '{"why":"Heat transfer","sol":"Step 1: Heat flows from water to room\nStep 2: Water loses energy\nStep 3: Temperature decreases gradually\nStep 4: Final temperature = 10°C (thermal equilibrium)","steps":["Step 1: Heat flows from water to room","Step 2: Water loses energy","Step 3: Temperature decreases gradually","Step 4: Final temperature = 10°C (thermal equilibrium)"],"options":[],"conceptId":"chemistry_matter_phase_changes_advanced","skillId":"chemistry_matter","subskillId":"chemistry_matter_q4","subject":"chemistry","chapter":"matter","topic":"Phase Changes (Advanced)"}', 3),
  (1530, 388, 'If water cools from 25°C to 15°C, calculate heat lost (m=1kg, c=4200)', 'text', 1, 'Focus on the core principle of Phase Changes (Advanced).', '{"why":"Cooling calculation","sol":"Step 1: Q = mcΔT\nStep 2: ΔT = 25 - 15 = 10\nStep 3: Q = 1 × 4200 × 10\nStep 4: Q = 42000 J","steps":["Step 1: Q = mcΔT","Step 2: ΔT = 25 - 15 = 10","Step 3: Q = 1 × 4200 × 10","Step 4: Q = 42000 J"],"options":[],"conceptId":"chemistry_matter_phase_changes_advanced","skillId":"chemistry_matter","subskillId":"chemistry_matter_q5","subject":"chemistry","chapter":"matter","topic":"Phase Changes (Advanced)"}', 4),
  (1531, 389, 'What is a mixture?', 'text', 1, 'Focus on the core principle of Elements compounds mixtures.', '{"why":"Definition","sol":"Step 1: Substances are combined\nStep 2: Not chemically bonded\nStep 3: Can be separated physically","steps":["Step 1: Substances are combined","Step 2: Not chemically bonded","Step 3: Can be separated physically"],"options":[],"conceptId":"chemistry_matter_elements_compounds_mixtures","skillId":"chemistry_matter","subskillId":"chemistry_matter_q1","subject":"chemistry","chapter":"matter","topic":"Elements compounds mixtures"}', 0),
  (1532, 389, 'Differentiate between homogeneous and heterogeneous mixtures', 'text', 1, 'Focus on the core principle of Elements compounds mixtures.', '{"why":"Concept comparison","sol":"Step 1: Homogeneous is uniform\nStep 2: Heterogeneous is not uniform","steps":["Step 1: Homogeneous is uniform","Step 2: Heterogeneous is not uniform"],"options":[],"conceptId":"chemistry_matter_elements_compounds_mixtures","skillId":"chemistry_matter","subskillId":"chemistry_matter_q2","subject":"chemistry","chapter":"matter","topic":"Elements compounds mixtures"}', 1),
  (1533, 389, 'A student accidentally mixes iron filings, sand, salt, and sulphur. Describe how to separate the mixture.', 'text', 1, 'Focus on the core principle of Elements compounds mixtures.', '{"why":"Uses different physical properties","sol":"Step 1: Use a magnet to remove iron filings (magnetic)\nStep 2: Add water to dissolve salt (salt is soluble)\nStep 3: Filter the mixture to separate sand and sulphur from salt solution\nStep 4: Evaporate the filtrate to obtain salt\nStep 5: Separate sand and sulphur manually or using a suitable solvent (if needed)","steps":["Step 1: Use a magnet to remove iron filings (magnetic)","Step 2: Add water to dissolve salt (salt is soluble)","Step 3: Filter the mixture to separate sand and sulphur from salt solution","Step 4: Evaporate the filtrate to obtain salt","Step 5: Separate sand and sulphur manually or using a suitable solvent (if needed)"],"options":[],"conceptId":"chemistry_matter_elements_compounds_mixtures","skillId":"chemistry_matter","subskillId":"chemistry_matter_q3","subject":"chemistry","chapter":"matter","topic":"Elements compounds mixtures"}', 2),
  (1534, 389, 'Why is filtration used to separate sand and water?', 'text', 1, 'Focus on the core principle of Elements compounds mixtures.', '{"why":"Property-based separation","sol":"Step 1: Sand is insoluble\nStep 2: Water passes through filter","steps":["Step 1: Sand is insoluble","Step 2: Water passes through filter"],"options":[],"conceptId":"chemistry_matter_elements_compounds_mixtures","skillId":"chemistry_matter","subskillId":"chemistry_matter_q4","subject":"chemistry","chapter":"matter","topic":"Elements compounds mixtures"}', 3),
  (1535, 389, 'Why is evaporation used to obtain salt from salt solution?', 'text', 1, 'Focus on the core principle of Elements compounds mixtures.', '{"why":"Difference in volatility","sol":"Step 1: Heat solution\nStep 2: Water evaporates\nStep 3: Salt remains","steps":["Step 1: Heat solution","Step 2: Water evaporates","Step 3: Salt remains"],"options":[],"conceptId":"chemistry_matter_elements_compounds_mixtures","skillId":"chemistry_matter","subskillId":"chemistry_matter_q5","subject":"chemistry","chapter":"matter","topic":"Elements compounds mixtures"}', 4),
  (1536, 390, 'Give 5 examples of physical changes.', 'text', 1, 'Focus on the core principle of Physical and chemical changes.', '{"why":"All involve change in form only","sol":"Step 1: Identify state or shape changes\nStep 2: Ensure no new substance forms\nStep 3: List common examples","steps":["Step 1: Identify state or shape changes","Step 2: Ensure no new substance forms","Step 3: List common examples"],"options":[],"conceptId":"chemistry_matter_physical_and_chemical_changes","skillId":"chemistry_matter","subskillId":"chemistry_matter_q1","subject":"chemistry","chapter":"matter","topic":"Physical and chemical changes"}', 0),
  (1537, 390, 'Give 5 examples of chemical changes.', 'text', 1, 'Focus on the core principle of Physical and chemical changes.', '{"why":"All produce new substances","sol":"Step 1: Identify reactions forming new substances\nStep 2: Look for irreversible processes\nStep 3: List examples","steps":["Step 1: Identify reactions forming new substances","Step 2: Look for irreversible processes","Step 3: List examples"],"options":[],"conceptId":"chemistry_matter_physical_and_chemical_changes","skillId":"chemistry_matter","subskillId":"chemistry_matter_q2","subject":"chemistry","chapter":"matter","topic":"Physical and chemical changes"}', 1),
  (1538, 390, 'Why is cooking food a chemical change?', 'text', 1, 'Focus on the core principle of Physical and chemical changes.', '{"why":"Chemical composition changes permanently","sol":"Step 1: Identify heat application\nStep 2: Check for new substances\nStep 3: Confirm irreversibility","steps":["Step 1: Identify heat application","Step 2: Check for new substances","Step 3: Confirm irreversibility"],"options":[],"conceptId":"chemistry_matter_physical_and_chemical_changes","skillId":"chemistry_matter","subskillId":"chemistry_matter_q3","subject":"chemistry","chapter":"matter","topic":"Physical and chemical changes"}', 2),
  (1539, 390, 'Why is crushing a can a physical change?', 'text', 1, 'Focus on the core principle of Physical and chemical changes.', '{"why":"Only physical structure is affected","sol":"Step 1: Observe shape change\nStep 2: Check if new substance forms\nStep 3: Confirm reversibility","steps":["Step 1: Observe shape change","Step 2: Check if new substance forms","Step 3: Confirm reversibility"],"options":[],"conceptId":"chemistry_matter_physical_and_chemical_changes","skillId":"chemistry_matter","subskillId":"chemistry_matter_q4","subject":"chemistry","chapter":"matter","topic":"Physical and chemical changes"}', 3),
  (1540, 390, 'State one similarity between physical and chemical changes.', 'text', 1, 'Focus on the core principle of Physical and chemical changes.', '{"why":"Energy is involved in both processes","sol":"Step 1: Compare both processes\nStep 2: Identify energy involvement\nStep 3: Give common feature","steps":["Step 1: Compare both processes","Step 2: Identify energy involvement","Step 3: Give common feature"],"options":[],"conceptId":"chemistry_matter_physical_and_chemical_changes","skillId":"chemistry_matter","subskillId":"chemistry_matter_q5","subject":"chemistry","chapter":"matter","topic":"Physical and chemical changes"}', 4),
  (1541, 391, 'What is electron arrangement?', 'text', 1, 'Focus on the core principle of Atomic Structure and Electron Arrangement.', '{"why":"Structure of atom","sol":"Step 1: Electrons are arranged in shells\nStep 2: Each shell has a fixed capacity\nStep 3: Electrons fill from inner to outer shells","steps":["Step 1: Electrons are arranged in shells","Step 2: Each shell has a fixed capacity","Step 3: Electrons fill from inner to outer shells"],"options":[],"conceptId":"chemistry_atoms_atomic_structure_and_electron_arrangement","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q1","subject":"chemistry","chapter":"atoms","topic":"Atomic Structure and Electron Arrangement"}', 0),
  (1542, 391, 'What is the maximum number of electrons in the first shell?', 'text', 1, 'Focus on the core principle of Atomic Structure and Electron Arrangement.', '{"why":"Shell rule","sol":"Step 1: Identify K shell\nStep 2: Apply rule","steps":["Step 1: Identify K shell","Step 2: Apply rule"],"options":[],"conceptId":"chemistry_atoms_atomic_structure_and_electron_arrangement","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q2","subject":"chemistry","chapter":"atoms","topic":"Atomic Structure and Electron Arrangement"}', 1),
  (1543, 391, 'Why are electrons arranged in shells?', 'text', 1, 'Focus on the core principle of Atomic Structure and Electron Arrangement.', '{"why":"Energy stability","sol":"Step 1: Electrons have energy levels\nStep 2: They occupy fixed regions\nStep 3: Lower energy shells fill first","steps":["Step 1: Electrons have energy levels","Step 2: They occupy fixed regions","Step 3: Lower energy shells fill first"],"options":[],"conceptId":"chemistry_atoms_atomic_structure_and_electron_arrangement","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q3","subject":"chemistry","chapter":"atoms","topic":"Atomic Structure and Electron Arrangement"}', 2),
  (1544, 391, 'Write electron arrangement for oxygen', 'text', 1, 'Focus on the core principle of Atomic Structure and Electron Arrangement.', '{"why":"Shell filling rule","sol":"Step 1: Oxygen has 8 electrons\nStep 2: Fill K shell = 2\nStep 3: Remaining = 6 in L shell","steps":["Step 1: Oxygen has 8 electrons","Step 2: Fill K shell = 2","Step 3: Remaining = 6 in L shell"],"options":[],"conceptId":"chemistry_atoms_atomic_structure_and_electron_arrangement","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q4","subject":"chemistry","chapter":"atoms","topic":"Atomic Structure and Electron Arrangement"}', 3),
  (1545, 392, 'What is an atomic orbital?', 'text', 1, 'Think about probability regions rather than fixed tracks', '{"why":"Definition of an atomic orbital based on quantum mechanics.","sol":"Step 1: Identify that electrons do not move in fixed orbits.\nStep 2: Define orbital as a 3D region of space.\nStep 3: State that it represents high probability (90%+) of finding an electron.","steps":["Step 1: Identify that electrons do not move in fixed orbits.","Step 2: Define orbital as a 3D region of space.","Step 3: State that it represents high probability (90%+) of finding an electron."],"options":[],"conceptId":"chemistry_atoms_atomic_orbitals_and_electron_configurations","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q1","subject":"chemistry","chapter":"atoms","topic":"Atomic Orbitals and Electron Configurations"}', 0),
  (1546, 392, 'What are the shapes of s and p orbitals?', 'text', 1, 's is symmetrical in all directions, p extends along axes', '{"why":"s orbitals are spherically symmetrical; p orbitals have two lobes creating a dumbbell shape along spatial axes.","sol":"Step 1: Recall the shape of the s energy level orbitals.\nStep 2: Recall the shape of the p energy level orbitals.","steps":["Step 1: Recall the shape of the s energy level orbitals.","Step 2: Recall the shape of the p energy level orbitals."],"options":[],"conceptId":"chemistry_atoms_atomic_orbitals_and_electron_configurations","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q2","subject":"chemistry","chapter":"atoms","topic":"Atomic Orbitals and Electron Configurations"}', 1),
  (1547, 392, 'What is the maximum number of electrons that can occupy the p energy level?', 'text', 1, 'The p energy level contains 3 orbitals, and each orbital holds up to 2 electrons.', '{"why":"The p energy level has 3 orbitals (px, py, pz). Each orbital holds 2 electrons, giving 3 x 2 = 6 electrons total.","sol":"Step 1: Determine number of orbitals in the p energy level = 3.\nStep 2: Multiply by maximum capacity per orbital (2 electrons).\nStep 3: 3 x 2 = 6 electrons.","steps":["Step 1: Determine number of orbitals in the p energy level = 3.","Step 2: Multiply by maximum capacity per orbital (2 electrons).","Step 3: 3 x 2 = 6 electrons."],"options":[],"conceptId":"chemistry_atoms_atomic_orbitals_and_electron_configurations","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q3","subject":"chemistry","chapter":"atoms","topic":"Atomic Orbitals and Electron Configurations"}', 2),
  (1548, 392, 'State the Aufbau principle.', 'text', 1, 'Focus on the energy order in which orbitals are filled.', '{"why":"The Aufbau principle dictates that electron configurations build up from the lowest energy level outward.","sol":"Step 1: Consider how electrons build up in an atom.\nStep 2: State that lower energy levels fill before higher energy levels.","steps":["Step 1: Consider how electrons build up in an atom.","Step 2: State that lower energy levels fill before higher energy levels."],"options":[],"conceptId":"chemistry_atoms_atomic_orbitals_and_electron_configurations","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q4","subject":"chemistry","chapter":"atoms","topic":"Atomic Orbitals and Electron Configurations"}', 3),
  (1549, 392, 'Write the full electron configuration for a neutral sodium atom (atomic number 11).', 'text', 1, 'Fill energy levels in order: 1s, 2s, 2p, 3s until you reach 11 electrons.', '{"why":"1s holds 2, 2s holds 2, 2p holds 6, and 3s holds the 11th electron, totaling 1s² 2s² 2p⁶ 3s¹.","sol":"Step 1: Total electrons for Na = 11.\nStep 2: Fill 1s with 2 electrons -> 1s² (9 remaining).\nStep 3: Fill 2s with 2 electrons -> 2s² (7 remaining).\nStep 4: Fill 2p with 6 electrons -> 2p⁶ (1 remaining).\nStep 5: Place final electron in 3s -> 3s¹.","steps":["Step 1: Total electrons for Na = 11.","Step 2: Fill 1s with 2 electrons -> 1s² (9 remaining).","Step 3: Fill 2s with 2 electrons -> 2s² (7 remaining).","Step 4: Fill 2p with 6 electrons -> 2p⁶ (1 remaining).","Step 5: Place final electron in 3s -> 3s¹."],"options":[],"conceptId":"chemistry_atoms_atomic_orbitals_and_electron_configurations","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q5","subject":"chemistry","chapter":"atoms","topic":"Atomic Orbitals and Electron Configurations"}', 4),
  (1550, 392, 'Why does the 4s energy level fill before the 3d energy level?', 'text', 1, 'Compare the relative energies of the 4s and 3d energy levels.', '{"why":"According to the Aufbau principle, orbitals fill in order of increasing energy. 4s is slightly lower in energy than 3d, so it fills first.","sol":"Step 1: Compare energy of 4s and 3d energy levels.\nStep 2: Apply the Aufbau principle.\nStep 3: 4s has lower energy than 3d in uncharged atoms.","steps":["Step 1: Compare energy of 4s and 3d energy levels.","Step 2: Apply the Aufbau principle.","Step 3: 4s has lower energy than 3d in uncharged atoms."],"options":[],"conceptId":"chemistry_atoms_atomic_orbitals_and_electron_configurations","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q6","subject":"chemistry","chapter":"atoms","topic":"Atomic Orbitals and Electron Configurations"}', 5),
  (1551, 393, 'What is atomic number?', 'text', 1, 'Focus on the core principle of Mass Number and Atomic Number.', '{"why":"Element identity","sol":"Step 1: Count protons in nucleus\nStep 2: That number defines element\nStep 3: It is called atomic number","steps":["Step 1: Count protons in nucleus","Step 2: That number defines element","Step 3: It is called atomic number"],"options":[],"conceptId":"chemistry_atoms_mass_number_and_atomic_number","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q1","subject":"chemistry","chapter":"atoms","topic":"Mass Number and Atomic Number"}', 0),
  (1552, 393, 'What is mass number?', 'text', 1, 'Focus on the core principle of Mass Number and Atomic Number.', '{"why":"Nuclear structure","sol":"Step 1: Add protons and neutrons\nStep 2: This gives total nuclear particles","steps":["Step 1: Add protons and neutrons","Step 2: This gives total nuclear particles"],"options":[],"conceptId":"chemistry_atoms_mass_number_and_atomic_number","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q2","subject":"chemistry","chapter":"atoms","topic":"Mass Number and Atomic Number"}', 1),
  (1553, 393, 'An atom has 8 protons and 10 neutrons. Find atomic and mass number.', 'text', 1, 'Focus on the core principle of Mass Number and Atomic Number.', '{"why":"Calculation using formulas","sol":"Step 1: Atomic number = protons = 8\nStep 2: Mass number = 8 + 10 = 18","steps":["Step 1: Atomic number = protons = 8","Step 2: Mass number = 8 + 10 = 18"],"options":[],"conceptId":"chemistry_atoms_mass_number_and_atomic_number","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q3","subject":"chemistry","chapter":"atoms","topic":"Mass Number and Atomic Number"}', 2),
  (1554, 393, 'How do you find neutrons in an atom?', 'text', 1, 'Focus on the core principle of Mass Number and Atomic Number.', '{"why":"Formula derivation","sol":"Step 1: Identify mass number\nStep 2: Subtract atomic number","steps":["Step 1: Identify mass number","Step 2: Subtract atomic number"],"options":[],"conceptId":"chemistry_atoms_mass_number_and_atomic_number","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q4","subject":"chemistry","chapter":"atoms","topic":"Mass Number and Atomic Number"}', 3),
  (1555, 394, 'What are isotopes?', 'text', 1, 'Focus on the core principle of Isotopes.', '{"why":"Definition","sol":"Step 1: Same element\nStep 2: Same protons\nStep 3: Different neutrons","steps":["Step 1: Same element","Step 2: Same protons","Step 3: Different neutrons"],"options":[],"conceptId":"chemistry_atoms_isotopes","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q1","subject":"chemistry","chapter":"atoms","topic":"Isotopes"}', 0),
  (1556, 394, 'Why do isotopes have the same chemical properties?', 'text', 1, 'Focus on the core principle of Isotopes.', '{"why":"Electron structure","sol":"Step 1: Chemical behavior depends on electrons\nStep 2: Isotopes have same electrons\nStep 3: Therefore same reactions","steps":["Step 1: Chemical behavior depends on electrons","Step 2: Isotopes have same electrons","Step 3: Therefore same reactions"],"options":[],"conceptId":"chemistry_atoms_isotopes","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q2","subject":"chemistry","chapter":"atoms","topic":"Isotopes"}', 1),
  (1557, 394, 'What is the difference between Carbon-12 and Carbon-14?', 'text', 1, 'Focus on the core principle of Isotopes.', '{"why":"Mass difference","sol":"Step 1: Both have 6 protons\nStep 2: C-12 has 6 neutrons\nStep 3: C-14 has 8 neutrons","steps":["Step 1: Both have 6 protons","Step 2: C-12 has 6 neutrons","Step 3: C-14 has 8 neutrons"],"options":[],"conceptId":"chemistry_atoms_isotopes","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q3","subject":"chemistry","chapter":"atoms","topic":"Isotopes"}', 2),
  (1558, 394, 'State two properties of isotopes', 'text', 1, 'think protons and neutrons', '{"why":"Definition","sol":"Step 1: Same element\nStep 2: Different neutrons","steps":["Step 1: Same element","Step 2: Different neutrons"],"options":[],"conceptId":"chemistry_atoms_isotopes","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q4","subject":"chemistry","chapter":"atoms","topic":"Isotopes"}', 3),
  (1559, 394, 'Why are isotopes of chlorine chemically similar?', 'text', 1, 'electrons', '{"why":"Chemical behavior","sol":"Step 1: Same atomic number\nStep 2: Same electrons","steps":["Step 1: Same atomic number","Step 2: Same electrons"],"options":[],"conceptId":"chemistry_atoms_isotopes","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q5","subject":"chemistry","chapter":"atoms","topic":"Isotopes"}', 4),
  (1560, 395, 'What is an ion?', 'text', 1, 'Focus on the core principle of Ion Formation.', '{"why":"Definition","sol":"Step 1: Start with atom\nStep 2: Gain or lose electrons\nStep 3: Become charged","steps":["Step 1: Start with atom","Step 2: Gain or lose electrons","Step 3: Become charged"],"options":[],"conceptId":"chemistry_atoms_ion_formation","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q1","subject":"chemistry","chapter":"atoms","topic":"Ion Formation"}', 0),
  (1561, 395, 'What is a cation?', 'text', 1, 'Focus on the core principle of Ion Formation.', '{"why":"Electron loss","sol":"Step 1: Atom loses electrons\nStep 2: More protons than electrons\nStep 3: Positive charge formed","steps":["Step 1: Atom loses electrons","Step 2: More protons than electrons","Step 3: Positive charge formed"],"options":[],"conceptId":"chemistry_atoms_ion_formation","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q2","subject":"chemistry","chapter":"atoms","topic":"Ion Formation"}', 1),
  (1562, 395, 'What is an anion?', 'text', 1, 'Focus on the core principle of Ion Formation.', '{"why":"Electron gain","sol":"Step 1: Atom gains electrons\nStep 2: More electrons than protons\nStep 3: Negative charge formed","steps":["Step 1: Atom gains electrons","Step 2: More electrons than protons","Step 3: Negative charge formed"],"options":[],"conceptId":"chemistry_atoms_ion_formation","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q3","subject":"chemistry","chapter":"atoms","topic":"Ion Formation"}', 2),
  (1563, 395, 'How is Na⁺ formed?', 'text', 1, 'electron loss', '{"why":"Cation formation","sol":"Step 1: Sodium has 11 electrons\nStep 2: Loses 1 electron\nStep 3: Becomes Na⁺","steps":["Step 1: Sodium has 11 electrons","Step 2: Loses 1 electron","Step 3: Becomes Na⁺"],"options":[],"conceptId":"chemistry_atoms_ion_formation","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q4","subject":"chemistry","chapter":"atoms","topic":"Ion Formation"}', 3),
  (1564, 395, 'How is Cl⁻ formed?', 'text', 1, 'electron gain', '{"why":"Anion formation","sol":"Step 1: Chlorine has 17 electrons\nStep 2: Gains 1 electron\nStep 3: Becomes Cl⁻","steps":["Step 1: Chlorine has 17 electrons","Step 2: Gains 1 electron","Step 3: Becomes Cl⁻"],"options":[],"conceptId":"chemistry_atoms_ion_formation","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q5","subject":"chemistry","chapter":"atoms","topic":"Ion Formation"}', 4),
  (1565, 395, 'Why is Mg²⁺ formed?', 'text', 1, 'loses two electrons', '{"why":"Charge increase","sol":"Step 1: Magnesium has 12 electrons\nStep 2: Loses 2 electrons\nStep 3: Becomes Mg²⁺","steps":["Step 1: Magnesium has 12 electrons","Step 2: Loses 2 electrons","Step 3: Becomes Mg²⁺"],"options":[],"conceptId":"chemistry_atoms_ion_formation","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q6","subject":"chemistry","chapter":"atoms","topic":"Ion Formation"}', 5),
  (1566, 396, 'What is the periodic table?', 'text', 1, 'Focus on the core principle of Periodic Table and Periodicity.', '{"why":"Definition","sol":"Step 1: Arrangement of elements\nStep 2: Based on atomic number\nStep 3: Similar properties grouped","steps":["Step 1: Arrangement of elements","Step 2: Based on atomic number","Step 3: Similar properties grouped"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q1","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 0),
  (1567, 396, 'Why are elements in the same group similar?', 'text', 1, 'Focus on the core principle of Periodic Table and Periodicity.', '{"why":"Electron structure","sol":"Step 1: Same number of valence electrons\nStep 2: Similar chemical behavior","steps":["Step 1: Same number of valence electrons","Step 2: Similar chemical behavior"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q2","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 1),
  (1568, 396, 'Which element has the largest atomic radius: Na, Mg, Al, Cl?', 'text', 1, 'Focus on the core principle of Periodic Table and Periodicity.', '{"why":"Trend across period","sol":"Step 1: All are in same period\nStep 2: Atomic radius decreases across period\nStep 3: Na is farthest left","steps":["Step 1: All are in same period","Step 2: Atomic radius decreases across period","Step 3: Na is farthest left"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q3","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 2),
  (1569, 396, 'Which element is most likely to form a chloride ion?', 'text', 1, 'Focus on the core principle of Periodic Table and Periodicity.', '{"why":"Halogen behavior","sol":"Step 1: Look for non-metal in Group 17\nStep 2: Chlorine gains electron easily","steps":["Step 1: Look for non-metal in Group 17","Step 2: Chlorine gains electron easily"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q4","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 3),
  (1570, 396, 'Which two elements react to form a salt?', 'text', 1, 'Focus on the core principle of Periodic Table and Periodicity.', '{"why":"Ionic compound formation","sol":"Step 1: Metal + Non-metal\nStep 2: Example sodium + chlorine\nStep 3: Forms NaCl","steps":["Step 1: Metal + Non-metal","Step 2: Example sodium + chlorine","Step 3: Forms NaCl"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q5","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 4),
  (1571, 396, 'Compare reactivity of Group 1 elements down the group', 'text', 1, 'Focus on the core principle of Periodic Table and Periodicity.', '{"why":"Electron distance effect","sol":"Step 1: Atoms get larger\nStep 2: Outer electron is easier to lose\nStep 3: Reactivity increases","steps":["Step 1: Atoms get larger","Step 2: Outer electron is easier to lose","Step 3: Reactivity increases"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q6","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 5),
  (1572, 396, 'Why are noble gases unreactive?', 'text', 1, 'outer shell', '{"why":"Stability","sol":"Step 1: Full outer shell\nStep 2: No need to gain or lose electrons","steps":["Step 1: Full outer shell","Step 2: No need to gain or lose electrons"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q7","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 6),
  (1573, 396, 'Which element forms a -1 ion easily?', 'text', 1, 'halogen', '{"why":"Electron gain","sol":"Step 1: Group 17 elements\nStep 2: Gain 1 electron","steps":["Step 1: Group 17 elements","Step 2: Gain 1 electron"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q8","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 7),
  (1574, 396, 'Arrange Na, Mg, Al in order of increasing atomic radius', 'text', 1, 'across period', '{"why":"Periodic trend","sol":"Step 1: radius decreases across period\nStep 2: Al < Mg < Na","steps":["Step 1: radius decreases across period","Step 2: Al < Mg < Na"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q9","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 8),
  (1575, 397, 'What is chemical bonding?', 'text', 1, 'Focus on the core principle of Chemical bonding.', '{"why":"Atoms bond to become stable","sol":"Step 1: Atoms come close together\nStep 2: They interact through electrons\nStep 3: A force holds them together","steps":["Step 1: Atoms come close together","Step 2: They interact through electrons","Step 3: A force holds them together"],"options":[],"conceptId":"chemistry_bonding_chemical_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q1","subject":"chemistry","chapter":"bonding","topic":"Chemical bonding"}', 0),
  (1576, 397, 'What happens during ionic bonding?', 'text', 1, 'Focus on the core principle of Chemical bonding.', '{"why":"Electrostatic attraction forms the bond","sol":"Step 1: Metal loses electrons\nStep 2: Non-metal gains electrons\nStep 3: Opposite charges attract","steps":["Step 1: Metal loses electrons","Step 2: Non-metal gains electrons","Step 3: Opposite charges attract"],"options":[],"conceptId":"chemistry_bonding_chemical_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q2","subject":"chemistry","chapter":"bonding","topic":"Chemical bonding"}', 1),
  (1577, 397, 'What happens during covalent bonding?', 'text', 1, 'Focus on the core principle of Chemical bonding.', '{"why":"Sharing leads to stability","sol":"Step 1: Two non-metals approach\nStep 2: They share electrons\nStep 3: Shared electrons complete outer shells","steps":["Step 1: Two non-metals approach","Step 2: They share electrons","Step 3: Shared electrons complete outer shells"],"options":[],"conceptId":"chemistry_bonding_chemical_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q3","subject":"chemistry","chapter":"bonding","topic":"Chemical bonding"}', 2),
  (1578, 397, 'Which type of bonding involves transfer of electrons?', 'text', 1, 'metal + non-metal', '{"why":"Electron transfer creates charged ions","sol":"Step 1: One atom loses electrons\nStep 2: Another gains electrons\nStep 3: Ions form","steps":["Step 1: One atom loses electrons","Step 2: Another gains electrons","Step 3: Ions form"],"options":[],"conceptId":"chemistry_bonding_chemical_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q4","subject":"chemistry","chapter":"bonding","topic":"Chemical bonding"}', 3),
  (1579, 397, 'Which type of bonding involves sharing electrons?', 'text', 1, 'non-metal + non-metal', '{"why":"Sharing fills outer shells","sol":"Step 1: Atoms approach\nStep 2: Share electrons\nStep 3: Form molecule","steps":["Step 1: Atoms approach","Step 2: Share electrons","Step 3: Form molecule"],"options":[],"conceptId":"chemistry_bonding_chemical_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q5","subject":"chemistry","chapter":"bonding","topic":"Chemical bonding"}', 4),
  (1580, 397, 'Why are noble gases unreactive?', 'text', 1, 'Focus on the core principle of Chemical bonding.', '{"why":"Stable electronic configuration","sol":"Step 1: Outer shell is full\nStep 2: No need to gain or lose electrons\nStep 3: No bonding required","steps":["Step 1: Outer shell is full","Step 2: No need to gain or lose electrons","Step 3: No bonding required"],"options":[],"conceptId":"chemistry_bonding_chemical_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q6","subject":"chemistry","chapter":"bonding","topic":"Chemical bonding"}', 5),
  (1581, 398, 'What is ionic bonding?', 'text', 1, 'Focus on the core principle of Ionic bonding.', '{"why":"Opposite charges create strong attraction","sol":"Step 1: Identify two atoms (metal and non-metal)\nStep 2: Electron is transferred from metal to non-metal\nStep 3: Oppositely charged ions form\nStep 4: Ions attract each other","steps":["Step 1: Identify two atoms (metal and non-metal)","Step 2: Electron is transferred from metal to non-metal","Step 3: Oppositely charged ions form","Step 4: Ions attract each other"],"options":[],"conceptId":"chemistry_bonding_ionic_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q1","subject":"chemistry","chapter":"bonding","topic":"Ionic bonding"}', 0),
  (1582, 398, 'Why does ionic bonding occur between metals and non-metals?', 'text', 1, 'Focus on the core principle of Ionic bonding.', '{"why":"Both achieve stable electron configuration","sol":"Step 1: Metals have few outer electrons\nStep 2: They lose electrons easily\nStep 3: Non-metals need electrons to complete outer shell\nStep 4: Electron transfer happens","steps":["Step 1: Metals have few outer electrons","Step 2: They lose electrons easily","Step 3: Non-metals need electrons to complete outer shell","Step 4: Electron transfer happens"],"options":[],"conceptId":"chemistry_bonding_ionic_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q2","subject":"chemistry","chapter":"bonding","topic":"Ionic bonding"}', 1),
  (1583, 398, 'Explain step-by-step formation of NaCl', 'text', 1, 'Focus on the core principle of Ionic bonding.', '{"why":"Opposite ions attract strongly","sol":"Step 1: Sodium has 1 valence electron\nStep 2: Sodium loses 1 electron → Na⁺\nStep 3: Chlorine has 7 valence electrons\nStep 4: Chlorine gains 1 electron → Cl⁻\nStep 5: Na⁺ and Cl⁻ attract each other\nStep 6: Ionic bond forms NaCl crystal","steps":["Step 1: Sodium has 1 valence electron","Step 2: Sodium loses 1 electron → Na⁺","Step 3: Chlorine has 7 valence electrons","Step 4: Chlorine gains 1 electron → Cl⁻","Step 5: Na⁺ and Cl⁻ attract each other","Step 6: Ionic bond forms NaCl crystal"],"options":[],"conceptId":"chemistry_bonding_ionic_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q3","subject":"chemistry","chapter":"bonding","topic":"Ionic bonding"}', 2),
  (1584, 398, 'Why is NaCl electrically neutral overall?', 'text', 1, 'charges cancel', '{"why":"Total charge becomes zero","sol":"Step 1: Na becomes +1\nStep 2: Cl becomes -1\nStep 3: Charges balance out","steps":["Step 1: Na becomes +1","Step 2: Cl becomes -1","Step 3: Charges balance out"],"options":[],"conceptId":"chemistry_bonding_ionic_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q4","subject":"chemistry","chapter":"bonding","topic":"Ionic bonding"}', 3),
  (1585, 398, 'Explain why ionic compounds form crystal structures', 'text', 1, 'Focus on the core principle of Ionic bonding.', '{"why":"Ions arrange in a stable repeating structure","sol":"Step 1: Ions attract in all directions\nStep 2: Repeating pattern forms\nStep 3: Strong lattice structure develops","steps":["Step 1: Ions attract in all directions","Step 2: Repeating pattern forms","Step 3: Strong lattice structure develops"],"options":[],"conceptId":"chemistry_bonding_ionic_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q5","subject":"chemistry","chapter":"bonding","topic":"Ionic bonding"}', 4),
  (1586, 398, 'Predict what happens when magnesium reacts with chlorine', 'text', 1, 'Focus on the core principle of Ionic bonding.', '{"why":"Charge balance determines formula","sol":"Step 1: Magnesium loses 2 electrons → Mg²⁺\nStep 2: Chlorine gains 1 electron → Cl⁻\nStep 3: Two Cl atoms needed for balance\nStep 4: Mg²⁺ + 2Cl⁻ → MgCl₂","steps":["Step 1: Magnesium loses 2 electrons → Mg²⁺","Step 2: Chlorine gains 1 electron → Cl⁻","Step 3: Two Cl atoms needed for balance","Step 4: Mg²⁺ + 2Cl⁻ → MgCl₂"],"options":[],"conceptId":"chemistry_bonding_ionic_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q6","subject":"chemistry","chapter":"bonding","topic":"Ionic bonding"}', 5),
  (1587, 399, 'What is covalent bonding?', 'text', 1, 'Focus on the core principle of Covalent bonding.', '{"why":"Sharing allows atoms to complete outer shells","sol":"Step 1: Identify two non-metal atoms\nStep 2: Each atom needs electrons\nStep 3: They share electrons instead of transferring\nStep 4: Shared electrons form a bond","steps":["Step 1: Identify two non-metal atoms","Step 2: Each atom needs electrons","Step 3: They share electrons instead of transferring","Step 4: Shared electrons form a bond"],"options":[],"conceptId":"chemistry_bonding_covalent_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q1","subject":"chemistry","chapter":"bonding","topic":"Covalent bonding"}', 0),
  (1588, 399, 'Why does covalent bonding occur between non-metals?', 'text', 1, 'Focus on the core principle of Covalent bonding.', '{"why":"Electron sharing is energetically favorable","sol":"Step 1: Non-metals have nearly full outer shells\nStep 2: They need a few electrons\nStep 3: Losing electrons is difficult\nStep 4: Sharing is easier than transfer","steps":["Step 1: Non-metals have nearly full outer shells","Step 2: They need a few electrons","Step 3: Losing electrons is difficult","Step 4: Sharing is easier than transfer"],"options":[],"conceptId":"chemistry_bonding_covalent_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q2","subject":"chemistry","chapter":"bonding","topic":"Covalent bonding"}', 1),
  (1589, 399, 'What is a single covalent bond?', 'text', 1, 'Focus on the core principle of Covalent bonding.', '{"why":"One shared pair creates a single bond","sol":"Step 1: Two atoms approach\nStep 2: They share one pair of electrons\nStep 3: Bond holds atoms together","steps":["Step 1: Two atoms approach","Step 2: They share one pair of electrons","Step 3: Bond holds atoms together"],"options":[],"conceptId":"chemistry_bonding_covalent_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q3","subject":"chemistry","chapter":"bonding","topic":"Covalent bonding"}', 2),
  (1590, 399, 'Which is stronger: single, double, or triple bond?', 'text', 1, 'more sharing = stronger', '{"why":"More shared electrons increase bond strength","sol":"Step 1: compare electron pairs\nStep 2: single = 1 pair\nStep 3: double = 2 pairs\nStep 4: triple = 3 pairs","steps":["Step 1: compare electron pairs","Step 2: single = 1 pair","Step 3: double = 2 pairs","Step 4: triple = 3 pairs"],"options":[],"conceptId":"chemistry_bonding_covalent_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q4","subject":"chemistry","chapter":"bonding","topic":"Covalent bonding"}', 3),
  (1591, 399, 'Explain why O₂ has a double bond', 'text', 1, 'Focus on the core principle of Covalent bonding.', '{"why":"Each oxygen needs 2 electrons for stability","sol":"Step 1: Oxygen has 6 outer electrons\nStep 2: Needs 2 more to complete octet\nStep 3: Two oxygen atoms share 2 pairs\nStep 4: Double bond forms O₂","steps":["Step 1: Oxygen has 6 outer electrons","Step 2: Needs 2 more to complete octet","Step 3: Two oxygen atoms share 2 pairs","Step 4: Double bond forms O₂"],"options":[],"conceptId":"chemistry_bonding_covalent_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q5","subject":"chemistry","chapter":"bonding","topic":"Covalent bonding"}', 4),
  (1592, 399, 'Explain why N₂ has a triple bond', 'text', 1, 'Focus on the core principle of Covalent bonding.', '{"why":"Each nitrogen needs 3 electrons for stability","sol":"Step 1: Nitrogen has 5 outer electrons\nStep 2: Needs 3 more to complete octet\nStep 3: Two nitrogen atoms share 3 pairs\nStep 4: Strong triple bond forms","steps":["Step 1: Nitrogen has 5 outer electrons","Step 2: Needs 3 more to complete octet","Step 3: Two nitrogen atoms share 3 pairs","Step 4: Strong triple bond forms"],"options":[],"conceptId":"chemistry_bonding_covalent_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q6","subject":"chemistry","chapter":"bonding","topic":"Covalent bonding"}', 5),
  (1593, 400, 'What is the main difference between ionic and covalent bonding?', 'text', 1, 'Focus on the core principle of Ionic vs covalent.', '{"why":"Electron movement defines bonding type","sol":"Step 1: Identify electron behavior\nStep 2: Ionic involves transfer\nStep 3: Covalent involves sharing\nStep 4: Compare outcomes (ions vs molecules)","steps":["Step 1: Identify electron behavior","Step 2: Ionic involves transfer","Step 3: Covalent involves sharing","Step 4: Compare outcomes (ions vs molecules)"],"options":[],"conceptId":"chemistry_bonding_ionic_vs_covalent","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q1","subject":"chemistry","chapter":"bonding","topic":"Ionic vs covalent"}', 0),
  (1594, 400, 'Which elements form covalent bonds?', 'text', 1, 'Focus on the core principle of Ionic vs covalent.', '{"why":"Similar electronegativity leads to sharing","sol":"Step 1: Identify non-metals\nStep 2: Both need electrons\nStep 3: Neither wants to lose electrons\nStep 4: They share electrons","steps":["Step 1: Identify non-metals","Step 2: Both need electrons","Step 3: Neither wants to lose electrons","Step 4: They share electrons"],"options":[],"conceptId":"chemistry_bonding_ionic_vs_covalent","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q2","subject":"chemistry","chapter":"bonding","topic":"Ionic vs covalent"}', 1),
  (1595, 400, 'Why do ionic compounds have high melting points?', 'text', 1, 'Focus on the core principle of Ionic vs covalent.', '{"why":"Strong bonds require high energy to break","sol":"Step 1: Identify ionic lattice\nStep 2: Strong electrostatic forces\nStep 3: Requires large energy to break bonds","steps":["Step 1: Identify ionic lattice","Step 2: Strong electrostatic forces","Step 3: Requires large energy to break bonds"],"options":[],"conceptId":"chemistry_bonding_ionic_vs_covalent","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q3","subject":"chemistry","chapter":"bonding","topic":"Ionic vs covalent"}', 2),
  (1596, 400, 'Explain why NaCl is ionic but H₂ is covalent', 'text', 1, 'Focus on the core principle of Ionic vs covalent.', '{"why":"Type of elements determines bonding type","sol":"Step 1: Na is a metal, Cl is non-metal\nStep 2: electron transfer occurs → ionic bond\nStep 3: H and H are both non-metals\nStep 4: electrons are shared → covalent bond","steps":["Step 1: Na is a metal, Cl is non-metal","Step 2: electron transfer occurs → ionic bond","Step 3: H and H are both non-metals","Step 4: electrons are shared → covalent bond"],"options":[],"conceptId":"chemistry_bonding_ionic_vs_covalent","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q4","subject":"chemistry","chapter":"bonding","topic":"Ionic vs covalent"}', 3),
  (1597, 400, 'Predict bonding type in MgO and CO₂', 'text', 1, 'Focus on the core principle of Ionic vs covalent.', '{"why":"Element types determine bonding","sol":"Step 1: MgO has metal + non-metal → ionic\nStep 2: CO₂ has non-metal + non-metal → covalent","steps":["Step 1: MgO has metal + non-metal → ionic","Step 2: CO₂ has non-metal + non-metal → covalent"],"options":[],"conceptId":"chemistry_bonding_ionic_vs_covalent","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q5","subject":"chemistry","chapter":"bonding","topic":"Ionic vs covalent"}', 4),
  (1598, 401, 'A chemistry student is told that 1 mole of any substance always contains the same fixed number of particles. What is this number, and what is it called?', 'text', 1, 'Focus on the core principle of Meaning of mole.', '{"why":"The mole is defined as the amount of substance containing exactly 6.02 × 10²³ particles. This number is always the same regardless of what substance you are measuring.","sol":"Step 1: Recall that the mole is a counting unit, like ''dozen'' means 12\nStep 2: Remember the fixed number linked to 1 mole is Avogadro''s constant\nStep 3: State the value: 6.02 × 10²³ particles per mole","steps":["Step 1: Recall that the mole is a counting unit, like ''dozen'' means 12","Step 2: Remember the fixed number linked to 1 mole is Avogadro''s constant","Step 3: State the value: 6.02 × 10²³ particles per mole"],"options":[],"conceptId":"chemistry_mole_meaning_of_mole","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Meaning of mole"}', 0),
  (1599, 401, 'A sample contains 1.204 × 10²⁴ atoms of sodium. How many moles of sodium is this?', 'text', 1, 'Divide the number of particles by Avogadro''s number (6.02 × 10²³)', '{"why":"You divide by Avogadro''s constant to convert from number of particles to moles. 1.204 × 10²⁴ is exactly twice Avogadro''s number, so it equals 2 moles.","sol":"Step 1: Write the formula: n = number of particles ÷ 6.02 × 10²³\nStep 2: Substitute the values: n = 1.204 × 10²⁴ ÷ 6.02 × 10²³\nStep 3: Divide: 1.204 ÷ 6.02 = 0.2, and 10²⁴ ÷ 10²³ = 10¹ = 10\nStep 4: So n = 0.2 × 10 = 2","steps":["Step 1: Write the formula: n = number of particles ÷ 6.02 × 10²³","Step 2: Substitute the values: n = 1.204 × 10²⁴ ÷ 6.02 × 10²³","Step 3: Divide: 1.204 ÷ 6.02 = 0.2, and 10²⁴ ÷ 10²³ = 10¹ = 10","Step 4: So n = 0.2 × 10 = 2"],"options":[],"conceptId":"chemistry_mole_meaning_of_mole","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Meaning of mole"}', 1),
  (1600, 401, 'A teacher asks: ''How many individual molecules are contained in 2 moles of water (H₂O)?'' Show your working.', 'text', 1, 'Multiply the number of moles by Avogadro''s number', '{"why":"Each mole contains 6.02 × 10²³ molecules, so 2 moles contains twice that amount. Scientific notation is used because the number is extremely large.","sol":"Step 1: Write the formula: Number of particles = n × 6.02 × 10²³\nStep 2: Substitute: Number of particles = 2 × 6.02 × 10²³\nStep 3: Multiply the coefficient: 2 × 6.02 = 12.04\nStep 4: Express in standard scientific notation: 1.204 × 10²⁴","steps":["Step 1: Write the formula: Number of particles = n × 6.02 × 10²³","Step 2: Substitute: Number of particles = 2 × 6.02 × 10²³","Step 3: Multiply the coefficient: 2 × 6.02 = 12.04","Step 4: Express in standard scientific notation: 1.204 × 10²⁴"],"options":[],"conceptId":"chemistry_mole_meaning_of_mole","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Meaning of mole"}', 2),
  (1601, 401, 'A scientist measures out 3 moles of oxygen gas (O₂). How many oxygen molecules does this sample contain?', 'text', 1, 'Focus on the core principle of Meaning of mole.', '{"why":"Multiplying moles by Avogadro''s number converts from moles to individual particles. Since each mole has 6.02 × 10²³ molecules, 3 moles has 3 times that.","sol":"Step 1: Write the formula: Number of molecules = n × 6.02 × 10²³\nStep 2: Substitute: Number of molecules = 3 × 6.02 × 10²³\nStep 3: Multiply: 3 × 6.02 = 18.06\nStep 4: Write in scientific notation: 1.806 × 10²⁴ molecules","steps":["Step 1: Write the formula: Number of molecules = n × 6.02 × 10²³","Step 2: Substitute: Number of molecules = 3 × 6.02 × 10²³","Step 3: Multiply: 3 × 6.02 = 18.06","Step 4: Write in scientific notation: 1.806 × 10²⁴ molecules"],"options":[],"conceptId":"chemistry_mole_meaning_of_mole","skillId":"chemistry_mole","subskillId":"chemistry_mole_q4","subject":"chemistry","chapter":"mole","topic":"Meaning of mole"}', 3),
  (1602, 401, 'Why do chemists use the mole instead of counting atoms directly? Explain using the idea of microscopic vs macroscopic.', 'text', 1, 'Focus on the core principle of Meaning of mole.', '{"why":"Without the mole, it would be impossible to connect what we measure in the lab (grams, litres) to what is happening at the atomic level. The mole is the essential bridge.","sol":"Step 1: Recognise that atoms are too small to count individually — even 1 g of hydrogen contains ~6 × 10²³ atoms\nStep 2: The mole groups this enormous number into a manageable counting unit\nStep 3: It bridges the microscopic world (atoms) and the macroscopic world (grams on a balance scale)","steps":["Step 1: Recognise that atoms are too small to count individually — even 1 g of hydrogen contains ~6 × 10²³ atoms","Step 2: The mole groups this enormous number into a manageable counting unit","Step 3: It bridges the microscopic world (atoms) and the macroscopic world (grams on a balance scale)"],"options":[],"conceptId":"chemistry_mole_meaning_of_mole","skillId":"chemistry_mole","subskillId":"chemistry_mole_q5","subject":"chemistry","chapter":"mole","topic":"Meaning of mole"}', 4),
  (1603, 402, 'A chemist has 36 g of water (H₂O). The molar mass of water is 18 g/mol. Calculate how many moles of water are present.', 'text', 1, 'Use the formula: n = mass ÷ molar mass', '{"why":"Dividing mass by molar mass converts grams into moles. Since 36 g is exactly twice the molar mass (18 g/mol), the sample contains 2 moles.","sol":"Step 1: Write the formula: n = m ÷ M\nStep 2: Identify values: m = 36 g, M = 18 g/mol\nStep 3: Substitute: n = 36 ÷ 18\nStep 4: Calculate: n = 2 mol","steps":["Step 1: Write the formula: n = m ÷ M","Step 2: Identify values: m = 36 g, M = 18 g/mol","Step 3: Substitute: n = 36 ÷ 18","Step 4: Calculate: n = 2 mol"],"options":[],"conceptId":"chemistry_mole_mole_relationships","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Mole relationships"}', 0),
  (1604, 402, 'A student measures 0.5 moles of nitrogen gas (N₂). How many individual molecules does this sample contain?', 'text', 1, 'Multiply the number of moles by Avogadro''s number (6.02 × 10²³)', '{"why":"Half a mole contains exactly half of Avogadro''s number of particles. Moles and particle count are directly proportional.","sol":"Step 1: Write the formula: N = n × 6.02 × 10²³\nStep 2: Substitute: N = 0.5 × 6.02 × 10²³\nStep 3: Multiply: 0.5 × 6.02 = 3.01\nStep 4: Write the answer: N = 3.01 × 10²³ molecules","steps":["Step 1: Write the formula: N = n × 6.02 × 10²³","Step 2: Substitute: N = 0.5 × 6.02 × 10²³","Step 3: Multiply: 0.5 × 6.02 = 3.01","Step 4: Write the answer: N = 3.01 × 10²³ molecules"],"options":[],"conceptId":"chemistry_mole_mole_relationships","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Mole relationships"}', 1),
  (1605, 402, 'A laboratory has 2 moles of carbon dioxide (CO₂). The molar mass of CO₂ is 44 g/mol. What is the total mass of this CO₂ sample?', 'text', 1, 'Focus on the core principle of Mole relationships.', '{"why":"Multiplying moles by molar mass converts moles back into grams. Each mole of CO₂ has a mass of 44 g, so 2 moles has twice the mass.","sol":"Step 1: Write the formula: m = n × M\nStep 2: Identify values: n = 2 mol, M = 44 g/mol\nStep 3: Substitute: m = 2 × 44\nStep 4: Calculate: m = 88 g","steps":["Step 1: Write the formula: m = n × M","Step 2: Identify values: n = 2 mol, M = 44 g/mol","Step 3: Substitute: m = 2 × 44","Step 4: Calculate: m = 88 g"],"options":[],"conceptId":"chemistry_mole_mole_relationships","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Mole relationships"}', 2),
  (1606, 402, 'A sample contains 9.03 × 10²³ atoms of iron (Fe). How many moles of iron is this?', 'text', 1, 'Divide the particle count by Avogadro''s number', '{"why":"Dividing the number of particles by Avogadro''s constant gives moles. 9.03 × 10²³ is 1.5 times Avogadro''s number, so the answer is 1.5 moles.","sol":"Step 1: Write the formula: n = N ÷ 6.02 × 10²³\nStep 2: Substitute: n = 9.03 × 10²³ ÷ 6.02 × 10²³\nStep 3: Divide: 9.03 ÷ 6.02 ≈ 1.5\nStep 4: Answer: n = 1.5 mol","steps":["Step 1: Write the formula: n = N ÷ 6.02 × 10²³","Step 2: Substitute: n = 9.03 × 10²³ ÷ 6.02 × 10²³","Step 3: Divide: 9.03 ÷ 6.02 ≈ 1.5","Step 4: Answer: n = 1.5 mol"],"options":[],"conceptId":"chemistry_mole_mole_relationships","skillId":"chemistry_mole","subskillId":"chemistry_mole_q4","subject":"chemistry","chapter":"mole","topic":"Mole relationships"}', 3),
  (1607, 402, 'The molar mass of NaOH (sodium hydroxide) is 40 g/mol. A student uses 20 g of NaOH in an experiment. How many moles of NaOH is this?', 'text', 1, 'Use n = mass ÷ molar mass', '{"why":"20 g is exactly half the molar mass of NaOH (40 g/mol), so the sample contains 0.5 moles.","sol":"Step 1: Write the formula: n = m ÷ M\nStep 2: Identify values: m = 20 g, M = 40 g/mol\nStep 3: Substitute: n = 20 ÷ 40\nStep 4: Calculate: n = 0.5 mol","steps":["Step 1: Write the formula: n = m ÷ M","Step 2: Identify values: m = 20 g, M = 40 g/mol","Step 3: Substitute: n = 20 ÷ 40","Step 4: Calculate: n = 0.5 mol"],"options":[],"conceptId":"chemistry_mole_mole_relationships","skillId":"chemistry_mole","subskillId":"chemistry_mole_q5","subject":"chemistry","chapter":"mole","topic":"Mole relationships"}', 4),
  (1608, 403, 'A student is asked to calculate the molar mass of carbon dioxide (CO₂). Given that the atomic mass of C = 12 and O = 16, find the molar mass of CO₂.', 'text', 1, 'Focus on the core principle of Molar mass.', '{"why":"Molar mass is found by adding the atomic masses of all atoms in the formula. CO₂ has one C (mass 12) and two O atoms (mass 16 each), giving 44 g/mol.","sol":"Step 1: Write the molecular formula: CO₂ — it contains 1 carbon atom and 2 oxygen atoms\nStep 2: Find the mass of carbon: 1 × 12 = 12\nStep 3: Find the mass of oxygen: 2 × 16 = 32\nStep 4: Add all atomic masses together: 12 + 32 = 44 g/mol","steps":["Step 1: Write the molecular formula: CO₂ — it contains 1 carbon atom and 2 oxygen atoms","Step 2: Find the mass of carbon: 1 × 12 = 12","Step 3: Find the mass of oxygen: 2 × 16 = 32","Step 4: Add all atomic masses together: 12 + 32 = 44 g/mol"],"options":[],"conceptId":"chemistry_mole_molar_mass","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Molar mass"}', 0),
  (1609, 403, 'Calculate the molar mass of sodium chloride (NaCl). Use: Na = 23, Cl = 35.5.', 'text', 1, 'Add the atomic mass of each element present in one formula unit', '{"why":"NaCl is a simple ionic compound with one atom of each element. Adding their atomic masses directly gives the molar mass.","sol":"Step 1: Write the formula: NaCl — it contains 1 Na and 1 Cl atom\nStep 2: Mass of Na = 1 × 23 = 23\nStep 3: Mass of Cl = 1 × 35.5 = 35.5\nStep 4: Total molar mass = 23 + 35.5 = 58.5 g/mol","steps":["Step 1: Write the formula: NaCl — it contains 1 Na and 1 Cl atom","Step 2: Mass of Na = 1 × 23 = 23","Step 3: Mass of Cl = 1 × 35.5 = 35.5","Step 4: Total molar mass = 23 + 35.5 = 58.5 g/mol"],"options":[],"conceptId":"chemistry_mole_molar_mass","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Molar mass"}', 1),
  (1610, 403, 'Find the molar mass of sodium oxide (Na₂O). Use: Na = 23, O = 16.', 'text', 1, 'Note there are 2 sodium atoms — multiply the atomic mass of Na by 2', '{"why":"The subscript 2 in Na₂O means there are 2 sodium atoms. Always multiply the atomic mass by the subscript number before adding.","sol":"Step 1: Write the formula: Na₂O — it contains 2 Na atoms and 1 O atom\nStep 2: Mass of Na: 2 × 23 = 46\nStep 3: Mass of O: 1 × 16 = 16\nStep 4: Total molar mass = 46 + 16 = 62 g/mol","steps":["Step 1: Write the formula: Na₂O — it contains 2 Na atoms and 1 O atom","Step 2: Mass of Na: 2 × 23 = 46","Step 3: Mass of O: 1 × 16 = 16","Step 4: Total molar mass = 46 + 16 = 62 g/mol"],"options":[],"conceptId":"chemistry_mole_molar_mass","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Molar mass"}', 2),
  (1611, 403, 'Calculate the molar mass of calcium hydroxide, Ca(OH)₂. Use: Ca = 40, O = 16, H = 1.', 'text', 1, 'The bracket (OH)₂ means there are 2 OH groups — so 2 oxygen atoms and 2 hydrogen atoms in total', '{"why":"The bracket and subscript 2 in Ca(OH)₂ mean both O and H appear twice. Always expand brackets before calculating molar mass.","sol":"Step 1: Expand the formula: Ca(OH)₂ = Ca + 2O + 2H\nStep 2: Mass of Ca: 1 × 40 = 40\nStep 3: Mass of O: 2 × 16 = 32\nStep 4: Mass of H: 2 × 1 = 2\nStep 5: Total = 40 + 32 + 2 = 74 g/mol","steps":["Step 1: Expand the formula: Ca(OH)₂ = Ca + 2O + 2H","Step 2: Mass of Ca: 1 × 40 = 40","Step 3: Mass of O: 2 × 16 = 32","Step 4: Mass of H: 2 × 1 = 2","Step 5: Total = 40 + 32 + 2 = 74 g/mol"],"options":[],"conceptId":"chemistry_mole_molar_mass","skillId":"chemistry_mole","subskillId":"chemistry_mole_q4","subject":"chemistry","chapter":"mole","topic":"Molar mass"}', 3),
  (1612, 403, 'A chemist knows that the molar mass of H₂SO₄ (sulphuric acid) is 98 g/mol and uses 49 g in a reaction. How many moles of H₂SO₄ does the chemist use?', 'text', 1, 'Use n = mass ÷ molar mass', '{"why":"Once you know the molar mass, you can find moles by dividing the given mass by it. 49 g is half of 98 g/mol, so this is 0.5 moles.","sol":"Step 1: Write the formula: n = m ÷ M\nStep 2: Identify: m = 49 g, M = 98 g/mol\nStep 3: Substitute: n = 49 ÷ 98\nStep 4: Calculate: n = 0.5 mol","steps":["Step 1: Write the formula: n = m ÷ M","Step 2: Identify: m = 49 g, M = 98 g/mol","Step 3: Substitute: n = 49 ÷ 98","Step 4: Calculate: n = 0.5 mol"],"options":[],"conceptId":"chemistry_mole_molar_mass","skillId":"chemistry_mole","subskillId":"chemistry_mole_q5","subject":"chemistry","chapter":"mole","topic":"Molar mass"}', 4),
  (1613, 404, 'In the reaction 2H₂ + O₂ → 2H₂O, a student burns 2 moles of hydrogen gas (H₂). Using the mole ratio from the equation, how many moles of water (H₂O) are produced?', 'text', 1, 'Focus on the core principle of Stoichiometry.', '{"why":"The balanced equation shows H₂ and H₂O are in a 1:1 ratio. The coefficient of each is 2, so they cancel to give an equal mole relationship.","sol":"Step 1: Read the balanced equation: 2H₂ + O₂ → 2H₂O\nStep 2: Identify the mole ratio of H₂ to H₂O from the coefficients: 2 : 2, which simplifies to 1 : 1\nStep 3: Since the ratio is 1:1, every mole of H₂ produces exactly 1 mole of H₂O\nStep 4: Therefore 2 moles of H₂ → 2 moles of H₂O","steps":["Step 1: Read the balanced equation: 2H₂ + O₂ → 2H₂O","Step 2: Identify the mole ratio of H₂ to H₂O from the coefficients: 2 : 2, which simplifies to 1 : 1","Step 3: Since the ratio is 1:1, every mole of H₂ produces exactly 1 mole of H₂O","Step 4: Therefore 2 moles of H₂ → 2 moles of H₂O"],"options":[],"conceptId":"chemistry_mole_stoichiometry","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Stoichiometry"}', 0),
  (1614, 404, 'Using the equation N₂ + 3H₂ → 2NH₃, calculate how many moles of ammonia (NH₃) are produced from 1 mole of nitrogen gas (N₂).', 'text', 1, 'Focus on the core principle of Stoichiometry.', '{"why":"The coefficient of N₂ is 1 and NH₃ is 2 in the balanced equation. The ratio 1:2 means for every mole of N₂ used, 2 moles of NH₃ are produced.","sol":"Step 1: Write the balanced equation: N₂ + 3H₂ → 2NH₃\nStep 2: Read the mole ratio of N₂ to NH₃ from the coefficients: 1 : 2\nStep 3: Since 1 mole of N₂ produces 2 moles of NH₃, multiply: 1 × 2 = 2\nStep 4: Answer: 1 mol N₂ → 2 mol NH₃","steps":["Step 1: Write the balanced equation: N₂ + 3H₂ → 2NH₃","Step 2: Read the mole ratio of N₂ to NH₃ from the coefficients: 1 : 2","Step 3: Since 1 mole of N₂ produces 2 moles of NH₃, multiply: 1 × 2 = 2","Step 4: Answer: 1 mol N₂ → 2 mol NH₃"],"options":[],"conceptId":"chemistry_mole_stoichiometry","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Stoichiometry"}', 1),
  (1615, 404, 'In the reaction 2H₂ + O₂ → 2H₂O, if 4 moles of H₂ are burned, how many moles of water are formed?', 'text', 1, 'Focus on the core principle of Stoichiometry.', '{"why":"Because H₂ and H₂O have an equal (1:1) ratio in this equation, the number of moles produced always equals the number of moles of H₂ used.","sol":"Step 1: Read the equation: 2H₂ + O₂ → 2H₂O\nStep 2: Find the mole ratio H₂ : H₂O = 2 : 2 = 1 : 1\nStep 3: Apply the ratio to 4 moles of H₂: 4 × (1/1) = 4\nStep 4: 4 moles of H₂ produces 4 moles of H₂O","steps":["Step 1: Read the equation: 2H₂ + O₂ → 2H₂O","Step 2: Find the mole ratio H₂ : H₂O = 2 : 2 = 1 : 1","Step 3: Apply the ratio to 4 moles of H₂: 4 × (1/1) = 4","Step 4: 4 moles of H₂ produces 4 moles of H₂O"],"options":[],"conceptId":"chemistry_mole_stoichiometry","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Stoichiometry"}', 2),
  (1616, 404, 'Calcium carbonate decomposes according to: CaCO₃ → CaO + CO₂. If 1 mole of CaCO₃ fully decomposes, how many moles of carbon dioxide (CO₂) are released?', 'text', 1, 'Focus on the core principle of Stoichiometry.', '{"why":"In a 1:1 decomposition, every formula unit of CaCO₃ produces exactly one CO₂ molecule. The coefficients are all 1, making this a direct conversion.","sol":"Step 1: Write the balanced equation: CaCO₃ → CaO + CO₂\nStep 2: Read the mole ratio of CaCO₃ to CO₂ from coefficients: 1 : 1\nStep 3: Apply the ratio: 1 mole of CaCO₃ → 1 mole of CO₂\nStep 4: Answer: 1 mole of CO₂ is released","steps":["Step 1: Write the balanced equation: CaCO₃ → CaO + CO₂","Step 2: Read the mole ratio of CaCO₃ to CO₂ from coefficients: 1 : 1","Step 3: Apply the ratio: 1 mole of CaCO₃ → 1 mole of CO₂","Step 4: Answer: 1 mole of CO₂ is released"],"options":[],"conceptId":"chemistry_mole_stoichiometry","skillId":"chemistry_mole","subskillId":"chemistry_mole_q4","subject":"chemistry","chapter":"mole","topic":"Stoichiometry"}', 3),
  (1617, 404, 'In the reaction 4Al + 3O₂ → 2Al₂O₃, calculate the moles of aluminium oxide (Al₂O₃) produced from 4 moles of aluminium (Al).', 'text', 1, 'Focus on the core principle of Stoichiometry.', '{"why":"The equation shows that 4 moles of Al always produce 2 moles of Al₂O₃. The ratio is 4:2 = 2:1. With exactly 4 moles of Al, the answer is directly 2 moles of product.","sol":"Step 1: Write the balanced equation: 4Al + 3O₂ → 2Al₂O₃\nStep 2: Find the mole ratio of Al to Al₂O₃: 4 : 2, which simplifies to 2 : 1\nStep 3: Set up the ratio calculation: moles of Al₂O₃ = 4 × (2/4) = 4 × 0.5 = 2\nStep 4: Wait — use ratio directly: if 4 mol Al → 2 mol Al₂O₃ (from equation)","steps":["Step 1: Write the balanced equation: 4Al + 3O₂ → 2Al₂O₃","Step 2: Find the mole ratio of Al to Al₂O₃: 4 : 2, which simplifies to 2 : 1","Step 3: Set up the ratio calculation: moles of Al₂O₃ = 4 × (2/4) = 4 × 0.5 = 2","Step 4: Wait — use ratio directly: if 4 mol Al → 2 mol Al₂O₃ (from equation)"],"options":[],"conceptId":"chemistry_mole_stoichiometry","skillId":"chemistry_mole","subskillId":"chemistry_mole_q5","subject":"chemistry","chapter":"mole","topic":"Stoichiometry"}', 4),
  (1618, 405, 'A compound contains 52.2% carbon, 13% hydrogen, and 34.8% oxygen by mass. Determine its empirical formula. (C = 12, H = 1, O = 16)', 'text', 1, 'Assume 100 g of the compound, then convert each mass to moles, divide by the smallest, and write the whole-number ratio', '{"why":"After dividing all mole values by the smallest (2.18), the ratios become whole numbers: 2, 6, 1. This gives the simplest atom ratio, which is the empirical formula.","sol":"Step 1: Assume 100 g — so C = 52.2 g, H = 13 g, O = 34.8 g\nStep 2: Convert to moles: C = 52.2 ÷ 12 = 4.35, H = 13 ÷ 1 = 13, O = 34.8 ÷ 16 = 2.18\nStep 3: Divide all by the smallest value (2.18): C = 4.35/2.18 ≈ 2, H = 13/2.18 ≈ 6, O = 2.18/2.18 = 1\nStep 4: The whole-number ratio is C:H:O = 2:6:1, so the empirical formula is C₂H₆O","steps":["Step 1: Assume 100 g — so C = 52.2 g, H = 13 g, O = 34.8 g","Step 2: Convert to moles: C = 52.2 ÷ 12 = 4.35, H = 13 ÷ 1 = 13, O = 34.8 ÷ 16 = 2.18","Step 3: Divide all by the smallest value (2.18): C = 4.35/2.18 ≈ 2, H = 13/2.18 ≈ 6, O = 2.18/2.18 = 1","Step 4: The whole-number ratio is C:H:O = 2:6:1, so the empirical formula is C₂H₆O"],"options":[],"conceptId":"chemistry_mole_empirical_formula","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Empirical Formula"}', 0),
  (1619, 405, 'An iron oxide compound contains 70% iron (Fe) and 30% oxygen (O) by mass. Find its empirical formula. (Fe = 56, O = 16)', 'text', 1, 'When the ratio gives a decimal like 1.5, multiply all values by 2 to get whole numbers', '{"why":"The ratio 1:1.5 must be made into whole numbers. Multiplying by 2 gives 2:3, which is the correct ratio of Fe to O atoms in iron(III) oxide.","sol":"Step 1: Assume 100 g — Fe = 70 g, O = 30 g\nStep 2: Convert to moles: Fe = 70 ÷ 56 = 1.25, O = 30 ÷ 16 = 1.875\nStep 3: Divide by the smallest (1.25): Fe = 1.25/1.25 = 1, O = 1.875/1.25 = 1.5\nStep 4: Ratio 1 : 1.5 is not whole — multiply everything by 2: Fe = 2, O = 3\nStep 5: Empirical formula = Fe₂O₃","steps":["Step 1: Assume 100 g — Fe = 70 g, O = 30 g","Step 2: Convert to moles: Fe = 70 ÷ 56 = 1.25, O = 30 ÷ 16 = 1.875","Step 3: Divide by the smallest (1.25): Fe = 1.25/1.25 = 1, O = 1.875/1.25 = 1.5","Step 4: Ratio 1 : 1.5 is not whole — multiply everything by 2: Fe = 2, O = 3","Step 5: Empirical formula = Fe₂O₃"],"options":[],"conceptId":"chemistry_mole_empirical_formula","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Empirical Formula"}', 1),
  (1620, 405, 'A sample contains 2.0 g of hydrogen (H) and 16 g of oxygen (O). What is the empirical formula of the compound formed? (H = 1, O = 16)', 'text', 1, 'Focus on the core principle of Empirical Formula.', '{"why":"The mole ratio of 2:1 directly gives the subscripts in the empirical formula. Since both values are already whole numbers, no further adjustment is needed.","sol":"Step 1: Convert each mass to moles: H = 2.0 ÷ 1 = 2, O = 16 ÷ 16 = 1\nStep 2: Find the mole ratio: H : O = 2 : 1\nStep 3: Check — are these already whole numbers? Yes.\nStep 4: Write the empirical formula: H₂O","steps":["Step 1: Convert each mass to moles: H = 2.0 ÷ 1 = 2, O = 16 ÷ 16 = 1","Step 2: Find the mole ratio: H : O = 2 : 1","Step 3: Check — are these already whole numbers? Yes.","Step 4: Write the empirical formula: H₂O"],"options":[],"conceptId":"chemistry_mole_empirical_formula","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Empirical Formula"}', 2),
  (1621, 405, 'A compound is made from 3.0 g of carbon (C) and 8.0 g of oxygen (O). Find the empirical formula. (C = 12, O = 16)', 'text', 1, 'Focus on the core principle of Empirical Formula.', '{"why":"Dividing both mole values by the smallest (0.25) gives a ratio of 1:2, meaning for every 1 carbon atom there are 2 oxygen atoms. This matches the known formula of carbon dioxide.","sol":"Step 1: Convert to moles: C = 3.0 ÷ 12 = 0.25, O = 8.0 ÷ 16 = 0.5\nStep 2: Divide by the smallest value (0.25): C = 0.25/0.25 = 1, O = 0.5/0.25 = 2\nStep 3: Ratio C : O = 1 : 2\nStep 4: Empirical formula = CO₂","steps":["Step 1: Convert to moles: C = 3.0 ÷ 12 = 0.25, O = 8.0 ÷ 16 = 0.5","Step 2: Divide by the smallest value (0.25): C = 0.25/0.25 = 1, O = 0.5/0.25 = 2","Step 3: Ratio C : O = 1 : 2","Step 4: Empirical formula = CO₂"],"options":[],"conceptId":"chemistry_mole_empirical_formula","skillId":"chemistry_mole","subskillId":"chemistry_mole_q4","subject":"chemistry","chapter":"mole","topic":"Empirical Formula"}', 3),
  (1622, 406, 'A compound has an empirical formula of CH₂ and a molar mass (Mr) of 56 g/mol. Find the molecular formula.', 'text', 1, 'Find the empirical formula mass first, then divide Mr by it to get the multiplying factor n', '{"why":"The empirical formula CH₂ has a mass of 14. Since the actual Mr is 56, the molecular formula is 4 times bigger, giving C₄H₈ (the formula for butene).","sol":"Step 1: Calculate the empirical formula mass (EFM): CH₂ → C = 12, H₂ = 2, EFM = 14\nStep 2: Calculate the multiplying factor: n = Mr ÷ EFM = 56 ÷ 14 = 4\nStep 3: Multiply the entire empirical formula by n: CH₂ × 4 = C₄H₈","steps":["Step 1: Calculate the empirical formula mass (EFM): CH₂ → C = 12, H₂ = 2, EFM = 14","Step 2: Calculate the multiplying factor: n = Mr ÷ EFM = 56 ÷ 14 = 4","Step 3: Multiply the entire empirical formula by n: CH₂ × 4 = C₄H₈"],"options":[],"conceptId":"chemistry_mole_molecular_formula","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Molecular Formula"}', 0),
  (1623, 406, 'A compound has the empirical formula NH₂ and a molar mass (Mr) of 32 g/mol. What is its molecular formula? (N = 14, H = 1)', 'text', 1, 'Focus on the core principle of Molecular Formula.', '{"why":"The EFM of NH₂ is 16. With Mr = 32, n = 2. Multiplying every subscript by 2 gives N₂H₄, which is hydrazine.","sol":"Step 1: Calculate EFM: NH₂ → N = 14, H₂ = 2, EFM = 16\nStep 2: Find n: n = Mr ÷ EFM = 32 ÷ 16 = 2\nStep 3: Multiply formula by 2: NH₂ × 2 = N₂H₄","steps":["Step 1: Calculate EFM: NH₂ → N = 14, H₂ = 2, EFM = 16","Step 2: Find n: n = Mr ÷ EFM = 32 ÷ 16 = 2","Step 3: Multiply formula by 2: NH₂ × 2 = N₂H₄"],"options":[],"conceptId":"chemistry_mole_molecular_formula","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Molecular Formula"}', 1),
  (1624, 406, 'The empirical formula of a compound is CH and its molar mass is 78 g/mol. Determine the molecular formula. (C = 12, H = 1)', 'text', 1, 'Focus on the core principle of Molecular Formula.', '{"why":"EFM of CH is 13. Since Mr = 78 and 78 ÷ 13 = 6, the molecular formula is 6 times the empirical formula, giving C₆H₆ (benzene).","sol":"Step 1: Calculate EFM: CH → C = 12, H = 1, EFM = 13\nStep 2: Find n: n = Mr ÷ EFM = 78 ÷ 13 = 6\nStep 3: Multiply formula by 6: CH × 6 = C₆H₆","steps":["Step 1: Calculate EFM: CH → C = 12, H = 1, EFM = 13","Step 2: Find n: n = Mr ÷ EFM = 78 ÷ 13 = 6","Step 3: Multiply formula by 6: CH × 6 = C₆H₆"],"options":[],"conceptId":"chemistry_mole_molecular_formula","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Molecular Formula"}', 2),
  (1625, 406, 'A compound has the empirical formula CH₂O and a molar mass of 90 g/mol. Find the molecular formula. (C = 12, H = 1, O = 16)', 'text', 1, 'Focus on the core principle of Molecular Formula.', '{"why":"EFM of CH₂O is 30. Dividing the actual Mr (90) by 30 gives n = 3. Every atom in the empirical formula is multiplied by 3 to get the molecular formula.","sol":"Step 1: Calculate EFM: CH₂O → C = 12, H₂ = 2, O = 16, EFM = 30\nStep 2: Find n: n = Mr ÷ EFM = 90 ÷ 30 = 3\nStep 3: Multiply formula by 3: CH₂O × 3 = C₃H₆O₃","steps":["Step 1: Calculate EFM: CH₂O → C = 12, H₂ = 2, O = 16, EFM = 30","Step 2: Find n: n = Mr ÷ EFM = 90 ÷ 30 = 3","Step 3: Multiply formula by 3: CH₂O × 3 = C₃H₆O₃"],"options":[],"conceptId":"chemistry_mole_molecular_formula","skillId":"chemistry_mole","subskillId":"chemistry_mole_q4","subject":"chemistry","chapter":"mole","topic":"Molecular Formula"}', 3),
  (1626, 407, 'In the reaction N₂ + 3H₂ → 2NH₃, a student has 6 mol of H₂ and 2 mol of N₂. Which substance, if any, is the limiting reagent?', 'text', 1, 'Check how much H₂ is needed for 2 mol of N₂ using the mole ratio from the equation', '{"why":"When the available amounts of reactants exactly match the required mole ratio, both are fully consumed. There is no limiting reagent and no excess.","sol":"Step 1: Read the equation: N₂ + 3H₂ → 2NH₃. The ratio is N₂ : H₂ = 1 : 3\nStep 2: Calculate H₂ needed for 2 mol N₂: 2 × 3 = 6 mol of H₂ is required\nStep 3: Compare with what is available: we have exactly 6 mol H₂\nStep 4: Both reactants are used up at the same rate — neither runs out first","steps":["Step 1: Read the equation: N₂ + 3H₂ → 2NH₃. The ratio is N₂ : H₂ = 1 : 3","Step 2: Calculate H₂ needed for 2 mol N₂: 2 × 3 = 6 mol of H₂ is required","Step 3: Compare with what is available: we have exactly 6 mol H₂","Step 4: Both reactants are used up at the same rate — neither runs out first"],"options":[],"conceptId":"chemistry_mole_limiting_reagent","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Limiting Reagent"}', 0),
  (1627, 407, 'In the reaction N₂ + 3H₂ → 2NH₃, a student mixes 10 mol of H₂ with 2 mol of N₂. Which reactant is the limiting reagent?', 'text', 1, 'Focus on the core principle of Limiting Reagent.', '{"why":"N₂ runs out first because the 2 mol available is completely consumed when reacting with 6 mol H₂. The remaining 4 mol of H₂ is excess and does not react.","sol":"Step 1: Read the equation: N₂ + 3H₂ → 2NH₃. Ratio N₂ : H₂ = 1 : 3\nStep 2: Calculate how much H₂ is needed to react with 2 mol N₂: 2 × 3 = 6 mol H₂\nStep 3: Compare: we have 10 mol H₂ but only need 6 mol — so H₂ is in excess\nStep 4: N₂ is used up completely (only 2 mol available), so N₂ is the limiting reagent","steps":["Step 1: Read the equation: N₂ + 3H₂ → 2NH₃. Ratio N₂ : H₂ = 1 : 3","Step 2: Calculate how much H₂ is needed to react with 2 mol N₂: 2 × 3 = 6 mol H₂","Step 3: Compare: we have 10 mol H₂ but only need 6 mol — so H₂ is in excess","Step 4: N₂ is used up completely (only 2 mol available), so N₂ is the limiting reagent"],"options":[],"conceptId":"chemistry_mole_limiting_reagent","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Limiting Reagent"}', 1),
  (1628, 407, 'In the reaction 2H₂ + O₂ → 2H₂O, a student has 4 mol of H₂ and only 1 mol of O₂. Identify the limiting reagent and state how many moles of water are produced.', 'text', 1, 'Focus on the core principle of Limiting Reagent.', '{"why":"Only 1 mol of O₂ is available, and it can react with at most 2 mol of H₂. The remaining 2 mol of H₂ goes unreacted. The limiting reagent controls the amount of product formed.","sol":"Step 1: Read the equation: 2H₂ + O₂ → 2H₂O. Ratio H₂ : O₂ = 2 : 1\nStep 2: Calculate H₂ needed for 1 mol O₂: 1 × 2 = 2 mol H₂ needed\nStep 3: We have 4 mol H₂ — that is more than enough, so H₂ is in excess\nStep 4: O₂ is the limiting reagent. The reaction produces 2 × 1 = 2 mol H₂O","steps":["Step 1: Read the equation: 2H₂ + O₂ → 2H₂O. Ratio H₂ : O₂ = 2 : 1","Step 2: Calculate H₂ needed for 1 mol O₂: 1 × 2 = 2 mol H₂ needed","Step 3: We have 4 mol H₂ — that is more than enough, so H₂ is in excess","Step 4: O₂ is the limiting reagent. The reaction produces 2 × 1 = 2 mol H₂O"],"options":[],"conceptId":"chemistry_mole_limiting_reagent","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Limiting Reagent"}', 2),
  (1629, 407, 'In the reaction 4Al + 3O₂ → 2Al₂O₃, a student has 4 mol of Al but has a very large excess of O₂. Which is the limiting reagent, and how many moles of Al₂O₃ are produced?', 'text', 1, 'Focus on the core principle of Limiting Reagent.', '{"why":"When one reactant is in large excess, the other (Al here) is the limiting reagent. The amount of product is always determined by the limiting reagent, not by the excess.","sol":"Step 1: Read the equation: 4Al + 3O₂ → 2Al₂O₃. Ratio Al : Al₂O₃ = 4 : 2 = 2 : 1\nStep 2: Since O₂ is in excess, the amount of Al controls the reaction\nStep 3: Al is the limiting reagent. Use the ratio: 4 mol Al → 2 mol Al₂O₃\nStep 4: 4 mol Al produces (4 ÷ 2) × 1 = 2 mol Al₂O₃","steps":["Step 1: Read the equation: 4Al + 3O₂ → 2Al₂O₃. Ratio Al : Al₂O₃ = 4 : 2 = 2 : 1","Step 2: Since O₂ is in excess, the amount of Al controls the reaction","Step 3: Al is the limiting reagent. Use the ratio: 4 mol Al → 2 mol Al₂O₃","Step 4: 4 mol Al produces (4 ÷ 2) × 1 = 2 mol Al₂O₃"],"options":[],"conceptId":"chemistry_mole_limiting_reagent","skillId":"chemistry_mole","subskillId":"chemistry_mole_q4","subject":"chemistry","chapter":"mole","topic":"Limiting Reagent"}', 3),
  (1630, 408, 'A container holds 44.8 dm³ of carbon dioxide gas at STP. How many moles of CO₂ does the container hold?', 'text', 1, 'Use the formula: moles = volume ÷ 22.4', '{"why":"At STP, 1 mole of any gas occupies 22.4 dm³. Dividing 44.8 by 22.4 gives 2, meaning the container holds 2 moles of CO₂.","sol":"Step 1: Write the formula: n = Volume ÷ 22.4\nStep 2: Substitute: n = 44.8 ÷ 22.4\nStep 3: Calculate: n = 2 mol","steps":["Step 1: Write the formula: n = Volume ÷ 22.4","Step 2: Substitute: n = 44.8 ÷ 22.4","Step 3: Calculate: n = 2 mol"],"options":[],"conceptId":"chemistry_mole_gas_volume","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Gas Volume"}', 0),
  (1631, 408, 'A chemist needs 5 moles of hydrogen gas (H₂) for an experiment. What volume of hydrogen gas, measured at STP, would the chemist need to collect?', 'text', 1, 'Focus on the core principle of Gas Volume.', '{"why":"Multiplying moles by 22.4 converts to volume at STP. 5 moles of any gas takes up 5 × 22.4 = 112 dm³ under standard conditions.","sol":"Step 1: Write the formula: Volume = n × 22.4\nStep 2: Substitute: Volume = 5 × 22.4\nStep 3: Calculate: Volume = 112 dm³","steps":["Step 1: Write the formula: Volume = n × 22.4","Step 2: Substitute: Volume = 5 × 22.4","Step 3: Calculate: Volume = 112 dm³"],"options":[],"conceptId":"chemistry_mole_gas_volume","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Gas Volume"}', 1),
  (1632, 408, 'A balloon contains 11.2 dm³ of helium gas at STP. How many moles of helium are in the balloon?', 'text', 1, 'Focus on the core principle of Gas Volume.', '{"why":"11.2 dm³ is exactly half of 22.4 dm³ (the molar volume at STP). So the balloon contains half a mole of helium gas.","sol":"Step 1: Write the formula: n = Volume ÷ 22.4\nStep 2: Substitute: n = 11.2 ÷ 22.4\nStep 3: Calculate: n = 0.5 mol","steps":["Step 1: Write the formula: n = Volume ÷ 22.4","Step 2: Substitute: n = 11.2 ÷ 22.4","Step 3: Calculate: n = 0.5 mol"],"options":[],"conceptId":"chemistry_mole_gas_volume","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Gas Volume"}', 2),
  (1633, 409, 'A student says ''the mole concept is a bridge in chemistry.'' What do they mean by this? Explain using the difference between the microscopic and macroscopic worlds.', 'text', 1, 'Think about how atoms are too small to weigh individually, but we can measure grams in the lab', '{"why":"Without the mole, chemists could not relate what happens at the atomic level (e.g. 2 atoms of H react with 1 atom of O) to what they measure in the lab (grams of hydrogen and oxygen).","sol":"Step 1: The microscopic world = individual atoms and molecules, which are far too small to count or weigh directly\nStep 2: The macroscopic world = the gram quantities we can measure using a balance in a laboratory\nStep 3: The mole links these two worlds — 1 mole of any substance has a fixed number of particles (6.02 × 10²³) AND a measurable mass in grams (its molar mass)\nStep 4: This allows chemists to move between counting particles and measuring mass","steps":["Step 1: The microscopic world = individual atoms and molecules, which are far too small to count or weigh directly","Step 2: The macroscopic world = the gram quantities we can measure using a balance in a laboratory","Step 3: The mole links these two worlds — 1 mole of any substance has a fixed number of particles (6.02 × 10²³) AND a measurable mass in grams (its molar mass)","Step 4: This allows chemists to move between counting particles and measuring mass"],"options":[],"conceptId":"chemistry_mole_importance_and_applications_of_mole_concept","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Importance and applications of mole concept"}', 0),
  (1634, 409, 'Explain how the mole concept is used in the pharmaceutical (medicine) industry when manufacturing drugs.', 'text', 1, 'Think about why precise amounts of substances matter in medicine', '{"why":"Drug effectiveness depends on having the right number of molecules, not just the right weight. The mole converts between particle counts and measurable gram quantities.","sol":"Step 1: Drug molecules must be mixed in exact proportions to be effective and safe\nStep 2: Chemists use mole ratios to calculate exactly how many grams of each ingredient to combine\nStep 3: The mole ensures that the correct number of molecules of the active substance is in every tablet or dose\nStep 4: Too little is ineffective; too much can be toxic — the mole concept enables precision","steps":["Step 1: Drug molecules must be mixed in exact proportions to be effective and safe","Step 2: Chemists use mole ratios to calculate exactly how many grams of each ingredient to combine","Step 3: The mole ensures that the correct number of molecules of the active substance is in every tablet or dose","Step 4: Too little is ineffective; too much can be toxic — the mole concept enables precision"],"options":[],"conceptId":"chemistry_mole_importance_and_applications_of_mole_concept","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Importance and applications of mole concept"}', 1),
  (1635, 409, 'State two industrial applications of the mole concept and briefly explain how it is used in each.', 'text', 1, 'Think of industries that involve chemical reactions at large scale', '{"why":"Large-scale chemical manufacturing depends on accurate mole calculations. Even small errors in mole ratios can result in wasted materials, unsafe products, or financial loss.","sol":"Step 1: Ammonia production (Haber Process) — N₂ + 3H₂ → 2NH₃. Mole ratios tell engineers exactly how much N₂ and H₂ to feed into the reactor to maximise yield.\nStep 2: Fertilizer production — nutrients like nitrogen, phosphorus, and potassium (NPK) must be present in precise mole ratios for plant growth.\nStep 3: Both industries use mole calculations to avoid waste, maximise efficiency, and ensure product quality.","steps":["Step 1: Ammonia production (Haber Process) — N₂ + 3H₂ → 2NH₃. Mole ratios tell engineers exactly how much N₂ and H₂ to feed into the reactor to maximise yield.","Step 2: Fertilizer production — nutrients like nitrogen, phosphorus, and potassium (NPK) must be present in precise mole ratios for plant growth.","Step 3: Both industries use mole calculations to avoid waste, maximise efficiency, and ensure product quality."],"options":[],"conceptId":"chemistry_mole_importance_and_applications_of_mole_concept","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Importance and applications of mole concept"}', 2),
  (1636, 410, 'Balance: N₂ + H₂ → NH₃', 'text', 1, 'Focus on the core principle of Balancing equations.', '{"why":"Match nitrogen first, then hydrogen","sol":"Step 1: Nitrogen is 2 on left, 1 on right\nStep 2: Put 2 in front of NH₃\nStep 3: Now H = 6 on right\nStep 4: Put 3 in front of H₂","steps":["Step 1: Nitrogen is 2 on left, 1 on right","Step 2: Put 2 in front of NH₃","Step 3: Now H = 6 on right","Step 4: Put 3 in front of H₂"],"options":[],"conceptId":"chemistry_reactions_balancing_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q1","subject":"chemistry","chapter":"reactions","topic":"Balancing equations"}', 0),
  (1637, 410, 'Balance: Na + Cl₂ → NaCl', 'text', 1, 'Focus on the core principle of Balancing equations.', '{"why":"Equal chlorine atoms required","sol":"Step 1: Chlorine is 2 on left\nStep 2: Put 2 in front of NaCl\nStep 3: Adjust sodium to 2Na","steps":["Step 1: Chlorine is 2 on left","Step 2: Put 2 in front of NaCl","Step 3: Adjust sodium to 2Na"],"options":[],"conceptId":"chemistry_reactions_balancing_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q2","subject":"chemistry","chapter":"reactions","topic":"Balancing equations"}', 1),
  (1638, 410, 'Balance: Mg + O₂ → MgO', 'text', 1, 'Focus on the core principle of Balancing equations.', '{"why":"Balance oxygen first","sol":"Step 1: Oxygen is 2 on left, 1 on right\nStep 2: Put 2 in front of MgO\nStep 3: Put 2 in front of Mg","steps":["Step 1: Oxygen is 2 on left, 1 on right","Step 2: Put 2 in front of MgO","Step 3: Put 2 in front of Mg"],"options":[],"conceptId":"chemistry_reactions_balancing_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q3","subject":"chemistry","chapter":"reactions","topic":"Balancing equations"}', 2),
  (1639, 410, 'Balance: Al + O₂ → Al₂O₃', 'text', 1, 'Focus on the core principle of Balancing equations.', '{"why":"Use least common multiple method","sol":"Step 1: Oxygen: LCM of 2 and 3 = 6\nStep 2: Put 3O₂ and 2Al₂O₃\nStep 3: Adjust aluminum to 4Al","steps":["Step 1: Oxygen: LCM of 2 and 3 = 6","Step 2: Put 3O₂ and 2Al₂O₃","Step 3: Adjust aluminum to 4Al"],"options":[],"conceptId":"chemistry_reactions_balancing_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q4","subject":"chemistry","chapter":"reactions","topic":"Balancing equations"}', 3),
  (1640, 410, 'Balance: Fe + O₂ → Fe₂O₃', 'text', 1, 'use LCM', '{"why":"equal oxygen atoms first","sol":"Step 1: Oxygen LCM = 6\nStep 2: 3O₂ and 2Fe₂O₃\nStep 3: adjust Fe to 4","steps":["Step 1: Oxygen LCM = 6","Step 2: 3O₂ and 2Fe₂O₃","Step 3: adjust Fe to 4"],"options":[],"conceptId":"chemistry_reactions_balancing_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q5","subject":"chemistry","chapter":"reactions","topic":"Balancing equations"}', 4),
  (1641, 411, 'In H₂ + O₂ → H₂O, is mass conserved?', 'text', 1, 'Focus on the core principle of Conservation of mass.', '{"why":"Balanced equation ensures equal atoms","sol":"Step 1: Count atoms on both sides\nStep 2: Same number of H and O atoms\nStep 3: Total mass remains constant","steps":["Step 1: Count atoms on both sides","Step 2: Same number of H and O atoms","Step 3: Total mass remains constant"],"options":[],"conceptId":"chemistry_reactions_conservation_of_mass","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q1","subject":"chemistry","chapter":"reactions","topic":"Conservation of mass"}', 0),
  (1642, 411, 'Why must equations be balanced to obey this law?', 'text', 1, 'Focus on the core principle of Conservation of mass.', '{"why":"Balancing enforces conservation of mass","sol":"Step 1: Count atoms in reactants\nStep 2: Count atoms in products\nStep 3: Ensure equality\nStep 4: Adjust coefficients","steps":["Step 1: Count atoms in reactants","Step 2: Count atoms in products","Step 3: Ensure equality","Step 4: Adjust coefficients"],"options":[],"conceptId":"chemistry_reactions_conservation_of_mass","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q2","subject":"chemistry","chapter":"reactions","topic":"Conservation of mass"}', 1),
  (1643, 411, 'Why is a closed container important in experiments?', 'text', 1, 'gas loss', '{"why":"Open systems lose matter","sol":"Step 1: Check reaction system\nStep 2: Prevent gas escape\nStep 3: Measure total mass correctly","steps":["Step 1: Check reaction system","Step 2: Prevent gas escape","Step 3: Measure total mass correctly"],"options":[],"conceptId":"chemistry_reactions_conservation_of_mass","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q3","subject":"chemistry","chapter":"reactions","topic":"Conservation of mass"}', 2),
  (1644, 411, 'What law explains balancing chemical equations?', 'text', 1, 'Focus on the core principle of Conservation of mass.', '{"why":"Equations must reflect equal atoms","sol":"Step 1: Identify principle\nStep 2: Relate to atom conservation\nStep 3: State law","steps":["Step 1: Identify principle","Step 2: Relate to atom conservation","Step 3: State law"],"options":[],"conceptId":"chemistry_reactions_conservation_of_mass","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q4","subject":"chemistry","chapter":"reactions","topic":"Conservation of mass"}', 3),
  (1645, 412, 'Balance: Mg + O₂ → MgO', 'text', 1, 'Focus on the core principle of Chemical equations.', '{"why":"Equal number of atoms on both sides","sol":"Step 1: Oxygen atoms are 2 on left and 1 on right\nStep 2: Put 2 in front of MgO\nStep 3: Adjust magnesium to 2\nStep 4: Final check","steps":["Step 1: Oxygen atoms are 2 on left and 1 on right","Step 2: Put 2 in front of MgO","Step 3: Adjust magnesium to 2","Step 4: Final check"],"options":[],"conceptId":"chemistry_reactions_chemical_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q1","subject":"chemistry","chapter":"reactions","topic":"Chemical equations"}', 0),
  (1646, 412, 'Write equation for hydrogen reacting with oxygen', 'text', 1, 'Focus on the core principle of Chemical equations.', '{"why":"Water formation reaction","sol":"Step 1: Identify reactants H₂ and O₂\nStep 2: Product is H₂O\nStep 3: Balance equation\nStep 4: Final form","steps":["Step 1: Identify reactants H₂ and O₂","Step 2: Product is H₂O","Step 3: Balance equation","Step 4: Final form"],"options":[],"conceptId":"chemistry_reactions_chemical_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q2","subject":"chemistry","chapter":"reactions","topic":"Chemical equations"}', 1),
  (1647, 412, 'What type of reaction is Fe + S → FeS?', 'text', 1, 'Focus on the core principle of Chemical equations.', '{"why":"Two reactants form one product","sol":"Step 1: Two elements combine\nStep 2: Form one compound\nStep 3: Identify reaction type","steps":["Step 1: Two elements combine","Step 2: Form one compound","Step 3: Identify reaction type"],"options":[],"conceptId":"chemistry_reactions_chemical_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q3","subject":"chemistry","chapter":"reactions","topic":"Chemical equations"}', 2),
  (1648, 412, 'Identify reactants in: CaCO₃ → CaO + CO₂', 'text', 1, 'Focus on the core principle of Chemical equations.', '{"why":"Left side shows reactant","sol":"Step 1: Look left side\nStep 2: Identify compound present","steps":["Step 1: Look left side","Step 2: Identify compound present"],"options":[],"conceptId":"chemistry_reactions_chemical_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q4","subject":"chemistry","chapter":"reactions","topic":"Chemical equations"}', 3),
  (1649, 412, 'Identify products in: Zn + HCl → ZnCl₂ + H₂', 'text', 1, 'Focus on the core principle of Chemical equations.', '{"why":"Right side shows products","sol":"Step 1: Look right side\nStep 2: List substances formed","steps":["Step 1: Look right side","Step 2: List substances formed"],"options":[],"conceptId":"chemistry_reactions_chemical_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q5","subject":"chemistry","chapter":"reactions","topic":"Chemical equations"}', 4),
  (1650, 413, 'Why is neutralization an exothermic reaction?', 'text', 1, 'Focus on the core principle of Neutralization.', '{"why":"Bond formation releases energy","sol":"Step 1: H⁺ and OH⁻ combine\nStep 2: Energy is released\nStep 3: Temperature increases","steps":["Step 1: H⁺ and OH⁻ combine","Step 2: Energy is released","Step 3: Temperature increases"],"options":[],"conceptId":"chemistry_reactions_neutralization","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q1","subject":"chemistry","chapter":"reactions","topic":"Neutralization"}', 0),
  (1651, 413, 'What are the product formed after this reaction: HCl + NaOH → ?', 'text', 1, 'Focus on the core principle of Neutralization.', '{"why":"acid + base reaction","sol":"Step 1: Identify acid (HCl)\nStep 2: Identify base (NaOH)\nStep 3: Swap ions\nStep 4: Form NaCl + H₂O","steps":["Step 1: Identify acid (HCl)","Step 2: Identify base (NaOH)","Step 3: Swap ions","Step 4: Form NaCl + H₂O"],"options":[],"conceptId":"chemistry_reactions_neutralization","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q2","subject":"chemistry","chapter":"reactions","topic":"Neutralization"}', 1),
  (1652, 413, 'What are the product formed after this reaction: H₂SO₄ + KOH → ?', 'text', 1, 'Focus on the core principle of Neutralization.', '{"why":"neutralization produces salt + water","sol":"Step 1: Acid = H₂SO₄\nStep 2: Base = KOH\nStep 3: Form salt K₂SO₄\nStep 4: Form water","steps":["Step 1: Acid = H₂SO₄","Step 2: Base = KOH","Step 3: Form salt K₂SO₄","Step 4: Form water"],"options":[],"conceptId":"chemistry_reactions_neutralization","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q3","subject":"chemistry","chapter":"reactions","topic":"Neutralization"}', 2),
  (1653, 413, 'What ions react in neutralization?', 'text', 1, 'Focus on the core principle of Neutralization.', '{"why":"they form water","sol":"Step 1: Acid releases H⁺\nStep 2: Base releases OH⁻\nStep 3: Combine ions","steps":["Step 1: Acid releases H⁺","Step 2: Base releases OH⁻","Step 3: Combine ions"],"options":[],"conceptId":"chemistry_reactions_neutralization","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q4","subject":"chemistry","chapter":"reactions","topic":"Neutralization"}', 3),
  (1654, 413, 'Why does pH move towards 7?', 'text', 1, 'Focus on the core principle of Neutralization.', '{"why":"neutral solution forms","sol":"Step 1: Acid lowers pH\nStep 2: Base raises pH\nStep 3: Reaction balances ions","steps":["Step 1: Acid lowers pH","Step 2: Base raises pH","Step 3: Reaction balances ions"],"options":[],"conceptId":"chemistry_reactions_neutralization","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q5","subject":"chemistry","chapter":"reactions","topic":"Neutralization"}', 4),
  (1655, 413, 'Example 5: Identify salt in HNO₃ + NaOH', 'text', 1, 'Focus on the core principle of Neutralization.', '{"why":"salt is ionic product","sol":"Step 1: Remove H from acid\nStep 2: Remove OH from base\nStep 3: Combine Na + NO₃","steps":["Step 1: Remove H from acid","Step 2: Remove OH from base","Step 3: Combine Na + NO₃"],"options":[],"conceptId":"chemistry_reactions_neutralization","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q6","subject":"chemistry","chapter":"reactions","topic":"Neutralization"}', 5),
  (1656, 414, 'What is an acid?', 'text', 1, 'Focus on the core principle of Acids.', '{"why":"Acidity is due to hydrogen ions","sol":"Step 1: Identify substance in water\nStep 2: Check for ion production\nStep 3: Confirm H⁺ ions released","steps":["Step 1: Identify substance in water","Step 2: Check for ion production","Step 3: Confirm H⁺ ions released"],"options":[],"conceptId":"chemistry_acids_bases_acids","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q1","subject":"chemistry","chapter":"acids_bases","topic":"Acids"}', 0),
  (1657, 414, 'What happens when HCl is added in water?', 'text', 1, 'Focus on the core principle of Acids.', '{"why":"strong acid fully dissociates","sol":"Step 1: Identify acid (HCl)\nStep 2: Dissociation occurs\nStep 3: H⁺ and Cl⁻ form","steps":["Step 1: Identify acid (HCl)","Step 2: Dissociation occurs","Step 3: H⁺ and Cl⁻ form"],"options":[],"conceptId":"chemistry_acids_bases_acids","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q2","subject":"chemistry","chapter":"acids_bases","topic":"Acids"}', 1),
  (1658, 414, 'What is H₂SO₄ dissociation?', 'text', 1, 'Focus on the core principle of Acids.', '{"why":"releases two hydrogen ions","sol":"Step 1: Recognize diprotic acid\nStep 2: Releases 2 H⁺ ions\nStep 3: Forms SO₄²⁻ ion","steps":["Step 1: Recognize diprotic acid","Step 2: Releases 2 H⁺ ions","Step 3: Forms SO₄²⁻ ion"],"options":[],"conceptId":"chemistry_acids_bases_acids","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q3","subject":"chemistry","chapter":"acids_bases","topic":"Acids"}', 2),
  (1659, 414, 'Why are acids corrosive?', 'text', 1, 'Focus on the core principle of Acids.', '{"why":"chemical reactivity of H⁺","sol":"Step 1: Acids release H⁺ ions\nStep 2: H⁺ reacts with proteins\nStep 3: Tissue damage occurs","steps":["Step 1: Acids release H⁺ ions","Step 2: H⁺ reacts with proteins","Step 3: Tissue damage occurs"],"options":[],"conceptId":"chemistry_acids_bases_acids","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q4","subject":"chemistry","chapter":"acids_bases","topic":"Acids"}', 3),
  (1660, 414, 'Why do acids turn blue litmus red?', 'text', 1, 'Focus on the core principle of Acids.', '{"why":"indicator sensitivity to pH","sol":"Step 1: Indicator reacts with H⁺\nStep 2: Colour change occurs\nStep 3: Indicates acidity","steps":["Step 1: Indicator reacts with H⁺","Step 2: Colour change occurs","Step 3: Indicates acidity"],"options":[],"conceptId":"chemistry_acids_bases_acids","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q5","subject":"chemistry","chapter":"acids_bases","topic":"Acids"}', 4),
  (1661, 414, 'Identify acid strength in CH₃COOH', 'text', 1, 'Focus on the core principle of Acids.', '{"why":"only partially ionizes","sol":"Step 1: Check dissociation symbol\nStep 2: ⇌ shows partial ionization\nStep 3: classify acid","steps":["Step 1: Check dissociation symbol","Step 2: ⇌ shows partial ionization","Step 3: classify acid"],"options":[],"conceptId":"chemistry_acids_bases_acids","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q6","subject":"chemistry","chapter":"acids_bases","topic":"Acids"}', 5),
  (1662, 415, 'What is a base?', 'text', 1, 'Focus on the core principle of Bases and alkalis.', '{"why":"bases neutralize acids","sol":"Step 1: Check reaction with acid\nStep 2: Identify neutralization ability\nStep 3: Confirm OH⁻ production","steps":["Step 1: Check reaction with acid","Step 2: Identify neutralization ability","Step 3: Confirm OH⁻ production"],"options":[],"conceptId":"chemistry_acids_bases_bases_and_alkalis","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q1","subject":"chemistry","chapter":"acids_bases","topic":"Bases and alkalis"}', 0),
  (1663, 415, 'What happens when alkalis dissolve in water?', 'text', 1, 'Focus on the core principle of Bases and alkalis.', '{"why":"OH⁻ causes alkalinity","sol":"Step 1: Alkali dissolves\nStep 2: Ionic dissociation occurs\nStep 3: OH⁻ ions are released","steps":["Step 1: Alkali dissolves","Step 2: Ionic dissociation occurs","Step 3: OH⁻ ions are released"],"options":[],"conceptId":"chemistry_acids_bases_bases_and_alkalis","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q2","subject":"chemistry","chapter":"acids_bases","topic":"Bases and alkalis"}', 1),
  (1664, 415, 'Write dissociation of NaOH in water', 'text', 1, 'Focus on the core principle of Bases and alkalis.', '{"why":"strong alkali dissociates fully","sol":"Step 1: Identify compound\nStep 2: Break into ions\nStep 3: Na⁺ and OH⁻ form","steps":["Step 1: Identify compound","Step 2: Break into ions","Step 3: Na⁺ and OH⁻ form"],"options":[],"conceptId":"chemistry_acids_bases_bases_and_alkalis","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q3","subject":"chemistry","chapter":"acids_bases","topic":"Bases and alkalis"}', 2),
  (1665, 415, 'Why is Ca(OH)₂ a base?', 'text', 1, 'Focus on the core principle of Bases and alkalis.', '{"why":"neutralization property","sol":"Step 1: Identify hydroxide groups\nStep 2: Check reaction with acids\nStep 3: Confirm neutralization","steps":["Step 1: Identify hydroxide groups","Step 2: Check reaction with acids","Step 3: Confirm neutralization"],"options":[],"conceptId":"chemistry_acids_bases_bases_and_alkalis","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q4","subject":"chemistry","chapter":"acids_bases","topic":"Bases and alkalis"}', 3),
  (1666, 415, 'Example 4: Why do bases feel slippery?', 'text', 1, 'Focus on the core principle of Bases and alkalis.', '{"why":"chemical interaction with fats","sol":"Step 1: OH⁻ ions interact with skin oils\nStep 2: Soap-like effect occurs\nStep 3: Surface becomes slippery","steps":["Step 1: OH⁻ ions interact with skin oils","Step 2: Soap-like effect occurs","Step 3: Surface becomes slippery"],"options":[],"conceptId":"chemistry_acids_bases_bases_and_alkalis","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q5","subject":"chemistry","chapter":"acids_bases","topic":"Bases and alkalis"}', 4),
  (1667, 415, 'Example 5: Why is ammonia a weak alkali?', 'text', 1, 'Focus on the core principle of Bases and alkalis.', '{"why":"weak base behavior","sol":"Step 1: NH₃ dissolves in water\nStep 2: Partially produces OH⁻\nStep 3: Low ionization","steps":["Step 1: NH₃ dissolves in water","Step 2: Partially produces OH⁻","Step 3: Low ionization"],"options":[],"conceptId":"chemistry_acids_bases_bases_and_alkalis","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q6","subject":"chemistry","chapter":"acids_bases","topic":"Bases and alkalis"}', 5),
  (1668, 416, 'State three natural indicators.', 'text', 1, 'Focus on the core principle of Indicators.', '{"why":"Natural indicators come from plants","sol":"Step 1: Think of plant-based substances\nStep 2: Identify substances that change colour in acids/bases\nStep 3: List any three examples","steps":["Step 1: Think of plant-based substances","Step 2: Identify substances that change colour in acids/bases","Step 3: List any three examples"],"options":[],"conceptId":"chemistry_acids_bases_indicators","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q1","subject":"chemistry","chapter":"acids_bases","topic":"Indicators"}', 0),
  (1669, 416, 'What is the colour of litmus in neutral solution?', 'text', 1, 'Focus on the core principle of Indicators.', '{"why":"Neutral solution does not shift litmus to red or blue","sol":"Step 1: Identify neutral pH (~7)\nStep 2: Recall litmus behaviour\nStep 3: State observed colour","steps":["Step 1: Identify neutral pH (~7)","Step 2: Recall litmus behaviour","Step 3: State observed colour"],"options":[],"conceptId":"chemistry_acids_bases_indicators","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q2","subject":"chemistry","chapter":"acids_bases","topic":"Indicators"}', 1),
  (1670, 416, 'Why is litmus not a complete indicator?', 'text', 1, 'Focus on the core principle of Indicators.', '{"why":"It does not measure exact acidity or alkalinity","sol":"Step 1: Check what information litmus gives\nStep 2: Compare with full pH range\nStep 3: Identify limitation","steps":["Step 1: Check what information litmus gives","Step 2: Compare with full pH range","Step 3: Identify limitation"],"options":[],"conceptId":"chemistry_acids_bases_indicators","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q3","subject":"chemistry","chapter":"acids_bases","topic":"Indicators"}', 2),
  (1671, 416, 'What is a universal indicator?', 'text', 1, 'Focus on the core principle of Indicators.', '{"why":"It measures strength of acid or base","sol":"Step 1: Identify type of indicator mixture\nStep 2: Check pH range coverage\nStep 3: Define function","steps":["Step 1: Identify type of indicator mixture","Step 2: Check pH range coverage","Step 3: Define function"],"options":[],"conceptId":"chemistry_acids_bases_indicators","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q4","subject":"chemistry","chapter":"acids_bases","topic":"Indicators"}', 3),
  (1672, 416, 'What colour does universal indicator show in strong acid and strong base?', 'text', 1, 'Focus on the core principle of Indicators.', '{"why":"Extreme pH values give extreme colours","sol":"Step 1: Recall pH scale extremes\nStep 2: Match colour changes\nStep 3: State both results","steps":["Step 1: Recall pH scale extremes","Step 2: Match colour changes","Step 3: State both results"],"options":[],"conceptId":"chemistry_acids_bases_indicators","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q5","subject":"chemistry","chapter":"acids_bases","topic":"Indicators"}', 4),
  (1673, 417, 'What does a pH of 1 indicate?', 'text', 1, 'Focus on the core principle of pH scale.', '{"why":"Extremely high H⁺ ion concentration","sol":"Step 1: Check pH value\nStep 2: Locate on pH scale\nStep 3: Determine acidity level","steps":["Step 1: Check pH value","Step 2: Locate on pH scale","Step 3: Determine acidity level"],"options":[],"conceptId":"chemistry_acids_bases_ph_scale","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q1","subject":"chemistry","chapter":"acids_bases","topic":"pH scale"}', 0),
  (1674, 417, 'What is the pH range of a weak base?', 'text', 1, 'Focus on the core principle of pH scale.', '{"why":"Low OH⁻ concentration compared to strong bases","sol":"Step 1: Identify basic range (>7)\nStep 2: Focus on mild alkalinity\nStep 3: Give range","steps":["Step 1: Identify basic range (>7)","Step 2: Focus on mild alkalinity","Step 3: Give range"],"options":[],"conceptId":"chemistry_acids_bases_ph_scale","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q2","subject":"chemistry","chapter":"acids_bases","topic":"pH scale"}', 1),
